// Hyperreal Steamed Mirror — Hand-Wiped Arc, Eye, Cheek & Condensation Drip
// p5.js 2.x + p5.brush

const ARC_CX = 580;
const ARC_CY = 1090;

// Smooth helper for top and bottom radii of the hand-wiped arc at angle theta (in degrees)
function getWipeBounds(theta) {
  // Wipe spans roughly from theta = -117 deg (left) to -62 deg (right)
  const norm = map(theta, -117, -62, -1, 1);
  const env = max(0, 1 - pow(abs(norm), 2.35));

  // Subtle organic undulation along the swipe path
  const waveTop = 6 * sin((theta + 90) * 7) + 4 * cos((theta + 90) * 13);
  const waveBot = 7 * sin((theta + 90) * 5.5 + 40) + 5 * cos((theta + 90) * 11);

  const midR = 594 + 8 * sin((theta + 95) * 3.2);
  const halfThick = 98 * pow(env, 0.58);

  return {
    rBot: midR - halfThick + waveBot * env, // lower edge on canvas (larger y)
    rTop: midR + halfThick + waveTop * env, // upper edge on canvas (smaller y)
    midR: midR,
    env: env,
    norm: norm
  };
}

// Convert polar (theta in deg, r) around (ARC_CX, ARC_CY) to canvas (x, y)
function arcPt(theta, r) {
  return [
    ARC_CX + r * cos(theta),
    ARC_CY + r * sin(theta)
  ];
}

// Evaluate whether (x, y) is inside the clear wipe (< 0) or in the steam (> 0)
function wipeSignedDist(x, y) {
  const dx = x - ARC_CX;
  const dy = y - ARC_CY;
  const r = sqrt(dx * dx + dy * dy);
  const theta = atan2(dy, dx); // DEGREES mode active
  if (theta < -122 || theta > -57) return 200;

  const b = getWipeBounds(theta);
  if (b.env <= 0.001) return 150;

  // Finger track ridges (4 subtle channels along the hand wipe, stronger at right lift-off)
  const fingerFreq = (r - b.midR) * 4.2;
  const fingerStreak = sin(fingerFreq) * (theta > -78 ? map(theta, -78, -62, 2, 28, true) : 3);

  const distToMid = abs(r - b.midR);
  const halfSpan = (b.rTop - b.rBot) * 0.5;
  return distToMid - halfSpan + fingerStreak;
}

// Eye lid geometry (x from 468 to 682)
function upperLidY(x) {
  const t = constrain((x - 468) / (682 - 468), 0, 1);
  // Asymmetric natural human upper lid arch (peak slightly medial-center)
  const arch = sin(pow(t, 0.88) * 180);
  const baseLine = lerp(485, 466, t);
  return baseLine - 43 * pow(arch, 1.12);
}

function lowerLidY(x) {
  const t = constrain((x - 468) / (682 - 468), 0, 1);
  // Subtle S-curve of lower lid (dipping slightly lateral to center)
  const arch = sin(pow(t, 1.08) * 180);
  const baseLine = lerp(485, 466, t);
  return baseLine + 24 * pow(arch, 1.15);
}

function drawOrganicBlob(cx, cy, rx, ry, rotDeg, noiseAmp = 0.18, steps = 28) {
  brush.beginShape(0.45);
  const c = cos(rotDeg);
  const s = sin(rotDeg);
  for (let i = 0; i < steps; i++) {
    const ang = (i / steps) * 360;
    const n = noise(cx * 0.01 + cos(ang) * 1.3, cy * 0.01 + sin(ang) * 1.3);
    const radScale = 1 + (n - 0.5) * 2 * noiseAmp;
    const lx = rx * radScale * cos(ang);
    const ly = ry * radScale * sin(ang);
    const px = cx + lx * c - ly * s;
    const py = cy + lx * s + ly * c;
    brush.vertex(px, py);
  }
  brush.endShape(true);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7319);
  noiseSeed(4821);

  // Ultra-soft vapor brush for seamless perceptual fog gradients
  brush.add("vapor_haze", {
    type: "spray",
    weight: 28,
    scatter: 5.5,
    opacity: 9,
    spacing: 0.35,
    pressure: [0.4, 1.2, 0.4],
    rotate: "random"
  });

  // Medium mist brush for wipe edges and skin softness
  brush.add("fine_mist", {
    type: "spray",
    weight: 9,
    scatter: 2.2,
    opacity: 16,
    spacing: 0.25,
    pressure: [0.5, 1.1, 0.5],
    rotate: "random"
  });

  // Micro skin & iris texture brush
  brush.add("micro_detail", {
    type: "default",
    weight: 0.28,
    scatter: 0.06,
    sharpness: 0.85,
    grain: 0.45,
    opacity: 165,
    spacing: 0.08,
    pressure: [0.3, 1.15, 0.15],
    noise: 0.25
  });

  // Tapered wet eyelash & glass highlight brush
  brush.add("wet_lash", {
    type: "default",
    weight: 0.55,
    scatter: 0.02,
    sharpness: 0.94,
    grain: 0.2,
    opacity: 230,
    spacing: 0.05,
    pressure: [1.35, 0.85, 0.08],
    noise: 0.12
  });

  // Soft velvet blender for skin subsurface gradients
  brush.add("velvet_skin", {
    type: "default",
    weight: 3.5,
    scatter: 0.65,
    sharpness: 0.12,
    grain: 0.35,
    opacity: 26,
    spacing: 0.18,
    pressure: [0.3, 1.0, 0.3],
    noise: 0.2
  });

  // Gentle perceptual steam drift field
  brush.addField("steam_drift", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        const nx = col * 0.06;
        const ny = row * 0.06;
        field[col][row] = -15 + (noise(nx, ny, t) - 0.5) * 65;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // =========================================================================
  // 1. LUMINOUS PERCEPTUAL STEAM FIELD (WATERCOLOR + SPRAY HAZE)
  // =========================================================================
  background("#f7f1f8");

  brush.noStroke();
  // Border intensity near zero so watercolor clouds have zero hard edges
  brush.fillTexture(0.14, 0.01);
  brush.fillBleed(0.6, "out");

  // Batch 1: Vivid lavender & electric violet-lilac atmospheric blooms (left & upper-mid)
  const lavenderClouds = [
    { x: 240, y: 310, rx: 360, ry: 290, rot: -18, col: "#b98eff", op: 42 },
    { x: 180, y: 680, rx: 380, ry: 340, rot: 12, col: "#a472ff", op: 46 },
    { x: 420, y: 210, rx: 350, ry: 240, rot: -8, col: "#cfb0ff", op: 40 },
    { x: 350, y: 890, rx: 410, ry: 290, rot: 22, col: "#b384ff", op: 44 },
    { x: 680, y: 180, rx: 340, ry: 220, rot: 10, col: "#d9c2ff", op: 36 },
    { x: 130, y: 980, rx: 310, ry: 270, rot: -15, col: "#945eff", op: 38 }
  ];
  for (const c of lavenderClouds) {
    brush.fill(c.col, c.op);
    drawOrganicBlob(c.x, c.y, c.rx, c.ry, c.rot, 0.22, 26);
  }

  // Batch 2: Saturated luminous peach, coral-apricot & rose-gold blooms (right, center & lower)
  const peachClouds = [
    { x: 890, y: 520, rx: 390, ry: 330, rot: 15, col: "#ff9270", op: 48 },
    { x: 760, y: 780, rx: 420, ry: 320, rot: -14, col: "#ffa582", op: 50 },
    { x: 980, y: 860, rx: 360, ry: 310, rot: 25, col: "#ff7e66", op: 45 },
    { x: 610, y: 690, rx: 350, ry: 260, rot: -6, col: "#ff8c7a", op: 46 },
    { x: 960, y: 260, rx: 330, ry: 260, rot: -20, col: "#ffb999", op: 42 },
    { x: 540, y: 980, rx: 430, ry: 250, rot: 8, col: "#ff9b85", op: 40 }
  ];
  for (const c of peachClouds) {
    brush.fill(c.col, c.op);
    drawOrganicBlob(c.x, c.y, c.rx, c.ry, c.rot, 0.22, 26);
  }

  // Batch 3: Diffused warm rose-magenta presence behind the fog (around the face zone)
  const rosePresence = [
    { x: 570, y: 520, rx: 340, ry: 230, rot: -4, col: "#ff6b8b", op: 42 },
    { x: 480, y: 610, rx: 290, ry: 210, rot: 12, col: "#ff7d99", op: 38 },
    { x: 690, y: 470, rx: 280, ry: 190, rot: -10, col: "#ff8da3", op: 36 },
    { x: 580, y: 790, rx: 260, ry: 280, rot: 4, col: "#e87ea1", op: 35 }
  ];
  for (const c of rosePresence) {
    brush.fill(c.col, c.op);
    drawOrganicBlob(c.x, c.y, c.rx, c.ry, c.rot, 0.2, 24);
  }

  // Batch 4: Radiant pearl-white & opalescent cyan-cream light veils (top-left & upper-right glow)
  const pearlClouds = [
    { x: 260, y: 150, rx: 380, ry: 240, rot: -12, col: "#ffffff", op: 65 },
    { x: 840, y: 140, rx: 360, ry: 220, rot: 14, col: "#e8fbf8", op: 55 },
    { x: 140, y: 460, rx: 280, ry: 310, rot: 6, col: "#fdfaff", op: 58 },
    { x: 1050, y: 620, rx: 290, ry: 340, rot: -9, col: "#fff6f0", op: 52 },
    { x: 380, y: 1060, rx: 390, ry: 210, rot: 5, col: "#faf2ff", op: 50 }
  ];
  for (const c of pearlClouds) {
    brush.fill(c.col, c.op);
    drawOrganicBlob(c.x, c.y, c.rx, c.ry, c.rot, 0.2, 24);
  }
  brush.noFill();

  // Seamless spray haze pass across the whole mirror to fuse watercolor into velvety vapor
  brush.field("steam_drift");
  const hazePalette = [
    "#ffffff", "#fcf8ff", "#ebd9ff", "#d4b2ff",
    "#ffe3d6", "#ffc2ab", "#ffd1dc", "#ebfbfa"
  ];
  for (let i = 0; i < 420; i++) {
    const hx = random(-60, width + 60);
    const hy = random(-60, height + 60);
    // Bias colors spatially: cooler lavender left/top, warmer peach right/bottom, pearl top
    let colIdx = floor(random(hazePalette.length));
    if (hx < 520 && random() < 0.65) colIdx = random([0, 1, 2, 3]);
    else if (hx >= 520 && random() < 0.65) colIdx = random([0, 4, 5, 6]);
    if (hy < 320 && random() < 0.5) colIdx = random([0, 1, 7]);

    brush.set("vapor_haze", hazePalette[colIdx], random(1.2, 2.8));
    brush.flowLine(hx, hy, random(140, 320), random(-25, 25));
  }
  brush.noField();

  // =========================================================================
  // 2. THE HAND-WIPED ARC — CLEAR MIRROR BASE & SKIN UNDERPAINTING
  // =========================================================================
  // Trace the outer contour of the wiped arc for the base skin wash
  brush.noStroke();
  brush.wash("#8f3f49", 215); // Deep warm subsurface rose-umber base
  brush.beginShape(0.35);
  for (let th = -116; th <= -63; th += 2) {
    const b = getWipeBounds(th);
    const [px, py] = arcPt(th, b.rTop - 4);
    brush.vertex(px, py);
  }
  for (let th = -63; th >= -116; th -= 2) {
    const b = getWipeBounds(th);
    const [px, py] = arcPt(th, b.rBot + 4);
    brush.vertex(px, py);
  }
  brush.endShape(true);
  brush.noWash();

  // Layered luminous watercolor + wash planes inside the wiped arc for 3D facial anatomy
  brush.fillTexture(0.15, 0.02);
  brush.fillBleed(0.28, "out");

  // Recessed medial eye socket & side of nasal bridge (left of eye: x 355..485)
  const socketShadows = [
    { x: 425, y: 475, rx: 78, ry: 56, rot: -15, col: "#4a1926", op: 145 },
    { x: 390, y: 515, rx: 68, ry: 48, rot: -24, col: "#662432", op: 130 },
    { x: 465, y: 445, rx: 62, ry: 36, rot: -12, col: "#571e2b", op: 135 },
    // Nasal bridge highlight strip on far left of wipe
    { x: 365, y: 535, rx: 42, ry: 34, rot: -28, col: "#d9786c", op: 120 }
  ];
  for (const s of socketShadows) {
    brush.fill(s.col, s.op);
    drawOrganicBlob(s.x, s.y, s.rx, s.ry, s.rot, 0.12, 22);
  }

  // Rich, vivid cheek and temple flesh tones (coral-terracotta, peach-gold, rose-carmine)
  const cheekPlanes = [
    { x: 585, y: 548, rx: 165, ry: 52, rot: -3, col: "#d95b52", op: 150 },
    { x: 645, y: 538, rx: 135, ry: 48, rot: 6, col: "#e8725d", op: 145 },
    { x: 520, y: 552, rx: 110, ry: 44, rot: -8, col: "#e06458", op: 140 },
    { x: 735, y: 515, rx: 95, ry: 55, rot: 14, col: "#b84648", op: 135 },
    // High cheekbone luminous peach-apricot glow
    { x: 605, y: 536, rx: 120, ry: 32, rot: -2, col: "#ff9b7d", op: 155 },
    { x: 555, y: 534, rx: 85, ry: 26, rot: -5, col: "#ffb89e", op: 150 },
    { x: 665, y: 532, rx: 75, ry: 25, rot: 5, col: "#ffa88a", op: 140 },
    // Brow bone & mobile upper eyelid warmth
    { x: 585, y: 418, rx: 115, ry: 24, rot: -4, col: "#c45850", op: 135 },
    { x: 572, y: 438, rx: 78, ry: 18, rot: -5, col: "#f09580", op: 155 },
    // Lower eyelid orbicularis roll (warm rose-peach)
    { x: 578, y: 508, rx: 92, ry: 14, rot: -5, col: "#f28d7c", op: 155 }
  ];
  for (const p of cheekPlanes) {
    brush.fill(p.col, p.op);
    drawOrganicBlob(p.x, p.y, p.rx, p.ry, p.rot, 0.1, 22);
  }
  brush.noFill();

  // Sculptural velvet skin strokes following facial contours inside the wiped arc
  const skinStrokes = [
    // Cheekbone contour sweep
    { x1: 440, y1: 545, x2: 575, y2: 535, x3: 745, y3: 548, col: "#ffcab5", n: 45, spread: 24 },
    // Lower cheek blush & coral warmth
    { x1: 420, y1: 568, x2: 580, y2: 566, x3: 760, y3: 576, col: "#d94e4e", n: 42, spread: 22 },
    // Tear trough subtle violet-crimson shadow
    { x1: 472, y1: 502, x2: 555, y2: 520, x3: 665, y3: 504, col: "#852d3c", n: 28, spread: 9 },
    // Upper eyelid crease shadow
    { x1: 470, y1: 465, x2: 568, y2: 420, x3: 685, y3: 452, col: "#3d121d", n: 34, spread: 8 },
    // Temple & outer canthus shadow
    { x1: 678, y1: 462, x2: 735, y2: 475, x3: 795, y3: 515, col: "#702836", n: 32, spread: 22 }
  ];

  for (const s of skinStrokes) {
    for (let i = 0; i < s.n; i++) {
      const offY = random(-s.spread, s.spread);
      const offX = random(-12, 12);
      const p1 = [s.x1 + offX, s.y1 + offY, random(0.3, 0.7)];
      const p2 = [s.x2 + offX, s.y2 + offY, random(0.8, 1.2)];
      const p3 = [s.x3 + offX, s.y3 + offY, random(0.3, 0.7)];
      if (wipeSignedDist(p2[0], p2[1]) < 8) {
        brush.set("velvet_skin", s.col, random(0.6, 1.35));
        brush.spline([p1, p2, p3], 0.5);
      }
    }
  }

  // Hyperreal damp skin pore texture & steam-dewy cheekbone sheen
  for (let i = 0; i < 650; i++) {
    const sx = random(355, 810);
    const sy = random(405, 595);
    // Skip eye opening
    if (sx > 466 && sx < 684 && sy > upperLidY(sx) - 4 && sy < lowerLidY(sx) + 5) continue;
    if (wipeSignedDist(sx, sy) > -4) continue;

    // Determine local skin lighting
    const distCheekHighlight = hypot((sx - 585) * 0.55, sy - 534);
    const distBrowHighlight = hypot((sx - 580) * 0.6, sy - 432);
    let col = "#b84a48";
    if (distCheekHighlight < 46) {
      col = random(["#ffe6d9", "#ffd1bd", "#ffbfa8", "#fff5ef"]);
    } else if (distBrowHighlight < 30) {
      col = random(["#ffd4c2", "#f5a591", "#ffeae0"]);
    } else if (sx < 465) {
      col = random(["#591f2c", "#782d3b", "#963f4a", "#b8585c"]);
    } else {
      col = random(["#c7524a", "#de6a5b", "#f08570", "#9e3842", "#ffa48c"]);
    }

    brush.set("micro_detail", col, random(0.5, 1.1));
    const ang = -8 + (sx - 580) * 0.06 + random(-20, 20);
    const len = random(2.5, 6.5);
    brush.line(sx, sy, sx + len * cos(ang), sy + len * sin(ang));
  }

  // Tiny dewy skin moisture micro-highlights along the cheekbone ridge & temple
  for (let i = 0; i < 140; i++) {
    const hx = random(465, 725);
    const hy = 532 + (hx - 580) * 0.04 + randomGaussian(0, 14);
    if (wipeSignedDist(hx, hy) < -8) {
      brush.set("micro_detail", random() < 0.4 ? "#ffffff" : "#ffefe8", random(0.4, 0.9));
      brush.line(hx, hy, hx + random(1.2, 2.8), hy + random(-0.6, 0.6));
    }
  }

  // =========================================================================
  // 3. EYEBROW (UPPER EDGE OF THE WIPE, PARTIALLY VEILED BY STEAM)
  // =========================================================================
  for (let i = 0; i < 145; i++) {
    const t = random(0, 1);
    const bx = lerp(448, 712, t);
    const archY = 415 - 19 * sin(pow(t, 0.85) * 175) + (t > 0.65 ? (t - 0.65) * 28 : 0);
    const by = archY + random(-9, 9);

    // Brow hairs slant upward medially, then sweep laterally and slightly downward
    const baseAngle = lerp(-58, 18, pow(t, 0.78)) + random(-8, 8);
    const hairLen = random(18, 32) * (1 - 0.3 * abs(t - 0.45));
    const mx = bx + hairLen * 0.5 * cos(baseAngle);
    const my = by + hairLen * 0.5 * sin(baseAngle);
    const ex = bx + hairLen * cos(baseAngle + 8);
    const ey = by + hairLen * sin(baseAngle + 8);

    const hairCol = random(["#1c0e13", "#2b161c", "#3d2128", "#543038", "#784c52"]);
    brush.set("wet_lash", hairCol, random(0.45, 0.95));
    brush.spline([[bx, by, 0.9], [mx, my, 1.1], [ex, ey, 0.15]], 0.45);
  }

  // =========================================================================
  // 4. HYPERREAL EYE — SCLERA, TEAR DUCT, IRIS, PUPIL, CATCHLIGHT & LASHES
  // =========================================================================
  // 4A. Sclera base & spherical shading
  brush.noStroke();
  brush.wash("#f4e8e6", 245);
  brush.beginShape(0.25);
  for (let x = 472; x <= 680; x += 6) brush.vertex(x, upperLidY(x));
  for (let x = 680; x >= 472; x -= 6) brush.vertex(x, lowerLidY(x));
  brush.endShape(true);

  // Spherical shadow at medial and lateral corners of sclera
  brush.wash("#cfb2be", 155);
  brush.beginShape(0.25);
  for (let x = 472; x <= 532; x += 6) brush.vertex(x, upperLidY(x));
  for (let x = 532; x >= 472; x -= 6) brush.vertex(x, lowerLidY(x));
  brush.endShape(true);

  brush.wash("#c7a5b4", 165);
  brush.beginShape(0.25);
  for (let x = 612; x <= 680; x += 6) brush.vertex(x, upperLidY(x));
  for (let x = 680; x >= 612; x -= 6) brush.vertex(x, lowerLidY(x));
  brush.endShape(true);

  // Cool blue-lavender cast shadow from upper eyelid across top of sclera
  brush.wash("#8e94b2", 145);
  brush.beginShape(0.2);
  for (let x = 476; x <= 676; x += 6) brush.vertex(x, upperLidY(x));
  for (let x = 676; x >= 476; x -= 6) brush.vertex(x, upperLidY(x) + 11);
  brush.endShape(true);
  brush.noWash();

  // Delicate scleral micro-capillaries & wet pink plica semilunaris
  const capillaries = [
    [[496, 482, 0.8], [508, 476, 0.5], [520, 478, 0.2]],
    [[498, 488, 0.7], [512, 489, 0.5], [524, 485, 0.15]],
    [[666, 468, 0.9], [648, 470, 0.6], [630, 466, 0.2]],
    [[662, 474, 0.8], [644, 479, 0.5], [625, 482, 0.15]],
    [[654, 463, 0.7], [638, 461, 0.4], [622, 464, 0.1]]
  ];
  for (const cap of capillaries) {
    brush.set("micro_detail", "#d65c6e", 0.45);
    brush.spline(cap, 0.5);
  }

  // 4B. Inner Canthus — Lacrimal Caruncle & Plica Semilunaris (x: 468..500)
  brush.noStroke();
  brush.wash("#c94958", 230);
  brush.beginShape(0.3);
  brush.vertex(467, 485);
  brush.vertex(480, 475);
  brush.vertex(497, 474);
  brush.vertex(499, 489);
  brush.vertex(482, 492);
  brush.endShape(true);

  brush.wash("#f07882", 210);
  brush.circle(481, 484, 7, 0.15);
  brush.wash("#9e2838", 190);
  brush.circle(492, 482, 5, 0.15);
  brush.noWash();

  // 4C. THE IRIS (Clipped precisely between upperLidY and lowerLidY)
  const IRIS_CX = 572;
  const IRIS_CY = 465;
  const IRIS_R = 44.5;

  // Helper to clamp any point inside the eye opening
  function clampToEye(x, y) {
    const uy = upperLidY(x) + 0.8;
    const ly = lowerLidY(x) - 0.8;
    return [x, constrain(y, uy, ly)];
  }

  // Outer dark limbal ring base
  brush.noStroke();
  brush.wash("#121d26", 248);
  brush.beginShape(0.15);
  for (let a = 0; a < 360; a += 5) {
    const px = IRIS_CX + IRIS_R * cos(a);
    const py = IRIS_CY + IRIS_R * sin(a);
    const [cx, cy] = clampToEye(px, py);
    brush.vertex(cx, cy);
  }
  brush.endShape(true);

  // Mid iris base (rich peacock-emerald & deep teal)
  brush.wash("#1f6166", 235);
  brush.beginShape(0.15);
  for (let a = 0; a < 360; a += 5) {
    const px = IRIS_CX + (IRIS_R - 4.5) * cos(a);
    const py = IRIS_CY + (IRIS_R - 4.5) * sin(a);
    const [cx, cy] = clampToEye(px, py);
    brush.vertex(cx, cy);
  }
  brush.endShape(true);

  // Inner collarette zone (vivid amber, burnt gold & honey-ochre)
  brush.wash("#b85f24", 220);
  brush.beginShape(0.2);
  for (let a = 0; a < 360; a += 6) {
    const r = 25 + 3 * sin(a * 7);
    const px = IRIS_CX + r * cos(a);
    const py = IRIS_CY + r * sin(a);
    const [cx, cy] = clampToEye(px, py);
    brush.vertex(cx, cy);
  }
  brush.endShape(true);
  brush.noWash();

  // 520 Radial Iris Stroma Fibers, Crypts & Collarette Filaments
  for (let i = 0; i < 520; i++) {
    const ang = random(0, 360);
    const zone = random();
    let r1, r2, col, w;

    if (zone < 0.42) {
      // Ciliary outer zone: emerald, turquoise, jade, deep slate
      r1 = random(21, 28);
      r2 = random(37, IRIS_R - 1);
      col = random(["#2b8a87", "#3eb5a9", "#17424a", "#52d1bd", "#1d5754", "#7be3cf"]);
      w = random(0.45, 0.95);
    } else if (zone < 0.78) {
      // Collarette & golden-amber ring: fiery honey, copper, ochre, chartreuse
      r1 = random(14.5, 22);
      r2 = random(24, 34);
      col = random(["#f09c35", "#ffbe4f", "#d46a20", "#ffe07d", "#9c3e16", "#c98b2e"]);
      w = random(0.4, 0.85);
    } else {
      // Dark crypts of Fuchs & limbal spokes
      r1 = random(16, 32);
      r2 = min(IRIS_R, r1 + random(6, 13));
      col = random(["#0c161c", "#182830", "#29181c", "#0f2429"]);
      w = random(0.6, 1.15);
    }

    const rm = (r1 + r2) * 0.5;
    const wiggle = random(-4, 4);
    const [x1, y1] = clampToEye(IRIS_CX + r1 * cos(ang), IRIS_CY + r1 * sin(ang));
    const [xm, ym] = clampToEye(IRIS_CX + rm * cos(ang + wiggle), IRIS_CY + rm * sin(ang + wiggle));
    const [x2, y2] = clampToEye(IRIS_CX + r2 * cos(ang), IRIS_CY + r2 * sin(ang));

    // Only draw if not completely squashed against the eyelid margin
    if (hypot(x2 - x1, y2 - y1) > 2.5) {
      brush.set("micro_detail", col, w);
      brush.spline([[x1, y1, 0.5], [xm, ym, 1.1], [x2, y2, 0.4]], 0.35);
    }
  }

  // Lower-right corneal bounce glow inside the iris (vivid golden-turquoise caustic)
  for (let a = 15; a <= 115; a += 2.5) {
    const r = random(22, 37);
    const [px, py] = clampToEye(IRIS_CX + r * cos(a), IRIS_CY + r * sin(a));
    const [qx, qy] = clampToEye(IRIS_CX + (r + 5) * cos(a + 3), IRIS_CY + (r + 5) * sin(a + 3));
    brush.set("micro_detail", random(["#ffe699", "#8cf5e2", "#ffffff"]), 0.65);
    brush.line(px, py, qx, qy);
  }

  // 4D. THE PUPIL (Velvet Obsidian with Warm Copper Sphincter Fringe)
  const PUPIL_R = 14.8;
  brush.noStroke();
  brush.wash("#05050a", 255);
  brush.circle(IRIS_CX, IRIS_CY - 1, PUPIL_R, 0.04);
  brush.noWash();

  for (let a = 0; a < 360; a += 6) {
    const rIn = PUPIL_R - 1.2;
    const rOut = PUPIL_R + random(1.8, 4.2);
    const x1 = IRIS_CX + rIn * cos(a);
    const y1 = IRIS_CY - 1 + rIn * sin(a);
    const x2 = IRIS_CX + rOut * cos(a);
    const y2 = IRIS_CY - 1 + rOut * sin(a);
    brush.set("micro_detail", random(["#d96b27", "#f5a642", "#592212"]), 0.55);
    brush.line(x1, y1, x2, y2);
  }

  // Upper eyelid cast shadow over top of iris & pupil for deep 3D recession
  brush.noStroke();
  brush.wash("#0d1221", 150);
  brush.beginShape(0.15);
  for (let x = 526; x <= 618; x += 4) brush.vertex(x, upperLidY(x));
  for (let x = 618; x >= 526; x -= 4) brush.vertex(x, upperLidY(x) + 15);
  brush.endShape(true);
  brush.noWash();

  // 4E. CORNEAL WINDOW SPECULAR CATCHLIGHT (With Reflected Eyelash Silhouettes!)
  // Soft cyan-pearl outer glow of the catchlight
  brush.noStroke();
  brush.wash("#d4f4ff", 160);
  brush.beginShape(0.2);
  brush.vertex(536, 452);
  brush.vertex(558, 442);
  brush.vertex(567, 446);
  brush.vertex(562, 464);
  brush.vertex(541, 468);
  brush.endShape(true);

  // Crisp pure white core of the window reflection
  brush.wash("#ffffff", 248);
  brush.beginShape(0.15);
  brush.vertex(539, 453);
  brush.vertex(557, 444);
  brush.vertex(565, 448);
  brush.vertex(560, 462);
  brush.vertex(543, 465);
  brush.endShape(true);

  // Secondary pinpoint specular highlight on opposite side of pupil
  brush.circle(588, 474, 2.6, 0.05);
  brush.noWash();

  // Fine dark silhouettes of upper eyelashes cutting across the bright corneal catchlight
  for (let i = 0; i < 5; i++) {
    const lx = 542 + i * 4.8;
    brush.set("micro_detail", "#1c2838", 0.48);
    brush.spline([
      [lx, 443, 0.8],
      [lx - 2, 454, 0.6],
      [lx - 5, 465, 0.2]
    ], 0.4);
  }

  // 4F. WET LOWER WATERLINE & TEAR MENISCUS
  // Fleshy coral-pink lower lid shelf
  for (let x = 474; x <= 676; x += 3) {
    const ly = lowerLidY(x);
    const col = (x > 520 && x < 630) ? "#ffadb0" : "#e37b84";
    brush.set("velvet_skin", col, 0.75);
    brush.line(x, ly + 1.5, x + 4, lowerLidY(x + 4) + 1.5);
  }

  // Razor-sharp glistening white tear meniscus pooling along lower cornea & inner corner
  for (let x = 476; x <= 668; x += 4) {
    if (random() < 0.82) {
      const ly = lowerLidY(x);
      brush.set("wet_lash", "#ffffff", random(0.45, 0.95));
      brush.line(x, ly - 0.3, x + random(2.5, 5.5), lowerLidY(x + 4) - 0.3);
    }
  }
  // Tear duct liquid pinpoint highlights
  brush.set("wet_lash", "#ffffff", 1.15);
  brush.line(477, 482, 482, 480);
  brush.line(488, 487, 493, 488);

  // 4G. UPPER EYELID CREASE & LASH ROOT LINE
  for (let x = 470; x <= 682; x += 3) {
    const uy = upperLidY(x);
    brush.set("wet_lash", "#160a10", 0.95);
    brush.line(x, uy, x + 3.5, upperLidY(x + 3.5));
  }

  // 4H. UPPER & LOWER EYELASHES (Slightly clumped by bathroom humidity + micro-droplets)
  const numUpperLashes = 52;
  for (let i = 0; i < numUpperLashes; i++) {
    const t = i / (numUpperLashes - 1);
    const lx = lerp(488, 678, t);
    const ly = upperLidY(lx);

    // Group adjacent lashes slightly at their tips into damp bundles
    const clumpCenterT = round(t * 14) / 14;
    const clumpPull = (clumpCenterT - t) * 42;

    const baseAng = lerp(-132, -28, pow(t, 0.92));
    const len = (24 + 22 * sin(pow(t, 0.85) * 170)) * random(0.88, 1.12);

    // Lashes dip slightly as they exit the lid, then curl strongly upward
    const p1 = [lx, ly + 1, 1.35];
    const p2 = [
      lx + len * 0.42 * cos(baseAng + 12),
      ly + len * 0.42 * sin(baseAng + 12) + 3,
      0.95
    ];
    const p3 = [
      lx + len * cos(baseAng) + clumpPull,
      ly + len * sin(baseAng),
      0.08
    ];

    // Faint shadow cast by lash on upper lid
    brush.set("micro_detail", "#4a1e29", 0.55);
    brush.spline([[p1[0], p1[1] - 2, 0.6], [p2[0], p2[1] - 3, 0.4], [p3[0], p3[1] - 2, 0.1]], 0.45);

    // Main wet black-espresso lash
    brush.set("wet_lash", random(["#0b0609", "#170c11", "#241319"]), random(0.75, 1.15));
    brush.spline([p1, p2, p3], 0.5);

    // Tiny specular moisture glint on select lashes
    if (i % 7 === 3) {
      brush.set("micro_detail", "#ffffff", 0.75);
      brush.line(p2[0], p2[1], p2[0] + 1.5, p2[1] - 1.5);
    }
  }

  // Lower eyelashes (delicate, shorter, damp V-clusters)
  const numLowerLashes = 34;
  for (let i = 0; i < numLowerLashes; i++) {
    const t = i / (numLowerLashes - 1);
    const lx = lerp(496, 672, t);
    const ly = lowerLidY(lx) + 3.2;

    const clumpCenterT = round(t * 11) / 11;
    const clumpPull = (clumpCenterT - t) * 28;
    const baseAng = lerp(122, 42, t);
    const len = (11 + 9 * sin(t * 180)) * random(0.85, 1.15);

    const p1 = [lx, ly, 0.95];
    const p2 = [
      lx + len * 0.5 * cos(baseAng - 8),
      ly + len * 0.5 * sin(baseAng - 8),
      0.65
    ];
    const p3 = [
      lx + len * cos(baseAng) + clumpPull,
      ly + len * sin(baseAng),
      0.08
    ];

    // Soft cast shadow on lower lid / upper cheek
    brush.set("micro_detail", "#8f3d48", 0.45);
    brush.line(lx, ly + 2, p3[0] + 2, p3[1] + 3);

    brush.set("wet_lash", random(["#1a0d12", "#2e1820", "#3d222a"]), random(0.45, 0.72));
    brush.spline([p1, p2, p3], 0.45);
  }

  // =========================================================================
  // 5. WIPE BOUNDARY SMEARS, FINGER TRACKS & GLASS SHEAR STREAKS
  // =========================================================================
  // Soften and feather the perimeter of the hand-wiped arc into the perceptual field
  for (let pass = 0; pass < 3; pass++) {
    for (let th = -119; th <= -59; th += 1.2) {
      const b = getWipeBounds(th);
      if (b.env <= 0.01) continue;

      // Top boundary mist feathering
      const rTopJitter = b.rTop + random(-18, 26);
      const [tx, ty] = arcPt(th, rTopJitter);
      const topCol = tx < 560 ? random(["#f7f0ff", "#dec4ff", "#ffffff"]) : random(["#fff2eb", "#ffd4c2", "#ffffff"]);
      brush.set("fine_mist", topCol, random(0.8, 1.8));
      const tang = th + 90;
      brush.line(tx, ty, tx + 24 * cos(tang), ty + 24 * sin(tang));

      // Bottom boundary mist feathering
      const rBotJitter = b.rBot + random(-24, 16);
      const [bx, by] = arcPt(th, rBotJitter);
      const botCol = bx < 540 ? random(["#f2e6ff", "#ffd6e0", "#ffffff"]) : random(["#ffcab5", "#ffe5d9", "#fff7f2"]);
      brush.set("fine_mist", botCol, random(0.8, 1.8));
      brush.line(bx, by, bx + 24 * cos(tang), by + 24 * sin(tang));
    }
  }

  // Finger-pad lift-off streaks on the right side of the arc (theta -80 to -60)
  // and palm press-in streaks on the left side (theta -117 to -102)
  const fingerOffsets = [-0.62, -0.22, 0.2, 0.62];
  for (const fOff of fingerOffsets) {
    // Right lift-off trails
    for (let j = 0; j < 9; j++) {
      const pts = [];
      for (let th = -82; th <= -60; th += 3) {
        const b = getWipeBounds(th);
        const r = b.midR + fOff * (b.rTop - b.rBot) * 0.46 + random(-5, 5);
        const [px, py] = arcPt(th, r);
        pts.push([px, py, map(th, -82, -60, 0.2, 1.2)]);
      }
      brush.set("fine_mist", random(["#fff4ed", "#ffdac7", "#ffffff"]), random(0.7, 1.4));
      brush.spline(pts, 0.45);
    }

    // Left press-in trails
    for (let j = 0; j < 7; j++) {
      const pts = [];
      for (let th = -117; th <= -100; th += 3) {
        const b = getWipeBounds(th);
        const r = b.midR + fOff * (b.rTop - b.rBot) * 0.44 + random(-5, 5);
        const [px, py] = arcPt(th, r);
        pts.push([px, py, map(th, -117, -100, 1.2, 0.2)]);
      }
      brush.set("fine_mist", random(["#f5ebff", "#e2c9ff", "#ffffff"]), random(0.7, 1.3));
      brush.spline(pts, 0.45);
    }
  }

  // Ultra-faint curved shear marks of moisture across the clear glass itself
  for (let i = 0; i < 28; i++) {
    const thStart = random(-108, -78);
    const thEnd = thStart + random(8, 22);
    const r = random(512, 672);
    const pts = [];
    for (let th = thStart; th <= thEnd; th += 3) {
      const [px, py] = arcPt(th, r);
      if (wipeSignedDist(px, py) < -6) {
        pts.push([px, py, 0.6]);
      }
    }
    if (pts.length >= 3) {
      brush.set("micro_detail", "#fff7f5", random(0.25, 0.48));
      brush.spline(pts, 0.4);
    }
  }

  // =========================================================================
  // 6. THE SINGLE SLOW DRIP TRAIL & HANGING DROPLET
  // =========================================================================
  // Starts at the lower ridge of the wipe at theta = -95 deg (x ~ 528, y ~ 596)
  // and runs slowly down the steamed mirror to y = 962
  const dripStartTheta = -95.2;
  const dripBounds = getWipeBounds(dripStartTheta);
  const [dripStartX, dripStartY] = arcPt(dripStartTheta, dripBounds.rBot + 3);
  const dripEndY = 962;

  function getDripX(y) {
    const t = (y - dripStartY) / (dripEndY - dripStartY);
    return dripStartX + 4 * sin(t * 240) + (noise(y * 0.012, 9.1) - 0.5) * 9 * sin(t * 180);
  }

  // 6A. Cleared vertical track in the fog (revealing warm cheek/neck/room reflection behind the steam)
  for (let y = dripStartY; y < dripEndY; y += 3) {
    const dx = getDripX(y);
    const dxNext = getDripX(y + 4);
    const t = (y - dripStartY) / (dripEndY - dripStartY);
    const trackWidth = lerp(6.2, 4.2, t) + sin(y * 0.08) * 0.7;

    // Color inside the cleared drip track transitions from warm cheek coral to deep rose-violet
    let innerCol;
    if (t < 0.35) innerCol = "#d96259";
    else if (t < 0.68) innerCol = "#b85668";
    else innerCol = "#8c4b6e";

    brush.noStroke();
    brush.wash(innerCol, 185);
    brush.circle(dx, y, trackWidth, 0.08);
    brush.noWash();

    // Soft bright inner refraction along right side of the cleared track
    brush.set("micro_detail", t < 0.5 ? "#ffb59e" : "#e5b8ff", 0.65);
    brush.line(dx + 1.5, y, dxNext + 1.5, y + 4);

    // Crisp pearl-white displaced water meniscus rims on left and right of the drip track
    brush.set("micro_detail", "#ffffff", 0.65);
    brush.line(dx - trackWidth, y, dxNext - trackWidth, y + 4);
    brush.set("micro_detail", "#fff2f7", 0.5);
    brush.line(dx + trackWidth, y, dxNext + trackWidth, y + 4);
  }

  // 6B. The Main Hanging Water Droplet at the bottom of the trail (dxEnd, dripEndY)
  const dropX = getDripX(dripEndY);
  const dropY = dripEndY + 6;

  // Soft warm caustic glow cast onto the glass just below the heavy drop
  brush.noStroke();
  brush.wash("#ff9e8a", 95);
  brush.circle(dropX + 1.5, dropY + 12, 11, 0.12);
  brush.wash("#fff5f0", 140);
  brush.circle(dropX + 1, dropY + 9, 6.5, 0.1);

  // Teardrop silhouette — dark refracted upper body
  brush.wash("#4f2438", 230);
  brush.beginShape(0.35);
  brush.vertex(dropX, dropY - 15);
  brush.vertex(dropX + 9.5, dropY - 2);
  brush.vertex(dropX + 8.5, dropY + 9);
  brush.vertex(dropX, dropY + 13.5);
  brush.vertex(dropX - 8.5, dropY + 9);
  brush.vertex(dropX - 9.5, dropY - 2);
  brush.endShape(true);

  // Warm coral-peach & lavender internal refraction in the lower belly of the drop
  brush.wash("#ff8a75", 215);
  brush.circle(dropX + 0.8, dropY + 4.5, 7.2, 0.08);
  brush.wash("#ffe3d8", 235);
  brush.circle(dropX + 1.2, dropY + 6.8, 4.8, 0.06);
  brush.noWash();

  // Crisp dark hydrostatic upper rim
  brush.set("wet_lash", "#2b101d", 0.85);
  brush.arc(dropX, dropY + 2, 9.2, -165, -25);

  // Bright lower-right caustic rim reflection
  brush.set("wet_lash", "#ffffff", 0.9);
  brush.arc(dropX, dropY + 2, 8.8, 15, 135);

  // Two exact, dazzling pure-white specular highlights on the upper-left of the hanging drop
  brush.noStroke();
  brush.wash("#ffffff", 255);
  brush.circle(dropX - 3.6, dropY - 1.5, 2.8, 0.02);
  brush.circle(dropX - 1.8, dropY - 5.8, 1.5, 0.02);
  brush.noWash();

  // =========================================================================
  // 7. CONDENSATION BEADS (WITH EXACT REFRACTION & PINPOINT HIGHLIGHTS)
  // =========================================================================
  function drawCondensationBead(bx, by, rad, tintWarm = true) {
    // 1. Subtle lower caustic glow
    brush.noStroke();
    brush.wash(tintWarm ? "#ffcab8" : "#e8d4ff", 125);
    brush.circle(bx + rad * 0.18, by + rad * 0.45, rad * 0.95, 0.08);

    // 2. Dark refracted upper crescent
    brush.wash(tintWarm ? "#6e3240" : "#56426e", 205);
    brush.circle(bx, by, rad, 0.06);

    // 3. Luminous lower belly refraction
    brush.wash(tintWarm ? "#fff0e8" : "#f6f0ff", 235);
    brush.circle(bx + rad * 0.12, by + rad * 0.25, rad * 0.68, 0.06);

    // 4. Tiny, exact pure-white specular highlight on upper-left
    brush.wash("#ffffff", 255);
    brush.circle(bx - rad * 0.32, by - rad * 0.32, max(0.9, rad * 0.34), 0.02);
    brush.noWash();

    // 5. Crisp bottom-right rim glint for larger beads
    if (rad > 3.2) {
      brush.set("micro_detail", "#ffffff", 0.55);
      brush.arc(bx, by, rad * 0.92, 20, 115);
    }
  }

  // 7A. Residual satellite beads inside the vertical drip trail
  const trailBeadYs = [624, 668, 722, 785, 838, 896, 928];
  for (const ty of trailBeadYs) {
    const tx = getDripX(ty) + random(-1.2, 1.2);
    drawCondensationBead(tx, ty, random(1.8, 3.6), true);
  }

  // 7B. Heavy coalesced condensation beads along the lower ridge of the wiped arc
  // (where the hand pushed the water downward)
  for (let th = -114; th <= -64; th += random(1.6, 3.2)) {
    const b = getWipeBounds(th);
    const r = b.rBot + random(-4, 7);
    const [bx, by] = arcPt(th, r);
    const rad = random(2.0, 5.8) * pow(b.env, 0.4);
    if (rad > 1.3) {
      drawCondensationBead(bx, by, rad, bx > 490);
    }
  }

  // 7C. Smaller beads clinging along the upper ridge of the wiped arc
  for (let th = -112; th <= -66; th += random(2.4, 4.5)) {
    const b = getWipeBounds(th);
    const r = b.rTop + random(-5, 6);
    const [bx, by] = arcPt(th, r);
    const rad = random(1.4, 3.8) * pow(b.env, 0.4);
    if (rad > 1.2) {
      drawCondensationBead(bx, by, rad, bx > 540);
    }
  }

  // 7D. Microscopic condensation droplets clinging to 4 upper eyelashes!
  const lashBeads = [
    { x: 528, y: 422, r: 2.1 },
    { x: 562, y: 413, r: 2.4 },
    { x: 604, y: 416, r: 1.9 },
    { x: 642, y: 428, r: 2.2 }
  ];
  for (const lb of lashBeads) {
    drawCondensationBead(lb.x, lb.y, lb.r, true);
  }

  // 7E. Scattered micro-condensation clusters in the steam field near the wipe & drip
  for (let i = 0; i < 210; i++) {
    // Cluster near the wipe perimeter and along the drip zone
    let bx, by;
    if (i < 145) {
      const th = random(-118, -60);
      const b = getWipeBounds(th);
      const side = random() < 0.62 ? -1 : 1; // More beads below the wipe than above
      const distFromEdge = random(6, 135) * pow(random(), 0.7);
      const r = (side < 0 ? b.rBot - distFromEdge : b.rTop + distFromEdge);
      [bx, by] = arcPt(th, r);
    } else {
      by = random(600, 1040);
      bx = getDripX(min(by, dripEndY)) + randomGaussian(0, 55);
    }

    if (wipeSignedDist(bx, by) > 4) {
      const rad = random(1.1, 3.2);
      drawCondensationBead(bx, by, rad, bx > 520);
    }
  }

  // Final atmospheric veil of ultra-fine pearl-white & rose-lavender steam glints in the outer field
  for (let i = 0; i < 180; i++) {
    const gx = random(40, width - 40);
    const gy = random(40, height - 40);
    if (wipeSignedDist(gx, gy) > 28 && abs(gx - getDripX(constrain(gy, dripStartY, dripEndY))) > 16) {
      brush.set("micro_detail", "#ffffff", random(0.4, 0.85));
      brush.line(gx, gy, gx + random(0.8, 1.8), gy + random(-0.5, 0.5));
    }
  }

  noLoop();
}

