async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4209);
  noiseSeed(4209);

  // Custom brushes tailored for smooth spray gradients and crisp marker detailing
  brush.add("smooth_marker", {
    type: "marker",
    weight: 8,
    scatter: 0.04,
    opacity: 32,
    spacing: 0.22,
    pressure: [0.9, 1.0, 0.9],
    markerTip: false,
    noise: 0.2
  });

  brush.add("fine_marker", {
    type: "marker",
    weight: 2.2,
    scatter: 0.02,
    opacity: 85,
    spacing: 0.18,
    pressure: [0.95, 1.0, 0.95],
    markerTip: false,
    noise: 0.15
  });

  brush.add("soft_spray", {
    type: "spray",
    weight: 13,
    scatter: 3.8,
    opacity: 36,
    spacing: 0.35,
    pressure: [0.6, 1.1, 0.6],
    rotate: "random"
  });

  brush.add("leather_spray", {
    type: "spray",
    weight: 6,
    scatter: 2.0,
    opacity: 55,
    spacing: 0.45,
    pressure: [0.8, 1.0, 0.8],
    rotate: "random"
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  const CX = 600;
  const CY = 584;
  const TILE_SIZE = 768;
  const TILE_R = 160;

  // 1. Flat linen-grey cloth background in dusky twilight tones
  drawLinenBackground();

  // 2. Monumental soft drop shadow beneath the floating icon
  drawIconDropShadow(CX, CY, TILE_SIZE, TILE_R);

  // 3. Rounded-square tile: outer anodized bevel, pebbled black leather, stitched channel
  drawLeatherTileAndBevel(CX, CY, TILE_SIZE, TILE_R);

  // 4. Cast shadow of the protruding lens barrel onto the leather deck
  drawLensBarrelShadow(CX, CY, 294);

  // 5. Concentric machined & knurled aluminium rings + engraved markings
  drawLensBarrelAndRings(CX, CY);

  // 6. Multicoated optical glass, internal aperture blades, magenta-green flare
  drawMulticoatedGlass(CX, CY, 165);

  // 7. Glossy curved highlight sweeping across the top third of the icon and lens
  drawTopThirdGlossHighlight(CX, CY, TILE_SIZE, TILE_R);

  noLoop();
}

// =============================================================================
// GEOMETRY & DRAWING HELPERS
// =============================================================================

function washShape(pts, col, opacity, curvature = 0.05) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, opacity);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function strokeShape(pts, brushName, col, weight, close = true, curvature = 0.05) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, weight);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(close);
  brush.noStroke();
}

function washCircle(x, y, r, col, opacity, irr = 0.0) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, opacity);
  brush.circle(x, y, r, irr);
  brush.noWash();
}

function getRoundedRectPoints(cx, cy, w, h, r, stepsPerCorner = 16) {
  let pts = [];
  let hw = w / 2;
  let hh = h / 2;
  let cr = min(r, hw, hh);
  let corners = [
    { x: cx + hw - cr, y: cy - hh + cr, a0: -90, a1: 0 },
    { x: cx + hw - cr, y: cy + hh - cr, a0: 0,   a1: 90 },
    { x: cx - hw + cr, y: cy + hh - cr, a0: 90,  a1: 180 },
    { x: cx - hw + cr, y: cy - hh + cr, a0: 180, a1: 270 }
  ];
  for (let c of corners) {
    for (let i = 0; i <= stepsPerCorner; i++) {
      let a = lerp(c.a0, c.a1, i / stepsPerCorner);
      pts.push([c.x + cos(a) * cr, c.y + sin(a) * cr]);
    }
  }
  return pts;
}

function insideRoundedRect(x, y, cx, cy, w, h, r) {
  let dx = max(abs(x - cx) - (w / 2 - r), 0);
  let dy = max(abs(y - cy) - (h / 2 - r), 0);
  return (dx * dx + dy * dy) <= (r * r);
}

function sampleRoundedRectPerimeter(cx, cy, w, h, r, numSamples) {
  let dense = getRoundedRectPoints(cx, cy, w, h, r, 48);
  dense.push(dense[0]);
  let cumLen = [0];
  let total = 0;
  for (let i = 1; i < dense.length; i++) {
    let d = dist(dense[i - 1][0], dense[i - 1][1], dense[i][0], dense[i][1]);
    total += d;
    cumLen.push(total);
  }
  let samples = [];
  for (let s = 0; s < numSamples; s++) {
    let target = (s / numSamples) * total;
    let idx = 0;
    while (idx < cumLen.length - 2 && cumLen[idx + 1] < target) idx++;
    let segLen = max(0.0001, cumLen[idx + 1] - cumLen[idx]);
    let t = (target - cumLen[idx]) / segLen;
    let x = lerp(dense[idx][0], dense[idx + 1][0], t);
    let y = lerp(dense[idx][1], dense[idx + 1][1], t);
    let tx = (dense[idx + 1][0] - dense[idx][0]) / segLen;
    let ty = (dense[idx + 1][1] - dense[idx][1]) / segLen;
    let nx = ty;
    let ny = -tx;
    samples.push({ x, y, tx, ty, nx, ny });
  }
  return samples;
}

// =============================================================================
// 1. FLAT LINEN-GREY CLOTH TEXTURE BACKGROUND
// =============================================================================

function drawLinenBackground() {
  background("#494f5c");

  // Subtle dusky twilight atmospheric washes (darker slate at edges, cool dusk center)
  washCircle(600, 500, 680, "#565d6c", 35);
  washCircle(600, 420, 480, "#626a7a", 28);

  // Corner vignette bands
  let topBand = [[0, 0], [1200, 0], [1200, 220], [0, 220]];
  let botBand = [[0, 960], [1200, 960], [1200, 1200], [0, 1200]];
  washShape(topBand, "#373c47", 45, 0);
  washShape(botBand, "#2b2f3a", 65, 0);

  // Fine woven linen cross-hatch passes across the canvas
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.hatchStyle("2H", "#393e4a", 0.32);
  brush.hatch(7, 0, { rand: 0.02 });
  brush.rect(0, 0, 1200, 1200, "corner");
  brush.noHatch();

  brush.hatchStyle("2H", "#5b6272", 0.28);
  brush.hatch(7, 90, { rand: 0.02 });
  brush.rect(0, 0, 1200, 1200, "corner");
  brush.noHatch();

  // Individual slub linen threads (alternating light/dark warp and weft)
  for (let y = 4; y < 1200; y += 9) {
    let isLight = (y % 18 === 4);
    let col = isLight ? "#5e6575" : "#343945";
    let w = isLight ? 0.28 : 0.34;
    brush.set("rotring", col, w);
    let x0 = 0;
    while (x0 < 1200) {
      let seg = random(90, 260);
      let x1 = min(1200, x0 + seg);
      brush.line(x0, y + random(-0.4, 0.4), x1, y + random(-0.4, 0.4));
      x0 = x1 + random(8, 28);
    }
  }

  for (let x = 5; x < 1200; x += 9) {
    let isLight = (x % 18 === 5);
    let col = isLight ? "#585f6e" : "#313642";
    let w = isLight ? 0.25 : 0.3;
    brush.set("rotring", col, w);
    let y0 = 0;
    while (y0 < 1200) {
      let seg = random(90, 260);
      let y1 = min(1200, y0 + seg);
      brush.line(x + random(-0.4, 0.4), y0, x + random(-0.4, 0.4), y1);
      y0 = y1 + random(8, 28);
    }
  }

  // Soft spray grain over the cloth to unify weave
  for (let i = 0; i < 45; i++) {
    let y = map(i, 0, 44, 20, 1180);
    let col = y < 600 ? "#5a6172" : "#2f3440";
    brush.set("soft_spray", col, 0.8);
    brush.line(30, y, 1170, y);
  }
  brush.noStroke();
}

// =============================================================================
// 2. SOFT DROP SHADOW BENEATH THE ICON
// =============================================================================

function drawIconDropShadow(cx, cy, size, r) {
  // Multi-stepped soft shadow washes expanding downward
  for (let i = 18; i >= 1; i--) {
    let t = i / 18;
    let expand = lerp(4, 76, t);
    let shiftY = lerp(8, 52, pow(t, 0.85));
    let pts = getRoundedRectPoints(cx, cy + shiftY, size + expand, size + expand * 0.9, r + expand * 0.45, 14);
    let alpha = lerp(28, 7, t);
    washShape(pts, "#10131b", alpha, 0.08);
  }

  // Spray shadow halo around bottom and lower sides for plush skeuomorphic lift
  let haloPts = sampleRoundedRectPerimeter(cx, cy + 28, size + 18, size + 18, r + 8, 90);
  for (let p of haloPts) {
    if (p.y > cy - 120) {
      let weight = map(p.y, cy - 120, cy + size / 2, 0.5, 1.5, true);
      brush.set("soft_spray", "#0b0d13", weight);
      brush.line(p.x - p.tx * 18, p.y - p.ty * 18, p.x + p.tx * 18, p.y + p.ty * 18);
    }
  }

  // Tight ambient occlusion contact shadow directly under the icon base
  let aoPts = getRoundedRectPoints(cx, cy + 7, size + 4, size + 4, r + 2, 16);
  washShape(aoPts, "#07080c", 140, 0.06);
  brush.noStroke();
}

// =============================================================================
// 3. ROUNDED-SQUARE TILE: BEVEL, PEBBLED LEATHER & STITCHING
// =============================================================================

function drawLeatherTileAndBevel(cx, cy, size, r) {
  // Outer dark metallic / bezel rim
  let outerPts = getRoundedRectPoints(cx, cy, size, size, r, 18);
  washShape(outerPts, "#181b22", 255, 0.05);

  // Outer bevel directional shading (bright twilight top edge, deep dark bottom edge)
  let bevelPerim = sampleRoundedRectPerimeter(cx, cy, size - 4, size - 4, r - 2, 160);
  for (let i = 0; i < bevelPerim.length; i++) {
    let p0 = bevelPerim[i];
    let p1 = bevelPerim[(i + 1) % bevelPerim.length];
    // Normal pointing upward gets bright twilight highlight
    let upFactor = constrain(-p0.ny, -1, 1);
    let col;
    if (upFactor > 0.65) col = "#b6c0d4";
    else if (upFactor > 0.25) col = "#6d768a";
    else if (upFactor > -0.3) col = "#353a47";
    else col = "#0c0e13";
    brush.set("fine_marker", col, 1.3);
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }

  // Main leather deck recessed inside the outer rim
  let deckSize = size - 16;
  let deckR = r - 7;
  let deckPts = getRoundedRectPoints(cx, cy, deckSize, deckSize, deckR, 18);
  washShape(deckPts, "#191c23", 255, 0.05);

  // Smooth marker & spray gradient across the leather deck (twilight top-down lighting)
  let halfDeck = deckSize / 2;
  for (let y = cy - halfDeck + 8; y <= cy + halfDeck - 8; y += 10) {
    let dy = abs(y - cy);
    let xSpan = halfDeck - 6;
    if (dy > halfDeck - deckR) {
      let cdy = dy - (halfDeck - deckR);
      xSpan = (halfDeck - deckR) + sqrt(max(0, deckR * deckR - cdy * cdy)) - 6;
    }
    let t = map(y, cy - halfDeck, cy + halfDeck, 0, 1);
    let col = t < 0.35 ? "#2e3340" : (t < 0.68 ? "#1c2028" : "#0e1016");
    brush.set("smooth_marker", col, 0.9);
    brush.line(cx - xSpan, y, cx + xSpan, y);
  }

  // Subtle corner pillow bevel shading around the leather perimeter
  let innerBevelPerim = sampleRoundedRectPerimeter(cx, cy, deckSize - 10, deckSize - 10, deckR - 5, 120);
  for (let i = 0; i < innerBevelPerim.length; i++) {
    let p0 = innerBevelPerim[i];
    let p1 = innerBevelPerim[(i + 1) % innerBevelPerim.length];
    let col = p0.ny < -0.3 ? "#394050" : "#0b0d12";
    brush.set("smooth_marker", col, 0.85);
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }

  // Pebbled black leather cellular texture (in the visible leather annulus outside lens R=286)
  let stitchSize = size - 68;
  let stitchR = r - 30;
  let step = 11.5;
  let row = 0;
  for (let py = cy - halfDeck + 14; py <= cy + halfDeck - 14; py += step * 0.86) {
    row++;
    let xOffset = (row % 2) * (step * 0.5);
    for (let px = cx - halfDeck + 14 + xOffset; px <= cx + halfDeck - 14; px += step) {
      let jx = px + random(-2.6, 2.6);
      let jy = py + random(-2.6, 2.6);

      // Must be inside leather deck and outside the central lens mount
      let dCenter = dist(jx, jy, cx, cy);
      if (dCenter < 286) continue;
      if (!insideRoundedRect(jx, jy, cx, cy, deckSize - 18, deckSize - 18, deckR - 8)) continue;

      // Skip directly inside the narrow stitch groove so the groove remains razor-clean
      let inOuterStitch = insideRoundedRect(jx, jy, cx, cy, stitchSize + 12, stitchSize + 12, stitchR + 6);
      let inInnerStitch = insideRoundedRect(jx, jy, cx, cy, stitchSize - 12, stitchSize - 12, stitchR - 6);
      if (inOuterStitch && !inInnerStitch) continue;

      let pRad = random(3.2, 4.8);
      // Dark crevice under the pebble
      brush.set("rotring", "#07080c", 0.52);
      brush.line(jx - pRad * 0.7, jy + pRad * 0.45, jx + pRad * 0.1, jy + pRad * 0.65);
      brush.line(jx + pRad * 0.1, jy + pRad * 0.65, jx + pRad * 0.75, jy + pRad * 0.25);

      // Specular pebble crown (brighter on upper third, subtler below)
      let nVal = noise(jx * 0.015, jy * 0.015);
      let yNorm = map(jy, cy - halfDeck, cy + halfDeck, 0, 1);
      let hiCol;
      if (yNorm < 0.32) {
        hiCol = nVal > 0.48 ? "#525b70" : "#3c4354";
      } else if (yNorm < 0.68) {
        hiCol = nVal > 0.5 ? "#353b4a" : "#262b36";
      } else {
        hiCol = nVal > 0.52 ? "#252a35" : "#1a1e26";
      }
      brush.set("fine_marker", hiCol, 0.42);
      brush.line(jx - pRad * 0.45, jy - pRad * 0.25, jx + pRad * 0.45, jy - pRad * 0.15);
    }
  }

  // Fine leather spray stipple around the corners for organic richness
  for (let i = 0; i < 60; i++) {
    let p = innerBevelPerim[i * 2];
    let col = p.y < cy ? "#3a4152" : "#0b0d12";
    brush.set("leather_spray", col, 0.65);
    brush.line(p.x - p.nx * 22, p.y - p.ny * 22, p.x - p.nx * 55, p.y - p.ny * 55);
  }

  // Recessed stitching channel / groove around the bevel
  let grooveOuter = getRoundedRectPoints(cx, cy, stitchSize + 5, stitchSize + 5, stitchR + 2, 20);
  let grooveCenter = getRoundedRectPoints(cx, cy, stitchSize, stitchSize, stitchR, 20);
  let grooveInner = getRoundedRectPoints(cx, cy, stitchSize - 5, stitchSize - 5, stitchR - 2, 20);

  strokeShape(grooveOuter, "fine_marker", "#090b10", 0.9, true, 0.05);
  strokeShape(grooveCenter, "rotring", "#050609", 0.85, true, 0.05);
  strokeShape(grooveInner, "rotring", "#343b4a", 0.45, true, 0.05);

  // Visible saddle stitching around the bevel (88 individual 3D waxed threads)
  let numStitches = 88;
  let stitchSamples = sampleRoundedRectPerimeter(cx, cy, stitchSize, stitchSize, stitchR, numStitches);
  for (let i = 0; i < numStitches; i++) {
    let s0 = stitchSamples[i];
    let s1 = stitchSamples[(i + 1) % numStitches];

    // Thread endpoints inset slightly with a subtle saddle-stitch slant
    let len = dist(s0.x, s0.y, s1.x, s1.y);
    let ax = s0.x + s0.tx * (len * 0.18) + s0.nx * 1.1;
    let ay = s0.y + s0.ty * (len * 0.18) + s0.ny * 1.1;
    let bx = s0.x + s0.tx * (len * 0.82) - s0.nx * 1.1;
    let by = s0.y + s0.ty * (len * 0.82) - s0.ny * 1.1;

    // Needle pinholes at ends of each stitch
    brush.set("rotring", "#040507", 0.95);
    brush.line(ax - s0.tx * 1.2, ay - s0.ty * 1.2, ax + s0.tx * 0.8, ay + s0.ty * 0.8);
    brush.line(bx - s0.tx * 0.8, by - s0.ty * 0.8, bx + s0.tx * 1.2, by + s0.ty * 1.2);

    // Cast shadow of the raised thread
    brush.set("rotring", "#07080c", 0.85);
    brush.line(ax, ay + 1.8, bx, by + 1.8);

    // Waxed thread body (shaded by vertical position on tile)
    let isTop = s0.y < cy;
    let threadBase = isTop ? "#b5a48b" : "#877863";
    let threadHighlight = isTop ? "#ebe0ce" : "#b8a890";

    brush.set("fine_marker", threadBase, 0.72);
    brush.line(ax, ay, bx, by);

    brush.set("rotring", threadHighlight, 0.45);
    let mx = (ax + bx) * 0.5;
    let my = (ay + by) * 0.5;
    brush.line(lerp(ax, mx, 0.35), lerp(ay, my, 0.35) - 0.4, lerp(bx, mx, 0.35), lerp(by, my, 0.35) - 0.4);
  }

  // Crisp outer rim catchlight along the top-left bevel
  let topRimPts = [];
  for (let i = 0; i <= 40; i++) {
    let a = lerp(195, 345, i / 40);
    // Project onto top edge of rounded rect
  }
  let topCornerLeft = [];
  for (let a = 195; a <= 270; a += 5) {
    topCornerLeft.push([cx - size / 2 + r + cos(a) * (r - 2), cy - size / 2 + r + sin(a) * (r - 2)]);
  }
  let topCornerRight = [];
  for (let a = 270; a <= 345; a += 5) {
    topCornerRight.push([cx + size / 2 - r + cos(a) * (r - 2), cy - size / 2 + r + sin(a) * (r - 2)]);
  }
  let fullTopRim = [...topCornerLeft, ...topCornerRight];
  strokeShape(fullTopRim, "rotring", "#dce4f5", 0.55, false, 0.05);
}

// =============================================================================
// 4. LENS BARREL CAST SHADOW ONTO THE LEATHER
// =============================================================================

function drawLensBarrelShadow(cx, cy, lensR) {
  for (let i = 14; i >= 1; i--) {
    let t = i / 14;
    let rad = lensR + lerp(2, 34, t);
    let sy = cy + lerp(4, 30, pow(t, 0.9));
    washCircle(cx, sy, rad, "#06070b", lerp(36, 8, t));
  }

  // Dark spray collar around the lower half of the lens barrel
  for (let a = 10; a <= 170; a += 4) {
    let rad = lensR + 10;
    let x0 = cx + cos(a) * (rad - 6);
    let y0 = cy + sin(a) * (rad - 6) + 8;
    let x1 = cx + cos(a) * (rad + 18);
    let y1 = cy + sin(a) * (rad + 18) + 14;
    brush.set("soft_spray", "#050609", 0.9);
    brush.line(x0, y0, x1, y1);
  }
  brush.noStroke();
}

// =============================================================================
// 5. CONCENTRIC KNURLED ALUMINIUM RINGS & ENGRAVED FOCAL MARKINGS
// =============================================================================

function getAnisotropicMetalColor(angleDeg, mode = "bright") {
  // Cylindrical anisotropic reflection with primary lobe at -110° and secondary at +70°
  let a1 = cos((angleDeg + 110) * 2);
  let a2 = cos((angleDeg + 65));
  let a3 = sin((angleDeg - 20) * 3) * 0.25;
  let spec = constrain(0.5 + 0.38 * a1 + 0.22 * a2 + a3, 0, 1);

  let palette;
  if (mode === "chrome") {
    palette = ["#11141c", "#262c3a", "#4d566b", "#838ea6", "#c4cee2", "#f2f6ff"];
  } else if (mode === "aluminium") {
    palette = ["#151821", "#252b38", "#3f4759", "#697389", "#9da7bd", "#dce4f5"];
  } else {
    // Dark satin anodized ring
    palette = ["#0b0d12", "#12151e", "#1b202c", "#282f3f", "#384154", "#4b556b"];
  }

  let idx = spec * (palette.length - 1);
  let i0 = floor(idx);
  let i1 = min(palette.length - 1, i0 + 1);
  let frac = idx - i0;
  return lerpColor(color(palette[i0]), color(palette[i1]), frac);
}

function drawMetallicRing(cx, cy, rInner, rOuter, radialSteps, angularSteps, mode, brushName, weight) {
  let stepA = 360 / angularSteps;
  for (let rStep = 0; rStep <= radialSteps; rStep++) {
    let r = lerp(rInner, rOuter, rStep / radialSteps);
    for (let s = 0; s < angularSteps; s++) {
      let a0 = s * stepA;
      let a1 = a0 + stepA + 1.8;
      let midA = a0 + stepA * 0.5;
      let col = getAnisotropicMetalColor(midA, mode);
      brush.set(brushName, col, weight);
      brush.arc(cx, cy, r, a0, a1);
    }
  }
  brush.noStroke();
}

function drawLensBarrelAndRings(cx, cy) {
  // Base recessed mount shadow
  washCircle(cx, cy, 295, "#07080c", 255);

  // RING 1: Outer Chamfered Titanium/Aluminium Bezel (R = 291 down to 272)
  washCircle(cx, cy, 291, "#3a4152", 255);
  drawMetallicRing(cx, cy, 272, 290, 9, 48, "aluminium", "fine_marker", 0.95);

  // Fine concentric lathe-turned lines on Outer Bezel
  for (let r = 274; r <= 289; r += 3) {
    brush.set("rotring", "#161922", 0.25);
    brush.arc(cx, cy, r, 0, 360);
  }
  // Specular highlight arcs on outer rim
  brush.set("rotring", "#eef3ff", 0.65);
  brush.arc(cx, cy, 290.5, 205, 295);
  brush.arc(cx, cy, 290.5, 35, 95);
  brush.set("rotring", "#080a0f", 0.75);
  brush.arc(cx, cy, 272, 0, 360);

  // RING 2: Knurled Aluminium Grip Ring (R = 272 down to 244)
  washCircle(cx, cy, 271.5, "#1f2430", 255);
  drawMetallicRing(cx, cy, 245, 270, 7, 48, "aluminium", "fine_marker", 0.85);

  // 200 CNC-machined radial knurl ridges around the grip ring
  let numKnurls = 200;
  for (let i = 0; i < numKnurls; i++) {
    let a = (i / numKnurls) * 360;
    let aRad = a;
    let rIn = 245.5;
    let rOut = 270.5;

    let x0 = cx + cos(aRad) * rIn;
    let y0 = cy + sin(aRad) * rIn;
    let x1 = cx + cos(aRad) * rOut;
    let y1 = cy + sin(aRad) * rOut;

    // Dark machined flute groove
    brush.set("rotring", "#090b10", 0.52);
    brush.line(x0, y0, x1, y1);

    // Illuminated metallic ridge next to the flute
    let aRidge = a + 0.85;
    let rx0 = cx + cos(aRidge) * (rIn + 0.8);
    let ry0 = cy + sin(aRidge) * (rIn + 0.8);
    let rx1 = cx + cos(aRidge) * (rOut - 0.8);
    let ry1 = cy + sin(aRidge) * (rOut - 0.8);

    let ridgeCol = getAnisotropicMetalColor(aRidge, "chrome");
    brush.set("rotring", ridgeCol, 0.58);
    brush.line(rx0, ry0, rx1, ry1);
  }

  // Chamfered top/bottom borders of the knurled ring
  brush.set("rotring", "#07090e", 0.85);
  brush.arc(cx, cy, 271.2, 0, 360);
  brush.arc(cx, cy, 244.5, 0, 360);
  brush.set("rotring", "#dce5f7", 0.45);
  brush.arc(cx, cy, 270.2, 200, 305);
  brush.arc(cx, cy, 245.2, 25, 115);

  // RING 3: Polished Chrome Accent Step Ring (R = 244 down to 234)
  washCircle(cx, cy, 244, "#2d3444", 255);
  drawMetallicRing(cx, cy, 234, 243.5, 5, 48, "chrome", "fine_marker", 0.85);
  brush.set("rotring", "#f5f8ff", 0.6);
  brush.arc(cx, cy, 239, 210, 290);
  brush.arc(cx, cy, 239, 35, 100);
  brush.set("rotring", "#06070b", 0.9);
  brush.arc(cx, cy, 234, 0, 360);

  // RING 4: Anodized Matte-Black Engraved Nameplate & Focal Scale Ring (R = 234 down to 185)
  washCircle(cx, cy, 233.5, "#12151e", 255);
  drawMetallicRing(cx, cy, 186, 233, 12, 48, "dark", "smooth_marker", 0.55);

  // Micro-turned concentric satin lines on the nameplate ring
  for (let r = 188; r <= 231; r += 2.5) {
    let col = (r % 5 === 0) ? "#252b3b" : "#0d0f16";
    brush.set("rotring", col, 0.24);
    brush.arc(cx, cy, r, 0, 360);
  }

  // Engraved markings on the Nameplate Ring
  drawEngravedLensMarkings(cx, cy);

  // RING 5: Stepped Anti-Reflective Filter Thread Baffle Cone (R = 185 down to 165)
  washCircle(cx, cy, 185, "#080a0f", 255);
  let numBaffles = 7;
  for (let b = 0; b < numBaffles; b++) {
    let r = map(b, 0, numBaffles - 1, 184, 166);
    // Deep velvet baffle trough
    brush.set("rotring", "#040508", 0.9);
    brush.arc(cx, cy, r, 0, 360);

    // Concave inner wall catches top-left light on the bottom-right side (+20° to +130°)
    brush.set("rotring", "#7e8aa3", 0.42);
    brush.arc(cx, cy, r - 0.8, 15, 135);
    brush.set("rotring", "#3d4557", 0.35);
    brush.arc(cx, cy, r - 0.8, 135, 225);
    brush.set("rotring", "#252b38", 0.3);
    brush.arc(cx, cy, r - 0.8, 315, 360);
  }
  brush.noStroke();
}

function drawEngravedLensMarkings(cx, cy) {
  // 1. Top Arc Engraving: "CANONICAL LENS  f=50mm  1:1.2"
  drawArcText(cx, cy, 209, -152, 4.3, "CANONICAL LENS  f=50mm  1:1.2", 11.5, "#e2e9f7", 0.48, true);

  // 2. Left & Right Arc Engravings: "Ø58mm" and "MULTI-COATED"
  drawArcText(cx, cy, 209, 166, 4.6, "Ø58mm", 10.5, "#bfc9de", 0.44, true);
  drawArcText(cx, cy, 209, -8, 4.2, "840291", 9.8, "#949fb5", 0.40, true);

  // 3. Bottom Depth-of-Field / Aperture Scale Ticks & Numbers
  // Center red index dot at 90° (bottom) and -90° (top) on the outer ring
  washCircle(cx, cy - 227.5, 3.4, "#e6392e", 250);
  brush.set("rotring", "#ff8a80", 0.4);
  brush.arc(cx, cy - 227.5, 2.2, 190, 340);

  // Bottom radial ticks along R = 222..232
  let dofStops = [
    { a: 46,  label: "16", col: "#c8d2e6", major: true },
    { a: 55,  label: "11", col: "#c8d2e6", major: false },
    { a: 64,  label: "8",  col: "#c8d2e6", major: true },
    { a: 73,  label: "4",  col: "#c8d2e6", major: true },
    { a: 81,  label: "2",  col: "#f08c2e", major: false },
    { a: 90,  label: "1.2",col: "#ef4036", major: true },
    { a: 99,  label: "2",  col: "#f08c2e", major: false },
    { a: 107, label: "4",  col: "#c8d2e6", major: true },
    { a: 116, label: "8",  col: "#c8d2e6", major: true },
    { a: 125, label: "11", col: "#c8d2e6", major: false },
    { a: 134, label: "16", col: "#c8d2e6", major: true }
  ];

  // Fine sub-ticks every 2.2 degrees between 42° and 138°
  for (let a = 42; a <= 138; a += 2.2) {
    let x0 = cx + cos(a) * 227;
    let y0 = cy + sin(a) * 227;
    let x1 = cx + cos(a) * 232.5;
    let y1 = cy + sin(a) * 232.5;
    brush.set("rotring", "#6e788f", 0.32);
    brush.line(x0, y0, x1, y1);
  }

  for (let st of dofStops) {
    let rIn = st.major ? 220 : 223.5;
    let rOut = 232.5;
    let x0 = cx + cos(st.a) * rIn;
    let y0 = cy + sin(st.a) * rIn;
    let x1 = cx + cos(st.a) * rOut;
    let y1 = cy + sin(st.a) * rOut;

    // Dark etched shadow
    brush.set("rotring", "#050609", 0.65);
    brush.line(x0 - 0.7, y0 - 0.7, x1 - 0.7, y1 - 0.7);

    // Bright engraved tick
    brush.set("rotring", st.col, st.major ? 0.58 : 0.45);
    brush.line(x0, y0, x1, y1);

    // Engraved f-stop number radially inside the tick
    let span = st.label.length * 3.1;
    drawArcText(cx, cy, 206, st.a + span * 0.42, -3.1, st.label, 9.2, st.col, 0.44, false);
  }
  brush.noStroke();
}

function drawArcText(cx, cy, radius, startAngle, stepAngle, str, charH, col, weight, topOrientation = true) {
  let charW = charH * 0.64;
  for (let i = 0; i < str.length; i++) {
    let ch = str[i];
    let glyph = GLYPHS[ch];
    if (!glyph) continue;

    let a = startAngle + i * stepAngle;
    let originX = cx + cos(a) * radius;
    let originY = cy + sin(a) * radius;

    // Tangent and radial unit vectors for local character coordinate frame
    let rotDeg = topOrientation ? (a + 90) : (a - 90);
    let ux = cos(rotDeg);
    let uy = sin(rotDeg);
    let vx = -sin(rotDeg);
    let vy = cos(rotDeg);

    for (let poly of glyph) {
      for (let j = 0; j < poly.length - 1; j++) {
        let lx0 = (poly[j][0] - 0.5) * charW;
        let ly0 = (poly[j][1] - 0.5) * charH;
        let lx1 = (poly[j + 1][0] - 0.5) * charW;
        let ly1 = (poly[j + 1][1] - 0.5) * charH;

        let px0 = originX + lx0 * ux + ly0 * vx;
        let py0 = originY + lx0 * uy + ly0 * vy;
        let px1 = originX + lx1 * ux + ly1 * vx;
        let py1 = originY + lx1 * uy + ly1 * vy;

        // Etched shadow
        brush.set("rotring", "#05060a", weight * 1.15);
        brush.line(px0 - 0.7, py0 - 0.7, px1 - 0.7, py1 - 0.7);

        // Crisp engraved fill
        brush.set("rotring", col, weight);
        brush.line(px0, py0, px1, py1);
      }
    }
  }
}

// =============================================================================
// 6. MULTICOATED GLASS, APERTURE BLADES & MAGENTA-GREEN FLARE
// =============================================================================

function drawMulticoatedGlass(cx, cy, glassR) {
  // Deep optical cavity base
  washCircle(cx, cy, glassR, "#05060c", 255);
  washCircle(cx, cy, glassR * 0.84, "#04050a", 255);
  washCircle(cx, cy, glassR * 0.64, "#030408", 255);

  // Internal 9-Blade Iris Diaphragm (visible deep inside the lens barrel)
  let numBlades = 9;
  let pupilR = 54;
  let irisOuterR = 112;
  for (let i = 0; i < numBlades; i++) {
    let a0 = (i / numBlades) * 360;
    let a1 = a0 + 52;
    let a2 = a0 + 88;
    let bladePts = [
      [cx + cos(a0) * pupilR, cy + sin(a0) * pupilR],
      [cx + cos(a0 + 38) * (pupilR + 4), cy + sin(a0 + 38) * (pupilR + 4)],
      [cx + cos(a2) * irisOuterR, cy + sin(a2) * irisOuterR],
      [cx + cos(a1) * irisOuterR, cy + sin(a1) * irisOuterR]
    ];
    washShape(bladePts, "#0c0f19", 220, 0.04);
    // Subtle metallic blade edge
    brush.set("rotring", "#242c40", 0.38);
    brush.line(bladePts[0][0], bladePts[0][1], bladePts[2][0], bladePts[2][1]);
  }

  // Deep central pupil abyss
  washCircle(cx, cy, pupilR, "#020206", 255);

  // Subtle concentric internal glass element rings
  let elementRadii = [158, 134, 108, 78, 54];
  for (let er of elementRadii) {
    brush.set("rotring", "#161c2e", 0.35);
    brush.arc(cx, cy, er, 0, 360);
  }

  // ---------------------------------------------------------------------------
  // MULTICOATED FLARE 1: Primary Magenta / Rose-Violet Meniscus (Upper-Left)
  // ---------------------------------------------------------------------------
  let magColors = [
    { r: 122, ox: -28, oy: -30, col: "#32104c", alpha: 28 },
    { r: 108, ox: -34, oy: -36, col: "#561466", alpha: 32 },
    { r: 94,  ox: -40, oy: -42, col: "#86186e", alpha: 36 },
    { r: 80,  ox: -46, oy: -48, col: "#b81e78", alpha: 42 },
    { r: 66,  ox: -52, oy: -54, col: "#e0328c", alpha: 48 },
    { r: 50,  ox: -58, oy: -60, col: "#ff58ae", alpha: 52 },
    { r: 34,  ox: -64, oy: -66, col: "#ff94ce", alpha: 58 },
    { r: 18,  ox: -70, oy: -72, col: "#ffdbf0", alpha: 75 }
  ];

  for (let mc of magColors) {
    let pts = getClippedCirclePoints(cx + mc.ox, cy + mc.oy, mc.r, cx, cy, glassR - 4, 48);
    if (pts.length > 4) {
      washShape(pts, mc.col, mc.alpha, 0.08);
    }
  }

  // Smooth spray & marker sweeps for the magenta-violet coating bloom
  for (let r = 45; r <= 152; r += 5) {
    let t = map(r, 45, 152, 0, 1);
    let col = t < 0.4 ? "#ff68b8" : (t < 0.75 ? "#c82480" : "#681874");
    let span = map(r, 45, 152, 55, 42);
    brush.set("smooth_marker", col, 0.85);
    brush.arc(cx, cy, r, 225 - span, 225 + span);
  }

  for (let i = 0; i < 28; i++) {
    let a = random(185, 265);
    let r = random(35, 148);
    let x = cx + cos(a) * r;
    let y = cy + sin(a) * r;
    let col = r > 90 ? "#e83894" : "#88248c";
    brush.set("soft_spray", col, random(0.6, 1.2));
    brush.line(x - 12, y + 12, x + 12, y - 12);
  }

  // ---------------------------------------------------------------------------
  // MULTICOATED FLARE 2: Secondary Emerald-Green & Cyan Reflection (Lower-Right)
  // ---------------------------------------------------------------------------
  let grnColors = [
    { r: 110, ox: 30, oy: 32, col: "#0a3254", alpha: 30 },
    { r: 96,  ox: 36, oy: 38, col: "#0c586e", alpha: 36 },
    { r: 82,  ox: 42, oy: 44, col: "#0e8868", alpha: 42 },
    { r: 68,  ox: 48, oy: 50, col: "#18b878", alpha: 46 },
    { r: 52,  ox: 54, oy: 56, col: "#34e696", alpha: 52 },
    { r: 36,  ox: 60, oy: 62, col: "#74ffbe", alpha: 58 },
    { r: 20,  ox: 65, oy: 67, col: "#c8ffe8", alpha: 72 }
  ];

  for (let gc of grnColors) {
    let pts = getClippedCirclePoints(cx + gc.ox, cy + gc.oy, gc.r, cx, cy, glassR - 14, 48);
    if (pts.length > 4) {
      washShape(pts, gc.col, gc.alpha, 0.08);
    }
  }

  // Smooth marker & spray sweeps for the emerald-cyan coating bloom
  for (let r = 38; r <= 138; r += 5) {
    let t = map(r, 38, 138, 0, 1);
    let col = t < 0.4 ? "#1cc488" : (t < 0.75 ? "#32f0a2" : "#1488a8");
    let span = map(r, 38, 138, 52, 38);
    brush.set("smooth_marker", col, 0.8);
    brush.arc(cx, cy, r, 45 - span, 45 + span);
  }

  for (let i = 0; i < 26; i++) {
    let a = random(5, 85);
    let r = random(30, 132);
    let x = cx + cos(a) * r;
    let y = cy + sin(a) * r;
    let col = r > 75 ? "#28e498" : "#1290b0";
    brush.set("soft_spray", col, random(0.6, 1.1));
    brush.line(x - 10, y + 10, x + 10, y - 10);
  }

  // ---------------------------------------------------------------------------
  // MULTICOATED FLARE 3: Optical Ghost Orbs & Caustic Interference Rings
  // ---------------------------------------------------------------------------
  // Violet ghost orb near upper-center-left
  washCircle(cx - 22, cy - 24, 34, "#4b2896", 28);
  brush.set("fine_marker", "#8c62f0", 0.55);
  brush.arc(cx - 22, cy - 24, 34, 180, 310);

  // Cyan-lime ghost orb near lower-center-right
  washCircle(cx + 20, cy + 22, 26, "#1ca878", 30);
  brush.set("fine_marker", "#72ffbe", 0.55);
  brush.arc(cx + 20, cy + 22, 26, 0, 130);

  // Small hot magenta internal double-reflection near (+82, +86)
  washCircle(cx + 80, cy + 82, 16, "#d82888", 45);
  washCircle(cx + 80, cy + 82, 7, "#ffb8e2", 80);

  // Small hot cyan-white pinpoint reflection near (-86, -88)
  washCircle(cx - 84, cy - 86, 14, "#ff68be", 55);
  washCircle(cx - 84, cy - 86, 5.5, "#ffffff", 160);

  // Crisp optical caustic rings along internal lens elements
  brush.set("rotring", "#ff6ec4", 0.5);
  brush.arc(cx, cy, 156, 190, 265);
  brush.arc(cx, cy, 108, 198, 255);

  brush.set("rotring", "#4effb8", 0.5);
  brush.arc(cx, cy, 134, 12, 82);
  brush.arc(cx, cy, 78, 18, 76);

  brush.set("rotring", "#7088ff", 0.42);
  brush.arc(cx, cy, 146, 285, 348);
  brush.arc(cx, cy, 94, 105, 162);

  // Deep peripheral shadow ring around the outer edge of the front glass element
  for (let r = glassR - 8; r <= glassR; r += 1.5) {
    brush.set("fine_marker", "#030408", 0.9);
    brush.arc(cx, cy, r, 0, 360);
  }
  brush.set("rotring", "#020306", 0.9);
  brush.arc(cx, cy, glassR, 0, 360);
  brush.noStroke();
}

function getClippedCirclePoints(cx, cy, r, clipCx, clipCy, clipR, nPts = 48) {
  let pts = [];
  for (let i = 0; i < nPts; i++) {
    let a = (i / nPts) * 360;
    let px = cx + cos(a) * r;
    let py = cy + sin(a) * r;
    let d = dist(px, py, clipCx, clipCy);
    if (d > clipR) {
      let ca = atan2(py - clipCy, px - clipCx);
      px = clipCx + cos(ca) * clipR;
      py = clipCy + sin(ca) * clipR;
    }
    pts.push([px, py]);
  }
  return pts;
}

// =============================================================================
// 7. GLOSSY CURVED HIGHLIGHT SWEEPING ACROSS THE TOP THIRD
// =============================================================================

function drawTopThirdGlossHighlight(cx, cy, tileSize, tileR) {
  let hw = (tileSize - 10) / 2;
  let hh = (tileSize - 10) / 2;
  let cr = tileR - 5;

  // 1. Curved glass dome reflection across the top third of the convex front lens (R = 161)
  let lensGlossPts = [];
  let lensR = 160;
  for (let a = 196; a <= 344; a += 4) {
    lensGlossPts.push([cx + cos(a) * lensR, cy + sin(a) * lensR]);
  }
  for (let a = 344; a >= 196; a -= 4) {
    let x = cx + cos(a) * lensR;
    let normX = (x - cx) / lensR;
    // Graceful downward-arching meniscus curve across top third of the lens
    let yCurve = (cy - 44) - 26 * (1 - normX * normX);
    lensGlossPts.push([x, yCurve]);
  }
  washShape(lensGlossPts, "#e6f0ff", 24, 0.06);

  // Second tighter upper-crescent sheen inside the lens glass
  let lensUpperCrest = [];
  for (let a = 206; a <= 334; a += 4) {
    lensUpperCrest.push([cx + cos(a) * (lensR - 3), cy + sin(a) * (lensR - 3)]);
  }
  for (let a = 334; a >= 206; a -= 4) {
    let x = cx + cos(a) * (lensR - 3);
    let normX = (x - cx) / (lensR - 3);
    let yCurve = (cy - 86) - 24 * (1 - normX * normX);
    lensUpperCrest.push([x, yCurve]);
  }
  washShape(lensUpperCrest, "#ffffff", 32, 0.06);

  // Crisp meniscus lower edge of the lens glass highlight
  let lensMeniscusEdge = [];
  for (let a = 198; a <= 342; a += 4) {
    let x = cx + cos(a) * lensR;
    let normX = (x - cx) / lensR;
    let yCurve = (cy - 44) - 26 * (1 - normX * normX);
    lensMeniscusEdge.push([x, yCurve]);
  }
  strokeShape(lensMeniscusEdge, "rotring", "#d4e6ff", 0.38, false, 0.08);

  // 2. Monumental early-iPhone skeuomorphic gloss sweep across the top third of the tile
  let glossPoly = [];
  // Left rounded corner arc from y ≈ cy - 155 up to top-left corner
  for (let a = 180; a <= 270; a += 5) {
    glossPoly.push([cx - hw + cr + cos(a) * cr, cy - hh + cr + sin(a) * cr]);
  }
  // Top right rounded corner arc
  for (let a = 270; a <= 360; a += 5) {
    glossPoly.push([cx + hw - cr + cos(a) * cr, cy - hh + cr + sin(a) * cr]);
  }
  // Right edge down to the curved sweep boundary (top third of the 768px tile)
  let yEdge = cy - hh + 235;
  let yCenter = cy - hh + 292;
  let steps = 40;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = lerp(cx + hw, cx - hw, t);
    let nx = (x - cx) / hw;
    let y = lerp(yCenter, yEdge, nx * nx);
    glossPoly.push([x, y]);
  }

  // Translucent multi-layered wash for the glossy top-third sweep
  washShape(glossPoly, "#dbe6fa", 16, 0.05);

  // Subtle horizontal marker gradient bands inside the gloss sweep (brighter near the curved edge)
  for (let band = 0; band < 14; band++) {
    let f = band / 13;
    let yMid = lerp(cy - hh + 24, yCenter - 4, f);
    let curveSample = [];
    for (let i = 0; i <= 30; i++) {
      let x = lerp(cx - hw + 8, cx + hw - 8, i / 30);
      let nx = (x - cx) / hw;
      let y = yMid - (1 - nx * nx) * lerp(0, 48, f);
      if (insideRoundedRect(x, y, cx, cy, tileSize - 12, tileSize - 12, tileR - 6)) {
        curveSample.push([x, y]);
      }
    }
    if (curveSample.length > 2) {
      let col = f > 0.75 ? "#e8f0ff" : "#b8c6de";
      let w = f > 0.8 ? 0.55 : 0.35;
      strokeShape(curveSample, "smooth_marker", col, w, false, 0.08);
    }
  }

  // Razor-crisp lower curved highlight edge sweeping across the top third
  let sweepArc = [];
  for (let i = 0; i <= 48; i++) {
    let x = lerp(cx - hw + 2, cx + hw - 2, i / 48);
    let nx = (x - cx) / hw;
    let y = lerp(yCenter, yEdge, nx * nx);
    sweepArc.push([x, y]);
  }
  strokeShape(sweepArc, "fine_marker", "#dce8ff", 0.52, false, 0.08);
  strokeShape(sweepArc, "rotring", "#ffffff", 0.36, false, 0.08);

  // Extra bright specular catchlights where the gloss curve intersects the metallic lens bezels
  for (let r of [290, 271, 244, 234, 165]) {
    for (let side of [-1, 1]) {
      // Approximate intersection of circle radius r with the gloss curve
      let approxY = yCenter - 16;
      let dy = approxY - cy;
      if (abs(dy) < r) {
        let dx = side * sqrt(r * r - dy * dy);
        let ix = cx + dx;
        let iy = cy + dy;
        brush.set("rotring", "#ffffff", 0.75);
        brush.line(ix - 5, iy - 1.5 * side, ix + 5, iy + 1.5 * side);
      }
    }
  }
  brush.noStroke();
}

// Hyperreal Husked Corn Cob in Darning-Stitch Silk & Khaddar-Ochre Weave
// p5.js 2.x + p5.brush (WEBGL 1200x1200)

const SEED = 42719;

// Palette: Soft pastel-infused golden yellow, saffron, deep marigold, pale gold silk, khaddar-ochre
const PALETTE = {
  khaddarBase: "#e5d6bc",
  khaddarLight: ["#f2e7d3", "#eadcc3", "#e2d1b3"],
  khaddarMid: ["#d4be9b", "#c7af88", "#baa077"],
  khaddarShadow: ["#9e8158", "#876b43", "#705533", "#5c4326"],

  creviceDark: ["#4a2912", "#5e3518", "#73421f", "#8a5127"],

  marigoldDeep: ["#ad521d", "#bf6024", "#cf6f2c", "#db7d37"],
  marigoldPastel: ["#e08645", "#e69253", "#eb9e60"],

  saffronRich: ["#e39239", "#ea9f46", "#f0ad54", "#f4b963"],
  saffronPastel: ["#ebb068", "#f2bd79", "#f6c88a"],

  goldenYellow: ["#f5c45a", "#f7ce6b", "#f9d77c", "#fbe08e"],
  goldenPastel: ["#f7d688", "#fae09b", "#fce8ae"],

  silkGlint: ["#fceca8", "#fef4c2", "#fff9db", "#ffffff"],
  silkThread: ["#d4ae66", "#e3c27b", "#f0d690", "#f8e5a7", "#fdf2c4", "#fffbe0"],
  silkShadow: ["#b58b47", "#996f31", "#7d5420"],
  silkTip: ["#a85f27", "#8c4819", "#6e3410"],

  huskLight: ["#efe3c8", "#e4d4b4", "#d8c49e"],
  huskMid: ["#c7b086", "#b89f74", "#c2b899", "#d4b08c"],
  huskDark: ["#997e56", "#7d633e", "#5e4628"]
};

// Cob spine geometry helpers
const P0 = { x: 228, y: 972 }; // Base of cob
const P1 = { x: 938, y: 262 }; // Tip of cob

function getSpinePoint(s) {
  let x = lerp(P0.x, P1.x, s);
  let y = lerp(P0.y, P1.y, s);
  // Subtle natural botanical bow along the cob axis
  let vx = 0.7071, vy = 0.7071;
  let bow = Math.sin(s * Math.PI) * -16 + Math.sin(s * Math.PI * 2) * 4;
  return { x: x + vx * bow, y: y + vy * bow };
}

function getSpineFrame(s) {
  let ds = 0.005;
  let pA = getSpinePoint(Math.max(0, s - ds));
  let pB = getSpinePoint(Math.min(1, s + ds));
  let tx = pB.x - pA.x;
  let ty = pB.y - pA.y;
  let len = Math.hypot(tx, ty) || 1;
  tx /= len;
  ty /= len;
  // Normal pointing toward bottom-right (shadow side)
  let nx = -ty;
  let ny = tx;
  return { c: getSpinePoint(s), t: { x: tx, y: ty }, n: { x: nx, y: ny } };
}

// Realistic heirloom corn cob radius profile R(s)
function getCobRadius(s) {
  if (s < 0) {
    return 92 * Math.max(0.35, 1 + s * 2.2);
  }
  let r = 0;
  if (s < 0.07) {
    let t = s / 0.07;
    r = lerp(94, 154, Math.pow(t, 0.65));
  } else if (s < 0.24) {
    let t = (s - 0.07) / 0.17;
    r = lerp(154, 174, Math.sin(t * Math.PI * 0.5));
  } else if (s < 0.66) {
    let t = (s - 0.24) / 0.42;
    r = lerp(174, 146, Math.pow(t, 1.1));
  } else if (s < 0.90) {
    let t = (s - 0.66) / 0.24;
    r = lerp(146, 72, Math.pow(t, 1.25));
  } else {
    let t = (s - 0.90) / 0.10;
    r = lerp(72, 15, Math.pow(t, 1.15));
  }
  // Subtle organic undulation
  let und = (noise(s * 4.5, 11.3) - 0.5) * 8;
  return r + und;
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  // Custom darning-stitch pen brush: tapers at needle entry/exit, swells over kernel crown
  brush.add("darning_stitch", {
    type: "default",
    weight: 0.44,
    scatter: 0.06,
    sharpness: 0.80,
    grain: 14,
    opacity: 225,
    spacing: 0.11,
    pressure: [0.58, 1.18, 0.58],
    noise: 0.28
  });

  // Fine floss-silk highlight brush
  brush.add("floss_glint", {
    type: "default",
    weight: 0.34,
    scatter: 0.05,
    sharpness: 0.86,
    grain: 10,
    opacity: 235,
    spacing: 0.10,
    pressure: [0.45, 1.15, 0.45],
    noise: 0.22
  });

  // Long single-thread silk tassel brush
  brush.add("silk_thread", {
    type: "default",
    weight: 0.30,
    scatter: 0.04,
    sharpness: 0.88,
    grain: 12,
    opacity: 205,
    spacing: 0.10,
    pressure: [0.85, 1.0, 0.22],
    noise: 0.35
  });

  // Coarse hand-spun khaddar yarn brush
  brush.add("khaddar_yarn", {
    type: "default",
    weight: 0.38,
    scatter: 0.18,
    sharpness: 0.52,
    grain: 28,
    opacity: 145,
    spacing: 0.16,
    pressure: [0.6, 1.1, 0.6],
    noise: 0.65
  });

  // Constraint #2: Call brush.scaleBrushes(3) in setup
  brush.scaleBrushes(3);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.khaddarBase);

  // 1. Coarse unbleached khaddar-ochre ground & low side-light shadow washes
  drawKhaddarGround();

  // 2. Under-silk tassels emerging behind the tip & casting shadows on the weave
  drawBackSilkTassels();

  // 3. Cob dark rachis core bed (so deep interstices between kernels are warm dark umber)
  drawCobCoreBed();

  // 4. Woody stem/shank & peeled-back dry inner husk remnants at the bottom-left base
  drawBaseShankAndHusk();

  // 5. Hyperreal darning-stitched kernels with anisotropic floss-silk shimmer
  drawAllStitchedKernels();

  // 6. Forefront cascading pale-gold silk tassels & stray single threads over the cob
  drawFrontSilkTassels();

  noLoop();
}

// ============================================================================
// 1. KHADDAR-OCHRE HAND-SPUN WOVEN GROUND & CAST SHADOW
// ============================================================================
function drawKhaddarGround() {
  brush.noStroke();
  brush.noHatch();

  // Subtle unbleached cloth tonal washes (batched by color for speed)
  brush.fillTexture(0.68, 0.28);
  brush.fillBleed(0.32, "out");

  // Warm upper-left raking light glow on the cloth
  brush.fill("#efe3cc", 75);
  brush.circle(260, 260, 420, 0.25);
  brush.circle(580, 190, 360, 0.25);

  // Deeper raw ochre cloth tones toward lower-right & corners
  brush.fill("#cfb791", 65);
  brush.circle(960, 960, 480, 0.3);
  brush.circle(1020, 460, 360, 0.3);
  brush.circle(280, 1020, 340, 0.3);

  // Cast shadow of the cob onto the khaddar ground (projected toward bottom-right from low upper-left light)
  let shadowLayers = [
    { col: "#b59669", alpha: 78, shiftN: 58, shiftT: -10, scaleR: 1.12 },
    { col: "#99794d", alpha: 88, shiftN: 42, shiftT: -6, scaleR: 0.96 },
    { col: "#7c5e36", alpha: 95, shiftN: 24, shiftT: -3, scaleR: 0.80 }
  ];

  for (let layer of shadowLayers) {
    brush.fill(layer.col, layer.alpha);
    brush.fillBleed(0.28, "out");
    brush.beginShape(0.35);
    let steps = 24;
    for (let i = 0; i <= steps; i++) {
      let s = i / steps;
      let fr = getSpineFrame(s);
      let r = getCobRadius(s) * layer.scaleR;
      let px = fr.c.x + fr.n.x * (layer.shiftN - r * 0.35) + fr.t.x * layer.shiftT;
      let py = fr.c.y + fr.n.y * (layer.shiftN - r * 0.35) + fr.t.y * layer.shiftT;
      brush.vertex(px, py);
    }
    for (let i = steps; i >= 0; i--) {
      let s = i / steps;
      let fr = getSpineFrame(s);
      let r = getCobRadius(s) * layer.scaleR;
      let px = fr.c.x + fr.n.x * (layer.shiftN + r * 1.18) + fr.t.x * layer.shiftT;
      let py = fr.c.y + fr.n.y * (layer.shiftN + r * 1.18) + fr.t.y * layer.shiftT;
      brush.vertex(px, py);
    }
    brush.endShape(true);
  }
  brush.noFill();

  // Helper to check if a canvas point (x, y) is inside the cob's cast shadow or under the cob
  function getGroundZone(x, y) {
    // Project onto cob axis
    let dx = x - P0.x;
    let dy = y - P0.y;
    let axisLen = Math.hypot(P1.x - P0.x, P1.y - P0.y);
    let s = (dx * 0.7071 - dy * 0.7071) / axisLen;
    if (s >= 0.02 && s <= 0.97) {
      let fr = getSpineFrame(constrain(s, 0, 1));
      let distN = (x - fr.c.x) * fr.n.x + (y - fr.c.y) * fr.n.y;
      let r = getCobRadius(s);
      // Skip drawing cloth weave deep inside the cob interior to save render budget
      if (Math.abs(distN) < r * 0.82) return "inside_cob";
      if (distN > r * 0.75 && distN < r * 1.48 + 42) return "cast_shadow";
    }
    // Check light gradient (upper-left is lit, lower-right is deeper ochre)
    let lightCoord = (x + y) / 2400;
    return lightCoord < 0.46 ? "lit_cloth" : "mid_cloth";
  }

  // Hand-spun khaddar weave: broken, slubbed warp and weft threads
  let spacing = 7.5;
  // Horizontal-ish warp threads
  for (let y = 6; y < height - 6; y += spacing) {
    let x = random(4, 18);
    while (x < width - 10) {
      let segLen = random(55, 145);
      let x2 = Math.min(width - 6, x + segLen);
      let xm = (x + x2) * 0.5;
      let ym = y + (noise(xm * 0.01, y * 0.02) - 0.5) * 3.2;
      let zone = getGroundZone(xm, ym);

      if (zone !== "inside_cob") {
        let col, wt;
        if (zone === "cast_shadow") {
          col = random(PALETTE.khaddarShadow);
          wt = random(0.45, 0.75);
        } else if (zone === "lit_cloth") {
          col = random() < 0.55 ? random(PALETTE.khaddarLight) : random(PALETTE.khaddarMid);
          wt = random(0.35, 0.62);
        } else {
          col = random() < 0.7 ? random(PALETTE.khaddarMid) : random(PALETTE.khaddarLight);
          wt = random(0.38, 0.68);
        }
        brush.set("khaddar_yarn", col, wt);
        let yDrift = (noise(x * 0.015, y * 0.03) - 0.5) * 2.5;
        brush.line(x, y + yDrift, x2, y - yDrift * 0.6);

        // Occasional hand-spun yarn slub (thickened fiber knot)
        if (random() < 0.14) {
          let sx = lerp(x, x2, random(0.2, 0.8));
          let sLen = random(10, 24);
          brush.set("cpencil", col, wt * 1.45);
          brush.line(sx - sLen * 0.5, y, sx + sLen * 0.5, y + 0.4);
        }
      }
      x = x2 + random(4, 14);
    }
  }

  // Vertical-ish weft threads
  for (let x = 6; x < width - 6; x += spacing * 1.05) {
    let y = random(4, 18);
    while (y < height - 10) {
      let segLen = random(55, 145);
      let y2 = Math.min(height - 6, y + segLen);
      let ym = (y + y2) * 0.5;
      let xm = x + (noise(x * 0.02, ym * 0.01) - 0.5) * 3.2;
      let zone = getGroundZone(xm, ym);

      if (zone !== "inside_cob") {
        let col, wt;
        if (zone === "cast_shadow") {
          col = random(PALETTE.khaddarShadow);
          wt = random(0.42, 0.70);
        } else if (zone === "lit_cloth") {
          col = random() < 0.6 ? random(PALETTE.khaddarLight) : random(PALETTE.khaddarMid);
          wt = random(0.32, 0.56);
        } else {
          col = random(PALETTE.khaddarMid);
          wt = random(0.35, 0.62);
        }
        brush.set("khaddar_yarn", col, wt);
        let xDrift = (noise(x * 0.03, y * 0.015) - 0.5) * 2.5;
        brush.line(x + xDrift, y, x - xDrift * 0.6, y2);
      }
      y = y2 + random(5, 16);
    }
  }
}

// ============================================================================
// 2. COB DARK RACHIS CORE BED
// ============================================================================
function drawCobCoreBed() {
  brush.noStroke();
  // Solid warm umber/marigold wash inside the cob footprint so kernel crevices are deep and rich
  brush.wash("#593316", 230);
  brush.beginShape(0.25);
  let steps = 28;
  for (let i = 0; i <= steps; i++) {
    let s = i / steps;
    let fr = getSpineFrame(s);
    let r = getCobRadius(s) * 0.94;
    brush.vertex(fr.c.x - fr.n.x * r, fr.c.y - fr.n.y * r);
  }
  for (let i = steps; i >= 0; i--) {
    let s = i / steps;
    let fr = getSpineFrame(s);
    let r = getCobRadius(s) * 0.94;
    brush.vertex(fr.c.x + fr.n.x * r, fr.c.y + fr.n.y * r);
  }
  brush.endShape(true);
  brush.noWash();
}

// ============================================================================
// 3. BASE SHANK & PEELED DRY HUSK COLLAR AT BOTTOM-LEFT
// ============================================================================
function drawBaseShankAndHusk() {
  let fr0 = getSpineFrame(0.0);

  // Woody fibrous cob shank extending from s = 0.02 down-left toward (115, 1085)
  let shankTracks = 38;
  for (let k = 0; k < shankTracks; k++) {
    let v = map(k, 0, shankTracks - 1, -1, 1);
    let pts = [];
    for (let step = 0; step <= 8; step++) {
      let u = step / 8; // 0 = tip of snapped stem, 1 = junction with cob base
      let s = lerp(-0.15, 0.02, u);
      let fr = getSpineFrame(Math.max(0, s));
      let cx = P0.x + fr0.t.x * (s * 980);
      let cy = P0.y + fr0.t.y * (s * 980);
      let rad = lerp(42, 92, Math.pow(u, 1.35));
      let angle = v * 82;
      let offsetN = rad * sin(angle);
      let bulge = Math.cos(angle) * 10 * (1 - u * 0.5);
      let px = cx + fr0.n.x * offsetN - fr0.t.x * bulge;
      let py = cy + fr0.n.y * offsetN - fr0.t.y * bulge;
      pts.push([px + random(-1, 1), py + random(-1, 1)]);
    }
    // Shade shank from lit upper-left (v < 0) to shadowed lower-right (v > 0)
    let col;
    if (v < -0.25) col = random(PALETTE.huskLight);
    else if (v < 0.25) col = random(PALETTE.huskMid);
    else col = random(PALETTE.huskDark);

    brush.set("darning_stitch", col, random(0.55, 0.85));
    brush.spline(pts, 0.35);
  }

  // Snapped woody stem ring at the very bottom-left end
  let endCenter = {
    x: P0.x - fr0.t.x * 147,
    y: P0.y - fr0.t.y * 147
  };
  for (let i = 0; i < 28; i++) {
    let a = map(i, 0, 28, 0, 360);
    let r1 = random(4, 16);
    let r2 = random(28, 42);
    let x1 = endCenter.x + fr0.n.x * cos(a) * r1 + fr0.t.x * sin(a) * r1 * 0.45;
    let y1 = endCenter.y + fr0.n.y * cos(a) * r1 + fr0.t.y * sin(a) * r1 * 0.45;
    let x2 = endCenter.x + fr0.n.x * cos(a) * r2 + fr0.t.x * sin(a) * r2 * 0.45;
    let y2 = endCenter.y + fr0.n.y * cos(a) * r2 + fr0.t.y * sin(a) * r2 * 0.45;
    brush.set("rotring", i % 2 === 0 ? "#6e5030" : "#b89b72", 0.55);
    brush.line(x1, y1, x2, y2);
  }

  // Two peeled-back papery inner husk bracts curling away from the base of the cob
  // Upper-left peeled husk leaf (catching warm low side-light)
  drawHuskLeaf(
    { x: 222, y: 952 },
    { x: 145, y: 865 },
    { x: 92, y: 745 },
    { x: 195, y: 880 },
    { x: 158, y: 790 },
    44,
    true
  );

  // Lower-right peeled husk leaf (curling onto shadowed khaddar ground)
  drawHuskLeaf(
    { x: 242, y: 982 },
    { x: 335, y: 1055 },
    { x: 465, y: 1098 },
    { x: 315, y: 998 },
    { x: 412, y: 1045 },
    48,
    false
  );
}

function drawHuskLeaf(base, ctrlA1, tip, ctrlB1, ctrlB2, numVeins, isLit) {
  for (let i = 0; i <= numVeins; i++) {
    let t = i / numVeins;
    // Interpolate between outer edge curve and inner edge curve
    let p0 = {
      x: lerp(base.x - 18, base.x + 22, t),
      y: lerp(base.y - 18, base.y + 22, t)
    };
    let p1 = {
      x: lerp(ctrlA1.x, ctrlB1.x, t) + (noise(i * 0.2, 1) - 0.5) * 8,
      y: lerp(ctrlA1.y, ctrlB1.y, t) + (noise(i * 0.2, 2) - 0.5) * 8
    };
    let p2 = {
      x: lerp((ctrlA1.x + tip.x) * 0.5, ctrlB2.x, t) + (noise(i * 0.2, 3) - 0.5) * 10,
      y: lerp((ctrlA1.y + tip.y) * 0.5, ctrlB2.y, t) + (noise(i * 0.2, 4) - 0.5) * 10
    };
    let p3 = {
      x: tip.x + (t - 0.5) * 14,
      y: tip.y + (t - 0.5) * 14
    };

    // Stitch the vein in short overlapping darning segments for textile consistency
    let col;
    if (isLit) {
      if (t < 0.35) col = random(PALETTE.silkGlint);
      else if (t < 0.75) col = random(PALETTE.huskLight);
      else col = random(PALETTE.huskMid);
    } else {
      if (t < 0.3) col = random(PALETTE.huskMid);
      else if (t < 0.75) col = random(PALETTE.huskDark);
      else col = random(PALETTE.creviceDark);
    }

    brush.set("darning_stitch", col, random(0.45, 0.75));
    brush.spline([[p0.x, p0.y], [p1.x, p1.y], [p2.x, p2.y], [p3.x, p3.y]], 0.45);

    // Fine cross-fibers between husk veins
    if (i % 3 === 0 && i < numVeins) {
      brush.set("rotring", isLit ? "#cbb48c" : "#785c38", 0.35);
      brush.line(p1.x, p1.y, p1.x + 8, p1.y - 6);
      brush.line(p2.x, p2.y, p2.x + 7, p2.y - 5);
    }
  }
}

// ============================================================================
// 4. HYPERREAL DARNING-STITCH KERNELS WITH FLOSS-SILK ANISOTROPIC SHIMMER
// ============================================================================
function drawAllStitchedKernels() {
  let kernels = [];

  // Low side-light vector coming from upper-left at a grazing elevation
  // In screen space, upper-left is (-0.68, -0.62) and elevation Lz = 0.39
  const LIGHT = { x: -0.68, y: -0.62, z: 0.39 };
  const lLen = Math.hypot(LIGHT.x, LIGHT.y, LIGHT.z);
  LIGHT.x /= lLen;
  LIGHT.y /= lLen;
  LIGHT.z /= lLen;

  // Half-vector H between light L and viewer V = (0, 0, 1) for specular silk glint
  const HALF = { x: LIGHT.x, y: LIGHT.y, z: LIGHT.z + 1.0 };
  const hLen = Math.hypot(HALF.x, HALF.y, HALF.z);
  HALF.x /= hLen;
  HALF.y /= hLen;
  HALF.z /= hLen;

  // Generate longitudinal ranks s from 0.0 to 1.0
  let s = 0.0;
  let rankIdx = 0;

  while (s < 0.995) {
    let rCob = getCobRadius(s);
    // Longitudinal kernel step ds scales naturally with position on cob
    let ds;
    if (s < 0.08) ds = map(s, 0, 0.08, 0.019, 0.0235);
    else if (s < 0.75) ds = 0.024 + (noise(s * 6, 1.7) - 0.5) * 0.0025;
    else ds = map(s, 0.75, 1.0, 0.023, 0.0135);

    let sNext = Math.min(1.0, s + ds);
    let sMid = (s + sNext) * 0.5;

    // Number of visible rows across the front hemisphere [-96 deg, +96 deg]
    // Real corn rows merge/drop in pairs near the tapering tip
    let numRows;
    if (sMid < 0.72) numRows = 10;
    else if (sMid < 0.87) numRows = 8;
    else if (sMid < 0.95) numRows = 6;
    else numRows = 5;

    let minTheta = -96;
    let maxTheta = 96;
    let dTheta = (maxTheta - minTheta) / numRows;

    for (let j = 0; j < numRows; j++) {
      // Natural row meandering & paired-row stagger
      let rowWave = (noise(sMid * 3.2, j * 1.9 + 10) - 0.5) * 9.5;
      let twist = sMid * 11.0;
      let thetaA = minTheta + j * dTheta + rowWave + twist;
      let thetaB = thetaA + dTheta;
      let thetaMid = (thetaA + thetaB) * 0.5;

      // Keep within visible + silhouette wrap zone
      if (thetaMid < -102 || thetaMid > 102) continue;

      // Slight longitudinal stagger between adjacent rows (characteristic of corn spikelet pairs)
      let rowStagger = ((j % 2) - 0.5) * ds * 0.30 + (noise(rankIdx * 0.35, j * 2.1) - 0.5) * ds * 0.22;
      let kSa = constrain(s + rowStagger, 0.0, 0.992);
      let kSb = constrain(sNext + rowStagger, kSa + 0.009, 1.0);
      let kSc = (kSa + kSb) * 0.5;

      let rLocal = getCobRadius(kSc);
      let zDepth = rLocal * cos(thetaMid) - kSc * 6.0;

      // Choose darning stitch angle for this kernel so adjacent kernels ALWAYS switch direction
      // 4 distinct textile stitch angle families (in degrees relative to kernel local frame)
      let patternIdx = (rankIdx + j) % 2;
      let subVariant = (rankIdx * 3 + j * 5) % 4;
      let stitchAngleLocal;
      if (patternIdx === 0) {
        // Family A: Diagonal up-right or steep longitudinal darning
        stitchAngleLocal = subVariant < 2 ? random(24, 42) : random(-8, 12);
      } else {
        // Family B: Counter-diagonal or transverse darning across the kernel crown
        stitchAngleLocal = subVariant < 2 ? random(-58, -34) : random(68, 88);
      }

      // Per-kernel natural pigment bias (golden yellow, saffron, deep marigold, pastel peach-gold)
      let hueNoise = noise(rankIdx * 0.45 + 30, j * 0.65 + 50);
      let hueRand = random();
      let pigmentType; // "golden", "saffron", "marigold", "pastel_saffron"
      if (kSc > 0.91) {
        pigmentType = "golden"; // Young tip kernels are paler butter-gold
      } else if (hueNoise < 0.34) {
        pigmentType = hueRand < 0.65 ? "marigold" : "saffron";
      } else if (hueNoise < 0.66) {
        pigmentType = hueRand < 0.6 ? "saffron" : "pastel_saffron";
      } else {
        pigmentType = hueRand < 0.7 ? "golden" : "saffron";
      }

      kernels.push({
        rankIdx,
        rowIdx: j,
        sa: kSa,
        sb: kSb,
        sc: kSc,
        thetaA,
        thetaB,
        thetaMid,
        zDepth,
        stitchAngleLocal,
        pigmentType,
        bulgeHeight: map(kSc, 0, 1, 18.5, 9.5) * random(0.92, 1.08),
        seedOffset: random(1000)
      });
    }

    s = sNext;
    rankIdx++;
  }

  // Sort kernels back-to-front (silhouette edge kernels first, central crown kernels last)
  kernels.sort((a, b) => a.zDepth - b.zDepth);

  // Render every kernel with 3D pillow projection and parallel darning stitches
  for (let k of kernels) {
    renderSingleStitchedKernel(k, LIGHT, HALF);
  }
}

// Project a local point (u, v) in [-1, 1] x [-1, 1] on kernel k to 2D canvas + 3D normal
function projectKernelPoint(k, u, v) {
  // Slight crown keystone shape (wider at top crown than root)
  let s = lerp(k.sa, k.sb, (u + 1) * 0.5);
  let theta = lerp(k.thetaA, k.thetaB, (v + 1) * 0.5);

  let fr = getSpineFrame(s);
  let rCob = getCobRadius(s);

  // Rounded cushion/pillow height profile: smooth dome that drops to 0 at boundary
  let r2 = Math.pow(Math.abs(u), 2.3) + Math.pow(Math.abs(v), 2.3);
  let dome = Math.max(0, 1.0 - r2 * 0.88);
  let pillow = Math.pow(dome, 0.58);

  // Characteristic subtle flint/dent crown crease near center of kernel
  let dent = Math.exp(-(u * u * 7.5 + v * v * 3.2)) * 0.14;
  let radialBulge = k.bulgeHeight * Math.max(0, pillow - dent);

  // 2D screen projection:
  // Circumferential offset + radial 3D protrusion (causes realistic scalloped silhouette at |theta| ~ 90)
  let rTotal = rCob + radialBulge;
  let perpDist = rTotal * sin(theta);
  // Slight axial tilt of the protruding kernel dome
  let axialPush = radialBulge * (-0.12 * u + (0.35 - s) * 0.18);

  let x = fr.c.x + fr.n.x * perpDist + fr.t.x * axialPush;
  let y = fr.c.y + fr.n.y * perpDist + fr.t.y * axialPush;

  // Compute 3D surface normal for lighting & silk anisotropy
  // Macro cylinder normal in screen (x, y, z)
  let macroNx = fr.n.x * sin(theta);
  let macroNy = fr.n.y * sin(theta);
  let macroNz = cos(theta);

  // Local pillow slope perturbations along axial (u) and circumferential (v) directions
  let slopeU = -0.62 * u;
  let slopeV = -0.58 * v;

  // Circumferential tangent vector in 3D
  let circumTx = fr.n.x * cos(theta);
  let circumTy = fr.n.y * cos(theta);
  let circumTz = -sin(theta);

  let nx = macroNx + fr.t.x * slopeU + circumTx * slopeV;
  let ny = macroNy + fr.t.y * slopeU + circumTy * slopeV;
  let nz = Math.max(0.05, macroNz + circumTz * slopeV + 0.35 * pillow);
  let nLen = Math.hypot(nx, ny, nz) || 1;

  return {
    x,
    y,
    nx: nx / nLen,
    ny: ny / nLen,
    nz: nz / nLen,
    fr,
    circumT: { x: circumTx, y: circumTy, z: circumTz },
    pillow
  };
}

function renderSingleStitchedKernel(k, LIGHT, HALF) {
  let centerP = projectKernelPoint(k, 0, 0);

  // Compute 3D stitch tangent direction T_stitch for Kajiya-Kay floss-silk anisotropy
  let ang = k.stitchAngleLocal;
  let ca = cos(ang);
  let sa = sin(ang);
  // In local kernel surface, u is along fr.t and v is along circumT
  let stx = centerP.fr.t.x * ca + centerP.circumT.x * sa;
  let sty = centerP.fr.t.y * ca + centerP.circumT.y * sa;
  let stz = centerP.circumT.z * sa;
  let stLen = Math.hypot(stx, sty, stz) || 1;
  stx /= stLen;
  sty /= stLen;
  stz /= stLen;

  // Kajiya-Kay anisotropic silk reflectance:
  // Silk threads glint strongest when the light/half vector is perpendicular to the stitch direction!
  let dotTH = stx * HALF.x + sty * HALF.y + stz * HALF.z;
  let sinTH = Math.sqrt(Math.max(0, 1.0 - dotTH * dotTH));
  let dotTL = stx * LIGHT.x + sty * LIGHT.y + stz * LIGHT.z;
  let sinTL = Math.sqrt(Math.max(0, 1.0 - dotTL * dotTL));

  // How strongly this kernel's stitch angle catches the low side-light (0.0 to 1.0)
  let stitchShimmer = Math.pow(sinTH, 9.0) * 0.65 + Math.pow(sinTL, 6.0) * 0.35;

  // 1. Draw recessed chaff/socket shadow around the lower-right & root boundary of the kernel
  let socketPts = [];
  for (let a = -35; a <= 155; a += 38) {
    let u = 0.96 * cos(a);
    let v = 0.96 * sin(a);
    let pt = projectKernelPoint(k, u, v);
    socketPts.push([pt.x, pt.y]);
  }
  brush.set("rotring", random(PALETTE.creviceDark), random(0.55, 0.85));
  brush.spline(socketPts, 0.4);

  // Determine number of parallel darning stitches across this kernel based on its screen size
  let pLeft = projectKernelPoint(k, 0, -0.95);
  let pRight = projectKernelPoint(k, 0, 0.95);
  let pTop = projectKernelPoint(k, 0.95, 0);
  let pBot = projectKernelPoint(k, -0.95, 0);
  let spanV = Math.hypot(pRight.x - pLeft.x, pRight.y - pLeft.y);
  let spanU = Math.hypot(pTop.x - pBot.x, pTop.y - pBot.y);
  let effectiveSpan = Math.abs(sa) * spanU + Math.abs(ca) * spanV;

  // Dense parallel stitches (~1.8px to 2.2px apart)
  let numStitches = constrain(Math.round(effectiveSpan / 1.95), 9, 22);

  // Direction vectors in (u, v) local kernel coordinates [-1, 1] x [-1, 1]
  let dirU = ca;
  let dirV = sa;
  let perpU = -sa;
  let perpV = ca;

  // Step across the kernel perpendicular to the stitch angle
  for (let i = 0; i < numStitches; i++) {
    let tPerp = map(i, 0, numStitches - 1, -0.90, 0.90);

    // Find intersection chord [tMin, tMax] with rounded superellipse kernel contour:
    // |u|^2.4 + |v|^2.4 <= 0.92
    let tMax = 0;
    for (let testT = 0.98; testT >= 0.08; testT -= 0.05) {
      let u = tPerp * perpU + testT * dirU;
      let v = tPerp * perpV + testT * dirV;
      if (Math.pow(Math.abs(u), 2.4) + Math.pow(Math.abs(v), 2.4) <= 0.94) {
        tMax = testT;
        break;
      }
    }
    if (tMax < 0.14) continue;
    let tMin = -tMax;

    // Slight hand-stitched organic jitter at needle entry/exit
    let jitterA = ((noise(k.seedOffset + i * 0.7, 1) - 0.5) * 0.07);
    let jitterB = ((noise(k.seedOffset + i * 0.7, 2) - 0.5) * 0.07);
    let t0 = tMin + jitterA;
    let t3 = tMax + jitterB;
    let t1 = lerp(t0, t3, 0.34);
    let t2 = lerp(t0, t3, 0.66);

    let pt0 = projectKernelPoint(k, tPerp * perpU + t0 * dirU, tPerp * perpV + t0 * dirV);
    let pt1 = projectKernelPoint(k, tPerp * perpU + t1 * dirU, tPerp * perpV + t1 * dirV);
    let pt2 = projectKernelPoint(k, tPerp * perpU + t2 * dirU, tPerp * perpV + t2 * dirV);
    let pt3 = projectKernelPoint(k, tPerp * perpU + t3 * dirU, tPerp * perpV + t3 * dirV);

    // Evaluate 3D illumination along this specific stitch track
    let midNx = (pt1.nx + pt2.nx) * 0.5;
    let midNy = (pt1.ny + pt2.ny) * 0.5;
    let midNz = (pt1.nz + pt2.nz) * 0.5;

    let diffuse = Math.max(0, midNx * LIGHT.x + midNy * LIGHT.y + midNz * LIGHT.z);
    let nDotH = Math.max(0, midNx * HALF.x + midNy * HALF.y + midNz * HALF.z);

    // Combine diffuse + anisotropic silk shimmer from stitch angle switching
    let silkSheen = diffuse * 0.58 + stitchShimmer * Math.pow(nDotH, 1.65) * 0.62;

    // Also bias illumination across the kernel's local cushion (upper-left crown vs lower-right flank)
    let localPosBias = -(tPerp * perpV) * 0.18 + (tPerp * perpU) * 0.06;
    let totalLum = constrain(silkSheen + localPosBias, 0.0, 1.0);

    // Select stitch color based on totalLum + kernel's pigmentType
    let baseCol = pickKernelStitchColor(k.pigmentType, totalLum);

    // Pass 1: Full darning stitch arching across the kernel from crevice to crevice
    brush.set("darning_stitch", baseCol, random(0.48, 0.68));
    brush.spline([
      [pt0.x, pt0.y],
      [pt1.x, pt1.y],
      [pt2.x, pt2.y],
      [pt3.x, pt3.y]
    ], 0.35);

    // Pass 2: Recessed needle-tuck shadow at whichever end of the stitch faces the shadow side
    let d0 = pt0.nx * LIGHT.x + pt0.ny * LIGHT.y + pt0.nz * LIGHT.z;
    let d3 = pt3.nx * LIGHT.x + pt3.ny * LIGHT.y + pt3.nz * LIGHT.z;
    if (d3 < 0.35) {
      let tuckCol = d3 < 0.15 ? random(PALETTE.creviceDark) : random(PALETTE.marigoldDeep);
      brush.set("rotring", tuckCol, 0.44);
      brush.line(lerp(pt2.x, pt3.x, 0.45), lerp(pt2.y, pt3.y, 0.45), pt3.x, pt3.y);
    }
    if (d0 < 0.28) {
      let tuckCol = d0 < 0.12 ? random(PALETTE.creviceDark) : random(PALETTE.marigoldDeep);
      brush.set("rotring", tuckCol, 0.42);
      brush.line(pt0.x, pt0.y, lerp(pt0.x, pt1.x, 0.5), lerp(pt0.y, pt1.y, 0.5));
    }

    // Pass 3: Anisotropic floss-silk glint stitch over the lit crown ridge of the kernel
    // When this kernel's stitch direction catches the low side-light, it shimmers brightly!
    if (totalLum > 0.52) {
      // Shift glint toward the light-facing half of the stitch chord
      let glintStart = d0 > d3 ? lerp(t0, t1, 0.35) : lerp(t0, t2, 0.45);
      let glintEnd = d0 > d3 ? lerp(t1, t3, 0.55) : lerp(t2, t3, 0.65);
      let gpA = projectKernelPoint(k, tPerp * perpU + glintStart * dirU, tPerp * perpV + glintStart * dirV);
      let gpM = projectKernelPoint(
        k,
        tPerp * perpU + ((glintStart + glintEnd) * 0.5) * dirU,
        tPerp * perpV + ((glintStart + glintEnd) * 0.5) * dirV
      );
      let gpB = projectKernelPoint(k, tPerp * perpU + glintEnd * dirU, tPerp * perpV + glintEnd * dirV);

      let glintCol;
      if (totalLum > 0.78 && stitchShimmer > 0.52) {
        glintCol = random(PALETTE.silkGlint);
      } else if (totalLum > 0.66) {
        glintCol = random(PALETTE.goldenPastel);
      } else {
        glintCol = random(PALETTE.goldenYellow);
      }

      brush.set("floss_glint", glintCol, map(totalLum, 0.52, 1.0, 0.42, 0.68));
      brush.spline([
        [gpA.x, gpA.y],
        [gpM.x, gpM.y],
        [gpB.x, gpB.y]
      ], 0.35);
    }
  }
}

function pickKernelStitchColor(pigmentType, lum) {
  if (lum < 0.18) {
    return random(PALETTE.creviceDark);
  }
  if (pigmentType === "marigold") {
    if (lum < 0.40) return random(PALETTE.marigoldDeep);
    if (lum < 0.62) return random(PALETTE.marigoldPastel);
    if (lum < 0.80) return random(PALETTE.saffronRich);
    return random(PALETTE.goldenYellow);
  } else if (pigmentType === "saffron") {
    if (lum < 0.32) return random(PALETTE.marigoldDeep);
    if (lum < 0.54) return random(PALETTE.saffronRich);
    if (lum < 0.75) return random(PALETTE.saffronPastel);
    return random(PALETTE.goldenYellow);
  } else if (pigmentType === "pastel_saffron") {
    if (lum < 0.30) return random(PALETTE.marigoldPastel);
    if (lum < 0.55) return random(PALETTE.saffronPastel);
    if (lum < 0.78) return random(PALETTE.goldenPastel);
    return random(PALETTE.silkGlint);
  } else {
    // "golden"
    if (lum < 0.28) return random(PALETTE.saffronRich);
    if (lum < 0.52) return random(PALETTE.goldenYellow);
    if (lum < 0.76) return random(PALETTE.goldenPastel);
    return random(PALETTE.silkGlint);
  }
}

// ============================================================================
// 5. SILK TASSELS — PALE GOLD SINGLE THREADS (BACK & FRONT CASCADES)
// ============================================================================
function generateSilkThreadPath(startX, startY, initAngle, totalLen, gravityStrength, curlSeed) {
  let pts = [[startX, startY]];
  let x = startX;
  let y = startY;
  let angle = initAngle;
  let segments = 10;
  let stepLen = totalLen / segments;

  for (let i = 1; i <= segments; i++) {
    let t = i / segments;
    // Smooth organic wave + downward gravity drape toward ~80-95 degrees
    let nVal = (noise(curlSeed + i * 0.28, startX * 0.005) - 0.48) * 28;
    // Target angle pulls gently downward and slightly right
    let targetAngle = lerp(initAngle, 84 + (noise(curlSeed, 9) - 0.5) * 34, Math.pow(t, 0.85) * gravityStrength);
    angle = lerp(angle, targetAngle, 0.32) + nVal;

    x += cos(angle) * stepLen;
    y += sin(angle) * stepLen;
    pts.push([x, y]);
  }
  return pts;
}

function drawBackSilkTassels() {
  let tipFr = getSpineFrame(0.98);

  // 1. Hair-fine cast shadows of the silk tassels on the khaddar cloth
  for (let i = 0; i < 65; i++) {
    let u = random(-0.8, 0.9);
    let sx = tipFr.c.x + tipFr.n.x * (u * 26) + random(-15, 18) + 22;
    let sy = tipFr.c.y + tipFr.n.y * (u * 26) + random(-15, 18) + 28;
    let initAng = random(-48, 35);
    let len = random(240, 680);
    let pts = generateSilkThreadPath(sx, sy, initAng, len, random(0.65, 1.0), i * 13.7 + 100);

    brush.set("rotring", random(PALETTE.khaddarShadow), random(0.28, 0.48));
    brush.spline(pts, 0.45);
  }

  // 2. Deeper antique-gold under-layer of silk threads emerging from behind the cob tip
  for (let i = 0; i < 75; i++) {
    let u = random(-0.9, 0.95);
    let sx = tipFr.c.x + tipFr.n.x * (u * 24) + random(-12, 12);
    let sy = tipFr.c.y + tipFr.n.y * (u * 24) + random(-12, 12);
    let initAng = map(u, -1, 1, -62, 32) + random(-12, 12);
    let len = random(220, 640);
    let pts = generateSilkThreadPath(sx, sy, initAng, len, random(0.60, 0.95), i * 19.3 + 300);

    let col = i % 3 === 0 ? random(PALETTE.silkShadow) : random(PALETTE.silkThread);
    brush.set("silk_thread", col, random(0.42, 0.72));
    brush.spline(pts, 0.45);
  }
}

function drawFrontSilkTassels() {
  let tipFr = getSpineFrame(0.985);

  // 1. Main luxuriant sheaf of long single threads of pale gold trailing from the cob tip
  let mainThreads = 135;
  for (let i = 0; i < mainThreads; i++) {
    let u = map(i, 0, mainThreads - 1, -0.95, 0.95) + random(-0.08, 0.08);
    // Originate from the apical kernel rows (s in 0.88..1.0)
    let sOrig = random(0.89, 1.0);
    let fr = getSpineFrame(sOrig);
    let r = getCobRadius(sOrig) * 0.78;
    let sx = fr.c.x + fr.n.x * (u * r);
    let sy = fr.c.y + fr.n.y * (u * r);

    // Fountain outward along the cob axis (-45 deg) then cascade gracefully down the right side
    let initAng = -45 + u * 44 + random(-14, 14);
    let len = random(260, 790);
    let grav = map(u, -1, 1, 0.52, 0.98) * random(0.85, 1.12);
    let pts = generateSilkThreadPath(sx, sy, initAng, len, grav, i * 23.1 + 700);

    // Upper-left threads catch the low side-light directly (pale champagne & ivory gold)
    let col;
    if (u < -0.25) {
      col = random() < 0.65 ? random(PALETTE.silkGlint) : PALETTE.silkThread[4];
    } else if (u < 0.35) {
      col = random(PALETTE.silkThread);
    } else {
      col = random() < 0.6 ? PALETTE.silkThread[1] : random(PALETTE.silkShadow);
    }

    brush.set("silk_thread", col, random(0.40, 0.68));
    brush.spline(pts, 0.45);

    // Dried russet-gold stigma tips at the trailing ends of the silk threads
    if (pts.length >= 4 && random() < 0.72) {
      let n = pts.length;
      let tipPts = [pts[n - 3], pts[n - 2], pts[n - 1]];
      brush.set("rotring", random(PALETTE.silkTip), random(0.32, 0.50));
      brush.spline(tipPts, 0.4);
    }

    // Specular glint on the upper arch of the silk thread where low side-light rakes across it
    if (u < 0.25 && pts.length >= 5 && random() < 0.55) {
      let glintPts = [pts[1], pts[2], pts[3], pts[4]];
      brush.set("floss_glint", "#fffbe6", random(0.32, 0.52));
      brush.spline(glintPts, 0.4);
    }
  }

  // 2. Stray single silk threads emerging between kernel rows along the cob & trailing across the kernels
  let strayCount = 46;
  for (let i = 0; i < strayCount; i++) {
    let sOrig = random(0.18, 0.90);
    let fr = getSpineFrame(sOrig);
    let r = getCobRadius(sOrig);
    let theta = random(-75, 65);
    let sx = fr.c.x + fr.n.x * (r * sin(theta));
    let sy = fr.c.y + fr.n.y * (r * sin(theta));

    // Subtle shadow just beneath the stray silk thread
    let initAng = random(-55, 25);
    let len = random(140, 440);
    let pts = generateSilkThreadPath(sx, sy, initAng, len, random(0.55, 0.95), i * 31.7 + 1500);

    let shadowPts = pts.map(p => [p[0] + 2.2, p[1] + 2.8]);
    brush.set("rotring", "#78481b", 0.26);
    brush.spline(shadowPts, 0.45);

    let threadCol = theta < 0 ? random(PALETTE.silkGlint) : random(PALETTE.silkThread);
    brush.set("silk_thread", threadCol, random(0.36, 0.56));
    brush.spline(pts, 0.45);
  }
}

