    weight: 0.34,
    scatter: 0.32,
    sharpness: 0.24,
    grain: 0.55,
    opacity: 48,
    spacing: 0.16,
    pressure: [0.15, 1.0, 0.15],
    noise: 0.45
  });

  brush.add("scribe", {
    type: "default",
    weight: 0.14,
    scatter: 0.08,
    sharpness: 0.68,
    grain: 0.38,
    opacity: 85,
    spacing: 0.11,
    pressure: [0.25, 1.0, 0.25],
    noise: 0.25
  });

  brush.add("glint", {
    type: "default",
    weight: 0.09,
    scatter: 0.02,
    sharpness: 0.92,
    grain: 0.12,
    opacity: 210,
    spacing: 0.07,
    pressure: [0.1, 1.25, 0.1],
    noise: 0.1
  });

  brush.scaleBrushes(3);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.voidBlack);

  // 1. Dense velvety charcoal ground
  drawVelvetGround();

  // 2. Pewter platter emerging from smoke
  drawPewterPlatter(600, 665, 485, 305, -4);

  // 3. Crushed ice bed (deep shadows & mid-tone facets)
  drawCrushedIceBed(600, 660, 415, 250);

  // 4. Shucked oysters arranged around the platter (back to front)
  const oysters = getOysterLayout();
  for (let i = 0; i < oysters.length; i++) {
    drawOyster(oysters[i]);
  }

  // 5. Foreground & interstitial crushed ice crystals overlapping shell edges
  drawInterstitialIce(oysters);

  // 6. The single muted pale-ochre lemon wedge at the center
  drawLemonWedge(LEMON_POS.x, LEMON_POS.y, 152, 70, 19);

  // 7. Dissolve outer edges into velvety darkness & nocturnal smoke
  drawAtmosphericDissolve();

  // 8. Final needle-sharp wet specular glints (nacre, brine meniscus, ice tips, lemon pulp)
  drawFinalWetSpeculars(oysters);

  noLoop();
}

// ============================================================================
// PRIMITIVE HELPERS
// ============================================================================

function washPoly(pts, col, opacity, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, opacity);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function hatchPoly(pts, brushName, col, weight, dist, angle, opts, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.hatchStyle(brushName, col, weight);
  brush.hatch(dist, angle, opts);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noHatch();
}

function strokeSpline(pts, brushName, col, weight, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, weight);
  brush.spline(pts, curvature);
  brush.noStroke();
}

function strokeLine(x1, y1, x2, y2, brushName, col, weight) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, weight);
  brush.line(x1, y1, x2, y2);
  brush.noStroke();
}

function lerpPt(p1, p2, t) {
  return [p1[0] + (p2[0] - p1[0]) * t, p1[1] + (p2[1] - p1[1]) * t];
}

// ============================================================================
// 1. VELVETY CHARCOAL GROUND
// ============================================================================

function drawVelvetGround() {
  // Subtle central tonal lift out of near-total black
  const rings = 9;
  for (let i = rings; i >= 1; i--) {
    let t = i / rings;
    let rx = 180 + t * 440;
    let ry = 130 + t * 310;
    let pts = [];
    for (let a = 0; a < 360; a += 12) {
      let n = noise(cos(a) * 0.8 + 10, sin(a) * 0.8 + 10, i * 0.2);
      let rMod = 0.88 + n * 0.24;
      pts.push([
        580 + cos(a - 8) * rx * rMod,
        640 + sin(a - 8) * ry * rMod
      ]);
    }
    let col = i > 5 ? PALETTE.soot : (i > 2 ? PALETTE.charcoalDark : PALETTE.charcoalMid);
    washPoly(pts, col, 38, 0.4);
  }

  // Dense cross-hatched charcoal bed across the canvas
  let fullRect = [[40, 40], [1160, 40], [1160, 1160], [40, 1160]];
  hatchPoly(fullRect, "charcoal", PALETTE.soot, 1.3, 11, -35, { rand: 0.18 }, 0);
  hatchPoly(fullRect, "charcoal", PALETTE.voidBlack, 1.4, 13, 55, { rand: 0.22 }, 0);

  // Burnished central charcoal glow where light falls from upper-left
  for (let i = 0; i < 160; i++) {
    let ang = random(360);
    let rad = Math.pow(random(), 0.75) * 490;
    let cx = 560 + cos(ang) * rad;
    let cy = 630 + sin(ang) * rad * 0.68;
    let len = random(90, 240);
    let dir = -32 + random(-18, 18);
    let p1 = [cx - cos(dir) * len * 0.5, cy - sin(dir) * len * 0.5, 0.2];
    let p2 = [cx + random(-10, 10), cy + random(-10, 10), 1.0];
    let p3 = [cx + cos(dir) * len * 0.5, cy + sin(dir) * len * 0.5, 0.2];
    let dLight = dist(cx, cy, 480, 560);
    let col = dLight < 280 ? PALETTE.charcoalMid : PALETTE.charcoalDark;
    strokeSpline([p1, p2, p3], "velvet", col, random(0.9, 1.8), 0.4);
  }
}

// ============================================================================
// 2. PEWTER PLATTER
// ============================================================================

function drawPewterPlatter(cx, cy, rx, ry, rotDeg) {
  let cosR = cos(rotDeg), sinR = sin(rotDeg);
  function ellPt(a, radX, radY) {
    let lx = cos(a) * radX;
    let ly = sin(a) * radY;
    return [cx + lx * cosR - ly * sinR, cy + lx * sinR + ly * cosR];
  }

  // Outer platter shadow into ground
  let shadowPts = [];
  for (let a = 0; a < 360; a += 8) {
    shadowPts.push(ellPt(a, rx + 18, ry + 22));
  }
  washPoly(shadowPts, PALETTE.voidBlack, 140, 0.3);

  // Outer platter rim body
  let rimPts = [];
  for (let a = 0; a < 360; a += 8) {
    rimPts.push(ellPt(a, rx, ry));
  }
  washPoly(rimPts, PALETTE.charcoalDark, 150, 0.3);

  // Inner platter well (darker recessed basin)
  let wellPts = [];
  for (let a = 0; a < 360; a += 8) {
    wellPts.push(ellPt(a, rx * 0.82, ry * 0.80));
  }
  washPoly(wellPts, PALETTE.soot, 190, 0.3);

  // Burnished pewter rim segments emerging on the front-left, left, and back-left
  // Angles in degrees: 180 is left, 90 is bottom, 270 is top, 0 is right
  const rimArcs = [
    // Subtle metallic sheen along front-left & left rim
    { aStart: 95, aEnd: 245, rFrac: 0.98, col: PALETTE.slateShadow, w: 1.6, brush: "velvet" },
    { aStart: 105, aEnd: 235, rFrac: 0.94, col: PALETTE.slateMid, w: 1.2, brush: "burnish" },
    { aStart: 112, aEnd: 215, rFrac: 0.96, col: PALETTE.pewterDark, w: 0.9, brush: "burnish" },
    { aStart: 122, aEnd: 195, rFrac: 0.99, col: PALETTE.pewterLight, w: 0.65, brush: "scribe" },
    { aStart: 130, aEnd: 178, rFrac: 0.995, col: PALETTE.silverGrey, w: 0.45, brush: "scribe" },
    { aStart: 138, aEnd: 166, rFrac: 0.998, col: PALETTE.nacreBright, w: 0.4, brush: "glint" },

    // Inner lip of the rim catching raking light on the bottom-right & front
    { aStart: 35, aEnd: 155, rFrac: 0.83, col: PALETTE.slateShadow, w: 1.2, brush: "burnish" },
    { aStart: 55, aEnd: 140, rFrac: 0.825, col: PALETTE.pewterDark, w: 0.75, brush: "scribe" },
    { aStart: 70, aEnd: 125, rFrac: 0.825, col: PALETTE.silverGrey, w: 0.45, brush: "scribe" },
    { aStart: 82, aEnd: 112, rFrac: 0.826, col: PALETTE.nacreSilver, w: 0.35, brush: "glint" },

    // Faint whisper of back-top rim before dissolving into smoke
    { aStart: 220, aEnd: 295, rFrac: 0.95, col: PALETTE.slateShadow, w: 1.1, brush: "velvet" },
    { aStart: 235, aEnd: 278, rFrac: 0.98, col: PALETTE.pewterDark, w: 0.55, brush: "burnish" },
    { aStart: 242, aEnd: 268, rFrac: 0.83, col: PALETTE.slateMid, w: 0.5, brush: "scribe" }
  ];

  for (let arc of rimArcs) {
    let pts = [];
    let steps = 18;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let a = lerp(arc.aStart, arc.aEnd, t);
      let p = ellPt(a, rx * arc.rFrac, ry * arc.rFrac);
      let press = sin(t * 180) * 1.1 + 0.15;
      pts.push([p[0], p[1], press]);
    }
    strokeSpline(pts, arc.brush, arc.col, arc.w, 0.5);
  }

  // Fine tarnished scratches on the visible pewter flange
  for (let i = 0; i < 65; i++) {
    let a = random(85, 255);
    let rf1 = random(0.84, 0.98);
    let rf2 = rf1 + random(-0.03, 0.03);
    let p1 = ellPt(a, rx * rf1, ry * rf1);
    let p2 = ellPt(a + random(3, 9), rx * rf2, ry * rf2);
    let col = random() < 0.4 ? PALETTE.pewterDark : PALETTE.charcoalDark;
    strokeLine(p1[0], p1[1], p2[0], p2[1], "scribe", col, random(0.25, 0.5));
  }
}

// ============================================================================
// 3. CRUSHED ICE BED & CRYSTALLINE FACETS
// ============================================================================

function drawIceShard(cx, cy, size, lightFactor, warmFactor) {
  let sides = floor(random(3, 6));
  let pts = [];
  let baseAng = random(360);
  for (let i = 0; i < sides; i++) {
    let a = baseAng + (i * 360) / sides + random(-18, 18);
    let r = size * random(0.55, 1.15);
    pts.push([cx + cos(a) * r, cy + sin(a) * r * 0.82]);
  }

  // Facet orientation vs light
  let facetAngle = random(360);
  let alignment = (cos(facetAngle) * LIGHT_DIR.x + sin(facetAngle) * LIGHT_DIR.y + 1) * 0.5;
  let lum = constrain(lightFactor * (0.35 + alignment * 0.85), 0, 1);

  // Base translucent ice wash
  let baseCol = PALETTE.charcoalDark;
  if (warmFactor > 0.25 && lum > 0.35) {
    baseCol = lum > 0.65 ? PALETTE.pithMid : (lum > 0.45 ? PALETTE.pithDark : PALETTE.ochreDeep);
  } else {
    if (lum > 0.78) baseCol = PALETTE.silverGrey;
    else if (lum > 0.58) baseCol = PALETTE.pewterLight;
    else if (lum > 0.40) baseCol = PALETTE.slateMid;
    else if (lum > 0.24) baseCol = PALETTE.slateShadow;
    else baseCol = PALETTE.charcoalDark;
  }

  washPoly(pts, baseCol, map(lum, 0, 1, 45, 115), 0.05);

  // Crystalline internal striation hatching
  if (size > 11 && lum > 0.22) {
    let hCol = warmFactor > 0.35 ? PALETTE.pithLight : (lum > 0.6 ? PALETTE.nacreSilver : PALETTE.pewterDark);
    hatchPoly(
      pts,
      "scribe",
      hCol,
      0.35,
      map(size, 10, 40, 3.5, 6.5),
      facetAngle,
      { rand: 0.08 },
      0.05
    );
  }

  // Dark wet crevice on the shadow edge of the crystal
  let sIdx = floor(random(pts.length));
  let pA = pts[sIdx];
  let pB = pts[(sIdx + 1) % pts.length];
  strokeLine(pA[0], pA[1], pB[0], pB[1], "burnish", PALETTE.voidBlack, random(0.4, 0.9));

  // Crisp frost edge along the upper-left facing ridge
  if (lum > 0.38) {
    let bestEdge = 0;
    let bestDot = -999;
    for (let i = 0; i < pts.length; i++) {
      let p1 = pts[i];
      let p2 = pts[(i + 1) % pts.length];
      let nx = -(p2[1] - p1[1]);
      let ny = p2[0] - p1[0];
      let len = Math.hypot(nx, ny) || 1;
      let dot = (nx / len) * LIGHT_DIR.x + (ny / len) * LIGHT_DIR.y;
      if (dot > bestDot) {
        bestDot = dot;
        bestEdge = i;
      }
    }
    let e1 = pts[bestEdge];
    let e2 = pts[(bestEdge + 1) % pts.length];
    let edgeCol = warmFactor > 0.4
      ? PALETTE.ochrePale
      : (lum > 0.72 ? PALETTE.nacreBright : PALETTE.silverGrey);
    strokeLine(e1[0], e1[1], e2[0], e2[1], "scribe", edgeCol, map(lum, 0.38, 1, 0.3, 0.65));

    if (lum > 0.76 && random() < 0.45) {
      let mid = lerpPt(e1, e2, 0.5);
      strokeLine(e1[0], e1[1], mid[0], mid[1], "glint", PALETTE.specular, 0.45);
    }
  }
}

function drawCrushedIceBed(cx, cy, rx, ry) {
  // Underlying dark slush mounds
  for (let i = 0; i < 45; i++) {
    let a = random(360);
    let r = Math.pow(random(), 0.65) * 0.95;
    let mx = cx + cos(a) * rx * r;
    let my = cy + sin(a) * ry * r;
    let dLight = dist(mx, my, 490, 560);
    let lFac = constrain(map(dLight, 80, 480, 0.95, 0.12), 0.1, 1);
    let moundPts = [];
    let mRad = random(35, 85);
    for (let k = 0; k < 8; k++) {
      let ka = k * 45 + random(-15, 15);
      let kr = mRad * random(0.7, 1.2);
      moundPts.push([mx + cos(ka) * kr, my + sin(ka) * kr * 0.72]);
    }
    let col = lFac > 0.55 ? PALETTE.slateShadow : PALETTE.charcoalDark;
    washPoly(moundPts, col, 75, 0.25);
  }

  // Hundreds of faceted crushed ice fragments across the platter well
  const shardCount = 340;
  for (let i = 0; i < shardCount; i++) {
    let a = random(360);
    let r = Math.pow(random(), 0.68);
    let sx = cx + cos(a) * rx * r + random(-15, 15);
    let sy = cy + sin(a) * ry * r + random(-12, 12);

    // Light falls strongest on upper-left/center, fades toward right & outer rim
    let dFocus = dist(sx, sy, 510, 585);
    let edgeFade = constrain(map(r, 0.65, 1.02, 1.0, 0.08), 0.05, 1.0);
    let lightFactor = constrain(map(dFocus, 40, 460, 1.0, 0.18), 0.12, 1.0) * edgeFade;

    // Warm ochre bounce light near the central lemon wedge
    let dLemon = dist(sx, sy, LEMON_POS.x, LEMON_POS.y);
    let warmFactor = constrain(map(dLemon, 35, 155, 0.85, 0), 0, 0.85);

    let size = random(9, 28) * map(r, 0, 1, 1.15, 0.75);
    drawIceShard(sx, sy, size, lightFactor, warmFactor);
  }
}

