      lip: [765, 445],
      width: 126,
      skew: 0.10,
      light: 0.62,
      warmBounce: 0.20,
      seed: 202
    },
    {
      // 3. Mid-Left Oyster (deep shell hollow catching silver crescent)
      hinge: [470, 605],
      lip: [245, 575],
      width: 134,
      skew: 0.06,
      light: 0.84,
      warmBounce: 0.25,
      seed: 303
    },
    {
      // 4. Mid-Right Oyster (dramatic chiaroscuro, outer edge dissolving into dark)
