function buildOysterPoint(cfg, uFrac, vFrac) {
  let hx = cfg.hinge[0], hy = cfg.hinge[1];
  let lx = cfg.lip[0], ly = cfg.lip[1];
  let dx = lx - hx, dy = ly - hy;
  let L = Math.hypot(dx, dy);
  let ux = dx / L, uy = dy / L;
  let vx = -uy, vy = ux;

  // Asymmetric organic curve of oyster shell
  let bend = sin(constrain(uFrac, 0, 1) * 180) * cfg.skew * L;
  let halfW = (cfg.width * 0.5) * (0.24 + 0.76 * Math.pow(constrain(uFrac, 0.02, 1), 0.58));

  let px = hx + ux * (uFrac * L) + vx * (vFrac * halfW + bend);
  let py = hy + uy * (uFrac * L) + vy * (vFrac * halfW + bend) * 0.92; // perspective foreshortening
  return [px, py];
}

function getOysterContour(cfg, scaleU, scaleV, fluteAmp, steps = 44) {
  let pts = [];
  for (let i = 0; i < steps; i++) {
    let a = (i * 360) / steps;
    // Parameterize along shell axis: a=0 is lip (u=1), a=180 is hinge (u=0)
    let uBase = (cos(a) + 1) * 0.5;
    let vBase = sin(a);

    // Fluted crenellations strongest near the outer lip (uBase > 0.55)
    let lipWeight = Math.pow(uBase, 1.6);
    let n = noise(cos(a) * 1.5 + cfg.seed, sin(a) * 1.5 + cfg.seed);
    let flute = (sin(a * 8 + cfg.seed) * 0.55 + (n - 0.5) * 1.3) * fluteAmp * lipWeight;

    let u = 0.5 + (uBase - 0.5) * scaleU + flute * 0.06;
    let v = vBase * scaleV * (1 + flute * 0.14);
    pts.push(buildOysterPoint(cfg, u, v));
  }
  return pts;
}

function drawOyster(cfg) {
  // 1. Deep shadow cast into the crushed ice beneath the shell
  let shadowPts = getOysterContour(cfg, 1.10, 1.14, 0.9, 40);
  for (let p of shadowPts) {
    p[0] += 8;
    p[1] += 12;
  }
  washPoly(shadowPts, PALETTE.voidBlack, 185, 0.35);

  // 2. Rough outer dark chalky shell rim & foliated lamellae
  let outerPts = getOysterContour(cfg, 1.03, 1.04, 1.0, 48);
  washPoly(outerPts, PALETTE.umberBlack, 225, 0.35);

  let midShellPts = getOysterContour(cfg, 0.97, 0.96, 0.85, 44);
  washPoly(midShellPts, PALETTE.umberDark, 180, 0.35);

  // Radial fluted ribs on the outer shell lip
  for (let i = 0; i < 42; i++) {
    let a = random(-105, 105); // Outer lip fan
    let u1 = 0.72 + random(0.08);
    let u2 = 0.98 + random(0.07);
    let v = sin(a) * random(0.85, 1.06);
    let p1 = buildOysterPoint(cfg, u1, v * 0.9);
    let p2 = buildOysterPoint(cfg, u2, v * 1.04);

    // Check if ridge faces upper-left light
    let rdx = p2[0] - p1[0], rdy = p2[1] - p1[1];
    let rLen = Math.hypot(rdx, rdy) || 1;
    let dot = (- (rdy / rLen) * LIGHT_DIR.x + (rdx / rLen) * LIGHT_DIR.y);
    let col = dot > 0.15 ? PALETTE.brineTaupe : (random() < 0.5 ? PALETTE.umberMid : PALETTE.voidBlack);
    strokeLine(p1[0], p1[1], p2[0], p2[1], "burnish", col, random(0.45, 0.95));
  }

  // 3. Inner Mother-of-Pearl (Nacre) Basin
  // Concave bowl lighting: top-left wall is in shadow, bottom-right wall & hinge catch burnished silver light
  let nacrePts = getOysterContour(cfg, 0.89, 0.85, 0.35, 44);
  washPoly(nacrePts, PALETTE.slateShadow, 210, 0.4);

  // Concentric pearlescent growth bands inside the shell basin
  const rings = 14;
  for (let r = rings; r >= 1; r--) {
    let t = r / rings;
    let ringPts = [];
    let steps = 36;
    for (let i = 0; i <= steps; i++) {
      let a = (i * 360) / steps;
      let uBase = (cos(a) + 1) * 0.5;
      let vBase = sin(a);
      let u = 0.08 + uBase * 0.80 * t;
      let v = vBase * 0.82 * t;
      let p = buildOysterPoint(cfg, u, v);
      ringPts.push([p[0], p[1], 0.5 + 0.5 * sin((i / steps) * 180)]);
    }

    // Determine nacre color for this ring
    let col = PALETTE.slateMid;
    if (t > 0.72) col = PALETTE.pewterDark;
    else if (t > 0.48) col = PALETTE.pearlSage;
    else col = PALETTE.charcoalMid;

    strokeSpline(ringPts, "burnish", col, 0.75, 0.5);
  }

  // Burnished nacre light sweeping across the concave interior wall facing the upper-left light
  // For each shell point, compute its inward normal (pointing toward basin center)
  let basinCenter = buildOysterPoint(cfg, 0.48, 0.0);
  for (let pass = 0; pass < 48; pass++) {
    let f = pass / 48;
    let aCenter = lerp(-155, 155, f);
    let aSpan = random(28, 65);
    let rBand = random(0.52, 0.88);

    // Sample point along the ring to test inward normal vs light direction
    let uTest = 0.08 + ((cos(aCenter) + 1) * 0.5) * 0.80 * rBand;
    let vTest = sin(aCenter) * 0.82 * rBand;
    let pTest = buildOysterPoint(cfg, uTest, vTest);
    let inX = basinCenter[0] - pTest[0];
    let inY = basinCenter[1] - pTest[1];
    let inLen = Math.hypot(inX, inY) || 1;
    // In a shallow concave shell, light hits the far interior wall (inward normal aligned with LIGHT_DIR)
    // AND the flat top-left rim bevel (outward normal aligned with LIGHT_DIR when rBand > 0.80)
    let concaveDot = (inX / inLen) * LIGHT_DIR.x + (inY / inLen) * LIGHT_DIR.y;
    let rimDot = -concaveDot;

    let intensity = 0;
    if (rBand > 0.78 && rimDot > 0.25) {
      intensity = rimDot * 0.95 * cfg.light;
    } else if (concaveDot > 0.05) {
      intensity = (0.35 + concaveDot * 0.75) * cfg.light;
    } else {
      intensity = 0.15 * cfg.light;
    }

    let arcPts = [];
    let arcSteps = 10;
    for (let k = 0; k <= arcSteps; k++) {
      let kt = k / arcSteps;
      let a = aCenter - aSpan * 0.5 + kt * aSpan;
      let u = 0.07 + ((cos(a) + 1) * 0.5) * 0.81 * rBand;
      let v = sin(a) * 0.83 * rBand;
      let pt = buildOysterPoint(cfg, u, v);
      arcPts.push([pt[0], pt[1], sin(kt * 180) * 1.1 + 0.15]);
    }

    let col = PALETTE.slateShadow;
    if (intensity > 0.78) col = PALETTE.nacreBright;
    else if (intensity > 0.62) col = PALETTE.nacreSilver;
    else if (intensity > 0.46) col = cfg.warmBounce > 0.25 && random() < 0.4 ? PALETTE.fleshLight : PALETTE.silverGrey;
    else if (intensity > 0.30) col = random() < 0.45 ? PALETTE.pearlWarm : PALETTE.pewterLight;
    else col = PALETTE.slateMid;

    let bName = intensity > 0.68 ? "scribe" : "burnish";
    let w = intensity > 0.68 ? random(0.45, 0.85) : random(0.75, 1.35);
    strokeSpline(arcPts, bName, col, w, 0.5);
  }

  // Luminous nacre hinge shelf (near u = 0.05..0.24)
  for (let h = 0; h < 18; h++) {
    let u = random(0.05, 0.24);
    let vSpan = random(0.35, 0.68);
    let p1 = buildOysterPoint(cfg, u, -vSpan);
    let p2 = buildOysterPoint(cfg, u + 0.03, 0);
    let p3 = buildOysterPoint(cfg, u, vSpan);
    let col = h > 11 ? PALETTE.nacreBright : (h > 5 ? PALETTE.nacreSilver : PALETTE.silverGrey);
    strokeSpline(
      [[p1[0], p1[1], 0.2], [p2[0], p2[1], 1.1], [p3[0], p3[1], 0.2]],
      "burnish",
      col,
      random(0.5, 1.0),
      0.5
    );
  }

  // 4. Pooled Brine (Oyster Liquor) in the deep hollow of the shell
  let brinePts = [];
  for (let i = 0; i < 32; i++) {
    let a = (i * 360) / 32;
    let u = 0.20 + ((cos(a) + 1) * 0.5) * 0.58;
    let v = sin(a) * 0.64;
    brinePts.push(buildOysterPoint(cfg, u, v));
  }
  washPoly(brinePts, PALETTE.umberBlack, 150, 0.4);
  washPoly(brinePts, PALETTE.slateShadow, 80, 0.4);

  // 5. The Ruffled Dark Mantle Frill (Briny Edge of the Oyster Meat)
  let frillOuter = [];
  let frillInner = [];
  let frillSteps = 64;
  for (let i = 0; i <= frillSteps; i++) {
    let a = (i * 360) / frillSteps;
    let uBase = 0.21 + ((cos(a) + 1) * 0.5) * 0.56;
    let vBase = sin(a) * 0.60;

    // Ruffled sinusoidal waves along the mantle edge
    let wave = sin(a * 14 + cfg.seed * 2) * 0.035 + cos(a * 23 - cfg.seed) * 0.022;
    let uOut = uBase + cos(a) * wave;
    let vOut = vBase + sin(a) * wave * 1.4;
    let uIn = 0.24 + ((cos(a) + 1) * 0.5) * 0.48 + cos(a + 20) * wave * 0.6;
    let vIn = sin(a) * 0.48 + sin(a + 20) * wave;

    frillOuter.push(buildOysterPoint(cfg, uOut, vOut));
    frillInner.push(buildOysterPoint(cfg, uIn, vIn));
  }

  // Base dark sepia-black mantle ribbon
  washPoly(frillOuter, PALETTE.umberBlack, 210, 0.35);
  washPoly(frillInner, PALETTE.umberDark, 190, 0.35);

  // Detailed crinkled folds across the mantle ribbon
  for (let i = 0; i < frillSteps; i++) {
    let pOut = frillOuter[i];
    let pIn = frillInner[i];
    let isCrest = sin((i / frillSteps) * 360 * 14 + cfg.seed * 2) > 0.15;
    let foldCol = isCrest
      ? (random() < 0.45 ? PALETTE.fleshShadow : PALETTE.brineTaupe)
      : PALETTE.umberBlack;
    strokeLine(pIn[0], pIn[1], pOut[0], pOut[1], "burnish", foldCol, isCrest ? 0.55 : 0.75);

    if (isCrest && random() < 0.38) {
      let mid = lerpPt(pIn, pOut, 0.65);
      strokeLine(mid[0], mid[1], pOut[0], pOut[1], "scribe", PALETTE.fleshMid, 0.32);
    }
  }

  // 6. Plump Visceral Oyster Belly & Adductor Muscle
  // Convex 3D pillow: top-left dome catches creamy pearlescent light, bottom-right tucks into shadow
  let bellyPts = [];
  for (let i = 0; i < 36; i++) {
    let a = (i * 360) / 36;
    let u = 0.24 + ((cos(a) + 1) * 0.5) * 0.46;
    let v = sin(a) * 0.47;
    bellyPts.push(buildOysterPoint(cfg, u, v));
  }
  washPoly(bellyPts, PALETTE.umberMid, 195, 0.45);
  washPoly(bellyPts, PALETTE.brineTaupe, 130, 0.45);

  // Compute meat center and light offset for convex shading
  let meatCenter = buildOysterPoint(cfg, 0.46, 0.0);
  let highlightPos = [
    meatCenter[0] + LIGHT_DIR.x * (cfg.width * 0.14),
    meatCenter[1] + LIGHT_DIR.y * (cfg.width * 0.12)
  ];

  // Layered 3D cross-contour burnish strokes over the plump belly
  const contourLayers = 52;
  for (let l = 0; l < contourLayers; l++) {
    let t = l / contourLayers; // 0 = outer belly, 1 = high dome center
    let radScale = 1.0 - t * 0.88;
    let aStart = random(0, 360);
    let aArc = random(95, 210);

    let curvePts = [];
    let steps = 10;
    let avgLum = 0;

    for (let k = 0; k <= steps; k++) {
      let kt = k / steps;
      let a = aStart + kt * aArc;
      let u = 0.25 + ((cos(a) + 1) * 0.5) * 0.43 * radScale;
      let v = sin(a) * 0.44 * radScale;
      let p = buildOysterPoint(cfg, u, v);
      // Shift inner rings slightly toward the convex highlight peak
      let px = lerp(p[0], highlightPos[0], t * 0.55);
      let py = lerp(p[1], highlightPos[1], t * 0.55);

      // Normal on convex pillow
      let nx = (px - meatCenter[0]) / (cfg.width * 0.35);
      let ny = (py - meatCenter[1]) / (cfg.width * 0.35);
      let dot = constrain(nx * LIGHT_DIR.x + ny * LIGHT_DIR.y, -1, 1);
      let lum = (0.35 + (dot + 1) * 0.35 + t * 0.35) * cfg.light;
      avgLum += lum;

      curvePts.push([px, py, sin(kt * 180) * 1.05 + 0.15]);
    }
    avgLum /= (steps + 1);

    let col = PALETTE.brineTaupe;
    if (avgLum > 0.86) col = PALETTE.fleshGlow;
    else if (avgLum > 0.72) col = PALETTE.fleshCream;
    else if (avgLum > 0.58) col = PALETTE.fleshLight;
    else if (avgLum > 0.44) col = PALETTE.fleshMid;
    else if (avgLum > 0.30) col = PALETTE.fleshShadow;
    else col = PALETTE.umberMid;

    strokeSpline(curvePts, "burnish", col, map(t, 0, 1, 1.15, 0.55), 0.5);
  }

  // Subtle anatomical gill striations & adductor muscle separation fold
  for (let g = 0; g < 16; g++) {
    let f = g / 16;
    let a = lerp(-75, 75, f);
    let p1 = buildOysterPoint(cfg, 0.52, sin(a) * 0.32);
    let p2 = buildOysterPoint(cfg, 0.67, sin(a) * 0.44);
    let col = g % 2 === 0 ? PALETTE.umberDark : PALETTE.fleshLight;
    strokeLine(p1[0], p1[1], p2[0], p2[1], "scribe", col, 0.32);
  }

  // Adductor muscle crescent scar/cushion (firmer, slightly warmer pearl tone at u ~ 0.34, v ~ 0.14)
  let addPts = [];
  for (let i = 0; i <= 14; i++) {
    let a = (i / 14) * 260 - 40;
    let u = 0.33 + cos(a) * 0.08;
    let v = 0.12 + sin(a) * 0.15;
    let p = buildOysterPoint(cfg, u, v);
    addPts.push([p[0], p[1], sin((i / 14) * 180) + 0.2]);
  }
  strokeSpline(addPts, "burnish", PALETTE.umberDark, 0.7, 0.5);
  for (let i = 0; i < addPts.length; i++) {
    addPts[i][0] -= 2.5;
    addPts[i][1] -= 2.5;
  }
  strokeSpline(addPts, "burnish", PALETTE.fleshCream, 0.65, 0.5);
}

// ============================================================================
// 5. INTERSTITIAL CRUSHED ICE & FROST OVERLAPS
// ============================================================================

function drawInterstitialIce(oysters) {
  // Clusters of crushed ice tucked between the shells and slightly overlapping outer rims
  for (let o of oysters) {
    for (let i = 0; i < 22; i++) {
      let a = random(360);
      let uBase = (cos(a) + 1) * 0.5;
      let vBase = sin(a);
      // Place right along the outer shell boundary
      let ringScale = random(0.92, 1.25);
      let pt = buildOysterPoint(o, 0.5 + (uBase - 0.5) * ringScale, vBase * ringScale);

      let dLemon = dist(pt[0], pt[1], LEMON_POS.x, LEMON_POS.y);
      let warmFactor = constrain(map(dLemon, 30, 150, 0.85, 0), 0, 0.85);
      let dFocus = dist(pt[0], pt[1], 510, 585);
      let lightFactor = constrain(map(dFocus, 50, 450, 0.95, 0.18), 0.15, 0.95) * o.light;

      drawIceShard(pt[0], pt[1], random(8, 20), lightFactor, warmFactor);
    }
  }

  // Central bed of glistening ice around the lemon wedge
  for (let i = 0; i < 55; i++) {
    let a = random(360);
    let r = random(28, 105);
    let ix = LEMON_POS.x + cos(a) * r;
    let iy = LEMON_POS.y + sin(a) * r * 0.72;
    let warm = constrain(map(r, 25, 110, 0.75, 0.1), 0, 0.8);
    drawIceShard(ix, iy, random(9, 22), random(0.65, 0.98), warm);
  }
}

// ============================================================================
// 6. THE SINGLE LEMON WEDGE (MUTED PALE OCHRE WARMTH)
// ============================================================================

function drawLemonWedge(cx, cy, length, radius, rotDeg) {
  let cosR = cos(rotDeg), sinR = sin(rotDeg);
  function toWorld(lx, ly) {
    return [cx + lx * cosR - ly * sinR, cy + lx * sinR + ly * cosR];
  }

  let halfL = length * 0.5;

  // 1. Deep amber-black cast shadow into the central ice bed
  let shadowPts = [];
  for (let i = 0; i <= 24; i++) {
    let a = (i / 24) * 360;
    let lx = cos(a) * (halfL + 10);
    let ly = sin(a) * (radius * 0.75) + 14;
    shadowPts.push(toWorld(lx, ly));
  }
  washPoly(shadowPts, PALETTE.voidBlack, 195, 0.35);
  washPoly(shadowPts, PALETTE.ochreShadow, 140, 0.35);

  // 2. Warm golden-ochre bounce glaze onto surrounding ice
  let glowPts = [];
  for (let i = 0; i < 20; i++) {
    let a = (i / 20) * 360;
    glowPts.push(toWorld(cos(a) * (halfL + 38), sin(a) * (radius + 26)));
  }
  washPoly(glowPts, PALETTE.ochreMuted, 28, 0.4);

  // 3. Outer Rind Crescent (Bottom curved belly of the wedge)
  let rindPts = [];
  let steps = 28;
  // Top ridge along cut edge from left tip (-halfL, 0) to right tip (+halfL, 0)
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let lx = lerp(-halfL, halfL, t);
    let ly = sin(t * 180) * (radius * 0.22); // Front cut rim
    rindPts.push(toWorld(lx, ly));
  }
  // Bottom rind belly from right tip back to left tip
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let lx = lerp(-halfL, halfL, t);
    let nipple = (t < 0.12 || t > 0.88) ? 0.85 : 1.0;
    let ly = sin(t * 180) * (radius * 0.98) * nipple;
    rindPts.push(toWorld(lx, ly));
  }
  washPoly(rindPts, PALETTE.ochreShadow, 230, 0.35);
  washPoly(rindPts, PALETTE.ochreDeep, 175, 0.35);

  // Burnished tonal steps along the curved lemon rind (dark umber base -> muted ochre upper curve)
  for (let b = 0; b < 38; b++) {
    let f = b / 38; // 0 = bottom shadow, 1 = upper rind near pith
    let tStart = random(0.06, 0.35);
    let tEnd = random(0.65, 0.94);
    let arcPts = [];
    let segs = 10;
    for (let k = 0; k <= segs; k++) {
      let kt = k / segs;
      let t = lerp(tStart, tEnd, kt);
      let lx = lerp(-halfL * 0.96, halfL * 0.96, t);
      let yBottom = sin(t * 180) * (radius * 0.95);
      let yTop = sin(t * 180) * (radius * 0.26);
      let ly = lerp(yBottom, yTop, f);
      let wp = toWorld(lx, ly);
      arcPts.push([wp[0], wp[1], sin(kt * 180) * 1.0 + 0.2]);
    }
    // Left half faces upper-left light more directly
    let col = PALETTE.ochreDeep;
    if (f > 0.78) col = PALETTE.ochreLight;
    else if (f > 0.56) col = PALETTE.ochreWarm;
    else if (f > 0.35) col = PALETTE.ochreMid;
    else if (f > 0.18) col = PALETTE.ochreMuted;
    else col = PALETTE.ochreUmber;

    strokeSpline(arcPts, "burnish", col, random(0.6, 1.15), 0.5);
  }

  // Porous citrus oil-gland dimples on the rind
  for (let d = 0; d < 95; d++) {
    let t = random(0.08, 0.92);
    let f = random(0.15, 0.88);
    let lx = lerp(-halfL * 0.92, halfL * 0.92, t);
    let ly = lerp(sin(t * 180) * radius * 0.92, sin(t * 180) * radius * 0.28, f);
    let p = toWorld(lx, ly);
    strokeLine(p[0], p[1], p[0] + 1.2, p[1] + 1.2, "scribe", PALETTE.ochreShadow, 0.45);
    if (f > 0.45 && t < 0.72 && random() < 0.55) {
      strokeLine(p[0] - 1.0, p[1] - 1.0, p[0], p[1] - 0.5, "glint", PALETTE.ochrePale, 0.3);
    }
  }

  // 4. Cut Pulp Faces & Pith Structure
  // Top-back cut plane (from central ridge at ly = -radius*0.42 down to back rim)
  // Front-top cut plane (from central ridge at ly = -radius*0.42 down to front rim at ly = +radius*0.26)
  let pulpOutline = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let lx = lerp(-halfL, halfL, t);
    let ly = -sin(t * 180) * (radius * 0.52); // Upper-back cut edge
    pulpOutline.push(toWorld(lx, ly));
  }
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let lx = lerp(-halfL, halfL, t);
    let ly = sin(t * 180) * (radius * 0.30); // Lower-front pith boundary
    pulpOutline.push(toWorld(lx, ly));
  }
  washPoly(pulpOutline, PALETTE.pithDark, 210, 0.35);

  // Inner pulp basin (recessed inside the white/ochre pith border)
  let innerPulp = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let lx = lerp(-halfL * 0.88, halfL * 0.88, t);
    let ly = -sin(t * 180) * (radius * 0.44);
    innerPulp.push(toWorld(lx, ly));
  }
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let lx = lerp(-halfL * 0.88, halfL * 0.88, t);
    let ly = sin(t * 180) * (radius * 0.18);
    innerPulp.push(toWorld(lx, ly));
  }
  washPoly(innerPulp, PALETTE.ochreDeep, 225, 0.35);

  // 5. Radial Carpel Segments & Translucent Juice Vesicles
  // Central pith core axis runs from (-halfL*0.85, -radius*0.14) to (+halfL*0.85, -radius*0.14)
  const numSegments = 5;
  const segAngles = [-162, -126, -90, -54, -18, 18]; // Fan across the cut face

  function getPulpRimPt(angDeg) {
    // Map angle from [-162..18] to t along the wedge rim
    let t = map(angDeg, -162, 18, 0.08, 0.92);
    let lx = lerp(-halfL * 0.86, halfL * 0.86, t);
    let ly = sin(t * 180) * (radius * 0.17);
    return [lx, ly];
  }

  function getBackRimPt(angDeg) {
    let t = map(angDeg, -162, 18, 0.08, 0.92);
    let lx = lerp(-halfL * 0.86, halfL * 0.86, t);
    let ly = -sin(t * 180) * (radius * 0.43);
    return [lx, ly];
  }

  // Render vesicles inside both the front-sloping and back-sloping cut faces
  for (let s = 0; s < numSegments; s++) {
    let a1 = segAngles[s] + 4;
    let a2 = segAngles[s + 1] - 4;
    let tMid = (s + 0.5) / numSegments;
    let coreX = lerp(-halfL * 0.42, halfL * 0.42, tMid);
    let coreY = -sin(tMid * 180) * (radius * 0.16);

    // Front-facing carpel vesicles
    for (let v = 0; v < 26; v++) {
      let af = random(a1, a2);
      let rf = random(0.18, 0.92);
      let rim = getPulpRimPt(af);
      let vx1 = lerp(coreX, rim[0], rf - 0.12);
      let vy1 = lerp(coreY, rim[1], rf - 0.12);
      let vx2 = lerp(coreX, rim[0], rf + 0.10);
      let vy2 = lerp(coreY, rim[1], rf + 0.10);

      let wp1 = toWorld(vx1, vy1);
      let wp2 = toWorld(vx2, vy2);

      let lum = map(s, 0, numSegments - 1, 0.95, 0.48) * random(0.7, 1.15);
      let vCol = lum > 0.82 ? PALETTE.ochreLight : (lum > 0.58 ? PALETTE.ochreWarm : PALETTE.ochreMuted);
      strokeLine(wp1[0], wp1[1], wp2[0], wp2[1], "burnish", vCol, random(0.45, 0.85));

      if (lum > 0.72 && random() < 0.42) {
        let mid = lerpPt(wp1, wp2, 0.5);
        strokeLine(wp1[0], wp1[1], mid[0], mid[1], "glint", PALETTE.ochrePale, 0.35);
      }
    }

    // Upper/Back-facing carpel vesicles (directly facing upper-left light!)
    for (let v = 0; v < 28; v++) {
      let af = random(a1, a2);
      let rf = random(0.18, 0.92);
      let rim = getBackRimPt(af);
      let vx1 = lerp(coreX, rim[0], rf - 0.12);
      let vy1 = lerp(coreY, rim[1], rf - 0.12);
      let vx2 = lerp(coreX, rim[0], rf + 0.10);
      let vy2 = lerp(coreY, rim[1], rf + 0.10);

      let wp1 = toWorld(vx1, vy1);
      let wp2 = toWorld(vx2, vy2);

      let lum = map(s, 0, numSegments - 1, 1.0, 0.55) * random(0.75, 1.2);
      let vCol = lum > 0.85 ? PALETTE.ochrePale : (lum > 0.62 ? PALETTE.ochreLight : PALETTE.ochreMid);
      strokeLine(wp1[0], wp1[1], wp2[0], wp2[1], "burnish", vCol, random(0.45, 0.85));

      if (lum > 0.75 && random() < 0.55) {
        let mid = lerpPt(wp1, wp2, 0.55);
        strokeLine(wp1[0], wp1[1], mid[0], mid[1], "glint", PALETTE.ochreGlint, 0.38);
      }
    }
  }

  // 6. Pith Membranes, Outer Pith Border & Central Pith Ridge
  // Radial membrane dividers
  for (let s = 0; s <= numSegments; s++) {
    let a = segAngles[s];
    let t = s / numSegments;
    let coreP = toWorld(lerp(-halfL * 0.45, halfL * 0.45, t), -sin(t * 180) * (radius * 0.16));
    let frontRim = toWorld(...getPulpRimPt(a));
    let backRim = toWorld(...getBackRimPt(a));
    let pCol = s < 4 ? PALETTE.pithLight : PALETTE.pithMid;
    strokeLine(coreP[0], coreP[1], frontRim[0], frontRim[1], "scribe", pCol, 0.45);
    strokeLine(coreP[0], coreP[1], backRim[0], backRim[1], "scribe", pCol, 0.45);
  }

  // Central pith ridge (from left tip to right tip)
  let ridgePts = [];
  for (let i = 0; i <= 16; i++) {
    let t = i / 16;
    let lx = lerp(-halfL * 0.95, halfL * 0.95, t);
    let ly = -sin(t * 180) * (radius * 0.16);
    let wp = toWorld(lx, ly);
    ridgePts.push([wp[0], wp[1], sin(t * 180) * 1.1 + 0.25]);
  }
  strokeSpline(ridgePts, "burnish", PALETTE.pithLight, 0.85, 0.5);
  strokeSpline(ridgePts.slice(1, 11), "scribe", PALETTE.ochrePale, 0.5, 0.5);

  // Front and back pith border arcs
  let frontBorder = [];
  let backBorder = [];
  for (let i = 0; i <= 18; i++) {
    let t = i / 18;
    let lx = lerp(-halfL * 0.96, halfL * 0.96, t);
    let wpF = toWorld(lx, sin(t * 180) * (radius * 0.23));
    let wpB = toWorld(lx, -sin(t * 180) * (radius * 0.47));
    frontBorder.push([wpF[0], wpF[1], sin(t * 180) + 0.2]);
    backBorder.push([wpB[0], wpB[1], sin(t * 180) + 0.2]);
  }
  strokeSpline(frontBorder, "burnish", PALETTE.pithMid, 0.8, 0.5);
  strokeSpline(frontBorder.slice(1, 12), "scribe", PALETTE.pithLight, 0.45, 0.5);
  strokeSpline(backBorder, "burnish", PALETTE.pithMid, 0.75, 0.5);
  strokeSpline(backBorder.slice(1, 11), "scribe", PALETTE.ochrePale, 0.45, 0.5);
}

// ============================================================================
// 7. ATMOSPHERIC SMOKE & VELVETY EDGE DISSOLVE
// ============================================================================

function drawAtmosphericDissolve() {
  // Peripheral charcoal washes that dissolve the platter's outer edges into total blackness
  const vignetteCount = 85;
  for (let i = 0; i < vignetteCount; i++) {
    let a = (i / vignetteCount) * 360 + random(-4, 4);
    // Keep upper-left slightly more open, make right and bottom-right deeply smoky
    let dirBias = (cos(a - 25) + 1) * 0.5;
    let rDist = random(420, 660) - dirBias * 75;
    let vx = 600 + cos(a) * rDist;
    let vy = 650 + sin(a) * rDist * 0.76;

    let blobPts = [];
    let bRad = random(95, 210);
    for (let k = 0; k < 10; k++) {
      let ka = k * 36 + random(-12, 12);
      let kr = bRad * random(0.7, 1.25);
      blobPts.push([vx + cos(ka) * kr, vy + sin(ka) * kr * 0.8]);
    }
    washPoly(blobPts, PALETTE.voidBlack, random(65, 145), 0.4);
  }

  // Sweeping dry-charcoal smoke veil strokes across the dark borders and right flank
  for (let i = 0; i < 190; i++) {
    let a = random(360);
    let r = random(370, 680);
    // Occasional smoke wisp drifting across the platter itself
    if (i < 35) r = random(180, 420);

    let sx = 600 + cos(a) * r;
    let sy = 655 + sin(a) * r * 0.74;
    let tangent = a + 90 + random(-25, 25);
    let len = random(110, 280);

    let p1 = [sx - cos(tangent) * len * 0.5, sy - sin(tangent) * len * 0.5, 0.15];
    let p2 = [sx + random(-15, 15), sy + random(-15, 15), 0.95];
    let p3 = [sx + cos(tangent) * len * 0.5, sy + sin(tangent) * len * 0.5, 0.15];

    let col = r > 440 ? PALETTE.voidBlack : PALETTE.soot;
    let w = r > 440 ? random(1.4, 2.6) : random(0.7, 1.3);
    strokeSpline([p1, p2, p3], "velvet", col, w, 0.45);
  }
}

// ============================================================================
// 8. FINAL WET SPECULAR GLINTS (NACRE, BRINE MENISCUS, ICE & LEMON)
// ============================================================================

function drawFinalWetSpeculars(oysters) {
  // 1. Razor-sharp wet highlights on each oyster (brine meniscus, nacre rim, plump belly)
  for (let cfg of oysters) {
    let glints = floor(26 * cfg.light);
    for (let i = 0; i < glints; i++) {
      let mode = random();
      if (mode < 0.42) {
        // Liquid meniscus crescent along the mantle frill & nacre boundary
        let a = random(-155, 155);
        let u = 0.22 + ((cos(a) + 1) * 0.5) * 0.52;
        let v = sin(a) * 0.56;
        let p1 = buildOysterPoint(cfg, u, v);
        let p2 = buildOysterPoint(cfg, u + 0.025, v + cos(a) * 0.04);
        let p3 = buildOysterPoint(cfg, u + 0.05, v + cos(a) * 0.07);
        let col = random() < 0.5 ? PALETTE.specular : PALETTE.nacreBright;
        strokeSpline(
          [[p1[0], p1[1], 0.1], [p2[0], p2[1], 1.15], [p3[0], p3[1], 0.1]],
          "glint",
          col,
          random(0.32, 0.62),
          0.5
        );
      } else if (mode < 0.76) {
        // Wet specular bead on the upper-left dome of the plump oyster belly
        let a = random(-135, 45);
        let rad = random(0.06, 0.34);
        let u = 0.38 + cos(a) * rad * 0.45;
        let v = -0.06 + sin(a) * rad * 0.45;
        let p = buildOysterPoint(cfg, u, v);
        let len = random(3.5, 9.5);
        let dir = a + 90 + random(-20, 20);
        strokeLine(
          p[0],
          p[1],
          p[0] + cos(dir) * len,
          p[1] + sin(dir) * len,
          "glint",
          PALETTE.specular,
          random(0.35, 0.68)
        );
      } else {
        // Mother-of-pearl glint near the hinge shelf or inner nacre wall
        let u = random() < 0.5 ? random(0.07, 0.22) : random(0.55, 0.84);
        let v = random(-0.68, 0.68);
        let p1 = buildOysterPoint(cfg, u, v);
        let p2 = buildOysterPoint(cfg, u + 0.03, v + random(-0.06, 0.06));
        strokeLine(p1[0], p1[1], p2[0], p2[1], "glint", PALETTE.nacreBright, random(0.3, 0.55));
      }
    }
  }

  // 2. Crystalline specular pinpricks on the central crushed ice facets
  for (let i = 0; i < 65; i++) {
    let a = random(360);
    let r = Math.pow(random(), 0.75) * 310;
    let ix = 545 + cos(a) * r;
    let iy = 625 + sin(a) * r * 0.65;
    let dLemon = dist(ix, iy, LEMON_POS.x, LEMON_POS.y);
    let col = dLemon < 95 ? PALETTE.ochreGlint : PALETTE.specular;
    let len = random(3, 8);
    let ang = random(-65, 25);
    strokeLine(ix, iy, ix + cos(ang) * len, iy + sin(ang) * len, "glint", col, random(0.3, 0.58));
  }

  // 3. Final wet juice glints on the lemon wedge pulp vesicles
  let cosR = cos(19), sinR = sin(19);
  for (let i = 0; i < 28; i++) {
    let lx = random(-58, 38);
    let ly = random(-26, 8);
    let wx = LEMON_POS.x + lx * cosR - ly * sinR;
    let wy = LEMON_POS.y + lx * sinR + ly * cosR;
    let len = random(2.5, 6.0);
    let ang = random(-80, 10);
    strokeLine(
      wx,
      wy,
      wx + cos(ang) * len,
      wy + sin(ang) * len,
      "glint",
      PALETTE.ochreGlint,
      random(0.32, 0.55)
    );
  }
}

// ============================================================================
// HYPERREALISM IN P5.BRUSH: TECHNICOLOR CANDY APPLE ON A STICK
// Layers of saturated watercolour glaze (blood carmine, crimson lake, hot cerise),
// warped mirror reflection of an emerald & canary yellow fairground awning,
// sharp pen-defined hardened sugar drip, over a velvety flat ultramarine curtain.
// ============================================================================

const CX = 708;
const CY = 742;
const R_BASE = 228;
const TILT = -7.5; // Slight theatrical tilt (degrees)

// Parametric apple contour in tilted canvas coordinates
function getAppleContourPt(deg, scaleX = 1.0, scaleY = 1.0, extraR = 0) {
  // deg: 0 = top cleft, 90 = right cheek, 180 = bottom base, 270 = left cheek
  let a = ((deg % 360) + 360) % 360;
  let dTop = a > 180 ? 360 - a : a; // distance in deg from top cleft (0..180)
  let dBot = Math.abs(180 - a);     // distance in deg from bottom base (0..180)

  // Apple anatomical modifiers:
  // 1. Deep top cleft indentation around 0 deg
  let topCleft = -0.19 * Math.exp(-Math.pow(dTop / 24, 2));
  // 2. Broad, voluptuous upper shoulders around +/- 44 deg
  let shoulder = 0.115 * Math.exp(-Math.pow((dTop - 44) / 34, 2));
  // 3. Full mid-cheeks around +/- 88 deg
  let cheek = 0.055 * Math.exp(-Math.pow((dTop - 88) / 48, 2));
  // 4. Slight organic asymmetry (left cheek slightly fuller, right slightly steeper)
  let asym = (a > 180 ? 0.018 : -0.008) * Math.sin(a * Math.PI / 180);
  // 5. Bottom double-lobe and subtle basal dimple at 180 deg
  let botLobe = 0.048 * Math.exp(-Math.pow((dBot - 26) / 20, 2));
  let botDimple = -0.045 * Math.exp(-Math.pow(dBot / 13, 2));

  let rNorm = 1.0 + topCleft + shoulder + cheek + asym + botLobe + botDimple;
  let r = R_BASE * rNorm + extraR;

  // Taper width slightly toward the bottom half for classic orchard apple poise
  let bottomTaper = 1.0 - 0.105 * Math.pow(Math.max(0, -Math.cos(a * Math.PI / 180)), 1.6);

  let lx = Math.sin(a * Math.PI / 180) * r * bottomTaper * scaleX;
  let ly = -Math.cos(a * Math.PI / 180) * r * scaleY;

  // Apply theatrical tilt
  let tr = TILT * Math.PI / 180;
  let rx = lx * Math.cos(tr) - ly * Math.sin(tr);
  let ry = lx * Math.sin(tr) + ly * Math.cos(tr);

  return [CX + rx, CY + ry];
}

// 3D Spherical-Apple Surface Mapping:
// u in [-1, 1] (horizontal across visible hemisphere)
// v in [-1, 1] (vertical from top cleft -1 to bottom base +1)
function getAppleSurfacePt(u, v) {
  let uClamped = Math.max(-1, Math.min(1, u));
  let vClamped = Math.max(-1, Math.min(1, v));

  // Spherical projection weighting for natural foreshortening near the rim
  let lat = vClamped * (Math.PI / 2);
  let lon = uClamped * (Math.PI / 2);

  let projX = Math.sin(lon) * Math.cos(lat * 0.88);
  let projY = Math.sin(lat);

  // Convert projected direction to contour angle & radial fraction
  let mag = Math.min(1.0, Math.hypot(projX, projY));
  let deg = (Math.atan2(projX, -projY) * 180 / Math.PI + 360) % 360;

  let edgePt = getAppleContourPt(deg, 1.0, 1.0, 0);
  // Cleft center shifts slightly down at top center
  let centerY = CY - 14 * Math.max(0, -vClamped);
  let centerX = CX - 4 * Math.max(0, -vClamped);

  // Smooth radial interpolation from interior axis to outer contour
  let easeMag = Math.pow(mag, 0.92);
  let x = centerX + (edgePt[0] - centerX) * easeMag;
  let y = centerY + (edgePt[1] - centerY) * easeMag;

  // Add top cleft depression pull when near u=0, v=-0.75
  let cleftPull = Math.exp(-Math.pow(uClamped / 0.35, 2) - Math.pow((vClamped + 0.78) / 0.25, 2));
  y += cleftPull * 28;

  return [x, y];
}

// Helper to build a closed polygon array on the 3D apple surface from a (u, v) loop
function buildSurfacePatch(uvPoints) {
  let pts = [];
  for (let i = 0; i < uvPoints.length; i++) {
    pts.push(getAppleSurfacePt(uvPoints[i][0], uvPoints[i][1]));
  }
  return pts;
}

// Helper to draw a closed polygon with current fill/wash/stroke state via beginShape
function drawClosedShape(pts, curvature = 0.35) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Primary Hardened Sugar Drip Contour (hanging from the right-base lobe)
function getPrimaryDripPts(offsetX = 0, offsetY = 0, scaleWidth = 1.0) {
  const cx = 738 + offsetX;
  const topY = 936 + offsetY;
  // Carefully sculpted asymmetric teardrop with collar, pinched neck, heavy belly, and sharp tip
  const profile = [
    // Left side descending from apple base collar to sharp hardened tip
    [-58, -4], [-42, 10], [-28, 28], [-18, 52], [-14, 78],
    [-19, 106], [-24, 132], [-20, 156], [-9, 176], [0, 192],
    // Right side ascending from sharp tip back to right apple base collar
    [8, 175], [18, 154], [22, 128], [17, 102], [13, 74],
    [17, 48], [28, 24], [46, 6], [64, -10], [20, -18], [-22, -16]
  ];
  return profile.map(p => [cx + p[0] * scaleWidth, topY + p[1]]);
}

// Secondary Smaller Sugar Drip / Bead on Left Base Lobe
function getSecondaryDripPts(offsetX = 0, offsetY = 0, scaleWidth = 1.0) {
  const cx = 636 + offsetX;
  const topY = 932 + offsetY;
  const profile = [
    [-42, -8], [-26, 6], [-16, 22], [-13, 42], [-15, 60],
    [-9, 76], [0, 86],
    [8, 75], [14, 58], [12, 40], [16, 20], [30, 4], [46, -6], [10, -14], [-18, -14]
  ];
  return profile.map(p => [cx + p[0] * scaleWidth, topY + p[1]]);
}

// Thick Molten Sugar Base Collar (spanning the bottom of the apple)
function getSugarCollarPts() {
  let pts = [];
  // Upper boundary inside lower apple belly
  for (let deg = 122; deg <= 238; deg += 6) {
    pts.push(getAppleContourPt(deg, 0.94, 0.93, -6));
  }
  // Lower boundary bulging with thick pooled candy wave
  for (let deg = 240; deg >= 120; deg -= 5) {
    let wave = 9 * Math.sin((deg - 120) * 0.11) + 6 * Math.cos((deg - 150) * 0.18);
    pts.push(getAppleContourPt(deg, 1.02, 1.03, 8 + wave));
  }
  return pts;
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(1955);
  noiseSeed(1955);

  // Custom fine glass-edge pen and soft glaze brushes
  brush.add("velvet_nap", {
    type: "default",
    weight: 4.5,
    scatter: 1.6,
    sharpness: 0.2,
    grain: 0.85,
    opacity: 42,
    spacing: 0.35,
    pressure: [0.4, 1.2, 0.4],
    rotate: "natural",
    noise: 0.7
  });

  brush.add("sugar_pen", {
    type: "default",
    weight: 1.1,
    scatter: 0.04,
    sharpness: 0.92,
    grain: 0.15,
    opacity: 220,
    spacing: 0.15,
    pressure: [0.6, 1.3, 0.5],
    rotate: "natural",
    noise: 0.2
  });

  background("#060b30");
}

function draw() {
  translate(-width / 2, -height / 2);

  // Ensure a valid brush state is always active
  brush.set("HB", "#0a1454", 1);

  // 1. VELVETY FLAT ULTRAMARINE CURTAIN
  drawUltramarineCurtain();

  // 2. THEATRICAL STAGE HALO & SHADOW ON CURTAIN
  drawTheatricalStageGlow();

  // 3. WOODEN STICK (DRAWN BEFORE FRONT CLEFT GLAZES)
  drawCandyAppleStick();

  // 4. OPAQUE LUMINOUS UNDER-WASHES (SO TRANSPARENT GLAZES GLOW PURELY)
  drawAppleOpaqueUnderpainting();

  // 5. LAYER UPON LAYER OF SATURATED WATERCOLOUR GLAZE
  drawAppleWatercolourGlazes();

  // 6. MIRROR HIGHLIGHTS: STRIPED FAIRGROUND AWNING IN EMERALD & CANARY YELLOW
  drawFairgroundAwningReflections();

  // 7. HARDENED SUGAR DRIP & SHARP PEN-DEFINED EDGES
  drawHardenedSugarDripsAndPenEdges();

  // 8. TOP CLEFT OVERLAPPING LIP, SYRUP MENISCUS & MICRO-BUBBLES
  drawTopCleftMeniscusAndMicroDetails();

  noLoop();
}

// ============================================================================
// 1. VELVETY FLAT ULTRAMARINE CURTAIN
// ============================================================================
function drawUltramarineCurtain() {
  brush.noStroke();
  brush.noFill();

  // Flat graphic theatrical curtain folds in pure, dense ultramarine tones
  const folds = [
    { x: -30,  w: 190, c: "#05092b", op: 255 },
    { x: 130,  w: 170, c: "#0c175c", op: 245 },
    { x: 265,  w: 140, c: "#13248a", op: 230 },
    { x: 375,  w: 185, c: "#081042", op: 250 },
    { x: 525,  w: 175, c: "#101f78", op: 235 },
    { x: 665,  w: 195, c: "#182ea8", op: 225 },
    { x: 825,  w: 165, c: "#0a134f", op: 245 },
    { x: 955,  w: 155, c: "#142794", op: 235 },
    { x: 1080, w: 160, c: "#060b33", op: 255 }
  ];

  for (let f of folds) {
    brush.wash(f.c, f.op);
    let pts = [
      [f.x, -20],
      [f.x + f.w, -20],
      [f.x + f.w - 18, 600],
      [f.x + f.w + 8, 1220],
      [f.x - 12, 1220],
      [f.x + 14, 600]
    ];
    drawClosedShape(pts, 0.2);
  }
  brush.noWash();

  // Deep velvety watercolour blooms across the curtain
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.65, 0.35);

  const curtainWashes = [
    { x: 290, y: 380, rx: 140, ry: 520, c: "#1b33b8", op: 75 },
    { x: 740, y: 460, rx: 180, ry: 540, c: "#1f3bd4", op: 85 },
    { x: 1010, y: 520, rx: 130, ry: 500, c: "#16299c", op: 70 },
    { x: 110, y: 700, rx: 150, ry: 480, c: "#050824", op: 110 },
    { x: 460, y: 680, rx: 130, ry: 520, c: "#070d38", op: 95 },
    { x: 890, y: 820, rx: 140, ry: 420, c: "#060b30", op: 105 }
  ];

  for (let cw of curtainWashes) {
    brush.fill(cw.c, cw.op);
    let pts = [];
    for (let a = 0; a < 360; a += 30) {
      pts.push([
        cw.x + Math.cos(a * Math.PI / 180) * cw.rx,
        cw.y + Math.sin(a * Math.PI / 180) * cw.ry
      ]);
    }
    drawClosedShape(pts, 0.45);
  }
  brush.noFill();

  // Tactile vertical velvet pile strokes (pure ultramarine & cobalt, zero mud)
  const velvetStrips = [
    { xMin: 150, xMax: 370, c: "#1c35bd", w: 0.9, count: 55 },
    { xMin: 540, xMax: 810, c: "#223fe0", w: 0.95, count: 75 },
    { xMin: 960, xMax: 1095, c: "#182ea8", w: 0.85, count: 40 },
    { xMin: 20, xMax: 140, c: "#04071f", w: 1.1, count: 45 },
    { xMin: 390, xMax: 520, c: "#060c33", w: 1.0, count: 45 },
    { xMin: 830, xMax: 950, c: "#070e3b", w: 1.0, count: 45 }
  ];

  for (let vs of velvetStrips) {
    brush.set("velvet_nap", vs.c, vs.w);
    for (let i = 0; i < vs.count; i++) {
      let x = random(vs.xMin, vs.xMax);
      let y1 = random(-10, 980);
      let len = random(140, 340);
      let drift = random(-6, 6);
      brush.line(x, y1, x + drift, Math.min(1210, y1 + len));
    }
  }

  // Fine ultramarine stipple grain for velvet sheen
  brush.set("spray", "#2442eb", 0.9);
  for (let i = 0; i < 38; i++) {
    let x = random(520, 960);
    let y = random(380, 1060);
    brush.line(x, y, x + random(-15, 15), y + random(50, 130));
  }
}

