function drawTheatricalStageGlow() {
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.3);

  // Subtle royal blue-violet & magenta-ultramarine spotlight aura where red candy radiates
  const halos = [
