// ============================================================================
// 3. CANDY-DIPPED WOODEN STICK
// ============================================================================
function drawCandyAppleStick() {
  // Stick emerges from top cleft (682, 575) angling up-left to (516, 128)
  const bx = 684, by = 578; // base inside cleft
  const tx = 516, ty = 126; // top tip of stick
  const dx = tx - bx, dy = ty - by;
  const len = Math.hypot(dx, dy);
  const nx = -dy / len, ny = dx / len; // normal pointing up-right

  function stickPt(t, offsetNorm) {
    // Taper slightly at very top
    let wScale = t > 0.93 ? 1.0 - (t - 0.93) * 3.5 : 1.0;
    return [
      bx + dx * t + nx * offsetNorm * wScale,
      by + dy * t + ny * offsetNorm * wScale
    ];
  }

  brush.noStroke();
  brush.noFill();

  // 1. Opaque high-chroma base wash for the stick (no muddy browns: pure saffron, amber, magenta-violet)
  brush.wash("#ffb700", 250);
  let fullStick = [
    stickPt(0.0, -15), stickPt(0.5, -14.5), stickPt(0.96, -13.5),
    stickPt(1.0, -5), stickPt(1.0, 6),
    stickPt(0.96, 14), stickPt(0.5, 15), stickPt(0.0, 16)
  ];
  drawClosedShape(fullStick, 0.15);

  // Lit left half in glowing canary-gold
  brush.wash("#ffe63b", 235);
  let litStick = [
    stickPt(0.0, -15), stickPt(0.5, -14.5), stickPt(0.97, -13.5),
    stickPt(1.0, -3), stickPt(0.97, -2), stickPt(0.5, -2), stickPt(0.0, -2)
  ];
  drawClosedShape(litStick, 0.12);

  // Right shadow half in rich amber-crimson & royal violet
  brush.wash("#9e004f", 215);
  let shadStick = [
    stickPt(0.0, 2), stickPt(0.5, 1.5), stickPt(0.97, 1.5),
    stickPt(1.0, 6), stickPt(0.96, 14), stickPt(0.5, 15), stickPt(0.0, 16)
  ];
  drawClosedShape(shadStick, 0.12);
  brush.noWash();

  // 2. Watercolour glazes along the stick
  brush.fillBleed(0.16, "in");
  brush.fillTexture(0.5, 0.4);

  // Warm orange-scarlet core turn
  brush.fill("#ff4800", 135);
  drawClosedShape([
    stickPt(0.0, -5), stickPt(0.97, -4), stickPt(0.97, 5), stickPt(0.0, 6)
  ], 0.15);

  // Deep carmine-violet shadow glaze along right side
  brush.fill("#520038", 155);
  drawClosedShape([
    stickPt(0.0, 5), stickPt(0.96, 4), stickPt(0.96, 13.5), stickPt(0.0, 15.5)
  ], 0.15);

  // Hot cerise rim bounce along the extreme right edge of the stick
  brush.fill("#ff0066", 150);
  drawClosedShape([
    stickPt(0.12, 10), stickPt(0.95, 9.5), stickPt(0.95, 14), stickPt(0.12, 15.5)
  ], 0.15);

  // 3. Creeping Molten Candy Collar at the base of the stick (t = 0.0 to 0.24)
  brush.fill("#b80028", 210);
  drawClosedShape([
    stickPt(0.0, -18), stickPt(0.16, -16), stickPt(0.23, -8),
    stickPt(0.20, 4), stickPt(0.25, 15), stickPt(0.14, 17), stickPt(0.0, 19)
  ], 0.35);

  brush.fill("#ff0055", 175);
  drawClosedShape([
    stickPt(0.0, -17), stickPt(0.19, -15), stickPt(0.22, -6), stickPt(0.0, -4)
  ], 0.3);
  brush.noFill();

  // 4. Crisp wood grain & theatrical edge highlights on stick
  brush.set("cpencil", "#ff7700", 0.85);
  for (let i = 0; i < 14; i++) {
    let f = map(i, 0, 13, -12, 4);
    let t1 = random(0.18, 0.35);
    let t2 = random(0.65, 0.96);
    let p1 = stickPt(t1, f);
    let p2 = stickPt(t2, f + random(-1.5, 1.5));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  brush.set("rotring", "#3d0024", 0.85);
  for (let i = 0; i < 10; i++) {
    let f = map(i, 0, 9, 3, 13);
    let p1 = stickPt(random(0.15, 0.3), f);
    let p2 = stickPt(random(0.7, 0.97), f);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Chamfered top end definition
  brush.set("rotring", "#ffe600", 1.1);
  let topEll = [
    stickPt(0.96, -13.5), stickPt(1.0, -5), stickPt(1.0, 6),
    stickPt(0.96, 14), stickPt(0.935, 4), stickPt(0.935, -6)
  ];
  drawClosedShape(topEll, 0.3);

  // Razor-sharp canary-white left rim & hot cerise right rim on stick
  brush.set("sugar_pen", "#ffffb3", 1.15);
  let pL1 = stickPt(0.18, -14.2), pL2 = stickPt(0.96, -13.2);
  brush.line(pL1[0], pL1[1], pL2[0], pL2[1]);

  brush.set("sugar_pen", "#ff2a85", 1.05);
  let pR1 = stickPt(0.22, 14.5), pR2 = stickPt(0.96, 13.5);
  brush.line(pR1[0], pR1[1], pR2[0], pR2[1]);

  // Glossy white specular streak on the candy collar creeping up the stick
  brush.set("sugar_pen", "#ffffff", 1.25);
  let sc1 = stickPt(0.04, -10), sc2 = stickPt(0.12, -9), sc3 = stickPt(0.20, -6);
  brush.spline([[sc1[0], sc1[1], 0.8], [sc2[0], sc2[1], 1.3], [sc3[0], sc3[1], 0.5]], 0.4);
}

// ============================================================================
// 4. OPAQUE LUMINOUS UNDER-WASHES FOR APPLE & SUGAR DRIPS
// ============================================================================
function drawAppleOpaqueUnderpainting() {
  brush.noStroke();
  brush.noFill();

  // Build outer apple contour (72 vertices for silky hyperreal smoothness)
  let outerApplePts = [];
  for (let deg = 0; deg < 360; deg += 5) {
    outerApplePts.push(getAppleContourPt(deg, 1.0, 1.0, 0));
  }

  let collarPts = getSugarCollarPts();
  let drip1Pts = getPrimaryDripPts(0, 0, 1.0);
  let drip2Pts = getSecondaryDripPts(0, 0, 1.0);

  // Layer 4A: Luminous warm rose-ivory foundation so subsequent red watercolours glow like stained glass
  brush.wash("#ffe6ee", 255);
  drawClosedShape(outerApplePts, 0.35);
  drawClosedShape(collarPts, 0.35);
  drawClosedShape(drip1Pts, 0.35);
  drawClosedShape(drip2Pts, 0.35);

  // Layer 4B: Vivid Technicolor Scarlet-Crimson body under-wash
  brush.wash("#ff1238", 235);
  let innerBodyPts = [];
  for (let deg = 0; deg < 360; deg += 6) {
    innerBodyPts.push(getAppleContourPt(deg, 0.985, 0.985, -2));
  }
  drawClosedShape(innerBodyPts, 0.35);
  drawClosedShape(collarPts, 0.35);
  drawClosedShape(getPrimaryDripPts(0, 0, 0.92), 0.35);
  drawClosedShape(getSecondaryDripPts(0, 0, 0.92), 0.35);

  // Layer 4C: Hot Cerise under-wash along the left and right outer rims
  brush.wash("#ff247c", 230);
  let leftRimPatch = buildSurfacePatch([
    [-0.99, -0.45], [-0.76, -0.42], [-0.72, 0.0], [-0.76, 0.55],
    [-0.92, 0.82], [-0.99, 0.55], [-1.0, 0.0]
  ]);
  let rightRimPatch = buildSurfacePatch([
    [0.68, -0.72], [0.96, -0.58], [1.0, 0.0], [0.96, 0.62],
    [0.72, 0.78], [0.76, 0.15], [0.74, -0.35]
  ]);
  drawClosedShape(leftRimPatch, 0.4);
  drawClosedShape(rightRimPatch, 0.4);

  // Layer 4D: Fiery Tangerine-Scarlet subsurface caustic glow in lower-left belly
  brush.wash("#ff4400", 210);
  let causticPatch = buildSurfacePatch([
    [-0.72, 0.18], [-0.18, 0.25], [-0.08, 0.68],
    [-0.38, 0.88], [-0.76, 0.78], [-0.84, 0.48]
  ]);
  drawClosedShape(causticPatch, 0.45);

  // Layer 4E: Deep Blood Carmine core shadow foundation in center-right belly
  brush.wash("#730019", 225);
  let coreShadowPatch = buildSurfacePatch([
    [-0.18, -0.25], [0.58, -0.32], [0.74, 0.12],
    [0.58, 0.62], [0.05, 0.64], [-0.28, 0.22]
  ]);
  drawClosedShape(coreShadowPatch, 0.45);

  // Layer 4F: Bright canary-ivory reserve under the upper-left mirror reflection zone
  brush.wash("#fff9d6", 245);
  let mirrorReserve = buildSurfacePatch([
    [-0.84, -0.66], [-0.14, -0.68], [-0.10, 0.08],
    [-0.48, 0.14], [-0.86, 0.04], [-0.92, -0.32]
  ]);
  drawClosedShape(mirrorReserve, 0.35);

  brush.noWash();
}

