// ============================================================================
// 6. MIRROR HIGHLIGHTS: STRIPED FAIRGROUND AWNING IN EMERALD & CANARY YELLOW
// ============================================================================
function drawFairgroundAwningReflections() {
  // -------------------------------------------------------------------------
  // A. MAIN UPPER-LEFT DOME REFLECTION (8 Warped Stripes + Scalloped Valance)
  // -------------------------------------------------------------------------
  const numStripes = 8;
  const uStart = -0.86;
  const uEnd = -0.10;
  const vTopBase = -0.68;
  const vBotBase = 0.12;

  // 1. Crisp dark carmine-emerald contrast frame immediately around the mirror highlight
  brush.noStroke();
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.4, 0.5);
  brush.fill("#4a0012", 140);
  drawClosedShape(buildSurfacePatch([
    [uStart - 0.04, vTopBase - 0.03],
    [(uStart + uEnd) / 2, vTopBase - 0.08],
    [uEnd + 0.04, vTopBase - 0.02],
    [uEnd + 0.05, vBotBase + 0.08],
    [(uStart + uEnd) / 2, vBotBase + 0.12],
    [uStart - 0.05, vBotBase + 0.06]
  ]), 0.35);
  brush.noFill();

  // Helper to compute warped (u, v) on the apple dome for stripe index s in [0..numStripes], t in [0..1] (top to bottom)
  function awningUV(sFrac, tFrac) {
    let u = uStart + (uEnd - uStart) * sFrac;
    // Perspective fan: stripes converge slightly toward the top cleft and flare at the cheek
    let fan = 1.0 + 0.16 * (tFrac - 0.35);
    let uCenter = (uStart + uEnd) * 0.5;
    let uWarped = uCenter + (u - uCenter) * fan;

    // Arch across the dome
    let arch = -0.06 * Math.sin(sFrac * Math.PI);
    let v = vTopBase + (vBotBase - vTopBase) * tFrac + arch;
    return [uWarped, v];
  }

  // Collect stripe geometries by color (Canary vs Emerald) to batch washes & fills
  let canaryStripes = [];
  let emeraldStripes = [];
  let canarySpecSpots = [];
  let emeraldSpecSpots = [];
  let bulbPositions = [];

  for (let i = 0; i < numStripes; i++) {
    let s0 = i / numStripes;
    let s1 = (i + 1) / numStripes;
    let sMid = (s0 + s1) * 0.5;

    // Build warped stripe polygon with a curved scalloped bottom edge!
    let uvPoly = [
      awningUV(s0, 0.0),
      awningUV(sMid, -0.015),
      awningUV(s1, 0.0),
      awningUV(s1, 0.45),
      awningUV(s1, 0.88),
      // Scalloped fairground valance tab at bottom of stripe (t goes down to 1.06 at center)
      awningUV(s0 + (s1 - s0) * 0.78, 1.01),
      awningUV(sMid, 1.07),
      awningUV(s0 + (s1 - s0) * 0.22, 1.01),
      awningUV(s0, 0.88),
      awningUV(s0, 0.45)
    ];

    // Inner bright specular core of each stripe (around t = 0.25..0.68)
    let uvSpec = [
      awningUV(s0 + (s1 - s0) * 0.15, 0.22),
      awningUV(s1 - (s1 - s0) * 0.15, 0.22),
      awningUV(s1 - (s1 - s0) * 0.15, 0.68),
      awningUV(s0 + (s1 - s0) * 0.15, 0.68)
    ];

    if (i % 2 === 0) {
      canaryStripes.push(buildSurfacePatch(uvPoly));
      canarySpecSpots.push(buildSurfacePatch(uvSpec));
    } else {
      emeraldStripes.push(buildSurfacePatch(uvPoly));
      emeraldSpecSpots.push(buildSurfacePatch(uvSpec));
    }

    // Fairground festoon bulb reflection tucked right under each scallop!
    bulbPositions.push(getAppleSurfacePt(...awningUV(sMid, 1.15)));
  }

  // 2. Opaque Wash Pass for Canary Yellow Stripes (#ffe600 & #fff780)
  brush.noStroke();
  brush.wash("#ffe600", 245);
  for (let poly of canaryStripes) {
    drawClosedShape(poly, 0.25);
  }
  brush.wash("#fff9a6", 240);
  for (let poly of canarySpecSpots) {
    drawClosedShape(poly, 0.3);
  }

  // 3. Opaque Wash Pass for Emerald Green Stripes (#00b353 & #1aff80)
  brush.wash("#00ad50", 245);
  for (let poly of emeraldStripes) {
    drawClosedShape(poly, 0.25);
  }
  brush.wash("#26ff8c", 220);
  for (let poly of emeraldSpecSpots) {
    drawClosedShape(poly, 0.3);
  }
  brush.noWash();

  // 4. Watercolour Glaze Pass over Awning Stripes (integrating reflection into glossy dome)
  brush.fillBleed(0.10, "in");
  brush.fillTexture(0.42, 0.45);

  brush.fill("#ffcc00", 115);
  for (let poly of canaryStripes) {
    drawClosedShape(poly, 0.25);
  }

  brush.fill("#007a37", 125);
  for (let poly of emeraldStripes) {
    drawClosedShape(poly, 0.25);
  }

  // Dazzling white-canary specular hot-band across the middle ridge of the reflection
  brush.fill("#ffffff", 165);
  drawClosedShape(buildSurfacePatch([
    awningUV(0.08, 0.30),
    awningUV(0.88, 0.28),
    awningUV(0.85, 0.50),
    awningUV(0.06, 0.52)
  ]), 0.35);
  brush.noFill();

  // 5. Crisp Pen-Defined Stripe Separators & Scalloped Valance Trim
  for (let i = 0; i <= numStripes; i++) {
    let s = i / numStripes;
    let p1 = getAppleSurfacePt(...awningUV(s, 0.0));
    let p2 = getAppleSurfacePt(...awningUV(s, 0.45));
    let p3 = getAppleSurfacePt(...awningUV(s, 0.88));
    brush.set("sugar_pen", "#00662b", 0.9);
    brush.spline([[p1[0], p1[1], 0.6], [p2[0], p2[1], 1.1], [p3[0], p3[1], 0.8]], 0.4);
  }

  // Scallop bottom trim in crisp canary-white and crimson-carmine shadow edge
  for (let i = 0; i < numStripes; i++) {
    let s0 = i / numStripes;
    let s1 = (i + 1) / numStripes;
    let sMid = (s0 + s1) * 0.5;
    let pL = getAppleSurfacePt(...awningUV(s0, 0.88));
    let pM = getAppleSurfacePt(...awningUV(sMid, 1.08));
    let pR = getAppleSurfacePt(...awningUV(s1, 0.88));

    brush.set("sugar_pen", "#7a001e", 1.15);
    brush.spline([[pL[0], pL[1] + 3, 0.8], [pM[0], pM[1] + 3, 1.2], [pR[0], pR[1] + 3, 0.8]], 0.45);

    brush.set("sugar_pen", i % 2 === 0 ? "#ffffff" : "#80ffbf", 1.1);
    brush.spline([[pL[0], pL[1], 0.8], [pM[0], pM[1], 1.2], [pR[0], pR[1], 0.8]], 0.45);
  }

  // Glowing fairground festoon bulbs under the scalloped awning reflection
  brush.noStroke();
  brush.wash("#fff275", 245);
  for (let bp of bulbPositions) {
    brush.circle(bp[0], bp[1], 4.5, 0.15);
  }
  brush.wash("#ffffff", 255);
  for (let bp of bulbPositions) {
    brush.circle(bp[0] - 0.8, bp[1] - 0.8, 2.4, 0.1);
  }
  brush.noWash();

  // -------------------------------------------------------------------------
  // B. SECONDARY UPPER-RIGHT SHOULDER REFLECTION (4 Warped Stripes)
  // -------------------------------------------------------------------------
  const rStripes = 4;
  function rightAwningUV(sFrac, tFrac) {
    let u = 0.24 + 0.50 * sFrac;
    let v = -0.62 + 0.42 * tFrac - 0.04 * Math.sin(sFrac * Math.PI);
    return [u, v];
  }

  let rCanary = [];
  let rEmerald = [];
  for (let i = 0; i < rStripes; i++) {
    let s0 = i / rStripes;
    let s1 = (i + 1) / rStripes;
    let sMid = (s0 + s1) * 0.5;
    let poly = buildSurfacePatch([
      rightAwningUV(s0, 0.0),
      rightAwningUV(s1, 0.0),
      rightAwningUV(s1, 0.85),
      rightAwningUV(sMid, 1.05),
      rightAwningUV(s0, 0.85)
    ]);
    if (i % 2 === 0) rCanary.push(poly);
    else rEmerald.push(poly);
  }

  brush.noStroke();
  brush.wash("#ffe600", 225);
  for (let p of rCanary) drawClosedShape(p, 0.28);

  brush.wash("#00b853", 220);
  for (let p of rEmerald) drawClosedShape(p, 0.28);
  brush.noWash();

  // Glaze right reflection slightly with hot cerise so it sits in the secondary rim zone
  brush.fillBleed(0.12, "in");
  brush.fill("#ff0066", 65);
  drawClosedShape(buildSurfacePatch([
    rightAwningUV(0.0, 0.0), rightAwningUV(1.0, 0.0),
    rightAwningUV(1.0, 1.0), rightAwningUV(0.0, 1.0)
  ]), 0.3);
  brush.noFill();

  // Crisp highlight streak across the upper-right reflection
  brush.set("sugar_pen", "#ffffcc", 1.15);
  let rp1 = getAppleSurfacePt(...rightAwningUV(0.08, 0.35));
  let rp2 = getAppleSurfacePt(...rightAwningUV(0.50, 0.30));
  let rp3 = getAppleSurfacePt(...rightAwningUV(0.92, 0.38));
  brush.spline([[rp1[0], rp1[1], 0.6], [rp2[0], rp2[1], 1.3], [rp3[0], rp3[1], 0.6]], 0.4);
}

