    brush.noWash();
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(1964);
  noiseSeed(1964);
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // =========================================================================
  // PALETTE — CONFECTIONERY WARM PASTELS & HYPERREAL ARCHITECTURAL INK
  // =========================================================================
  const PAL = {
    paper: "#FDF8EE",
    paperWarm: "#F9EFE0",

    // Butter-yellow upper wall & cream moldings
    wallYellow: "#FAEBBE",
    wallYellowDeep: "#F4DF9E",
    wallStripe: "#FFF6DA",
    wallFloret: "#E5C67B",
    moldingLight: "#FFF9EB",
    moldingMid: "#F3E2BE",
    moldingShadow: "#DFC89A",

    // Salmon-pink / shell-pink tiles & grout
    tileBase1: "#F4B8A8",
    tileBase2: "#F7C3B5",
    tileBase3: "#F1ADA0",
    tileBase4: "#F8CBC0",
    tileBase5: "#EDA394",
    tileCove: "#E89888",
    tileBullnose: "#EE9F8F",
    tileHighlight: "#FFF5F0",
    tileShade: "#DC8A7A",
    groutLight: "#FAF0EA",
    groutInk: "#B87A6D",

    // Floor mosaic
    floorCream: "#FAF0D6",
    floorPink: "#F0B0A0",
    floorMint: "#C8E2CF",

    // Round mirror & powder-blue door reflection
    doorBlue: "#B2D2E2",
    doorBlueMid: "#9EC2D5",
    doorBlueDark: "#85AEC4",
    doorBlueLight: "#DCF0FA",
    transomSky: "#D6ECF7",

    // Mint / pistachio porcelain pedestal sink
    mintBase: "#C2E3CF",
    mintLight: "#D6F1E0",
    mintBright: "#F0FCF5",
    mintMid: "#B0D6BF",
    mintShadow: "#99C2AA",
    mintDeep: "#84B097",
    waterRing: "#89B69D",
    waterHighlight: "#FFFFFF",

    // Twin brass taps, mirror frame & sconces
    brassBase: "#E8C36B",
    brassLight: "#FFF6CC",
    brassMid: "#D1A044",
    brassDark: "#9A6B22",
    brassInk: "#5E4016",

    // Towels & tiny wrapped soap
    towelCream: "#FDF4E4",
    towelShadow: "#ECDCC2",
    soapWrap: "#FCF3DC",
    soapBand: "#F2AAA0",

    // Crisp technical pen edges
    inkDark: "#4A332C",
    inkMid: "#6E4E44",
    inkSoft: "#8C675C",
    inkMint: "#4E6E5D",
    inkBlue: "#4E6978",
    white: "#FFFFFF"
  };

  // Base warm paper ground
  background(PAL.paper);

  // =========================================================================
  // LOW-LEVEL DRAWING HELPERS (CRISP WATERCOLOUR + FINE PEN EDGES)
  // =========================================================================
  function fillPoly(pts, col, alpha = 170, bleed = 0.02, tex = 0.22, border = 0.15) {
    if (!pts || pts.length < 3) return;
    brush.noStroke();
    brush.fill(col, alpha);
    brush.fillBleed(bleed, "in");
    brush.fillTexture(tex, border);
    brush.beginShape(0);
    for (let i = 0; i < pts.length; i++) {
      brush.vertex(pts[i][0], pts[i][1]);
    }
    brush.endShape(true);
    brush.noFill();
  }

  function washPoly(pts, col, alpha = 220) {
    if (!pts || pts.length < 3) return;
    brush.noStroke();
    brush.wash(col, alpha);
    brush.beginShape(0);
    for (let i = 0; i < pts.length; i++) {
      brush.vertex(pts[i][0], pts[i][1]);
    }
    brush.endShape(true);
    brush.noWash();
  }

  function rectPts(x, y, w, h) {
    return [
      [x, y],
      [x + w, y],
      [x + w, y + h],
      [x, y + h]
    ];
  }

  function fillRect(x, y, w, h, col, alpha = 170, bleed = 0.02, tex = 0.22, border = 0.15) {
    fillPoly(rectPts(x, y, w, h), col, alpha, bleed, tex, border);
  }

  function washRect(x, y, w, h, col, alpha = 220) {
    washPoly(rectPts(x, y, w, h), col, alpha);
  }

  function strokePoly(pts, bName, col, weight = 0.35, closed = true) {
    if (!pts || pts.length < 2) return;
    brush.noFill();
    brush.set(bName, col, weight);
    let n = pts.length;
    for (let i = 0; i < (closed ? n : n - 1); i++) {
      let a = pts[i];
      let b = pts[(i + 1) % n];
      brush.line(a[0], a[1], b[0], b[1]);
    }
    brush.noStroke();
  }

  function strokeRect(x, y, w, h, bName, col, weight = 0.35) {
    strokePoly(rectPts(x, y, w, h), bName, col, weight, true);
  }

  function penLine(x1, y1, x2, y2, col = PAL.inkDark, weight = 0.35, bName = "rotring") {
    brush.noFill();
    brush.set(bName, col, weight);
    brush.line(x1, y1, x2, y2);
    brush.noStroke();
  }

  function circlePts(cx, cy, r, steps = 48) {
    let pts = [];
    for (let i = 0; i < steps; i++) {
      let ang = (i / steps) * 360;
      pts.push([cx + cos(ang) * r, cy + sin(ang) * r]);
    }
    return pts;
  }

  // Clips a rectangle [x1, y1, x2, y2] to lie strictly inside circle (cx, cy, r)
  function clippedMirrorRectPts(x1, y1, x2, y2, cx, cy, r, steps = 16) {
    let xa = max(x1, cx - r + 0.5);
    let xb = min(x2, cx + r - 0.5);
    if (xa >= xb) return [];
    let topPts = [];
    let botPts = [];
    for (let i = 0; i <= steps; i++) {
      let x = lerp(xa, xb, i / steps);
      let dx = x - cx;
      let dy = sqrt(max(0, r * r - dx * dx));
      let cTop = cy - dy;
      let cBot = cy + dy;
      let yt = clampVal(y1, cTop, cBot);
      let yb = clampVal(y2, cTop, cBot);
      topPts.push([x, yt]);
      botPts.push([x, yb]);
    }
    botPts.reverse();
    let poly = topPts.concat(botPts);
    // Check if polygon has non-zero vertical area
    let maxH = 0;
    for (let i = 0; i <= steps; i++) {
      maxH = max(maxH, abs(botPts[steps - i][1] - topPts[i][1]));
    }
    return maxH > 0.5 ? poly : [];
  }

  function clampVal(v, lo, hi) {
    return max(lo, min(hi, v));
  }

  // Proscenium bounds
  const PX1 = 56;
  const PY1 = 56;
  const PX2 = 1144;
  const PY2 = 1144;
  const PW = PX2 - PX1; // 1088
  const CX = 600;

  // =========================================================================
  // 1. UPPER WALL: BUTTER-YELLOW WALLPAPER, CROWN MOLDING & DADO RAIL
  // =========================================================================
  function drawUpperWall() {
    const wallTop = 104;
    const wallBot = 462;
    const wallH = wallBot - wallTop;

    // Base warm butter-yellow watercolor washes
    washRect(PX1, PY1, PW, 438, PAL.wallYellow, 185);
    fillRect(PX1, wallTop, PW, wallH, PAL.wallYellow, 150, 0.03, 0.3, 0.18);
    fillRect(PX1 + 40, wallTop + 10, PW - 80, wallH - 20, PAL.wallYellowDeep, 55, 0.04, 0.25, 0.12);

    // Symmetrical hotel Regency vertical stripes & delicate floral-diamond pin-motifs
    const stripeStep = 48;
    for (let d = 0; d <= 520; d += stripeStep) {
      let xs = d === 0 ? [CX] : [CX - d, CX + d];
      for (let x of xs) {
        if (x < PX1 + 10 || x > PX2 - 10) continue;
        // Soft cream-ivory ribbon stripe
        washRect(x - 7, wallTop + 2, 14, wallH - 4, PAL.wallStripe, 145);
        penLine(x - 7, wallTop + 2, x - 7, wallBot - 2, PAL.moldingShadow, 0.22, "2H");
        penLine(x + 7, wallTop + 2, x + 7, wallBot - 2, PAL.moldingShadow, 0.22, "2H");
        penLine(x, wallTop + 2, x, wallBot - 2, PAL.wallFloret, 0.18, "2H");
      }
    }

    // Tiny diamond florets between stripes
    for (let d = 24; d <= 510; d += stripeStep) {
      let xs = [CX - d, CX + d];
      for (let x of xs) {
        if (x < PX1 + 16 || x > PX2 - 16) continue;
        for (let y = wallTop + 32; y < wallBot - 20; y += 56) {
          let r = 4.5;
          penLine(x - r, y, x, y - r, PAL.wallFloret, 0.25, "rotring");
          penLine(x, y - r, x + r, y, PAL.wallFloret, 0.25, "rotring");
          penLine(x + r, y, x, y + r, PAL.wallFloret, 0.25, "rotring");
          penLine(x, y + r, x - r, y, PAL.wallFloret, 0.25, "rotring");
          penLine(x - 1.5, y, x + 1.5, y, PAL.inkSoft, 0.22, "rotring");
          penLine(x, y - 1.5, x, y + 1.5, PAL.inkSoft, 0.22, "rotring");
        }
      }
    }

    // Stepped Crown Molding (Y: 56 to 104)
    washRect(PX1, 56, PW, 48, PAL.moldingLight, 230);
    fillRect(PX1, 56, PW, 18, PAL.moldingMid, 140, 0.01, 0.18, 0.12);
    fillRect(PX1, 88, PW, 16, PAL.moldingMid, 150, 0.01, 0.18, 0.12);
    washRect(PX1, 74, PW, 8, PAL.white, 210);
    washRect(PX1, 98, PW, 6, PAL.moldingShadow, 130);

    const crownLines = [64, 74, 82, 88, 98, 104];
    for (let ly of crownLines) {
      penLine(PX1, ly, PX2, ly, PAL.inkMid, ly === 104 ? 0.45 : 0.28, "rotring");
    }
    // Dentil molding ticks along crown
    for (let x = PX1 + 8; x < PX2 - 4; x += 16) {
      washRect(x, 88, 8, 9, PAL.moldingShadow, 110);
      strokeRect(x, 88, 8, 9, "rotring", PAL.inkSoft, 0.2);
    }

    // Dado Rail / Ceramic Bullnose Cap Molding (Y: 462 to 492)
    washRect(PX1, 462, PW, 30, PAL.tileBullnose, 215);
    fillRect(PX1, 462, PW, 30, PAL.tileBase1, 160, 0.02, 0.22, 0.15);
    // Bright glazed bullnose top highlight
    washRect(PX1, 464, PW, 7, PAL.tileHighlight, 225);
    washRect(PX1, 484, PW, 8, PAL.tileShade, 150);

    // Bullnose tile joints (aligned with 64px module centered on CX=600)
    for (let x = PX1 + 64; x < PX2; x += 64) {
      penLine(x - 1.2, 462, x - 1.2, 492, PAL.groutLight, 0.45, "cpencil");
      penLine(x, 462, x, 492, PAL.groutInk, 0.28, "rotring");
    }
    penLine(PX1, 462, PX2, 462, PAL.inkDark, 0.48, "rotring");
    penLine(PX1, 471, PX2, 471, PAL.groutInk, 0.24, "rotring");
    penLine(PX1, 484, PX2, 484, PAL.groutInk, 0.28, "rotring");
    penLine(PX1, 492, PX2, 492, PAL.inkDark, 0.48, "rotring");
  }

  // =========================================================================
  // 2. SALMON-PINK TILED WALL WITH HYPERREAL GROUT & GLAZE SHEEN
  // =========================================================================
  function drawTiledWall() {
    const tileAreaTop = 492;
    const tileAreaBot = 1012;
    const tileAreaH = tileAreaBot - tileAreaTop;

    // 1. Smooth layered salmon-pink watercolor ground across the whole tile zone
    washRect(PX1, tileAreaTop, PW, tileAreaH, PAL.tileBase1, 225);
    fillRect(PX1, tileAreaTop, PW, tileAreaH, PAL.tileBase2, 165, 0.03, 0.32, 0.2);
    fillRect(PX1, tileAreaTop + 120, PW, tileAreaH - 160, PAL.tileBase1, 110, 0.03, 0.28, 0.18);

    // 2. Decorative Pencil-Liner Tile Strip (Y: 492 to 516, height 24px, width 32px)
    const linerY = 492;
    const linerH = 24;
    for (let col = 0; col < 34; col++) {
      let tx = PX1 + col * 32;
      let isAlt = col % 2 === 0;
      washRect(tx + 1.5, linerY + 1.5, 29, linerH - 3, isAlt ? PAL.tileBase4 : PAL.moldingLight, 190);
      // Glaze highlight along top & left
      penLine(tx + 2.5, linerY + 3, tx + 29, linerY + 3, PAL.white, 0.45, "cpencil");
      strokeRect(tx + 1.2, linerY + 1.2, 29.6, linerH - 2.4, "rotring", PAL.groutInk, 0.25);
    }
    penLine(PX1, 516, PX2, 516, PAL.inkDark, 0.42, "rotring");

    // 3. Main Subway Tile Grid (Y: 516 to 964 -> 14 rows of 32px height, 64px width)
    // 1088 / 64 = 17 tiles per row -> 100% symmetrical around CX = 600!
    const gridTop = 516;
    const rows = 14;
    const rowH = 32;
    const colW = 64;

    // Batch individual tile watercolor variations symmetrically or naturalistically
    const tileShades = [PAL.tileBase1, PAL.tileBase2, PAL.tileBase3, PAL.tileBase4, PAL.tileBase5];
    for (let r = 0; r < rows; r++) {
      let ty = gridTop + r * rowH;
      let isOddRow = r % 2 === 1;
      let startX = isOddRow ? PX1 - 32 : PX1;
      let numCols = isOddRow ? 18 : 17;

      for (let c = 0; c < numCols; c++) {
        let rawX = startX + c * colW;
        let x1 = max(PX1, rawX);
        let x2 = min(PX2, rawX + colW);
        let w = x2 - x1;
        if (w <= 4) continue;

        // Deterministic subtle shade shift per tile
        let idx = (r * 7 + c * 3 + (r % 3)) % tileShades.length;
        let shade = tileShades[idx];
        washRect(x1 + 1.6, ty + 1.6, w - 3.2, rowH - 3.2, shade, 165);

        // Occasional extra watercolor glaze bloom on select tiles
        if ((r + c) % 4 === 0) {
          fillRect(x1 + 2, ty + 2, w - 4, rowH - 4, shade, 95, 0.01, 0.22, 0.12);
        }
      }
    }

    // Horizontal grout channels (warm ivory core + dual fine pen edges for recessed mortar look)
    for (let r = 0; r <= rows; r++) {
      let gy = gridTop + r * rowH;
      penLine(PX1, gy, PX2, gy, PAL.groutLight, 0.85, "marker");
      penLine(PX1, gy - 1.1, PX2, gy - 1.1, PAL.groutInk, 0.24, "rotring");
      penLine(PX1, gy + 1.1, PX2, gy + 1.1, PAL.groutInk, 0.28, "rotring");
    }

    // Per-tile vertical grout joints, ceramic top/left specular bevels & bottom/right glaze shadow
    for (let r = 0; r < rows; r++) {
      let ty = gridTop + r * rowH;
      let isOddRow = r % 2 === 1;
      let startX = isOddRow ? PX1 - 32 : PX1;
      let numCols = isOddRow ? 18 : 17;

      for (let c = 0; c < numCols; c++) {
        let rawX = startX + c * colW;
        let x1 = max(PX1, rawX);
        let x2 = min(PX2, rawX + colW);
        let w = x2 - x1;
        if (w <= 4) continue;

        // Vertical grout joint at right edge of tile
        if (x2 < PX2 - 1) {
          penLine(x2, ty + 1.2, x2, ty + rowH - 1.2, PAL.groutLight, 0.75, "marker");
          penLine(x2 - 1.1, ty + 1.2, x2 - 1.1, ty + rowH - 1.2, PAL.groutInk, 0.24, "rotring");
          penLine(x2 + 1.1, ty + 1.2, x2 + 1.1, ty + rowH - 1.2, PAL.groutInk, 0.24, "rotring");
        }

        // Top & left ceramic cushion-edge highlight
        if (w > 12) {
          penLine(x1 + 3.5, ty + 3.2, x2 - 3.5, ty + 3.2, PAL.tileHighlight, 0.55, "cpencil");
          penLine(x1 + 3.2, ty + 3.5, x1 + 3.2, ty + rowH - 4, PAL.tileHighlight, 0.4, "cpencil");
          // Bottom glaze pooling line
          penLine(x1 + 3.5, ty + rowH - 2.8, x2 - 3.5, ty + rowH - 2.8, PAL.tileShade, 0.35, "2H");
        }

        // Subtle diagonal ceramic reflection streak on select tiles
        if ((r * 5 + c) % 6 === 0 && w > 36) {
          penLine(x1 + 14, ty + rowH - 5, x1 + 28, ty + 5, PAL.white, 0.45, "cpencil");
          penLine(x1 + 20, ty + rowH - 5, x1 + 34, ty + 5, PAL.white, 0.3, "cpencil");
        }
      }
    }

    // 4. Sanitary Cove Baseboard Tiles (Y: 964 to 1012, height 48px, width 64px)
    const baseTop = 964;
    const baseH = 48;
    washRect(PX1, baseTop, PW, baseH, PAL.tileCove, 225);
    fillRect(PX1, baseTop, PW, baseH, PAL.tileBase5, 155, 0.02, 0.24, 0.15);
    // Top lip & bottom curved cove highlight
    washRect(PX1, baseTop + 2, PW, 6, PAL.tileHighlight, 210);
    washRect(PX1, baseTop + 34, PW, 7, PAL.tileHighlight, 180);
    washRect(PX1, baseTop + 42, PW, 6, PAL.tileShade, 165);

    for (let c = 0; c < 17; c++) {
      let bx = PX1 + c * 64;
      if (c > 0) {
        penLine(bx, baseTop, bx, baseTop + baseH, PAL.groutLight, 0.7, "marker");
        penLine(bx - 1, baseTop, bx - 1, baseTop + baseH, PAL.groutInk, 0.26, "rotring");
        penLine(bx + 1, baseTop, bx + 1, baseTop + baseH, PAL.groutInk, 0.26, "rotring");
      }
    }
    penLine(PX1, baseTop, PX2, baseTop, PAL.inkDark, 0.45, "rotring");
    penLine(PX1, baseTop + 8, PX2, baseTop + 8, PAL.groutInk, 0.25, "rotring");
    penLine(PX1, baseTop + 35, PX2, baseTop + 35, PAL.groutInk, 0.22, "2H");
    penLine(PX1, tileAreaBot, PX2, tileAreaBot, PAL.inkDark, 0.55, "rotring");
  }

  // =========================================================================
  // 3. PROSCENIUM HOTEL FLOOR: PASTEL MOSAIC TILES (Y: 1012 to 1144)
  // =========================================================================
  function drawFloor() {
    const fTop = 1012;
    const fBot = 1144;
    const fH = fBot - fTop;

    washRect(PX1, fTop, PW, fH, PAL.floorCream, 235);
    fillRect(PX1, fTop, PW, fH, PAL.floorCream, 150, 0.02, 0.25, 0.15);

    // Orthographic hotel mosaic tile rows with subtle frontal foreshortening
    const rowY = [1012, 1028, 1046, 1066, 1089, 1115, 1144];
    const colStep = 32; // 34 columns across 1088px -> symmetrical!

    for (let r = 0; r < rowY.length - 1; r++) {
      let y1 = rowY[r];
      let y2 = rowY[r + 1];
      let rh = y2 - y1;

      for (let c = 0; c < 34; c++) {
        let x1 = PX1 + c * colStep;
        // Symmetrical mosaic border & checkerboard pattern
        let distFromCenter = abs(c - 16.5);
        let colTile = PAL.floorCream;
        if (r === 1 || r === 4) {
          colTile = (c % 2 === 0) ? PAL.floorPink : PAL.floorCream;
        } else if ((r + c) % 2 === 0) {
          colTile = (distFromCenter < 6.5) ? PAL.floorMint : PAL.floorPink;
        } else {
          colTile = PAL.floorCream;
        }

        washRect(x1 + 1.2, y1 + 1.2, colStep - 2.4, rh - 2.4, colTile, 195);
        penLine(x1 + 2.5, y1 + 2.5, x1 + colStep - 2.5, y1 + 2.5, PAL.white, 0.35, "cpencil");
      }

      penLine(PX1, y2, PX2, y2, PAL.groutInk, 0.28, "rotring");
    }

    // Vertical floor grout lines radiating very subtly from central axis for dollhouse depth
    for (let c = 1; c < 34; c++) {
      let x = PX1 + c * colStep;
      penLine(x, fTop, x, fBot, PAL.groutInk, 0.25, "rotring");
    }

    // Soft frontal reflection & contact shadow under the sink pedestal
    fillRect(465, 1052, 270, 34, PAL.tileShade, 55, 0.05, 0.2, 0.1);
  }

  // =========================================================================
  // 4. ROUND MIRROR REFLECTING POWDER-BLUE DOOR (DEAD-CENTRE)
  // =========================================================================
  function drawMirrorAndReflection() {
    const mCX = CX;
    const mCY = 294;
    const rOuter = 178;
    const rMid = 165;
    const rInner = 158;
    const rGlass = 148;

    // 1. Opaque circular wash to mask the wallpaper behind the mirror
    let outerCircle = circlePts(mCX, mCY, rOuter, 72);
    let glassCircle = circlePts(mCX, mCY, rGlass, 72);
    washPoly(outerCircle, PAL.paper, 255);

    // 2. Brass & Pistachio Enamel Mirror Frame
    fillPoly(outerCircle, PAL.brassBase, 210, 0.02, 0.22, 0.15);
    fillPoly(circlePts(mCX, mCY, rMid, 72), PAL.mintMid, 210, 0.01, 0.18, 0.12);
    fillPoly(circlePts(mCX, mCY, rInner, 72), PAL.brassLight, 220, 0.01, 0.18, 0.12);
    washPoly(glassCircle, PAL.wallYellow, 250);

    // 3. Reflected Opposite Wall inside the Round Mirror (clipped to rGlass)
    // Upper reflected butter-yellow wall
    let refWall = clippedMirrorRectPts(mCX - rGlass, mCY - rGlass, mCX + rGlass, 358, mCX, mCY, rGlass, 28);
    fillPoly(refWall, PAL.wallYellow, 165, 0.02, 0.22, 0.12);

    // Reflected vertical wallpaper stripes on flanking walls
    for (let sx of [474, 726]) {
      let stPts = clippedMirrorRectPts(sx - 5, mCY - rGlass, sx + 5, 352, mCX, mCY, rGlass, 6);
      washPoly(stPts, PAL.wallStripe, 160);
    }

    // Reflected dado rail & lower salmon-pink tiles on flanking walls inside mirror
    let refDado = clippedMirrorRectPts(mCX - rGlass, 352, mCX + rGlass, 366, mCX, mCY, rGlass, 24);
    washPoly(refDado, PAL.tileBullnose, 215);
    let refTiles = clippedMirrorRectPts(mCX - rGlass, 366, mCX + rGlass, mCY + rGlass, mCX, mCY, rGlass, 28);
    fillPoly(refTiles, PAL.tileBase2, 195, 0.02, 0.22, 0.12);

    // Reflected tile grout lines on left and right of door frame
    for (let ty = 384; ty < mCY + rGlass; ty += 20) {
      let dy = ty - mCY;
      if (abs(dy) < rGlass - 2) {
        let halfW = sqrt(rGlass * rGlass - dy * dy);
        penLine(mCX - halfW + 2, ty, 496, ty, PAL.groutInk, 0.22, "rotring");
        penLine(704, ty, mCX + halfW - 2, ty, PAL.groutInk, 0.22, "rotring");
      }
    }
    // Reflected dado horizontal rules
    for (let dyLine of [352, 366]) {
      let dy = dyLine - mCY;
      let halfW = sqrt(rGlass * rGlass - dy * dy);
      penLine(mCX - halfW + 2, dyLine, 496, dyLine, PAL.inkMid, 0.28, "rotring");
      penLine(704, dyLine, mCX + halfW - 2, dyLine, PAL.inkMid, 0.28, "rotring");
    }

    // 4. REFLECTED POWDER-BLUE DOOR & ARCHITRAVE (Dead-centre X: 496 to 704)
    // Outer cream wooden door architrave / casing
    let archOuter = clippedMirrorRectPts(496, 152, 704, mCY + rGlass, mCX, mCY, rGlass, 24);
    washPoly(archOuter, PAL.moldingLight, 240);
    fillPoly(archOuter, PAL.moldingMid, 120, 0.01, 0.18, 0.12);

    let archStep = clippedMirrorRectPts(506, 162, 694, mCY + rGlass, mCX, mCY, rGlass, 22);
    washPoly(archStep, PAL.moldingShadow, 110);

    // Transom window above door (X: 514 to 686, Y: 164 to 198)
    let transomPts = clippedMirrorRectPts(514, 164, 686, 196, mCX, mCY, rGlass, 18);
    washPoly(transomPts, PAL.transomSky, 230);
    fillPoly(transomPts, PAL.doorBlueLight, 140, 0.01, 0.18, 0.12);
    strokePoly(transomPts, "rotring", PAL.inkBlue, 0.32);
    // Transom mullion bars
    penLine(570, 164, 570, 196, PAL.moldingLight, 0.9, "marker");
    penLine(630, 164, 630, 196, PAL.moldingLight, 0.9, "marker");
    penLine(570, 164, 570, 196, PAL.inkBlue, 0.28, "rotring");
    penLine(630, 164, 630, 196, PAL.inkBlue, 0.28, "rotring");

    // Transom gold room numerals "204" in centre pane
    penLine(590, 176, 595, 176, PAL.brassMid, 0.35, "rotring");
    penLine(595, 176, 595, 180, PAL.brassMid, 0.35, "rotring");
    penLine(590, 180, 595, 180, PAL.brassMid, 0.35, "rotring");
    penLine(590, 180, 590, 184, PAL.brassMid, 0.35, "rotring");
    penLine(590, 184, 595, 184, PAL.brassMid, 0.35, "rotring");
    strokeRect(598, 176, 5, 8, "rotring", PAL.brassMid, 0.35);
    penLine(606, 176, 606, 181, PAL.brassMid, 0.35, "rotring");
    penLine(606, 181, 611, 181, PAL.brassMid, 0.35, "rotring");
    penLine(610, 176, 610, 184, PAL.brassMid, 0.35, "rotring");

    // Transom horizontal bar
    let transomBar = clippedMirrorRectPts(508, 196, 692, 206, mCX, mCY, rGlass, 18);
    washPoly(transomBar, PAL.moldingLight, 240);
    strokePoly(transomBar, "rotring", PAL.inkMid, 0.32);

    // Main Powder-Blue Door Leaf (X: 514 to 686, Y: 206 to bottom of mirror)
    let doorLeaf = clippedMirrorRectPts(514, 206, 686, mCY + rGlass, mCX, mCY, rGlass, 24);
    washPoly(doorLeaf, PAL.doorBlue, 240);
    fillPoly(doorLeaf, PAL.doorBlue, 175, 0.02, 0.25, 0.15);

    // Center vertical meeting stile line (subtle French-hotel double-panel symmetry)
    penLine(CX, 206, CX, mCY + rGlass - 2, PAL.inkBlue, 0.24, "2H");

    // Helper for recessed powder-blue door panels with 3D mitred bevels
    function drawDoorPanel(px1, py1, px2, py2) {
      let outerP = clippedMirrorRectPts(px1, py1, px2, py2, mCX, mCY, rGlass, 12);
      let innerP = clippedMirrorRectPts(px1 + 6, py1 + 6, px2 - 6, py2 - 6, mCX, mCY, rGlass, 12);
      if (outerP.length < 3) return;
      washPoly(outerP, PAL.doorBlueDark, 175);
      if (innerP.length >= 3) {
        washPoly(innerP, PAL.doorBlueMid, 210);
        fillPoly(innerP, PAL.doorBlue, 130, 0.01, 0.18, 0.1);
      }
      // Bevel highlight on right & bottom, shadow on top & left
      penLine(px1 + 1, py2 - 1, px2 - 1, py2 - 1, PAL.doorBlueLight, 0.65, "cpencil");
      penLine(px2 - 1, py1 + 1, px2 - 1, py2 - 1, PAL.doorBlueLight, 0.65, "cpencil");
      // Miter corners
      penLine(px1, py1, px1 + 6, py1 + 6, PAL.inkBlue, 0.25, "rotring");
      penLine(px2, py1, px2 - 6, py1 + 6, PAL.inkBlue, 0.25, "rotring");
      penLine(px1, py2, px1 + 6, py2 - 6, PAL.inkBlue, 0.25, "rotring");
      penLine(px2, py2, px2 - 6, py2 - 6, PAL.inkBlue, 0.25, "rotring");
      strokePoly(outerP, "rotring", PAL.inkBlue, 0.32);
      if (innerP.length >= 3) strokePoly(innerP, "rotring", PAL.inkBlue, 0.24);
    }

    // Twin upper tall panels
    drawDoorPanel(530, 222, 591, 326);
    drawDoorPanel(609, 222, 670, 326);

    // Twin middle horizontal lock-rail panels
    drawDoorPanel(530, 340, 591, 366);
    drawDoorPanel(609, 340, 670, 366);

    // Twin lower panels (clipped cleanly at bottom of mirror)
    let lowLeft = clippedMirrorRectPts(530, 380, 591, 440, mCX, mCY, rGlass, 12);
    let lowRight = clippedMirrorRectPts(609, 380, 670, 440, mCX, mCY, rGlass, 12);
    washPoly(lowLeft, PAL.doorBlueMid, 200);
    washPoly(lowRight, PAL.doorBlueMid, 200);
    strokePoly(lowLeft, "rotring", PAL.inkBlue, 0.3);
    strokePoly(lowRight, "rotring", PAL.inkBlue, 0.3);

    // Architrave vertical ink lines & top miter corners
    let yArch496 = mCY + sqrt(rGlass * rGlass - (496 - mCX) * (496 - mCX));
    let yArch514 = mCY + sqrt(rGlass * rGlass - (514 - mCX) * (514 - mCX));
    penLine(496, 152, 704, 152, PAL.inkMid, 0.38, "rotring");
    penLine(506, 162, 694, 162, PAL.inkSoft, 0.26, "rotring");
    penLine(514, 164, 686, 164, PAL.inkMid, 0.35, "rotring");
    penLine(496, 152, 496, yArch496 - 1, PAL.inkMid, 0.38, "rotring");
    penLine(704, 152, 704, yArch496 - 1, PAL.inkMid, 0.38, "rotring");
    penLine(506, 162, 506, yArch496 - 4, PAL.inkSoft, 0.25, "rotring");
    penLine(694, 162, 694, yArch496 - 4, PAL.inkSoft, 0.25, "rotring");
    penLine(514, 164, 514, yArch514 - 1, PAL.inkBlue, 0.38, "rotring");
    penLine(686, 164, 686, yArch514 - 1, PAL.inkBlue, 0.38, "rotring");
    penLine(496, 152, 514, 164, PAL.inkMid, 0.3, "rotring");
    penLine(704, 152, 686, 164, PAL.inkMid, 0.3, "rotring");

    // Symmetrical Brass Door Hardware (escutcheon plates, twin brass knobs & keyholes)
    for (let kx of [522, 678]) {
      washRect(kx - 4, 336, 8, 34, PAL.brassBase, 240);
      strokeRect(kx - 4, 336, 8, 34, "rotring", PAL.brassInk, 0.28);
      let knobPts = circlePts(kx, 348, 6.5, 20);
      washPoly(knobPts, PAL.brassLight, 245);
      fillPoly(knobPts, PAL.brassMid, 160, 0.01, 0.15, 0.1);
      strokePoly(knobPts, "rotring", PAL.brassInk, 0.32);
      // Keyhole slot below knob
      penLine(kx, 358, kx, 365, PAL.inkDark, 0.45, "rotring");
    }
    // Tiny brass card frame centered on door at (600, 274)
    washRect(592, 266, 16, 12, PAL.brassBase, 230);
    washRect(594, 268, 12, 8, PAL.white, 230);
    strokeRect(592, 266, 16, 12, "rotring", PAL.brassInk, 0.26);

    // 5. Mirror Glass Bevel Ring & Crisp Diagonal Specular Streaks
    // Bevel refraction highlight ring along inner circumference (r = 138 to 148)
    for (let a = 0; a < 360; a += 4) {
      let a1 = a;
      let a2 = a + 4;
      let rB = rGlass - 7;
      penLine(
        mCX + cos(a1) * rB,
        mCY + sin(a1) * rB,
        mCX + cos(a2) * rB,
        mCY + sin(a2) * rB,
        PAL.white,
        0.45,
        "cpencil"
      );
    }

    // Diagonal glass sheen streaks (clipped inside rGlass - 8)
    const sheenOffsets = [-68, -54, 32, 44, 52];
    for (let off of sheenOffsets) {
      // Line x + y = mCX + mCY + off (45-degree diagonal)
      let pts = [];
      for (let t = -rGlass; t <= rGlass; t += 4) {
        let sx = mCX + t;
        let sy = mCY - t + off;
        if (dist(sx, sy, mCX, mCY) < rGlass - 9) {
          pts.push([sx, sy]);
        }
      }
      if (pts.length > 2) {
        let aPt = pts[0];
        let bPt = pts[pts.length - 1];
        penLine(aPt[0], aPt[1], bPt[0], bPt[1], PAL.white, 0.75, "cpencil");
      }
    }

    // 6. Crisp Brass Mirror Frame Specular Arcs, Rivets & Concentric Ink Circles
    const frameRadii = [
      { r: rOuter, col: PAL.brassInk, w: 0.55 },
      { r: rOuter - 4, col: PAL.brassLight, w: 0.65, b: "cpencil" },
      { r: rMid, col: PAL.brassInk, w: 0.38 },
      { r: rInner, col: PAL.brassInk, w: 0.38 },
      { r: rGlass + 3, col: PAL.brassLight, w: 0.6, b: "cpencil" },
      { r: rGlass, col: PAL.brassInk, w: 0.52 },
      { r: rGlass - 7, col: PAL.inkBlue, w: 0.22 }
    ];
    for (let fr of frameRadii) {
      let cPts = circlePts(mCX, mCY, fr.r, 84);
      strokePoly(cPts, fr.b || "rotring", fr.col, fr.w, true);
    }

    // Cardinal brass frame rivets / clasps at 0, 90, 180, 270 degrees
    for (let ang of [0, 45, 90, 135, 180, 225, 270, 315]) {
      let rx = mCX + cos(ang) * (rOuter - 6.5);
      let ry = mCY + sin(ang) * (rOuter - 6.5);
      let rPts = circlePts(rx, ry, 2.6, 12);
      washPoly(rPts, PAL.brassLight, 240);
      strokePoly(rPts, "rotring", PAL.brassInk, 0.26);
    }
  }

  // =========================================================================
  // 5. SYMMETRICAL TWIN BRASS & MILK-GLASS WALL SCONCES
  // =========================================================================
  function drawTwinSconces() {
    for (let dir of [-1, 1]) {
      let sx = CX + dir * 304; // X = 296 and X = 904
      let sy = 296;

      // Stepped circular brass wall backplate
      let bpOuter = circlePts(sx, sy, 32, 36);
      let bpInner = circlePts(sx, sy, 22, 32);
      washPoly(bpOuter, PAL.brassBase, 235);
      fillPoly(bpOuter, PAL.brassMid, 150, 0.01, 0.18, 0.12);
      washPoly(bpInner, PAL.brassLight, 225);
      strokePoly(bpOuter, "rotring", PAL.brassInk, 0.42);
      strokePoly(bpInner, "rotring", PAL.brassInk, 0.32);

      // Curved/stepped Art Deco brass arm & socket cup
      washRect(sx - 7, sy - 8, 14, 16, PAL.brassDark, 220);
      strokeRect(sx - 7, sy - 8, 14, 16, "rotring", PAL.brassInk, 0.32);
      // Vertical stem rising to tulip shade & lower brass finial drop
      washRect(sx - 4, sy - 34, 8, 28, PAL.brassBase, 240);
      strokeRect(sx - 4, sy - 34, 8, 28, "rotring", PAL.brassInk, 0.32);
      // Lower finial acorn
      let finPts = [
        [sx - 6, sy + 8],
        [sx + 6, sy + 8],
        [sx + 4, sy + 24],
        [sx, sy + 34],
        [sx - 4, sy + 24]
      ];
      washPoly(finPts, PAL.brassBase, 235);
      strokePoly(finPts, "rotring", PAL.brassInk, 0.32);

      // Brass gallery cup holding the milk-glass shade
      let cupPts = [
