  // =========================================================================
  // 6. SYMMETRICAL BRASS TOWEL BARS & HANGING FOLDED BATH TOWELS
  // =========================================================================
  function drawWallTowels() {
    for (let dir of [-1, 1]) {
      let cxBar = CX + dir * 372; // X = 228 and X = 972 (centered on flanking tile walls)
      let barY = 716;
      let barHalfW = 72;

      // Brass wall rosettes (left & right ends of towel bar)
      for (let endDir of [-1, 1]) {
        let rx = cxBar + endDir * barHalfW;
        let rOuter = circlePts(rx, barY, 13, 20);
        let rInner = circlePts(rx, barY, 7, 16);
        washPoly(rOuter, PAL.brassBase, 240);
        washPoly(rInner, PAL.brassLight, 245);
        strokePoly(rOuter, "rotring", PAL.brassInk, 0.35);
        strokePoly(rInner, "rotring", PAL.brassInk, 0.28);
      }

      // Horizontal polished brass towel bar
      washRect(cxBar - barHalfW, barY - 4.5, barHalfW * 2, 9, PAL.brassBase, 240);
      penLine(cxBar - barHalfW, barY - 1.5, cxBar + barHalfW, barY - 1.5, PAL.brassLight, 0.7, "cpencil");
      strokeRect(cxBar - barHalfW, barY - 4.5, barHalfW * 2, 9, "rotring", PAL.brassInk, 0.34);

      // Crisp Folded Hotel Bath Towel hanging over the brass bar
      let tw = 104;
      let tx = cxBar - tw / 2;
      let ty = barY - 8;
      let th = 198;

      // Back fold layer peeking slightly below front layer
      washRect(tx + 4, ty + th - 4, tw - 8, 16, PAL.towelShadow, 235);
      strokeRect(tx + 4, ty + th - 4, tw - 8, 16, "rotring", PAL.inkMid, 0.32);

      // Main front hanging towel body (opaque wash + soft watercolor fill)
      washRect(tx, ty, tw, th, PAL.towelCream, 250);
      fillRect(tx, ty, tw, th, PAL.towelCream, 175, 0.02, 0.28, 0.15);
      // Subtle vertical fold-crease shading
      fillRect(tx + tw - 12, ty + 4, 12, th - 8, PAL.towelShadow, 120, 0.01, 0.2, 0.1);
      penLine(tx + tw / 2, ty + 14, tx + tw / 2, ty + th - 6, PAL.towelShadow, 0.35, "2H");

      // Confectionery pastel woven border stripes near bottom hem
      washRect(tx + 1, ty + th - 44, tw - 2, 12, PAL.tileBase2, 215);
      washRect(tx + 1, ty + th - 26, tw - 2, 7, PAL.mintMid, 215);
      penLine(tx + 1, ty + th - 44, tx + tw - 1, ty + th - 44, PAL.inkSoft, 0.26, "rotring");
      penLine(tx + 1, ty + th - 32, tx + tw - 1, ty + th - 32, PAL.inkSoft, 0.26, "rotring");
      penLine(tx + 1, ty + th - 26, tx + tw - 1, ty + th - 26, PAL.inkSoft, 0.24, "rotring");
      penLine(tx + 1, ty + th - 19, tx + tw - 1, ty + th - 19, PAL.inkSoft, 0.24, "rotring");

      // Hyperreal terry-cloth weave texture (fine graphite hatch & stipple)
      for (let hy = ty + 12; hy < ty + th - 4; hy += 5.5) {
        penLine(tx + 4, hy, tx + tw - 4, hy, PAL.moldingShadow, 0.18, "2H");
      }
      // Side folded layer edges (showing tri-fold thickness)
      penLine(tx + 3.5, ty + 8, tx + 3.5, ty + th - 2, PAL.inkSoft, 0.24, "rotring");
      penLine(tx + tw - 3.5, ty + 8, tx + tw - 3.5, ty + th - 2, PAL.inkSoft, 0.24, "rotring");

      // Crisp outer pen outline
      strokeRect(tx, ty, tw, th, "rotring", PAL.inkDark, 0.4);
    }
  }

