  // =========================================================================
  // 8. TWIN BRASS TAPS (HOT & COLD) AND CENTRAL POP-UP DRAIN ROD
  // =========================================================================
  function drawTwinBrassTaps() {
    // 1. Central Pop-Up Drain Lift Rod on Sink Deck (X = 600, Y = 615)
    let cBase = rectPts(CX - 10, 609, 20, 7);
    washPoly(cBase, PAL.brassBase, 245);
    strokePoly(cBase, "rotring", PAL.brassInk, 0.32);
    washRect(CX - 3.5, 586, 7, 23, PAL.brassBase, 245);
    strokeRect(CX - 3.5, 586, 7, 23, "rotring", PAL.brassInk, 0.3);
    let cKnob = circlePts(CX, 581, 8, 20);
    washPoly(cKnob, PAL.white, 245);
    strokePoly(cKnob, "rotring", PAL.brassInk, 0.34);
    let cCap = circlePts(CX, 581, 4, 14);
    washPoly(cCap, PAL.brassBase, 240);
    strokePoly(cCap, "rotring", PAL.brassInk, 0.24);

    // 2. Twin Brass Pillar Taps with Cross-Handles & Curved Spouts (X = 488 and X = 712)
    const taps = [
      { x: 488, dir: 1, label: "H" },  // Left tap spouts inward (+1) toward basin center
      { x: 712, dir: -1, label: "C" }  // Right tap spouts inward (-1) toward basin center
    ];

    for (let t of taps) {
      let tx = t.x;
      let d = t.dir;
      let baseY = 616;

      // Stepped hexagonal brass deck escutcheon (Y: 604 to 618)
      let esc1 = rectPts(tx - 24, baseY - 6, 48, 8);
      let esc2 = [
        [tx - 20, baseY - 14],
        [tx + 20, baseY - 14],
        [tx + 24, baseY - 6],
        [tx - 24, baseY - 6]
