      washPoly(esc1, PAL.brassBase, 245);
      washPoly(esc2, PAL.brassLight, 240);
      penLine(tx - 10, baseY - 6, tx - 10, baseY + 2, PAL.brassInk, 0.28, "rotring");
      penLine(tx + 10, baseY - 6, tx + 10, baseY + 2, PAL.brassInk, 0.28, "rotring");
      strokePoly(esc1, "rotring", PAL.brassInk, 0.36);
      strokePoly(esc2, "rotring", PAL.brassInk, 0.34);

      // Vertical brass pillar body (Y: 548 to 602)
      let pillar = rectPts(tx - 12, 548, 24, 54);
      washPoly(pillar, PAL.brassBase, 245);
      fillPoly(pillar, PAL.brassMid, 140, 0.01, 0.18, 0.1);
      // Specular vertical brass band
      washRect(tx - 5, 550, 7, 50, PAL.brassLight, 230);
      washRect(tx + 6, 550, 5, 50, PAL.brassDark, 155);
      strokePoly(pillar, "rotring", PAL.brassInk, 0.38);

      // Decorative collar ring at spout junction (Y: 566 to 576)
      washRect(tx - 15, 566, 30, 10, PAL.brassLight, 245);
      strokeRect(tx - 15, 566, 30, 10, "rotring", PAL.brassInk, 0.35);

      // Inward-arching brass spout reaching over the basin (from tx to tx + d * 64)
      let spoutPts = [
        [tx + d * 12, 564],
        [tx + d * 42, 558],
        [tx + d * 62, 566],
        [tx + d * 68, 582],
        [tx + d * 68, 592],
        [tx + d * 54, 592],
        [tx + d * 52, 578],
        [tx + d * 36, 573],
        [tx + d * 12, 578]
