      washPoly(spoutPts, PAL.brassBase, 245);
      fillPoly(spoutPts, PAL.brassMid, 150, 0.01, 0.18, 0.1);
      // Bright brass highlight along top curve of spout
      penLine(tx + d * 14, 566, tx + d * 42, 561, PAL.brassLight, 0.85, "cpencil");
      penLine(tx + d * 42, 561, tx + d * 60, 568, PAL.brassLight, 0.85, "cpencil");
