      penLine(nozX - 1.5, 600, nozX - 0.5, 599, PAL.white, 0.55, "cpencil");
      strokePoly(dropPts, "rotring", PAL.inkMint, 0.24);

      // Cross-Handle Stem & Turned Brass Arms (Y = 532)
      let hY = 532;
      washRect(tx - 6, hY + 6, 12, 11, PAL.brassDark, 230);
      strokeRect(tx - 6, hY + 6, 12, 11, "rotring", PAL.brassInk, 0.32);

