function draw() {
  translate(-width / 2, -height / 2);

  // =========================================================================
  // 1. FAST DETERMINISTIC VALUE NOISE & FBM ENGINE
  // =========================================================================
  const PERM = new Uint8Array(512);
  const VALS = new Float32Array(256);
  for (let i = 0; i < 256; i++) {
    PERM[i] = i;
    VALS[i] = random();
  }
  for (let i = 255; i > 0; i--) {
    const j = Math.floor(random(i + 1));
    const tmp = PERM[i];
    PERM[i] = PERM[j];
    PERM[j] = tmp;
  }
  for (let i = 0; i < 256; i++) PERM[i + 256] = PERM[i];

  function vnoise(x, y) {
    const xi = Math.floor(x) & 255;
    const yi = Math.floor(y) & 255;
    const xf = x - Math.floor(x);
    const yf = y - Math.floor(y);
    const u = xf * xf * (3.0 - 2.0 * xf);
    const v = yf * yf * (3.0 - 2.0 * yf);
    const aa = VALS[PERM[xi + PERM[yi]]];
    const ba = VALS[PERM[xi + 1 + PERM[yi]]];
    const ab = VALS[PERM[xi + PERM[yi + 1]]];
    const bb = VALS[PERM[xi + 1 + PERM[yi + 1]]];
    return (aa + u * (ba - aa)) + v * ((ab + u * (bb - ab)) - (aa + u * (ba - aa)));
  }

  function fbm(x, y) {
    return 0.53 * vnoise(x, y) +
           0.27 * vnoise(x * 2.07 + 17.3, y * 2.07 + 31.7) +
           0.13 * vnoise(x * 4.31 + 59.1, y * 4.31 + 11.4) +
           0.07 * vnoise(x * 8.73 + 23.8, y * 8.73 + 83.2);
  }

  // =========================================================================
  // 2. YELLOWED, FAINTLY FOXED NEWSPRINT GROUND
  // =========================================================================
  background("#efe1ba");

  // Watercolor & wash layers for aged yellowed newsprint and foxing stains
  brush.noStroke();
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.68, 0.32);

  // Broad warm newsprint age toning (darker at clipped edges)
  brush.fill("#e3ce98", 95);
  brush.rect(0, 0, 1200, 1200, "corner");

  brush.fill("#d8bc7c", 75);
  brush.circle(120, 110, 420, 0.4);
  brush.circle(1120, 150, 380, 0.4);
  brush.circle(1090, 1080, 460, 0.4);
  brush.circle(90, 1090, 400, 0.4);

  // Faint foxing spots (oxidized warm ochre / sienna / rust blooms in paper)
  const foxSpots = [
    [165, 240, 68], [1040, 190, 82], [920, 85, 48], [1110, 520, 74],
    [105, 840, 62], [380, 1115, 78], [980, 1020, 92], [540, 95, 55],
    [82, 480, 52], [1135, 810, 64], [720, 1130, 58], [295, 130, 44],
    [840, 310, 38], [460, 620, 45], [215, 1040, 54], [1060, 360, 42]
  ];
  brush.fillBleed(0.45, "out");
  brush.fill("#c48a47", 52);
  for (let i = 0; i < foxSpots.length; i++) {
    brush.circle(foxSpots[i][0], foxSpots[i][1], foxSpots[i][2], 0.55);
  }
  brush.fill("#a86428", 38);
  for (let i = 0; i < foxSpots.length; i += 2) {
    brush.circle(foxSpots[i][0] + 8, foxSpots[i][1] - 5, foxSpots[i][2] * 0.48, 0.6);
  }
  brush.noFill();

  // Subtle horizontal & diagonal newsprint pulp grain across the whole sheet
  brush.set("2H", "#cdb480", 0.55);
  for (let i = 0; i < 240; i++) {
    const py = random(0, 1200);
    const px = random(0, 1050);
    const plen = random(50, 180);
    brush.line(px, py, px + plen, py + random(-2, 2));
  }

  // =========================================================================
  // 3. BUILD 600x600 HYPERREAL LIGHTING & COLOR PLATE BUFFERS (2px Pitch)
  // =========================================================================
  const GW = 600;
  const GH = 600;
  const bufK = new Float32Array(GW * GH);     // Black halftone key darkness [0..1]
  const bufR = new Float32Array(GW * GH);     // Vivid crimson/vermilion plate [0..1]
  const bufY = new Float32Array(GW * GH);     // Warm golden-amber/ochre plate [0..1]
  const bufC = new Float32Array(GW * GH);     // Prussian-cyan shadow/drift plate [0..1]
  const bufChalk = new Float32Array(GW * GH); // Chalk dust & blown highlight stipple [0..1]
  const bufZone = new Uint8Array(GW * GH);    // 0 = bg, 1 = hand, 2 = ball, 3 = seam

  // Capsule evaluation helper: returns { inside, t, s, z, nx, ny, nz, dist }
  function evalCapsule(px, py, x1, y1, r1, x2, y2, r2, bulgeEnd) {
    const dx = x2 - x1;
    const dy = y2 - y1;
    const len2 = dx * dx + dy * dy;
    const len = Math.sqrt(len2);
    let t = ((px - x1) * dx + (py - y1) * dy) / len2;
    t = Math.max(0.0, Math.min(1.0, t));
    const cx = x1 + t * dx;
    const cy = y1 + t * dy;
    // Joint swelling at ends of phalanx
    const jointSwelling = bulgeEnd * (Math.exp(-t * t * 18.0) + Math.exp(-(1.0 - t) * (1.0 - t) * 18.0));
    const rad = r1 + t * (r2 - r1) + jointSwelling;
    const tx = dx / len;
    const ty = dy / len;
    const nxPerp = -ty;
    const nyPerp = tx;
    const vx = px - cx;
    const vy = py - cy;
    const sSigned = (vx * nxPerp + vy * nyPerp) / rad;
    const axialDist = (vx * tx + vy * ty) / rad;
    let dNorm2 = sSigned * sSigned;
    if (t <= 0.001 && axialDist < 0) dNorm2 += axialDist * axialDist * 0.85;
    if (t >= 0.999 && axialDist > 0) dNorm2 += axialDist * axialDist * 0.85;
    if (dNorm2 >= 1.0) {
      return { inside: false, dist: Math.sqrt(dNorm2) - 1.0, t, s: sSigned };
    }
    const z = Math.sqrt(1.0 - dNorm2);
    const nxx = sSigned * nxPerp + (t <= 0.001 || t >= 0.999 ? axialDist * 0.65 * tx : 0);
    const nyy = sSigned * nyPerp + (t <= 0.001 || t >= 0.999 ? axialDist * 0.65 * ty : 0);
    const nzz = z;
    const nLen = Math.sqrt(nxx * nxx + nyy * nyy + nzz * nzz) || 1;
    return {
      inside: true,
      dist: 0,
      t,
      s: sSigned,
      z,
      nx: nxx / nLen,
      ny: nyy / nLen,
      nz: nzz / nLen
    };
  }

  // Distance to segment helper for veins, tendons, creases, shadows
  function segInfo(px, py, x1, y1, x2, y2) {
    const dx = x2 - x1;
    const dy = y2 - y1;
    const l2 = dx * dx + dy * dy;
    const t = Math.max(0, Math.min(1, ((px - x1) * dx + (py - y1) * dy) / l2));
    const qx = x1 + t * dx - px;
    const qy = y1 + t * dy - py;
    return { d: Math.sqrt(qx * qx + qy * qy), t };
  }

  // Primary hard flash light vector (slightly upper-right-front strobe)
  const lx = 0.31, ly = -0.29, lz = 0.905;

  // Ball parameters (large macro crop)
  const ballX = 688;
  const ballY = 544;
  const ballR = 388;

  // Seam rotation constants (tilted ~13.5 degrees counter-clockwise, seam up)
  const seamAng = -13.5 * Math.PI / 180.0;
  const cosSeam = Math.cos(seamAng);
  const sinSeam = Math.sin(seamAng);

  for (let gy = 0; gy < GH; gy++) {
    const y = gy * 2.0 + 1.0;
    for (let gx = 0; gx < GW; gx++) {
      const x = gx * 2.0 + 1.0;
      const idx = gy * GW + gx;

      const nCoarse = fbm(x * 0.007, y * 0.007);
      const nMed = fbm(x * 0.025 + 19.4, y * 0.025 + 41.2);
      const nFine = vnoise(x * 0.09, y * 0.09);
      const nMicro = vnoise(x * 0.24 + 7.1, y * 0.24 + 13.8);

      // ---------------------------------------------------------------------
      // LAYER 0: DARK FLASH-FALLOFF PRESS PHOTO BACKGROUND
      // ---------------------------------------------------------------------
      // Brighter behind upper-left knuckles, deep inky drop-off on right & bottom-right
      const bgRadial = Math.sqrt((x - 420) * (x - 420) + (y - 380) * (y - 380)) / 920.0;
      let K = Math.min(0.95, Math.max(0.18, 0.34 + 0.58 * bgRadial + 0.14 * (nCoarse - 0.5)));
      // Motion/stadium streak texture in background
      const streak = vnoise(x * 0.012 - y * 0.006, y * 0.035);
      K = Math.min(0.96, K + (streak - 0.5) * 0.12);
      let R = 0.04;
      let Y = 0.16;
      let C = 0.28 * K;
      let chalk = 0.0;
      let zone = 0;

      // ---------------------------------------------------------------------
      // LAYER 1: BACK OF HAND, WRIST, PALM & CURLED RING / LITTLE FINGERS
      // ---------------------------------------------------------------------
      // Dorsal hand & wrist mass bleeding off left (x=0) and bottom (y=1200)
      const wristCap = evalCapsule(x, y, -40, 1220, 290, 145, 620, 235, 8);
      const dorsalCap = evalCapsule(x, y, 65, 580, 215, 205, 260, 155, 10);
      const palmCap = evalCapsule(x, y, 165, 840, 195, 340, 610, 165, 6);

      // Curled Ring Finger (MCP -> bent PIP -> tucked tip)
      const ringProx = evalCapsule(x, y, 128, 548, 72, 304, 578, 59, 6);
      const ringDist = evalCapsule(x, y, 304, 578, 57, 236, 702, 47, 4);

      // Curled Little Finger (MCP -> bent PIP -> tucked tip)
      const pinkyProx = evalCapsule(x, y, 86, 692, 64, 246, 728, 51, 5);
      const pinkyDist = evalCapsule(x, y, 246, 728, 49, 184, 828, 42, 4);

      // Evaluate Layer 1 Hand base
      if (wristCap.inside || dorsalCap.inside || palmCap.inside) {
        zone = 1;
        // Choose most prominent normal
        let hnx = -0.35, hny = -0.15, hnz = 0.82;
        if (dorsalCap.inside && dorsalCap.z > 0.2) {
          hnx = dorsalCap.nx; hny = dorsalCap.ny; hnz = dorsalCap.nz;
        } else if (palmCap.inside && palmCap.z > 0.2) {
          hnx = palmCap.nx; hny = palmCap.ny; hnz = palmCap.nz;
        } else if (wristCap.inside) {
          hnx = wristCap.nx; hny = wristCap.ny; hnz = wristCap.nz;
        }

        // Extensor tendons & dorsal veins on back of hand
        const tend1 = segInfo(x, y, 15, 920, 175, 405);
        const tend2 = segInfo(x, y, -10, 820, 225, 240);
        const tend3 = segInfo(x, y, 30, 980, 130, 550);
        const vein1 = segInfo(x, y, 45, 760, 155, 450);

        let ridgeLift = 0.0;
        if (tend1.d < 34) {
          const u = (tend1.d / 34.0);
          ridgeLift += (1.0 - u * u) * 0.24;
          hnx += (x < 95 ? -0.18 : 0.18) * (1.0 - u);
        }
        if (tend2.d < 30) {
          const u = (tend2.d / 30.0);
          ridgeLift += (1.0 - u * u) * 0.20;
        }
        if (tend3.d < 28) {
          const u = (tend3.d / 28.0);
          ridgeLift += (1.0 - u * u) * 0.18;
        }
        if (vein1.d < 14) {
          const u = vein1.d / 14.0;
          ridgeLift += (1.0 - u * u) * 0.14;
        }

        // Skin creases & pores on wrist/dorsum
        const wristFold = Math.sin((x * 0.09 + y * 0.06) + nMed * 3.5);
        const diff = Math.max(0.0, hnx * lx + hny * ly + hnz * lz) + ridgeLift;
        K = 0.76 - 0.62 * diff + (nMed - 0.5) * 0.14 + (nFine - 0.5) * 0.09;
        if (wristFold > 0.78 && y > 680) K += 0.16;

        // Shadow cast by cricket ball onto palm webbing (x ~ 230..380, y ~ 430..820)
        const dToBallCenter = Math.sqrt((x - ballX) * (x - ballX) + (y - ballY) * (y - ballY));
        if (dToBallCenter < ballR + 85 && x > 185 && y > 410 && y < 870) {
          constao = 1.0 - Math.max(0, (dToBallCenter - ballR) / 85.0);
          K = Math.min(0.97, K + 0.52 * constao);
        }

        K = Math.max(0.04, Math.min(0.96, K));
        R = 0.26 * (1.0 - K * 0.5);
        Y = 0.62 * (1.0 - K * 0.35);
        C = 0.18 * K;
        chalk = diff > 0.68 ? 0.32 : 0.05;
      }

      // Curled Little Finger & Ring Finger (overlapping palm, tucked under ball)
      const curledList = [
        { cap: pinkyDist, isProx: false, jx: 246, jy: 728 },
        { cap: pinkyProx, isProx: true,  jx: 246, jy: 728 },
        { cap: ringDist,  isProx: false, jx: 304, jy: 578 },
        { cap: ringProx,  isProx: true,  jx: 304, jy: 578 }
      ];
      for (let c = 0; c < curledList.length; c++) {
        const item = curledList[c];
        const cap = item.cap;
        if (cap.inside) {
          zone = 1;
          let diff = Math.max(0.0, cap.nx * lx + cap.ny * ly + cap.nz * lz);
          const spec = Math.pow(Math.max(0.0, cap.nx * 0.25 + cap.ny * -0.25 + cap.nz * 0.93), 14.0);

          // Concentric knuckle creases near MCP (t~0) and bent PIP joint (t~1 on prox)
          let creaseK = 0.0;
          let creaseChalk = 0.0;
          if (item.isProx) {
            // MCP knuckle folds near t = 0.12
            const dt0 = cap.t - 0.12;
            const env0 = Math.exp(-dt0 * dt0 * 42.0) * Math.exp(-cap.s * cap.s * 2.8);
            const w0 = Math.sin(dt0 * 95.0 + cap.s * cap.s * 6.0 + nFine * 2.2);
            creaseK += env0 * (w0 > 0.2 ? 0.28 : -0.14);
            if (env0 > 0.3 && w0 < -0.2) creaseChalk += 0.45;

            // Bent PIP knuckle folds near t = 0.88
            const dt1 = cap.t - 0.88;
            const env1 = Math.exp(-dt1 * dt1 * 38.0) * Math.exp(-cap.s * cap.s * 2.4);
            const w1 = Math.sin(dt1 * 110.0 - cap.s * cap.s * 8.0 + nFine * 2.5);
            creaseK += env1 * (w1 > 0.15 ? 0.34 : -0.18);
            if (env1 > 0.25 && w1 < -0.15) creaseChalk += 0.55;
          } else {
            // Tucked distal segment plunges into deep shadow under the ball
            diff *= 0.38 * (1.0 - cap.t * 0.7);
          }

          // Edge crevice darkening around finger boundary
          const edgeAO = Math.pow(Math.abs(cap.s), 3.2) * 0.48;
          K = 0.72 - 0.64 * diff - 0.26 * spec + creaseK + edgeAO + (nFine - 0.5) * 0.1;

          // Deep shadow from overhanging ball on tucked fingers
          const dBall = Math.sqrt((x - ballX) * (x - ballX) + (y - ballY) * (y - ballY));
          if (dBall < ballR + 36 && x > 235) {
            const overhang = 1.0 - Math.max(0.0, (dBall - ballR) / 36.0);
            K = Math.min(0.97, K + overhang * 0.48);
          }

          K = Math.max(0.02, Math.min(0.97, K));
          R = 0.32 * (1.0 - K * 0.45) + (creaseK > 0.1 ? 0.14 : 0);
          Y = 0.66 * (1.0 - K * 0.35);
          C = 0.16 * K;
          chalk = creaseChalk + (spec > 0.4 ? 0.45 : 0.0);
        }
      }

      // ---------------------------------------------------------------------
      // LAYER 2: THE WORN RED CRICKET BALL (SEAM UP)
      // ---------------------------------------------------------------------
      const bdx = x - ballX;
      const bdy = y - ballY;
      // Slight organic irregularity on leather silhouette + raised seam bumps at poles
      const edgeRough = (nFine - 0.5) * 3.5;
      const bDist = Math.sqrt(bdx * bdx + bdy * bdy);

      if (bDist <= ballR + edgeRough) {
        zone = 2;
        const rNorm = Math.min(0.998, bDist / (ballR + edgeRough));
        const bnx = bdx / ballR;
        const bny = bdy / ballR;
        const bnz = Math.sqrt(Math.max(0.001, 1.0 - rNorm * rNorm));

        // Rotate sphere normal into seam-aligned coordinate system:
        // sx = signed distance across the upright seam
        // sy = distance along the vertical seam axis
        const sx0 = bnx * cosSeam - bny * sinSeam;
        const sy0 = bnx * sinSeam + bny * cosSeam;
        // Slight 3D spherical perspective curve of the equatorial belt
        const sx = sx0 * 0.985 - (1.0 - bnz) * 0.065;
        const sy = sy0;
        const sz = bnz;

        // Lighting on sphere
        let bDiff = Math.max(0.0, bnx * lx + bny * ly + bnz * lz);
        // Half-vector for hard flash specular reflection
        const hx = lx, hy = ly, hz = lz + 1.0;
        const hLen = Math.sqrt(hx * hx + hy * hy + hz * hz);
        const ndoth = Math.max(0.0, (bnx * hx + bny * hy + bnz * hz) / hLen);

        // Seam belt spans |sx| < 0.148 (~114px wide at center)
        const absSx = Math.abs(sx);

        if (absSx < 0.148) {
          // =================================================================
          // THE RAISED EQUATORIAL SEAM & 6 ROWS OF HAND-STITCHING
          // =================================================================
          zone = 3;
          const phi = Math.atan2(sy, sz + 0.15); // Angular coordinate along the seam

          // 1. Central split cleft between the two leather hemispheres (|sx| < 0.013)
          if (absSx < 0.013) {
            const cleftDepth = 1.0 - (absSx / 0.013);
            K = 0.78 + 0.18 * cleftDepth - 0.15 * bDiff;
            R = 0.45 * (1.0 - cleftDepth * 0.6);
            Y = 0.25;
            C = 0.35;
            chalk = cleftDepth > 0.6 && nMicro > 0.68 ? 0.55 : 0.05;
          } else {
            // 2. Six parallel rows of stitches: 3 on left (-), 3 on right (+)
            // Row centers at |sx| = 0.036, 0.074, 0.112
            const rowCenters = [0.036, 0.074, 0.112];
            let bestRowDist = 999.0;
            let rowIdx = 0;
            for (let r = 0; r < 3; r++) {
              const d = Math.abs(absSx - rowCenters[r]);
              if (d < bestRowDist) {
                bestRowDist = d;
                rowIdx = r;
              }
            }

            // Stitch repetition along phi (approx 72 stitches visible down the front)
            const stitchFreq = 70.0;
            const rowPhase = rowIdx * 1.15 + (sx > 0 ? 0.0 : 0.55);
            // Slight herringbone slant of thread across the row
            const slant = (absSx - rowCenters[rowIdx]) * 18.0 * (sx > 0 ? 1.0 : -1.0);
            const stitchCoord = phi * stitchFreq + rowPhase + slant;
            const stitchCell = stitchCoord - Math.floor(stitchCoord); // [0..1] along single stitch

            // Cross-row profile of thread (width ~ 0.0155 in normalized sphere coords)
            const threadHalfW = 0.0145;
            const uAcross = bestRowDist / threadHalfW;

            if (uAcross < 1.0 && stitchCell > 0.14 && stitchCell < 0.88) {
              // ON A RAISED WHITE/CHALKY LINEN STITCH!
              const vAlong = (stitchCell - 0.51) / 0.37; // [-1..1] along stitch length
              const pillowH = Math.sqrt(Math.max(0.0, 1.0 - uAcross * uAcross * 0.75 - vAlong * vAlong * 0.65));
              // Stitch 3D micro-normal catches top-right flash and shades at bottom
              const stLight = bDiff * 0.75 + pillowH * 0.45 - vAlong * 0.38 + (sx > 0 ? 0.08 : -0.05);
              // Twisted linen cord fiber micro-texture
              const fiber = Math.sin((uAcross * 9.0 + vAlong * 5.0) + nMicro * 3.0) * 0.07;

              K = Math.max(0.01, Math.min(0.85, 0.58 - 0.62 * stLight + fiber));
              // Stitches are chalky cream/white with faint pink/red leather dye stain
              R = 0.12 + 0.14 * (1.0 - pillowH);
              Y = 0.28 + 0.15 * K;
              C = 0.08 * K;
              chalk = Math.max(0.25, 0.92 - K * 0.85);
            } else if (uAcross < 1.15 && (stitchCell <= 0.14 || stitchCell >= 0.88)) {
              // NEEDLE PUNCTURE HOLE & CAST SHADOW UNDER STITCH END
              K = Math.min(0.96, 0.78 + 0.16 * (1.0 - bDiff) + nFine * 0.08);
              R = 0.48;
              Y = 0.22;
              C = 0.32;
              chalk = 0.12;
            } else {
              // Red leather ridge between stitch rows (proud, scuffed, dusty)
              const ridgeSlope = Math.sin((absSx / 0.148) * Math.PI * 6.0) * 0.14;
              const ridgeLight = bDiff + ridgeSlope;
              K = Math.max(0.08, Math.min(0.92, 0.68 - 0.56 * ridgeLight + (nFine - 0.5) * 0.16));
              R = 0.82 * (1.0 - K * 0.35);
              Y = 0.38 * (1.0 - K * 0.35);
              C = 0.18 * K;
              chalk = nMicro > 0.62 ? 0.38 : 0.08;
            }
          }
        } else if (sx < -0.148) {
          // =================================================================
          // LEFT HEMISPHERE: THE WORN, SCUFFED, ABRADED LEATHER SIDE
          // =================================================================
          // Multi-scale rough leather grain, turf scratches, and dry chalk patches
          const scuffPatch = fbm(x * 0.018 + 5.2, y * 0.018 + 9.7);
          const scratch1 = Math.abs(Math.sin((x * 0.055 + y * 0.032) + nCoarse * 5.5));
          const scratch2 = Math.abs(Math.sin((x * 0.028 - y * 0.064) + nMed * 6.2));
          const isGouge = (scratch1 < 0.085 && scuffPatch > 0.44) || (scratch2 < 0.075 && scuffPatch > 0.48);

          // Matte rough specular response
          const roughSpec = Math.pow(ndoth, 7.0) * 0.28;
          const poreBump = (nFine - 0.5) * 0.22 + (nMicro - 0.5) * 0.16;

          K = 0.78 - 0.64 * bDiff - roughSpec + poreBump;

          if (isGouge) {
            // Turf gouge exposes paler orange-buff core leather with a dark torn rim
            K = Math.max(0.08, K - 0.18 + (nMicro - 0.5) * 0.25);
            R = 0.68;
            Y = 0.74;
            C = 0.06;
            chalk = 0.55;
          } else if (scuffPatch > 0.60) {
            // Heavily abraded dry scuffed patch
            K = Math.max(0.06, K - 0.10 + (nMicro - 0.5) * 0.24);
            R = 0.78;
            Y = 0.62;
            C = 0.10 * K;
            chalk = 0.42 * (scuffPatch - 0.45);
          } else {
            // Worn crimson leather
            R = 0.92 * (1.0 - K * 0.25);
            Y = 0.46 * (1.0 - K * 0.30);
            C = 0.22 * K;
            chalk = nMicro > 0.75 ? 0.25 : 0.0;
          }

          // Terminator shadow near left/bottom-left rim of ball
          if (rNorm > 0.84) {
            const rimDark = (rNorm - 0.84) / 0.16;
            K = Math.min(0.95, K + rimDark * 0.32);
          }
          K = Math.max(0.03, Math.min(0.95, K));
        } else {
          // =================================================================
          // RIGHT HEMISPHERE: THE POLISHED, LACQUERED CRIMSON SIDE + HARD FLASH
          // =================================================================
          // Blinding hard-flash specular highlight on upper-right dome
          const glossSpecCore = Math.pow(ndoth, 34.0);
          const glossSpecHalo = Math.pow(ndoth, 11.0);
          // Secondary curved studio/stadium flash reflection arc
          const arcDist = Math.abs(Math.sqrt((bnx - 0.34) * (bnx - 0.34) + (bny + 0.26) * (bny + 0.26)) - 0.26);
          const arcHighlight = (arcDist < 0.055 && bnx > 0.25 && bny < -0.05)
            ? (1.0 - arcDist / 0.055) * 0.42
            : 0.0;

          // Subtle internal quarter-seam running perpendicular across right hemisphere
          const qSeamDist = Math.abs(sy - 0.06 + sx * 0.18);
          const qSeamGroove = qSeamDist < 0.011 ? (1.0 - qSeamDist / 0.011) * 0.28 : 0.0;

          // Faint worn embossed circular brand stamp in upper-right quarter panel
          const stampDx = bnx - 0.46;
          const stampDy = bny + 0.12;
          const stampR = Math.sqrt(stampDx * stampDx + stampDy * stampDy);
          const isStampRing = (Math.abs(stampR - 0.16) < 0.009 || Math.abs(stampR - 0.125) < 0.008) && nMed > 0.38;

          const smoothGrain = (nFine - 0.5) * 0.08 + (nMicro - 0.5) * 0.06;
          K = 0.82 - 0.66 * bDiff - 0.72 * glossSpecCore - 0.28 * glossSpecHalo - arcHighlight + qSeamGroove + smoothGrain;

          // Steep flash falloff into inky shadow at bottom-right & far-right edge of ball
          if (bnx > 0.62 || bny > 0.48) {
            const shadowTerm = Math.max(0.0, (bnx * 0.65 + bny * 0.65) - 0.38);
            K = Math.min(0.96, K + shadowTerm * 0.55);
          }

          K = Math.max(0.0, Math.min(0.96, K));

          // Blown highlight bleaches out both black and red dots at the hottest flash core
          const bleach = Math.min(1.0, glossSpecCore * 1.35 + arcHighlight * 0.7);
          R = Math.max(0.02, (0.98 - bleach * 0.94) * (1.0 - K * 0.18));
          Y = isStampRing ? 0.85 : Math.max(0.02, (0.44 - bleach * 0.40) * (1.0 - K * 0.25));
          C = 0.26 * K * (1.0 - bleach);
          chalk = bleach > 0.45 ? bleach * 0.85 : (isStampRing ? 0.35 : 0.0);
        }

        // ===================================================================
        // CAST SHADOWS FROM GRIPPING FINGERS ONTO THE CRICKET BALL
        // ===================================================================
        // 1. Shadow under Index Finger (arching from upper-left to (552, 292))
        const shIdx1 = segInfo(x, y, 310, 305, 455, 268);
        const shIdx2 = segInfo(x, y, 455, 268, 565, 315);
        const dShIdx = Math.min(shIdx1.d, shIdx2.d);
        if (dShIdx < 48 && y > 235) {
          const sStrength = Math.pow(1.0 - dShIdx / 48.0, 1.5);
          K = Math.min(0.97, K + sStrength * 0.62);
          R *= (1.0 - sStrength * 0.45);
        }

        // 2. Shadow under Middle Finger (arching over crown to (692, 232))
        const shMid1 = segInfo(x, y, 400, 160, 575, 175);
        const shMid2 = segInfo(x, y, 575, 175, 702, 258);
        const dShMid = Math.min(shMid1.d, shMid2.d);
        if (dShMid < 52 && y > 135) {
          const sStrength = Math.pow(1.0 - dShMid / 52.0, 1.5);
          K = Math.min(0.97, K + sStrength * 0.64);
          R *= (1.0 - sStrength * 0.45);
        }

        // 3. Shadow above/around Thumb pressing into bottom seam (665, 895)
        const shThm = segInfo(x, y, 320, 885, 675, 880);
        if (shThm.d < 54 && y > 815) {
          const sStrength = Math.pow(1.0 - shThm.d / 54.0, 1.4);
          K = Math.min(0.97, K + sStrength * 0.58);
        }
      }

      // ---------------------------------------------------------------------
      // LAYER 3: GRIPPING FINGERS IN FRONT OF BALL (INDEX, MIDDLE, THUMB)
      // ---------------------------------------------------------------------
      // Define phalanges for Index, Middle, and Thumb
      // Index Finger (gripping left of upright seam)
      const idx1 = evalCapsule(x, y, 162, 422, 74, 318, 272, 58, 7);
      const idx2 = evalCapsule(x, y, 318, 272, 56, 448, 234, 48, 5);
      const idx3 = evalCapsule(x, y, 448, 234, 47, 554, 290, 41, 3);

      // Middle Finger (gripping right of upright seam)
      const mid1 = evalCapsule(x, y, 224, 242, 76, 408, 122, 61, 8);
      const mid2 = evalCapsule(x, y, 408, 122, 59, 574, 142, 50, 6);
      const mid3 = evalCapsule(x, y, 574, 142, 49, 692, 232, 43, 3);

      // Thumb (supporting bottom of upright seam)
      const thm1 = evalCapsule(x, y, 118, 825, 112, 312, 912, 78, 8);
      const thm2 = evalCapsule(x, y, 312, 912, 75, 496, 942, 63, 7);
      const thm3 = evalCapsule(x, y, 496, 942, 61, 668, 892, 49, 4);

      const frontSegments = [
        // Thumb segments
        { cap: thm1, finger: 3, seg: 1 },
        { cap: thm2, finger: 3, seg: 2 },
        { cap: thm3, finger: 3, seg: 3 },
        // Middle finger segments
        { cap: mid1, finger: 2, seg: 1 },
        { cap: mid2, finger: 2, seg: 2 },
        { cap: mid3, finger: 2, seg: 3 },
        // Index finger segments (drawn after middle so index overlaps middle base cleanly)
        { cap: idx1, finger: 1, seg: 1 },
        { cap: idx2, finger: 1, seg: 2 },
        { cap: idx3, finger: 1, seg: 3 }
      ];

      for (let f = 0; f < frontSegments.length; f++) {
        const item = frontSegments[f];
        const cap = item.cap;
        if (cap.inside) {
          zone = 1;
          let fnx = cap.nx;
          let fny = cap.ny;
          let fnz = cap.nz;

          let fDiff = Math.max(0.0, fnx * lx + fny * ly + fnz * lz);
          const fSpec = Math.pow(Math.max(0.0, fnx * 0.25 + fny * -0.25 + fnz * 0.93), 18.0);

          // -----------------------------------------------------------------
          // KNUCKLE CREASES (Concentric oval & transverse accordion skin folds)
          // -----------------------------------------------------------------
          let kCrease = 0.0;
          let kChalk = 0.0;

          // Proximal joint creases (t near 0.08..0.22)
          const dtA = cap.t - 0.14;
          const envA = Math.exp(-dtA * dtA * 48.0) * Math.exp(-cap.s * cap.s * 2.6);
          const waveA = Math.sin(dtA * 115.0 + cap.s * cap.s * 7.5 + nFine * 2.6);
          if (envA > 0.08) {
            kCrease += envA * (waveA > 0.15 ? 0.36 : -0.18);
            if (waveA < -0.15) kChalk += envA * 0.65;
          }

          // Distal joint creases (t near 0.84..0.96 on seg 1 and seg 2)
          if (item.seg <= 2) {
            const dtB = cap.t - 0.88;
            const envB = Math.exp(-dtB * dtB * 45.0) * Math.exp(-cap.s * cap.s * 2.4);
            const waveB = Math.sin(dtB * 125.0 - cap.s * cap.s * 8.5 + nFine * 2.8);
            if (envB > 0.08) {
              kCrease += envB * (waveB > 0.12 ? 0.38 : -0.20);
              if (waveB < -0.12) kChalk += envB * 0.72;
            }
          }

          // Fine transverse skin wrinkles along shaft of finger
          const microFold = Math.sin(cap.t * 68.0 + cap.s * cap.s * 3.5 + nMed * 4.0) * 0.06;

          // Underside shadow of finger (s > 0.25 faces downward toward the ball)
          const underShadow = cap.s > 0.18 ? Math.pow((cap.s - 0.18) / 0.82, 1.45) * 0.56 : 0.0;
          // Crisp contour rim shadow where finger overlaps another structure
          const rimCrevice = Math.pow(Math.abs(cap.s), 4.0) * 0.38;

          K = 0.68 - 0.62 * fDiff - 0.32 * fSpec + kCrease + microFold + underShadow + rimCrevice + (nFine - 0.5) * 0.09;
          R = 0.28 * (1.0 - K * 0.45) + (kCrease > 0.08 ? 0.16 : 0.0);
          Y = 0.64 * (1.0 - K * 0.32);
          C = 0.15 * K;
          chalk = kChalk + (fSpec > 0.32 ? 0.62 : 0.06);

          // -----------------------------------------------------------------
          // FINGERNAILS ON DISTAL PHALANGES (SEG 3)
          // -----------------------------------------------------------------
          if (item.seg === 3) {
            // Pressurized fingertip blood blush around pad
            if (cap.t > 0.45) R = Math.min(0.68, R + 0.22);

            // Nail plate sits on dorsal/upper half of distal segment:
            // t in [0.38, 0.88], s in [-0.62, 0.28]
            const nt = (cap.t - 0.63) / 0.25; // [-1..1] along nail
            const ns = (cap.s + 0.17) / 0.45; // [-1..1] across nail
            const nailShape = nt * nt * 0.85 + ns * ns;

            if (item.finger <= 2 && nailShape < 1.0) {
              if (nailShape > 0.78) {
                // Dark cuticle & lateral nail fold groove
                K = Math.min(0.92, K + 0.36);
                R = 0.38;
              } else {
                // Smooth hard keratin nail plate catching bright flash highlight
                const isLunula = nt < -0.32 && (nt + 0.55) * (nt + 0.55) + ns * ns * 0.7 < 0.28;
                const nailSpec = Math.pow(Math.max(0.0, fnz), 6.0) * 0.42;
                K = Math.max(0.01, 0.24 - nailSpec - (isLunula ? 0.12 : 0.0) + (nt > 0.55 ? -0.10 : 0.04));
                R = isLunula ? 0.12 : 0.34;
                Y = 0.28;
                C = 0.04;
                chalk = 0.78;
              }
            }
          }
        }
      }

      bufK[idx] = K;
      bufR[idx] = R;
      bufY[idx] = Y;
      bufC[idx] = C;
      bufChalk[idx] = chalk;
      bufZone[idx] = zone;
    }
  }

  // Bilinear buffer sampler for any canvas coordinate (x, y) in [0..1200]
  function sampleBuf(buf, x, y) {
    const gx = Math.max(0.0, Math.min(GW - 1.001, (x - 1.0) * 0.5));
    const gy = Math.max(0.0, Math.min(GH - 1.001, (y - 1.0) * 0.5));
    const ix = Math.floor(gx);
    const iy = Math.floor(gy);
    const fx = gx - ix;
    const fy = gy - iy;
    const i00 = iy * GW + ix;
    const v00 = buf[i00];
    const v10 = buf[i00 + 1];
    const v01 = buf[i00 + GW];
    const v11 = buf[i00 + GW + 1];
    return (v00 + fx * (v10 - v00)) + fy * ((v01 + fx * (v11 - v01)) - (v00 + fx * (v10 - v00)));
  }

  // =========================================================================
  // 4. VIVID SPOT-COLOR UNDER-WASH PLATES (WITH SLIGHT REGISTRATION DRIFT)
  // =========================================================================
  // In vintage back-page sports supplements, vivid red & golden-amber ink tints
  // sit slightly misregistered beneath the coarse black halftone key plate.
  const driftRedX = 6.5;
  const driftRedY = -4.5;

  brush.noStroke();
  brush.fillBleed(0.26, "out");
  brush.fillTexture(0.55, 0.35);

  // Vivid crimson-vermilion ink base on the cricket ball (shifted by registration drift)
  brush.fill("#e81915", 115);
  brush.circle(ballX + driftRedX, ballY + driftRedY, ballR * 0.97, 0.12);

  // Deeper blood-crimson saturation on the polished right hemisphere
  brush.fill("#b8060c", 95);
  brush.beginShape(0.45);
  for (let a = -72; a <= 82; a += 18) {
    const rad = a * Math.PI / 180.0;
    const px = ballX + driftRedX + Math.cos(rad) * ballR * 0.94;
    const py = ballY + driftRedY + Math.sin(rad) * ballR * 0.94;
    brush.vertex(px, py);
  }
  brush.vertex(ballX + 55, ballY + 280);
  brush.vertex(ballX + 20, ballY);
  brush.vertex(ballX - 25, ballY - 290);
  brush.endShape(true);

  // Fiery saturated vermilion-orange glow on the scuffed left hemisphere
  brush.fill("#ff3814", 82);
  brush.beginShape(0.45);
  for (let a = 108; a <= 252; a += 18) {
    const rad = a * Math.PI / 180.0;
    const px = ballX + driftRedX + Math.cos(rad) * ballR * 0.93;
    const py = ballY + driftRedY + Math.sin(rad) * ballR * 0.93;
    brush.vertex(px, py);
  }
  brush.vertex(ballX - 45, ballY - 270);
  brush.vertex(ballX + 10, ballY);
  brush.vertex(ballX + 40, ballY + 270);
  brush.endShape(true);

  // Knock out the blown flash highlight & white seam belt with warm newsprint cream wash
  brush.noFill();
  brush.wash("#f4e8c6", 185);
  brush.circle(ballX + 150, ballY - 125, 118, 0.35);
  brush.noWash();

  // =========================================================================
  // 5. HALFTONE GRID HELPER (ROTATED SCREEN + OPTICAL CONTACT-SCREEN PULL)
  // =========================================================================
  // Helper to iterate over a rotated halftone screen at angle `angDeg` and spacing `S`
  function renderHalftonePlate(angDeg, S, shiftX, shiftY, drawCellFn) {
    const rad = angDeg * Math.PI / 180.0;
    const cosA = Math.cos(rad);
    const sinA = Math.sin(rad);
    const cx = 600.0;
    const cy = 600.0;
    const halfSpan = 870.0; // Covers full 1200x1200 diagonal (1200 * sqrt(2) / 2 = 848.5)
    const steps = Math.ceil((halfSpan * 2.0) / S);

    for (let iu = -steps; iu <= steps; iu++) {
      const u = iu * S - halfSpan;
      for (let iv = -steps; iv <= steps; iv++) {
        const v = iv * S - halfSpan;
        const x = cx + u * cosA - v * sinA + shiftX;
        const y = cy + u * sinA + v * cosA + shiftY;
        if (x >= -6 && x <= 1206 && y >= -6 && y <= 1206) {
          drawCellFn(x, y, iu, iv, cosA, sinA);
        }
      }
    }
  }

  // Helper to stamp a single halftone dot at (x, y) with radius/weight `w` and angle `angRad`
  function stampDot(x, y, w, angRad) {
    const segHalf = Math.max(0.42, w * 0.32);
    const dx = Math.cos(angRad) * segHalf;
    const dy = Math.sin(angRad) * segHalf;
    brush.strokeWeight(w);
    brush.line(x - dx, y - dy, x + dx, y + dy);
  }

  // =========================================================================
  // 6. PLATE 1: WARM GOLDEN-AMBER & CORAL HALFTONE PLATE (ANGLE 72°, DRIFTED)
  // =========================================================================
  // Enriches skin tones, knuckle folds, and worn leather warmth
  brush.set("htColorDot", "#e0871f", 1.0);
  renderHalftonePlate(72.0, 13.5, -4.2, 3.2, (x, y) => {
    const sx = x + 4.2;
    const sy = y - 3.2;
    const yVal = sampleBuf(bufY, sx, sy);
    const kVal = sampleBuf(bufK, sx, sy);
    if (yVal > 0.20 && kVal < 0.84) {
      const w = (yVal - 0.14) * 1.65;
      stampDot(x, y, w, 1.25);
    }
  });

  // Deeper burnt coral-sienna plate in knuckle creases & warm shadows
  brush.set("htColorDot", "#c94418", 1.0);
  renderHalftonePlate(72.0, 13.5, -3.5, 2.8, (x, y) => {
    const sx = x + 3.5;
    const sy = y - 2.8;
    const yVal = sampleBuf(bufY, sx, sy);
    const rVal = sampleBuf(bufR, sx, sy);
    const kVal = sampleBuf(bufK, sx, sy);
    if (yVal > 0.35 && rVal > 0.24 && kVal > 0.22 && kVal < 0.80) {
      const w = (rVal * 0.8 + yVal * 0.5 - 0.25) * 1.45;
      if (w > 0.3) stampDot(x, y, w, 0.78);
    }
  });

  // =========================================================================
  // 7. PLATE 2: VIVID SATURATED RED/CRIMSON HALFTONE PLATE (ANGLE 17°, DRIFTED)
  // =========================================================================
  // Coarse saturated red halftone screen shifted (+6.5, -4.5) for authentic press misregistration
  // Pass A: Electric vermilion-red halftone dots
  brush.set("htColorDot", "#ff1e12", 1.0);
  renderHalftonePlate(17.0, 11.8, driftRedX, driftRedY, (x, y) => {
    const sx = x - driftRedX;
    const sy = y - driftRedY;
    const rVal = sampleBuf(bufR, sx, sy);
    const kVal = sampleBuf(bufK, sx, sy);
    if (rVal > 0.22 && kVal < 0.72) {
      const w = (rVal - 0.12) * 1.95;
      stampDot(x, y, w, 0.30);
    }
  });

  // Pass B: Deep saturated crimson ink dots in rich leather midtones & shadows
  brush.set("htDot", "#a8050d", 1.0);
  renderHalftonePlate(17.0, 11.8, driftRedX * 0.85, driftRedY * 0.85, (x, y) => {
    const sx = x - driftRedX * 0.85;
    const sy = y - driftRedY * 0.85;
    const rVal = sampleBuf(bufR, sx, sy);
    const kVal = sampleBuf(bufK, sx, sy);
    if (rVal > 0.48 && kVal > 0.18 && kVal < 0.86) {
      const w = (rVal - 0.35) * 2.15;
      stampDot(x, y, w, 0.30);
    }
  });

  // =========================================================================
  // 8. PLATE 3: REGISTRATION DRIFT GHOST PLATE (PRUSSIAN SLATE & SEPIA, 43.7°)
  // =========================================================================
  // Creates the unmistakable close-up double-dot rhythm & slight registration drift
  const ghostShiftX = 4.8;
  const ghostShiftY = -3.6;

  brush.set("htColorDot", "#1b394d", 1.0);
  renderHalftonePlate(43.7, 12.2, ghostShiftX, ghostShiftY, (x, y) => {
    const sx = x - ghostShiftX;
    const sy = y - ghostShiftY;
    const cVal = sampleBuf(bufC, sx, sy);
    const kVal = sampleBuf(bufK, sx, sy);
    if (cVal > 0.09 && kVal > 0.16 && kVal < 0.86) {
      const w = Math.min(1.65, (kVal - 0.10) * 1.45);
      stampDot(x, y, w, 0.76);
    }
  });

  // Warm dark umber/sepia registration ghost near high-contrast edges (stitches & knuckles)
  brush.set("htDot", "#381c11", 1.0);
  renderHalftonePlate(45.8, 11.6, -3.8, 2.9, (x, y) => {
    const sx = x + 3.8;
    const sy = y - 2.9;
    const k0 = sampleBuf(bufK, sx, sy);
    const kx = sampleBuf(bufK, sx + 5.0, sy);
    const ky = sampleBuf(bufK, sx, sy + 5.0);
    const grad = Math.abs(kx - k0) + Math.abs(ky - k0);
    if (grad > 0.14 && k0 > 0.12 && k0 < 0.82) {
      const w = Math.min(1.5, grad * 2.4 + k0 * 0.55);
      stampDot(x, y, w, 0.80);
    }
  });

  // =========================================================================
  // 9. PLATE 4: MASTER COARSE BLACK HALFTONE KEY PLATE (ANGLE 45°, S = 11.6px)
  // =========================================================================
  // Optical contact-screen sub-sampling pulls dots toward sharp stitch & knuckle edges
  // while preserving the strict 45° coarse halftone dot matrix.
  const keySpacing = 11.6;

  // Pass 4A: Deepest inky shadow under-bridging (where K > 0.74, dots merge into solid ink)
  brush.set("htDot", "#12100e", 1.0);
  renderHalftonePlate(45.0, keySpacing, 0.0, 0.0, (x, y, iu, iv, cosA, sinA) => {
    const k0 = sampleBuf(bufK, x, y);
    if (k0 > 0.64) {
      // Check neighboring cells along +u and +v screen axes for dot-gain bridging
      const nx1 = x + keySpacing * cosA;
      const ny1 = y + keySpacing * sinA;
      const k1 = sampleBuf(bufK, nx1, ny1);
      if (k1 > 0.64) {
        const bridgeW = Math.min(2.6, ((k0 + k1) * 0.5 - 0.56) * 5.8);
        brush.strokeWeight(bridgeW);
        brush.line(x, y, nx1, ny1);
      }

      const nx2 = x - keySpacing * sinA;
      const ny2 = y + keySpacing * cosA;
      const k2 = sampleBuf(bufK, nx2, ny2);
      if (k2 > 0.64) {
        const bridgeW = Math.min(2.6, ((k0 + k2) * 0.5 - 0.56) * 5.8);
        brush.strokeWeight(bridgeW);
        brush.line(x, y, nx2, ny2);
      }
    }
  });

  // Pass 4B: Primary swelling & shrinking black halftone dots across entire 1200x1200 frame
  brush.set("htDot", "#0c0b09", 1.0);
  renderHalftonePlate(45.0, keySpacing, 0.0, 0.0, (x, y) => {
    // 5-point optical contact screen sample inside the halftone cell
    const d = 2.8;
    const kC = sampleBuf(bufK, x, y);
    const kR = sampleBuf(bufK, x + d, y);
    const kL = sampleBuf(bufK, x - d, y);
    const kD = sampleBuf(bufK, x, y + d);
    const kU = sampleBuf(bufK, x, y - d);

    const kAvg = 0.40 * kC + 0.15 * (kR + kL + kD + kU);

    // Blown highlights (kAvg < 0.045) drop out completely to reveal pure paper/chalk!
    if (kAvg < 0.045) return;

    // Optical edge pull: dot centroid shifts slightly toward the darker side of sharp edges
    const gx = kR - kL;
    const gy = kD - kU;
    const pullX = Math.max(-2.6, Math.min(2.6, gx * 4.2));
    const pullY = Math.max(-2.6, Math.min(2.6, gy * 4.2));

    // Slight newsprint fiber jitter
    const jx = (vnoise(x * 0.17, y * 0.17) - 0.5) * 0.85;
    const jy = (vnoise(x * 0.17 + 31.0, y * 0.17 + 19.0) - 0.5) * 0.85;

    const px = x + pullX + jx;
    const py = y + pullY + jy;

    // Non-linear halftone dot swelling curve:
    // Pinpricks in highlights -> crisp round dots in midtones -> swollen heavy dots in shadows
    let dotW;
    if (kAvg < 0.20) {
      dotW = 0.22 + (kAvg - 0.045) * 3.2;
    } else if (kAvg < 0.65) {
      dotW = 0.72 + (kAvg - 0.20) * 3.45;
    } else {
      dotW = 2.27 + (kAvg - 0.65) * 3.8;
    }

    // Orient dot slightly along isophote (perpendicular to gradient) on sharp creases/stitches
    const gradMag = Math.sqrt(gx * gx + gy * gy);
    const ang = gradMag > 0.08 ? Math.atan2(gy, gx) + Math.PI * 0.5 : 0.785;

    stampDot(px, py, dotW, ang);
  });

  // =========================================================================
  // 10. REVERSE HALFTONE PINHOLES IN DARK SHADOW CROSSOVER ZONE (0.66 < K < 0.90)
  // =========================================================================
  // Where black dots bridge together in dark shadows, tiny diamond/round pinholes of
  // yellowed newsprint or vivid red ball ink remain at the dual grid centers (iu+0.5, iv+0.5)!
  const halfKey = keySpacing * 0.5;

  // Paper-toned reverse pinholes on skin, seam, and background shadows
  brush.set("htDot", "#efe1ba", 1.0);
  renderHalftonePlate(45.0, keySpacing, halfKey * Math.SQRT1_2, 0.0, (x, y) => {
    const kVal = sampleBuf(bufK, x, y);
    const rVal = sampleBuf(bufR, x, y);
    if (kVal > 0.66 && kVal < 0.90 && rVal < 0.45) {
      const pinholeW = (0.91 - kVal) * 4.2;
      stampDot(x, y, pinholeW, 0.785);
    }
  });

  // Vivid crimson-red reverse pinholes in the dark shadow side of the cricket ball
  brush.set("htDot", "#e31b15", 1.0);
  renderHalftonePlate(45.0, keySpacing, halfKey * Math.SQRT1_2, 0.0, (x, y) => {
    const kVal = sampleBuf(bufK, x, y);
    const rVal = sampleBuf(bufR, x, y);
    if (kVal > 0.64 && kVal < 0.89 && rVal >= 0.45) {
      const pinholeW = (0.90 - kVal) * 4.5;
      stampDot(x, y, pinholeW, 0.785);
    }
  });

  // =========================================================================
  // 11. CHALKY DUST, SCUFF FLECKS & BLOWN FLASH HIGHLIGHT STIPPLE
  // =========================================================================
  // Crisp chalk dust rubbed into knuckle creases, raised seam stitches, and rough leather scuffs
  brush.set("chalkFleck", "#faf2dc", 1.0);
  renderHalftonePlate(28.0, 8.5, 0.0, 0.0, (x, y) => {
    const ch = sampleBuf(bufChalk, x, y);
    const kVal = sampleBuf(bufK, x, y);
    if (ch > 0.34 && kVal < 0.55) {
      const n = vnoise(x * 0.23, y * 0.23);
      if (n > 0.36) {
        const w = (ch - 0.25) * 1.65 * n;
        const jx = (n - 0.5) * 3.5;
        const jy = (vnoise(y * 0.23, x * 0.23) - 0.5) * 3.5;
        stampDot(x + jx, y + jy, w, n * Math.PI);
      }
    }
  });

  // Pure bright chalk highlights on the crown of the 6-stitch seam, fingernails & flash dome
  brush.set("chalkFleck", "#fffdf7", 1.0);
  renderHalftonePlate(62.0, 9.2, 0.0, 0.0, (x, y) => {
    const ch = sampleBuf(bufChalk, x, y);
    const kVal = sampleBuf(bufK, x, y);
    if (ch > 0.58 && kVal < 0.24) {
      const n = vnoise(x * 0.31 + 11.0, y * 0.31 + 7.0);
      if (n > 0.42) {
        const w = (ch - 0.42) * 1.85;
        stampDot(x, y, w, n * Math.PI);
      }
    }
  });

  // Fine ink-splatter & micro-stipple along the sharpest seam stitches and scuffed leather gouges
  brush.set("rotring", "#141210", 0.85);
  for (let i = 0; i < 650; i++) {
    const sx = random(280, 980);
    const sy = random(110, 980);
    const kVal = sampleBuf(bufK, sx, sy);
    const ch = sampleBuf(bufChalk, sx, sy);
    if (kVal > 0.35 && kVal < 0.82 && ch > 0.18) {
      const ang = random(0, 360);
      const len = random(1.5, 4.5);
      brush.line(
        sx,
        sy,
        sx + cos(ang) * len,
        sy + sin(ang) * len
      );
    }
  }

  noLoop();
}

