// Box 3D coordinate system constants
const BOX_CX = 582;
const BOX_CY = 772;
constCELL_W = 106;
const CELL_D = 104;

// Projection helper: maps 3D box coordinates (u, v, w) to 2D canvas (x, y)
// u: left-to-right (-212..+212), v: back-to-front (-156..+156), w: vertical height
function projBox(u, v, w = 0) {
  const persp = 1 + v * 0.00042 - w * 0.00015;
  const uu = u * persp;
  const vv = v * persp;
  const x = BOX_CX + uu * 0.955 + vv * 0.285;
  const y = BOX_CY - uu * 0.195 + vv * 0.675 - w * 0.80;
  return [x, y];
}

// Projection helper for the open hinged lid
// uL: along hinge (-232..+232), sL: distance up the lid (0..336), tL: thickness normal (-20..+20)
function projLid(uL, sL, tL = 0) {
  const hingeV = -168;
  const hingeW = 44;
  const base = projBox(uL, hingeV, hingeW);
  const persp = 1 - sL * 0.00018;
  const x = base[0] * persp + (1 - persp) * BOX_CX - sL * 0.145 + tL * 0.26;
  const y = base[1] - sL * 0.905 + tL * 0.62;
  return [x, y];
}

