  drawOpenBoxLid();

  // 4. Open box tray back walls, interior lining & paper lace doilies
  drawBoxTrayBackStructure();

  // 5. All 12 compartments, fluted gold-foil cups & hyperreal chocolates (sorted back-to-front)
  drawAllCompartmentsAndChocolates();

  // 6. Front & left exterior box walls with embossed gilt Greek-key trim
  drawBoxTrayFrontStructure();

