// =============================================================================
// GEOMETRY & DRAWING UTILITIES
// =============================================================================

function resetBrushStates() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function polyShape(pts, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function washPoly(pts, col, opacity = 220, curvature = 0) {
  resetBrushStates();
  brush.wash(col, opacity);
  polyShape(pts, curvature);
  resetBrushStates();
}

function washAndHatchPoly(pts, washCol, washOp, hatchBrush, hatchCol, hatchW, dist, ang, rand = 0.04, curvature = 0) {
  resetBrushStates();
  if (washCol) brush.wash(washCol, washOp);
  brush.hatchStyle(hatchBrush, hatchCol, hatchW);
  brush.hatch(dist, ang, { rand: rand });
  polyShape(pts, curvature);
  resetBrushStates();
}

function hatchOnlyPoly(pts, hatchBrush, hatchCol, hatchW, dist, ang, rand = 0.04, curvature = 0) {
  resetBrushStates();
  brush.hatchStyle(hatchBrush, hatchCol, hatchW);
  brush.hatch(dist, ang, { rand: rand });
  polyShape(pts, curvature);
  resetBrushStates();
}

function strokePoly(pts, brushName, col, weight, curvature = 0, closed = true) {
  resetBrushStates();
  brush.set(brushName, col, weight);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
  resetBrushStates();
}

function stippleRegion(cx, cy, rx, ry, rotDeg, brushName, col, weight, count, biasAngle = null) {
  resetBrushStates();
  brush.set(brushName, col, weight);
  const c = cos(rotDeg);
  const s = sin(rotDeg);
  for (let i = 0; i < count; i++) {
    let a = biasAngle !== null ? biasAngle + randomGaussian(0, 48) : random(360);
    let r = sqrt(random()) * random(0.25, 1.0);
    let lx = cos(a) * rx * r;
    let ly = sin(a) * ry * r;
    let px = cx + lx * c - ly * s;
    let py = cy + lx * s + ly * c;
    let len = random(1.5, 5.5);
    let dir = a + 90 + random(-25, 25);
    brush.line(px, py, px + cos(dir) * len, py + sin(dir) * len);
  }
  resetBrushStates();
}

function lerpPt(p1, p2, t) {
  return [lerp(p1[0], p2[0], t), lerp(p1[1], p2[1], t)];
}

function bilerpQuad(q, u, v) {
  // q = [topLeft, topRight, bottomRight, bottomLeft]
  const top = lerpPt(q[0], q[1], u);
  const bot = lerpPt(q[3], q[2], u);
  return lerpPt(top, bot, v);
}

