function drawLithoGroundAndBackdrop() {
  // Base warm stone wash inside frame
  const innerRect = [[85, 85], [1115, 85], [1115, 1115], [85, 1115]];
  washPoly(innerRect, PAL.paperWarm, 150);

  // Upper wall in deep Prussian Blue chromolitho plates
  const horizonL = 625;
  const horizonR = 540;
  const wallPts = [[85, 85], [1115, 85], [1115, horizonR], [85, horizonL]];

  washAndHatchPoly(
    wallPts,
    PAL.prussianDeep, 235,
    "engraver", PAL.prussianDark, 0.85,
    5.5, 32, 0.03
  );

  // Second cross-hatch pass on Prussian blue wall
  hatchOnlyPoly(wallPts, "engraver", PAL.prussianMid, 0.65, 7.5, -38, 0.04);

  // Darker upper corners vignette in Prussian Dark + Umber Black
  const upperArchPts = [
    [85, 85], [1115, 85], [1115, 420],
    [940, 270], [600, 195], [260, 270], [85, 460]
  ];
  washAndHatchPoly(
    upperArchPts,
    PAL.prussianDark, 185,
    "engraver", PAL.umberBlack, 0.8,
    5.0, -15, 0.03
  );

  // Radiant light halo behind the open lid & box
  for (let r = 420; r >= 140; r -= 55) {
    let pts = [];
    for (let a = 0; a < 360; a += 15) {
      pts.push([545 + cos(a) * r * 1.18, 495 + sin(a) * r * 0.88]);
    }
    let col = r > 280 ? PAL.prussianMid : PAL.prussianSoft;
    washPoly(pts, col, 48, 0.3);
  }

  // Subtle Victorian wallpaper arabesque diamonds on the Prussian blue wall
  resetBrushStates();
  for (let gx = 130; gx <= 1070; gx += 76) {
    for (let gy = 130; gy <= 540; gy += 76) {
      if (gy > lerp(horizonL, horizonR, (gx - 85) / 1030) - 28) continue;
      let dFromCenter = dist(gx, gy, 535, 420);
      let motifCol = dFromCenter < 320 ? PAL.prussianPale : PAL.prussianSoft;
      brush.set("engraver", motifCol, 0.55);
      let dm = [
        [gx, gy - 32], [gx + 26, gy], [gx, gy + 32], [gx - 26, gy]
      ];
      strokePoly(dm, "engraver", motifCol, 0.5, 0.15, true);

      // Small gilt & rose rosette at diamond center
      brush.set("engraver", PAL.goldAntique, 0.6);
      brush.circle(gx, gy, 7, 0.1);
      brush.set("litho_fine", PAL.goldOchre, 0.65);
      for (let a = 0; a < 360; a += 90) {
        brush.line(gx + cos(a) * 4, gy + sin(a) * 4, gx + cos(a) * 12, gy + sin(a) * 12);
      }
    }
  }

  // Lower table surface in rich claret-rose, gilt ochre & chocolate umber damask
  const tablePts = [[85, horizonL], [1115, horizonR], [1115, 1115], [85, 1115]];
  washAndHatchPoly(
    tablePts,
    PAL.claretDeep, 210,
    "engraver", PAL.claretBlack, 0.75,
    6.0, 14, 0.03
  );
  hatchOnlyPoly(tablePts, "litho_chalk", PAL.roseMid, 0.55, 9.5, -52, 0.05);

  // Perspective woven damask grid on the tablecloth
  resetBrushStates();
  for (let u = -6; u <= 8; u++) {
    let p1 = projBox(u * 95, -240, -18);
    let p2 = projBox(u * 95, 360, -18);
    brush.set("engraver", PAL.goldAntique, 0.55);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.set("engraver", PAL.roseSoft, 0.4);
    brush.line(p1[0] + 4, p1[1], p2[0] + 4, p2[1]);
  }
  for (let v = -2; v <= 4; v++) {
    let p1 = projBox(-580, v * 95, -18);
    let p2 = projBox(680, v * 95, -18);
    brush.set("engraver", PAL.goldAntique, 0.5);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Carved gilt & umber wainscoting molding along the horizon line
  const dadoTopL = [85, horizonL - 14];
  const dadoTopR = [1115, horizonR - 14];
  const dadoBotR = [1115, horizonR + 12];
  const dadoBotL = [85, horizonL + 12];
  washPoly([dadoTopL, dadoTopR, dadoBotR, dadoBotL], PAL.umberDark, 235);

  resetBrushStates();
  brush.set("cpencil", PAL.goldOchre, 1.3);
  brush.line(dadoTopL[0], dadoTopL[1], dadoTopR[0], dadoTopR[1]);
  brush.set("engraver", PAL.goldPale, 0.9);
  brush.line(dadoTopL[0], dadoTopL[1] + 3, dadoTopR[0], dadoTopR[1] + 3);
  brush.set("cpencil", PAL.goldAntique, 1.1);
  brush.line(dadoBotL[0], dadoBotL[1] - 4, dadoBotR[0], dadoBotR[1] - 4);
  brush.set("engraver", PAL.umberBlack, 1.0);
  brush.line(dadoBotL[0], dadoBotL[1], dadoBotR[0], dadoBotR[1]);
}

