// =============================================================================
// 3. OPEN HINGED LID: ORNATE CARTOUCHE, ROSES & EMBOSSED LETTERING
// =============================================================================

function drawOpenBoxLid() {
  const U = 232;
  const S = 338;

  // Back/left thickness bevel of the open lid (in deep gold & claret shadow)
  const backRimPts = [
    projLid(-U, 0, -18),
    projLid(-U, S, -18),
    projLid(U, S, -18),
    projLid(U, S, 0),
    projLid(-U, S, 0),
    projLid(-U, 0, 0)
  ];
  washAndHatchPoly(
    backRimPts,
    PAL.goldShadow, 240,
    "engraver", PAL.umberBlack, 0.8,
    4.0, 45, 0.02
  );

  // Outer gilded frame of the lid interior face
  const lidOuter = [
    projLid(-U, 0, 0),
    projLid(U, 0, 0),
    projLid(U, S, 0),
    projLid(-U, S, 0)
  ];
  washAndHatchPoly(
    lidOuter,
    PAL.goldOchre, 235,
    "engraver", PAL.goldAntique, 0.65,
    5.0, -25, 0.03
  );

  // Claret velvet inner border band on lid
  const b1 = 16;
  const lidClaretBand = [
    projLid(-U + b1, b1, 1),
    projLid(U - b1, b1, 1),
    projLid(U - b1, S - b1, 1),
    projLid(-U + b1, S - b1, 1)
  ];
  washAndHatchPoly(
    lidClaretBand,
    PAL.claretDeep, 240,
    "engraver", PAL.claretBlack, 0.7,
    4.5, 18, 0.03
  );

  // Gold inner molding
  const b2 = 30;
  const lidGoldInner = [
    projLid(-U + b2, b2, 2),
    projLid(U - b2, b2, 2),
    projLid(U - b2, S - b2, 2),
    projLid(-U + b2, S - b2, 2)
  ];
  washPoly(lidGoldInner, PAL.goldBright, 230);

  // Padded antique silk ivory card panel inside lid
  const b3 = 38;
  const lidSilkCard = [
    projLid(-U + b3, b3, 2),
    projLid(U - b3, b3, 2),
    projLid(U - b3, S - b3, 2),
    projLid(-U + b3, S - b3, 2)
  ];
  washAndHatchPoly(
    lidSilkCard,
    PAL.paper, 248,
    "litho_fine", PAL.paperWarm, 0.55,
    6.0, -18, 0.04
  );

  // Subtle diagonal diamond quilting & stipple shading on the silk card
  hatchOnlyPoly(lidSilkCard, "engraver", PAL.paperShadow, 0.45, 18, 34, 0.02);
  hatchOnlyPoly(lidSilkCard, "engraver", PAL.paperShadow, 0.45, 18, -52, 0.02);

  // Crisp double-ruled gilt & umber borders around lid panels
  strokePoly(lidOuter, "engraver", PAL.umberBlack, 1.1);
  strokePoly(lidClaretBand, "engraver", PAL.goldPale, 0.9);
  strokePoly(lidGoldInner, "engraver", PAL.goldShadow, 0.85);
  strokePoly(lidSilkCard, "engraver", PAL.goldAntique, 0.85);

  // Inner filigree frame with corner fans
  const b4 = 52;
  const lidFiligree = [
    projLid(-U + b4, b4, 2),
    projLid(U - b4, b4, 2),
    projLid(U - b4, S - b4, 2),
    projLid(-U + b4, S - b4, 2)
  ];
  strokePoly(lidFiligree, "engraver", PAL.prussianMid, 0.65);

  // Ornate Victorian corner spandrels on the lid silk card
  const corners = [
    [-U + 56, 56, 1, 1],
    [U - 56, 56, -1, 1],
    [U - 56, S - 56, -1, -1],
    [-U + 56, S - 56, 1, -1]
  ];
  for (let [cu, cs, du, ds] of corners) {
    drawLidCornerOrnament(cu, cs, du, ds);
  }

  // Central Prussian Blue & Gold Oval Cartouche on the Lid
  const cartoucheS = 176;
  const rxU = 148;
  const ryS = 96;

  // Outer scalloped gilt wreath of cartouche
  let wreathPts = [];
  for (let i = 0; i < 48; i++) {
    let a = (i / 48) * 360;
    let rMod = (i % 2 === 0) ? 1.08 : 0.98;
    wreathPts.push(projLid(cos(a) * rxU * rMod, cartoucheS + sin(a) * ryS * rMod, 3));
  }
  washAndHatchPoly(
    wreathPts,
    PAL.goldOchre, 235,
    "engraver", PAL.goldShadow, 0.7,
    4.0, 35, 0.03, 0.25
  );
  strokePoly(wreathPts, "engraver", PAL.umberBlack, 0.8, 0.25);

  // Bright gold bevel ring
  let ringPts = [];
  for (let a = 0; a < 360; a += 10) {
    ringPts.push(projLid(cos(a) * rxU * 0.94, cartoucheS + sin(a) * ryS * 0.94, 3));
  }
  washPoly(ringPts, PAL.goldPale, 225, 0.3);
  strokePoly(ringPts, "engraver", PAL.goldAntique, 0.75, 0.3);

  // Deep Prussian Blue oval core inside cartouche
  let corePts = [];
  for (let a = 0; a < 360; a += 10) {
    corePts.push(projLid(cos(a) * rxU * 0.86, cartoucheS + sin(a) * ryS * 0.86, 3));
  }
  washAndHatchPoly(
    corePts,
    PAL.prussianDeep, 240,
    "engraver", PAL.prussianDark, 0.75,
    4.0, -22, 0.02, 0.3
  );
  hatchOnlyPoly(corePts, "engraver", PAL.prussianMid, 0.55, 6.5, 58, 0.03, 0.3);
  strokePoly(corePts, "engraver", PAL.goldBright, 1.0, 0.3);

  // Decorative Victorian Rose garlands at top and bottom of the cartouche
  drawLidRoseCluster(0, cartoucheS + ryS * 0.96, 1.0);
  drawLidRoseCluster(0, cartoucheS - ryS * 0.96, 0.88);
  drawLidRoseCluster(-rxU * 0.95, cartoucheS, 0.72);
  drawLidRoseCluster(rxU * 0.95, cartoucheS, 0.72);

  // Royal Heraldic Crown above the lettering inside the cartouche
  drawLidCrown(0, cartoucheS + 52);

  // Embossed Gilt Lettering on the Lid:
  // Curved upper banner: "CHOCOLATS"
  drawEmbossedLidString("CHOCOLATS", 0, cartoucheS + 14, 15.5, 21, 0.16);
  // Center banner in claret ribbon: "DE LUXE"
  drawLidRibbonScroll(0, cartoucheS - 19, 108, 17);
  drawEmbossedLidString("DE LUXE", 0, cartoucheS - 19, 12.5, 15, 0.0);
  // Lower small gold lettering: "LONDON"
  drawEmbossedLidString("LONDON", 0, cartoucheS - 48, 10.5, 12, -0.10);

  // Hinged crease shadow & brass hinges along sL = 0
  const hingeShadow = [
    projLid(-U, -4, 0),
    projLid(U, -4, 0),
    projLid(U, 14, 2),
    projLid(-U, 14, 2)
  ];
  washPoly(hingeShadow, PAL.umberBlack, 210);

  for (let hu of [-145, 0, 145]) {
    let hp = [
      projLid(hu - 22, -3, 2),
      projLid(hu + 22, -3, 2),
      projLid(hu + 22, 9, 3),
      projLid(hu - 22, 9, 3)
    ];
    washPoly(hp, PAL.goldBright, 240);
    strokePoly(hp, "engraver", PAL.umberBlack, 0.85);
  }
}

function drawLidCornerOrnament(cu, cs, du, ds) {
  resetBrushStates();
  // Gilt & Prussian blue fan shell in each corner of the lid
  let p0 = projLid(cu, cs, 3);
  for (let i = 0; i <= 5; i++) {
    let a = (i / 5) * 90;
    let r = (i === 2 || i === 3) ? 44 : 34;
    let p1 = projLid(cu + cos(a) * r * du, cs + sin(a) * r * ds, 3);
    brush.set("cpencil", PAL.goldOchre, 1.1);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
    brush.set("engraver", PAL.prussianDeep, 0.65);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
    brush.set("engraver", PAL.roseMid, 0.8);
    brush.circle(p1[0], p1[1], 3.5, 0.1);
  }
  brush.set("cpencil", PAL.claretRich, 1.1);
  brush.circle(p0[0], p0[1], 7, 0.1);
  brush.set("engraver", PAL.goldPale, 0.8);
  brush.circle(p0[0], p0[1], 4, 0.1);
  resetBrushStates();
}

function drawLidRoseCluster(cu, cs, sc) {
  // Olive-pistachio leaves behind roses
  const leafAngles = [-155, -25, 25, 155, -110, 110];
  for (let a of leafAngles) {
    let tipU = cu + cos(a) * 38 * sc;
    let tipS = cs + sin(a) * 24 * sc;
    let mid1 = projLid(cu + cos(a - 22) * 20 * sc, cs + sin(a - 22) * 14 * sc, 3);
    let mid2 = projLid(cu + cos(a + 22) * 20 * sc, cs + sin(a + 22) * 14 * sc, 3);
    let pBase = projLid(cu, cs, 3);
    let pTip = projLid(tipU, tipS, 3);
    washPoly([pBase, mid1, pTip, mid2], PAL.pistachioDark, 225, 0.25);
    washPoly([pBase, mid1, pTip], PAL.pistachioMid, 195, 0.2);
    strokePoly([pBase, mid1, pTip, mid2], "engraver", PAL.umberDark, 0.55, 0.25);
  }

  // Central cabochon rose + two side buds
  const buds = [
    [cu - 18 * sc, cs - 3 * sc, 11 * sc],
    [cu + 18 * sc, cs - 3 * sc, 11 * sc],
    [cu, cs, 16 * sc]
  ];
  for (let [bu, bs, rad] of buds) {
    let cPt = projLid(bu, bs, 4);
    let outer = [];
    for (let a = 0; a < 360; a += 30) {
      let r = rad * (1 + 0.12 * sin(a * 5));
      outer.push(projLid(bu + cos(a) * r, bs + sin(a) * r * 0.85, 4));
    }
    washPoly(outer, PAL.claretRich, 235, 0.3);
    strokePoly(outer, "engraver", PAL.claretBlack, 0.6, 0.3);

    // Concentric rose petals in roseMid, roseSoft, rosePale
    resetBrushStates();
    for (let ring = 0.78; ring >= 0.22; ring -= 0.24) {
      let col = ring > 0.6 ? PAL.roseMid : (ring > 0.38 ? PAL.roseSoft : PAL.rosePale);
      brush.set("cpencil", col, 1.3 * sc);
      for (let a = 0; a < 360; a += 90) {
        let aOff = a + ring * 140;
        let p1 = projLid(bu + cos(aOff) * rad * ring, bs + sin(aOff) * rad * ring * 0.8, 4);
        let p2 = projLid(bu + cos(aOff + 55) * rad * ring, bs + sin(aOff + 55) * rad * ring * 0.8, 4);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }
    brush.set("engraver", PAL.goldPale, 0.75);
    brush.circle(cPt[0], cPt[1], 2.5 * sc, 0.1);
  }
  resetBrushStates();
}

function drawLidCrown(cu, cs) {
  const crownPts = [
    projLid(cu - 22, cs - 8, 4),
    projLid(cu - 28, cs + 10, 4),
    projLid(cu - 14, cs + 3, 4),
    projLid(cu, cs + 15, 4),
    projLid(cu + 14, cs + 3, 4),
    projLid(cu + 28, cs + 10, 4),
    projLid(cu + 22, cs - 8, 4)
  ];
  washPoly(crownPts, PAL.goldBright, 240);
  strokePoly(crownPts, "engraver", PAL.umberBlack, 0.75);
  resetBrushStates();
  brush.set("cpencil", PAL.goldSpecular, 1.0);
  for (let du of [-26, -13, 0, 13, 26]) {
    let p = projLid(cu + du, cs + (du === 0 ? 15 : 8), 4);
    brush.circle(p[0], p[1], 2.5, 0.1);
  }
  resetBrushStates();
}

function drawLidRibbonScroll(cu, cs, halfW, halfH) {
  let pts = [];
  for (let i = 0; i <= 12; i++) {
    let t = (i / 12) * 2 - 1;
    let wave = sin(t * 90) * 3;
    pts.push(projLid(cu + t * halfW, cs + halfH + wave, 4));
  }
  for (let i = 12; i >= 0; i--) {
    let t = (i / 12) * 2 - 1;
    let wave = sin(t * 90) * 3;
    pts.push(projLid(cu + t * halfW, cs - halfH + wave, 4));
  }
  washPoly(pts, PAL.claretDeep, 240);
  strokePoly(pts, "cpencil", PAL.goldBright, 1.05);
  strokePoly(pts, "engraver", PAL.umberBlack, 0.65);
}

// Vector glyph definitions for embossed Victorian lid lettering
const GLYPHS = {
  'C': [[[0.85,0.2],[0.6,0.0],[0.2,0.0],[0.0,0.25],[0.0,0.75],[0.2,1.0],[0.6,1.0],[0.85,0.8]]],
  'H': [[[0,0],[0,1]], [[0.85,0],[0.85,1]], [[0,0.5],[0.85,0.5]]],
  'O': [[[0.2,0],[0.65,0],[0.85,0.25],[0.85,0.75],[0.65,1],[0.2,1],[0,0.75],[0,0.25],[0.2,0]]],
  'L': [[[0,1],[0,0],[0.8,0]]],
  'A': [[[0,0],[0.42,1],[0.85,0]], [[0.15,0.35],[0.7,0.35]]],
  'T': [[[0.42,0],[0.42,1]], [[0,1],[0.85,1]]],
  'S': [[[0.8,0.18],[0.55,0],[0.15,0],[0,0.2],[0.15,0.45],[0.7,0.55],[0.85,0.78],[0.65,1],[0.2,1],[0.05,0.82]]],
  'D': [[[0,0],[0,1],[0.55,1],[0.85,0.75],[0.85,0.25],[0.55,0],[0,0]]],
  'E': [[[0.8,0],[0,0],[0,1],[0.8,1]], [[0,0.5],[0.6,0.5]]],
  'U': [[[0,1],[0,0.22],[0.2,0],[0.65,0],[0.85,0.22],[0.85,1]]],
  'X': [[[0,0],[0.85,1]], [[0,1],[0.85,0]]],
  'N': [[[0,0],[0,1],[0.85,0],[0.85,1]]],
  ' ': []
};

function drawEmbossedLidString(str, centerU, centerS, charW, charH, archFactor = 0) {
  resetBrushStates();
  const n = str.length;
  const totalW = n * charW * 1.25;
  const startU = centerU - totalW / 2;

  // 3 passes: 1) Umber drop-shadow, 2) Gold ochre body, 3) Bright specular highlight
  const passes = [
    { du: 2.2, ds: -2.4, brush: "cpencil", col: PAL.umberBlack, w: 1.5 },
    { du: 0.0, ds: 0.0,  brush: "cpencil", col: PAL.goldBright, w: 1.45 },
    { du: -1.1, ds: 1.2, brush: "engraver", col: PAL.goldSpecular, w: 0.85 }
  ];

  for (let pass of passes) {
    brush.set(pass.brush, pass.col, pass.w);
    for (let i = 0; i < n; i++) {
      let ch = str[i];
      let strokes = GLYPHS[ch];
      if (!strokes) continue;
      let u0 = startU + i * charW * 1.25;
      let normX = (i - (n - 1) / 2) / max(1, (n - 1) / 2);
      let archS = (1 - normX * normX) * archFactor * 75;

      for (let st of strokes) {
        for (let k = 0; k < st.length - 1; k++) {
          let p1 = projLid(
            u0 + st[k][0] * charW + pass.du,
            centerS + (st[k][1] - 0.5) * charH + archS + pass.ds,
            4
          );
          let p2 = projLid(
            u0 + st[k + 1][0] * charW + pass.du,
            centerS + (st[k + 1][1] - 0.5) * charH + archS + pass.ds,
            4
          );
          brush.line(p1[0], p1[1], p2[0], p2[1]);
        }
      }
    }
  }
  resetBrushStates();
}

