function drawBoxTrayBackStructure() {
  const U = 212;
  const V = 156;
  const rimW = 46;
  const wallT = 16;

  // Interior floor of the box tray
  const floorPts = [
    projBox(-U, -V, 0),
    projBox(U, -V, 0),
    projBox(U, V, 0),
    projBox(-U, V, 0)
  ];
  washPoly(floorPts, PAL.umberBlack, 245);

  // Back interior wall (v = -V, w = 0..rimW)
  const backInnerWall = [
    projBox(-U, -V, 0),
    projBox(U, -V, 0),
    projBox(U, -V, rimW),
    projBox(-U, -V, rimW)
  ];
  washAndHatchPoly(
    backInnerWall,
    PAL.umberDark, 240,
    "engraver", PAL.umberBlack, 0.8,
    4.0, 12, 0.02
  );

  // Right interior wall (u = +U, w = 0..rimW)
  const rightInnerWall = [
    projBox(U, -V, 0),
    projBox(U, V, 0),
    projBox(U, V, rimW),
    projBox(U, -V, rimW)
  ];
  washAndHatchPoly(
    rightInnerWall,
    PAL.claretDeep, 240,
    "engraver", PAL.umberBlack, 0.85,
    4.0, -35, 0.02
  );

  // Top gilded rim ledges for Back wall and Right wall
  const backRimTop = [
    projBox(-U - wallT, -V - wallT, rimW),
    projBox(U + wallT, -V - wallT, rimW),
    projBox(U, -V, rimW),
    projBox(-U, -V, rimW)
  ];
  washPoly(backRimTop, PAL.goldOchre, 240);
  strokePoly(backRimTop, "engraver", PAL.umberBlack, 0.8);

  const rightRimTop = [
    projBox(U, -V, rimW),
    projBox(U + wallT, -V - wallT, rimW),
    projBox(U + wallT, V + wallT, rimW),
    projBox(U, V, rimW)
  ];
  washPoly(rightRimTop, PAL.goldBright, 240);
  strokePoly(rightRimTop, "engraver", PAL.umberBlack, 0.8);

  // Exterior Right Wall (visible on the right side of the box)
  const rightOuterWall = [
    projBox(U + wallT, -V - wallT, -14),
    projBox(U + wallT, V + wallT, -14),
    projBox(U + wallT, V + wallT, rimW),
    projBox(U + wallT, -V - wallT, rimW)
  ];
  washAndHatchPoly(
    rightOuterWall,
    PAL.prussianDark, 245,
    "engraver", PAL.umberBlack, 0.9,
    3.8, 45, 0.02
  );
  strokePoly(rightOuterWall, "engraver", PAL.goldAntique, 0.9);

  // Delicate white die-cut Victorian paper lace doily peaking along Back and Right rims
  drawPaperLaceStrip([-U, -V, 42], [U, -V, 42], [0, 8, 12], 18);
  drawPaperLaceStrip([U, -V, 42], [U, V, 42], [-8, 0, 12], 14);
}

function drawPaperLaceStrip(startUVW, endUVW, liftUVW, numScallops) {
  resetBrushStates();
  for (let i = 0; i < numScallops; i++) {
    let t0 = i / numScallops;
    let t1 = (i + 0.5) / numScallops;
    let t2 = (i + 1) / numScallops;

    let p0 = projBox(
      lerp(startUVW[0], endUVW[0], t0),
      lerp(startUVW[1], endUVW[1], t0),
      startUVW[2]
    );
    let pMid = projBox(
      lerp(startUVW[0], endUVW[0], t1) + liftUVW[0],
      lerp(startUVW[1], endUVW[1], t1) + liftUVW[1],
      startUVW[2] + liftUVW[2]
    );
    let p2 = projBox(
      lerp(startUVW[0], endUVW[0], t2),
      lerp(startUVW[1], endUVW[1], t2),
      startUVW[2]
    );

    washPoly([p0, pMid, p2], PAL.ivoryCream, 225, 0.25);
    strokePoly([p0, pMid, p2], "engraver", PAL.paperShadow, 0.65, 0.25, false);

    // Tiny die-cut eyelet perforation inside each lace scallop
    let pHole = lerpPt(lerpPt(p0, p2, 0.5), pMid, 0.52);
    brush.set("engraver", PAL.umberDark, 0.75);
    brush.circle(pHole[0], pHole[1], 2.2, 0.1);
  }
  resetBrushStates();
}

// =============================================================================
// 5. ALL 12 COMPARTMENTS, FLUTED GOLD-FOIL CUPS & HYPERREAL CHOCOLATES
// =============================================================================

function drawAllCompartmentsAndChocolates() {
  // Build list of 12 cells and sort strictly back-to-front by projected screen Y
  let cells = [];
  for (let r = 0; r < 3; r++) {
    for (let c = 0; c < 4; c++) {
      let u0 = -212 + c * 106;
      let u1 = u0 + 106;
      let v0 = -156 + r * 104;
      let v1 = v0 + 104;
      let uc = (u0 + u1) * 0.5;
      let vc = (v0 + v1) * 0.5;
      let centerPt = projBox(uc, vc, 0);
      cells.push({ r, c, u0, u1, v0, v1, uc, vc, sortY: centerPt[1] });
    }
  }

  cells.sort((a, b) => a.sortY - b.sortY);

  const divH = 34;

  for (let cell of cells) {
    const { r, c, u0, u1, v0, v1, uc, vc } = cell;

    // 5a. Receding Back Wall (v = v0) and Right Wall (u = u1) of this compartment
    const backWall = [
      projBox(u0, v0, 0),
      projBox(u1, v0, 0),
      projBox(u1, v0, divH),
      projBox(u0, v0, divH)
    ];
    washAndHatchPoly(
      backWall,
      PAL.goldShadow, 235,
      "engraver", PAL.umberBlack, 0.7,
      4.5, 15, 0.02
    );

    const rightWall = [
      projBox(u1, v0, 0),
      projBox(u1, v1, 0),
      projBox(u1, v1, divH),
      projBox(u1, v0, divH)
    ];
    washAndHatchPoly(
      rightWall,
      PAL.umberDark, 235,
      "engraver", PAL.umberBlack, 0.75,
      4.5, -45, 0.02
    );

    // Top gilt edge of receding walls
    resetBrushStates();
    brush.set("cpencil", PAL.goldOchre, 1.1);
    let bw0 = projBox(u0, v0, divH);
    let bw1 = projBox(u1, v0, divH);
    let rw1 = projBox(u1, v1, divH);
    brush.line(bw0[0], bw0[1], bw1[0], bw1[1]);
    brush.line(bw1[0], bw1[1], rw1[0], rw1[1]);

    // 5b. Back half of the Crisp Fluted Gold-Foil Cup
    drawFlutedGoldFoilCupHalf(uc, vc, true);

    // 5c. The Unique Chocolate Truffle / Confection nestled inside the cup
    drawChocolateByIndex(r, c, uc, vc);

    // 5d. Front half of the Crisp Fluted Gold-Foil Cup wrapping around the truffle base
    drawFlutedGoldFoilCupHalf(uc, vc, false);

    // 5e. Near Front Divider Wall (v = v1) and Left Divider Wall (u = u0)
    if (r < 2) {
      const frontDiv = [
        projBox(u0, v1, 0),
        projBox(u1, v1, 0),
        projBox(u1, v1, divH),
        projBox(u0, v1, divH)
      ];
      washPoly(frontDiv, PAL.goldAntique, 235);
      strokePoly(frontDiv, "engraver", PAL.umberBlack, 0.65);
      resetBrushStates();
      brush.set("cpencil", PAL.goldPale, 1.15);
      let fd0 = projBox(u0, v1, divH);
      let fd1 = projBox(u1, v1, divH);
      brush.line(fd0[0], fd0[1], fd1[0], fd1[1]);
    }

    if (c > 0) {
      const leftDiv = [
        projBox(u0, v0, 0),
        projBox(u0, v1, 0),
        projBox(u0, v1, divH),
        projBox(u0, v0, divH)
      ];
      washPoly(leftDiv, PAL.goldShadow, 235);
      strokePoly(leftDiv, "engraver", PAL.umberBlack, 0.65);
      resetBrushStates();
      brush.set("cpencil", PAL.goldBright, 1.1);
      let ld0 = projBox(u0, v0, divH);
      let ld1 = projBox(u0, v1, divH);
      brush.line(ld0[0], ld0[1], ld1[0], ld1[1]);
    }
  }
  resetBrushStates();
}

// Renders a 32-pleat 3D accordion gold-foil cup (back half or front half)
function drawFlutedGoldFoilCupHalf(uc, vc, isBackHalf) {
  const numPleats = 32; // 64 alternating inner/outer vertices around 360 deg
  const totalVerts = numPleats * 2;
  const wBot = 4;
  const wTop = 36;
  const rBotOut = 32;
  const rBotIn = 28;
  const rTopOut = 48;
  const rTopIn = 40;

  // If back half, render interior shadow cavity first
  if (isBackHalf) {
    let innerRim = [];
    for (let i = 0; i <= 24; i++) {
      let a = 180 + (i / 24) * 180;
      innerRim.push(projBox(uc + cos(a) * 41, vc + sin(a) * 41, wTop - 2));
    }
    for (let i = 24; i >= 0; i--) {
      let a = 180 + (i / 24) * 180;
      innerRim.push(projBox(uc + cos(a) * 30, vc + sin(a) * 30, wBot + 8));
    }
    washPoly(innerRim, PAL.umberBlack, 225);
  }

  // Loop over all 64 triangular accordion facets
  for (let i = 0; i < totalVerts; i++) {
    let a0 = (i / totalVerts) * 360;
    let a1 = ((i + 1) / totalVerts) * 360;
    let aMid = (a0 + a1) * 0.5;

    // Back half is sin(aMid) < 0 (away from viewer); front half is sin(aMid) >= 0 (toward viewer)
    let inBack = sin(aMid) < -0.05;
    if (isBackHalf !== inBack) continue;

    let r0Top = (i % 2 === 0) ? rTopOut : rTopIn;
    let r1Top = ((i + 1) % 2 === 0) ? rTopOut : rTopIn;
    let r0Bot = (i % 2 === 0) ? rBotOut : rBotIn;
    let r1Bot = ((i + 1) % 2 === 0) ? rBotOut : rBotIn;

    let t0 = projBox(uc + cos(a0) * r0Top, vc + sin(a0) * r0Top, wTop + (i % 2 === 0 ? 2 : -1));
    let t1 = projBox(uc + cos(a1) * r1Top, vc + sin(a1) * r1Top, wTop + ((i + 1) % 2 === 0 ? 2 : -1));
    let b1 = projBox(uc + cos(a1) * r1Bot, vc + sin(a1) * r1Bot, wBot);
    let b0 = projBox(uc + cos(a0) * r0Bot, vc + sin(a0) * r0Bot, wBot);

    // Metallic gold facet shading based on pleat orientation + back/front lighting
    let facetNormal = aMid + ((i % 2 === 0) ? 52 : -52);
    let lightDot = cos(facetNormal - 215); // Light from upper-left

    let col;
    if (isBackHalf) {
      // Interior of back half faces forward; alternating bright & antique gold pleats
      if (lightDot > 0.45) col = PAL.goldPale;
      else if (lightDot > 0.0) col = PAL.goldBright;
      else if (lightDot > -0.45) col = PAL.goldOchre;
      else col = PAL.goldAntique;
    } else {
      // Exterior of front half wraps around the front of the truffle
      if (lightDot > 0.55) col = PAL.goldSpecular;
      else if (lightDot > 0.18) col = PAL.goldPale;
      else if (lightDot > -0.18) col = PAL.goldBright;
      else if (lightDot > -0.55) col = PAL.goldAntique;
      else col = PAL.goldShadow;
    }

    washPoly([t0, t1, b1, b0], col, 240);

    // Crisp engraved pleat crease line
    resetBrushStates();
    let lineCol = (i % 2 === 0) ? PAL.goldSpecular : PAL.umberDark;
    let lineW = (i % 2 === 0) ? 0.65 : 0.5;
    brush.set("engraver", lineCol, lineW);
    brush.line(t0[0], t0[1], b0[0], b0[1]);

    // Zigzag gold-foil top rim highlight
    brush.set("engraver", (i % 2 === 0) ? PAL.whiteSpec : PAL.goldShadow, 0.75);
    brush.line(t0[0], t0[1], t1[0], t1[1]);
  }
  resetBrushStates();
}

// =============================================================================
// INDIVIDUAL HYPERREAL CHOCOLATES (12 ASSORTED CONFECTIONS)
// =============================================================================

// Helper: builds a 3D domed truffle base from concentric offset chromolitho plates
function drawTruffleDomeBase(uc, vc, radU, radV, baseW, peakW, palette, shapePower = 1.0, rotDeg = 0) {
  // palette = [shadowCol, darkCol, midCol, warmCol, highlightCol]
  const layers = [
    { t: 0.00, col: palette[0], op: 248, offU: 0, offV: 0, hatchCol: PAL.umberBlack, hAng: 25 },
    { t: 0.14, col: palette[1], op: 240, offU: -2, offV: -2, hatchCol: palette[0], hAng: -35 },
    { t: 0.32, col: palette[2], op: 230, offU: -5, offV: -4, hatchCol: palette[1], hAng: 55 },
    { t: 0.54, col: palette[3], op: 215, offU: -9, offV: -7, hatchCol: palette[2], hAng: -15 },
    { t: 0.75, col: palette[4], op: 190, offU: -13, offV: -9, hatchCol: palette[3], hAng: 40 }
  ];

  const cR = cos(rotDeg);
  const sR = sin(rotDeg);

  for (let L of layers) {
    let scaleR = pow(1 - L.t * 0.78, 0.65);
    let wCur = lerp(baseW, peakW, pow(L.t, 0.75));
    let pts = [];
    for (let a = 0; a < 360; a += 15) {
      let bump = 1 + (shapePower !== 1.0 ? 0.05 * sin(a * shapePower) : 0);
      let lu = cos(a) * radU * scaleR * bump;
      let lv = sin(a) * radV * scaleR * bump;
      let ru = lu * cR - lv * sR + L.offU * (1 - scaleR * 0.3);
      let rv = lu * sR + lv * cR + L.offV * (1 - scaleR * 0.3);
      let wPt = wCur + (1 - sin(a)) * (peakW - baseW) * 0.22 * scaleR;
      pts.push(projBox(uc + ru, vc + rv, wPt));
    }
    washAndHatchPoly(pts, L.col, L.op, "engraver", L.hatchCol, 0.6, 4.2, L.hAng, 0.04, 0.28);
  }

  // Lithographic stipple grain over the dome
  let centerScreen = projBox(uc - 4, vc - 3, (baseW + peakW) * 0.55);
  stippleRegion(centerScreen[0], centerScreen[1], 28, 22, -12, "litho_stipple", palette[1], 0.9, 55);
  stippleRegion(centerScreen[0] - 8, centerScreen[1] - 7, 18, 14, -15, "litho_fine", palette[4], 0.85, 45);
}

// Helper: draws tempered mirror-gloss specular window reflection on a chocolate dome
function drawTemperedGlossHighlight(uc, vc, peakW, rx = 18, ry = 14) {
  resetBrushStates();
  // Cool Prussian-blue secondary ambient sheen on the shadow right-back flank
  brush.set("cpencil", PAL.prussianSoft, 1.15);
  for (let a = -40; a <= 45; a += 8) {
    let p1 = projBox(uc + cos(a) * (rx + 8), vc + sin(a) * (ry + 6), peakW - 12);
    let p2 = projBox(uc + cos(a + 8) * (rx + 8), vc + sin(a + 8) * (ry + 6), peakW - 12);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Primary bright crescent window reflection on upper-left dome
  let hlPts = [];
  for (let a = 195; a <= 265; a += 10) {
    hlPts.push(projBox(uc + cos(a) * rx, vc + sin(a) * ry, peakW - 4));
  }
  for (let a = 265; a >= 195; a -= 10) {
    hlPts.push(projBox(uc + cos(a) * (rx * 0.62), vc + sin(a) * (ry * 0.62), peakW + 2));
  }
  washPoly(hlPts, PAL.whiteSpec, 235, 0.3);
  strokePoly(hlPts, "engraver", PAL.goldSpecular, 0.85, 0.3);

  // Pinpoint catchlight dot next to crescent
  let dotPt = projBox(uc - rx * 0.45, vc - ry * 0.82, peakW - 2);
  brush.set("cpencil", PAL.whiteSpec, 1.6);
  brush.circle(dotPt[0], dotPt[1], 3.2, 0.05);
  resetBrushStates();
}

function drawChocolateByIndex(r, c, uc, vc) {
  const idx = r * 4 + c;

  if (idx === 0) {
    // (0,0) Velvety Cocoa-Dusted Truffle with natural cocoa fissures
    drawTruffleDomeBase(
      uc, vc, 39, 37, 20, 56,
      [PAL.umberBlack, PAL.umberDark, PAL.umberRich, PAL.cocoaWarm, PAL.pralineTan],
      5, 15
    );
    let cPt = projBox(uc - 3, vc - 3, 44);
    stippleRegion(cPt[0], cPt[1], 32, 24, -10, "litho_stipple", PAL.cocoaWarm, 1.15, 95);
    stippleRegion(cPt[0] - 8, cPt[1] - 7, 20, 15, -15, "litho_fine", PAL.caramelLight, 0.95, 70);
    stippleRegion(cPt[0] - 11, cPt[1] - 9, 12, 9, -15, "litho_fine", PAL.goldPale, 0.75, 35);
    // Natural cocoa dust crevices
    resetBrushStates();
    brush.set("engraver", PAL.umberBlack, 0.85);
    for (let k = -1; k <= 1; k++) {
      let p1 = projBox(uc - 18, vc + k * 9 - 4, 42);
      let p2 = projBox(uc + 2, vc + k * 7 + 2, 52);
      let p3 = projBox(uc + 18, vc + k * 10 - 3, 40);
      brush.spline([p1, p2, p3], 0.4);
    }
    resetBrushStates();

  } else if (idx === 1) {
    // (0,1) Victorian Rose Fondant Crème Swirl with crystallized petal & gold leaf
    drawTruffleDomeBase(
      uc, vc, 38, 36, 20, 55,
      [PAL.claretBlack, PAL.claretDeep, PAL.claretRich, PAL.roseMid, PAL.roseSoft],
      1, 0
    );
    drawTemperedGlossHighlight(uc, vc, 53, 19, 15);
    // Piped rose-cream spiral on top
    resetBrushStates();
    let spDark = [];
    let spLight = [];
    for (let t = 0; t <= 1; t += 0.05) {
      let a = t * 540;
      let rad = (1 - t) * 24;
      let w = 40 + t * 20;
      spDark.push(projBox(uc + cos(a) * rad + 2, vc + sin(a) * rad + 2, w - 1));
      spLight.push(projBox(uc + cos(a) * rad, vc + sin(a) * rad, w));
    }
    brush.set("cpencil", PAL.claretDeep, 1.45);
    brush.spline(spDark, 0.5);
    brush.set("cpencil", PAL.rosePale, 1.35);
    brush.spline(spLight, 0.5);
    brush.set("engraver", PAL.whiteSpec, 0.85);
    brush.spline(spLight.slice(4), 0.5);
    // Crystallized violet/claret petal & gold speck at apex
    let topPt = projBox(uc, vc, 60);
    washPoly([
      [topPt[0] - 8, topPt[1] - 3],
      [topPt[0] + 2, topPt[1] - 9],
      [topPt[0] + 9, topPt[1] - 1],
      [topPt[0] - 1, topPt[1] + 4]
    ], PAL.claretRich, 240, 0.3);
    brush.set("cpencil", PAL.goldBright, 1.4);
    brush.circle(topPt[0] + 3, topPt[1] - 2, 3.2, 0.1);
    resetBrushStates();

  } else if (idx === 2) {
    // (0,2) Tempered Bittersweet Mirror-Gloss Dome with 24k Gold Leaf
    drawTruffleDomeBase(
      uc, vc, 39, 38, 20, 58,
      [PAL.umberBlack, PAL.umberBlack, PAL.umberDark, PAL.umberRich, PAL.umberMilk],
      1, 0
    );
    drawTemperedGlossHighlight(uc, vc, 56, 22, 17);
    // 24k Gold Leaf flake crowning the dome
    let gPts = [
      projBox(uc - 6, vc - 8, 58),
      projBox(uc + 9, vc - 11, 57),
      projBox(uc + 14, vc - 2, 55),
      projBox(uc + 5, vc + 7, 57),
      projBox(uc - 8, vc + 3, 58)
    ];
    washPoly(gPts, PAL.goldBright, 248, 0.15);
    strokePoly(gPts, "engraver", PAL.goldSpecular, 0.9, 0.15);
    resetBrushStates();
    brush.set("cpencil", PAL.whiteSpec, 1.2);
    let gp = projBox(uc, vc - 4, 59);
    brush.line(gp[0] - 4, gp[1], gp[0] + 5, gp[1] - 2);
    resetBrushStates();

  } else if (idx === 3) {
    // (0,3) Gianduja Hazelnut Star-Piped Rosette with Whole Roasted Hazelnut
    drawTruffleDomeBase(
      uc, vc, 38, 36, 18, 48,
      [PAL.umberDark, PAL.umberRich, PAL.umberMilk, PAL.cocoaWarm, PAL.pralineTan],
      10, 0
    );
    // 10 Star-nozzle piped ribs spiraling toward center
    resetBrushStates();
    for (let i = 0; i < 10; i++) {
      let aBase = i * 36;
      let ribShadow = [];
      let ribMid = [];
      let ribSpec = [];
      for (let t = 0; t <= 1; t += 0.2) {
        let a = aBase + t * 52;
        let rad = lerp(37, 10, t);
        let w = lerp(24, 52, t);
        ribShadow.push(projBox(uc + cos(a + 8) * rad, vc + sin(a + 8) * rad, w - 2));
        ribMid.push(projBox(uc + cos(a) * rad, vc + sin(a) * rad, w));
        ribSpec.push(projBox(uc + cos(a - 5) * rad, vc + sin(a - 5) * rad, w + 1));
      }
      brush.set("cpencil", PAL.umberBlack, 1.35);
      brush.spline(ribShadow, 0.4);
      brush.set("cpencil", PAL.cocoaWarm, 1.35);
      brush.spline(ribMid, 0.4);
      if (cos(aBase - 215) > -0.2) {
        brush.set("engraver", PAL.goldPale, 0.8);
        brush.spline(ribSpec, 0.4);
      }
    }
    // Whole roasted hazelnut on top
    drawTruffleDomeBase(
      uc, vc, 15, 14, 48, 63,
      [PAL.umberDark, PAL.umberMilk, PAL.cocoaWarm, PAL.pralineTan, PAL.paperWarm],
      1, 0
    );
    drawTemperedGlossHighlight(uc, vc, 61, 8, 6);

  } else if (idx === 4) {
    // (1,0) Moulded Praline Rectangular Pavé with Diagonal Gilt & Caramel Drizzle
    const wB = 18;
    const wT = 48;
    const bPts = [
      projBox(uc - 32, vc - 26, wB),
      projBox(uc + 32, vc - 26, wB),
      projBox(uc + 32, vc + 26, wB),
      projBox(uc - 32, vc + 26, wB)
    ];
    const tPts = [
      projBox(uc - 25, vc - 19, wT),
      projBox(uc + 25, vc - 19, wT),
      projBox(uc + 25, vc + 19, wT),
      projBox(uc - 25, vc + 19, wT)
    ];
    // Four chamfered side faces of the pavé
    washAndHatchPoly([bPts[0], bPts[1], tPts[1], tPts[0]], PAL.umberDark, 245, "engraver", PAL.umberBlack, 0.7, 4, 15);
    washAndHatchPoly([bPts[1], bPts[2], tPts[2], tPts[1]], PAL.umberBlack, 248, "engraver", PAL.prussianDark, 0.75, 3.5, -40);
    washAndHatchPoly([bPts[3], bPts[2], tPts[2], tPts[3]], PAL.umberRich, 245, "engraver", PAL.umberDark, 0.7, 4, 20);
    washAndHatchPoly([bPts[0], bPts[3], tPts[3], tPts[0]], PAL.umberMilk, 240, "engraver", PAL.umberRich, 0.65, 4.5, -25);
    // Glossy top face
    washAndHatchPoly(tPts, PAL.umberDark, 245, "engraver", PAL.umberBlack, 0.65, 4.0, 30);
    strokePoly(tPts, "cpencil", PAL.caramelLight, 1.0);
    // Specular edge along front-left bevel
    resetBrushStates();
    brush.set("engraver", PAL.whiteSpec, 0.95);
    brush.line(tPts[0][0], tPts[0][1], tPts[3][0], tPts[3][1]);
    brush.line(tPts[3][0], tPts[3][1], tPts[2][0], tPts[2][1]);
    // 5 Piped diagonal strings of gilt-caramel over the pavé
    for (let k = -2; k <= 2; k++) {
      let uA = uc + k * 10 - 10;
      let uB = uc + k * 10 + 10;
      let s1 = projBox(constrain(uA, uc - 29, uc + 29), vc - 23, wB + 8);
      let s2 = projBox(constrain(uA + 3, uc - 24, uc + 24), vc - 18, wT + 2);
      let s3 = projBox(constrain(uB - 3, uc - 24, uc + 24), vc + 18, wT + 2);
      let s4 = projBox(constrain(uB, uc - 29, uc + 29), vc + 23, wB + 8);
      brush.set("cpencil", PAL.umberBlack, 1.3);
      brush.spline([[s1[0] + 2, s1[1] + 2], [s2[0] + 2, s2[1] + 2], [s3[0] + 2, s3[1] + 2], [s4[0] + 2, s4[1] + 2]], 0.3);
      brush.set("cpencil", PAL.goldBright, 1.25);
      brush.spline([s1, s2, s3, s4], 0.3);
      brush.set("engraver", PAL.goldSpecular, 0.7);
      brush.line(s2[0], s2[1], s3[0], s3[1]);
    }
    resetBrushStates();

  } else if (idx === 5) {
    // (1,1) Grand Piped Dark Chocolate Rosette (Centerpiece)
    drawTruffleDomeBase(
      uc, vc, 40, 38, 20, 52,
      [PAL.umberBlack, PAL.umberDark, PAL.umberRich, PAL.umberMilk, PAL.cocoaWarm],
      12, 10
    );
    // Tall spiraled star-nozzle ganache peak
    resetBrushStates();
    for (let i = 0; i < 12; i++) {
      let a0 = i * 30;
      let ptsDark = [];
      let ptsMid = [];
      let ptsHi = [];
      for (let t = 0; t <= 1; t += 0.12) {
        let a = a0 + t * 145;
        let rad = (1 - pow(t, 0.85)) * 38;
        let w = 24 + t * 40;
        ptsDark.push(projBox(uc + cos(a + 7) * rad, vc + sin(a + 7) * rad, w - 2));
        ptsMid.push(projBox(uc + cos(a) * rad, vc + sin(a) * rad, w));
        ptsHi.push(projBox(uc + cos(a - 5) * rad, vc + sin(a - 5) * rad, w + 1.5));
      }
      brush.set("cpencil", PAL.umberBlack, 1.45);
      brush.spline(ptsDark, 0.45);
      brush.set("cpencil", PAL.umberRich, 1.35);
      brush.spline(ptsMid, 0.45);
      if (cos(a0 - 210) > -0.1) {
        brush.set("cpencil", PAL.caramelLight, 1.05);
        brush.spline(ptsHi, 0.45);
        brush.set("engraver", PAL.whiteSpec, 0.8);
        brush.spline(ptsHi.slice(2), 0.45);
      }
    }
    // Curled ganache peak with gold dust
    let tip = projBox(uc - 2, vc - 2, 65);
    brush.set("cpencil", PAL.whiteSpec, 1.3);
    brush.circle(tip[0], tip[1], 3.5, 0.1);
    stippleRegion(tip[0], tip[1] + 6, 16, 12, 0, "litho_fine", PAL.goldBright, 0.85, 35);
    resetBrushStates();

  } else if (idx === 6) {
    // (1,2) Ivory White-Chocolate & Claret Raspberry Lattice Dome
    drawTruffleDomeBase(
      uc, vc, 38, 37, 20, 56,
      [PAL.goldAntique, PAL.paperShadow, PAL.paperWarm, PAL.ivoryCream, PAL.whiteSpec],
      1, 0
    );
    drawTemperedGlossHighlight(uc, vc, 54, 18, 14);
    // Claret-rose glaze drizzle arches across the ivory dome
    resetBrushStates();
    for (let k = -2; k <= 2; k++) {
      let vOff = k * 10;
      let rMax = sqrt(max(10, 36 * 36 - vOff * vOff));
      let arcPts = [];
      for (let s = -1; s <= 1; s += 0.2) {
        let uCur = s * rMax;
        let wCur = 24 + (1 - s * s) * (1 - (vOff / 38) * (vOff / 38)) * 33;
        arcPts.push(projBox(uc + uCur, vc + vOff, wCur));
      }
      brush.set("cpencil", PAL.claretDeep, 1.4);
      brush.spline(arcPts, 0.45);
      brush.set("engraver", PAL.roseSoft, 0.8);
      brush.spline(arcPts.slice(1, 9), 0.45);
    }
    // Freeze-dried claret raspberry crumbs on crest
    let topC = projBox(uc - 3, vc - 2, 55);
    stippleRegion(topC[0], topC[1], 14, 10, 0, "litho_stipple", PAL.claretRich, 1.1, 32);
    stippleRegion(topC[0], topC[1], 10, 8, 0, "litho_fine", PAL.rosePale, 0.85, 20);
    resetBrushStates();

  } else if (idx === 7) {
    // (1,3) Pistachio Marzipan Medallion in Fluted Dark Chocolate Cup
    drawTruffleDomeBase(
      uc, vc, 39, 37, 20, 46,
      [PAL.umberBlack, PAL.umberDark, PAL.umberRich, PAL.umberMilk, PAL.cocoaWarm],
      16, 0
    );
    // Lush pistachio cream dome rising from the center of the dark chocolate crown
    drawTruffleDomeBase(
      uc, vc, 26, 25, 38, 58,
      [PAL.pistachioDark, PAL.pistachioDark, PAL.pistachioMid, PAL.pistachioPale, PAL.ivoryCream],
