    );
    let pCenter = projBox(uc - 2, vc - 2, 53);
    stippleRegion(pCenter[0], pCenter[1], 18, 14, 0, "litho_stipple", PAL.pistachioDark, 1.0, 45);
    stippleRegion(pCenter[0] - 4, pCenter[1] - 3, 13, 10, 0, "litho_fine", PAL.goldPale, 0.9, 35);
    // Glossy dark chocolate pip at center
    drawTruffleDomeBase(
      uc, vc, 9, 9, 54, 62,
      [PAL.umberBlack, PAL.umberDark, PAL.umberRich, PAL.cocoaWarm, PAL.whiteSpec],
      1, 0
    );

  } else if (idx === 8) {
    // (2,0) Mocha Espresso Oval Bonbon with Sculpted Coffee Bean
    drawTruffleDomeBase(
      uc, vc, 41, 31, 20, 54,
