    );
    resetBrushStates();
    let b1 = projBox(uc - 11, vc + 3, 58);
    let b2 = projBox(uc, vc - 1, 61);
    let b3 = projBox(uc + 11, vc - 3, 58);
    brush.set("cpencil", PAL.umberBlack, 1.35);
