    resetBrushStates();

  } else if (idx === 9) {
    // (2,1) Moulded Milk-Chocolate Scallop Shell with Sea-Salt Crystals
    drawTruffleDomeBase(
      uc, vc, 39, 36, 20, 52,
      [PAL.umberDark, PAL.umberRich, PAL.umberMilk, PAL.cocoaWarm, PAL.pralineTan],
