    drawTemperedGlossHighlight(uc, vc, 58, 12, 9);

  } else if (idx === 11) {
    // (2,3) Half-Peeled Crinkled Gold-Foil & Velvet Ganache Truffle
    // First render the rich cocoa-dusted truffle core
    drawTruffleDomeBase(
