    );
    let cPt = projBox(uc - 4, vc - 4, 48);
    stippleRegion(cPt[0], cPt[1], 24, 18, -10, "litho_stipple", PAL.cocoaWarm, 1.1, 70);
    stippleRegion(cPt[0] - 6, cPt[1] - 5, 15, 11, -10, "litho_fine", PAL.goldPale, 0.85, 45);

    // Crinkled faceted metallic gold foil wrapping the lower & right half of the sphere
    const foilFacets = [
      [[uc - 34, vc + 6, 28],  [uc - 12, vc + 12, 46], [uc - 8, vc + 34, 30],  PAL.goldSpecular],
      [[uc - 12, vc + 12, 46], [uc + 14, vc + 8, 48],  [uc + 6, vc + 35, 30],  PAL.goldBright],
      [[uc - 8, vc + 34, 30],  [uc + 14, vc + 8, 48],  [uc + 6, vc + 35, 30],  PAL.goldOchre],
      [[uc + 14, vc + 8, 48],  [uc + 35, vc - 6, 44],  [uc + 30, vc + 24, 28], PAL.goldAntique],
      [[uc + 14, vc + 8, 48],  [uc + 6, vc + 35, 30],  [uc + 30, vc + 24, 28], PAL.goldShadow],
      [[uc + 8, vc - 14, 53],  [uc + 35, vc - 6, 44],  [uc + 14, vc + 8, 48],  PAL.goldPale],
      [[uc + 8, vc - 14, 53],  [uc + 26, vc - 28, 38], [uc + 35, vc - 6, 44],  PAL.goldOchre]
    ];
    for (let f of foilFacets) {
      let tri = [projBox(...f[0]), projBox(...f[1]), projBox(...f[2])];
      washPoly(tri, f[3], 245);
      strokePoly(tri, "engraver", PAL.umberDark, 0.7);
      resetBrushStates();
      brush.set("engraver", PAL.whiteSpec, 0.8);
      brush.line(tri[0][0], tri[0][1], tri[1][0], tri[1][1]);
    }
  }
  resetBrushStates();
}

