function drawBoxTrayFrontStructure() {
  const U = 212;
  const V = 156;
  const rimW = 46;
  const wallT = 16;
  const baseW = -14;

  // Delicate white paper lace doily strip peaking along the inner Front and Left edges
  drawPaperLaceStrip([-U, V, 38], [U, V, 38], [0, -7, 10], 18);
  drawPaperLaceStrip([-U, -V, 38], [-U, V, 38], [7, 0, 10], 14);

  // Top Gilded Rim Ledges for Left Wall and Front Wall
  const leftRimTop = [
    projBox(-U - wallT, -V - wallT, rimW),
    projBox(-U, -V, rimW),
    projBox(-U, V, rimW),
    projBox(-U - wallT, V + wallT, rimW)
  ];
  washPoly(leftRimTop, PAL.goldPale, 245);
  strokePoly(leftRimTop, "engraver", PAL.umberBlack, 0.8);

  const frontRimTop = [
    projBox(-U, V, rimW),
    projBox(U, V, rimW),
    projBox(U + wallT, V + wallT, rimW),
    projBox(-U - wallT, V + wallT, rimW)
  ];
  washPoly(frontRimTop, PAL.goldBright, 245);
  strokePoly(frontRimTop, "engraver", PAL.umberBlack, 0.85);

  // Exterior Left Wall (u = -U - wallT, facing upper-left light)
  const leftOuterWall = [
    projBox(-U - wallT, -V - wallT, baseW),
    projBox(-U - wallT, V + wallT, baseW),
    projBox(-U - wallT, V + wallT, rimW),
    projBox(-U - wallT, -V - wallT, rimW)
  ];
  washAndHatchPoly(
    leftOuterWall,
    PAL.prussianMid, 245,
    "engraver", PAL.prussianDeep, 0.8,
    4.0, -28, 0.02
  );
  hatchOnlyPoly(leftOuterWall, "engraver", PAL.prussianDark, 0.65, 6.5, 42, 0.03);
  strokePoly(leftOuterWall, "engraver", PAL.umberBlack, 0.95);

  // Gilt molding strips on Left Wall
  resetBrushStates();
  for (let wLine of [baseW + 6, rimW - 7]) {
    let p1 = projBox(-U - wallT, -V - wallT, wLine);
    let p2 = projBox(-U - wallT, V + wallT, wLine);
    brush.set("cpencil", PAL.goldBright, 1.25);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.set("engraver", PAL.goldSpecular, 0.75);
    brush.line(p1[0], p1[1] - 1.5, p2[0], p2[1] - 1.5);
  }

  // Exterior Front Wall (v = V + wallT, main showcase face)
  const frontOuterWall = [
    projBox(-U - wallT, V + wallT, baseW),
    projBox(U + wallT, V + wallT, baseW),
    projBox(U + wallT, V + wallT, rimW),
    projBox(-U - wallT, V + wallT, rimW)
  ];
  washAndHatchPoly(
    frontOuterWall,
    PAL.prussianDeep, 248,
    "engraver", PAL.prussianDark, 0.85,
    3.8, 18, 0.02
  );
  hatchOnlyPoly(frontOuterWall, "engraver", PAL.umberBlack, 0.65, 6.0, -55, 0.03);
  strokePoly(frontOuterWall, "engraver", PAL.umberBlack, 1.0);

  // Embossed Claret & Gilt panel inset on the Front Wall
  const frontInset = [
    projBox(-U, V + wallT, baseW + 8),
    projBox(U, V + wallT, baseW + 8),
    projBox(U, V + wallT, rimW - 8),
    projBox(-U, V + wallT, rimW - 8)
  ];
  washAndHatchPoly(
    frontInset,
    PAL.claretDeep, 235,
    "engraver", PAL.claretBlack, 0.75,
    4.5, -18, 0.03
  );
  strokePoly(frontInset, "cpencil", PAL.goldBright, 1.15);
  strokePoly(frontInset, "engraver", PAL.goldSpecular, 0.7);

  // Embossed Gilt Greek-Key / Fretwork along the Front Wall
  resetBrushStates();
  for (let u = -U + 14; u <= U - 26; u += 28) {
    if (abs(u) < 62) continue; // Leave room for central gold medallion plaque
    let kPts = [
      projBox(u, V + wallT, baseW + 14),
      projBox(u, V + wallT, rimW - 14),
      projBox(u + 18, V + wallT, rimW - 14),
      projBox(u + 18, V + wallT, baseW + 22),
      projBox(u + 8, V + wallT, baseW + 22),
      projBox(u + 8, V + wallT, rimW - 22),
      projBox(u + 24, V + wallT, rimW - 22),
      projBox(u + 24, V + wallT, baseW + 14)
    ];
    strokePoly(kPts, "cpencil", PAL.goldOchre, 1.05, 0, false);
    strokePoly(kPts, "engraver", PAL.goldPale, 0.65, 0, false);
  }

  // Central Embossed Gold Cartouche Plaque on the Front Wall
  let plaquePts = [];
  for (let a = 0; a < 360; a += 18) {
    plaquePts.push(projBox(cos(a) * 56, V + wallT, (baseW + rimW) * 0.5 + sin(a) * 20));
  }
  washPoly(plaquePts, PAL.goldOchre, 245, 0.25);
  strokePoly(plaquePts, "cpencil", PAL.goldPale, 1.1, 0.25);
  strokePoly(plaquePts, "engraver", PAL.umberBlack, 0.8, 0.25);

  resetBrushStates();
  brush.set("engraver", PAL.umberDark, 0.85);
  let pL = projBox(-36, V + wallT, (baseW + rimW) * 0.5);
  let pR = projBox(36, V + wallT, (baseW + rimW) * 0.5);
  brush.line(pL[0], pL[1], pR[0], pR[1]);
  brush.set("engraver", PAL.goldSpecular, 0.85);
  brush.line(pL[0], pL[1] - 2, pR[0], pR[1] - 2);

  // Brass corner brackets on the Front-Left and Front-Right corners
  for (let cu of [-U - wallT, U + wallT]) {
    let dirU = cu < 0 ? 1 : -1;
    let brk = [
      projBox(cu, V + wallT, rimW),
      projBox(cu + dirU * 22, V + wallT, rimW),
      projBox(cu + dirU * 6, V + wallT, baseW),
      projBox(cu, V + wallT, baseW)
    ];
    washPoly(brk, PAL.goldBright, 245);
    strokePoly(brk, "engraver", PAL.umberBlack, 0.8);
  }
  resetBrushStates();
}

// =============================================================================
// 7. DEEP CLARET SATIN RIBBON BOW & CASCADING FOREGROUND TAILS
// =============================================================================

// Renders a sculptural satin ribbon strip from leftRail and rightRail point arrays
// lightProfile: array of [tCenter, widthSpread] where cylindrical satin specular bands occur
function drawSatinRibbonStrip(leftRail, rightRail, lightBands, castShadowOffset = [8, 12]) {
  const n = leftRail.length;

  // 1. Soft dark cast shadow underneath the ribbon
  if (castShadowOffset) {
    let shPts = [];
    for (let i = 0; i < n; i++) {
      shPts.push([leftRail[i][0] + castShadowOffset[0], leftRail[i][1] + castShadowOffset[1]]);
    }
    for (let i = n - 1; i >= 0; i--) {
      shPts.push([rightRail[i][0] + castShadowOffset[0], rightRail[i][1] + castShadowOffset[1]]);
    }
    washPoly(shPts, PAL.umberBlack, 155, 0.2);
  }

  // 2. Full ribbon silhouette base in deep velvety claret
  let fullOutline = [...leftRail, ...rightRail.slice().reverse()];
  washAndHatchPoly(
    fullOutline,
    PAL.claretDeep, 245,
    "engraver", PAL.claretBlack, 0.75,
    4.0, 28, 0.03, 0.15
  );

  // 3. Subdivide along length to render high-contrast cylindrical satin sheen bands
  resetBrushStates();
  const steps = 64;
  for (let s = 0; s < steps; s++) {
    let t0 = s / steps;
    let t1 = (s + 1) / steps;
    let idx0 = t0 * (n - 1);
    let i0 = floor(idx0);
    let f0 = idx0 - i0;
    let pL0 = i0 < n - 1 ? lerpPt(leftRail[i0], leftRail[i0 + 1], f0) : leftRail[n - 1];
    let pR0 = i0 < n - 1 ? lerpPt(rightRail[i0], rightRail[i0 + 1], f0) : rightRail[n - 1];

    let idx1 = t1 * (n - 1);
    let i1 = floor(idx1);
    let f1 = idx1 - i1;
    let pL1 = i1 < n - 1 ? lerpPt(leftRail[i1], leftRail[i1 + 1], f1) : leftRail[n - 1];
    let pR1 = i1 < n - 1 ? lerpPt(rightRail[i1], rightRail[i1 + 1], f1) : rightRail[n - 1];

    // Compute satin specular intensity at parameter t0
    let intensity = 0;
    for (let [tc, spread] of lightBands) {
      let d = (t0 - tc) / spread;
      intensity = max(intensity, exp(-d * d * 2.5));
    }

    let col, w;
    if (intensity > 0.84) {
      col = PAL.whiteSpec;
      w = 1.15;
    } else if (intensity > 0.64) {
      col = PAL.rosePale;
      w = 1.3;
    } else if (intensity > 0.42) {
      col = PAL.roseSoft;
      w = 1.4;
    } else if (intensity > 0.22) {
      col = PAL.roseMid;
      w = 1.4;
    } else if (intensity > 0.08) {
      col = PAL.claretRich;
      w = 1.35;
    } else {
      col = PAL.claretBlack;
      w = 1.25;
    }

    // Cross-contour satin weave strokes
    brush.set("cpencil", col, w);
    let q0 = lerpPt(pL0, pR0, 0.06);
    let q1 = lerpPt(pL0, pR0, 0.94);
    brush.line(q0[0], q0[1], q1[0], q1[1]);

    // Extra crisp engraving highlight line at peak satin reflection
    if (intensity > 0.78) {
      brush.set("engraver", PAL.whiteSpec, 0.85);
      let h0 = lerpPt(pL1, pR1, 0.14);
      let h1 = lerpPt(pL1, pR1, 0.86);
      brush.line(h0[0], h0[1], h1[0], h1[1]);
    }
  }

  // 4. Longitudinal silk warp threads & woven gold-thread selvedge borders
  for (let u = 0.15; u <= 0.85; u += 0.175) {
    let warpPts = [];
    for (let i = 0; i < n; i++) {
      warpPts.push(lerpPt(leftRail[i], rightRail[i], u));
    }
    brush.set("engraver", PAL.claretRich, 0.55);
    brush.spline(warpPts, 0.45);
  }

  // Gilt selvedge edges
  strokePoly(leftRail, "cpencil", PAL.goldBright, 1.05, 0.35, false);
  strokePoly(rightRail, "cpencil", PAL.goldOchre, 1.05, 0.35, false);
  strokePoly(leftRail, "engraver", PAL.umberBlack, 0.65, 0.35, false);
  strokePoly(rightRail, "engraver", PAL.umberBlack, 0.65, 0.35, false);
  resetBrushStates();
}

function drawClaretSatinRibbon() {
  // Knot anchor near the right corner of the box rim
  const kx = 835;
  const ky = 640;

  // 1. Diagonal sash band wrapping the upper-right corner of the open lid
  drawSatinRibbonStrip(
    [[605, 255], [665, 315], [735, 395], [785, 465]],
    [[648, 240], [705, 300], [772, 378], [818, 445]],
    [[0.45, 0.22]],
    [5, 8]
  );

  // 2. Long lower-left cascading tail draping in front of the box onto the foreground table
  const tail1L = [
    [kx - 8, ky + 12],
    [825, 735],
