// 9. DECORATIVE SCALLOPED VICTORIAN BORDER & REGISTRATION MARKS
// =============================================================================

function buildScallopedInnerContour() {
  // Generates a continuous closed path of inward-curving semicircular Victorian scallops
  // along all 4 sides from (112, 112) to (1088, 1088)
  const M = 108;
  const span = 1200 - 2 * M; // 984 px
  const numScallops = 12;
  const step = span / numScallops; // 82 px per scallop
  const amp = 22; // Depth of inward scallop cusp

  let pts = [];

  // Top edge: left to right
  for (let i = 0; i < numScallops; i++) {
    let x0 = M + i * step;
    for (let k = 0; k < 8; k++) {
      let t = k / 8;
      let x = x0 + t * step;
      let y = M + (1 - sin(t * 180)) * amp;
      pts.push([x, y]);
    }
  }
  // Right edge: top to bottom
  for (let i = 0; i < numScallops; i++) {
    let y0 = M + i * step;
    for (let k = 0; k < 8; k++) {
      let t = k / 8;
      let y = y0 + t * step;
      let x = (1200 - M) - (1 - sin(t * 180)) * amp;
      pts.push([x, y]);
    }
  }
  // Bottom edge: right to left
  for (let i = 0; i < numScallops; i++) {
    let x0 = (1200 - M) - i * step;
    for (let k = 0; k < 8; k++) {
      let t = k / 8;
      let x = x0 - t * step;
      let y = (1200 - M) - (1 - sin(t * 180)) * amp;
      pts.push([x, y]);
    }
  }
  // Left edge: bottom to top
  for (let i = 0; i < numScallops; i++) {
    let y0 = (1200 - M) - i * step;
    for (let k = 0; k < 8; k++) {
      let t = k / 8;
      let y = y0 - t * step;
      let x = M + (1 - sin(t * 180)) * amp;
      pts.push([x, y]);
    }
  }
  return pts;
}

function offsetScallopContour(pts, radialOffset) {
  // Offsets points outward (radialOffset > 0) or inward (radialOffset < 0) relative to (600, 600)
  return pts.map(([x, y]) => {
    let dx = x - 600;
    let dy = y - 600;
    let len = max(1, sqrt(dx * dx + dy * dy));
    return [x + (dx / len) * radialOffset, y + (dy / len) * radialOffset];
  });
}

function drawScallopedVictorianBorder() {
  const scPts = buildScallopedInnerContour();
  const scInnerShadow = offsetScallopContour(scPts, -7);
  const scGoldInner   = offsetScallopContour(scPts, 9);
  const scClaretBand  = offsetScallopContour(scPts, 22);
  const scGoldOuter   = offsetScallopContour(scPts, 34);

  // 1. Mask the 4 outer margins outside scGoldOuter with antique stone paper
  const N = scGoldOuter.length;
  const q = N / 4;

  const topMask = [[0, 0], [1200, 0], [1200, 140], ...scGoldOuter.slice(0, q + 1).reverse(), [0, 140]];
  const rightMask = [[1200, 0], [1200, 1200], [1060, 1200], ...scGoldOuter.slice(q, 2 * q + 1).reverse(), [1060, 0]];
  const botMask = [[1200, 1200], [0, 1200], [0, 1060], ...scGoldOuter.slice(2 * q, 3 * q + 1).reverse(), [1200, 1060]];
  const leftMask = [[0, 1200], [0, 0], [140, 0], ...scGoldOuter.slice(3 * q, N).reverse(), [140, 1200]];

  washPoly(topMask, PAL.paper, 255);
  washPoly(rightMask, PAL.paper, 255);
  washPoly(botMask, PAL.paper, 255);
  washPoly(leftMask, PAL.paper, 255);

  // 2. Draw the multi-layered Scalloped Gilt, Claret & Prussian Blue Frame Band
  for (let i = 0; i < N; i++) {
    let j = (i + 1) % N;

    // Inner cast shadow onto the artwork
    washPoly([scInnerShadow[i], scInnerShadow[j], scPts[j], scPts[i]], PAL.umberBlack, 155);

    // Inner bright metallic gold scalloped molding
    washPoly([scPts[i], scPts[j], scGoldInner[j], scGoldInner[i]], PAL.goldBright, 245);

    // Middle claret & rose beaded channel
    washPoly([scGoldInner[i], scGoldInner[j], scClaretBand[j], scClaretBand[i]], PAL.claretDeep, 245);

    // Outer antique gold & Prussian blue frame molding
    washPoly([scClaretBand[i], scClaretBand[j], scGoldOuter[j], scGoldOuter[i]], PAL.goldOchre, 245);
  }

  // 3. Crisp engraved & gilded contour lines along the scalloped arches
  strokePoly(scPts, "engraver", PAL.umberBlack, 1.0);
  strokePoly(offsetScallopContour(scPts, 3), "engraver", PAL.goldSpecular, 0.9);
  strokePoly(scGoldInner, "engraver", PAL.umberDark, 0.85);
  strokePoly(scClaretBand, "cpencil", PAL.goldPale, 1.0);
  strokePoly(scGoldOuter, "engraver", PAL.prussianDark, 1.1);

  // 4. Delicate lace fleur-de-lis & rose pearls at every scallop cusp and arch crest
  const M = 108;
  const span = 1200 - 2 * M;
  const numScallops = 12;
  const step = span / numScallops;

  resetBrushStates();
  for (let side = 0; side < 4; side++) {
    for (let i = 0; i <= numScallops; i++) {
      let t = M + i * step;
      let cx, cy, nx, ny;
      if (side === 0)      { cx = t; cy = M + 22; nx = 0; ny = 1; }
      else if (side === 1) { cx = 1200 - M - 22; cy = t; nx = -1; ny = 0; }
      else if (side === 2) { cx = 1200 - t; cy = 1200 - M - 22; nx = 0; ny = -1; }
      else                 { cx = M + 22; cy = 1200 - t; nx = 1; ny = 0; }

      // Cusp pendant jewel pointing inward
      let tipX = cx + nx * 12;
      let tipY = cy + ny * 12;
      brush.set("cpencil", PAL.goldBright, 1.2);
      brush.line(cx, cy, tipX, tipY);
      brush.set("cpencil", PAL.claretRich, 1.3);
      brush.circle(tipX, tipY, 4.0, 0.1);
      brush.set("engraver", PAL.whiteSpec, 0.75);
      brush.circle(tipX - 1, tipY - 1, 1.8, 0.1);

      // Rose pearl inside the claret channel at each arch midpoint
      if (i < numScallops) {
        let mx = cx + (side === 0 ? step * 0.5 : (side === 2 ? -step * 0.5 : 0)) - nx * 16;
        let my = cy + (side === 1 ? step * 0.5 : (side === 3 ? -step * 0.5 : 0)) - ny * 16;
        brush.set("cpencil", PAL.roseSoft, 1.25);
        brush.circle(mx, my, 4.5, 0.1);
        brush.set("engraver", PAL.goldPale, 0.8);
        brush.circle(mx, my, 2.2, 0.1);
      }
    }
  }

  // 5. Outer rectangular Victorian Double Rule & Corner Medallions
  const r1 = 62;
  const r2 = 54;
  strokePoly([[r1, r1], [1200 - r1, r1], [1200 - r1, 1200 - r1], [r1, 1200 - r1]], "cpencil", PAL.goldOchre, 1.3);
  strokePoly([[r1, r1], [1200 - r1, r1], [1200 - r1, 1200 - r1], [r1, 1200 - r1]], "engraver", PAL.prussianDark, 0.85);
  strokePoly([[r2, r2], [1200 - r2, r2], [1200 - r2, 1200 - r2], [r2, 1200 - r2]], "engraver", PAL.claretRich, 0.75);

  // Four Grand Corner Rosette Medallions
  const cornerCenters = [[102, 102], [1098, 102], [1098, 1098], [102, 1098]];
  for (let [ccx, ccy] of cornerCenters) {
    let petals = [];
    for (let a = 0; a < 360; a += 15) {
      let r = 34 + 6 * sin(a * 6);
      petals.push([ccx + cos(a) * r, ccy + sin(a) * r]);
    }
    washPoly(petals, PAL.prussianDeep, 245, 0.25);
    strokePoly(petals, "cpencil", PAL.goldBright, 1.2, 0.25);
    strokePoly(petals, "engraver", PAL.umberBlack, 0.8, 0.25);

    let innerR = [];
    for (let a = 0; a < 360; a += 20) {
      innerR.push([ccx + cos(a) * 20, ccy + sin(a) * 20]);
    }
    washPoly(innerR, PAL.claretRich, 245, 0.3);
    strokePoly(innerR, "cpencil", PAL.goldPale, 1.0, 0.3);

    resetBrushStates();
    brush.set("cpencil", PAL.roseSoft, 1.4);
    brush.circle(ccx, ccy, 9, 0.1);
    brush.set("engraver", PAL.whiteSpec, 0.9);
    brush.circle(ccx - 2, ccy - 2, 3.5, 0.1);
  }

  // 6. Authentic Chromolithograph Printer's Registration Marks & Color Plate Blocks in Outer Margin
  resetBrushStates();
  // Registration crosshairs at top, bottom, left, right centers
  const regCenters = [[600, 30], [600, 1172], [30, 600], [1170, 600]];
  for (let [rx, ry] of regCenters) {
    brush.set("engraver", PAL.prussianDark, 0.65);
    brush.circle(rx, ry, 7, 0.05);
    brush.line(rx - 12, ry, rx + 12, ry);
    brush.line(rx, ry - 12, rx, ry + 12);
    brush.set("engraver", PAL.claretRich, 0.5);
    brush.line(rx - 9, ry + 0.8, rx + 9, ry + 0.8);
  }

  // 6-Plate Chromolitho Ink Step-Wedge at lower right margin
  const plateCols = [PAL.prussianDeep, PAL.umberDark, PAL.goldOchre, PAL.claretRich, PAL.roseSoft, PAL.pistachioMid];
  for (let i = 0; i < plateCols.length; i++) {
    let bx = 920 + i * 18;
    let by = 1166;
    washPoly([[bx, by], [bx + 14, by], [bx + 14, by + 10], [bx, by + 10]], plateCols[i], 235);
    strokePoly([[bx, by], [bx + 14, by], [bx + 14, by + 10], [bx, by + 10]], "engraver", PAL.umberBlack, 0.55);
  }
  resetBrushStates();
}

