  // 1. Cream ground + subtle woven linen paper grain
  background(PALETTE.creamGround);
  renderSubtleCreamGroundTexture();

  // 2. Build 3D cloth heightfield, fabric UV coordinates, and ray-marched lighting
  buildClothTopographyAndLighting();

  // 3. Generate topographic running-stitch streamlines (5 hierarchical passes)
  generateTopographicContourStitches();

  // 4. Generate cross-contour crease & deep hollow stitches for velvety shadow depth
  generateDeepCreaseCrossStitches();

  // 5. Generate classic handkerchief woven border bands & rolled hem stitches
  generateHandkerchiefBorderAndHemStitches();

  // 6. Generate cast drop-shadow running stitches on the cream ground
  generateTableDropShadowStitches();

  // 7. Generate the frayed hem unraveling threads & corner mend bar-tacks
  generateFrayedCornerThreadsAndMends();

  // 8. Generate the woven darning lattice & buttonhole rim over the hole
  generateDarnedHoleStitches();

  // 9. Flush all batched running-stitch segments through p5.brush
  flushAllStitchBatches();

  noLoop();
}

