function renderSubtleCreamGroundTexture() {
  // Very delicate, sparse warm cream background fiber dashes so the ground feels tactile
  brush.set("2H", PALETTE.creamWeave1, 0.28);
  for (let i = 0; i < 420; i++) {
    let x = random(30, 1170);
    let y = random(30, 1170);
    let len = random(8, 22);
    let ang = (i % 2 === 0) ? random(-2, 2) : random(88, 92);
    let dx = cos(ang) * len;
    let dy = sin(ang) * len;
    brush.line(x, y, x + dx, y + dy);
