  darknessGrid = new Float32Array(N);
  warmthGrid = new Float32Array(N);
  concavityGrid = new Float32Array(N);
  tableShadowGrid = new Float32Array(N);

  // Sculpted anatomical fold ridges: quadratic Bezier spines with asymmetric cross-sections
  // [x0, y0, x1, y1, x2, y2, peakH, wLeft, wRight, power, troughDepth]
  const ridges = [
    // R1: Grand diagonal ridge from center-left pinch toward top-right corner
    [415, 535, 635, 385, 935, 215, 118, 92, 24, 1.65, 26],
