    [475, 610, 535, 795, 575, 985, 86, 72, 23, 1.60, 22],
    // R7: Foreground framing fold sheltering the lower-right darned corner
    [615, 615, 680, 765, 718, 975, 72, 64, 21, 1.65, 18],
    // R8: Upper-center secondary buckle toward top edge
    [520, 425, 565, 285, 615, 165, 78, 58, 20, 1.65, 18],
    // R9: Left-flank secondary fold
    [435, 555, 290, 595, 155, 625, 68, 22, 56, 1.65, 16],
    // R10: Gentle Diagonal Undulation across the lower-right anchor corner
    [695, 645, 840, 735, 985, 825, 40, 72, 48, 1.75, 10],
    // R11: Subtle counter-roll near extreme bottom-right tip
    [725, 875, 855, 915, 985, 965, 26, 52, 34, 1.75, 6],
    // R12: Upper-right secondary fan fold
    [675, 385, 825, 355, 975, 365, 62, 55, 22, 1.65, 14]
  ];

  // Concave pinch hollows (d-cone dimples where folds meet)
  const hollows = [
    [485, 495, 68, 38],
    [605, 525, 62, 34],
    [425, 615, 58, 28],
    [665, 445, 54, 26],
