  ];

  const cosH = Math.cos(HOLE_ANGLE);
  const sinH = Math.sin(HOLE_ANGLE);

  // Step 2a: Evaluate raw continuous 3D heightfield hRawGrid across the canvas
  for (let gy = 0; gy < GH; gy++) {
