      let h = Math.max(0, 24 * (1 - 0.65 * r2));

      // Sum anatomical Bezier fold ridges
      for (let r = 0; r < ridges.length; r++) {
        let R = ridges[r];
        let info = closestPointOnQuadBezier(x, y, R[0], R[1], R[2], R[3], R[4], R[5]);
        let d = info.signedDist;
        let t = info.t;

        // Smooth longitudinal taper at spine endpoints
        let env = Math.sin(Math.PI * constrain(t, 0.02, 0.98));
        env = Math.pow(env, 0.65);

        let w = (d < 0) ? R[7] : R[8];
        // Slight narrowing of fold near pinch start (t -> 0)
        w *= (0.72 + 0.45 * t);

        let uDist = Math.abs(d) / w;
        if (uDist < 3.2) {
          let ridgeProf = Math.exp(-Math.pow(uDist, R[9]));
          h += R[6] * env * ridgeProf;
        }
        // Adjacent parallel trough on the steep side (d > 0) for crisp fold-under illusion
        if (d > 0) {
          let tDist = (d - R[8] * 1.15) / (R[8] * 1.35);
          if (Math.abs(tDist) < 2.2) {
            h -= R[10] * env * Math.exp(-tDist * tDist);
          }
        }
      }

      // Subtract d-cone pinch hollows
      for (let k = 0; k < hollows.length; k++) {
        let H = hollows[k];
        let dxh = (x - H[0]) / H[2];
        let dyh = (y - H[1]) / H[2];
        let d2 = dxh * dxh + dyh * dyh;
        if (d2 < 4.0) {
          h -= H[3] * Math.exp(-d2);
        }
      }

      // Subtle multi-scale cotton crumple micro-relief
      let n1 = noise(x * 0.0065, y * 0.0065);
      let n2 = noise(x * 0.018 + 40, y * 0.018 + 40);
      h += (n1 - 0.48) * 22 + (n2 - 0.5) * 7.5;

      // Normalized distance to the darned hole in the lower-right corner
      let hx = x - HOLE_CX;
      let hy = y - HOLE_CY;
      let hrx = (hx * cosH + hy * sinH) / HOLE_RX;
      let hry = (-hx * sinH + hy * cosH) / HOLE_RY;
      let hAngle = Math.atan2(hry, hrx);
      let rimWobble = 1.0 + 0.07 * Math.sin(hAngle * 3 + 0.7) + 0.04 * Math.cos(hAngle * 5 - 1.2);
      let hDist = Math.sqrt(hrx * hrx + hry * hry) / rimWobble;
      holeDistGrid[idx] = hDist;

      // Radial darning tension puckers around the mended hole!
      if (hDist > 0.75 && hDist < 2.6) {
        let puckerEnv = Math.exp(-Math.pow((hDist - 1.25) / 0.65, 2));
        let puckerWave = Math.sin(hAngle * 11 + 0.4 * Math.sin(hAngle * 3));
        let rimLip = Math.exp(-Math.pow((hDist - 1.06) / 0.22, 2)) * 6.5;
        h += puckerEnv * puckerWave * 5.2 + rimLip;
      }

      hRawGrid[idx] = Math.max(2.0, h);
    }
  }

  // Step 2b: Smooth heightfield slightly for clean gradient & fabric foreshortening
  gaussianBlurGrid(hRawGrid, hSmoothGrid, GW, GH, 2);

  // Step 2c: Compute warped fabric coordinates (u, v) in [-1, 1]^2 & cloth mask
  // Nominal handkerchief center & orientation
  const cx0 = 582;
  const cy0 = 578;
  const halfSpanX = 378;
  const halfSpanY = 376;
  const rotAng = 0.065; // slight natural tilt (~3.7 degrees)
  const cosR = Math.cos(rotAng);
  const sinR = Math.sin(rotAng);

  for (let gy = 1; gy < GH - 1; gy++) {
    let y = (gy + 0.5) * CELL;
    for (let gx = 1; gx < GW - 1; gx++) {
      let x = (gx + 0.5) * CELL;
      let idx = gy * GW + gx;

      // Local height gradient for 3D cloth foreshortening warp
      let dhdx = (hSmoothGrid[idx + 1] - hSmoothGrid[idx - 1]) / (2 * CELL);
      let dhdy = (hSmoothGrid[idx + GW] - hSmoothGrid[idx - GW]) / (2 * CELL);

      // Central gather pinch pulls outer edges inward along troughs, pushes out on ridges
      let rx = x - cx0;
      let ry = y - cy0;
      let sx = (rx * cosR + ry * sinR) / halfSpanX;
      let sy = (-rx * sinR + ry * cosR) / halfSpanY;

      // Asymmetric corner pull: lower-right corner (sx > 0, sy > 0) extends out further
      let cornerPullX = (sx > 0 && sy > 0) ? -0.085 * sx * sy : 0.04 * (1 - sy * sy);
      let cornerPullY = (sx > 0 && sy > 0) ? -0.095 * sx * sy : 0.045 * (1 - sx * sx);

      // Edge ruffling wave linked directly to 3D fold elevation hSmoothGrid
      let hVal = hSmoothGrid[idx];
      let edgePush = (hVal - 42) * 0.00145;

      // Foreshortening shift: climbing a slope shifts fabric coordinate
      let u = sx * (1.0 - edgePush) + cornerPullX - dhdx * 0.032;
      let v = sy * (1.0 - edgePush) + cornerPullY - dhdy * 0.032;

      // Organic hand-woven edge waviness
      let edgeNoiseU = (noise(y * 0.009, 12.3) - 0.5) * 0.055 + (noise(y * 0.025, 45.1) - 0.5) * 0.018;
      let edgeNoiseV = (noise(x * 0.009, 78.9) - 0.5) * 0.055 + (noise(x * 0.025, 31.7) - 0.5) * 0.018;
      u += edgeNoiseU;
      v += edgeNoiseV;

      // Faint pocket quarter-fold crease memory near u = 0 and v = 0
      let qCreaseU = Math.exp(-Math.pow(u / 0.028, 2)) * 5.5;
      let qCreaseV = Math.exp(-Math.pow(v / 0.028, 2)) * 4.8;
      hRawGrid[idx] += qCreaseU + qCreaseV;

      uGrid[idx] = u;
      vGrid[idx] = v;

      let maxUV = Math.max(Math.abs(u), Math.abs(v));
      let hDist = holeDistGrid[idx];

      // Determine final height with lifted scalloped arches at the outer hem
      if (maxUV <= 1.0) {
        // Taper height gently near edge but keep 45% of ridge height so folds arch off table
        let edgeDist = 1.0 - maxUV;
        let edgeFactor = constrain(edgeDist / 0.11, 0, 1);
        edgeFactor = edgeFactor * edgeFactor * (3 - 2 * edgeFactor);
        let hEdgeArch = 3.5 + 0.46 * hRawGrid[idx];
        let hCloth = lerp(hEdgeArch, hRawGrid[idx], edgeFactor);

        // Inside the torn opening of the darned hole, cloth surface drops to table/darning plane
        if (hDist < 0.96) {
          maskGrid[idx] = 0; // Topographic cloth contour lines stop at the hole rim
          clothPresenceGrid[idx] = 0.0;
          hFinalGrid[idx] = 3.2;
        } else {
          maskGrid[idx] = 1;
          clothPresenceGrid[idx] = 1.0;
          hFinalGrid[idx] = hCloth;
        }
      } else {
        maskGrid[idx] = 0;
        clothPresenceGrid[idx] = 0.0;
        hFinalGrid[idx] = 0.0;
      }
    }
  }

  // Smooth heightfield used for topographic contour tangents so stitches flow silkily
  gaussianBlurGrid(hRawGrid, hSmoothGrid, GW, GH, 3);

  // Step 2d: Compute surface normals, concavity, and ray-marched soft shadows
  // Key light from warm upper-left
  const lx = -0.61;
  const ly = -0.54;
  const lz = 0.58;

  for (let gy = 2; gy < GH - 2; gy++) {
    let y = (gy + 0.5) * CELL;
    for (let gx = 2; gx < GW - 2; gx++) {
      let x = (gx + 0.5) * CELL;
      let idx = gy * GW + gx;

      // Topographic contour gradient (from continuous cloth sheet hSmoothGrid)
      let s_dx = (hSmoothGrid[idx + 1] - hSmoothGrid[idx - 1]) / (2 * CELL);
      let s_dy = (hSmoothGrid[idx + GW] - hSmoothGrid[idx - GW]) / (2 * CELL);
      gxGrid[idx] = s_dx;
      gyGrid[idx] = s_dy;

      // Detailed lighting gradient & Laplacian concavity
      let dhdx = (hFinalGrid[idx + 1] - hFinalGrid[idx - 1]) / (2 * CELL);
      let dhdy = (hFinalGrid[idx + GW] - hFinalGrid[idx - GW]) / (2 * CELL);
      let d2x = hFinalGrid[idx + 1] - 2 * hFinalGrid[idx] + hFinalGrid[idx - 1];
      let d2y = hFinalGrid[idx + GW] - 2 * hFinalGrid[idx] + hFinalGrid[idx - GW];
      let lap = (d2x + d2y) / (CELL * CELL); // > 0 in concave valley troughs

      // Ray-march toward the upper-left light source for soft cast shadows
      let z0 = hFinalGrid[idx];
      let maxShadow = 0.0;
      for (let step = 1; step <= 22; step++) {
        let dist = step * 6.5;
        let rx = x + lx * dist;
        let ry = y + ly * dist;
        let rz = z0 + lz * dist * 0.72;

        let rgx = Math.floor(rx / CELL);
        let rgy = Math.floor(ry / CELL);
        if (rgx < 1 || rgx >= GW - 1 || rgy < 1 || rgy >= GH - 1) break;

        let rIdx = rgy * GW + rgx;
        let occluderH = hFinalGrid[rIdx];
        if (occluderH > rz) {
          let diff = occluderH - rz;
          // Soft penumbra attenuation with distance
          let sVal = constrain(diff / (8.0 + 0.22 * dist), 0, 1);
          if (sVal > maxShadow) maxShadow = sVal;
        }
      }

      if (maskGrid[idx] === 1) {
        // Surface normal (-dhdx, -dhdy, 1)
        let invLen = 1.0 / Math.sqrt(dhdx * dhdx + dhdy * dhdy + 1.0);
        let nx = -dhdx * invLen;
        let ny = -dhdy * invLen;
        let nz = invLen;

        let ndotl = constrain(nx * lx + ny * ly + nz * lz, 0, 1);
        // Remap diffuse light for strong sculptural chiaroscuro
        let diffuseDark = Math.pow(1.0 - ndotl, 1.38);

        // Valley concavity ambient occlusion
        let concav = constrain(lap * 1.45, 0, 1);
        let lowValleyAO = constrain((42.0 - z0) / 55.0, 0, 0.38);

        // Combine diffuse shading, cast shadow, and valley crevice occlusion
        let dark = diffuseDark * 0.62 + maxShadow * 0.44 + concav * 0.34 + lowValleyAO * 0.25;
        dark = constrain(dark, 0.02, 0.98);

        // Warm subsurface / reflected bounce light on mid-tone slopes & facing walls
        let slopeMag = Math.sqrt(dhdx * dhdx + dhdy * dhdy);
        let midToneBell = Math.exp(-Math.pow((dark - 0.42) / 0.24, 2));
        let bounceDir = constrain((nx * 0.55 + ny * 0.55), 0, 1);
        let warmth = constrain(midToneBell * 0.68 + bounceDir * 0.35 + (1 - dark) * 0.22 - concav * 0.25, 0.05, 0.95);

        darknessGrid[idx] = dark;
        warmthGrid[idx] = warmth;
        concavityGrid[idx] = concav;
      } else {
        // Outside cloth (or inside hole): record cast drop shadow on the cream ground
        tableShadowGrid[idx] = maxShadow;
      }
    }
  }

  // Smooth darkness & table shadow grids slightly for natural penumbra transitions
  let tmpGrid = new Float32Array(N);
  gaussianBlurGrid(darknessGrid, tmpGrid, GW, GH, 1);
  darknessGrid.set(tmpGrid);
  gaussianBlurGrid(tableShadowGrid, tmpGrid, GW, GH, 2);
  tableShadowGrid.set(tmpGrid);
}

// ============================================================================
// 3. HIERARCHICAL 5-PASS TOPOGRAPHIC CONTOUR RUNNING STITCHES
// ============================================================================
function generateTopographicContourStitches() {
  // Occupancy distance grid shared across all 5 passes so new contour streamlines
  // nest cleanly halfway between existing contour streamlines!
  const occW = 1200;
  const occH = 1200;
  let occGrid = new Uint8Array(occW * occH);

  // 5 Hierarchical Density Passes: from wide master contours (spanning lit ridges + shadows)
  // down to ultra-tight shadow hollow contour packing
  const passes = [
    { dSep: 18, dTest: 13, minDark: 0.04, maxSteps: 260, seedStep: 11, passId: 0 },
    { dSep: 10, dTest: 7,  minDark: 0.16, maxSteps: 220, seedStep: 7,  passId: 1 },
    { dSep: 5,  dTest: 3.6, minDark: 0.30, maxSteps: 190, seedStep: 4, passId: 2 },
    { dSep: 2.8, dTest: 2.0, minDark: 0.48, maxSteps: 160, seedStep: 3, passId: 3 },
    { dSep: 1.7, dTest: 1.2, minDark: 0.66, maxSteps: 130, seedStep: 2, passId: 4 }
  ];

  const stepLen = 2.0; // Integration step in pixels

  for (let p = 0; p < passes.length; p++) {
    let cfg = passes[p];

    // Generate jittered candidate seeds across the handkerchief
    let seeds = [];
    for (let y = 125; y < 1075; y += cfg.seedStep) {
      for (let x = 125; x < 1075; x += cfg.seedStep) {
        let sx = x + random(-cfg.seedStep * 0.4, cfg.seedStep * 0.4);
        let sy = y + random(-cfg.seedStep * 0.4, cfg.seedStep * 0.4);
        if (!isInsideCloth(sx, sy)) continue;
        let dark = sampleGrid(darknessGrid, sx, sy);
        if (dark >= cfg.minDark * 0.85) {
          seeds.push({ x: sx, y: sy, dark: dark });
        }
      }
    }

    // Sort seeds so deepest hollows/creases get prime contour placement first
    seeds.sort((a, b) => b.dark - a.dark);

    // Occupancy bitmask per pass: mark disk of radius dSep around accepted points
    // Wait: to allow Pass p+1 to nest between Pass p lines, we check against a freshly
    // dilated occupancy grid built from all previously accepted streamline points!
    let allAcceptedPts = (p === 0) ? [] : passes[p - 1]._acceptedPts;
    if (p === 0) cfg._acceptedPts = [];
    else cfg._acceptedPts = allAcceptedPts;

    // Rebuild occupancy grid for current pass separation radius cfg.dTest
    occGrid.fill(0);
    let rMark = Math.ceil(cfg.dTest);
    let rMark2 = cfg.dTest * cfg.dTest;
    let ptsList = cfg._acceptedPts;
    for (let i = 0; i < ptsList.length; i += 2) {
      markOccupancyDisk(occGrid, occW, occH, ptsList[i], ptsList[i + 1], rMark, rMark2);
    }

    let rSep = Math.ceil(cfg.dSep);
    let rSep2 = cfg.dSep * cfg.dSep;

    for (let s = 0; s < seeds.length; s++) {
      let sx = seeds[s].x;
      let sy = seeds[s].y;
      let ix = Math.floor(sx);
      let iy = Math.floor(sy);
      if (ix < 2 || ix >= occW - 2 || iy < 2 || iy >= occH - 2) continue;
      if (occGrid[iy * occW + ix] !== 0) continue;

      // Trace forward and backward along the 3D topographic contour tangent (-dH/dy, dH/dx)
      let fwd = traceContourHalfLine(sx, sy, 1.0, cfg.maxSteps, stepLen, occGrid, occW, occH, cfg.minDark);
      let bwd = traceContourHalfLine(sx, sy, -1.0, cfg.maxSteps, stepLen, occGrid, occW, occH, cfg.minDark);

      let totalPts = bwd.length + 1 + fwd.length;
      if (totalPts < 7) continue;

      // Assemble full streamline polyline
      let poly = [];
      for (let i = bwd.length - 1; i >= 0; i--) poly.push(bwd[i]);
      poly.push([sx, sy]);
      for (let i = 0; i < fwd.length; i++) poly.push(fwd[i]);

      // Mark streamline in current pass occupancy grid and save points for finer passes
      for (let i = 0; i < poly.length; i++) {
        let px = poly[i][0];
        let py = poly[i][1];
        markOccupancyDisk(occGrid, occW, occH, px, py, rSep, rSep2);
        if (i % 2 === 0) {
          cfg._acceptedPts.push(px, py);
        }
      }

      // Convert continuous contour streamline into discrete running-stitch dashes!
      emitRunningStitchesAlongPolyline(poly, cfg.passId, cfg.minDark);
    }
  }
}

function traceContourHalfLine(x0, y0, dirSign, maxSteps, stepLen, occGrid, occW, occH, minDark) {
  let pts = [];
  let cx = x0;
  let cy = y0;
  let prevVx = 0;
  let prevVy = 0;

  for (let step = 0; step < maxSteps; step++) {
    let tang = getTopographicContourTangent(cx, cy);
    let vx = tang[0] * dirSign;
    let vy = tang[1] * dirSign;

    // Maintain consistent orientation along streamline
    if (step > 0 && (vx * prevVx + vy * prevVy) < 0) {
      vx = -vx;
      vy = -vy;
    }

    // RK2 midpoint integration for smooth curvature around tight fold crests
    let mx = cx + vx * (stepLen * 0.5);
    let my = cy + vy * (stepLen * 0.5);
    let mTang = getTopographicContourTangent(mx, my);
    let mvx = mTang[0] * dirSign;
    let mvy = mTang[1] * dirSign;
    if (mvx * vx + mvy * vy < 0) {
      mvx = -mvx;
      mvy = -mvy;
    }

    let nx = cx + mvx * stepLen;
    let ny = cy + mvy * stepLen;

    if (!isInsideCloth(nx, ny)) break;

    let ix = Math.floor(nx);
    let iy = Math.floor(ny);
    if (ix < 2 || ix >= occW - 2 || iy < 2 || iy >= occH - 2) break;

    // Allow first 2 steps to clear starting neighborhood, then check occupancy collision
    if (step > 2 && occGrid[iy * occW + ix] !== 0) break;

    let dark = sampleGrid(darknessGrid, nx, ny);
    if (dark < minDark * 0.72) break;

    pts.push([nx, ny]);
    cx = nx;
    cy = ny;
    prevVx = mvx;
    prevVy = mvy;
  }
  return pts;
}

function getTopographicContourTangent(x, y) {
  let gx = sampleGrid(gxGrid, x, y);
  let gy = sampleGrid(gyGrid, x, y);
  // Subtle regularizer so stationary saddles/peaks still have clean tangent flow
  gx += 0.014;
  gy -= 0.011;
  // Contour tangent is perpendicular to elevation gradient: (-dH/dy, dH/dx)
  let tx = -gy;
  let ty = gx;
  let len = Math.sqrt(tx * tx + ty * ty) + 1e-6;
  return [tx / len, ty / len];
}

// ============================================================================
// RUNNING-STITCH DASH GENERATOR ALONG A CONTOUR POLYLINE
// ============================================================================
function emitRunningStitchesAlongPolyline(poly, passId, minDark) {
  // Compute cumulative arclength along polyline
  let n = poly.length;
  let arc = new Float32Array(n);
  arc[0] = 0;
  for (let i = 1; i < n; i++) {
    let dx = poly[i][0] - poly[i - 1][0];
    let dy = poly[i][1] - poly[i - 1][1];
    arc[i] = arc[i - 1] + Math.sqrt(dx * dx + dy * dy);
  }
  let totalLen = arc[n - 1];
  if (totalLen < 6.5) return;

  // Choose initial thread color and keep thread color coherent for 14..32 consecutive stitches
  let sCursor = random(0, 4.5);
  let stitchesRemainingInThread = Math.floor(random(14, 32));
  let currentThreadColor = null;
  let currentBrush = (passId >= 3) ? "thread" : (passId === 0 ? "rotring" : "needle");

  while (sCursor < totalLen - 3.5) {
    let ptStart = pointAtArcLength(poly, arc, sCursor);
    let mx = ptStart[0];
    let my = ptStart[1];

    let dark = sampleGrid(darknessGrid, mx, my);
    let warmth = sampleGrid(warmthGrid, mx, my);
    let concav = sampleGrid(concavityGrid, mx, my);
    let u = sampleGrid(uGrid, mx, my);
    let v = sampleGrid(vGrid, mx, my);

    // Check if local darkness warrants drawing a stitch on this pass
    if (dark < minDark) {
      sCursor += 6.0;
      continue;
    }

    // Modulate stitch dash length and gap length by local shadow darkness:
    // Shadow hollows -> longer bold dashes (7..10px) and tight gaps (1.8..3.2px)
    // Lit ridges -> delicate short dashes (4.5..6.5px) and wide breathing gaps (5.5..9.5px)
    let dashLen = lerp(4.8, 9.6, constrain(dark * 1.15, 0, 1)) * random(0.88, 1.12);
    let gapLen  = lerp(8.5, 2.0, constrain(Math.pow(dark, 0.78), 0, 1)) * random(0.85, 1.15);

    if (sCursor + dashLen > totalLen) break;

    let ptEnd = pointAtArcLength(poly, arc, sCursor + dashLen);

    // Refresh thread color only when starting a new thread run or crossing into border stripe
    let borderType = getHandkerchiefBorderBand(u, v);
    if (currentThreadColor === null || stitchesRemainingInThread <= 0 || borderType > 0) {
      currentThreadColor = pickThreadColor(dark, warmth, concav, passId, borderType);
      stitchesRemainingInThread = Math.floor(random(14, 30));
    }
    stitchesRemainingInThread--;

    // Quantized stroke weight based on shadow depth & pass hierarchy
    let wBase = lerp(0.36, 0.86, constrain(dark * 0.9 + concav * 0.25, 0, 1));
    if (passId === 0 && dark < 0.25) wBase = 0.36;
    if (borderType > 0) wBase = Math.max(wBase, 0.56);

    // Subtle hand-stitched organic micro-jitter
    let jx1 = random(-0.28, 0.28);
    let jy1 = random(-0.28, 0.28);
    let jx2 = random(-0.28, 0.28);
    let jy2 = random(-0.28, 0.28);

    addStitchSegment(currentBrush, currentThreadColor, wBase,
      ptStart[0] + jx1, ptStart[1] + jy1,
      ptEnd[0] + jx2, ptEnd[1] + jy2
    );

    sCursor += dashLen + gapLen;
  }
}

function getHandkerchiefBorderBand(u, v) {
  let maxUV = Math.max(Math.abs(u), Math.abs(v));
  // Classic vintage handkerchief double border stripe near the 4 edges
  if (maxUV >= 0.885 && maxUV <= 0.916) return 1; // Wide primary madder/indigo stripe
  if (maxUV >= 0.848 && maxUV <= 0.862) return 2; // Inner mustard/indigo pinstripe
  if (maxUV >= 0.936 && maxUV <= 0.948) return 3; // Outer madder pinstripe
  return 0;
}

function pickThreadColor(dark, warmth, concav, passId, borderType) {
  // If crossing one of the handkerchief's woven border bands, bias strongly to stripe color
  if (borderType === 1) {
    if (dark > 0.58) return (random() < 0.65) ? PALETTE.madderDeep : PALETTE.indigoDeep;
    return (random() < 0.78) ? PALETTE.madderVivid : PALETTE.indigoVivid;
  }
  if (borderType === 2) {
    return (dark > 0.52) ? PALETTE.indigoDark : (random() < 0.72 ? PALETTE.mustardVivid : PALETTE.indigoVivid);
  }
  if (borderType === 3) {
    return (dark > 0.55) ? PALETTE.madderDeep : PALETTE.madderBright;
  }

  let r = random();

  // 1. Deepest shadowed hollows & sharp tucked creases (dark > 0.68)
  if (dark > 0.68) {
    if (r < 0.52) return PALETTE.indigoDeep;
    if (r < 0.76) return PALETTE.indigoDark;
    if (r < 0.93) return PALETTE.madderDeep; // Rich crimson-madder depth in shadow core
    return PALETTE.mustardDeep;
  }

  // 2. Medium-dark shadow slopes (0.46 < dark <= 0.68)
  if (dark > 0.46) {
    if (warmth > 0.58) {
      // Warm bounce-light shadow slope: madder red & indigo optical weave
      if (r < 0.38) return PALETTE.madderVivid;
      if (r < 0.58) return PALETTE.madderDeep;
      if (r < 0.84) return PALETTE.indigoDark;
      return PALETTE.mustardDeep;
    } else {
      if (r < 0.46) return PALETTE.indigoDark;
      if (r < 0.68) return PALETTE.indigoVivid;
      if (r < 0.88) return PALETTE.madderDeep;
      return PALETTE.mustardVivid;
    }
  }

  // 3. Mid-tone turn of the form (0.24 < dark <= 0.46)
  if (dark > 0.24) {
    if (warmth > 0.52) {
      if (r < 0.42) return PALETTE.madderVivid;
      if (r < 0.62) return PALETTE.madderBright;
      if (r < 0.84) return PALETTE.mustardVivid;
      return PALETTE.indigoVivid;
    } else {
      if (r < 0.36) return PALETTE.indigoVivid;
      if (r < 0.66) return PALETTE.madderVivid;
      if (r < 0.90) return PALETTE.mustardVivid;
      return PALETTE.indigoBright;
    }
  }

  // 4. Sunlit ridges & high slopes (dark <= 0.24)
  // Faded mustard & warm madder dominate sunlit crests, with sparse crisp indigo structural traces
  if (r < 0.46) return PALETTE.mustardWarm;
  if (r < 0.68) return PALETTE.mustardVivid;
  if (r < 0.86) return PALETTE.madderBright;
  return PALETTE.indigoBright;
}

// ============================================================================
// 4. DEEP CREASE & HOLLOW CROSS-CONTOUR STITCHES
// ============================================================================
function generateDeepCreaseCrossStitches() {
  // In the deepest concave hollows and sharp fold overhangs, add a secondary pass
  // of slightly angled cross-contour running stitches so the shadow cores pack with rich density
  const occW = 1200;
  const occH = 1200;
  let occGrid = new Uint8Array(occW * occH);
  const dSep = 2.6;
  const rSep = Math.ceil(dSep);
  const rSep2 = dSep * dSep;

  for (let y = 140; y < 1060; y += 4) {
    for (let x = 140; x < 1060; x += 4) {
      let sx = x + random(-1.8, 1.8);
      let sy = y + random(-1.8, 1.8);
      if (!isInsideCloth(sx, sy)) continue;

      let dark = sampleGrid(darknessGrid, sx, sy);
      let concav = sampleGrid(concavityGrid, sx, sy);
      if (dark < 0.56 && concav < 0.45) continue;

      let ix = Math.floor(sx);
      let iy = Math.floor(sy);
      if (occGrid[iy * occW + ix] !== 0) continue;

      // Trace a short streamline angled ~28 degrees from the primary contour tangent
      let poly = [[sx, sy]];
      let cx = sx;
      let cy = sy;
      let rotCos = Math.cos(0.48);
      let rotSin = Math.sin(0.48);

      for (let step = 0; step < 36; step++) {
        let t = getTopographicContourTangent(cx, cy);
        let vx = t[0] * rotCos - t[1] * rotSin;
        let vy = t[0] * rotSin + t[1] * rotCos;
        let nx = cx + vx * 2.0;
        let ny = cy + vy * 2.0;
        if (!isInsideCloth(nx, ny)) break;
        if (sampleGrid(darknessGrid, nx, ny) < 0.50) break;
        poly.push([nx, ny]);
        markOccupancyDisk(occGrid, occW, occH, nx, ny, rSep, rSep2);
        cx = nx;
        cy = ny;
      }

      if (poly.length >= 6) {
        emitRunningStitchesAlongPolyline(poly, 4, 0.52);
      }
    }
  }
}

// ============================================================================
// 5. WOVEN HANDKERCHIEF BORDER STRIPES & ROLLED HEM STITCHES
// ============================================================================
function generateHandkerchiefBorderAndHemStitches() {
  // Trace continuous contour rings at constant fabric border coordinates max(|u|, |v|) = level
  // Because (u, v) is warped by 3D fold elevation & gradient, these border lines naturally
  // curve, compress, and dip through every fold around all 4 sides of the handkerchief!
  const borderLevels = [
    // Inner mustard/indigo pinstripe
    { level: 0.852, colLight: PALETTE.mustardVivid, colDark: PALETTE.indigoDark, weight: 0.52, dash: 6.5, gap: 3.0 },
    { level: 0.857, colLight: PALETTE.indigoVivid,  colDark: PALETTE.indigoDeep, weight: 0.48, dash: 6.5, gap: 3.2 },

    // Main wide Madder Red & Indigo woven border band (multiple parallel stitched threads)
    { level: 0.886, colLight: PALETTE.madderVivid,  colDark: PALETTE.madderDeep, weight: 0.62, dash: 7.5, gap: 2.2 },
    { level: 0.891, colLight: PALETTE.madderBright, colDark: PALETTE.madderDeep, weight: 0.64, dash: 7.5, gap: 2.0 },
    { level: 0.896, colLight: PALETTE.madderVivid,  colDark: PALETTE.indigoDeep, weight: 0.66, dash: 7.8, gap: 2.0 },
    { level: 0.901, colLight: PALETTE.indigoVivid,  colDark: PALETTE.indigoDeep, weight: 0.64, dash: 7.5, gap: 2.2 },
    { level: 0.906, colLight: PALETTE.indigoDark,   colDark: PALETTE.indigoDeep, weight: 0.62, dash: 7.5, gap: 2.2 },
    { level: 0.911, colLight: PALETTE.madderVivid,  colDark: PALETTE.madderDeep, weight: 0.58, dash: 7.2, gap: 2.4 },

    // Outer mustard/madder pinstripe
    { level: 0.940, colLight: PALETTE.mustardVivid, colDark: PALETTE.mustardDeep, weight: 0.52, dash: 6.8, gap: 2.8 },
    { level: 0.945, colLight: PALETTE.madderVivid,  colDark: PALETTE.madderDeep,  weight: 0.52, dash: 6.8, gap: 2.8 },

    // Rolled hem inner & outer seam lines
    { level: 0.976, colLight: PALETTE.indigoVivid,  colDark: PALETTE.indigoDeep,  weight: 0.62, dash: 6.2, gap: 2.4 },
    { level: 0.986, colLight: PALETTE.madderVivid,  colDark: PALETTE.indigoDeep,  weight: 0.66, dash: 6.5, gap: 2.2 },
    { level: 0.994, colLight: PALETTE.mustardDeep,  colDark: PALETTE.indigoDeep,  weight: 0.58, dash: 5.8, gap: 2.4 }
  ];

  // Extract iso-contours of max(|u|, |v|) on the 600x600 grid via marching squares segments
  for (let b = 0; b < borderLevels.length; b++) {
    let cfg = borderLevels[b];
    let target = cfg.level;

    for (let gy = 2; gy < GH - 3; gy++) {
      for (let gx = 2; gx < GW - 3; gx++) {
        let idx = gy * GW + gx;
        if (maskGrid[idx] === 0 && target < 0.98) continue;

        let f00 = Math.max(Math.abs(uGrid[idx]), Math.abs(vGrid[idx])) - target;
        let f10 = Math.max(Math.abs(uGrid[idx + 1]), Math.abs(vGrid[idx + 1])) - target;
        let f01 = Math.max(Math.abs(uGrid[idx + GW]), Math.abs(vGrid[idx + GW])) - target;
        let f11 = Math.max(Math.abs(uGrid[idx + GW + 1]), Math.abs(vGrid[idx + GW + 1])) - target;

        let x0 = (gx + 0.5) * CELL;
        let y0 = (gy + 0.5) * CELL;

        // Collect edge zero-crossings of the cell
        let crossings = [];
        if (f00 * f10 <= 0 && Math.abs(f10 - f00) > 1e-5) {
          let t = -f00 / (f10 - f00);
          crossings.push([x0 + t * CELL, y0]);
        }
        if (f10 * f11 <= 0 && Math.abs(f11 - f10) > 1e-5) {
          let t = -f10 / (f11 - f10);
          crossings.push([x0 + CELL, y0 + t * CELL]);
        }
        if (f01 * f11 <= 0 && Math.abs(f11 - f01) > 1e-5) {
          let t = -f01 / (f11 - f01);
          crossings.push([x0 + t * CELL, y0 + CELL]);
        }
        if (f00 * f01 <= 0 && Math.abs(f01 - f00) > 1e-5) {
          let t = -f00 / (f01 - f00);
          crossings.push([x0, y0 + t * CELL]);
        }

        if (crossings.length >= 2) {
          let mx = 0.5 * (crossings[0][0] + crossings[1][0]);
          let my = 0.5 * (crossings[0][1] + crossings[1][1]);
          if (sampleGrid(holeDistGrid, mx, my) < 1.02) continue;

          // Rhythmic running-stitch gating along the perimeter using spatial phase
          let phase = (mx * 0.65 + my * 0.65 + b * 3.7) % (cfg.dash + cfg.gap);
          if (phase < cfg.dash) {
            let dark = sampleGrid(darknessGrid, mx, my);
            let col = (dark > 0.52) ? cfg.colDark : cfg.colLight;
            let w = cfg.weight * lerp(0.82, 1.25, dark);
            addStitchSegment("needle", col, w,
              crossings[0][0], crossings[0][1],
              crossings[1][0], crossings[1][1]
            );
          }

          // Along the outer rolled hem (level == 0.994), add tiny perpendicular whip stitches
          if (b === borderLevels.length - 1 && (gx + gy) % 3 === 0) {
            let dx = crossings[1][0] - crossings[0][0];
            let dy = crossings[1][1] - crossings[0][1];
            let len = Math.sqrt(dx * dx + dy * dy) + 1e-5;
            let nx = -dy / len;
            let ny = dx / len;
            let dark = sampleGrid(darknessGrid, mx, my);
            let whipCol = (dark > 0.48) ? PALETTE.indigoDeep : (random() < 0.6 ? PALETTE.madderVivid : PALETTE.mustardDeep);
            addStitchSegment("needle", whipCol, 0.52,
              mx - nx * 3.2, my - ny * 3.2,
              mx + nx * 3.2, my + ny * 3.2
            );
          }
        }
      }
    }
  }
}

// ============================================================================
// 6. TABLE DROP-SHADOW RUNNING STITCHES ON THE CREAM GROUND
// ============================================================================
function generateTableDropShadowStitches() {
  // Outside the cloth mask where the lifted handkerchief casts a shadow onto the cream table,
  // draw parallel running-stitch dashes that pack tightly right under the lifted hem and
  // thin out across the soft penumbra.
  for (let y = 135; y < 1075; y += 2.6) {
    let xCursor = 135 + random(0, 5);
    while (xCursor < 1075) {
      let sh = sampleGrid(tableShadowGrid, xCursor, y);
      let inCloth = isInsideCloth(xCursor, y);
      let hDist = sampleGrid(holeDistGrid, xCursor, y);

      if (inCloth || hDist < 1.05 || sh < 0.06) {
        xCursor += 4.5;
        continue;
      }

      // Probability of active shadow contour row scales with shadow intensity
      let rowMod = Math.floor(y / 2.6);
      let active = false;
      if (sh > 0.62) active = true;
      else if (sh > 0.38 && rowMod % 2 === 0) active = true;
      else if (sh > 0.18 && rowMod % 4 === 0) active = true;
      else if (sh > 0.07 && rowMod % 8 === 0) active = true;

      if (!active) {
        xCursor += 5.0;
        continue;
      }

      let dashLen = lerp(4.5, 8.2, sh) * random(0.9, 1.1);
      let gapLen  = lerp(7.5, 2.2, sh) * random(0.9, 1.1);

      // Slight contour curve hugging the cloth boundary
      let ang = -0.08 + 0.12 * Math.sin(xCursor * 0.01 + y * 0.01);
      let x2 = xCursor + Math.cos(ang) * dashLen;
      let y2 = y + Math.sin(ang) * dashLen;

      if (!isInsideCloth(x2, y2)) {
        let r = random();
        let col = (sh > 0.52)
          ? (r < 0.68 ? PALETTE.indigoDeep : (r < 0.88 ? PALETTE.indigoDark : PALETTE.madderDeep))
          : (r < 0.45 ? PALETTE.indigoVivid : (r < 0.75 ? PALETTE.mustardDeep : PALETTE.madderVivid));
        let w = lerp(0.36, 0.72, sh);
        addStitchSegment("needle", col, w, xCursor, y, x2, y2);
      }

      xCursor += dashLen + gapLen;
    }
  }
}

// ============================================================================
// 7. FRAYED HEM UNRAVELING THREADS & ANCHOR CORNER MEND BAR-TACKS
// ============================================================================
function generateFrayedCornerThreadsAndMends() {
  // Scan around the boundary (max(|u|,|v|) == 1.0), focusing strongly on the lower-right
  // anchor corner (u > 0.25, v > 0.25) and minor frays on the other corners
  for (let gy = 10; gy < GH - 10; gy++) {
    for (let gx = 10; gx < GW - 10; gx++) {
      let idx = gy * GW + gx;
      let u = uGrid[idx];
      let v = vGrid[idx];
      let maxUV = Math.max(Math.abs(u), Math.abs(v));
      if (maxUV < 0.985 || maxUV > 1.008) continue;

      let x = (gx + 0.5) * CELL;
      let y = (gy + 0.5) * CELL;

      // Determine if we are in the hero lower-right anchor corner
      let isHeroCorner = (u > 0.22 && v > 0.22);
      let isTip = (u > 0.82 && v > 0.82);
      let frayProb = isTip ? 0.85 : (isHeroCorner ? 0.42 : 0.06);
      if (random() > frayProb) continue;

      // Outward normal direction from the handkerchief edge
      let outX = (Math.abs(u) >= Math.abs(v)) ? Math.sign(u) : 0.25 * Math.sign(u);
      let outY = (Math.abs(v) >= Math.abs(u)) ? Math.sign(v) : 0.25 * Math.sign(v);
      let outLen = Math.sqrt(outX * outX + outY * outY) + 1e-5;
      outX /= outLen;
      outY /= outLen;

      // Also add woven warp/weft thread alignment so unraveling threads emerge along fabric grain
      let baseAng = Math.atan2(outY, outX) + random(-0.32, 0.32);
      let threadLen = isTip ? random(16, 44) : (isHeroCorner ? random(10, 32) : random(7, 16));
      let nSteps = Math.max(3, Math.floor(threadLen / 4.2));

      // Choose thread color: cream-mustard cotton warp, madder border thread, or indigo thread
      let r = random();
      let col = (r < 0.44) ? PALETTE.mustardWarm
              : (r < 0.68) ? PALETTE.mustardDeep
              : (r < 0.86) ? PALETTE.madderVivid
              : PALETTE.indigoDark;

      let tx = x;
      let ty = y;
      let curAng = baseAng;
      let curlRate = random(-0.18, 0.22);

      for (let s = 0; s < nSteps; s++) {
        curAng += curlRate + random(-0.08, 0.08);
        let segLen = random(3.4, 5.2);
        let nx = tx + Math.cos(curAng) * segLen;
        let ny = ty + Math.sin(curAng) * segLen;

        // Tiny cast shadow of the loose thread on the cream table beneath it!
        addStitchSegment("needle", PALETTE.indigoDeep, 0.34,
          tx + 1.6, ty + 2.0,
          nx + 1.6, ny + 2.0
        );

        // The frayed thread segment itself
        addStitchSegment("needle", col, 0.46, tx, ty, nx, ny);

        tx = nx;
        ty = ny;
      }

      // In the hero lower-right corner, add occasional cross-frayed loose snippets lying on the cream ground
      if (isTip && random() < 0.18) {
        let sx = tx + random(3, 14);
        let sy = ty + random(2, 12);
        let sAng = random(0, Math.PI * 2);
        let sLen = random(5, 11);
        let sx2 = sx + Math.cos(sAng) * sLen;
        let sy2 = sy + Math.sin(sAng) * sLen;
        addStitchSegment("needle", PALETTE.indigoDeep, 0.32, sx + 1.2, sy + 1.5, sx2 + 1.2, sy2 + 1.5);
        addStitchSegment("needle", (random() < 0.5 ? PALETTE.madderVivid : PALETTE.mustardDeep), 0.44, sx, sy, sx2, sy2);
      }

      // Add reinforcing mended bar-tack / whip stitches holding the fraying corner hem together
      if (isHeroCorner && random() < 0.28) {
        let mCol = (random() < 0.62) ? PALETTE.madderVivid : PALETTE.indigoDark;
        let px = -outY;
        let py = outX;
        let bx = x - outX * random(2, 9);
        let by = y - outY * random(2, 9);
        addStitchSegment("thread", mCol, 0.68,
          bx - outX * 4.5 + px * 2.2, by - outY * 4.5 + py * 2.2,
          bx + outX * 3.5 - px * 2.2, by + outY * 3.5 - py * 2.2
        );
      }
    }
  }
}

// ============================================================================
// 8. THE DARNED HOLE (WOVEN OVER-UNDER LATTICE & BUTTONHOLE RIM)
// ============================================================================
function generateDarnedHoleStitches() {
  const cosH = Math.cos(HOLE_ANGLE);
  const sinH = Math.sin(HOLE_ANGLE);

  // Helper to convert local hole coordinates (uH, vH) in pixels to canvas (x, y)
  function holeToCanvas(uH, vH) {
    return [
      HOLE_CX + uH * cosH - vH * sinH,
      HOLE_CY + uH * sinH + vH * cosH
    ];
  }

  // Helper to evaluate normalized hole radius at local (uH, vH)
  function getNormHoleDist(uH, vH) {
    let nx = uH / HOLE_RX;
    let ny = vH / HOLE_RY;
    let ang = Math.atan2(ny, nx);
    let wobble = 1.0 + 0.07 * Math.sin(ang * 3 + 0.7) + 0.04 * Math.cos(ang * 5 - 1.2);
    return Math.sqrt(nx * nx + ny * ny) / wobble;
  }

  // 8a. Dark recessed rim shadow inside the upper-left lip of the hole (where the torn cloth
  // thickness casts a shadow onto the cream table and darning lattice below)
  for (let vH = -HOLE_RY * 1.05; vH <= HOLE_RY * 1.05; vH += 2.2) {
    for (let uH = -HOLE_RX * 1.05; uH <= HOLE_RX * 1.05; uH += 2.2) {
      let rNorm = getNormHoleDist(uH, vH);
      if (rNorm > 0.98) continue;

      // Upper-left crescent inside the opening receives deep lip shadow
      let lipShadow = constrain(1.0 - (uH + HOLE_RX * 0.35) / (HOLE_RX * 0.95), 0, 1) *
                      constrain(1.0 - (vH + HOLE_RY * 0.35) / (HOLE_RY * 0.95), 0, 1);
      let edgeShadow = (rNorm > 0.74) ? constrain((rNorm - 0.74) / 0.24, 0, 1) : 0;
      let totSh = Math.max(lipShadow * 0.85, edgeShadow * 0.75);

      if (totSh > 0.25 && random() < totSh) {
        let p1 = holeToCanvas(uH - 2.4, vH - 0.5);
        let p2 = holeToCanvas(uH + 2.4, vH + 0.5);
        let col = (totSh > 0.58) ? PALETTE.indigoDeep : PALETTE.indigoDark;
        addStitchSegment("needle", col, 0.58, p1[0], p1[1], p2[0], p2[1]);
      }
    }
  }

  // 8b. Woven Darning Lattice (Warp & Weft threads anchored well into the surrounding cotton!)
  const spacing = 3.1; // Thread spacing of the darning weave in pixels
  const maxSpanU = HOLE_RX * 1.62;
  const maxSpanV = HOLE_RY * 1.62;

  // Build grid of warp (along uH) and weft (along vH) intersections for authentic over-under weave
  let iCount = Math.floor((2 * maxSpanU) / spacing);
  let jCount = Math.floor((2 * maxSpanV) / spacing);

  // First: draw Warp darning threads (horizontal in local hole frame, tilted at 18.3 deg)
  for (let j = -Math.floor(jCount / 2); j <= Math.floor(jCount / 2); j++) {
    let vH = j * spacing + random(-0.22, 0.22);
    if (Math.abs(vH) > HOLE_RY * 1.22) continue;

    // Alternating feathered anchor reach into the intact fabric around the hole (1.22..1.58 * radius)
    let reachNorm = 1.24 + 0.28 * ((Math.abs(j * 7) % 5) / 4.0);

    // Choose warp thread color: primarily vivid Madder Red & deep Madder, with occasional Indigo guide threads
    let warpCol = (Math.abs(j) % 6 === 0) ? PALETTE.indigoDark
                : (Math.abs(j) % 2 === 0) ? PALETTE.madderVivid
                : PALETTE.madderBright;
    let warpColShadow = (Math.abs(j) % 6 === 0) ? PALETTE.indigoDeep : PALETTE.madderDeep;

    for (let i = -Math.floor(iCount / 2); i < Math.floor(iCount / 2); i++) {
      let u1 = i * spacing;
      let u2 = (i + 1) * spacing;
      let uMid = 0.5 * (u1 + u2);
      let rNorm = getNormHoleDist(uMid, vH);
      if (rNorm > reachNorm) continue;

      if (rNorm <= 1.02) {
        // Inside the hole: plain weave over-and-under!
        // When (i + j) % 2 === 0, Warp is ON TOP of Weft (draw continuous bridge segment)
        // When (i + j) % 2 !== 0, Warp dips UNDER Weft (draw shorter tucked under-segment)
        let isOver = ((i + j + 100) % 2 === 0);
        let trim = isOver ? 0.15 : 0.75;
        let p1 = holeToCanvas(u1 + trim, vH);
        let p2 = holeToCanvas(u2 - trim, vH);

        // Darken threads slightly near the upper-left shadowed rim of the hole
        let inLipShadow = (uMid < -HOLE_RX * 0.15 || vH < -HOLE_RY * 0.15) && rNorm > 0.65;
        let col = (inLipShadow || !isOver) ? warpColShadow : warpCol;
        let w = isOver ? 0.74 : 0.52;
        addStitchSegment("thread", col, w, p1[0], p1[1], p2[0], p2[1]);
      } else {
        // Outside the hole (1.02 < rNorm <= reachNorm): running-stitch anchor tails in the intact cloth!
        if ((i + j + 100) % 2 === 0) {
          let p1 = holeToCanvas(u1 + 0.3, vH);
          let p2 = holeToCanvas(u2 - 0.3, vH);
          addStitchSegment("needle", warpCol, 0.58, p1[0], p1[1], p2[0], p2[1]);
        }
      }
    }
  }

  // Second: draw Weft darning threads (perpendicular, along vH) weaving over-and-under the Warp!
  for (let i = -Math.floor(iCount / 2); i <= Math.floor(iCount / 2); i++) {
    let uH = i * spacing + random(-0.22, 0.22);
    if (Math.abs(uH) > HOLE_RX * 1.22) continue;

    let reachNorm = 1.22 + 0.28 * ((Math.abs(i * 11) % 5) / 4.0);

    // Weft threads: rich Faded Mustard & warm Golden Ochre, with Madder Red & Indigo accents
    let weftCol = (Math.abs(i) % 5 === 0) ? PALETTE.madderVivid
                : (Math.abs(i) % 7 === 0) ? PALETTE.indigoVivid
                : (Math.abs(i) % 2 === 0) ? PALETTE.mustardVivid
                : PALETTE.mustardWarm;
    let weftColShadow = (Math.abs(i) % 5 === 0) ? PALETTE.madderDeep
                      : (Math.abs(i) % 7 === 0) ? PALETTE.indigoDark
                      : PALETTE.mustardDeep;

    for (let j = -Math.floor(jCount / 2); j < Math.floor(jCount / 2); j++) {
      let v1 = j * spacing;
      let v2 = (j + 1) * spacing;
      let vMid = 0.5 * (v1 + v2);
      let rNorm = getNormHoleDist(uH, vMid);
      if (rNorm > reachNorm) continue;

      if (rNorm <= 1.02) {
        // Complementary over-under parity: Weft is ON TOP when (i + j) % 2 !== 0
        let isOver = ((i + j + 100) % 2 !== 0);
        let trim = isOver ? 0.15 : 0.78;
        let p1 = holeToCanvas(uH, v1 + trim);
        let p2 = holeToCanvas(uH, v2 - trim);

        let inLipShadow = (uH < -HOLE_RX * 0.15 || vMid < -HOLE_RY * 0.15) && rNorm > 0.65;
        let col = (inLipShadow || !isOver) ? weftColShadow : weftCol;
        let w = isOver ? 0.74 : 0.50;
        addStitchSegment("thread", col, w, p1[0], p1[1], p2[0], p2[1]);
      } else {
        // Anchor stitches into intact cloth
        if ((i + j + 100) % 2 !== 0) {
          let p1 = holeToCanvas(uH, v1 + 0.3);
          let p2 = holeToCanvas(uH, v2 - 0.3);
          addStitchSegment("needle", weftCol, 0.56, p1[0], p1[1], p2[0], p2[1]);
        }
      }
    }
  }

  // 8c. Torn Cotton Rim Collar: Radial buttonhole / whip stitches & tiny frayed cotton stubs
  const nRimStitches = 78;
  for (let k = 0; k < nRimStitches; k++) {
    let ang = (k / nRimStitches) * Math.PI * 2 + random(-0.02, 0.02);
    let wobble = 1.0 + 0.07 * Math.sin(ang * 3 + 0.7) + 0.04 * Math.cos(ang * 5 - 1.2);

    let rIn  = wobble * random(0.88, 0.96);
    let rOut = wobble * random(1.06, 1.18);

    let u1 = Math.cos(ang) * HOLE_RX * rIn;
    let v1 = Math.sin(ang) * HOLE_RY * rIn;
    let u2 = Math.cos(ang) * HOLE_RX * rOut;
    let v2 = Math.sin(ang) * HOLE_RY * rOut;

    let p1 = holeToCanvas(u1, v1);
    let p2 = holeToCanvas(u2, v2);

    let isShadowSide = (Math.cos(ang) < 0.2 && Math.sin(ang) < 0.2);
    let col = (k % 3 === 0)
      ? (isShadowSide ? PALETTE.indigoDeep : PALETTE.indigoDark)
      : (k % 3 === 1)
        ? (isShadowSide ? PALETTE.madderDeep : PALETTE.madderVivid)
        : PALETTE.mustardDeep;

    addStitchSegment("thread", col, 0.64, p1[0], p1[1], p2[0], p2[1]);

    // Tangential locking running stitch around the collar rim
    let angNext = ang + (Math.PI * 2 / nRimStitches) * 0.72;
    let u3 = Math.cos(angNext) * HOLE_RX * wobble * 1.03;
    let v3 = Math.sin(angNext) * HOLE_RY * wobble * 1.03;
    let pRim1 = holeToCanvas(Math.cos(ang) * HOLE_RX * wobble * 1.03, Math.sin(ang) * HOLE_RY * wobble * 1.03);
    let pRim2 = holeToCanvas(u3, v3);
    addStitchSegment("needle", isShadowSide ? PALETTE.indigoDeep : PALETTE.madderDeep, 0.58,
      pRim1[0], pRim1[1], pRim2[0], pRim2[1]
    );
  }
}

// ============================================================================
// 9. BATCHING & RENDERING UTILITIES
// ============================================================================
function addStitchSegment(brushName, colorHex, weight, x1, y1, x2, y2) {
  // Quantize weight to 0.08 increments for high-speed batch rendering
  let qWeight = Math.round(weight * 12.5) / 12.5;
  qWeight = constrain(qWeight, 0.32, 0.96);
  let key = brushName + "|" + colorHex + "|" + qWeight.toFixed(2);
  let bucket = stitchBatches.get(key);
  if (!bucket) {
    bucket = [];
    stitchBatches.set(key, bucket);
  }
  bucket.push(x1, y1, x2, y2);
}

function flushAllStitchBatches() {
  // Sort batches so lighter/broader base threads render first, and crisp dark indigo/madder
  // detail stitches sit cleanly on top
  let keys = Array.from(stitchBatches.keys());
  keys.sort((a, b) => {
    let scoreA = getBatchDrawOrder(a);
    let scoreB = getBatchDrawOrder(b);
    return scoreA - scoreB;
  });

  for (let k = 0; k < keys.length; k++) {
    let key = keys[k];
    let parts = key.split("|");
    let brushName = parts[0];
    let colorHex = parts[1];
    let weight = parseFloat(parts[2]);

    let segs = stitchBatches.get(key);
    brush.set(brushName, colorHex, weight);
    for (let i = 0; i < segs.length; i += 4) {
      brush.line(segs[i], segs[i + 1], segs[i + 2], segs[i + 3]);
    }
  }
}

function getBatchDrawOrder(key) {
  // Mustard & bright midtones first, deep madder & deep indigo last for crisp contrast
  if (key.includes(PALETTE.mustardLight) || key.includes(PALETTE.mustardWarm)) return 1;
  if (key.includes(PALETTE.mustardVivid) || key.includes(PALETTE.mustardDeep)) return 2;
  if (key.includes(PALETTE.madderBright) || key.includes(PALETTE.indigoBright)) return 3;
  if (key.includes(PALETTE.madderVivid)  || key.includes(PALETTE.indigoVivid))  return 4;
  if (key.includes(PALETTE.madderDeep)   || key.includes(PALETTE.indigoDark))   return 5;
  return 6; // PALETTE.indigoDeep on top
}

// ============================================================================
// GEOMETRY & GRID HELPER FUNCTIONS
// ============================================================================
function closestPointOnQuadBezier(px, py, x0, y0, x1, y1, x2, y2) {
  let minD2 = 1e18;
  let bestT = 0;
  let bestX = x0;
  let bestY = y0;
  const steps = 14;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let mt = 1 - t;
    let bx = mt * mt * x0 + 2 * mt * t * x1 + t * t * x2;
    let by = mt * mt * y0 + 2 * mt * t * y1 + t * t * y2;
    let dx = px - bx;
    let dy = py - by;
    let d2 = dx * dx + dy * dy;
    if (d2 < minD2) {
      minD2 = d2;
      bestT = t;
      bestX = bx;
      bestY = by;
    }
  }
  // Local tangent at bestT for signed distance
  let tx = 2 * (1 - bestT) * (x1 - x0) + 2 * bestT * (x2 - x1);
  let ty = 2 * (1 - bestT) * (y1 - y0) + 2 * bestT * (y2 - y1);
  let cross = tx * (py - bestY) - ty * (px - bestX);
  let sign = (cross >= 0) ? 1.0 : -1.0;
  return {
    t: bestT,
    signedDist: Math.sqrt(minD2) * sign
  };
}

function isInsideCloth(x, y) {
  let gx = Math.floor(x / CELL);
  let gy = Math.floor(y / CELL);
  if (gx < 1 || gx >= GW - 1 || gy < 1 || gy >= GH - 1) return false;
  return maskGrid[gy * GW + gx] === 1;
}

function sampleGrid(grid, x, y) {
  let fx = x / CELL - 0.5;
  let fy = y / CELL - 0.5;
  let gx = Math.floor(fx);
  let gy = Math.floor(fy);
  if (gx < 0 || gx >= GW - 1 || gy < 0 || gy >= GH - 1) return 0;
  let tx = fx - gx;
  let ty = fy - gy;
  let idx = gy * GW + gx;
  let v00 = grid[idx];
  let v10 = grid[idx + 1];
  let v01 = grid[idx + GW];
  let v11 = grid[idx + GW + 1];
  return (v00 * (1 - tx) + v10 * tx) * (1 - ty) + (v01 * (1 - tx) + v11 * tx) * ty;
}

function pointAtArcLength(poly, arc, targetS) {
  let lo = 0;
  let hi = arc.length - 1;
  while (lo < hi - 1) {
    let mid = (lo + hi) >> 1;
    if (arc[mid] <= targetS) lo = mid;
    else hi = mid;
  }
  let segLen = arc[hi] - arc[lo];
  let t = (segLen > 1e-5) ? (targetS - arc[lo]) / segLen : 0;
  return [
    poly[lo][0] + (poly[hi][0] - poly[lo][0]) * t,
    poly[lo][1] + (poly[hi][1] - poly[lo][1]) * t
  ];
}

function markOccupancyDisk(occGrid, w, h, cx, cy, r, r2) {
  let ix0 = Math.max(0, Math.floor(cx - r));
  let ix1 = Math.min(w - 1, Math.ceil(cx + r));
  let iy0 = Math.max(0, Math.floor(cy - r));
  let iy1 = Math.min(h - 1, Math.ceil(cy + r));
  for (let iy = iy0; iy <= iy1; iy++) {
    let dy = iy - cy;
    let dy2 = dy * dy;
    let rowOffset = iy * w;
    for (let ix = ix0; ix <= ix1; ix++) {
      let dx = ix - cx;
      if (dx * dx + dy2 <= r2) {
        occGrid[rowOffset + ix] = 1;
      }
    }
  }
}

function gaussianBlurGrid(src, dst, w, h, passes) {
  let tmp = new Float32Array(w * h);
  dst.set(src);
  for (let p = 0; p < passes; p++) {
    // Horizontal 5-tap pass
    for (let y = 0; y < h; y++) {
      let row = y * w;
      for (let x = 2; x < w - 2; x++) {
        let i = row + x;
        tmp[i] = 0.0625 * dst[i - 2] + 0.25 * dst[i - 1] + 0.375 * dst[i] + 0.25 * dst[i + 1] + 0.0625 * dst[i + 2];
      }
    }
    // Vertical 5-tap pass
    for (let y = 2; y < h - 2; y++) {
      let row = y * w;
      for (let x = 2; x < w - 2; x++) {
        let i = row + x;
        dst[i] = 0.0625 * tmp[i - 2 * w] + 0.25 * tmp[i - w] + 0.375 * tmp[i] + 0.25 * tmp[i + w] + 0.0625 * tmp[i + 2 * w];
      }
    }
  }
}

// Hyperrealist Divisionist Study:
// Sweating Glass Carafe of Rosé on a Tilted Zinc Café Table under Plane-Tree Shade
// Built entirely from short, unblended dabs of marker and coloured pencil

const PAL = {
  // Violet shadow register (Shadows are violet, never grey)
  VIO_DEEP:   "#21113e",
  VIO_DARK:   "#371c68",
  VIO_MID:    "#53328f",
  VIO_SOFT:   "#7755b5",
  VIO_PALE:   "#a992d6",

  // Cobalt register (Zinc café table & cool sky reflections)
  COB_DEEP:   "#142f75",
  COB_PURE:   "#1f4fb3",
  COB_BRIGHT: "#3876db",
  COB_SKY:    "#6ba2f2",
  COB_ICE:    "#b5d6ff",

  // Rose Madder register (The singular warm focal accent: rosé wine & caustic)
  ROSE_DEEP:   "#780f36",
  ROSE_MADDER: "#b81b4e",
  ROSE_BRIGHT: "#e33966",
  ROSE_CORAL:  "#f5655b",
  ROSE_BLUSH:  "#fca0ab",

  // Viridian register (Optical complement, foliage shade & thick glass tint)
  VIR_DEEP:   "#0f5949",
  VIR_PURE:   "#1b876d",
  VIR_MINT:   "#57bfa2",

  // Cadmium Lemon register (Coins of dappled sunlight, caustic heart & speculars)
  LEM_GOLD:   "#eb9c18",
  LEM_CAD:    "#f7cf23",
  LEM_PALE:   "#fff17a",
  LEM_WHITE:  "#fffce8"
};

// Scene geometry constants (1200x1200 canvas, cropped off-centre)
const CARAFE = {
  cx: 735,
  baseY: 880,
  tiltDeg: 2.6,
  wineLevelV: 350,
  topLipV: 660,
  puntV: 32
};

let dappleCoins = [];
let bgBokeh = [];
let droplets = [];
let rivulets = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  randomSeed(108);
  noiseSeed(108);

  // Custom short-dab marker & coloured pencil brushes (scaled by scaleBrushes(3))
  brush.add("dab_marker", {
    type: "marker",
    weight: 2.2,
    scatter: 0.12,
    opacity: 170,
    spacing: 0.35,
    pressure: [0.88, 1.12, 0.88],
    markerTip: false,
    noise: 0.28
  });

  brush.add("dab_cpencil", {
    type: "default",
    weight: 1.35,
    scatter: 0.32,
    sharpness: 0.48,
    grain: 14,
    opacity: 205,
    spacing: 0.24,
    pressure: [0.7, 1.25, 0.7],
    noise: 0.55
  });

  brush.scaleBrushes(3);

  initSceneStructures();
}

function initSceneStructures() {
  // 1. Coins of dappled sunlight filtering through plane-tree canopy onto the tilted zinc table
  const coinSeeds = [
    // Sunlit cluster on left-mid zinc table
    { x: 185, y: 790, rx: 64, ry: 34, rot: -14, str: 1.0 },
    { x: 255, y: 775, rx: 52, ry: 28, rot: -11, str: 0.92 },
    { x: 135, y: 845, rx: 48, ry: 25, rot: -15, str: 0.85 },
    { x: 335, y: 710, rx: 58, ry: 30, rot: -13, str: 0.95 },
    { x: 405, y: 695, rx: 44, ry: 23, rot: -12, str: 0.82 },
    { x: 285, y: 645, rx: 46, ry: 24, rot: -14, str: 0.78 },
    // Coins near the table rim on the left
    { x: 445, y: 580, rx: 50, ry: 24, rot: -14, str: 0.88 },
    { x: 110, y: 690, rx: 42, ry: 22, rot: -14, str: 0.75 },
    // Coins on the lower-right & right of the carafe
    { x: 985, y: 530, rx: 68, ry: 35, rot: -11, str: 1.0 },
    { x: 1065, y: 565, rx: 56, ry: 29, rot: -12, str: 0.95 },
    { x: 940, y: 605, rx: 52, ry: 27, rot: -13, str: 0.88 },
    { x: 1120, y: 490, rx: 60, ry: 30, rot: -10, str: 0.9 },
    { x: 1030, y: 745, rx: 72, ry: 38, rot: -13, str: 0.98 },
    { x: 1125, y: 790, rx: 58, ry: 31, rot: -14, str: 0.86 },
    { x: 935, y: 825, rx: 48, ry: 26, rot: -13, str: 0.8 },
    { x: 865, y: 985, rx: 64, ry: 34, rot: -14, str: 0.92 },
    { x: 960, y: 1030, rx: 55, ry: 29, rot: -12, str: 0.88 },
    { x: 640, y: 1095, rx: 62, ry: 33, rot: -14, str: 0.9 },
    { x: 735, y: 1120, rx: 50, ry: 27, rot: -13, str: 0.82 },
    // Subtle stray coin grazing the foreground left
    { x: 90, y: 1060, rx: 54, ry: 28, rot: -15, str: 0.84 },
    // Sunlit dapple grazing the right shoulder/belly of the carafe itself
    { x: 825, y: 585, rx: 54, ry: 32, rot: -10, str: 0.95 },
    { x: 805, y: 465, rx: 42, ry: 25, rot: -12, str: 0.85 }
  ];
  dappleCoins = coinSeeds;

  // 2. Out-of-focus plane-tree canopy gaps in the background above the tilted table
  for (let i = 0; i < 28; i++) {
    let bx = random(40, 1160);
    let maxY = getTableEdgeY(bx) - 35;
    if (maxY > 40) {
      let by = random(35, maxY);
      bgBokeh.push({
        x: bx,
        y: by,
        r: random(26, 68),
        warm: random() < 0.45
      });
    }
  }

  // 3. Vertical drip rivulets through the condensation on the chilled carafe
  const rivNu = [-0.54, -0.21, 0.09, 0.38, 0.64];
  for (let i = 0; i < rivNu.length; i++) {
    let vStart = random(315, 395);
    let vEnd = random(85, 195);
    let pts = [];
    let steps = 18;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let v = lerp(vStart, vEnd, t);
      let R = getCarafeRadius(v);
      let wiggle = (noise(i * 10 + t * 3.5) - 0.5) * 0.08;
      let nu = rivNu[i] + wiggle;
      let u = nu * R * sqrt(max(0.1, 1 - 0.15 * nu * nu));
      let p = carafeToCanvas(u, v);
      pts.push({ u, v, nu, x: p.x, y: p.y });
    }
    rivulets.push({ pts, vStart, vEnd, baseNu: rivNu[i] });

    // Heavy tear-drop bead hanging at the bottom of each rivulet
    let last = pts[pts.length - 1];
    droplets.push({
      u: last.u,
      v: last.v,
      nu: last.nu,
      x: last.x,
      y: last.y,
      r: random(9.5, 12.5),
      inWine: last.v < CARAFE.wineLevelV,
      isTear: true
    });
  }

  // 4. 95 beads of condensation across the sweating glass belly and chilled lower neck
  let attempts = 0;
  while (droplets.length < 100 && attempts < 1800) {
    attempts++;
    let v = random(42, 425);
    // Higher density on the chilled wine belly
    if (v > 365 && random() < 0.45) continue;
    let nu = random(-0.88, 0.88);
    let R = getCarafeRadius(v);
    let u = nu * R;

    // Avoid rivulet tracks
    let onRivulet = false;
    for (let riv of rivulets) {
      if (v <= riv.vStart + 8 && v >= riv.vEnd - 8 && abs(nu - riv.baseNu) < 0.085) {
        onRivulet = true;
        break;
      }
    }
    if (onRivulet) continue;

    let p = carafeToCanvas(u, v);
    let r = map(v, 40, 425, random(6.5, 10.5), random(3.8, 6.8));
    if (abs(nu) > 0.72) r *= 0.78; // foreshortened near glass cylinder edge

    let overlap = false;
    for (let d of droplets) {
      let distSq = (p.x - d.x) * (p.x - d.x) + (p.y - d.y) * (p.y - d.y);
      let minD = r + d.r + 5.5;
      if (distSq < minD * minD) {
        overlap = true;
        break;
      }
    }
    if (!overlap) {
      droplets.push({
        u,
        v,
        nu,
        x: p.x,
        y: p.y,
        r,
        inWine: v < CARAFE.wineLevelV,
        isTear: false
      });
    }
  }
}

// Tilted zinc café table upper edge curve
function getTableEdgeY(x) {
  let nx = (x - 600) / 600;
  return 522 - 162 * nx + 56 * nx * nx;
}

// Carafe horizontal radius profile R(v) for height v along axis
function getCarafeRadius(v) {
  if (v < 0) {
    let nv = constrain(v / -46, 0, 1);
    return 134 * sqrt(max(0, 1 - nv * nv * 0.35));
  }
  if (v <= 175) {
    // Swells from base (134) to bulbous belly (198)
    let t = v / 175;
    return 134 + 64 * sin(t * 90);
  }
  if (v <= 445) {
    // Tapers from belly (198) to pinched neck waist (70)
    let t = (v - 175) / 270;
    let s = t * t * (3 - 2 * t);
    return lerp(198, 70, s);
  }
  if (v <= 650) {
    // Flares from waist (70) to upper pouring rim (108)
    let t = (v - 445) / 205;
    let s = t * t * (3 - 2 * t);
    return lerp(70, 108, s);
  }
  // Rolled lip at top
  let t = constrain((v - 650) / 20, 0, 1);
  return 108 + 5 * sin(t * 180);
}

function canvasToCarafe(x, y) {
  let dx = x - CARAFE.cx;
  let dy = CARAFE.baseY - y;
  let c = cos(CARAFE.tiltDeg);
  let s = sin(CARAFE.tiltDeg);
  let u = dx * c - dy * s;
  let v = dx * s + dy * c;
  return { u, v };
}

function carafeToCanvas(u, v) {
  let c = cos(CARAFE.tiltDeg);
  let s = sin(CARAFE.tiltDeg);
  let x = CARAFE.cx + u * c + v * s;
  let y = CARAFE.baseY - (-u * s + v * c);
  return { x, y };
}

// Evaluate coins of dappled sunlight at (x, y)
function getDappleStrength(x, y) {
  let total = 0;
  for (let i = 0; i < dappleCoins.length; i++) {
    let c = dappleCoins[i];
    let dx = x - c.x;
    let dy = y - c.y;
    if (abs(dx) > c.rx * 1.6 || abs(dy) > c.ry * 1.6) continue;
    let ca = cos(c.rot);
    let sa = sin(c.rot);
    let lx = dx * ca + dy * sa;
    let ly = -dx * sa + dy * ca;
    let d2 = (lx * lx) / (c.rx * c.rx) + (ly * ly) / (c.ry * c.ry);
    if (d2 < 1.35) {
      let falloff = pow(max(0, 1 - d2 / 1.35), 1.6);
      total = max(total, falloff * c.str);
    }
  }
  return total;
}

// Choose a color from weighted candidate pairs [[color, weight], ...]
function pickWeighted(pairs) {
  let sum = 0;
  for (let i = 0; i < pairs.length; i++) sum += pairs[i][1];
  let r = random(sum);
  let acc = 0;
  for (let i = 0; i < pairs.length; i++) {
    acc += pairs[i][1];
    if (r <= acc) return pairs[i][0];
  }
  return pairs[pairs.length - 1][0];
}

// Hyperrealist optical evaluator returning { color, angle, lenScale, zone }
function evaluateOptics(x, y) {
  // Transform to carafe coordinates
  let cv = canvasToCarafe(x, y);
  let u = cv.u;
  let v = cv.v;

  // Check if inside or on the soft vibrating edge of the carafe
  let inCarafe = false;
  let R = 100;
  let nu = 0;

  if (v >= -46 && v <= 696) {
    R = getCarafeRadius(max(0, min(665, v)));
    // Bottom base ellipse cutoff
    let vMin = -44 * sqrt(max(0, 1 - (u * u) / (136 * 136)));
    // Top mouth ellipse cutoff (with pouring spout dip on left)
    let spoutDip = u < -35 ? 7 * pow((-u - 35) / 75, 1.4) : 0;
    let vMax = CARAFE.topLipV - spoutDip + 34 * sqrt(max(0, 1 - (u * u) / (112 * 112)));

    if (v >= vMin - 6 && v <= vMax + 6 && abs(u) <= R + 7) {
      inCarafe = true;
      nu = u / max(1, R);
    }
  }

  if (inCarafe) {
    return evaluateCarafeOptics(x, y, u, v, R, nu);
  }

  // Outside the carafe: check table edge vs background plane-tree shade
  let edgeY = getTableEdgeY(x);
  // Soft vibrating transition at the table rim
  let rimJitter = random(-4.5, 4.5);

  if (y < edgeY + rimJitter) {
    return evaluateBackgroundShade(x, y, edgeY);
  }

  // Zinc table rim & bevel band
  if (y < edgeY + 28 + rimJitter) {
    return evaluateTableRim(x, y, edgeY);
  }

  // Main zinc café tabletop surface (including violet cast shadow & rosé caustic)
  return evaluateZincTable(x, y, edgeY);
}

function evaluateBackgroundShade(x, y, edgeY) {
  // Deep plane-tree shade in violet, cobalt, viridian, with out-of-focus sunlit bokeh coins
  let bokehHit = 0;
  let bokehWarm = false;
  for (let i = 0; i < bgBokeh.length; i++) {
    let b = bgBokeh[i];
    let d = dist(x, y, b.x, b.y);
    if (d < b.r) {
      let f = pow(1 - d / b.r, 1.4);
      if (f > bokehHit) {
        bokehHit = f;
        bokehWarm = b.warm;
      }
    }
  }

  let n = noise(x * 0.008, y * 0.008);
  let ang = -52 + (n - 0.5) * 45 + random(-16, 16);

  if (bokehHit > 0.35) {
    let col = bokehWarm
      ? pickWeighted([
          [PAL.LEM_CAD, 3.2],
          [PAL.LEM_PALE, 2.0],
          [PAL.VIR_MINT, 2.2],
          [PAL.ROSE_BLUSH, 1.4],
          [PAL.COB_SKY, 1.5]
        ])
      : pickWeighted([
          [PAL.VIR_MINT, 2.8],
          [PAL.COB_SKY, 2.6],
          [PAL.VIR_PURE, 2.2],
          [PAL.VIO_SOFT, 1.8],
          [PAL.LEM_CAD, 1.2]
        ]);
    return { color: col, angle: ang, lenScale: 1.15, zone: "bg" };
  }

  // Rich dappled shade weave
  let col = pickWeighted([
    [PAL.VIO_DEEP, 3.6],
    [PAL.VIO_DARK, 3.8],
    [PAL.COB_DEEP, 3.0],
    [PAL.VIR_DEEP, 2.4],
    [PAL.VIO_MID, 1.8],
    [PAL.VIR_PURE, 1.1],
    [PAL.ROSE_DEEP, 0.6]
  ]);
  return { color: col, angle: ang, lenScale: 1.2, zone: "bg" };
}

function evaluateTableRim(x, y, edgeY) {
  let dy = y - edgeY;
  let dapple = getDappleStrength(x, y + 25);
  let rimSlopeAngle = -14 + ((x - 600) / 600) * 11;

  if (dy < 11) {
    // Upper bevel of the zinc rim catching sky & sunlit shimmer
    let col = dapple > 0.35
      ? pickWeighted([
          [PAL.LEM_PALE, 3.2],
          [PAL.LEM_CAD, 2.8],
          [PAL.COB_ICE, 2.5],
          [PAL.ROSE_BLUSH, 1.4],
          [PAL.VIR_MINT, 1.2]
        ])
      : pickWeighted([
          [PAL.COB_ICE, 3.4],
          [PAL.COB_SKY, 3.0],
          [PAL.VIO_PALE, 2.2],
          [PAL.VIR_MINT, 1.2],
          [PAL.LEM_PALE, 0.8]
        ]);
    return {
      color: col,
      angle: rimSlopeAngle + random(-18, 18),
      lenScale: 0.85,
      zone: "rim"
    };
  } else {
    // Rolled metallic lip underside with violet-cobalt groove and vertical glints
    let col = pickWeighted([
      [PAL.VIO_DARK, 3.2],
      [PAL.COB_DEEP, 3.0],
      [PAL.VIO_MID, 2.4],
      [PAL.COB_PURE, 2.0],
      [PAL.VIR_DEEP, 1.0],
      [PAL.ROSE_MADDER, 0.6]
    ]);
    return {
      color: col,
      angle: rimSlopeAngle + 65 + random(-20, 20),
      lenScale: 0.8,
      zone: "rim"
    };
  }
}

function evaluateZincTable(x, y, edgeY) {
  // Check carafe cast shadow and internal rosé caustic stretching toward bottom-left
  // Shadow axis: from carafe base (735, 880) along angle 156 deg (down-left)
  let dx = x - (CARAFE.cx - 10);
  let dy = y - (CARAFE.baseY + 4);
  let shAng = 157;
  let ca = cos(shAng);
  let sa = sin(shAng);
  let su = dx * ca + dy * sa; // distance along shadow axis (0 to ~680)
  let sv = -dx * sa + dy * ca; // perpendicular offset

  // Shadow width expands slightly then tapers
  let shHalfW = map(constrain(su, -40, 660), -40, 660, 128, 175);
  let normShDist = sqrt(pow((su - 275) / 345, 2) + pow(sv / shHalfW, 2));

  // Contact shadow directly under the thick glass base
  let baseDist = sqrt(pow((x - CARAFE.cx) / 142, 2) + pow((y - (CARAFE.baseY + 8)) / 48, 2));

  if (baseDist < 1.08) {
    let col = pickWeighted([
      [PAL.VIO_DEEP, 4.5],
      [PAL.VIO_DARK, 3.0],
      [PAL.COB_DEEP, 2.2],
      [PAL.ROSE_DEEP, 1.5]
    ]);
    return {
      color: col,
      angle: -14 + random(-14, 14),
      lenScale: 0.82,
      zone: "shadow"
    };
  }

  // Inside the carafe's violet cast shadow
  if (su > -30 && normShDist < 1.04 + random(-0.06, 0.06)) {
    // Evaluate the focused Rosé Caustic inside the shadow!
    // Caustic forms a glowing double-arc / heart focus from su = 75 to su = 420
    let cu = (su - 225) / 155;
    // Slight parabolic curve to the caustic ribs
    let cv = (sv - 14 * cu * cu) / 72;
    let causticR = sqrt(cu * cu + cv * cv);
    // Bright caustic ring + warm interior
    let causticRing = exp(-pow((causticR - 0.52) / 0.28, 2));
    let causticCore = max(0, 1 - causticR * 1.15);
    let causticIntensity = max(causticRing * 0.95, causticCore * 0.85);

    // Secondary inner caustic filament
    let fil = exp(-pow(cu - 0.15, 2) * 5 - pow(cv + 0.12, 2) * 8);
    causticIntensity = max(causticIntensity, fil * 1.05);

    if (causticIntensity > 0.22 + random(-0.08, 0.08)) {
      let col;
      if (causticIntensity > 0.72) {
        // Hot incandescent caustic heart: cadmium lemon + coral + rose madder
        col = pickWeighted([
          [PAL.LEM_PALE, 2.4],
          [PAL.LEM_CAD, 3.2],
          [PAL.ROSE_CORAL, 3.6],
          [PAL.ROSE_BRIGHT, 2.8],
          [PAL.ROSE_BLUSH, 1.8],
          [PAL.LEM_GOLD, 1.6]
        ]);
      } else if (causticIntensity > 0.42) {
        // Vibrant rose-madder caustic body
        col = pickWeighted([
          [PAL.ROSE_MADDER, 3.8],
          [PAL.ROSE_BRIGHT, 3.4],
          [PAL.ROSE_CORAL, 2.6],
          [PAL.LEM_GOLD, 1.5],
          [PAL.VIO_MID, 1.2]
        ]);
      } else {
        // Warm claret-violet transition at caustic edge
        col = pickWeighted([
          [PAL.ROSE_DEEP, 3.5],
          [PAL.ROSE_MADDER, 2.8],
          [PAL.VIO_DARK, 3.0],
          [PAL.VIO_MID, 2.2],
          [PAL.COB_DEEP, 1.2]
        ]);
      }
      // Caustic dabs follow the curved refraction arcs
      let cAng = shAng + atan2(cv, cu) * 0.35 + random(-15, 15);
      return { color: col, angle: cAng, lenScale: 0.88, zone: "caustic" };
    }

    // Pure Violet Cast Shadow (Shadows are violet, never grey!)
    let edgeSoft = normShDist > 0.82;
    let col = edgeSoft
      ? pickWeighted([
          [PAL.VIO_MID, 3.6],
          [PAL.VIO_SOFT, 2.8],
          [PAL.COB_PURE, 2.5],
          [PAL.VIO_DARK, 2.0],
          [PAL.VIR_DEEP, 1.0],
          [PAL.ROSE_DEEP, 0.7]
        ])
      : pickWeighted([
          [PAL.VIO_DARK, 4.2],
          [PAL.VIO_DEEP, 2.8],
          [PAL.VIO_MID, 3.0],
          [PAL.COB_DEEP, 2.4],
          [PAL.VIR_DEEP, 1.1],
          [PAL.ROSE_DEEP, 0.9]
        ]);
    return {
      color: col,
      angle: -14 + random(-16, 16),
      lenScale: 0.95,
      zone: "shadow"
    };
  }

  // Outside the cast shadow: check for Coins of Dappled Sunlight on the zinc table
  let dapple = getDappleStrength(x, y);
  let patNoise = noise(x * 0.006, y * 0.006);
  let tableAng = -13.5 + (patNoise - 0.5) * 18 + random(-14, 14);

  if (dapple > 0.25 + random(-0.1, 0.1)) {
    let col;
    if (dapple > 0.68) {
      // Bright coin center: cadmium lemon, icy sky cobalt, viridian mint & blush
      col = pickWeighted([
        [PAL.LEM_CAD, 3.8],
        [PAL.LEM_PALE, 3.2],
        [PAL.COB_ICE, 2.4],
        [PAL.COB_SKY, 2.0],
        [PAL.VIR_MINT, 1.6],
        [PAL.ROSE_BLUSH, 1.1],
        [PAL.LEM_GOLD, 1.0]
      ]);
    } else {
      // Shimmering half-light border of the sunlight coin
      col = pickWeighted([
        [PAL.COB_SKY, 3.4],
        [PAL.LEM_CAD, 2.8],
        [PAL.VIR_MINT, 2.4],
        [PAL.VIO_PALE, 2.0],
        [PAL.COB_BRIGHT, 2.2],
        [PAL.ROSE_BLUSH, 1.2],
        [PAL.VIR_PURE, 1.0]
      ]);
    }
    return { color: col, angle: tableAng, lenScale: 0.95, zone: "dapple" };
  }

  // Shaded Zinc Café Table: optical tumult of cobalt, violet, viridian, and subtle rose/lemon sparks
  // Gradation: slightly lighter toward the upper right and table rim, deeper toward lower left
  let lightGrad = map(x - y * 0.5, -500, 900, 0, 1) + (patNoise - 0.5) * 0.25;
  let col;
  if (lightGrad > 0.55) {
    col = pickWeighted([
      [PAL.COB_BRIGHT, 3.6],
      [PAL.COB_SKY, 3.0],
      [PAL.VIO_SOFT, 2.8],
      [PAL.VIO_PALE, 2.0],
      [PAL.COB_PURE, 2.2],
      [PAL.VIR_PURE, 1.3],
      [PAL.VIR_MINT, 1.0],
      [PAL.ROSE_BLUSH, 0.65],
      [PAL.LEM_CAD, 0.45]
    ]);
  } else {
    col = pickWeighted([
      [PAL.COB_PURE, 3.8],
      [PAL.VIO_MID, 3.4],
      [PAL.COB_BRIGHT, 2.8],
      [PAL.VIO_SOFT, 2.4],
      [PAL.COB_DEEP, 1.6],
      [PAL.VIR_PURE, 1.4],
      [PAL.VIR_DEEP, 0.9],
      [PAL.ROSE_MADDER, 0.5],
      [PAL.LEM_GOLD, 0.35]
    ]);
  }
  return { color: col, angle: tableAng, lenScale: 1.05, zone: "table" };
}

function evaluateCarafeOptics(x, y, u, v, R, nu) {
  // Check if point lies on a clean vertical drip rivulet track
  let onRivulet = false;
  for (let i = 0; i < rivulets.length; i++) {
    let riv = rivulets[i];
    if (v <= riv.vStart && v >= riv.vEnd && abs(nu - riv.baseNu) < 0.045) {
      onRivulet = true;
      break;
    }
  }

  // Contour-following angle for carafe strokes (vertical glass contour + elliptical cross-arc)
  let contourAng = 90 - CARAFE.tiltDeg + nu * 18 + random(-14, 14);
  let ellipseAng = -CARAFE.tiltDeg + nu * 28 + random(-12, 12);

  // 1. TOP POURING LIP & MOUTH ELLIPSE (v around 660, rx = 108, ry = 34)
  let spoutDip = u < -35 ? 7 * pow((-u - 35) / 75, 1.4) : 0;
  let mouthCenterV = CARAFE.topLipV - spoutDip;
  let mouthDy = (v - mouthCenterV) / 34;
  let mouthDx = u / 108;
  let mouthR = sqrt(mouthDx * mouthDx + mouthDy * mouthDy);

  if (v > 615 && mouthR <= 1.12) {
    // Rolled glass rim ring
    if (mouthR > 0.82) {
      let isLitRim = (u > 15 && mouthDy < 0.2) || (u < -10 && mouthDy > 0.3);
      let col = isLitRim
        ? pickWeighted([
            [PAL.LEM_WHITE, 3.5],
            [PAL.LEM_PALE, 3.0],
            [PAL.COB_ICE, 2.8],
            [PAL.VIR_MINT, 1.5],
            [PAL.ROSE_BLUSH, 1.0]
          ])
        : pickWeighted([
            [PAL.COB_PURE, 3.0],
            [PAL.VIO_DARK, 2.8],
            [PAL.VIR_PURE, 2.2],
            [PAL.COB_SKY, 2.4],
            [PAL.VIO_PALE, 1.6]
          ]);
      return { color: col, angle: ellipseAng, lenScale: 0.72, zone: "carafe_rim" };
    } else {
      // Inside the open glass mouth looking through back glass wall into shade
      let col = pickWeighted([
        [PAL.VIO_MID, 3.0],
        [PAL.COB_PURE, 3.2],
        [PAL.COB_SKY, 2.4],
        [PAL.VIR_PURE, 1.8],
        [PAL.VIO_PALE, 1.8],
        [PAL.LEM_PALE, 0.9]
      ]);
      return { color: col, angle: ellipseAng, lenScale: 0.8, zone: "carafe_neck" };
    }
  }

  // 2. CLEAR GLASS NECK ABOVE THE WINE (v from wine meniscus ~350 up to 625)
  let menRx = 110;
  let menRy = 36;
  let menDx = u / menRx;
  let menDy = (v - CARAFE.wineLevelV) / menRy;
  let menR = sqrt(menDx * menDx + menDy * menDy);

  // Check if above the wine meniscus
  if (v > CARAFE.wineLevelV && menR > 1.03) {
    // Refracted table edge passing behind the lower glass neck (around v = 400..445)
    let neckRefractV = 420 - 18 * nu + 14 * nu * nu;
    let onNeckRefract = abs(v - neckRefractV) < 15;

    // Right sunlit vertical specular window on the neck
    if (nu > 0.52 && nu < 0.88) {
      let col = pickWeighted([
        [PAL.LEM_WHITE, 3.2],
        [PAL.LEM_PALE, 2.8],
        [PAL.COB_ICE, 3.0],
        [PAL.VIR_MINT, 1.6],
        [PAL.ROSE_BLUSH, 1.0]
      ]);
      return { color: col, angle: contourAng, lenScale: 0.8, zone: "carafe_spec" };
    }

    // Left or right outer glass wall thickness refraction
    if (abs(nu) > 0.84) {
      let col = pickWeighted([
        [PAL.VIO_DARK, 3.0],
        [PAL.COB_DEEP, 3.2],
        [PAL.VIR_PURE, 2.4],
        [PAL.COB_SKY, 2.0],
        [PAL.ROSE_BLUSH, 1.2]
      ]);
      return { color: col, angle: contourAng, lenScale: 0.78, zone: "carafe_edge" };
    }

    if (onNeckRefract) {
      let col = pickWeighted([
        [PAL.COB_ICE, 3.0],
        [PAL.LEM_CAD, 2.4],
        [PAL.VIO_DARK, 2.6],
        [PAL.COB_PURE, 2.5],
        [PAL.VIR_MINT, 1.5]
      ]);
      return { color: col, angle: ellipseAng, lenScale: 0.78, zone: "carafe_refract" };
    }

    // Clear glass neck: below v = 425 it has a chilled condensation veil
    let chilledNeck = v < 425 && !onRivulet;
    let col = chilledNeck
      ? pickWeighted([
          [PAL.COB_ICE, 3.2],
          [PAL.VIO_PALE, 2.8],
          [PAL.COB_SKY, 2.8],
          [PAL.VIR_MINT, 1.8],
          [PAL.ROSE_BLUSH, 1.5],
          [PAL.VIO_MID, 1.4]
        ])
      : pickWeighted([
          [PAL.VIO_MID, 3.0],
          [PAL.COB_PURE, 3.2],
          [PAL.COB_SKY, 2.4],
          [PAL.VIO_SOFT, 2.4],
          [PAL.VIR_PURE, 1.6],
          [PAL.COB_ICE, 1.4]
        ]);
    return { color: col, angle: contourAng, lenScale: 0.85, zone: "carafe_neck" };
  }

  // 3. THE ROSÉ WINE MENISCUS ELLIPSE (centered at v = 350, rx = 110, ry = 36)
  if (menR <= 1.05) {
    if (menR > 0.82) {
      // Clinging liquid meniscus rim: bright lemon/pink/ice highlight + dark ruby underside on front arc
      let isFrontDark = menDy < -0.25 && menR > 0.92;
      let col = isFrontDark
        ? pickWeighted([
            [PAL.ROSE_DEEP, 3.8],
            [PAL.VIO_DARK, 3.2],
            [PAL.ROSE_MADDER, 2.5],
            [PAL.COB_DEEP, 1.5]
          ])
        : pickWeighted([
            [PAL.LEM_WHITE, 3.4],
            [PAL.ROSE_BLUSH, 3.6],
            [PAL.LEM_PALE, 2.8],
            [PAL.COB_ICE, 2.4],
            [PAL.ROSE_CORAL, 2.0]
          ]);
      return { color: col, angle: ellipseAng, lenScale: 0.72, zone: "meniscus" };
    } else {
      // Elliptical top surface of the rosé reflecting dappled canopy & sky
      let col = pickWeighted([
        [PAL.ROSE_BLUSH, 3.8],
        [PAL.ROSE_CORAL, 3.2],
        [PAL.COB_ICE, 2.4],
        [PAL.LEM_PALE, 2.0],
        [PAL.ROSE_BRIGHT, 2.4],
        [PAL.VIO_PALE, 1.5]
      ]);
      return { color: col, angle: ellipseAng, lenScale: 0.82, zone: "meniscus" };
    }
  }

  // 4. THICK SOLID GLASS BASE / PUNT (v <= 38)
  let puntTopV = 30 - 16 * (1 - nu * nu);
  if (v <= puntTopV) {
    // Complex refraction of viridian glass tint, ruby wine above, cobalt table & lemon caustics
    let isBaseHighlight = abs(v - 10) < 9 && abs(nu) < 0.68;
    let col = isBaseHighlight
      ? pickWeighted([
          [PAL.LEM_WHITE, 2.8],
          [PAL.LEM_CAD, 3.2],
          [PAL.VIR_MINT, 3.0],
          [PAL.ROSE_CORAL, 2.4],
          [PAL.COB_ICE, 2.2]
        ])
      : pickWeighted([
          [PAL.VIR_DEEP, 3.2],
          [PAL.VIR_PURE, 3.0],
          [PAL.ROSE_DEEP, 3.0],
          [PAL.VIO_DARK, 2.8],
          [PAL.COB_DEEP, 2.4],
          [PAL.ROSE_MADDER, 2.0],
          [PAL.LEM_GOLD, 1.2]
        ]);
    return { color: col, angle: ellipseAng, lenScale: 0.76, zone: "punt" };
  }

  // 5. MAIN BODY OF THE SWEATING ROSÉ WINE (v from ~30 to ~350)
  // A. Refracted Table Edge Bent Through the Wine!
  // Because the cylindrical wine belly acts as a strong converging lens, the tilted table edge
  // bends dramatically into an S-arc across the middle of the wine (v ~ 225 to 335).
  let bentTableV = 262 - 38 * nu - 56 * nu * nu * nu + 30 * nu * nu;
  let distToBentRim = v - bentTableV;

  if (abs(distToBentRim) < 19 && abs(nu) < 0.88) {
    // Chromatic dispersion fringe on lower side, deep claret-violet core on upper side
    let col = distToBentRim < -3
      ? pickWeighted([
          [PAL.LEM_CAD, 3.4],
          [PAL.LEM_GOLD, 3.2],
          [PAL.ROSE_CORAL, 3.5],
          [PAL.ROSE_BRIGHT, 2.4],
          [PAL.COB_ICE, 1.2]
        ])
      : pickWeighted([
          [PAL.VIO_DEEP, 3.5],
          [PAL.ROSE_DEEP, 4.2],
          [PAL.VIO_DARK, 3.0],
          [PAL.COB_DEEP, 2.0],
          [PAL.ROSE_MADDER, 2.2]
        ]);
    let bAng = ellipseAng - 18 * (1 - nu * nu) + random(-10, 10);
    return { color: col, angle: bAng, lenScale: 0.78, zone: "bent_rim" };
  }

  // B. Outer Glass Wall & Vibrating Silhouette Edge (|nu| > 0.86)
  if (abs(nu) > 0.86) {
    let col = nu > 0
      ? pickWeighted([
          [PAL.ROSE_CORAL, 3.0],
          [PAL.LEM_CAD, 2.6],
          [PAL.ROSE_MADDER, 2.8],
          [PAL.VIO_DARK, 2.0],
          [PAL.COB_ICE, 1.8]
        ])
      : pickWeighted([
          [PAL.VIO_DARK, 3.4],
          [PAL.ROSE_DEEP, 3.6],
          [PAL.COB_DEEP, 2.4],
          [PAL.ROSE_BLUSH, 1.8],
          [PAL.COB_ICE, 1.5]
        ]);
    // Slight feathering angle at edge so silhouette vibrates softly
    return { color: col, angle: contourAng + random(-22, 22), lenScale: 0.76, zone: "carafe_edge" };
  }

  // C. Primary Sunlit Window Reflection on Right Shoulder/Belly (nu in [0.50, 0.83], v in [140, 330])
  if (nu > 0.50 && nu < 0.83 && v > 135 && v < 330) {
    let specCore = nu > 0.60 && nu < 0.76 && v > 175 && v < 305;
    let col = specCore
      ? pickWeighted([
          [PAL.LEM_WHITE, 3.6],
          [PAL.LEM_PALE, 3.4],
          [PAL.ROSE_BLUSH, 3.0],
          [PAL.COB_ICE, 2.6],
          [PAL.LEM_CAD, 2.0]
        ])
      : pickWeighted([
          [PAL.ROSE_BLUSH, 3.6],
          [PAL.ROSE_CORAL, 3.4],
          [PAL.LEM_CAD, 2.8],
          [PAL.COB_ICE, 2.2],
          [PAL.ROSE_BRIGHT, 2.2]
        ]);
    return { color: col, angle: contourAng, lenScale: 0.82, zone: "carafe_spec" };
  }

  // D. Secondary Internal Caustic Crescent on Lower-Left Belly (light focused through wine)
  let leftCrescent = nu > -0.82 && nu < -0.45 && v > 55 && v < 215;
  if (leftCrescent) {
    let col = pickWeighted([
      [PAL.ROSE_CORAL, 3.8],
      [PAL.ROSE_BRIGHT, 3.6],
      [PAL.LEM_GOLD, 2.8],
      [PAL.LEM_CAD, 2.2],
      [PAL.ROSE_MADDER, 2.4],
      [PAL.ROSE_BLUSH, 1.5]
    ]);
    return { color: col, angle: contourAng, lenScale: 0.85, zone: "wine_glow" };
  }

  // E. Core Rosé Wine Volume (modulated by whether above or below the refracted table edge, and condensation frost)
  let aboveRefractedEdge = distToBentRim > 0;
  // Chilled condensation frost adds icy cobalt / blush / pale violet dabs unless wiped by a rivulet
  let frostFactor = onRivulet ? 0.0 : 0.26;

  if (random() < frostFactor) {
    let frostCol = pickWeighted([
      [PAL.ROSE_BLUSH, 3.6],
      [PAL.COB_ICE, 2.8],
      [PAL.VIO_PALE, 2.2],
      [PAL.LEM_PALE, 1.4],
      [PAL.COB_SKY, 1.4]
    ]);
    return { color: frostCol, angle: contourAng + random(-25, 25), lenScale: 0.72, zone: "wine_frost" };
  }

  if (aboveRefractedEdge) {
    // Upper wine backed by dark plane-tree shade: deeper rose madder, claret, and violet-cobalt
    let col = nu > 0.15
      ? pickWeighted([
          [PAL.ROSE_MADDER, 4.2],
          [PAL.ROSE_BRIGHT, 3.4],
          [PAL.ROSE_DEEP, 2.8],
          [PAL.ROSE_CORAL, 2.2],
          [PAL.VIO_MID, 1.5],
          [PAL.LEM_GOLD, 1.0]
        ])
      : pickWeighted([
          [PAL.ROSE_DEEP, 4.4],
          [PAL.ROSE_MADDER, 3.8],
          [PAL.VIO_DARK, 2.8],
          [PAL.VIO_MID, 1.8],
          [PAL.ROSE_BRIGHT, 1.6],
          [PAL.COB_DEEP, 1.0]
        ]);
    return { color: col, angle: contourAng, lenScale: 0.88, zone: "wine_upper" };
  } else {
    // Lower wine backed by sunlit zinc table: incandescent coral, rose madder, and cadmium lemon/gold
    let col = nu > -0.15
      ? pickWeighted([
          [PAL.ROSE_BRIGHT, 4.0],
          [PAL.ROSE_CORAL, 4.2],
          [PAL.ROSE_MADDER, 3.2],
          [PAL.LEM_GOLD, 2.4],
          [PAL.LEM_CAD, 1.8],
          [PAL.ROSE_BLUSH, 1.6]
        ])
      : pickWeighted([
          [PAL.ROSE_MADDER, 4.2],
          [PAL.ROSE_BRIGHT, 3.5],
          [PAL.ROSE_DEEP, 2.8],
          [PAL.ROSE_CORAL, 2.4],
          [PAL.VIO_MID, 1.6],
          [PAL.LEM_GOLD, 1.2]
        ]);
    return { color: col, angle: contourAng, lenScale: 0.88, zone: "wine_lower" };
  }
}

// Helper to append a short dab segment to a batch map
function addDab(batches, brushName, colorHex, weight, x, y, len, angleDeg) {
  let wKey = nf(weight, 1, 2);
  let key = brushName + "|" + colorHex + "|" + wKey;
  let bucket = batches.get(key);
  if (!bucket) {
    bucket = { brushName, colorHex, weight, segs: [] };
    batches.set(key, bucket);
  }
  let hl = len * 0.5;
  let dx = cos(angleDeg) * hl;
  let dy = sin(angleDeg) * hl;
  bucket.segs.push(x - dx, y - dy, x + dx, y + dy);
}

// Execute all batched dabs cleanly
function flushBatches(batches) {
  for (let bucket of batches.values()) {
    brush.set(bucket.brushName, bucket.colorHex, bucket.weight);
    let s = bucket.segs;
    for (let i = 0; i < s.length; i += 4) {
      brush.line(s[i], s[i + 1], s[i + 2], s[i + 3]);
    }
  }
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm late-morning parchment ground (only tiny breathing slits between dabs show through)
  background("#f7efe0");
  brush.noField();
  brush.noFill();
  brush.noHatch();

  // =========================================================================
  // PASS 1: Broad Divisionist Marker Under-Mosaic (Establishes optical mass)
  // =========================================================================
  let pass1 = new Map();
  let step1 = 17;
  for (let gy = -10; gy <= height + 10; gy += step1) {
    for (let gx = -10; gx <= width + 10; gx += step1) {
      let x = gx + random(-7, 7);
      let y = gy + random(-7, 7);
      let opt = evaluateOptics(x, y);
      let bName = random() < 0.72 ? "dab_marker" : "marker";
      let w = bName === "marker" ? 0.85 : 1.05;
      let len = random(18, 27) * opt.lenScale;
      addDab(pass1, bName, opt.color, w, x, y, len, opt.angle);
    }
  }
  flushBatches(pass1);

  // =========================================================================
  // PASS 2: Dense Marker & Coloured Pencil Optical Weave
  // =========================================================================
  let pass2 = new Map();
  let step2 = 11.5;
  for (let gy = -6; gy <= height + 6; gy += step2) {
    for (let gx = -6; gx <= width + 6; gx += step2) {
      let x = gx + random(-5, 5);
      let y = gy + random(-5, 5);
      let opt = evaluateOptics(x, y);

      let useMarker = random() < 0.48;
      let bName = useMarker
        ? (random() < 0.8 ? "dab_marker" : "marker")
        : (random() < 0.65 ? "dab_cpencil" : "cpencil");
      let w = useMarker ? 0.68 : 0.95;
      let len = random(11, 18) * opt.lenScale;
      addDab(pass2, bName, opt.color, w, x, y, len, opt.angle);
    }
  }
  flushBatches(pass2);

  // =========================================================================
  // PASS 3: High-Resolution Optical Focus on Carafe, Caustic, Rim & Dapples
  // =========================================================================
  let pass3 = new Map();

  // 3A. Extra-dense coloured pencil & fine marker dabs over the entire carafe + soft vibrating edge halo
  for (let v = -48; v <= 695; v += 5.8) {
    let R = getCarafeRadius(max(0, min(665, v)));
    for (let u = -R - 14; u <= R + 14; u += 5.8) {
      let p = carafeToCanvas(u + random(-2.8, 2.8), v + random(-2.8, 2.8));
      if (p.x < 0 || p.x > width || p.y < 0 || p.y > height) continue;

      let opt = evaluateOptics(p.x, p.y);
      let isPencil = random() < 0.68;
      let bName = isPencil
        ? (random() < 0.7 ? "dab_cpencil" : "cpencil")
        : "dab_marker";
      let w = isPencil ? 0.78 : 0.52;
      let len = random(7.5, 13.5) * opt.lenScale;
      addDab(pass3, bName, opt.color, w, p.x, p.y, len, opt.angle);
    }
  }

  // 3B. Explicit hyperrealist reinforcement of the Refracted Table Edge Bent Through the Wine
  for (let i = 0; i < 420; i++) {
    let nu = random(-0.88, 0.88);
    let bentV = 262 - 38 * nu - 56 * nu * nu * nu + 30 * nu * nu;
    let v = bentV + random(-16, 16);
    let R = getCarafeRadius(v);
    let u = nu * R;
    let p = carafeToCanvas(u, v);
    let opt = evaluateOptics(p.x, p.y);
    let bName = random() < 0.6 ? "dab_cpencil" : "dab_marker";
    let w = bName === "dab_cpencil" ? 0.72 : 0.48;
    addDab(pass3, bName, opt.color, w, p.x, p.y, random(7, 12), opt.angle);
  }

  // 3C. Explicit reinforcement of the Rosé Caustic & Table Rim Shimmer
  for (let i = 0; i < 950; i++) {
    // Caustic region sampling
    let cx = random(180, 690);
    let cy = random(860, 1170);
    let opt = evaluateOptics(cx, cy);
    if (opt.zone === "caustic" || opt.zone === "shadow") {
      let bName = random() < 0.62 ? "dab_cpencil" : "dab_marker";
      let w = bName === "dab_cpencil" ? 0.82 : 0.55;
      addDab(pass3, bName, opt.color, w, cx, cy, random(8, 15), opt.angle);
    }
  }

  for (let rx = 0; rx <= width; rx += 4.5) {
    let edgeY = getTableEdgeY(rx);
    let ry = edgeY + random(-6, 30);
    let opt = evaluateOptics(rx, ry);
    if (opt.zone !== "carafe_edge") {
      let bName = random() < 0.6 ? "dab_cpencil" : "dab_marker";
      let w = bName === "dab_cpencil" ? 0.75 : 0.52;
      addDab(pass3, bName, opt.color, w, rx + random(-2, 2), ry, random(7, 13), opt.angle);
    }
  }

  flushBatches(pass3);

  // =========================================================================
  // PASS 4: Micro-Hyperrealist Details: Rivulets, 100 Condensation Beads & Speculars
  // =========================================================================
  let pass4 = new Map();

  // 4A. Render the 5 vertical drip rivulets (clear darker track + wet sunlit edge glints)
  for (let riv of rivulets) {
    for (let i = 0; i < riv.pts.length; i++) {
      let pt = riv.pts[i];
      // Core of the wiped track reveals deeper, un-frosted wine/glass
      let coreCol = pt.v < CARAFE.wineLevelV
        ? (pt.nu > 0.1 ? PAL.ROSE_MADDER : PAL.ROSE_DEEP)
        : PAL.COB_PURE;
      addDab(pass4, "dab_cpencil", coreCol, 0.58, pt.x, pt.y, 7.5, 90 - CARAFE.tiltDeg + random(-6, 6));

      // Tiny wet meniscus highlight along right edge of rivulet track
      let glintCol = pt.v < CARAFE.wineLevelV ? PAL.ROSE_BLUSH : PAL.COB_ICE;
      addDab(pass4, "cpencil", glintCol, 0.48, pt.x + 3.2, pt.y, 6.0, 90 - CARAFE.tiltDeg + random(-6, 6));
    }
  }

  // 4B. Render each of the 100 Beads of Condensation with micro-lens optics
  // (Water drop acts as a convex lens: dark shadow at upper-right, glowing refracted belly at lower-left, pinpoint specular at upper-right)
  for (let d of droplets) {
    let r = d.r;
    let x = d.x;
    let y = d.y;

    // 1. Tiny cast shadow immediately below-left of the bead
    let shCol = d.inWine ? PAL.ROSE_DEEP : PAL.VIO_DARK;
    addDab(pass4, "dab_cpencil", shCol, 0.62, x - r * 0.45, y + r * 0.78, r * 1.15, -28 + random(-10, 10));
    if (d.isTear) {
      addDab(pass4, "dab_cpencil", PAL.VIO_DEEP, 0.58, x - r * 0.35, y + r * 0.95, r * 0.95, -25);
    }

    // 2. Upper-right internal inverted shadow crescent inside the bead
    let topCresCol = d.inWine
      ? (random() < 0.55 ? PAL.VIO_DEEP : PAL.ROSE_DEEP)
      : (random() < 0.65 ? PAL.VIO_DARK : PAL.COB_DEEP);
    addDab(pass4, "dab_cpencil", topCresCol, 0.62, x + r * 0.22, y - r * 0.38, r * 1.1, -32 + random(-8, 8));
    addDab(pass4, "cpencil", PAL.VIO_DEEP, 0.52, x - r * 0.12, y - r * 0.48, r * 0.9, -12 + random(-8, 8));

    // 3. Lower-left glowing refracted lens belly of the bead
    if (d.inWine) {
      let bellyCol1 = d.nu > -0.2 ? PAL.LEM_CAD : PAL.ROSE_CORAL;
      let bellyCol2 = d.nu > 0.1 ? PAL.LEM_PALE : PAL.ROSE_BRIGHT;
      addDab(pass4, "dab_marker", bellyCol1, 0.45, x - r * 0.25, y + r * 0.28, r * 1.05, 38 + random(-10, 10));
      addDab(pass4, "dab_cpencil", bellyCol2, 0.65, x - r * 0.15, y + r * 0.38, r * 0.95, 25 + random(-10, 10));
      addDab(pass4, "cpencil", PAL.ROSE_BLUSH, 0.55, x + r * 0.15, y + r * 0.32, r * 0.85, -18 + random(-10, 10));
    } else {
      addDab(pass4, "dab_marker", PAL.COB_ICE, 0.45, x - r * 0.25, y + r * 0.28, r * 1.0, 38 + random(-10, 10));
      addDab(pass4, "dab_cpencil", PAL.LEM_PALE, 0.62, x - r * 0.15, y + r * 0.38, r * 0.9, 25 + random(-10, 10));
      addDab(pass4, "cpencil", PAL.VIR_MINT, 0.52, x + r * 0.15, y + r * 0.32, r * 0.8, -18 + random(-10, 10));
    }

    // 4. Crisp pinpoint specular highlight at upper-right of the bead
    addDab(pass4, "dab_cpencil", PAL.LEM_WHITE, 0.68, x + r * 0.32, y - r * 0.22, max(4.2, r * 0.65), -45 + random(-8, 8));
    if (r > 7.5) {
      addDab(pass4, "cpencil", PAL.LEM_PALE, 0.55, x + r * 0.22, y - r * 0.15, r * 0.55, 45);
    }
  }

  // 4C. Final sparkling specular accents on the pouring lip, meniscus rim, and punt caustics
  for (let i = 0; i < 65; i++) {
    // Meniscus rim sparkles
    let ang = random(0, 360);
    let u = 109 * cos(ang);
    let v = CARAFE.wineLevelV + 35 * sin(ang);
    let p = carafeToCanvas(u, v);
    let col = sin(ang) > -0.2 ? PAL.LEM_WHITE : PAL.ROSE_BLUSH;
    let tang = -CARAFE.tiltDeg + atan2(35 * cos(ang), -109 * sin(ang));
    addDab(pass4, "dab_cpencil", col, 0.62, p.x, p.y, random(5.5, 9.5), tang + random(-8, 8));
  }

  for (let i = 0; i < 55; i++) {
    // Top pouring lip sparkles
    let ang = random(-160, 160);
    let u = 108 * cos(ang);
    let spoutDip = u < -35 ? 7 * pow((-u - 35) / 75, 1.4) : 0;
    let v = CARAFE.topLipV - spoutDip + 34 * sin(ang);
    let p = carafeToCanvas(u, v);
    let col = random() < 0.65 ? PAL.LEM_WHITE : PAL.COB_ICE;
    let tang = -CARAFE.tiltDeg + atan2(34 * cos(ang), -108 * sin(ang));
    addDab(pass4, "dab_cpencil", col, 0.65, p.x, p.y, random(5.5, 9.5), tang + random(-8, 8));
  }

  flushBatches(pass4);

  noLoop();
}

// Hyperrealist Watercolor & Graphite Study:
// Tall Glass of Black Iced Tea with Plunged Lemon Wheel (Titration Palette)

const GX = 475;          // Glass center X (slightly to the left)
const RIM_Y = 220;       // Top rim Y
const RIM_RX = 154;      // Top rim X radius
const RIM_RY = 27;       // Top rim Y radius

const LIQ_Y = 286;       // Liquid meniscus Y
const LIQ_RX = 149;      // Liquid meniscus X radius
const LIQ_RY = 26;       // Liquid meniscus Y radius

const SHAM_Y = 882;      // Top of heavy glass sham (bottom of liquid)
const SHAM_RX = 123;
const SHAM_RY = 27;

const BASE_Y = 956;      // Bottom of glass base on tabletop
const BASE_RX = 119;
const BASE_RY = 28;

const WALL_Y = 872;      // Horizontal tabletop line

const PAPER = "#F8F5EC";

function glassOuterRx(y) {
  return map(y, RIM_Y, BASE_Y, RIM_RX, BASE_RX);
}

function glassInnerRx(y) {
  return glassOuterRx(y) - 7.5;
}

function clampToGlass(x, y, margin = 8) {
  let rx = glassOuterRx(y) - margin;
  return constrain(x, GX - rx, GX + rx);
}

// Helper to draw a closed organic polygon with p5.brush beginShape
function drawOrganicPoly(pts, curvature = 0.35) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(CLOSE);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4271);
  noiseSeed(8831);
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. ARCHIVAL WATERCOLOR PAPER GROUND (Reserved white paper base)
  background(PAPER);
  drawPaperGrain();

  // 2. FLAT CHALKY CYAN WALL & HORIZONTAL TABLETOP (Painted around the glass silhouette)
  drawChalkyCyanWall();
  drawTabletopAndCaustics();

  // 3. WET-INTO-WET TITRATION WATERCOLOR GRADIENTS INSIDE THE GLASS
  drawTitrationLiquid();

  // 4. SUBMERGED ICE CUBES (Lower & Mid-depth cubes behind/around lemon)
  drawLowerAndMidIceCubes();

  // 5. THE PLUNGED LEMON WHEEL & ACID-DIFFUSION WAKE
  drawPlungedLemonWheel();

  // 6. UPPER ICE CUBES (Reserved white paper with crisp graphite fracture lines)
  drawUpperIceCubes();

  // 7. LIQUID MENISCUS, RISING BUBBLES & SURFACE REFRACTIONS
  drawMeniscusAndBubbles();

  // 8. HEAVY GLASS SHAM (BASE), SIDE WALL REFRACTIONS, RIM & CONDENSATION
  drawGlassBaseSham();
  drawGlassWallsAndRim();
  drawCondensationAndFinalDetails();

  noLoop();
}

// ---------------------------------------------------------------------------
// 1. SUBTLE PAPER TEXTURE
// ---------------------------------------------------------------------------
function drawPaperGrain() {
  brush.noFill();
  brush.noHatch();
  brush.set("2H", "#EAE3D2", 0.18);
  for (let i = 0; i < 160; i++) {
    let x = random(30, 1170);
    let y = random(30, 1170);
    let len = random(18, 65);
    brush.line(x, y, x + len, y + random(-2, 2));
  }
}

// ---------------------------------------------------------------------------
// 2. FLAT CHALKY CYAN WALL (Around the glass so interior remains pure paper)
// ---------------------------------------------------------------------------
function drawChalkyCyanWall() {
  brush.noStroke();
  brush.noHatch();

  // Build left, top, and right wall polygons that hug the outer glass contour cleanly
  let leftWallPts = [
    [0, 0],
    [GX, 0],
    [GX, RIM_Y - RIM_RY]
  ];
  for (let a = 265; a >= 180; a -= 15) {
    leftWallPts.push([
      GX + RIM_RX * cos(a),
      RIM_Y + RIM_RY * sin(a)
    ]);
  }
  for (let y = RIM_Y; y <= WALL_Y; y += 45) {
    leftWallPts.push([GX - glassOuterRx(y), y]);
  }
  leftWallPts.push([0, WALL_Y]);

  let rightWallPts = [
    [GX, 0],
    [1200, 0],
    [1200, WALL_Y],
    [GX + glassOuterRx(WALL_Y), WALL_Y]
  ];
  for (let y = WALL_Y; y >= RIM_Y; y -= 45) {
    rightWallPts.push([GX + glassOuterRx(y), y]);
  }
  for (let a = 0; a >= -90; a -= 15) {
    rightWallPts.push([
      GX + RIM_RX * cos(a),
      RIM_Y + RIM_RY * sin(a)
    ]);
  }

  // Base flat chalky cyan wash
  brush.wash("#87A3A6", 225);
  drawOrganicPoly(leftWallPts, 0.02);
  drawOrganicPoly(rightWallPts, 0.02);
  brush.noWash();

  // Layered matte plaster / chalky mineral watercolor washes on the wall
  const cyanTones = [
    { col: "#7A989B", op: 55, bleed: 0.18 },
    { col: "#94B0B2", op: 50, bleed: 0.22 },
    { col: "#6E8D90", op: 40, bleed: 0.15 },
    { col: "#A3BCBD", op: 45, bleed: 0.20 }
  ];

  for (let t of cyanTones) {
    brush.fill(t.col, t.op);
    brush.fillBleed(t.bleed, "in");
    brush.fillTexture(0.45, 0.2);

    // Left wall patches
    for (let i = 0; i < 4; i++) {
      let y1 = random(20, WALL_Y - 180);
      let y2 = min(WALL_Y - 5, y1 + random(140, 280));
      let xRight1 = GX - glassOuterRx(constrain(y1, RIM_Y, WALL_Y)) - 6;
      let xRight2 = GX - glassOuterRx(constrain(y2, RIM_Y, WALL_Y)) - 6;
      if (y2 < RIM_Y) { xRight1 = GX + 80; xRight2 = GX + 80; }
      let x1 = random(0, max(40, xRight1 - 180));
      drawOrganicPoly([
        [x1, y1],
        [xRight1, y1 + random(-10, 10)],
        [xRight2, y2 + random(-10, 10)],
        [x1, y2]
      ], 0.15);
    }

    // Right wall patches (expansive negative space)
    for (let i = 0; i < 6; i++) {
      let y1 = random(15, WALL_Y - 200);
      let y2 = min(WALL_Y - 5, y1 + random(150, 320));
      let xLeft1 = (y1 < RIM_Y - 20) ? GX : GX + glassOuterRx(constrain(y1, RIM_Y, WALL_Y)) + 6;
      let xLeft2 = (y2 < RIM_Y - 20) ? GX : GX + glassOuterRx(constrain(y2, RIM_Y, WALL_Y)) + 6;
      let xStart = random(xLeft1, 1020);
      let xEnd = min(1195, xStart + random(160, 380));
      drawOrganicPoly([
        [xStart, y1],
        [xEnd, y1 + random(-12, 12)],
        [xEnd, y2 + random(-12, 12)],
        [xStart, y2]
      ], 0.15);
    }
  }
  brush.noFill();

  // Chalky dry-brush vertical and horizontal mineral tooth on the cyan wall
  brush.set("2H", "#ADC3C4", 0.22);
  for (let i = 0; i < 220; i++) {
    let y = random(15, WALL_Y - 12);
    let x = random(15, 1185);
    let rx = (y > RIM_Y - 30) ? glassOuterRx(constrain(y, RIM_Y, WALL_Y)) + 10 : 0;
    if (y > RIM_Y - 30 && abs(x - GX) < rx) continue;
    let len = random(35, 110);
    if (x < GX && x + len > GX - rx && y > RIM_Y - 30) len = max(8, (GX - rx) - x);
    brush.line(x, y, x + len, y + random(-1.5, 1.5));
  }

  brush.set("charcoal", "#6A8689", 0.16);
  for (let i = 0; i < 95; i++) {
    let y = random(20, WALL_Y - 15);
    let x = random(20, 1180);
    let rx = (y > RIM_Y - 30) ? glassOuterRx(constrain(y, RIM_Y, WALL_Y)) + 14 : 0;
    if (y > RIM_Y - 30 && abs(x - GX) < rx) continue;
    brush.line(x, y, x + random(-2, 2), min(WALL_Y - 10, y + random(25, 75)));
  }
}

// ---------------------------------------------------------------------------
// 2B. HORIZONTAL TABLETOP, CLEAN DAYLIGHT SHADOW & CAUSTIC REFRACTION
// ---------------------------------------------------------------------------
function drawTabletopAndCaustics() {
  brush.noStroke();
  brush.noHatch();

  // Tabletop polygon hugging the lower glass base so the glass sham stays crisp paper
  let tableLeft = [
    [0, WALL_Y],
    [GX - glassOuterRx(WALL_Y), WALL_Y],
    [GX - glassOuterRx(BASE_Y), BASE_Y]
  ];
  for (let a = 180; a >= 90; a -= 15) {
    tableLeft.push([
      GX + BASE_RX * cos(a),
      BASE_Y + BASE_RY * sin(a)
    ]);
  }
  tableLeft.push([GX, 1200], [0, 1200]);

  let tableRight = [
    [GX + glassOuterRx(WALL_Y), WALL_Y],
    [1200, WALL_Y],
    [1200, 1200],
    [GX, 1200]
  ];
  for (let a = 90; a >= 0; a -= 15) {
    tableRight.push([
      GX + BASE_RX * cos(a),
      BASE_Y + BASE_RY * sin(a)
    ]);
  }
  tableRight.push([GX + glassOuterRx(BASE_Y), BASE_Y]);

  // Warm pale stone / travertine wash
  brush.wash("#E5DEC9", 185);
  drawOrganicPoly(tableLeft, 0.02);
  drawOrganicPoly(tableRight, 0.02);
  brush.noWash();

  // Subtle warm earth washes across tabletop
  brush.fill("#D6CCB4", 55);
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.45, 0.2);
  drawOrganicPoly([
    [5, WALL_Y + 4],
    [GX - glassOuterRx(WALL_Y) - 8, WALL_Y + 4],
    [GX - glassOuterRx(BASE_Y) - 12, BASE_Y + 35],
    [5, BASE_Y + 40]
  ], 0.12);
  drawOrganicPoly([
    [GX + glassOuterRx(WALL_Y) + 8, WALL_Y + 4],
    [1195, WALL_Y + 4],
    [1195, BASE_Y + 60],
    [GX + glassOuterRx(BASE_Y) + 12, BASE_Y + 35]
  ], 0.12);

  // Clean daylight minimal shadow cast to the right of the glass
  // Outer cool-warm shadow envelope
  brush.fill("#B8B09C", 85);
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.4, 0.25);
  let shadowPts = [];
  for (let a = -25; a <= 195; a += 15) {
    let sx = 675 + 215 * cos(a);
    let sy = 952 + 37 * sin(a);
    if (sx < GX + BASE_RX - 15) sx = GX + BASE_RX - 15;
    shadowPts.push([sx, sy]);
  }
  drawOrganicPoly(shadowPts, 0.35);

  // Deeper shadow core right next to the glass base
  brush.fill("#968D7B", 95);
  brush.fillBleed(0.14, "out");
  drawOrganicPoly([
    [GX + BASE_RX - 8, BASE_Y - 10],
    [GX + BASE_RX + 145, BASE_Y - 14],
    [GX + BASE_RX + 185, BASE_Y + 8],
    [GX + BASE_RX + 115, BASE_Y + 26],
    [GX + BASE_RX - 20, BASE_Y + 24]
  ], 0.3);

  // Refracted golden-citrine & burnt-sienna caustic inside the shadow!
  brush.fill("#EAB940", 125);
  brush.fillBleed(0.25, "out");
  drawOrganicPoly([
    [GX + BASE_RX + 18, BASE_Y - 4],
    [GX + BASE_RX + 120, BASE_Y - 7],
    [GX + BASE_RX + 142, BASE_Y + 6],
    [GX + BASE_RX + 95, BASE_Y + 18],
    [GX + BASE_RX + 12, BASE_Y + 14]
  ], 0.35);

  brush.fill("#C8641C", 95);
  brush.fillBleed(0.2, "out");
  drawOrganicPoly([
    [GX + BASE_RX + 35, BASE_Y - 1],
    [GX + BASE_RX + 100, BASE_Y - 2],
    [GX + BASE_RX + 112, BASE_Y + 7],
    [GX + BASE_RX + 55, BASE_Y + 12]
  ], 0.35);

  // Bright caustic focal line
  brush.wash("#F8F3DC", 190);
  drawOrganicPoly([
    [GX + BASE_RX + 28, BASE_Y + 2],
    [GX + BASE_RX + 86, BASE_Y + 1],
    [GX + BASE_RX + 92, BASE_Y + 6],
    [GX + BASE_RX + 34, BASE_Y + 7]
  ], 0.2);
  brush.noWash();
  brush.noFill();

  // Crisp horizontal tabletop division line (left and right of glass)
  brush.set("2H", "#5E7274", 0.55);
  brush.line(0, WALL_Y, GX - glassOuterRx(WALL_Y) - 2, WALL_Y);
  brush.line(GX + glassOuterRx(WALL_Y) + 2, WALL_Y, 1200, WALL_Y);

  brush.set("HB", "#7A7264", 0.32);
  brush.line(0, WALL_Y + 2, GX - glassOuterRx(WALL_Y) - 2, WALL_Y + 2);
  brush.line(GX + glassOuterRx(WALL_Y) + 2, WALL_Y + 2, 1200, WALL_Y + 2);

  // Subtle horizontal stone grain lines on the tabletop
  brush.set("2H", "#C4B9A2", 0.22);
  for (let i = 0; i < 65; i++) {
    let y = random(WALL_Y + 8, 1185);
    let x1 = random(10, 1120);
    let x2 = min(1190, x1 + random(40, 180));
    if (y < BASE_Y + 35 && x2 > GX - BASE_RX - 10 && x1 < GX + BASE_RX + 10) continue;
    brush.line(x1, y, x2, y);
  }
}

// ---------------------------------------------------------------------------
// 3. WET-INTO-WET TITRATION WATERCOLOR GRADIENTS INSIDE THE GLASS
//    (Water -> Straw -> Citrine -> Honey -> Raw Sienna -> Burnt Sienna -> Mahogany)
// ---------------------------------------------------------------------------
function drawTitrationLiquid() {
  brush.noStroke();
  brush.noHatch();

  // Helper to build a vertical/diagonal wet-into-wet plume clamped to the glass interior
  function makePlume(xTop, xBot, yTop, yBot, wTop, wBot, steps = 10, wobble = 14) {
    let leftPts = [];
    let rightPts = [];
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let y = lerp(yTop, yBot, t);
      let cx = lerp(xTop, xBot, t) + sin(t * 180) * (wobble * 0.6);
      let w = lerp(wTop, wBot, sin(t * 140) * 0.35 + 0.65);
      let nL = (noise(i * 0.45, yTop * 0.01) - 0.5) * wobble * 2;
      let nR = (noise(i * 0.45 + 9, yBot * 0.01) - 0.5) * wobble * 2;
      let lx = clampToGlass(cx - w * 0.5 + nL, y, 9);
      let rx = clampToGlass(cx + w * 0.5 + nR, y, 9);
      if (rx - lx < 12) rx = min(GX + glassInnerRx(y), lx + 14);
      leftPts.push([lx, y]);
      rightPts.unshift([rx, y]);
    }
    return leftPts.concat(rightPts);
  }

  // STAGE A: Pale Straw & Citrine-Water Halo around upper-left/center (where lemon plunged)
  // Note: We intentionally leave the immediate upper-left ice & water pockets almost pure paper!
  const strawPasses = [
    { x1: GX - 75, x2: GX - 55, y1: LIQ_Y + 12, y2: 640, w1: 135, w2: 110, col: "#F4E8B4", op: 55, bleed: 0.38 },
    { x1: GX - 30, x2: GX - 40, y1: LIQ_Y + 18, y2: 710, w1: 150, w2: 125, col: "#EFE09E", op: 65, bleed: 0.42 },
    { x1: GX + 10, x2: GX - 10, y1: LIQ_Y + 10, y2: 680, w1: 140, w2: 130, col: "#EAD278", op: 65, bleed: 0.40 }
  ];
  for (let p of strawPasses) {
    brush.fill(p.col, p.op);
    brush.fillBleed(p.bleed, "out");
    brush.fillTexture(0.55, 0.32);
    drawOrganicPoly(makePlume(p.x1, p.x2, p.y1, p.y2, p.w1, p.w2, 10, 16), 0.38);
  }

  // STAGE B: Luminous Citrine & Pale Honey Wet-into-Wet Plumes (Streaming down from the lemon)
  const citrinePasses = [
    { x1: GX - 65, x2: GX - 50, y1: 350, y2: 780, w1: 115, w2: 95, col: "#E6C24C", op: 75, bleed: 0.42 },
    { x1: GX - 10, x2: GX - 25, y1: 310, y2: 830, w1: 135, w2: 120, col: "#DFB036", op: 80, bleed: 0.45 },
    { x1: GX + 35, x2: GX + 15, y1: 295, y2: 790, w1: 130, w2: 140, col: "#D89E28", op: 85, bleed: 0.40 },
    { x1: GX - 85, x2: GX - 70, y1: 490, y2: 865, w1: 85, w2: 90, col: "#DDA832", op: 75, bleed: 0.38 }
  ];
  for (let p of citrinePasses) {
    brush.fill(p.col, p.op);
    brush.fillBleed(p.bleed, "out");
    brush.fillTexture(0.62, 0.42);
    drawOrganicPoly(makePlume(p.x1, p.x2, p.y1, p.y2, p.w1, p.w2, 12, 18), 0.4);
  }

  // STAGE C: Golden Amber & Raw Sienna Transition Columns (Mid-titration boundary)
  const siennaPasses = [
    { x1: GX + 55, x2: GX + 35, y1: 300, y2: 865, w1: 125, w2: 155, col: "#C9781E", op: 90, bleed: 0.42 },
    { x1: GX + 15, x2: GX - 5, y1: 440, y2: 878, w1: 115, w2: 175, col: "#BE6416", op: 95, bleed: 0.45 },
    { x1: GX - 45, x2: GX - 35, y1: 560, y2: 878, w1: 95, w2: 140, col: "#C46D1B", op: 85, bleed: 0.38 },
    { x1: GX + 80, x2: GX + 60, y1: 315, y2: 860, w1: 95, w2: 120, col: "#B45614", op: 95, bleed: 0.36 }
  ];
  for (let p of siennaPasses) {
    brush.fill(p.col, p.op);
    brush.fillBleed(p.bleed, "out");
    brush.fillTexture(0.68, 0.48);
    drawOrganicPoly(makePlume(p.x1, p.x2, p.y1, p.y2, p.w1, p.w2, 12, 16), 0.4);
  }

  // STAGE D: Burnt Sienna & Deep Amber-Mahogany (Right side and deep lower body of tea)
  const mahoganyPasses = [
    { x1: GX + 78, x2: GX + 55, y1: 315, y2: 878, w1: 105, w2: 145, col: "#963912", op: 105, bleed: 0.38 },
    { x1: GX + 40, x2: GX + 10, y1: 500, y2: 882, w1: 120, w2: 215, col: "#822B0C", op: 110, bleed: 0.42 },
    { x1: GX - 20, x2: GX - 10, y1: 635, y2: 882, w1: 135, w2: 225, col: "#742309", op: 105, bleed: 0.40 },
    { x1: GX + 90, x2: GX + 68, y1: 360, y2: 872, w1: 80, w2: 110, col: "#611906", op: 115, bleed: 0.32 },
    { x1: GX + 25, x2: GX + 5, y1: 690, y2: 884, w1: 165, w2: 228, col: "#4E1204", op: 115, bleed: 0.35 },
    { x1: GX + 55, x2: GX + 35, y1: 580, y2: 878, w1: 110, w2: 155, col: "#380B02", op: 95, bleed: 0.30 }
  ];
  for (let p of mahoganyPasses) {
    brush.fill(p.col, p.op);
    brush.fillBleed(p.bleed, "out");
    brush.fillTexture(0.72, 0.52);
    drawOrganicPoly(makePlume(p.x1, p.x2, p.y1, p.y2, p.w1, p.w2, 12, 15), 0.38);
  }

  // STAGE E: Wet-into-wet watercolor backruns / cauliflower blooms where citric acid pushes dark tea
  const blooms = [
    { cx: GX + 22, cy: 485, rx: 42, ry: 68, col: "#E8CB62", op: 75 },
    { cx: GX - 18, cy: 555, rx: 48, ry: 74, col: "#E2BA46", op: 70 },
    { cx: GX + 38, cy: 615, rx: 38, ry: 62, col: "#C9741D", op: 75 },
    { cx: GX - 48, cy: 660, rx: 36, ry: 58, col: "#D99C2B", op: 70 }
  ];
  for (let b of blooms) {
    brush.fill(b.col, b.op);
    brush.fillBleed(0.45, "out");
    brush.fillTexture(0.75, 0.65); // High border intensity creates authentic watercolor bloom edge
    let pts = [];
    for (let a = 0; a < 360; a += 30) {
      let rMod = 0.8 + 0.4 * noise(b.cx * 0.02 + cos(a), b.cy * 0.02 + sin(a));
      let px = clampToGlass(b.cx + b.rx * rMod * cos(a), b.cy + b.ry * rMod * sin(a), 12);
      let py = constrain(b.cy + b.ry * rMod * sin(a), LIQ_Y + 20, SHAM_Y - 12);
      pts.push([px, py]);
    }
    drawOrganicPoly(pts, 0.45);
  }
  brush.noFill();

  // Long, delicate vertical watercolor diffusion streaks inside the liquid
  const streakColors = ["#F4E7B0", "#E2B53B", "#C86E1B", "#8C300E", "#521405"];
  for (let i = 0; i < 48; i++) {
    let tX = random(0, 1);
    let y1 = random(LIQ_Y + 25, 680);
    let y2 = min(SHAM_Y - 15, y1 + random(90, 260));
    let x1 = lerp(GX - glassInnerRx(y1) + 14, GX + glassInnerRx(y1) - 14, tX);
    let x2 = clampToGlass(x1 + random(-18, 18), y2, 14);
    // Pick color according to titration position (left/top = citrine/straw, right/bottom = burnt sienna/mahogany)
    let idx = floor(constrain(map(tX * 0.65 + ((y1 - LIQ_Y) / 600) * 0.55, 0, 1, 0, streakColors.length), 0, streakColors.length - 1));
    brush.set("watercolor", streakColors[idx], random(0.35, 0.85));
    let midY = (y1 + y2) * 0.5;
    let midX = (x1 + x2) * 0.5 + random(-10, 10);
    brush.spline([[x1, y1, 0.3], [midX, midY, 0.9], [x2, y2, 0.2]], 0.5);
  }
}

// ---------------------------------------------------------------------------
// HELPER: DRAW AN ICE CUBE (Reserved white paper core + translucent bevels + crisp graphite fractures)
// ---------------------------------------------------------------------------
function renderIceCube(cube) {
  const {
    cx, cy, w, h, angle,
    tintCol, tintOp, rimCol,
    paperReserveRatio = 0.85,
    fractureSeed = 100
  } = cube;

  // Compute 6-8 outer bevel vertices of a tumbled rounded-rectangular ice cube
  function pt(lx, ly) {
    let ca = cos(angle);
    let sa = sin(angle);
    return [
      cx + lx * ca - ly * sa,
      cy + lx * sa + ly * ca
    ];
  }

  let hw = w * 0.5;
  let hh = h * 0.5;

  let outerPoly = [
    pt(-hw * 0.78, -hh),
    pt(hw * 0.75, -hh * 0.96),
    pt(hw, -hh * 0.62),
    pt(hw * 0.96, hh * 0.72),
    pt(hw * 0.68, hh),
    pt(-hw * 0.74, hh * 0.95),
    pt(-hw, hh * 0.60),
    pt(-hw * 0.95, -hh * 0.68)
  ];

  // Inner reserved white paper facet
  let s = paperReserveRatio;
  let innerCore = [
    pt(-hw * 0.65 * s, -hh * 0.82 * s),
    pt(hw * 0.62 * s, -hh * 0.78 * s),
    pt(hw * 0.82 * s, -hh * 0.35 * s),
    pt(hw * 0.75 * s, hh * 0.55 * s),
    pt(hw * 0.35 * s, hh * 0.80 * s),
    pt(-hw * 0.60 * s, hh * 0.74 * s),
    pt(-hw * 0.80 * s, hh * 0.25 * s)
  ];

  // Top-left bright facet
  let topFacet = [
    outerPoly[7],
    outerPoly[0],
    outerPoly[1],
    innerCore[1],
    innerCore[0],
    innerCore[6]
  ];

  // Right-bottom refracted bevel facet
  let rightBevel = [
    outerPoly[1],
    outerPoly[2],
    outerPoly[3],
    outerPoly[4],
    innerCore[4],
    innerCore[3],
    innerCore[2],
    innerCore[1]
  ];

  brush.noStroke();
  brush.noHatch();

  // 1. Re-establish pure reserved white paper across the ice cube body
  brush.wash(PAPER, 240);
  drawOrganicPoly(outerPoly, 0.18);
  brush.noWash();

  // 2. Subtle surrounding liquid glaze in the outer bevels so the ice sits *inside* the tea
  brush.fill(tintCol, tintOp);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.45, 0.35);
  drawOrganicPoly(rightBevel, 0.2);
  brush.noFill();

  // 3. Re-enforce crisp untouched white paper on the top/center facets
  brush.wash(PAPER, 250);
  drawOrganicPoly(innerCore, 0.12);
  drawOrganicPoly(topFacet, 0.12);
  brush.noWash();

  // 4. Delicate graphite shading on one internal cleavage plane
  brush.hatchStyle("2H", "#8C9698", 0.22);
  brush.hatch(5.5, angle + 35, { rand: 0.08 });
  brush.noStroke();
  drawOrganicPoly([
    pt(hw * 0.15, -hh * 0.25),
    pt(hw * 0.68, -hh * 0.10),
    pt(hw * 0.55, hh * 0.48),
    pt(hw * 0.05, hh * 0.30)
  ], 0.1);
  brush.noHatch();

  // 5. Crisp Graphite Fracture Lines & Facet Edges (The signature detail!)
  // Outer bevel contour in varied-pressure 2H and HB graphite
  brush.set("2H", "#555F61", 0.42);
  for (let i = 0; i < outerPoly.length; i++) {
    let p1 = outerPoly[i];
    let p2 = outerPoly[(i + 1) % outerPoly.length];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Internal facet ridges
  brush.set("HB", "#3B4345", 0.38);
  for (let i = 0; i < innerCore.length; i += 2) {
    let p1 = innerCore[i];
    let p2 = innerCore[(i + 1) % innerCore.length];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    let pOut = outerPoly[i % outerPoly.length];
    brush.line(p1[0], p1[1], pOut[0], pOut[1]);
  }

  // Internal thermal stress fractures (branching razor-sharp angular graphite lines)
  randomSeed(fractureSeed);
  for (let f = 0; f < 5; f++) {
    let sx = random(-hw * 0.55, hw * 0.35);
    let sy = random(-hh * 0.55, hh * 0.35);
    let cur = pt(sx, sy);
    let segs = [[cur[0], cur[1], 0.8]];
    let dir = angle + random(-65, 65);
    for (let sIdx = 0; sIdx < 4; sIdx++) {
      dir += random(-38, 38);
      let stepLen = random(10, 24);
      let nx = cur[0] + cos(dir) * stepLen;
      let ny = cur[1] + sin(dir) * stepLen;
      segs.push([nx, ny, 0.5]);
      // Secondary micro-branch fracture
      if (sIdx === 1 || sIdx === 2) {
        brush.set("2H", "#485254", 0.30);
        let bDir = dir + random(35, 65) * (random() > 0.5 ? 1 : -1);
        let bx = nx + cos(bDir) * random(8, 18);
        let by = ny + sin(bDir) * random(8, 18);
        brush.line(nx, ny, bx, by);
      }
      cur = [nx, ny];
    }
    brush.set("HB", "#2D3436", 0.42);
    brush.spline(segs, 0.15);
  }

  // Accentuate fracture shadows & amber-tea pocket trapping in crevices
  brush.set("cpencil", rimCol, 0.45);
  brush.line(outerPoly[2][0], outerPoly[2][1], outerPoly[3][0], outerPoly[3][1]);
  brush.line(outerPoly[3][0], outerPoly[3][1], outerPoly[4][0], outerPoly[4][1]);
  brush.line(outerPoly[4][0], outerPoly[4][1], outerPoly[5][0], outerPoly[5][1]);

  // Tiny trapped air micro-bubbles inside the ice crystal
  brush.set("2H", "#4C5658", 0.28);
  for (let b = 0; b < 6; b++) {
    let bp = pt(random(-hw * 0.45, hw * 0.45), random(-hh * 0.45, hh * 0.45));
    brush.circle(bp[0], bp[1], random(1.5, 3.8), 0.15);
  }
}

