// ---------------------------------------------------------------------------
// 5. THE PLUNGED LEMON WHEEL & ACID-DIFFUSION WAKE
// ---------------------------------------------------------------------------
function drawPlungedLemonWheel() {
  const lcx = GX - 26;
  const lcy = 438;
  const rx = 86;   // Major semi-axis of lemon wheel
  const ry = 60;   // Minor semi-axis (tilted in 3D inside the liquid)
  const rot = -26; // Dynamic plunge tilt angle

  function lPt(rNorm, thetaDeg, shiftX = 0, shiftY = 0) {
    let lx = rx * rNorm * cos(thetaDeg);
    let ly = ry * rNorm * sin(thetaDeg);
    let ca = cos(rot);
    let sa = sin(rot);
    return [
      lcx + shiftX + lx * ca - ly * sa,
      lcy + shiftY + lx * sa + ly * ca
    ];
  }

  brush.noStroke();
  brush.noHatch();

  // 1. Bright Citrine-Water Titration Halo immediately surrounding the plunged lemon wheel
  brush.fill("#F6ECC4", 95);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.5, 0.35);
  let haloPts = [];
  for (let a = 0; a < 360; a += 24) {
    haloPts.push(lPt(1.28, a, 0, -10));
  }
  drawOrganicPoly(haloPts, 0.4);
  brush.noFill();

  // 2. Underside / Side 3D Rind Thickness (Flavedo)
  let rindBottomPts = [];
  for (let a = -15; a <= 205; a += 15) {
    rindBottomPts.push(lPt(1.03, a, 5, 13));
  }
  for (let a = 205; a >= -15; a -= 15) {
    rindBottomPts.push(lPt(0.96, a, 0, 0));
  }

  // Base citrine-gold rind wash
  brush.wash("#E5B524", 235);
  drawOrganicPoly(rindBottomPts, 0.25);
  brush.noWash();

  // Shaded ochre / raw sienna on lower curve of rind
  brush.fill("#B87614", 115);
  brush.fillBleed(0.2, "in");
  brush.fillTexture(0.55, 0.35);
  let rindShadePts = [];
  for (let a = 20; a <= 170; a += 15) {
    rindShadePts.push(lPt(1.03, a, 5, 13));
  }
  for (let a = 170; a >= 20; a -= 15) {
    rindShadePts.push(lPt(0.98, a, 2, 4));
  }
  drawOrganicPoly(rindShadePts, 0.25);
  brush.noFill();

  // 3. Outer Face of Lemon Wheel — Reserved White Paper Pith (Albedo)
  let faceOuterPts = [];
  for (let a = 0; a < 360; a += 15) {
    faceOuterPts.push(lPt(1.0, a));
  }
  // Thin vivid lemon-yellow outer rind edge around the face
  brush.wash("#ECC432", 230);
  drawOrganicPoly(faceOuterPts, 0.3);

  let pithOuterPts = [];
  for (let a = 0; a < 360; a += 15) {
    pithOuterPts.push(lPt(0.93, a));
  }
  // Pure reserved white paper for the pith & radial membranes!
  brush.wash(PAPER, 250);
  drawOrganicPoly(pithOuterPts, 0.3);
  brush.noWash();

  // 4. Translucent Citrus Carpels (9 radial segments)
  const numSegments = 9;
  const segPalette = ["#E8C84B", "#DFA92C", "#F0D868", "#D49322", "#E5BE3E"];

  for (let s = 0; s < numSegments; s++) {
    let aStart = s * (360 / numSegments) + 5.5;
    let aEnd = (s + 1) * (360 / numSegments) - 5.5;
    let aMid = (aStart + aEnd) * 0.5;

    let segPts = [
      lPt(0.16, aMid),
      lPt(0.28, aStart + 2),
      lPt(0.78, aStart + 1),
      lPt(0.83, aMid),
      lPt(0.78, aEnd - 1),
      lPt(0.28, aEnd - 2)
    ];

    // Base translucent citrine-honey watercolor fill for the segment
    let col = segPalette[s % segPalette.length];
    brush.fill(col, 135);
    brush.fillBleed(0.14, "in");
    brush.fillTexture(0.55, 0.4);
    drawOrganicPoly(segPts, 0.32);

    // Deeper amber-honey inner shadow near the core of each segment
    let innerSegPts = [
      lPt(0.18, aMid),
      lPt(0.48, aStart + 3),
      lPt(0.54, aMid),
      lPt(0.48, aEnd - 3)
    ];
    brush.fill("#C47A18", 85);
    brush.fillBleed(0.18, "in");
    drawOrganicPoly(innerSegPts, 0.3);
    brush.noFill();

    // Individual juice vesicles (radial teardrop cells) & reserved-paper highlights
    for (let v = 0; v < 7; v++) {
      let vr1 = random(0.24, 0.56);
      let vr2 = vr1 + random(0.14, 0.22);
      let va = random(aStart + 3, aEnd - 3);
      let vp1 = lPt(vr1, va);
      let vp2 = lPt(vr2, va);
      brush.set("2H", "#B57818", 0.26);
      brush.line(vp1[0], vp1[1], vp2[0], vp2[1]);

      // Specular white-paper glint on juice vesicles
      if (v % 2 === 0) {
        brush.set("pen", PAPER, 0.42);
        let hp1 = lPt(vr1 + 0.04, va + 1.5);
        let hp2 = lPt(vr2 - 0.03, va + 1.5);
        brush.line(hp1[0], hp1[1], hp2[0], hp2[1]);
      }
    }

    // Crisp graphite contour along segment membrane walls
    brush.set("2H", "#8F7C56", 0.30);
    for (let i = 0; i < segPts.length; i++) {
      let p1 = segPts[i];
      let p2 = segPts[(i + 1) % segPts.length];
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // 5. Central Pith Core & Cut Lemon Seeds
  let corePts = [];
  for (let a = 0; a < 360; a += 40) {
    corePts.push(lPt(0.15, a));
  }
  brush.wash(PAPER, 250);
  drawOrganicPoly(corePts, 0.35);
  brush.noWash();

  // Two small realistic teardrop seeds near the center
  let seedAngles = [42, 195];
  for (let sa of seedAngles) {
    let sp1 = lPt(0.08, sa);
    let sp2 = lPt(0.22, sa - 8);
    let sp3 = lPt(0.25, sa);
    let sp4 = lPt(0.22, sa + 8);
    brush.wash("#EFE4C2", 240);
    drawOrganicPoly([sp1, sp2, sp3, sp4], 0.35);
    brush.noWash();
    brush.set("HB", "#6E5326", 0.35);
    brush.line(sp1[0], sp1[1], sp2[0], sp2[1]);
    brush.line(sp2[0], sp2[1], sp3[0], sp3[1]);
    brush.line(sp3[0], sp3[1], sp4[0], sp4[1]);
    brush.line(sp4[0], sp4[1], sp1[0], sp1[1]);
  }

  // 6. Fine Botanical Graphite & Stipple Detail on Lemon Rind and Pith
  brush.set("2H", "#9E8D6C", 0.28);
  for (let i = 0; i < pithOuterPts.length; i++) {
    let p1 = pithOuterPts[i];
    let p2 = pithOuterPts[(i + 1) % pithOuterPts.length];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  brush.set("HB", "#7A4E0D", 0.38);
  for (let i = 0; i < rindBottomPts.length / 2 - 1; i++) {
    let p1 = rindBottomPts[i];
    let p2 = rindBottomPts[i + 1];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  // Oil gland pores along the rind
  brush.set("cpencil", "#8C580E", 0.35);
  for (let a = -5; a <= 195; a += 6) {
