// ============================================================================
// GEOMETRY & POLYGON CLIPPING UTILITIES
// ============================================================================

function evalBezier(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let b0 = u * u * u;
  let b1 = 3 * u * u * t;
  let b2 = 3 * u * t * t;
  let b3 = t * t * t;
  return [
    b0 * p0[0] + b1 * p1[0] + b2 * p2[0] + b3 * p3[0],
    b0 * p0[1] + b1 * p1[1] + b2 * p2[1] + b3 * p3[1]
  ];
}

function sampleBezierChain(segments, stepsPerSeg = 16) {
  let pts = [];
  for (let s of segments) {
    for (let i = 0; i < stepsPerSeg; i++) {
      let t = i / stepsPerSeg;
      pts.push(evalBezier(s[0], s[1], s[2], s[3], t));
    }
  }
  return pts;
}

function buildMirrorGeometry() {
  // Base Mirror Glass Contour (sleek vintage muscle-car trapezoidal wedge)
  const glassSegs = [
    // Top edge (rising slightly toward outer peak)
    [[435, 355], [610, 304], [835, 286], [982, 314]],
    // Top-right corner
    [[982, 314], [1042, 326], [1068, 378], [1054, 458]],
    // Outer right edge (tapering inward)
    [[1054, 458], [1040, 535], [1012, 622], [972, 674]],
    // Bottom-right corner
    [[972, 674], [942, 712], [888, 722], [822, 720]],
    // Bottom edge
    [[822, 720], [690, 718], [562, 712], [476, 694]],
    // Bottom-left corner
    [[476, 694], [420, 682], [395, 636], [392, 565]],
    // Inner left edge
    [[392, 565], [388, 492], [398, 422], [412, 382]],
    // Top-left corner
    [[412, 382], [418, 365], [424, 358], [435, 355]]
  ];

  glassPolyPts = sampleBezierChain(glassSegs, 16);

  // Compute centroid of glass for eccentric offsets
  let cx = 715, cy = 515;

  // Inner prismatic glass bevel ring (~8px inside glass edge)
  glassBevelPts = glassPolyPts.map(p => {
    let dx = p[0] - cx;
    let dy = p[1] - cy;
    return [cx + dx * 0.976, cy + dy * 0.964];
  });

  // Outer edge of dark recessed gasket / inner bezel wall (~11px outside glass)
  gasketOuterPts = glassPolyPts.map(p => {
    let dx = p[0] - cx;
    let dy = p[1] - cy;
    let ox = dx < 0 ? -12 : 9;
    let oy = dy < 0 ? -11 : 10;
    return [p[0] + ox * (Math.abs(dx) / 340), p[1] + oy * (Math.abs(dy) / 220)];
  });

  // Sharp Chrome Bezel Ridge (the high-point apex around the glass aperture)
  bezelRidgePts = glassPolyPts.map(p => {
    let dx = p[0] - cx;
    let dy = p[1] - cy;
    let nx = dx / 340;
    let ny = dy / 220;
    let len = Math.sqrt(nx * nx + ny * ny) || 1;
    nx /= len;
    ny /= len;
    // Asymmetrical width: wider visor hood on top-left and top
    let leftBoost = p[0] < 650 ? map(p[0], 390, 650, 18, 0, true) : 0;
    let topBoost = p[1] < 480 ? map(p[1], 290, 480, 12, 0, true) : 0;
    let dist = 24 + leftBoost + topBoost;
    return [
      p[0] + nx * dist - (p[0] < 550 ? 8 : 0),
      p[1] + ny * dist - (p[1] < 450 ? 5 : 0)
    ];
  });

  // Outer Silhouette of the 3D Chrome Mirror Housing (shows the sculpted left bullet cowl cheek)
  housingOuterPts = glassPolyPts.map(p => {
    let dx = p[0] - cx;
    let dy = p[1] - cy;
    let nx = dx / 340;
    let ny = dy / 220;
    let len = Math.sqrt(nx * nx + ny * ny) || 1;
    nx /= len;
    ny /= len;

    // On the left and upper-left, the aerodynamic bullet housing extends dramatically left & up
    let cowlFactor = 0;
    if (p[0] < 720) {
      let fx = map(p[0], 390, 720, 1.0, 0.0, true);
      let fy = map(p[1], 295, 720, 1.05, 0.55, true);
      cowlFactor = Math.pow(fx, 1.35) * fy;
    }
    let baseDist = 38;
    let extraX = -cowlFactor * 74;
    let extraY = -cowlFactor * 36 + (p[1] > 640 && p[0] < 620 ? 14 : 0);
    return [
      p[0] + nx * baseDist + extraX,
      p[1] + ny * baseDist + extraY
    ];
  });
}

// Sutherland-Hodgman half-plane clipper: keeps points where (nx*x + ny*y >= c)
function clipPolyHalfPlane(pts, nx, ny, c) {
  if (!pts || pts.length < 3) return [];
  let out = [];
  for (let i = 0; i < pts.length; i++) {
    let cur = pts[i];
    let prev = pts[(i + pts.length - 1) % pts.length];
    let dCur = nx * cur[0] + ny * cur[1] - c;
    let dPrev = nx * prev[0] + ny * prev[1] - c;
    if (dCur >= 0) {
      if (dPrev < 0) {
        let t = dPrev / (dPrev - dCur);
        out.push([prev[0] + t * (cur[0] - prev[0]), prev[1] + t * (cur[1] - prev[1])]);
      }
      out.push(cur);
    } else if (dPrev >= 0) {
      let t = dPrev / (dPrev - dCur);
      out.push([prev[0] + t * (cur[0] - prev[0]), prev[1] + t * (cur[1] - prev[1])]);
    }
  }
  return out;
}

function slicePolyY(pts, yMin, yMax) {
  let p1 = clipPolyHalfPlane(pts, 0, 1, yMin);
  return clipPolyHalfPlane(p1, 0, -1, -yMax);
}

// Clip arbitrary polygon against a convex clipper polygon
function clipPolyToConvex(subjectPts, clipPts) {
  let out = subjectPts;
  // Determine winding of clipPts using centroid
  let cx = 0, cy = 0;
  for (let p of clipPts) { cx += p[0]; cy += p[1]; }
  cx /= clipPts.length; cy /= clipPts.length;

  for (let i = 0; i < clipPts.length; i++) {
    let a = clipPts[i];
    let b = clipPts[(i + 1) % clipPts.length];
    let nx = -(b[1] - a[1]);
    let ny = b[0] - a[0];
    let c = nx * a[0] + ny * a[1];
    if (nx * cx + ny * cy < c) {
      nx = -nx; ny = -ny; c = -c;
    }
    out = clipPolyHalfPlane(out, nx, ny, c);
    if (out.length < 3) return [];
  }
  return out;
}

function pointInPoly(x, y, vs) {
  let inside = false;
  for (let i = 0, j = vs.length - 1; i < vs.length; j = i++) {
    let xi = vs[i][0], yi = vs[i][1];
    let xj = vs[j][0], yj = vs[j][1];
    let intersect = ((yi > y) !== (yj > y)) &&
      (x < (xj - xi) * (y - yi) / ((yj - yi) || 1e-6) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

// Safe wrappers that guarantee brush.set() is always active for strokes
function strokeLine(bName, col, weight, x1, y1, x2, y2) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, weight);
  brush.line(x1, y1, x2, y2);
}

function strokeSpline(bName, col, weight, pts, curv = 0.5) {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, weight);
  brush.spline(pts, curv);
}

function washPoly(pts, col, opacity) {
  if (!pts || pts.length < 3) return;
  let p = new brush.Polygon(pts);
  p.wash(col, opacity);
}

function fillPoly(pts, col, opacity, bleed = 0.2, tex = 0.3) {
  if (!pts || pts.length < 3) return;
  let p = new brush.Polygon(pts);
  p.fill(col, opacity, bleed, tex);
}

// Build a quad band between two equal-length point arrays from index i0 to i1
function getRingBandPoly(ringA, ringB, i0, i1) {
  let pts = [];
  let n = ringA.length;
  for (let i = i0; i <= i1; i++) {
    pts.push(ringA[(i + n) % n]);
  }
  for (let i = i1; i >= i0; i--) {
    pts.push(ringB[(i + n) % n]);
  }
  return pts;
}

