// ============================================================================
// 4. CHROME MIRROR HOUSING, BULLET COWL & BEZEL COLLAR
// ============================================================================

function drawChromeHousingAndBezel() {
  let n = glassPolyPts.length; // 128 vertices around the clock
  // Vertex index mapping along the 8 Bezier segments (16 steps each):
  // 0..16: Top edge (left to right)
  // 16..32: Top-right corner
  // 32..48: Outer right edge (top to bottom)
  // 48..64: Bottom-right corner
  // 64..80: Bottom edge (right to left)
  // 80..96: Bottom-left corner
  // 96..112: Inner left edge (bottom to top)
  // 112..128: Top-left corner

  // A. OUTER HOUSING SLOPE (Between housingOuterPts and bezelRidgePts)
  // Draw segment by segment with high-contrast liquid-chrome horizon reflections
  for (let i = 0; i < n; i++) {
    let iNext = i + 1;
    let quad = getRingBandPoly(housingOuterPts, bezelRidgePts, i, iNext);
    let midY = (housingOuterPts[i][1] + bezelRidgePts[i][1]) * 0.5;
    let midX = (housingOuterPts[i][0] + bezelRidgePts[i][0]) * 0.5;

    let col = "#062838";
    // Top visor slope (0..22): reflects deep petrol sky -> cyan -> golden sun on left
    if (i < 22) {
      if (midX < 540) col = "#ffb84d";
      else if (midX < 680) col = "#3ca6b8";
      else if (midX < 860) col = "#0d4a61";
      else col = "#052230";
    }
    // Top-right & right slope (22..52): sharp horizon transition at y ~ 455
    else if (i < 52) {
      if (midY < 390) col = "#073142";
      else if (midY < 435) col = "#4ec4d4";
      else if (midY < 468) col = "#fff2bd";
      else if (midY < 495) col = "#020c12";
      else if (midY < 575) col = "#e85d0c";
      else col = "#051f2c";
    }
    // Bottom slope (52..88): dark asphalt reflection + warm tangerine door/road bounce
    else if (i < 88) {
      if (midX > 820) col = "#031621";
      else if (midX > 620) col = "#b83e06";
      else if (midX > 480) col = "#ff8019";
      else col = "#021018";
    }
    // Left Bullet Cowl Cheek (88..128): Hero raking golden-hour chrome reflection!
    else {
      if (midY < 355) col = "#08374a";
      else if (midY < 395) col = "#3eb0c4";
      else if (midY < 432) col = "#ffffff";
      else if (midY < 468) col = "#ffae38";
      else if (midY < 496) col = "#020b10"; // Sharp chrome horizon line!
      else if (midY < 545) col = "#d94604";
      else if (midY < 610) col = "#ff851b";
      else if (midY < 655) col = "#ffc466";
      else col = "#041c29";
    }
    washPoly(quad, col, 252);
  }

  // Soft chrome glazing over the Left Bullet Cowl Cheek for seamless metallic curvature
  for (let i = 86; i < 127; i += 2) {
    let pOut1 = housingOuterPts[i % n];
    let pIn1 = bezelRidgePts[i % n];
    let pOut2 = housingOuterPts[(i + 2) % n];
    let pIn2 = bezelRidgePts[(i + 2) % n];
    let yAvg = (pOut1[1] + pIn1[1]) * 0.5;

    let glazeCol = "#ff7b17";
    if (yAvg < 385) glazeCol = "#125c75";
    else if (yAvg < 445) glazeCol = "#fff4c2";
    else if (yAvg < 500) glazeCol = "#020e16";
    else if (yAvg < 630) glazeCol = "#ff9429";
    else glazeCol = "#072c3d";

    strokeLine("chrome_shader", glazeCol, 1.1,
      (pOut1[0] + pOut2[0]) * 0.5, (pOut1[1] + pOut2[1]) * 0.5,
      (pIn1[0] + pIn2[0]) * 0.5, (pIn1[1] + pIn2[1]) * 0.5
    );
  }

  // B. INWARD BEZEL LIP / COWL OVERHANG (Between bezelRidgePts and gasketOuterPts)
  // This recessed metal wall faces INWARD toward the glass:
  // - Top/Left overhang is in deep petrol shadow (#020e16, #072c3d)
  // - Right & Bottom inner lip catches blazing raking tangerine & white-gold sunlight!
  for (let i = 0; i < n; i++) {
    let quad = getRingBandPoly(bezelRidgePts, gasketOuterPts, i, i + 1);
    let midX = (bezelRidgePts[i][0] + gasketOuterPts[i][0]) * 0.5;
    let midY = (bezelRidgePts[i][1] + gasketOuterPts[i][1]) * 0.5;

    let col = "#031520";
    // Top inner visor wall (0..20): deep petrol shadow with subtle cyan sky bounce
    if (i < 20) {
      col = midX < 680 ? "#020d14" : "#083142";
    }
    // Right inner wall (20..54): directly faces the raking golden sun from the left!
    else if (i < 54) {
      if (midY < 375) col = "#3ca8ba";
      else if (midY < 475) col = "#fff0b5";
      else if (midY < 590) col = "#ff8014";
      else col = "#c94204";
    }
    // Bottom inner lip (54..84): catches blazing golden-hour upward/side reflection!
    else if (i < 84) {
      if (midX > 840) col = "#ff942e";
      else if (midX > 620) col = "#ffd980";
      else if (midX > 490) col = "#ff730f";
      else col = "#062636";
    }
    // Left inner wall (84..128): shaded overhang with a hot orange horizon band
    else {
      if (midY > 490 && midY < 545) col = "#9e3304";
      else if (midY < 390) col = "#020b10";
      else col = "#05202e";
    }
    washPoly(quad, col, 255);
  }

  // C. RECESSED DARK RUBBER GASKET CHANNEL (Between gasketOuterPts and glassPolyPts)
  for (let i = 0; i < n; i++) {
    let quad = getRingBandPoly(gasketOuterPts, glassPolyPts, i, i + 1);
    let col = (i >= 22 && i <= 75) ? "#061e2b" : "#01070b";
    washPoly(quad, col, 255);
  }

  // Cast shadow of the upper-left cowl visor falling onto the top-left strip of the mirror glass
  let visorShadowPts = [];
  for (let i = 104; i <= 146; i++) {
    visorShadowPts.push(glassPolyPts[i % n]);
  }
  for (let i = 146; i >= 104; i--) {
    let p = glassPolyPts[i % n];
    visorShadowPts.push([p[0] + 16, p[1] + 14]);
  }
  washPoly(clipPolyToConvex(visorShadowPts, glassPolyPts), "#010910", 165);

  // D. RAZOR-SHARP MARKER LINES FOR CHROME EDGES, SEAMS & SPECULAR HIGHLIGHTS
  // 1. Outer housing silhouette edge
  strokeSpline("chrome_pen", "#01080d", 1.4, [...housingOuterPts, housingOuterPts[0]], 0.4);
  // Raking sun highlight on the upper-left and left outer housing edge
  strokeSpline("chrome_pen", "#ffffff", 1.7, housingOuterPts.slice(106, 128).concat(housingOuterPts.slice(0, 12)), 0.4);
  strokeSpline("chrome_pen", "#ff9424", 1.5, housingOuterPts.slice(86, 110), 0.4);
  strokeSpline("chrome_pen", "#5ce1f2", 1.1, housingOuterPts.slice(10, 32), 0.4);

  // 2. Sharp Bezel Ridge apex (bezelRidgePts)
  strokeSpline("chrome_pen", "#021018", 1.5, [...bezelRidgePts, bezelRidgePts[0]], 0.4);
  // Blazing white & tangerine highlights along the bezel ridge corners
  strokeSpline("chrome_pen", "#ffffff", 1.9, bezelRidgePts.slice(112, 128).concat(bezelRidgePts.slice(0, 16)), 0.4);
  strokeSpline("chrome_pen", "#ffb84d", 1.4, bezelRidgePts.slice(18, 48), 0.4);
  strokeSpline("chrome_pen", "#ff7714", 1.4, bezelRidgePts.slice(56, 86), 0.4);
  strokeSpline("chrome_pen", "#7ce8f5", 1.2, bezelRidgePts.slice(92, 114), 0.4);

  // 3. Inner gasket & glass seating edge
  strokeSpline("micro_detail", "#010609", 1.3, [...glassPolyPts, glassPolyPts[0]], 0.4);
  // Inner lip specular catch on the right and bottom bezel wall
  strokeSpline("chrome_pen", "#fff4c2", 1.3, gasketOuterPts.slice(22, 50), 0.4);
  strokeSpline("chrome_pen", "#ff9429", 1.2, gasketOuterPts.slice(52, 82), 0.4);
}

// ============================================================================
// 5. GLASS SURFACE INCIDENTS (PRISMATIC BEVEL, ETCHED TEXT, BUG SPLAT, DUST, FLARE)
// ============================================================================

function drawGlassSurfaceDetails() {
  // A. PRISMATIC DOUBLE-REFLECTION GLASS BEVEL (8px chamfer inside glassPolyPts)
  // Top & Left bevel catches electric cyan sky glint
  strokeSpline("micro_detail", "#64e8f5", 1.0, glassBevelPts.slice(105, 128).concat(glassBevelPts.slice(0, 24)), 0.4);
  // Right bevel catches blinding white-gold & tangerine sun reflection
  strokeSpline("chrome_pen", "#ffffff", 1.1, glassBevelPts.slice(24, 52), 0.4);
  strokeSpline("micro_detail", "#ff881c", 0.9, glassBevelPts.slice(20, 56), 0.4);
  // Bottom bevel catches warm amber & cyan double-edge
  strokeSpline("micro_detail", "#ffae47", 0.95, glassBevelPts.slice(54, 86), 0.4);
  strokeSpline("micro_detail", "#2da6b8", 0.75, glassBevelPts.slice(84, 108), 0.4);

  // B. ETCHED WARNING TEXT ALONG BOTTOM OF MIRROR GLASS
  // "OBJECTS IN MIRROR ARE CLOSER THAN THEY APPEAR" simulated as crisp micro-etched glyph ticks
  const wordLengths = [7, 2, 6, 3, 6, 4, 4, 6]; // character counts per word
  let cursorX = 578;
  let baseY = 696;
  for (let w = 0; w < wordLengths.length; w++) {
    let chars = wordLengths[w];
    for (let c = 0; c < chars; c++) {
      let cy = baseY + (cursorX - 700) * 0.022;
      let col = cursorX > 720 && cursorX < 810 ? "#ffe49e" : "#7ccad6";
      // Vertical & horizontal micro-strokes of etched capital letters
      strokeLine("micro_detail", col, 0.42, cursorX, cy - 3.5, cursorX, cy + 3.5);
      if (c % 2 === 0) {
        strokeLine("micro_detail", col, 0.38, cursorX, cy - 3.5, cursorX + 2.8, cy - 3.5);
        strokeLine("micro_detail", col, 0.38, cursorX, cy + 3.5, cursorX + 2.8, cy + 3.5);
      } else {
        strokeLine("micro_detail", col, 0.38, cursorX, cy, cursorX + 2.6, cy - 3.2);
      }
      cursorX += 4.6;
    }
    cursorX += 7.5; // space between words
  }

  // C. SUBTLE CIRCULAR WIPING MICRO-SCRATCHES ON THE GLASS SURFACE
  // Fine hairline arcs catching the low golden sun near the bright sky/horizon
  for (let i = 0; i < 24; i++) {
    let sx = random(530, 960);
    let sy = random(350, 620);
    if (!pointInPoly(sx, sy, glassPolyPts)) continue;
    let len = random(18, 52);
    let ang = random(-25, 35);
    let mx = sx + cos(ang) * len * 0.5 + random(-4, 4);
    let my = sy + sin(ang) * len * 0.5 - random(3, 8);
    let ex = sx + cos(ang) * len;
    let ey = sy + sin(ang) * len;
    if (!pointInPoly(ex, ey, glassPolyPts)) continue;
    let col = sy < 470 ? "#5ce1f2" : "#ffd27d";
    strokeSpline("micro_detail", col, 0.32, [[sx, sy], [mx, my], [ex, ey]], 0.5);
  }

  // D. BACKLIT GOLDEN-HOUR DUST SPECKS (Across Glass & Chrome Housing)
  // On a second-surface mirror, each dust speck on the front glass casts a tiny offset reflection!
  for (let i = 0; i < 240; i++) {
    let dx = random(345, 1050);
    let dy = random(280, 735);
    let inGlass = pointInPoly(dx, dy, glassPolyPts);
    let inHousing = pointInPoly(dx, dy, housingOuterPts);
    if (!inGlass && !inHousing) continue;

    let isBright = random() < 0.35;
    let speckLen = isBright ? random(1.2, 2.6) : random(0.6, 1.4);
    let w = isBright ? random(0.65, 1.15) : random(0.35, 0.65);

    // Choose backlit tangerine, white-gold, or ice-cyan depending on local light
    let col = random(["#ffd478", "#ff9429", "#fff6d1", "#7ce8f5"]);
    if (inGlass) {
      // Secondary ghost reflection offset 3.5px down-right inside the glass thickness
      strokeLine("micro_detail", "#031824", w * 0.75, dx + 3.2, dy + 2.8, dx + 3.2 + speckLen, dy + 2.8);
    }
    strokeLine("micro_detail", col, w, dx, dy, dx + speckLen, dy + 0.4);
  }

  // E. THE SINGLE BUG SPLAT ON THE GLASS (Focal hyperreal detail at x = 632, y = 428)
  drawBugSplat(632, 428);

  // F. ANAMORPHIC HORIZONTAL LENS FLARE STREAKS
  // 1. Solar flare streak from the blinding left chrome visor corner (x = 408, y = 418)
  const flareY1 = 418;
  strokeLine("soft_glaze", "#3ca8ba", 0.55, 140, flareY1, 720, flareY1);
  strokeLine("chrome_pen", "#6ce8f5", 0.9, 250, flareY1, 610, flareY1);
  strokeLine("chrome_pen", "#ffffff", 1.3, 345, flareY1, 495, flareY1);
  strokeLine("micro_detail", "#ffae47", 0.8, 310, flareY1 + 2, 540, flareY1 + 2);

  // 2. Subtle horizontal anamorphic streak across the horizon vanishing point glare (x = 775, y = 534)
  const flareY2 = 534;
  strokeLine("soft_glaze", "#ff7714", 0.5, 590, flareY2, 960, flareY2);
  strokeLine("chrome_pen", "#ffd278", 0.85, 670, flareY2, 880, flareY2);
  strokeLine("micro_detail", "#ffffff", 1.0, 730, flareY2, 820, flareY2);
}

function drawBugSplat(bx, by) {
  // 1. Secondary reflection (ghost double-image on the rear silvered surface of the mirror glass, offset +5px, +4px)
  let gx = bx + 5.5;
  let gy = by + 4.5;
  let ghostPts = [];
  for (let a = 0; a < 360; a += 30) {
    let r = 7 + noise(a * 0.1) * 6;
    ghostPts.push([gx + cos(a) * r * 1.2, gy + sin(a) * r * 0.85]);
  }
  washPoly(ghostPts, "#010a10", 185);
  for (let i = 0; i < 14; i++) {
    let ang = map(i, 0, 14, -65, 220);
    let len = random(10, 26);
    strokeLine("micro_detail", "#02131c", 0.5, gx, gy, gx + cos(ang) * len, gy + sin(ang) * len);
  }

  // 2. Translucent viscous amber-cream outer impact halo on the front glass surface
  let haloPts = [];
  for (let a = 0; a < 360; a += 20) {
    let windStretch = cos(a) > 0 ? 1.45 : 0.85; // Wind-sheared to the right by car speed
    let r = (8 + noise(a * 0.08 + 10) * 7) * windStretch;
    haloPts.push([bx + cos(a) * r, by + sin(a) * (6 + noise(a * 0.08 + 20) * 5)]);
  }
  washPoly(haloPts, "#d97b16", 175);
  fillPoly(haloPts, "#ffae3b", 140, 0.25, 0.2);

  // 3. Dense creamy-yellow inner body core
  let corePts = [];
  for (let a = 0; a < 360; a += 24) {
    let r = 4.5 + noise(a * 0.12 + 50) * 4;
    corePts.push([bx + cos(a) * r * 1.15, by + sin(a) * r * 0.85]);
  }
  washPoly(corePts, "#fff0b3", 240);

  // 4. Radial wind-sheared micro-splatter streaks & terminal bead droplets
  const streakCount = 34;
  for (let i = 0; i < streakCount; i++) {
    let ang = random(360);
    // Bias longer streaks toward the right/upper-right (-55 to +55 deg) due to airflow across glass
    let isWindward = cos(ang) > 0.15;
    let innerR = random(4, 8);
    let outerR = isWindward ? random(16, 46) : random(9, 22);
    let x1 = bx + cos(ang) * innerR;
    let y1 = by + sin(ang) * innerR * 0.85;
    let x2 = bx + cos(ang) * outerR + (isWindward ? random(2, 8) : 0);
    let y2 = by + sin(ang) * outerR * 0.85;

    let col = i % 3 === 0 ? "#ff9d2e" : (i % 3 === 1 ? "#ffe699" : "#c45b08");
    strokeLine("micro_detail", col, random(0.45, 0.85), x1, y1, x2, y2);

    // Terminal micro-droplet bead at the tip of the splatter ray
    let dropX = x2 + cos(ang) * random(2.5, 6);
    let dropY = y2 + sin(ang) * random(2, 5);
    // Dark shadow side of droplet
    strokeLine("micro_detail", "#021018", 0.85, dropX + 1.2, dropY + 1.0, dropX + 2.4, dropY + 1.4);
    // Bright golden-white sun catch on droplet
    strokeLine("micro_detail", "#ffffff", 0.8, dropX, dropY, dropX + 1.3, dropY + 0.3);
  }

  // 5. Tiny crumpled dark chitin fragment, wing translucent glint & crooked leg in center
  let chitinPts = [
    [bx - 4, by - 2], [bx + 2, by - 4], [bx + 5, by + 1], [bx - 1, by + 3]
  ];
  washPoly(chitinPts, "#0c1418", 255);

  // Translucent iridescent wing fragment jutting up-right
  let wingPts = [
    [bx + 1, by - 2], [bx + 14, by - 11], [bx + 18, by - 6], [bx + 4, by + 1]
  ];
  washPoly(wingPts, "#8ce8f5", 160);
  strokeLine("micro_detail", "#ffffff", 0.65, bx + 1, by - 2, bx + 16, by - 9);
  strokeLine("micro_detail", "#ff9e38", 0.5, bx + 3, by - 1, bx + 15, by - 6);

  // Two tiny jointed insect legs
  strokeSpline("micro_detail", "#050d12", 0.75, [[bx - 2, by + 1], [bx - 9, by + 6], [bx - 14, by + 3]], 0.2);
  strokeSpline("micro_detail", "#050d12", 0.7, [[bx + 2, by + 2], [bx + 8, by + 9], [bx + 15, by + 8]], 0.2);

  // Razor-sharp golden-white specular rim highlights on the thickest viscous ridges
  strokeSpline("chrome_pen", "#ffffff", 0.95, [[bx - 6, by - 3], [bx - 2, by - 6], [bx + 4, by - 5]], 0.4);
  strokeSpline("micro_detail", "#ff8814", 0.85, [[bx - 5, by + 4], [bx + 1, by + 6], [bx + 7, by + 4]], 0.4);
}

