// Clip polygon vertices to a bounding rectangle (Sutherland-Hodgman)
function clipPolyEdge(pts, insideFn, intersectFn) {
  if (!pts || pts.length === 0) return [];
  let out = [];
  for (let i = 0; i < pts.length; i++) {
    let cur = pts[i];
    let prev = pts[(i + pts.length - 1) % pts.length];
    let curIn = insideFn(cur);
    let prevIn = insideFn(prev);
    if (curIn) {
      if (!prevIn) out.push(intersectFn(prev, cur));
      out.push(cur);
    } else if (prevIn) {
      out.push(intersectFn(prev, cur));
    }
  }
  return out;
}

function clipPoly(pts, x0 = -8, y0 = -8, x1 = 1208, y1 = 1208) {
  let p = pts;
  p = clipPolyEdge(p, pt => pt[0] >= x0, (a, b) => [x0, a[1] + (b[1] - a[1]) * (x0 - a[0]) / (b[0] - a[0])]);
  p = clipPolyEdge(p, pt => pt[0] <= x1, (a, b) => [x1, a[1] + (b[1] - a[1]) * (x1 - a[0]) / (b[0] - a[0])]);
  p = clipPolyEdge(p, pt => pt[1] >= y0, (a, b) => [a[0] + (b[0] - a[0]) * (y0 - a[1]) / (b[1] - a[1]), y0]);
  p = clipPolyEdge(p, pt => pt[1] <= y1, (a, b) => [a[0] + (b[0] - a[0]) * (y1 - a[1]) / (b[1] - a[1]), y1]);
  return p;
}

function inCanvas(x, y, pad = 12) {
  return x >= -pad && x <= 1200 + pad && y >= -pad && y <= 1200 + pad;
}

function setStrokeState(name, col, w = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(name, col, w);
}

function circlePoints(cx, cy, r, steps = 72) {
  let pts = [];
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    pts.push([cx + r * cos(a), cy + r * sin(a)]);
  }
  return pts;
}

function sectorPoints(cx, cy, r, aStart, aEnd, steps = 36) {
  let pts = [[cx, cy]];
  for (let i = 0; i <= steps; i++) {
    let a = lerp(aStart, aEnd, i / steps);
    pts.push([cx + r * cos(a), cy + r * sin(a)]);
  }
  return pts;
}

function annulusSectorPoints(cx, cy, r1, r2, aStart, aEnd, steps = 20) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let a = lerp(aStart, aEnd, i / steps);
    pts.push([cx + r2 * cos(a), cy + r2 * sin(a)]);
  }
  for (let i = steps; i >= 0; i--) {
    let a = lerp(aStart, aEnd, i / steps);
    pts.push([cx + r1 * cos(a), cy + r1 * sin(a)]);
  }
  return pts;
}

// Draw a clipped polyline / curve in segments that stay inside the canvas
function drawClippedChain(pts, brushName, col, w, curvature = 0.25) {
  let chunk = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (inCanvas(p[0], p[1], 10)) {
      chunk.push(p);
    } else {
      if (chunk.length >= 2) {
        setStrokeState(brushName, col, w);
        brush.beginShape(curvature);
        for (let pt of chunk) brush.vertex(pt[0], pt[1]);
        brush.endShape(false);
      }
      chunk = [];
    }
  }
  if (chunk.length >= 2) {
    setStrokeState(brushName, col, w);
    brush.beginShape(curvature);
    for (let pt of chunk) brush.vertex(pt[0], pt[1]);
    brush.endShape(false);
  }
}

// Draw a clipped straight line segment
function drawClippedLine(x1, y1, x2, y2, brushName, col, w) {
  let pts = clipPoly([[x1, y1], [x2, y2], [x2 + 0.01, y2 + 0.01]], -6, -6, 1206, 1206);
  if (pts.length >= 2) {
    let a = pts[0];
    let b = pts[1];
    if (dist(a[0], a[1], b[0], b[1]) > 0.8) {
      setStrokeState(brushName, col, w);
      brush.line(a[0], a[1], b[0], b[1]);
    }
  }
}

// Render a polygonal crop region with multi-pass directional coloured pencil
function renderCropPolygon(rawPts, pal, rowAngle, spacing = 3.2, crossWeight = 0.32) {
  let pts = clipPoly(rawPts, -6, -6, 1206, 1206);
  if (pts.length < 3) return;

  let poly = new brush.Polygon(pts);

  // 1. Coloured pencil pigment base & subtle paper grain
  brush.noStroke();
  brush.noHatch();
  poly.wash(pal.wash, 125);
  poly.fill(pal.base, 50, 0.015, 0.6);

  // 2. Multi-pass vernier directional hatching along planting rows
  brush.set("cpencil", pal.base, 0.75);
  brush.hatchStyle("cpencil", pal.base, 0.82);
  poly.hatch(spacing, rowAngle, { rand: 0.025 });

  brush.hatchStyle("cpencil", pal.mid, 0.72);
  poly.hatch(spacing * 1.62, rowAngle, { rand: 0.035 });

  brush.hatchStyle("cpencil", pal.light, 0.65);
  poly.hatch(spacing * 2.55, rowAngle, { rand: 0.04 });

  brush.hatchStyle("2H", pal.dark, 0.52);
  poly.hatch(spacing * 3.35, rowAngle, { rand: 0.03 });

  if (crossWeight > 0) {
    brush.hatchStyle("cpencil", pal.mid, crossWeight);
    poly.hatch(spacing * 3.9, rowAngle + 90, { rand: 0.05 });
  }
  brush.noHatch();
}

// Render individual planter-pass streaks across a circle or sector
function drawPlanterStreaks(cx, cy, r, rowAngle, pal, seedOffset = 0, aMin = null, aMax = null, step = 4.6) {
  let perpAngle = rowAngle + 90;
  let ca = cos(rowAngle), sa = sin(rowAngle);
  let cp = cos(perpAngle), sp = sin(perpAngle);

  for (let d = -r + 5; d <= r - 5; d += step) {
    let halfLen = sqrt(max(0, r * r - d * d)) - 2.5;
    if (halfLen < 6) continue;

    let n = noise(d * 0.055 + seedOffset, seedOffset * 0.37);
    let col = pal.mid;
    let bName = "cpencil";
    let w = 0.55;

    if (n < 0.28) {
      col = pal.dark;
      bName = "2H";
      w = 0.48;
    } else if (n > 0.68) {
      col = pal.light;
      bName = "cpencil";
      w = 0.68;
    } else if (n > 0.48 && n < 0.56) {
      col = pal.base;
      bName = "cpencil";
      w = 0.62;
    } else {
      continue;
    }

    let mx = cx + d * cp;
    let my = cy + d * sp;

    if (aMin === null) {
      let x1 = mx - halfLen * ca;
      let y1 = my - halfLen * sa;
      let x2 = mx + halfLen * ca;
      let y2 = my + halfLen * sa;
      drawClippedLine(x1, y1, x2, y2, bName, col, w);
    } else {
      // Sample along the chord and keep points inside [aMin, aMax]
      let chain = [];
      let segs = 14;
      for (let k = 0; k <= segs; k++) {
        let s = lerp(-halfLen, halfLen, k / segs);
        let px = mx + s * ca;
        let py = my + s * sa;
        let ang = atan2(py - cy, px - cx);
        let diff = ((ang - aMin) % 360 + 360) % 360;
        let span = ((aMax - aMin) % 360 + 360) % 360;
        if (diff <= span) {
          chain.push([px, py]);
        } else {
          if (chain.length >= 2) {
            drawClippedLine(chain[0][0], chain[0][1], chain[chain.length - 1][0], chain[chain.length - 1][1], bName, col, w);
          }
          chain = [];
        }
      }
      if (chain.length >= 2) {
        drawClippedLine(chain[0][0], chain[0][1], chain[chain.length - 1][0], chain[chain.length - 1][1], bName, col, w);
      }
    }
  }
}

// Render the dun square plot base and corner tractor turnarounds
function drawDunSquarePlot(x1, y1, x2, y2, cx, cy, r, dunPal, dryAngle, seed) {
  let pad = 6.5;
  let sx1 = x1 + pad, sy1 = y1 + pad, sx2 = x2 - pad, sy2 = y2 - pad;
  let sqPts = clipPoly([[sx1, sy1], [sx2, sy1], [sx2, sy2], [sx1, sy2]], -6, -6, 1206, 1206);
  if (sqPts.length < 3) return;

  let poly = new brush.Polygon(sqPts);
  brush.noStroke();
  brush.noHatch();
  poly.wash(dunPal.wash, 115);
  poly.fill(dunPal.base, 42, 0.02, 0.55);

  // Dryland harrowing lines in the dun plot
  brush.set("cpencil", dunPal.base, 0.65);
  brush.hatchStyle("cpencil", dunPal.base, 0.68);
  poly.hatch(4.3, dryAngle, { rand: 0.03 });

  brush.hatchStyle("cpencil", dunPal.light, 0.55);
  poly.hatch(7.4, dryAngle, { rand: 0.04 });

  brush.hatchStyle("2H", dunPal.dark, 0.42);
  poly.hatch(9.5, dryAngle + 90, { rand: 0.04 });
  brush.noHatch();

  // Curved tractor turnaround tracks in the 4 dryland spandrel corners
  let cornerAngles = [-45, 45, 135, 225];
  for (let ca of cornerAngles) {
    for (let k = 1; k <= 4; k++) {
      let rk = r + 3.5 + k * 4.2;
      let span = 24 - k * 3.5;
      let pts = [];
      for (let s = 0; s <= 12; s++) {
        let a = lerp(ca - span, ca + span, s / 12);
        let px = cx + rk * cos(a);
        let py = cy + rk * sin(a);
        if (px > sx1 + 2 && px < sx2 - 2 && py > sy1 + 2 && py < sy2 - 2) {
          pts.push([px, py]);
        }
      }
      if (pts.length >= 2) {
        drawClippedChain(pts, k % 2 === 0 ? "cpencil" : "2H", k % 2 === 0 ? dunPal.light : dunPal.dark, 0.42, 0.25);
      }
    }

    // Dry scrub / weed stipples in the far corner tips
    let cornerDist = r + 26;
    let cornerX = cx + cornerDist * cos(ca);
    let cornerY = cy + cornerDist * sin(ca);
    if (inCanvas(cornerX, cornerY, 5)) {
      for (let m = 0; m < 10; m++) {
        let jx = cornerX + random(-11, 11);
        let jy = cornerY + random(-11, 11);
        if (jx > sx1 + 3 && jx < sx2 - 3 && jy > sy1 + 3 && jy < sy2 - 3 && dist(jx, jy, cx, cy) > r + 5) {
          setStrokeState("cpencil", m % 2 === 0 ? "#6e6944" : dunPal.dark, 0.55);
          brush.line(jx, jy, jx + random(-2.5, 2.5), jy + random(-2.5, 2.5));
        }
      }
    }
  }

  // Crisp field boundary furrow around the dun square plot
  drawClippedChain([[sx1, sy1], [sx2, sy1], [sx2, sy2], [sx1, sy2], [sx1, sy1]], "2H", dunPal.dark, 0.48, 0.05);
}

// Render concentric tower wheel tracks & optional continuous spiral tyre ruts
function drawTyreRuts(cx, cy, r, pal, hasSpiral = false, spiralTurns = 6.5, seed = 0) {
  // 1. Concentric irrigation tower wheel tracks (7 towers along the radius)
  let numTowers = 7;
  for (let t = 1; t <= numTowers; t++) {
    let rt = (t / (numTowers + 0.25)) * r;
    let ptsDark = [];
    let ptsLight = [];
    let steps = 64;
    for (let i = 0; i <= steps; i++) {
      let a = (i / steps) * 360;
      let wob = 0.45 * (noise(cos(a) * 1.5 + t, sin(a) * 1.5 + seed) - 0.5);
      ptsDark.push([cx + (rt + wob) * cos(a), cy + (rt + wob) * sin(a)]);
      ptsLight.push([cx + (rt - 1.15 + wob) * cos(a), cy + (rt - 1.15 + wob) * sin(a)]);
    }
    drawClippedChain(ptsLight, "cpencil", pal.rutLight, 0.38, 0.25);
    drawClippedChain(ptsDark, "2H", pal.rutDark, 0.48, 0.25);
  }

  // 2. Continuous Archimedean spiral tyre ruts (prominent on bare umber & half-tilled plots)
  if (hasSpiral) {
    let totalDeg = spiralTurns * 360;
    let stepDeg = 9;
    let spiralDark1 = [];
    let spiralDark2 = [];
    let spiralRidge = [];

    for (let deg = 0; deg <= totalDeg; deg += stepDeg) {
      let frac = deg / totalDeg;
      let rad = 11 + (r - 15) * frac + 0.9 * sin(deg * 2.5 + seed * 20);
      let ang = deg + seed * 45;
      let ca = cos(ang), sa = sin(ang);
      spiralDark1.push([cx + rad * ca, cy + rad * sa]);
      spiralRidge.push([cx + (rad + 1.35) * ca, cy + (rad + 1.35) * sa]);
      spiralDark2.push([cx + (rad - 2.4) * ca, cy + (rad - 2.4) * sa]);
    }
    drawClippedChain(spiralRidge, "cpencil", pal.rutLight, 0.52, 0.3);
    drawClippedChain(spiralDark1, "2H", pal.rutDark, 0.62, 0.3);
    drawClippedChain(spiralDark2, "2H", pal.dark, 0.45, 0.3);
  }

  // 3. Soft perimeter headland ring
  let rimPts = [];
  for (let i = 0; i <= 72; i++) {
    let a = (i / 72) * 360;
    rimPts.push([cx + r * cos(a), cy + r * sin(a)]);
  }
  drawClippedChain(rimPts, "2H", pal.dark, 0.52, 0.2);
}

// Render the center-pivot pipe, wheeled towers, concrete pad, access road & shadow line
function drawPivotArmAndAccess(cx, cy, r, armAngle, accessDirAngle, isWet = false) {
  // 1. Two-track dirt service lane from section road to center pad
  let roadDist = 184;
  let rx = cx + roadDist * cos(accessDirAngle);
  let ry = cy + roadDist * sin(accessDirAngle);
  let px = cos(accessDirAngle + 90);
  let py = sin(accessDirAngle + 90);

  drawClippedLine(cx, cy, rx, ry, "cpencil", "#dfd0b4", 0.75);
  drawClippedLine(cx + 1.7 * px, cy + 1.7 * py, rx + 1.7 * px, ry + 1.7 * py, "2H", "#6b5338", 0.42);
  drawClippedLine(cx - 1.7 * px, cy - 1.7 * py, rx - 1.7 * px, ry - 1.7 * py, "2H", "#6b5338", 0.42);

  // 2. Center concrete pivot pad
  if (inCanvas(cx, cy, 8)) {
    let padPts = circlePoints(cx, cy, 4.8, 12);
    let padPoly = new brush.Polygon(padPts);
    brush.noStroke();
    brush.noHatch();
    padPoly.wash("#e3dac8", 210);
    drawClippedChain(padPts.concat([padPts[0]]), "2H", "#4d4132", 0.45, 0.1);
  }

  // 3. Pivot arm's shadow line (offset to the North-Northeast)
  let sdx = 3.4, sdy = -3.8;
  let ca = cos(armAngle), sa = sin(armAngle);
  let cPerp = cos(armAngle + 90), sPerp = sin(armAngle + 90);

  let sx1 = cx + sdx, sy1 = cy + sdy;
  let sx2 = cx + (r + 3) * ca + sdx, sy2 = cy + (r + 3) * sa + sdy;

  // Main pipe shadow + bowed truss shadow
  drawClippedLine(sx1, sy1, sx2, sy2, "2H", "#1a2110", 0.68);

  let numTowers = 7;
  for (let t = 1; t <= numTowers; t++) {
    let rt = (t / (numTowers + 0.25)) * r;
    let rPrev = ((t - 1) / (numTowers + 0.25)) * r;
    let rMid = (rt + rPrev) * 0.5;

    // Bowed truss shadow between towers
    let bx1 = cx + rPrev * ca + sdx, by1 = cy + rPrev * sa + sdy;
    let bxm = cx + rMid * ca + sdx + 1.4 * cPerp, bym = cy + rMid * sa + sdy + 1.4 * sPerp;
    let bx2 = cx + rt * ca + sdx, by2 = cy + rt * sa + sdy;
    drawClippedChain([[bx1, by1], [bxm, bym], [bx2, by2]], "2H", "#222b15", 0.35, 0.3);

    // Shadow of wheeled tower base
    let tx = cx + rt * ca + sdx;
    let ty = cy + rt * sa + sdy;
    drawClippedLine(tx - 2.6 * cPerp, ty - 2.6 * sPerp, tx + 2.6 * cPerp, ty + 2.6 * sPerp, "2H", "#151c0c", 0.52);
  }

  // 4. Fine mist spray halo if actively irrigating
  if (isWet) {
    for (let t = 1; t <= numTowers; t++) {
      let rt = (t / (numTowers + 0.25)) * r - 7;
      let mx = cx + rt * ca;
      let my = cy + rt * sa;
      drawClippedLine(mx - 3 * ca, my - 3 * sa, mx + 3 * ca, my + 3 * sa, "cpencil", "#e8ede0", 0.65);
    }
  }

  // 5. The galvanized steel pivot arm pipe & wheeled tower trusses
  let ax2 = cx + (r + 3) * ca;
  let ay2 = cy + (r + 3) * sa;
  drawClippedLine(cx - 0.5 * cPerp, cy - 0.5 * sPerp, ax2 - 0.5 * cPerp, ay2 - 0.5 * sPerp, "2H", "#5d6355", 0.5);
  drawClippedLine(cx, cy, ax2, ay2, "cpencil", "#eceae2", 0.72);
  drawClippedLine(cx + 8 * ca, cy + 8 * sa, ax2 - 12 * ca, ay2 - 12 * sa, "2H", "#ffffff", 0.45);

  for (let t = 1; t <= numTowers; t++) {
    let rt = (t / (numTowers + 0.25)) * r;
    let tx = cx + rt * ca;
    let ty = cy + rt * sa;
    // Wheeled A-frame carrier bar
    drawClippedLine(tx - 2.8 * cPerp, ty - 2.8 * sPerp, tx + 2.8 * cPerp, ty + 2.8 * sPerp, "2H", "#dedcd2", 0.52);
    // Tiny dark wheels at ends of carrier bar
    drawClippedLine(tx - 3.1 * cPerp - 0.8 * ca, ty - 3.1 * sPerp - 0.8 * sa, tx - 3.1 * cPerp + 0.8 * ca, ty - 3.1 * sPerp + 0.8 * sa, "2H", "#2a261f", 0.6);
    drawClippedLine(tx + 3.1 * cPerp - 0.8 * ca, ty + 3.1 * sPerp - 0.8 * sa, tx + 3.1 * cPerp + 0.8 * ca, ty + 3.1 * sPerp + 0.8 * sa, "2H", "#2a261f", 0.6);
  }

  // Center pivot hub cap
  if (inCanvas(cx, cy, 5)) {
    setStrokeState("2H", "#2b261e", 0.7);
    brush.line(cx - 1.2, cy, cx + 1.2, cy);
    brush.line(cx, cy - 1.2, cx, cy + 1.2);
  }
}

// Render the farmstead with windbreak trees, grain bins & metal roof glint
function drawFarmstead(xCorner, yCorner) {
  // Farmstead occupies a ~68x64 px compound in the SE corner of Plot (2, 0)
  let fx = xCorner - 76;
  let fy = yCorner - 72;

  // 1. Gravel compound pad & driveway access to East and South dirt roads
  let yardPts = [
    [fx + 4, fy + 8],
    [xCorner - 6, fy + 8],
    [xCorner - 6, yCorner - 6],
    [fx + 8, yCorner - 6],
    [fx + 4, fy + 26]
  ];
  let yardPoly = new brush.Polygon(yardPts);
  brush.noStroke();
  brush.noHatch();
  yardPoly.wash("#dfd1b8", 170);
  brush.set("cpencil", "#c7b495", 0.55);
  brush.hatchStyle("cpencil", "#c7b495", 0.55);
  yardPoly.hatch(3.2, 0, { rand: 0.04 });
  brush.hatchStyle("2H", "#a38d6d", 0.4);
  yardPoly.hatch(4.5, 90, { rand: 0.04 });
  brush.noHatch();

  // Internal gravel turnaround loop
  let loopPts = circlePoints(fx + 38, fy + 38, 14, 24);
  drawClippedChain(loopPts.concat([loopPts[0]]), "2H", "#8f7858", 0.42, 0.25);
  drawClippedLine(fx + 52, fy + 38, xCorner - 4, fy + 38, "2H", "#856d4d", 0.45);
  drawClippedLine(fx + 38, fy + 52, fx + 38, yCorner - 4, "2H", "#856d4d", 0.45);

  // 2. Main Metal-Roofed Equipment Barn (with bright specular sun glint!)
  let bx = fx + 15, by = fy + 16, bw = 26, bh = 13;
  // Cast shadow (NE)
  let bShadow = new brush.Polygon([
    [bx + 3, by - 3.5],
    [bx + bw + 3.5, by - 3.5],
    [bx + bw + 3.5, by + bh - 3.5],
    [bx + bw, by + bh],
    [bx, by]
  ]);
  brush.noStroke();
  bShadow.wash("#211b12", 185);

  // North roof pitch (shaded cool silver-taupe)
  let roofNorth = new brush.Polygon([
    [bx, by],
    [bx + bw, by],
    [bx + bw, by + bh * 0.48],
    [bx, by + bh * 0.48]
  ]);
  roofNorth.wash("#9ca39e", 210);

  // South roof pitch (blazing specular metal roof glint!)
  let roofSouth = new brush.Polygon([
    [bx, by + bh * 0.48],
    [bx + bw, by + bh * 0.48],
    [bx + bw, by + bh],
    [bx, by + bh]
  ]);
  roofSouth.wash("#ffffff", 245);

  // Roof ribs & brilliant white highlight strokes
  for (let rx = bx + 2; rx < bx + bw; rx += 2.4) {
    drawClippedLine(rx, by, rx, by + bh * 0.48, "2H", "#747a75", 0.35);
    drawClippedLine(rx, by + bh * 0.48, rx, by + bh, "2H", "#ffffff", 0.55);
  }
  // Intense glint core + subtle starburst flare on the ridge
  drawClippedLine(bx + 1, by + bh * 0.5, bx + bw - 1, by + bh * 0.5, "cpencil", "#ffffff", 0.95);
  drawClippedLine(bx + 4, by + bh * 0.68, bx + bw - 3, by + bh * 0.68, "cpencil", "#fffef5", 0.85);
  drawClippedChain([[bx, by], [bx + bw, by], [bx + bw, by + bh], [bx, by + bh], [bx, by]], "2H", "#3d3932", 0.45, 0.05);

  // 3. Secondary Shed / Farmhouse
  let sx = fx + 15, sy = fy + 36, sw = 14, sh = 10;
  let sShadow = new brush.Polygon([
    [sx + 2.5, sy - 2.8],
    [sx + sw + 2.8, sy - 2.8],
    [sx + sw + 2.8, sy + sh - 2.8],
    [sx + sw, sy + sh],
    [sx, sy]
  ]);
  brush.noStroke();
  sShadow.wash("#241d14", 175);

  let sRoof = new brush.Polygon([[sx, sy], [sx + sw, sy], [sx + sw, sy + sh], [sx, sy + sh]]);
  sRoof.wash("#e3e6e1", 220);
  drawClippedLine(sx, sy + sh * 0.5, sx + sw, sy + sh * 0.5, "2H", "#ffffff", 0.7);
  drawClippedChain([[sx, sy], [sx + sw, sy], [sx + sw, sy + sh], [sx, sy + sh], [sx, sy]], "2H", "#453e35", 0.4, 0.05);

  // 4. Row of 4 Cylindrical Silver Grain Silos (with round NE shadows & conical glint)
  for (let i = 0; i < 4; i++) {
    let gx = fx + 54;
    let gy = fy + 15 + i * 9.5;
    let gr = 3.6;

    // Silo shadow
    let shPts = circlePoints(gx + 2.6, gy - 2.6, gr, 14);
    let shPoly = new brush.Polygon(shPts);
    brush.noStroke();
    shPoly.wash("#211a11", 180);

    // Silo body
    let binPts = circlePoints(gx, gy, gr, 16);
    let binPoly = new brush.Polygon(binPts);
    binPoly.wash("#b8bdb8", 225);

    // Sunlit SW crescent & white conical glint
    drawClippedLine(gx - 2.2, gy + 1.2, gx + 0.5, gy - 0.5, "cpencil", "#ffffff", 0.75);
    drawClippedChain(binPts.concat([binPts[0]]), "2H", "#474a45", 0.4, 0.15);
  }

  // 5. L-Shaped Windbreak of Trees (North and West perimeter of farmstead)
  let treeCoords = [];
  for (let tx = fx + 4; tx <= fx + 62; tx += 5.2) treeCoords.push([tx, fy + 6 + random(-1.2, 1.2)]);
  for (let ty = fy + 11; ty <= fy + 58; ty += 5.2) treeCoords.push([fx + 4 + random(-1.2, 1.2), ty]);

  // Tree shadows first
  for (let tc of treeCoords) {
    let tr = random(3.2, 4.4);
    let sp = circlePoints(tc[0] + 2.8, tc[1] - 2.8, tr, 10);
    let sPoly = new brush.Polygon(sp);
    brush.noStroke();
    sPoly.wash("#1c2112", 165);
  }
  // Tree crowns
  for (let tc of treeCoords) {
    let tr = random(3.2, 4.5);
    let tp = circlePoints(tc[0], tc[1], tr, 12);
    let tPoly = new brush.Polygon(tp);
    brush.noStroke();
    tPoly.wash("#384723", 210);
    setStrokeState("cpencil", "#566b36", 0.55);
    brush.line(tc[0] - 1.8, tc[1] + 1.2, tc[0] + 0.8, tc[1] - 0.8);
    setStrokeState("2H", "#222b14", 0.45);
    brush.line(tc[0] + 0.5, tc[1] - 1.5, tc[0] + 2.2, tc[1] + 1.0);
  }
}

// Render small grain-bin pad in NE corner of Plot (1, 0)
function drawCornerGrainBins(xCorner, yCorner) {
  let bx = xCorner - 38, by = yCorner + 10;
  let padPts = [[bx, by], [xCorner - 7, by], [xCorner - 7, by + 28], [bx, by + 28]];
  let padPoly = new brush.Polygon(padPts);
  brush.noStroke();
  padPoly.wash("#dfd1b8", 165);
  drawClippedChain(padPts.concat([padPts[0]]), "2H", "#8f7858", 0.4, 0.05);

  for (let i = 0; i < 3; i++) {
    let gx = bx + 9 + i * 8.5;
    let gy = by + 14;
    let gr = 3.3;
    let shPoly = new brush.Polygon(circlePoints(gx + 2.2, gy - 2.2, gr, 12));
    brush.noStroke();
    shPoly.wash("#241c12", 170);
    let binPts = circlePoints(gx, gy, gr, 14);
    let binPoly = new brush.Polygon(binPts);
    binPoly.wash("#c4c9c4", 220);
    drawClippedLine(gx - 1.8, gy + 1.0, gx + 0.5, gy - 0.5, "cpencil", "#ffffff", 0.7);
    drawClippedChain(binPts.concat([binPts[0]]), "2H", "#454743", 0.38, 0.15);
  }
}

// Render clay-lined tailwater retention pond in NW corner of Plot (0, 2)
function drawTailwaterPond(xCorner, yCorner) {
  let px = xCorner + 9, py = yCorner + 9, pw = 36, ph = 22;
  let bermPts = [[px, py], [px + pw, py], [px + pw, py + ph], [px, py + ph]];
  let bermPoly = new brush.Polygon(bermPts);
  brush.noStroke();
  bermPoly.wash("#e3d4b9", 180);

  let waterPts = [[px + 3.5, py + 3.5], [px + pw - 3.5, py + 3.5], [px + pw - 3.5, py + ph - 3.5], [px + 3.5, py + ph - 3.5]];
  let waterPoly = new brush.Polygon(waterPts);
  waterPoly.wash("#3b4a32", 200);
  brush.set("cpencil", "#2b3823", 0.55);
  brush.hatchStyle("cpencil", "#2b3823", 0.55);
  waterPoly.hatch(2.2, 0, { rand: 0.02 });
  brush.hatchStyle("2H", "#5d6e4e", 0.4);
  waterPoly.hatch(4.5, 0, { rand: 0.03 });
  brush.noHatch();

  drawClippedChain(bermPts.concat([bermPts[0]]), "2H", "#7d6849", 0.45, 0.05);
  drawClippedChain(waterPts.concat([waterPts[0]]), "2H", "#26301e", 0.45, 0.05);
}

// Render the grid of dirt section roads and intersection aprons
function drawDirtRoadGrid() {
  let coords = [48, 416, 784, 1152];

  // 1. Base caliche road washes
  brush.noStroke();
  brush.noHatch();
  for (let x of coords) {
    let rPoly = new brush.Polygon([[x - 5.5, 0], [x + 5.5, 0], [x + 5.5, 1200], [x - 5.5, 1200]]);
    rPoly.wash("#e4d4b8", 190);
  }
  for (let y of coords) {
    let rPoly = new brush.Polygon([[0, y - 5.5], [1200, y - 5.5], [1200, y + 5.5], [0, y + 5.5]]);
    rPoly.wash("#e4d4b8", 190);
  }

  // 2. Vertical dirt roads: ditches, graded crown & dual wheel tracks
  for (let x of coords) {
    for (let segY = 0; segY < 1200; segY += 120) {
      let y1 = segY, y2 = min(1200, segY + 120);
      // Weedy roadside ditches
      drawClippedLine(x - 5.8, y1, x - 5.8, y2, "cpencil", "#595034", 0.62);
      drawClippedLine(x + 5.8, y1, x + 5.8, y2, "cpencil", "#595034", 0.62);
      drawClippedLine(x - 4.8, y1, x - 4.8, y2, "2H", "#786444", 0.45);
      drawClippedLine(x + 4.8, y1, x + 4.8, y2, "2H", "#786444", 0.45);
      // Graded gravel shoulders & center crown
      drawClippedLine(x - 3.0, y1, x - 3.0, y2, "cpencil", "#ebdCC2", 0.65);
      drawClippedLine(x + 3.0, y1, x + 3.0, y2, "cpencil", "#ebdCC2", 0.65);
      drawClippedLine(x, y1, x, y2, "cpencil", "#f5ebd6", 0.6);
      // Dual tyre ruts
      drawClippedLine(x - 1.6, y1, x - 1.6, y2, "2H", "#8c7250", 0.45);
      drawClippedLine(x + 1.6, y1, x + 1.6, y2, "2H", "#8c7250", 0.45);
    }
  }

  // 3. Horizontal dirt roads: ditches, graded crown & dual wheel tracks
  for (let y of coords) {
    for (let segX = 0; segX < 1200; segX += 120) {
      let x1 = segX, x2 = min(1200, segX + 120);
      drawClippedLine(x1, y - 5.8, x2, y - 5.8, "cpencil", "#595034", 0.62);
      drawClippedLine(x1, y + 5.8, x2, y + 5.8, "cpencil", "#595034", 0.62);
      drawClippedLine(x1, y - 4.8, x2, y - 4.8, "2H", "#786444", 0.45);
      drawClippedLine(x1, y + 4.8, x2, y + 4.8, "2H", "#786444", 0.45);

      drawClippedLine(x1, y - 3.0, x2, y - 3.0, "cpencil", "#ebdCC2", 0.65);
      drawClippedLine(x1, y + 3.0, x2, y + 3.0, "cpencil", "#ebdCC2", 0.65);
      drawClippedLine(x1, y, x2, y, "cpencil", "#f5ebd6", 0.6);

      drawClippedLine(x1, y - 1.6, x2, y - 1.6, "2H", "#8c7250", 0.45);
      drawClippedLine(x1, y + 1.6, x2, y + 1.6, "2H", "#8c7250", 0.45);
    }
  }

  // 4. Swept gravel turning aprons at all 16 road intersections
  for (let ix of coords) {
    for (let iy of coords) {
      let centerPoly = new brush.Polygon(circlePoints(ix, iy, 8.5, 16));
      brush.noStroke();
      centerPoly.wash("#eadbc0", 210);

      let quadrants = [
        [1, 1, 180, 270],
        [-1, 1, 270, 360],
        [-1, -1, 0, 90],
        [1, -1, 90, 180]
      ];
      for (let q of quadrants) {
        let qx = ix + q[0] * 11;
        let qy = iy + q[1] * 11;
        let arcTrack = [];
        let arcDitch = [];
        for (let s = 0; s <= 8; s++) {
          let a = lerp(q[2], q[3], s / 8);
          arcTrack.push([qx + 9.2 * cos(a), qy + 9.2 * sin(a)]);
          arcDitch.push([qx + 5.5 * cos(a), qy + 5.5 * sin(a)]);
        }
        drawClippedChain(arcTrack, "2H", "#8c7250", 0.42, 0.25);
        drawClippedChain(arcDitch, "2H", "#595034", 0.45, 0.25);
      }
    }
  }
}

// Master dispatcher for each cell (gx, gy) in the 5x5 grid
function drawPlotCell(gx, gy) {
  let x1 = GRID_X[gx], x2 = GRID_X[gx + 1];
  let y1 = GRID_Y[gy], y2 = GRID_Y[gy + 1];
  let cx = (x1 + x2) * 0.5;
  let cy = (y1 + y2) * 0.5;
  let r = 168.5;
  let seed = gx * 19 + gy * 37;

  let isInterior = gx >= 1 && gx <= 3 && gy >= 1 && gy <= 3;
  let colIdx = gx - 1;
  let rowIdx = gy - 1;

  // Pick dun dryland palette & harrowing angle
  let dunPal = PALETTE.dun[(gx * 3 + gy * 5) % PALETTE.dun.length];
  let dryAngles = [0, 90, 45, -45];
  let dryAngle = dryAngles[(gx + gy * 2) % 4];

  // Slight offset for Plot (2,0) and Plot (0,2) to make room for farmstead & tailwater pond
  if (isInterior && colIdx === 2 && rowIdx === 0) {
    cx -= 5;
    cy -= 5;
    r = 164;
  } else if (isInterior && colIdx === 0 && rowIdx === 2) {
    cx += 3.5;
    cy += 3.5;
    r = 166;
  }

  // 1. Draw the dun square plot base and corner turnarounds
  drawDunSquarePlot(x1, y1, x2, y2, cx, cy, r, dunPal, dryAngle, seed);

  // 2. If this is an outer border cell (bleeding off the canvas edges), render its circle cleanly
  if (!isInterior) {
    let borderStage = (gx * 7 + gy * 11) % 4;
    let bPal = borderStage === 0 ? PALETTE.sapGreen :
               borderStage === 1 ? PALETTE.olive :
               borderStage === 2 ? PALETTE.straw : PALETTE.umber;
    let bRowAngle = (gx + gy) % 2 === 0 ? 0 : 90;
    renderCropPolygon(circlePoints(cx, cy, r, 64), bPal, bRowAngle, 3.3, 0.25);
    drawPlanterStreaks(cx, cy, r, bRowAngle, bPal, seed, null, null, 6.0);
    drawTyreRuts(cx, cy, r, bPal, borderStage === 3, 6.0, seed);
    return;
  }

  // 3. Render the 9 Hero Interior Plots (colIdx 0..2, rowIdx 0..2)
  if (colIdx === 0 && rowIdx === 0) {
    // PLOT (0, 0): Lush Sap Green with active dark-damp irrigation sector behind pivot arm
    renderCropPolygon(sectorPoints(cx, cy, r, 195, 495, 56), PALETTE.sapGreen, 0, 3.1, 0.32);
    renderCropPolygon(sectorPoints(cx, cy, r, 135, 195, 20), PALETTE.sapWet, 0, 3.0, 0.35);
    drawPlanterStreaks(cx, cy, r, 0, PALETTE.sapGreen, seed, 195, 495, 4.5);
    drawPlanterStreaks(cx, cy, r, 0, PALETTE.sapWet, seed + 5, 135, 195, 4.5);
    drawTyreRuts(cx, cy, r, PALETTE.sapGreen, false, 6, seed);
    drawPivotArmAndAccess(cx, cy, r, 135, 270, true);

  } else if (colIdx === 1 && rowIdx === 0) {
    // PLOT (1, 0): Mature Olive Green with vertical rows & radial moisture wedge
    renderCropPolygon(sectorPoints(cx, cy, r, 255, 565, 56), PALETTE.olive, 90, 3.1, 0.32);
    renderCropPolygon(sectorPoints(cx, cy, r, 205, 255, 18), PALETTE.oliveDeep, 90, 3.0, 0.35);
    drawPlanterStreaks(cx, cy, r, 90, PALETTE.olive, seed, 255, 565, 4.5);
    drawPlanterStreaks(cx, cy, r, 90, PALETTE.oliveDeep, seed + 7, 205, 255, 4.5);
    drawTyreRuts(cx, cy, r, PALETTE.olive, false, 6, seed);
    drawCornerGrainBins(x2, y1);
    drawPivotArmAndAccess(cx, cy, r, 205, 180, true);

  } else if (colIdx === 2 && rowIdx === 0) {
    // PLOT (2, 0): Bare Umber with prominent spiral tyre ruts + emerging sap wedge + Farmstead
    renderCropPolygon(circlePoints(cx, cy, r, 72), PALETTE.umber, 45, 3.1, 0.36);
    // Faint emerging sap green seedlings in a 75-degree sector
    let emergePts = clipPoly(sectorPoints(cx, cy, r * 0.92, -25, 50, 24));
    if (emergePts.length >= 3) {
      let ePoly = new brush.Polygon(emergePts);
      brush.set("cpencil", PALETTE.sapGreen.mid, 0.55);
      brush.hatchStyle("cpencil", PALETTE.sapGreen.mid, 0.55);
      ePoly.hatch(4.8, 45, { rand: 0.04 });
      brush.noHatch();
    }
    drawPlanterStreaks(cx, cy, r, 45, PALETTE.umber, seed, null, null, 4.6);
    drawTyreRuts(cx, cy, r, PALETTE.umber, true, 6.8, seed);
    drawFarmstead(x2, y2);
    drawPivotArmAndAccess(cx, cy, r, 312, 270, false);

  } else if (colIdx === 0 && rowIdx === 1) {
    // PLOT (0, 1): Harvested Straw with golden windrows & unharvested northern olive-gold strip
    renderCropPolygon(circlePoints(cx, cy, r, 72), PALETTE.straw, 0, 3.1, 0.28);
    // Northern unharvested chord sector (angles 225 to 315)
    let uncutPts = [];
    for (let i = 0; i <= 28; i++) {
      let a = lerp(220, 320, i / 28);
      uncutPts.push([cx + r * cos(a), cy + r * sin(a)]);
    }
    renderCropPolygon(uncutPts, PALETTE.strawUncut, 0, 3.0, 0.35);

    // Combine harvester windrows (bright golden straw lines + shadow lines)
    drawPlanterStreaks(cx, cy, r, 0, PALETTE.straw, seed, null, null, 4.2);
    for (let dy = -r * 0.62; dy <= r - 8; dy += 8.5) {
      let hl = sqrt(max(0, r * r - dy * dy)) - 4;
      if (hl > 10) {
        drawClippedLine(cx - hl, cy + dy, cx + hl, cy + dy, "cpencil", "#f2df9e", 0.72);
        drawClippedLine(cx - hl, cy + dy + 1.1, cx + hl, cy + dy + 1.1, "2H", "#7d5b16", 0.42);
      }
    }
    drawTyreRuts(cx, cy, r, PALETTE.straw, false, 6, seed);
    drawPivotArmAndAccess(cx, cy, r, 180, 180, false);

  } else if (colIdx === 1 && rowIdx === 1) {
    // PLOT (1, 1): Centerpiece Multi-Stage Split Pivot (Sap Green + Olive + Bare Umber & Straw)
    // Sector 1 (-45 to 115): Lush Sap Green (horizontal rows)
    renderCropPolygon(sectorPoints(cx, cy, r, -45, 115, 36), PALETTE.sapGreen, 0, 3.0, 0.32);
    drawPlanterStreaks(cx, cy, r, 0, PALETTE.sapGreen, seed, -45, 115, 4.4);

    // Sector 2 (115 to 230): Deep Olive & Sage (vertical rows)
    renderCropPolygon(sectorPoints(cx, cy, r, 115, 230, 30), PALETTE.olive, 90, 3.0, 0.32);
    drawPlanterStreaks(cx, cy, r, 90, PALETTE.olive, seed + 11, 115, 230, 4.4);

    // Sector 3 (230 to 275): Harvested Straw wedge (-45 deg rows)
    renderCropPolygon(sectorPoints(cx, cy, r, 230, 275, 16), PALETTE.straw, -45, 3.1, 0.28);
    drawPlanterStreaks(cx, cy, r, -45, PALETTE.straw, seed + 23, 230, 275, 4.5);

    // Sector 4 (275 to 315): Bare Umber wedge (-45 deg rows)
    renderCropPolygon(sectorPoints(cx, cy, r, 275, 315, 16), PALETTE.umber, -45, 3.1, 0.35);
    drawPlanterStreaks(cx, cy, r, -45, PALETTE.umber, seed + 31, 275, 315, 4.5);

    // Crisp radial sector seams
    for (let sa of [-45, 115, 230, 275]) {
      drawClippedLine(cx, cy, cx + r * cos(sa), cy + r * sin(sa), "2H", "#382f1d", 0.48);
    }

    drawTyreRuts(cx, cy, r, PALETTE.olive, true, 5.5, seed);
    drawPivotArmAndAccess(cx, cy, r, 115, 90, false);

  } else if (colIdx === 2 && rowIdx === 1) {
    // PLOT (2, 1): Striated Young Sap Green over Warm Sienna/Umber Ridges (-45 deg rows)
    renderCropPolygon(circlePoints(cx, cy, r, 72), PALETTE.sapYoung, -45, 3.2, 0.28);
    // Outer ring of denser sap green (R = 128..168)
    for (let q = 0; q < 6; q++) {
      let a1 = q * 60, a2 = (q + 1) * 60;
      renderCropPolygon(annulusSectorPoints(cx, cy, 128, r, a1, a2, 14), PALETTE.sapGreen, -45, 3.1, 0.3);
    }
    drawPlanterStreaks(cx, cy, r, -45, PALETTE.sapGreen, seed, null, null, 4.2);
    drawTyreRuts(cx, cy, r, PALETTE.sapYoung, false, 6, seed);
    drawPivotArmAndAccess(cx, cy, r, 28, 0, false);

  } else if (colIdx === 0 && rowIdx === 2) {
    // PLOT (0, 2): Deep Olive Concentric Cutting Rings + NW Tailwater Pond
    // Outer band (R = 126..166): Mid Olive
    renderCropPolygon(circlePoints(cx, cy, r, 72), PALETTE.olive, 90, 3.1, 0.3);
    // Middle band (R = 72..126): Sunlit Sage-Olive
    renderCropPolygon(circlePoints(cx, cy, 126, 60), PALETTE.oliveSage, 90, 3.1, 0.3);
    // Inner core (R = 0..72): Deep Dark Olive
    renderCropPolygon(circlePoints(cx, cy, 72, 48), PALETTE.oliveDeep, 90, 3.0, 0.35);

    drawPlanterStreaks(cx, cy, r, 90, PALETTE.olive, seed, null, null, 4.5);
    drawTyreRuts(cx, cy, r, PALETTE.olive, false, 6, seed);
    drawTailwaterPond(x1, y1);
    drawPivotArmAndAccess(cx, cy, r, 62, 180, false);

  } else if (colIdx === 1 && rowIdx === 2) {
    // PLOT (1, 2): Split Half Bare Umber (with Spiral Ruts) & Half Lush Sap Green
    renderCropPolygon(sectorPoints(cx, cy, r, -85, 95, 36), PALETTE.umber, 0, 3.1, 0.35);
    renderCropPolygon(sectorPoints(cx, cy, r, 95, 275, 36), PALETTE.sapGreen, 0, 3.1, 0.32);

    drawPlanterStreaks(cx, cy, r, 0, PALETTE.umber, seed, -85, 95, 4.4);
    drawPlanterStreaks(cx, cy, r, 0, PALETTE.sapGreen, seed + 9, 95, 275, 4.4);

    drawClippedLine(cx + r * cos(-85), cy + r * sin(-85), cx + r * cos(95), cy + r * sin(95), "2H", "#3b2816", 0.5);
    drawTyreRuts(cx, cy, r, PALETTE.umber, true, 6.5, seed);
    drawPivotArmAndAccess(cx, cy, r, 198, 270, false);

  } else if (colIdx === 2 && rowIdx === 2) {
    // PLOT (2, 2): Sap Green Core with Swathed Harvested Straw Outer Ring & Round Hay Bales
    renderCropPolygon(circlePoints(cx, cy, r, 72), PALETTE.straw, 90, 3.1, 0.28);
    // Concentric swather windrows in the outer straw ring (R = 132..168)
    for (let rw = 136; rw <= r - 3; rw += 6.5) {
      let wPts = circlePoints(cx, cy, rw, 64);
      drawClippedChain(wPts.concat([wPts[0]]), "cpencil", "#edd696", 0.6, 0.25);
      let sPts = circlePoints(cx, cy, rw + 1.1, 64);
      drawClippedChain(sPts.concat([sPts[0]]), "2H", "#87631c", 0.4, 0.25);
    }

    // Lush Sap Green inner circle (R = 132)
    renderCropPolygon(circlePoints(cx, cy, 132, 64), PALETTE.sapGreen, 90, 3.0, 0.32);
    drawPlanterStreaks(cx, cy, 132, 90, PALETTE.sapGreen, seed, null, null, 4.3);

    // Tiny round hay bales scattered along the outer harvested ring
    for (let b = 0; b < 28; b++) {
      let ba = b * 12.8 + random(-3, 3);
      let br = random(137, r - 5);
      let bx = cx + br * cos(ba);
      let by = cy + br * sin(ba);
      setStrokeState("2H", "#3d2b0c", 0.85);
      brush.line(bx + 1.1, by - 1.1, bx + 2.1, by - 1.5);
      setStrokeState("cpencil", "#f5e1a4", 0.95);
      brush.line(bx - 0.8, by, bx + 0.8, by);
    }

    drawTyreRuts(cx, cy, r, PALETTE.sapGreen, false, 6, seed);
    drawPivotArmAndAccess(cx, cy, r, 338, 90, false);
  }
}

