// ============================================================================
// SAFE BRUSH WRAPPERS (Prevent degenerate zero-length tangent NaNs)
// ============================================================================
function safeLine(x1, y1, x2, y2) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  if (dx * dx + dy * dy < 1.2) return;
  brush.line(x1, y1, x2, y2);
}

function safeSpline(pts, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    let dx = pts[i][0] - prev[0];
    let dy = pts[i][1] - prev[1];
    if (dx * dx + dy * dy >= 2.2) {
      clean.push(pts[i]);
    }
  }
  if (clean.length === 2) {
    safeLine(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  } else if (clean.length >= 3) {
    brush.spline(clean, curvature);
  }
}

// ============================================================================
// COLOR & MATH UTILITIES
// ============================================================================
function hexToRgb(hex) {
  let c = hex.replace("#", "");
  let n = parseInt(c, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function rgbToHex(r, g, b) {
  let cl = (v) => Math.max(0, Math.min(255, Math.round(v)));
  return (
    "#" +
    ((1 << 24) + (cl(r) << 16) + (cl(g) << 8) + cl(b))
      .toString(16)
      .slice(1)
  );
}

function lerpHex(h1, h2, t) {
  let u = Math.max(0, Math.min(1, t));
  let a = hexToRgb(h1);
  let b = hexToRgb(h2);
  return rgbToHex(
    a[0] + (b[0] - a[0]) * u,
    a[1] + (b[1] - a[1]) * u,
    a[2] + (b[2] - a[2]) * u
  );
}

function paletteRamp(stops, t) {
  let u = Math.max(0, Math.min(1, t));
  let scaled = u * (stops.length - 1);
  let idx = Math.min(stops.length - 2, Math.floor(scaled));
  let f = scaled - idx;
  return lerpHex(stops[idx], stops[idx + 1], f);
}

function norm3(x, y, z) {
  let l = Math.hypot(x, y, z) || 1;
  return [x / l, y / l, z / l];
}

