// ============================================================================
// DIRECTIONAL WINDOW LIGHT & 3D SURFACE SHADING ENGINE
// ============================================================================
// Window light streams from upper-left and front
const LIGHT_DIR = norm3(-0.62, -0.52, 0.59);
const VIEW_DIR = [0, 0, 1];
const HALF_DIR = norm3(
  LIGHT_DIR[0] + VIEW_DIR[0],
  LIGHT_DIR[1] + VIEW_DIR[1],
  LIGHT_DIR[2] + VIEW_DIR[2]
);

function getWindowBeam(x, y) {
  // Diagonal beam coming from upper-left (0, 150) across the armrest & cushion
  let proj = (x - 180) * 0.52 + (y - 320) * 0.42;
  let cross = (x - 320) * -0.45 + (y - 520) * 0.89;
  let distFalloff = constrain(1.12 - proj / 1150, 0.25, 1.08);
  let beamCore = Math.exp(-(cross * cross) / (560 * 560));
  // Subtle window mullion modulation in the upper right
  let mullion = 1.0 - 0.12 * Math.pow(Math.sin((x + y * 0.65) * 0.008), 4);
  return constrain((0.32 + 0.76 * beamCore) * distFalloff * mullion, 0.18, 1.12);
}

// Compute full hyperreal leather shading value [0..1] + specular [0..1]
function computeLeatherShade(pt, nx, ny, nz, ao, distToSeam, leather, patchSeed) {
  let x = pt[0];
  let y = pt[1];

  // Quilted puff normal perturbation near seams (d < 26px)
  let puffFactor = constrain(1.0 - distToSeam / 26.0, 0, 1);
  // Seam groove darkens right at the stitch line (d < 6px), puffs out at d ~ 8..22px
  let seamGroove = constrain(distToSeam / 6.5, 0.28, 1.0);
  let seamCrown = Math.sin(puffFactor * Math.PI) * 0.18;

  let n = norm3(nx, ny - seamCrown * 0.45, nz);
  let ndotl = Math.max(0, n[0] * LIGHT_DIR[0] + n[1] * LIGHT_DIR[1] + n[2] * LIGHT_DIR[2]);
  let ndotv = Math.max(0.05, n[2]);
  let ndoth = Math.max(0, n[0] * HALF_DIR[0] + n[1] * HALF_DIR[1] + n[2] * HALF_DIR[2]);

  let beam = getWindowBeam(x, y);

  // Diffuse + wrap lighting for rich translucent leather subsurface scatter
  let wrap = Math.max(0, (n[0] * LIGHT_DIR[0] + n[1] * LIGHT_DIR[1] + n[2] * LIGHT_DIR[2] + 0.35) / 1.35);
  let diffuse = (ndotl * 0.72 + wrap * 0.28) * beam;

  // Specular wear sheen
  let spec = Math.pow(ndoth, leather.specPower) * leather.specStrength * beam * seamGroove;

  // Suede special physics: velvety Fresnel grazing bloom + brushed nap mottled directionality
  let fresnel = 0;
  if (leather.id === "suede") {
    fresnel = Math.pow(1.0 - ndotv, 1.8) * 0.38 * beam;
    let napNoise = noise(x * 0.018 + patchSeed, y * 0.018 + patchSeed) - 0.5;
    diffuse = constrain(diffuse + napNoise * 0.22 + fresnel, 0.05, 0.96);
  }

  // Patent leather special physics: dark glossy base with sudden high-contrast window reflections
  if (leather.id === "patent") {
    let baseTone = constrain(diffuse * 0.42 * ao * seamGroove + 0.04, 0.02, 0.52);
    let sharpSpec = Math.pow(ndoth, 38) * 1.35 * beam * seamGroove;
    let secSpec = Math.pow(ndoth, 12) * 0.35 * beam * seamGroove;
    let total = constrain(baseTone + secSpec + sharpSpec, 0.02, 1.0);
    return { tone: total, spec: sharpSpec, diffuse: diffuse, ao: ao * seamGroove, beam: beam };
  }

  // Pull-up leather effect (crowns stretched over high curvature lighten & warm)
  let pullUpBoost = Math.pow(constrain(ndotv * beam, 0, 1), 2.2) * leather.pullUp * seamGroove;

  let tone = constrain(
    (0.08 + diffuse * 0.68 + pullUpBoost + seamCrown * 0.14 + spec * 0.42) * ao * seamGroove,
    0.03,
    0.99
  );

  return { tone: tone, spec: spec, diffuse: diffuse, ao: ao * seamGroove, beam: beam };
}

// ============================================================================
// 3D PARAMETRIC ANATOMICAL ZONES OF THE CLUB ARMCHAIR
// ============================================================================
// Each zone maps (u, v) in [0, 1]^2 -> { x, y, nx, ny, nz, ao }

function evalZone(zoneId, u, v) {
  u = constrain(u, 0, 1);
  v = constrain(v, 0, 1);

  if (zoneId === "backrest") {
    // Sweeps from behind the armrest (left) across to top-right
    let xTop = lerp(370, 1245, u);
    let yTop = lerp(175, -45, u) - Math.sin(u * Math.PI) * 38;
    let xBot = lerp(472, 1245, u);
    let yBot = lerp(618, 690, u) + Math.sin(u * Math.PI) * 18;

    let pillow = Math.sin(u * Math.PI * 0.92) * Math.sin(v * Math.PI);
    // Subtle vertical channel tufting waves in the plush backrest
    let channelWave = Math.sin(u * Math.PI * 3.5) * Math.sin(v * Math.PI) * 12;

    let x = lerp(xTop, xBot, v) - pillow * 22;
    let y = lerp(yTop, yBot, v) - pillow * 16 + channelWave;

    let nx = -0.26 - Math.cos(u * Math.PI * 0.9) * 0.22 + Math.cos(u * Math.PI * 3.5) * 0.12;
    let ny = -0.25 + (v - 0.42) * 0.95;
    let nz = 0.82 + pillow * 0.25;
    let n = norm3(nx, ny, nz);

    // Crevice shadow behind armrest (u -> 0) and above seat cushion (v -> 1)
    let aoArm = constrain(0.32 + u * 2.8, 0.32, 1.0);
    let aoSeat = constrain(0.28 + (1 - v) * 3.2, 0.28, 1.0);
    let ao = aoArm * aoSeat;

    return { x, y, nx: n[0], ny: n[1], nz: n[2], ao };
  }

  if (zoneId === "apron") {
    // Lower front skirt below seat cushion and armrest scroll
    let xTop, yTop, xBot, yBot;
    if (u < 0.28) {
      let t = u / 0.28;
      xTop = lerp(92, 395, t);
      yTop = lerp(918, 995, t);
      xBot = lerp(115, 405, t);
      yBot = lerp(1090, 1165, t);
    } else {
      let t = (u - 0.28) / 0.72;
      xTop = lerp(395, 1245, t);
      yTop = lerp(995, 1085, t);
      xBot = lerp(405, 1245, t);
      yBot = lerp(1165, 1240, t);
    }
    let bulge = Math.sin(v * Math.PI) * 10;
    let x = lerp(xTop, xBot, v) - bulge * 0.3;
    let y = lerp(yTop, yBot, v);

    let nx = u < 0.28 ? -0.35 : -0.12;
    let ny = (v - 0.35) * 0.75;
    let nz = 0.88;
    let n = norm3(nx, ny, nz);
    let aoTop = constrain(0.25 + v * 3.0, 0.25, 1.0);
    let aoBot = constrain(0.45 + (1 - v) * 2.2, 0.45, 1.0);
    return { x, y, nx: n[0], ny: n[1], nz: n[2], ao: aoTop * aoBot };
  }

  if (zoneId === "seatTop") {
    // Deep sunken plush seat cushion top
    let xBack = lerp(472, 1245, u);
    let yBack = lerp(614, 686, u);
    let xFront = lerp(388, 1245, u);
    let yFront = lerp(848, 932, u) - Math.sin(u * Math.PI * 0.85) * 24;

    // Worn saddle depression in the middle of the seat
    let saddle = Math.sin(u * Math.PI * 0.9) * Math.sin(v * Math.PI);
    let frontCrown = Math.pow(v, 1.6) * Math.sin(u * Math.PI * 0.85);

    let x = lerp(xBack, xFront, v);
    let y = lerp(yBack, yFront, v) + saddle * 18 - frontCrown * 14;

    // Normal points mostly up toward the window light, dipping into the saddle
    let nx = -0.18 - Math.cos(u * Math.PI) * 0.22;
    let ny = -0.78 + (v - 0.65) * 0.45 + Math.cos(v * Math.PI) * 0.15;
    let nz = 0.56 + frontCrown * 0.25;
    let n = norm3(nx, ny, nz);

    // Deep crevice AO where seat tucks under backrest (v=0) and armrest (u=0)
    let aoBack = constrain(0.22 + v * 3.4, 0.22, 1.0);
    let aoArm = constrain(0.24 + u * 3.6, 0.24, 1.0);
    return { x, y, nx: n[0], ny: n[1], nz: n[2], ao: aoBack * aoArm };
  }

  if (zoneId === "seatFront") {
    // Plump rounded bullnose front bolster of the seat cushion
    let xTop = lerp(388, 1245, u);
    let yTop = lerp(848, 932, u) - Math.sin(u * Math.PI * 0.85) * 24;
    let xBot = lerp(396, 1245, u);
    let yBot = lerp(1002, 1086, u);

    let roll = Math.sin(v * Math.PI);
    let x = lerp(xTop, xBot, v) - roll * 14;
    let y = lerp(yTop, yBot, v);

    let angle = (v - 0.38) * 155; // Rotates from facing up-front to down-under
    let ny = Math.sin((angle * Math.PI) / 180);
    let nz = Math.cos((angle * Math.PI) / 180);
    let nx = -0.14 - (1 - u) * 0.18;
    let n = norm3(nx, ny, nz);

    let aoArm = constrain(0.32 + u * 4.2, 0.32, 1.0);
    let aoBot = constrain(0.28 + (1 - v) * 2.8, 0.28, 1.0);
    return { x, y, nx: n[0], ny: n[1], nz: n[2], ao: aoArm * aoBot };
  }

  if (zoneId === "armBarrel") {
    // Voluptuous cylindrical club armrest sweeping from front scroll (v=0) to backrest (v=1)
    // u wraps over the cylinder cross-section from outer-left (u=0) over top crest (u=0.42) to inner seat tuck (u=1)
    let theta = lerp(-175, 42, u) * (Math.PI / 180); // Cross-section angle

    // Spine center of the cylinder at v=0 (front scroll) and v=1 (backrest)
    let cx0 = 240, cy0 = 595, rx0 = 202, ry0 = 205;
    let cx1 = 445, cy1 = 395, rx1 = 105, ry1 = 215;

    let vCurve = Math.pow(v, 0.92);
    let cx = lerp(cx0, cx1, vCurve);
    let cy = lerp(cy0, cy1, vCurve) - Math.sin(v * Math.PI) * 28;
    let rx = lerp(rx0, rx1, vCurve) + Math.sin(v * Math.PI) * 18;
    let ry = lerp(ry0, ry1, vCurve);

    let x = cx + Math.cos(theta) * rx;
    let y = cy + Math.sin(theta) * ry;

    // Pull inner-bottom edge (u -> 1) smoothly into the seat-armrest crease
    if (u > 0.68) {
      let t = (u - 0.68) / 0.32;
      let creaseX = lerp(395, 482, v);
      let creaseY = lerp(835, 616, v);
      x = lerp(x, creaseX, t * t * 0.85);
      y = lerp(y, creaseY, t * 0.78);
    }

    // 3D cylindrical surface normal
    let nx = Math.cos(theta) * 0.88 - 0.15 * (1 - v);
    let ny = Math.sin(theta) * 0.92 - 0.22;
    let nz = 0.48 + Math.sin(u * Math.PI) * 0.38 - v * 0.15;
    let n = norm3(nx, ny, nz);

    // Ambient occlusion in the inner seat tuck (u -> 1) and backrest junction (v -> 1)
    let aoInner = u > 0.72 ? constrain(1.0 - ((u - 0.72) / 0.28) * 0.75, 0.22, 1.0) : 1.0;
    let aoBack = v > 0.85 ? constrain(1.0 - ((v - 0.85) / 0.15) * 0.45, 0.55, 1.0) : 1.0;

    return { x, y, nx: n[0], ny: n[1], nz: n[2], ao: aoInner * aoBack };
  }

  if (zoneId === "armFace") {
    // Iconic foreground scrolled armrest face (left foreground focal point)
    // Parameterized over [0,1]^2 with scrolled mushroom-cap top and tapered post bottom
    let cx = 238;
    let cy = 595;

    // Map (u, v) in [0, 1]^2 into the scroll silhouette
    // Top half (v < 0.65) is the wide rounded scroll head; bottom (v >= 0.65) tapers into the post
    let uCentered = (u - 0.5) * 2.0; // [-1, 1]
    let vCentered = (v - 0.44) * 2.0;

    // Width profile as a function of v
    let halfWidth;
    if (v < 0.52) {
      // Upper circular dome of the scroll
      let t = constrain(v / 0.52, 0, 1);
      halfWidth = 42 + Math.sin(t * Math.PI * 0.68) * 162;
    } else {
      // Tapering cheek into the lower post
      let t = (v - 0.52) / 0.48;
      halfWidth = lerp(198, 148, Math.pow(t, 0.85));
    }

    let centerLineX = lerp(238, 244, v) - Math.sin(v * Math.PI) * 8;
    let yTopArch = 392 + Math.pow(Math.abs(uCentered), 1.85) * 82;
    let yBotBase = lerp(918, 992, u);

    let x = centerLineX + uCentered * halfWidth;
    let y = lerp(yTopArch, yBotBase, Math.pow(v, 0.94));

    // Radial distance to the central scroll tuft at (238, 595)
    let dx = (x - cx) / 195;
    let dy = (y - cy) / 210;
    let r = Math.hypot(dx, dy);

    // Central button tuft dimple pulls leather inward near r < 0.35
    let tuftPull = Math.exp(-(r * r) / 0.065);
    x = lerp(x, cx, tuftPull * 0.24);
    y = lerp(y, cy, tuftPull * 0.24);

    // Plump pillowed 3D normal + central dimple inversion
    let nx = dx * 0.78;
    let ny = dy * 0.78;
    if (r < 0.32) {
      // Inside the central tuft dimple, normals tilt inward toward the button
      let dimpleT = 1.0 - r / 0.32;
      nx = lerp(nx, -dx * 2.4, dimpleT);
      ny = lerp(ny, -dy * 2.4, dimpleT);
    }
    let nz = Math.sqrt(Math.max(0.12, 1.0 - Math.min(0.88, nx * nx + ny * ny)));
    let n = norm3(nx, ny, nz);

    let aoTuft = 1.0 - tuftPull * 0.68;
    let aoEdge = constrain(1.18 - Math.pow(Math.abs(uCentered), 3.0) * 0.35, 0.65, 1.0);
    let aoBot = v > 0.82 ? constrain(1.0 - ((v - 0.82) / 0.18) * 0.42, 0.55, 1.0) : 1.0;

    return { x, y, nx: n[0], ny: n[1], nz: n[2], ao: aoTuft * aoEdge * aoBot };
  }

  return { x: u * 1200, y: v * 1200, nx: 0, ny: 0, nz: 1, ao: 1 };
}

// ============================================================================
// WATERTIGHT VORONOI + CRAZY-QUILT SUBDIVISION ENGINE IN (u, v) SPACE
// ============================================================================
// Clips a polygon where each vertex is { u, v } and each edge i -> (i+1) has tag edgeNeighbors[i]
function clipUvPolyByBisector(poly, su, sv, tu, tv, neighborId) {
  let mu = (su + tu) * 0.5;
  let mv = (sv + tv) * 0.5;
  let nu = tu - su;
  let nv = tv - sv;

  let inside = (p) => (p.u - mu) * nu + (p.v - mv) * nv <= 1e-7;
  let intersect = (a, b) => {
    let da = (a.u - mu) * nu + (a.v - mv) * nv;
    let db = (b.u - mu) * nu + (b.v - mv) * nv;
    let t = da / (da - db || 1e-9);
    return { u: a.u + (b.u - a.u) * t, v: a.v + (b.v - a.v) * t };
  };

  let outPts = [];
  let outNeigh = [];
  let n = poly.pts.length;
  if (n < 3) return poly;

  for (let i = 0; i < n; i++) {
    let cur = poly.pts[i];
    let next = poly.pts[(i + 1) % n];
    let curEdgeNeigh = poly.neigh[i];
    let curIn = inside(cur);
    let nextIn = inside(next);

    if (curIn && nextIn) {
      outPts.push(cur);
      outNeigh.push(curEdgeNeigh);
    } else if (curIn && !nextIn) {
      outPts.push(cur);
      outNeigh.push(curEdgeNeigh);
      outPts.push(intersect(cur, next));
      outNeigh.push(neighborId);
    } else if (!curIn && nextIn) {
      outPts.push(intersect(cur, next));
      outNeigh.push(curEdgeNeigh);
    }
  }
  return { pts: outPts, neigh: outNeigh };
}

function buildCrazyQuiltZone(zoneId, seeds, stitchScale = 1.0) {
  let cells = [];
  for (let i = 0; i < seeds.length; i++) {
    let poly = {
      pts: [
        { u: 0, v: 0 },
        { u: 1, v: 0 },
        { u: 1, v: 1 },
        { u: 0, v: 1 }
      ],
      neigh: [-1, -2, -3, -4] // Boundary edges
    };
    for (let j = 0; j < seeds.length; j++) {
      if (i === j) continue;
      poly = clipUvPolyByBisector(poly, seeds[i].u, seeds[i].v, seeds[j].u, seeds[j].v, j);
    }
    cells.push({
      id: i,
      seedU: seeds[i].u,
      seedV: seeds[i].v,
      pts: poly.pts,
      neigh: poly.neigh,
      adj: new Set(poly.neigh.filter((id) => id >= 0))
    });
  }

  // Greedy 5-leather graph coloring with balanced hide distribution so adjacent patches NEVER match
  let typeCounts = [0, 0, 0, 0, 0];
  // Weight preference: slightly more oxblood, tobacco, green, mauve, and dramatic patent black accents
  let targetWeights = [1.3, 1.3, 1.15, 0.78, 1.15];

  for (let i = 0; i < cells.length; i++) {
    let usedByNeighbors = new Set();
    for (let nb of cells[i].adj) {
      if (cells[nb] && cells[nb].leatherIdx !== undefined) {
        usedByNeighbors.add(cells[nb].leatherIdx);
      }
    }
    let bestType = 0;
    let bestScore = 1e9;
    for (let t = 0; t < 5; t++) {
      let penalty = usedByNeighbors.has(t) ? 1000 : 0;
      let score = penalty + typeCounts[t] / targetWeights[t] + random(0, 0.35);
      if (score < bestScore) {
        bestScore = score;
        bestType = t;
      }
    }
    cells[i].leatherIdx = bestType;
    cells[i].leather = LEATHER_TYPES[bestType];
    cells[i].patchSeed = random(100, 9000);
    cells[i].grainAngle = random(-75, 75);
    cells[i].hueShift = random(-0.05, 0.05);
    typeCounts[bestType]++;
  }

  // Build curved 3D-mapped screen polygons and extract unique shared seams
  // Use a canonical key for each shared edge so both adjacent patches get the exact same curved seam
  let seamCache = new Map();
  let uniqueSeams = [];

  function getCurvedEdgeScreenPts(u1, v1, u2, v2, idA, idB) {
    let minId = Math.min(idA, idB);
    let maxId = Math.max(idA, idB);
    let forward = idA < idB;
    let key =
      minId >= 0
        ? `${minId}_${maxId}_${Math.round((u1 + u2) * 500)}_${Math.round((v1 + v2) * 500)}`
        : `bnd_${idA}_${idB}_${Math.round(u1 * 1000)}_${Math.round(v1 * 1000)}`;

    if (seamCache.has(key)) {
      let cached = seamCache.get(key);
      return forward ? cached : cached.slice().reverse();
    }

    let steps = 9;
    let du = u2 - u1;
    let dv = v2 - v1;
    let lenUv = Math.hypot(du, dv) || 1;
    let pu = -dv / lenUv;
    let pv = du / lenUv;
    let curveSign = ((minId * 31 + maxId * 17) % 2 === 0 ? 1 : -1) * (minId >= 0 ? 1 : 0);
    let curveAmp = minId >= 0 ? Math.min(0.022, lenUv * 0.085) * curveSign : 0;

    let screenPts = [];
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let bow = Math.sin(t * Math.PI) * curveAmp;
      let cu = constrain(lerp(u1, u2, t) + pu * bow, 0, 1);
      let cv = constrain(lerp(v1, v2, t) + pv * bow, 0, 1);
      let mapped = evalZone(zoneId, cu, cv);
      screenPts.push([mapped.x, mapped.y, cu, cv, mapped.nx, mapped.ny, mapped.nz, mapped.ao]);
    }

    seamCache.set(key, screenPts);
    if (minId >= 0) {
      uniqueSeams.push({
        pts: screenPts,
        cellA: minId,
        cellB: maxId,
        stitchType: (minId + maxId) % 2 === 0 ? "feather" : "herringbone",
        threadColor: (minId * 7 + maxId * 13) % 3 === 0 ? "ivory" : "gold",
        scale: stitchScale
      });
    }
    return forward ? screenPts : screenPts.slice().reverse();
  }

  for (let cell of cells) {
    let screenPoly = [];
    let n = cell.pts.length;
    for (let i = 0; i < n; i++) {
      let a = cell.pts[i];
      let b = cell.pts[(i + 1) % n];
      let nb = cell.neigh[i];
      let edgePts = getCurvedEdgeScreenPts(a.u, a.v, b.u, b.v, cell.id, nb);
      // Append all except last point (which starts next edge)
      for (let k = 0; k < edgePts.length - 1; k++) {
        screenPoly.push(edgePts[k]);
      }
    }
    cell.screenPoly = screenPoly;

    // Compute bounding box & centroid in screen space
    let minX = 1e9, minY = 1e9, maxX = -1e9, maxY = -1e9;
    let sumX = 0, sumY = 0;
    for (let p of screenPoly) {
      if (p[0] < minX) minX = p[0];
      if (p[0] > maxX) maxX = p[0];
      if (p[1] < minY) minY = p[1];
      if (p[1] > maxY) maxY = p[1];
      sumX += p[0];
      sumY += p[1];
    }
    cell.bbox = { minX, minY, maxX, maxY };
    cell.cx = sumX / (screenPoly.length || 1);
    cell.cy = sumY / (screenPoly.length || 1);
  }

  return { zoneId, cells, seams: uniqueSeams };
}

// ============================================================================
// 2D POLYGON GEOMETRY & SCANLINE CLIPPING HELPERS
// ============================================================================
function pointInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect = yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi + 1e-9) + xi;
    if (intersect) inside = !inside;
  }
  return inside;
}

function distToSegment(px, py, x1, y1, x2, y2) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let l2 = dx * dx + dy * dy;
  if (l2 < 1e-6) return Math.hypot(px - x1, py - y1);
  let t = constrain(((px - x1) * dx + (py - y1) * dy) / l2, 0, 1);
  return Math.hypot(px - (x1 + t * dx), py - (y1 + t * dy));
}

function distToPolyBoundary(px, py, poly) {
  let minD = 1e9;
  for (let i = 0; i < poly.length; i++) {
    let a = poly[i];
    let b = poly[(i + 1) % poly.length];
    let d = distToSegment(px, py, a[0], a[1], b[0], b[1]);
    if (d < minD) minD = d;
  }
  return minD;
}

// Intersect an infinite line P0 + s * D with a polygon; returns pairs of [ [xA, yA], [xB, yB] ]
function clipScanlineToPoly(ox, oy, dx, dy, poly, insetPx = 1.5) {
  let nx = -dy;
  let ny = dx;
  let hits = [];
  for (let i = 0; i < poly.length; i++) {
    let a = poly[i];
    let b = poly[(i + 1) % poly.length];
    let da = (a[0] - ox) * nx + (a[1] - oy) * ny;
    let db = (b[0] - ox) * nx + (b[1] - oy) * ny;
    if ((da <= 0 && db > 0) || (db <= 0 && da > 0)) {
      let t = da / (da - db);
      let ix = a[0] + (b[0] - a[0]) * t;
      let iy = a[1] + (b[1] - a[1]) * t;
      let s = (ix - ox) * dx + (iy - oy) * dy;
      hits.push(s);
    }
  }
  hits.sort((a, b) => a - b);
  let segments = [];
  for (let i = 0; i + 1 < hits.length; i += 2) {
    let s0 = hits[i] + insetPx;
    let s1 = hits[i + 1] - insetPx;
    if (s1 - s0 > 2.5) {
      segments.push([
        [ox + dx * s0, oy + dy * s0],
        [ox + dx * s1, oy + dy * s1]
      ]);
    }
  }
  return segments;
}

// Interpolate 3D normal & AO for any screen point inside a cell using inverse-distance weighting of boundary vertices
function sampleCellSurface(x, y, cell) {
  let nx = 0, ny = 0, nz = 0, ao = 0, wSum = 0;
  let poly = cell.screenPoly;
  for (let i = 0; i < poly.length; i += 2) {
    let p = poly[i];
    let d2 = (x - p[0]) * (x - p[0]) + (y - p[1]) * (y - p[1]) + 35;
    let w = 1.0 / d2;
    nx += p[4] * w;
    ny += p[5] * w;
    nz += p[6] * w;
    ao += p[7] * w;
    wSum += w;
  }
  let n = norm3(nx / wSum, ny / wSum, nz / wSum);
  return { nx: n[0], ny: n[1], nz: n[2], ao: ao / wSum };
}

// ============================================================================
// HYPERREAL PATCH RENDERING PIPELINE (Layered Marker + Pencil + Creases + Grain)
// ============================================================================
function renderLeatherPatch(cell, zoneId) {
  let poly = cell.screenPoly;
  if (poly.length < 3) return;
  let leather = cell.leather;
  let ramp = leather.ramp;

  // Sample centroid lighting for base wash underpainting
  let centerSurf = sampleCellSurface(cell.cx, cell.cy, cell);
  let centerShade = computeLeatherShade(
    [cell.cx, cell.cy],
    centerSurf.nx,
    centerSurf.ny,
    centerSurf.nz,
    centerSurf.ao,
    24,
    leather,
    cell.patchSeed
  );

  // 1. Solid opaque base wash so no raw canvas shows between marker strokes
  let baseHex = paletteRamp(ramp, constrain(centerShade.tone * 0.78, 0.08, 0.72));
  brush.noStroke();
  brush.wash(baseHex, 245);
  brush.beginShape(0);
  for (let p of poly) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noWash();

  // Determine scanline frame aligned with the patch's leather grain angle
  let ang = cell.grainAngle * (Math.PI / 180);
  let dx = Math.cos(ang);
  let dy = Math.sin(ang);
  let px = -dy;
  let py = dx;

  let diag = Math.hypot(cell.bbox.maxX - cell.bbox.minX, cell.bbox.maxY - cell.bbox.minY);
  let halfSpan = diag * 0.62;

  // 2. LAYERED ALCOHOL MARKER PASSES (Chisel marker + Glaze marker)
  let markerStep = 7.5;
  for (let offset = -halfSpan; offset <= halfSpan; offset += markerStep) {
    let ox = cell.cx + px * offset;
    let oy = cell.cy + py * offset;
    let segs = clipScanlineToPoly(ox, oy, dx, dy, poly, 2.0);
    for (let seg of segs) {
      let ax = seg[0][0], ay = seg[0][1];
      let bx = seg[1][0], by = seg[1][1];
      let segLen = Math.hypot(bx - ax, by - ay);
      if (segLen < 4) continue;

      // Subdivide long marker strokes into tonal sub-strokes so 3D shading wraps smoothly across the patch
      let subCount = Math.max(1, Math.min(4, Math.ceil(segLen / 38)));
      for (let s = 0; s < subCount; s++) {
        let t0 = Math.max(0, (s - 0.12) / subCount);
        let t1 = Math.min(1, (s + 1.12) / subCount);
        let sx0 = lerp(ax, bx, t0);
        let sy0 = lerp(ay, by, t0);
        let sx1 = lerp(ax, bx, t1);
        let sy1 = lerp(ay, by, t1);
        let mx = (sx0 + sx1) * 0.5;
        let my = (sy0 + sy1) * 0.5;

        let surf = sampleCellSurface(mx, my, cell);
        let dSeam = distToPolyBoundary(mx, my, poly);
        let sh = computeLeatherShade([mx, my], surf.nx, surf.ny, surf.nz, surf.ao, dSeam, leather, cell.patchSeed);

        let col = paletteRamp(ramp, constrain(sh.tone + cell.hueShift, 0.03, 0.96));
        brush.set("chiselMarker", col, random(0.85, 1.18));
        safeLine(sx0, sy0, sx1, sy1);
      }
    }
  }

  // Cross-contour glaze marker pass for rich alcohol-marker color depth & seam pillow shading
  let crossAng = ang + Math.PI * 0.48;
  let cdx = Math.cos(crossAng), cdy = Math.sin(crossAng);
  let cpx = -cdy, cpy = cdx;
  let glazeStep = 11.5;
  for (let offset = -halfSpan; offset <= halfSpan; offset += glazeStep) {
    let ox = cell.cx + cpx * offset;
    let oy = cell.cy + cpy * offset;
    let segs = clipScanlineToPoly(ox, oy, cdx, cdy, poly, 2.5);
    for (let seg of segs) {
      let ax = seg[0][0], ay = seg[0][1];
      let bx = seg[1][0], by = seg[1][1];
      let mx = (ax + bx) * 0.5, my = (ay + by) * 0.5;
      let surf = sampleCellSurface(mx, my, cell);
      let dSeam = distToPolyBoundary(mx, my, poly);
      let sh = computeLeatherShade([mx, my], surf.nx, surf.ny, surf.nz, surf.ao, dSeam, leather, cell.patchSeed);

      let col = paletteRamp(ramp, constrain(sh.tone + ( random(-0.06, 0.06) ), 0.04, 0.95));
      brush.set("glazeMarker", col, random(0.8, 1.15));
      safeLine(ax, ay, bx, by);
    }
  }

  // 3. QUILTED SEAM PILLOWING & TENSION WRINKLES AROUND PATCH PERIMETER
  // Draw recessed dark border shading and short radial tension pull-creases perpendicular to each seam
  let nVerts = poly.length;
  for (let i = 0; i < nVerts; i++) {
    let a = poly[i];
    let b = poly[(i + 1) % nVerts];
    let ex = b[0] - a[0];
    let ey = b[1] - a[1];
    let eLen = Math.hypot(ex, ey);
    if (eLen < 3) continue;

    // Inward normal pointing toward patch interior
    let inX = -ey / eLen;
    let inY = ex / eLen;
    let toCenter = (cell.cx - a[0]) * inX + (cell.cy - a[1]) * inY;
    if (toCenter < 0) {
      inX = -inX;
      inY = -inY;
    }

    let mx = (a[0] + b[0]) * 0.5 + inX * 6;
    let my = (a[1] + b[1]) * 0.5 + inY * 6;
    let surf = sampleCellSurface(mx, my, cell);
    let sh = computeLeatherShade([mx, my], surf.nx, surf.ny, surf.nz, surf.ao, 5, leather, cell.patchSeed);

    // Dark recessed edge shadow in 2B / cpencil
    let edgeDark = paletteRamp(ramp, constrain(sh.tone * 0.45, 0.01, 0.35));
    brush.set("2B", edgeDark, 1.05);
    safeLine(a[0] + inX * 2.2, a[1] + inY * 2.2, b[0] + inX * 2.2, b[1] + inY * 2.2);

    // Plump quilted lip highlight 9px inside the seam on light-facing edges
    let lipX1 = a[0] + inX * 9.5;
    let lipY1 = a[1] + inY * 9.5;
    let lipX2 = b[0] + inX * 9.5;
    let lipY2 = b[1] + inY * 9.5;
    if (pointInPoly((lipX1 + lipX2) * 0.5, (lipY1 + lipY2) * 0.5, poly)) {
      let lipDotLight = inX * LIGHT_DIR[0] + inY * LIGHT_DIR[1];
      if (lipDotLight < 0.15 && sh.tone > 0.32) {
        let lipBright = paletteRamp(ramp, constrain(sh.tone + 0.22, 0.25, 0.92));
        brush.set("cpencil", lipBright, 0.95);
        safeLine(lipX1, lipY1, lipX2, lipY2);
      }
    }

    // Short leather gather/tension pleats radiating inward from the stitched seam
    if (i % 2 === 0 && eLen > 6) {
      let pleatLen = random(9, 22);
      let px0 = (a[0] + b[0]) * 0.5 + inX * 2.0;
      let py0 = (a[1] + b[1]) * 0.5 + inY * 2.0;
      let px1 = px0 + inX * pleatLen + (ex / eLen) * random(-4, 4);
      let py1 = py0 + inY * pleatLen + (ey / eLen) * random(-4, 4);
      if (pointInPoly(px1, py1, poly)) {
        brush.set("2B", paletteRamp(ramp, constrain(sh.tone * 0.38, 0.01, 0.28)), 0.78);
        safeLine(px0, py0, px1, py1);
        if (sh.tone > 0.35) {
          brush.set("2H", paletteRamp(ramp, constrain(sh.tone + 0.24, 0.3, 0.92)), 0.65);
          safeLine(px0 + (ex / eLen) * 1.5, py0 + (ey / eLen) * 1.5, px1 + (ex / eLen) * 1.5, py1 + (ey / eLen) * 1.5);
        }
      }
    }
  }

  // 4. LAYERED COLORED PENCIL & GRAPHITE GRAIN HATCHING (cpencil, 2B, HB, 2H)
  let pencilStep = 5.2;
  for (let offset = -halfSpan; offset <= halfSpan; offset += pencilStep) {
    let ox = cell.cx + px * offset;
    let oy = cell.cy + py * offset;
    let segs = clipScanlineToPoly(ox, oy, dx, dy, poly, 3.0);
    for (let seg of segs) {
      let ax = seg[0][0], ay = seg[0][1];
      let bx = seg[1][0], by = seg[1][1];
      let sLen = Math.hypot(bx - ax, by - ay);
      if (sLen < 5) continue;

      let steps = Math.max(1, Math.floor(sLen / 22));
      for (let k = 0; k < steps; k++) {
        let t0 = k / steps;
        let t1 = (k + 0.88) / steps;
        let x0 = lerp(ax, bx, t0);
        let y0 = lerp(ay, by, t0);
        let x1 = lerp(ax, bx, t1);
        let y1 = lerp(ay, by, t1);
        let mx = (x0 + x1) * 0.5;
        let my = (y0 + y1) * 0.5;

        let surf = sampleCellSurface(mx, my, cell);
        let dSeam = distToPolyBoundary(mx, my, poly);
        let sh = computeLeatherShade([mx, my], surf.nx, surf.ny, surf.nz, surf.ao, dSeam, leather, cell.patchSeed);

        let grainVar = (noise(mx * 0.045, my * 0.045, cell.patchSeed) - 0.5) * 0.18;
        let localTone = constrain(sh.tone + grainVar, 0.02, 0.98);
        let pCol = paletteRamp(ramp, localTone);

        let bType = localTone < 0.35 ? "2B" : localTone < 0.68 ? "cpencil" : "2H";
        brush.set(bType, pCol, random(0.68, 1.05));
        safeLine(x0, y0, x1, y1);
      }
    }
  }

  // 5. MATERIAL-SPECIFIC HYPERREAL MICRO-GRAIN, CREASES & SPECULAR WEAR SHEEN
  renderMaterialMicroTexture(cell, poly, leather, ramp, halfSpan);
}

function renderMaterialMicroTexture(cell, poly, leather, ramp, halfSpan) {
  let areaApprox = (cell.bbox.maxX - cell.bbox.minX) * (cell.bbox.maxY - cell.bbox.minY);
  let countScale = constrain(areaApprox / 14000, 0.45, 2.2);

  // A. DEEP FLEX CREASES & BRANCHING WRINKLES (All hides, styled by leather stiffness)
  let numCreases = Math.round((leather.id === "suede" ? 3 : 6) * countScale);
  for (let c = 0; c < numCreases; c++) {
    // Pick a random interior start point and trace a curved crease across the patch
    let startX = random(cell.bbox.minX + 10, cell.bbox.maxX - 10);
    let startY = random(cell.bbox.minY + 10, cell.bbox.maxY - 10);
    if (!pointInPoly(startX, startY, poly)) continue;

    let cAng = (cell.grainAngle + random(-42, 42)) * (Math.PI / 180);
    let creasePts = [];
    let lightLipPts = [];
    let cx = startX, cy = startY;
    let stepLen = 8.5;
    let maxSteps = Math.floor(random(5, 11));

    for (let s = 0; s < maxSteps; s++) {
      if (!pointInPoly(cx, cy, poly) || distToPolyBoundary(cx, cy, poly) < 3.5) break;
      creasePts.push([cx, cy]);
      // Offset lip highlight toward window light (-LIGHT_DIR)
      lightLipPts.push([cx - LIGHT_DIR[0] * 2.1, cy - LIGHT_DIR[1] * 2.1]);
      cAng += (noise(cx * 0.02, cy * 0.02, c * 17) - 0.5) * 0.55;
      cx += Math.cos(cAng) * stepLen;
      cy += Math.sin(cAng) * stepLen;
    }

    if (creasePts.length >= 3) {
      let mid = creasePts[Math.floor(creasePts.length / 2)];
      let surf = sampleCellSurface(mid[0], mid[1], cell);
      let sh = computeLeatherShade(mid, surf.nx, surf.ny, surf.nz, surf.ao, 16, leather, cell.patchSeed);

      // Dark crease valley
      let darkCol = paletteRamp(ramp, constrain(sh.tone * 0.28, 0.01, 0.22));
      brush.set(leather.id === "patent" ? "rotring" : "2B", darkCol, random(0.75, 1.15));
      safeSpline(creasePts, 0.45);

      // Lit ridge lip catching the window sheen right next to the crease
      if (sh.tone > 0.24) {
        let ridgeTone = leather.id === "patent" ? constrain(sh.tone + 0.48, 0.45, 0.99) : constrain(sh.tone + 0.28, 0.35, 0.96);
        let lightCol = paletteRamp(ramp, ridgeTone);
        brush.set(leather.id === "patent" ? "rotring" : "2H", lightCol, random(0.65, 0.95));
        safeSpline(lightLipPts, 0.45);
      }

      // Secondary Y-branch micro-wrinkle splitting off the main crease
      if (creasePts.length >= 4 && random() < 0.65) {
        let bIdx = Math.floor(creasePts.length * 0.5);
        let bp = creasePts[bIdx];
        let bAng = cAng + (random() < 0.5 ? 0.52 : -0.52);
        let bx = bp[0] + Math.cos(bAng) * 14;
        let by = bp[1] + Math.sin(bAng) * 14;
        if (pointInPoly(bx, by, poly)) {
          brush.set("HB", darkCol, 0.65);
          safeLine(bp[0], bp[1], bx, by);
        }
      }
    }
  }

  // B. HIDE-SPECIFIC SURFACE GRAIN & SHEEN
  if (leather.id === "patent") {
    // CRACKED PATENT BLACK: Brittle craze/alligator crack network + razor-sharp white window reflection ribbons
    let crackCount = Math.round(14 * countScale);
    for (let k = 0; k < crackCount; k++) {
      let px = random(cell.bbox.minX + 6, cell.bbox.maxX - 6);
      let py = random(cell.bbox.minY + 6, cell.bbox.maxY - 6);
      if (!pointInPoly(px, py, poly)) continue;

      let surf = sampleCellSurface(px, py, cell);
      let dSeam = distToPolyBoundary(px, py, poly);
      let sh = computeLeatherShade([px, py], surf.nx, surf.ny, surf.nz, surf.ao, dSeam, leather, cell.patchSeed);

      // Angular craze crack segments
      let ang = random(0, Math.PI * 2);
      let len1 = random(7, 18);
      let x1 = px + Math.cos(ang) * len1;
      let y1 = py + Math.sin(ang) * len1;
      let ang2 = ang + random(-1.1, 1.1);
      let len2 = random(6, 15);
      let x2 = x1 + Math.cos(ang2) * len2;
      let y2 = y1 + Math.sin(ang2) * len2;

      if (pointInPoly(x1, y1, poly)) {
        // Dark matte fissure
        brush.set("rotring", "#040508", 0.75);
        safeLine(px, py, x1, y1);
        // Specular glint catching the sharp edge of the lacquer crack
        if (sh.beam > 0.45 && (sh.tone > 0.18 || random() < 0.45)) {
          let glintCol = sh.tone > 0.42 ? "#ffffff" : sh.tone > 0.22 ? "#bad8ff" : "#5b78a6";
          brush.set("rotring", glintCol, sh.tone > 0.42 ? 0.85 : 0.6);
          safeLine(px - LIGHT_DIR[0] * 1.3, py - LIGHT_DIR[1] * 1.3, x1 - LIGHT_DIR[0] * 1.3, y1 - LIGHT_DIR[1] * 1.3);
        }
        if (pointInPoly(x2, y2, poly)) {
          brush.set("rotring", "#040508", 0.65);
          safeLine(x1, y1, x2, y2);
        }
      }
    }

    // High-gloss window specular reflection streaks across patent leather
    let specSamples = Math.round(28 * countScale);
    for (let s = 0; s < specSamples; s++) {
      let sx = random(cell.bbox.minX + 6, cell.bbox.maxX - 6);
      let sy = random(cell.bbox.minY + 6, cell.bbox.maxY - 6);
      if (!pointInPoly(sx, sy, poly)) continue;
      let surf = sampleCellSurface(sx, sy, cell);
      let dSeam = distToPolyBoundary(sx, sy, poly);
      let sh = computeLeatherShade([sx, sy], surf.nx, surf.ny, surf.nz, surf.ao, dSeam, leather, cell.patchSeed);

      if (sh.spec > 0.22 || sh.tone > 0.42) {
        let sAng = (cell.grainAngle + 15) * (Math.PI / 180);
        let sLen = random(6, 16);
        let ex = sx + Math.cos(sAng) * sLen;
        let ey = sy + Math.sin(sAng) * sLen;
        if (pointInPoly(ex, ey, poly)) {
          let sheenCol = sh.spec > 0.55 ? "#ffffff" : "#cce4ff";
          brush.set("2H", sheenCol, random(0.85, 1.35));
          safeLine(sx, sy, ex, ey);
        }
      }
    }
  } else if (leather.id === "suede") {
    // DUSTY MAUVE SUEDE: Velvety multi-directional nap stipple + fibrous spray bloom
    let napCount = Math.round(52 * countScale);
    for (let k = 0; k < napCount; k++) {
      let sx = random(cell.bbox.minX + 4, cell.bbox.maxX - 4);
      let sy = random(cell.bbox.minY + 4, cell.bbox.maxY - 4);
      if (!pointInPoly(sx, sy, poly)) continue;

      let surf = sampleCellSurface(sx, sy, cell);
      let dSeam = distToPolyBoundary(sx, sy, poly);
      let sh = computeLeatherShade([sx, sy], surf.nx, surf.ny, surf.nz, surf.ao, dSeam, leather, cell.patchSeed);

      // Coherent nap swipe direction
      let napAng = noise(sx * 0.015, sy * 0.015, cell.patchSeed) * Math.PI * 2;
      let fLen = random(4, 9);
      let ex = sx + Math.cos(napAng) * fLen;
      let ey = sy + Math.sin(napAng) * fLen;
      if (!pointInPoly(ex, ey, poly)) continue;

      let napTone = constrain(sh.tone + random(-0.14, 0.16), 0.05, 0.96);
      let col = paletteRamp(ramp, napTone);
      brush.set(k % 3 === 0 ? "2B" : "cpencil", col, random(0.7, 1.15));
      safeLine(sx, sy, ex, ey);
    }
  } else {
    // OXBLOOD, TOBACCO-BROWN & FADED BOTTLE-GREEN:
    // Hyperreal pebble pores, morocco cross-grain, and luminous specular wear sheen
    let pebbleCount = Math.round(44 * countScale);
    for (let k = 0; k < pebbleCount; k++) {
      let gx = random(cell.bbox.minX + 5, cell.bbox.maxX - 5);
      let gy = random(cell.bbox.minY + 5, cell.bbox.maxY - 5);
      if (!pointInPoly(gx, gy, poly)) continue;

      let surf = sampleCellSurface(gx, gy, cell);
      let dSeam = distToPolyBoundary(gx, gy, poly);
      let sh = computeLeatherShade([gx, gy], surf.nx, surf.ny, surf.nz, surf.ao, dSeam, leather, cell.patchSeed);

      let rPebble = random(2.2, 4.5) * leather.grainScale;
      // Shadow crescent on bottom-right of pebble
      let darkPebble = paletteRamp(ramp, constrain(sh.tone * 0.48, 0.02, 0.42));
      brush.set("2B", darkPebble, 0.68);
      safeLine(gx - rPebble * 0.5, gy + rPebble * 0.7, gx + rPebble * 0.8, gy - rPebble * 0.2);

      // Specular wear glint on top-left crown of the pebble (stronger in lit zones)
      if (sh.tone > 0.36 || sh.spec > 0.14) {
        let glintTone = constrain(sh.tone + 0.26 + sh.spec * 0.35, 0.38, 0.99);
        let lightPebble = paletteRamp(ramp, glintTone);
        brush.set(glintTone > 0.82 ? "rotring" : "2H", lightPebble, glintTone > 0.82 ? 0.65 : 0.78);
        safeLine(gx - rPebble * 0.7, gy - rPebble * 0.5, gx + rPebble * 0.4, gy - rPebble * 0.8);
      }

      // Bottle-green morocco cross-hatch micro-grain
      if (leather.id === "green" && k % 2 === 0) {
        let mAng = (cell.grainAngle + 62) * (Math.PI / 180);
        let mx2 = gx + Math.cos(mAng) * 7;
        let my2 = gy + Math.sin(mAng) * 7;
        if (pointInPoly(mx2, my2, poly)) {
          brush.set("HB", paletteRamp(ramp, constrain(sh.tone + 0.15, 0.15, 0.88)), 0.6);
          safeLine(gx, gy, mx2, my2);
        }
      }
    }
  }
}

// ============================================================================
// THREAD-BY-THREAD DECORATIVE FEATHER & HERRINGBONE OVERSTITCHING IN FINE PEN
// ============================================================================
const THREAD_PALETTES = {
  gold: {
    shadow: "#1a0c04",
    dark: "#7a4b08",
    mid: "#c98a18",
    bright: "#f7bf36",
    glint: "#fff09e"
  },
  ivory: {
    shadow: "#170e0a",
    dark: "#85745c",
    mid: "#cfc0a8",
    bright: "#f5ebd8",
    glint: "#ffffff"
  }
};

function drawSingleThreadStitch(x1, y1, x2, y2, pal, lightFactor, weightScale = 1.0) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = Math.hypot(dx, dy);
  if (len < 1.8) return;

  // Slight arch to simulate taut round thread curving over the leather seam
  let nx = -dy / len;
  let ny = dx / len;
  let bow = Math.min(1.6, len * 0.1) * (nx * LIGHT_DIR[0] + ny * LIGHT_DIR[1] < 0 ? 1 : -1);
  let mx = (x1 + x2) * 0.5 + nx * bow;
  let my = (y1 + y2) * 0.5 + ny * bow;

  // 1. Needle hole punctures at both ends where the thread pierces the leather
  brush.set("rotring", "#0c0506", 0.95 * weightScale);
  safeLine(x1 - 0.8, y1 - 0.8, x1 + 0.9, y1 + 0.9);
  safeLine(x2 - 0.8, y2 - 0.8, x2 + 0.9, y2 + 0.9);

  // 2. Cast shadow of the raised thread onto the leather underneath
  brush.set("pen", pal.shadow, 1.05 * weightScale);
  safeSpline(
    [
      [x1 + 1.1, y1 + 1.4],
      [mx + 1.2, my + 1.5],
      [x2 + 1.1, y2 + 1.4]
    ],
    0.45
  );

  // 3. Main thread body modulated by 3D chair lighting
  let bodyCol =
    lightFactor > 0.62
      ? lerpHex(pal.mid, pal.bright, (lightFactor - 0.62) / 0.38)
      : lerpHex(pal.dark, pal.mid, lightFactor / 0.62);
  brush.set("pen", bodyCol, 1.22 * weightScale);
  safeSpline(
    [
      [x1, y1],
      [mx, my],
      [x2, y2]
    ],
    0.45
  );

  // 4. High-precision fine pen specular twist highlight along the crown of the thread
  if (lightFactor > 0.32) {
    let gCol = lightFactor > 0.68 ? pal.glint : pal.bright;
    let gx1 = lerp(x1, mx, 0.32);
    let gy1 = lerp(y1, my, 0.32);
    let gx2 = lerp(mx, x2, 0.68);
    let gy2 = lerp(my, y2, 0.68);
    brush.set("rotring", gCol, 0.78 * weightScale);
    safeLine(gx1, gy1, gx2, gy2);
  }
}

// Resample a seam polyline into uniform arc-length stations { x, y, tx, ty, nx, ny, light }
function resampleSeam(pts, stepPx) {
  let stations = [];
  let accum = 0;
  let totalLen = 0;
  let segLens = [];
  for (let i = 0; i < pts.length - 1; i++) {
    let d = Math.hypot(pts[i + 1][0] - pts[i][0], pts[i + 1][1] - pts[i][1]);
    segLens.push(d);
    totalLen += d;
  }
  if (totalLen < stepPx * 1.2) return stations;

  let numSteps = Math.max(2, Math.floor(totalLen / stepPx));
  let actualStep = totalLen / numSteps;

  let curSeg = 0;
  let segDist = 0;
  for (let s = 0; s <= numSteps; s++) {
    let target = s * actualStep;
    while (curSeg < segLens.length - 1 && segDist + segLens[curSeg] < target) {
      segDist += segLens[curSeg];
      curSeg++;
    }
    let rem = target - segDist;
    let t = segLens[curSeg] > 1e-5 ? constrain(rem / segLens[curSeg], 0, 1) : 0;
    let a = pts[curSeg];
    let b = pts[curSeg + 1];
    let x = lerp(a[0], b[0], t);
    let y = lerp(a[1], b[1], t);
    let dx = b[0] - a[0];
    let dy = b[1] - a[1];
    let dl = Math.hypot(dx, dy) || 1;
    let tx = dx / dl;
    let ty = dy / dl;
    let nx = -ty;
    let ny = tx;

    // Compute local 3D lighting for thread brightness
    let sNx = lerp(a[4] || 0, b[4] || 0, t);
    let sNy = lerp(a[5] || 0, b[5] || 0, t);
    let sNz = lerp(a[6] || 1, b[6] || 1, t);
    let sAo = lerp(a[7] || 1, b[7] || 1, t);
    let ndotl = Math.max(0.1, sNx * LIGHT_DIR[0] + sNy * LIGHT_DIR[1] + sNz * LIGHT_DIR[2]);
    let light = constrain((0.18 + ndotl * 0.82) * getWindowBeam(x, y) * sAo, 0.14, 1.0);

    stations.push({ x, y, tx, ty, nx, ny, light });
  }
  return stations;
}

function renderSeamOverstitching(seam) {
  let pts = seam.pts;
  if (!pts || pts.length < 2) return;
  let sc = seam.scale || 1.0;

  // 1. Deep recessed seam crevice groove where the two leather hides tuck together
  let rawCoords = pts.map((p) => [p[0], p[1]]);
  brush.set("2B", "#0a0406", 1.8 * sc);
  safeSpline(rawCoords, 0.45);
  brush.set("rotring", "#050203", 1.15 * sc);
  safeSpline(rawCoords, 0.45);

  let pal = THREAD_PALETTES[seam.threadColor] || THREAD_PALETTES.gold;

  if (seam.stitchType === "feather") {
    // DECORATIVE FEATHER STITCH (Alternating central zigzag spine + diagonal side wings)
    let stepPx = 10.5 * sc;
    let stations = resampleSeam(pts, stepPx);
    if (stations.length < 3) return;

    let wSpine = 2.8 * sc;
    let wWing = 9.2 * sc;

    for (let i = 0; i < stations.length - 1; i++) {
      let cur = stations[i];
      let next = stations[i + 1];
      let side = i % 2 === 0 ? 1 : -1;
      let nextSide = -side;

      // Central spine stitch from cur spine node to next spine node
      let sx0 = cur.x + cur.nx * side * wSpine;
      let sy0 = cur.y + cur.ny * side * wSpine;
      let sx1 = next.x + next.nx * nextSide * wSpine;
      let sy1 = next.y + next.ny * nextSide * wSpine;
      drawSingleThreadStitch(sx0, sy0, sx1, sy1, pal, (cur.light + next.light) * 0.5, sc);

      // Diagonal wing stitch reaching out into the leather patch on 'nextSide'
      let wx = cur.x + cur.tx * (stepPx * 0.35) + cur.nx * nextSide * wWing;
      let wy = cur.y + cur.ty * (stepPx * 0.35) + cur.ny * nextSide * wWing;
      drawSingleThreadStitch(wx, wy, sx1, sy1, pal, next.light, sc);
    }
  } else {
    // DECORATIVE HERRINGBONE STITCH (Plaited crossing X-lattice with locking side bars)
    let stepPx = 9.5 * sc;
    let stations = resampleSeam(pts, stepPx);
    if (stations.length < 3) return;

    let wOuter = 8.6 * sc;
    let wInner = 5.4 * sc;

    // First pass: diagonal strokes slanting one way + side locking bars
    for (let i = 0; i < stations.length - 1; i++) {
      let cur = stations[i];
      let next = stations[i + 1];
      let lf = (cur.light + next.light) * 0.5;

      if (i % 2 === 0) {
        // Cross from left outer to right outer
        let x1 = cur.x - cur.nx * wOuter;
        let y1 = cur.y - cur.ny * wOuter;
        let x2 = next.x + next.nx * wOuter;
        let y2 = next.y + next.ny * wOuter;
        drawSingleThreadStitch(x1, y1, x2, y2, pal, lf, sc);

        // Short locking back-stitch on right side
        let lx = next.x - next.tx * (stepPx * 0.42) + next.nx * wInner;
        let ly = next.y - next.ty * (stepPx * 0.42) + next.ny * wInner;
        drawSingleThreadStitch(x2, y2, lx, ly, pal, next.light, sc * 0.9);
      } else {
        // Cross from right outer to left outer (overlapping the previous diagonal!)
        let x1 = cur.x + cur.nx * wOuter;
        let y1 = cur.y + cur.ny * wOuter;
        let x2 = next.x - next.nx * wOuter;
        let y2 = next.y - next.ny * wOuter;
        drawSingleThreadStitch(x1, y1, x2, y2, pal, lf, sc);

        // Short locking back-stitch on left side
        let lx = next.x - next.tx * (stepPx * 0.42) - next.nx * wInner;
        let ly = next.y - next.ty * (stepPx * 0.42) - next.ny * wInner;
        drawSingleThreadStitch(x2, y2, lx, ly, pal, next.light, sc * 0.9);
      }
    }
  }
}

// ============================================================================
// CORDED LEATHER PIPING (WELTING) & TUFTED BUTTON RENDERERS
// ============================================================================
function renderPipedWelting(curvePts, radiusPx = 7.5) {
  let stations = resampleSeam(curvePts, 7.0);
  if (stations.length < 4) return;

  // Deep shadow under and above the piping cord
  for (let i = 0; i < stations.length - 1; i++) {
    let a = stations[i];
    let b = stations[i + 1];
    brush.set("2B", "#090406", 1.6);
    safeLine(a.x + a.nx * radiusPx, a.y + a.ny * radiusPx, b.x + b.nx * radiusPx, b.y + b.ny * radiusPx);
    safeLine(a.x - a.nx * radiusPx, a.y - a.ny * radiusPx, b.x - b.nx * radiusPx, b.y - b.ny * radiusPx);
  }

  // Bias-wrapped mismatched leather segments along the piping cord (switches hide every 9 stations)
  for (let i = 0; i < stations.length - 1; i++) {
    let a = stations[i];
    let b = stations[i + 1];
    let leatherIdx = Math.floor(i / 9) % 5;
    let leather = LEATHER_TYPES[leatherIdx];
    let ramp = leather.ramp;
    let lf = (a.light + b.light) * 0.5;

    // Shadow half of the cord
    let darkCol = paletteRamp(ramp, constrain(lf * 0.35, 0.04, 0.38));
    brush.set("glazeMarker", darkCol, 0.95);
    safeLine(
      a.x + a.nx * (radiusPx * 0.45),
      a.y + a.ny * (radiusPx * 0.45),
      b.x + b.nx * (radiusPx * 0.45),
      b.y + b.ny * (radiusPx * 0.45)
    );

    // Rich body of the cord
    let midCol = paletteRamp(ramp, constrain(lf * 0.76, 0.15, 0.85));
    brush.set("glazeMarker", midCol, 1.05);
    safeLine(a.x, a.y, b.x, b.y);

    // Specular wear crown of the cord
    let hiCol = paletteRamp(ramp, constrain(lf * 0.95 + 0.18, 0.35, 0.99));
    brush.set("2H", hiCol, 0.95);
    safeLine(
      a.x - a.nx * (radiusPx * 0.35),
      a.y - a.ny * (radiusPx * 0.35),
      b.x - b.nx * (radiusPx * 0.35),
      b.y - b.ny * (radiusPx * 0.35)
    );

    // Every 9 stations, draw a diagonal bias splice seam in gold thread
    if (i > 0 && i % 9 === 0) {
      drawSingleThreadStitch(
        a.x - a.nx * radiusPx,
        a.y - a.ny * radiusPx,
        b.x + b.nx * radiusPx,
        b.y + b.ny * radiusPx,
        THREAD_PALETTES.gold,
        lf,
        0.95
      );
    }

    // Overstitching along the base of the piping cord
    if (i % 2 === 0) {
      let pal = (Math.floor(i / 9) % 2 === 0) ? THREAD_PALETTES.gold : THREAD_PALETTES.ivory;
      drawSingleThreadStitch(
        a.x + a.nx * (radiusPx * 0.75),
        a.y + a.ny * (radiusPx * 0.75),
        b.x + b.nx * (radiusPx * 1.45),
        b.y + b.ny * (radiusPx * 1.45),
        pal,
        lf,
        0.88
      );
    }
  }
}

function renderScrollCenterButton(cx, cy) {
  // Deep pleated shadow ring around the central armrest scroll button
  let rBtn = 24;
  for (let a = 0; a < 360; a += 15) {
    let rad = (a * Math.PI) / 180;
    let nextRad = ((a + 18) * Math.PI) / 180;
    let x1 = cx + Math.cos(rad) * (rBtn + 3);
    let y1 = cy + Math.sin(rad) * (rBtn + 3);
    let x2 = cx + Math.cos(nextRad) * (rBtn + 3);
    let y2 = cy + Math.sin(nextRad) * (rBtn + 3);
    brush.set("2B", "#080305", 1.8);
    safeLine(x1, y1, x2, y2);

    // Radiating pleated tension creases into the surrounding scroll patches
    let pLen = random(18, 38);
    let px = cx + Math.cos(rad) * (rBtn + pLen);
    let py = cy + Math.sin(rad) * (rBtn + pLen);
    brush.set("2B", "#14060a", 1.05);
    safeLine(x1, y1, px, py);
    if (Math.cos(rad - 2.3) > 0) {
      brush.set("2H", "#eb7c6b", 0.75);
      safeLine(x1 + 1.8, y1 - 1.8, px + 1.8, py - 1.8);
    }
  }

  // Two-piece crazy-quilt leather button cap (Oxblood top-left + Tobacco bottom-right)
  for (let r = rBtn; r >= 2; r -= 2.5) {
    for (let a = 0; a < 360; a += 20) {
      let rad1 = (a * Math.PI) / 180;
      let rad2 = ((a + 22) * Math.PI) / 180;
      let isOxblood = Math.cos(rad1 + 0.6) < 0;
      let leather = isOxblood ? LEATHER_TYPES[0] : LEATHER_TYPES[1];
      let nx = (Math.cos(rad1) * r) / rBtn;
      let ny = (Math.sin(rad1) * r) / rBtn;
      let nz = Math.sqrt(Math.max(0.1, 1 - nx * nx - ny * ny));
      let ndotl = Math.max(0.08, nx * LIGHT_DIR[0] + ny * LIGHT_DIR[1] + nz * LIGHT_DIR[2]);
      let col = paletteRamp(leather.ramp, constrain(ndotl * 0.92, 0.12, 0.96));
      brush.set("glazeMarker", col, 0.85);
      safeLine(cx + Math.cos(rad1) * r, cy + Math.sin(rad1) * r, cx + Math.cos(rad2) * r, cy + Math.sin(rad2) * r);
    }
  }

  // Gold feather cross-stitching across the button diameter
  for (let t = -rBtn + 4; t <= rBtn - 4; t += 6.5) {
    let sx = cx + t * 0.7;
    let sy = cy - t * 0.7;
    drawSingleThreadStitch(sx - 5, sy - 5, sx + 5, sy + 5, THREAD_PALETTES.gold, 0.88, 0.95);
    drawSingleThreadStitch(sx - 5, sy + 5, sx + 5, sy - 5, THREAD_PALETTES.ivory, 0.85, 0.85);
  }
}

// ============================================================================
// BACKGROUND DIM CORNER, WINDOW LIGHT SHAFT & TURNED WALNUT BUN FOOT
// ============================================================================
function renderDimCornerAndFoot() {
  background("#0e0a0e");

  // 1. Moody dim corner wall behind the armchair (top-left x: 0..640, y: 0..600)
  for (let y = 0; y < 640; y += 9) {
    let maxX = y < 220 ? 1200 : 520;
    for (let x = 0; x < maxX; x += 48) {
      let beam = getWindowBeam(x, y);
      // Warm dusty gold-umber window shaft on the left, deep indigo-plum corner shadow on the right
      let wallRamp = ["#09070c", "#130f17", "#211921", "#38292b", "#59413a", "#7d5c4d"];
      let tone = constrain((beam - 0.18) * 0.75 * (1.0 - x / 1350), 0.02, 0.88);
      let col = paletteRamp(wallRamp, tone + random(-0.04, 0.04));
      brush.set("chiselMarker", col, random(1.1, 1.6));
      safeLine(x, y + random(-3, 3), x + 54, y + random(-3, 3));
    }
  }

  // Diagonal window light rays & subtle vertical wallpaper/plaster grain in colored pencil
  for (let i = 0; i < 190; i++) {
    let rx = random(0, 580);
    let ry = random(0, 540);
    let beam = getWindowBeam(rx, ry);
    let rayCol = lerpHex("#1a141c", "#6e5244", constrain(beam * 0.85, 0, 1));
    brush.set(i % 2 === 0 ? "cpencil" : "2B", rayCol, random(0.7, 1.2));
    // Diagonal window beam direction
    safeLine(rx, ry, rx + 42, ry + 34);
  }

  // Floating golden dust motes in the upper-left window beam
  for (let m = 0; m < 48; m++) {
    let mx = random(15, 420);
    let my = random(15, 430);
    if (getWindowBeam(mx, my) > 0.65) {
      brush.set("rotring", m % 2 === 0 ? "#ffe7b3" : "#c9a375", random(0.6, 1.1));
      safeLine(mx, my, mx + 1.8, my + 1.5);
    }
  }

  // 2. Shadowed floor corner & Turned Dark Walnut Bun Foot at bottom-left (x: 0..420, y: 880..1200)
  for (let y = 880; y <= 1200; y += 8) {
    for (let x = 0; x <= 420; x += 40) {
      let fCol = lerpHex("#070406", "#211410", constrain((1 - y / 1250) * 0.7, 0, 1));
      brush.set("chiselMarker", fCol, 1.3);
      safeLine(x, y, x + 45, y + 4);
    }
  }

  // Turned dark walnut bun foot under the front-left corner of the apron (cx: 235, cy: 1125)
  let fx = 235, fy = 1135, rx = 95, ry = 56;
  let woodRamp = ["#080302", "#1a0b05", "#36180b", "#5c2b14", "#8a4421", "#b86839"];
  for (let dy = -ry; dy <= ry; dy += 3.5) {
    let w = Math.sqrt(Math.max(0, 1 - (dy * dy) / (ry * ry))) * rx;
    // Lathe-turned beading profile
    let bead = 1.0 + 0.12 * Math.cos((dy / ry) * Math.PI * 2.5);
    w *= bead;
    for (let dx = -w; dx <= w; dx += 16) {
      let nx = dx / (w || 1);
      let ny = dy / ry;
      let ndotl = Math.max(0, -nx * 0.65 - ny * 0.45 + 0.45);
      let col = paletteRamp(woodRamp, constrain(ndotl * 0.85, 0.04, 0.92));
      brush.set("glazeMarker", col, 0.95);
      safeLine(fx + dx, fy + dy, fx + Math.min(w, dx + 18), fy + dy);
    }
  }
}

// ============================================================================
// SEED GENERATORS FOR CRAZY-QUILT PATCH TOPOLOGY PER ZONE
// ============================================================================
function generateStratifiedSeeds(cols, rows, jitter = 0.28) {
  let seeds = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      let u = constrain((c + 0.5 + random(-jitter, jitter)) / cols, 0.04, 0.96);
      let v = constrain((r + 0.5 + random(-jitter, jitter)) / rows, 0.04, 0.96);
      seeds.push({ u, v });
    }
  }
  return seeds;
}

function generateScrollRadialSeeds() {
  // Spiral/radial crazy-quilt layout around the scroll center (0.50, 0.44)
  let seeds = [{ u: 0.5, v: 0.44 }];
  // Inner ring of 6 seeds
  for (let i = 0; i < 6; i++) {
    let ang = (i * 60 + random(-14, 14)) * (Math.PI / 180);
    let r = random(0.18, 0.24);
    seeds.push({
      u: constrain(0.5 + Math.cos(ang) * r * 1.1, 0.08, 0.92),
      v: constrain(0.44 + Math.sin(ang) * r * 0.85, 0.08, 0.92)
    });
  }
  // Outer ring of 9 seeds + lower post seeds
  for (let i = 0; i < 9; i++) {
    let ang = (i * 40 + 18 + random(-10, 10)) * (Math.PI / 180);
    let r = random(0.38, 0.45);
    seeds.push({
      u: constrain(0.5 + Math.cos(ang) * r * 1.05, 0.05, 0.95),
      v: constrain(0.44 + Math.sin(ang) * r * 0.88, 0.05, 0.88)
    });
  }
  // Lower post base seeds
  seeds.push({ u: 0.25, v: 0.91 });
  seeds.push({ u: 0.52, v: 0.92 });
  seeds.push({ u: 0.78, v: 0.91 });
  return seeds;
}

// ============================================================================
// MAIN DRAW LOOP
// ============================================================================
function draw() {
  translate(-width / 2, -height / 2);

  // 1. Render atmospheric dim corner, window light beam, and walnut bun foot
  renderDimCornerAndFoot();

  // 2. Build all 6 anatomical crazy-quilt upholstery zones (back-to-front painter's order)
  let zones = [
    buildCrazyQuiltZone("backrest", generateStratifiedSeeds(5, 4, 0.3), 0.92),
    buildCrazyQuiltZone("apron", generateStratifiedSeeds(6, 2, 0.28), 0.95),
    buildCrazyQuiltZone("seatTop", generateStratifiedSeeds(5, 3, 0.3), 1.02),
    buildCrazyQuiltZone("seatFront", generateStratifiedSeeds(5, 2, 0.28), 1.08),
    buildCrazyQuiltZone("armBarrel", generateStratifiedSeeds(4, 4, 0.28), 1.12),
    buildCrazyQuiltZone("armFace", generateScrollRadialSeeds(), 1.18)
  ];

  // 3. Render each zone's leather patches + deep tuck crevice shadows + overstitched seams
  for (let z of zones) {
    // Render all crazy-quilt leather patches in this zone
    for (let cell of z.cells) {
      renderLeatherPatch(cell, z.zoneId);
    }

    // Render all decorative Feather & Herringbone gold/ivory seams in this zone
    for (let seam of z.seams) {
      renderSeamOverstitching(seam);
    }
  }

  // 4. Render thick corded crazy-quilt leather piping along the major structural borders
  // A. Piping between Seat Top and Seat Front Bullnose
  let seatCrownPipe = [];
  for (let i = 0; i <= 24; i++) {
    let u = i / 24;
    let m = evalZone("seatFront", u, 0);
    seatCrownPipe.push([m.x, m.y, u, 0, m.nx, m.ny, m.nz, m.ao]);
  }
  renderPipedWelting(seatCrownPipe, 6.8);

  // B. Piping between Seat Front Bullnose and Lower Apron
  let apronTopPipe = [];
  for (let i = 0; i <= 24; i++) {
    let u = i / 24;
    let m = evalZone("seatFront", u, 1);
    apronTopPipe.push([m.x, m.y, u, 1, m.nx, m.ny, m.nz, m.ao]);
  }
  renderPipedWelting(apronTopPipe, 6.2);

  // C. Prominent foreground piping framing the entire Armrest Front Scroll (armFace perimeter)
  let scrollPerimeterPipe = [];
  // Left post up over the scroll dome and down the inner cheek
  for (let i = 0; i <= 14; i++) {
    let v = 1.0 - i / 14;
    let m = evalZone("armFace", 0, v);
    scrollPerimeterPipe.push([m.x, m.y, 0, v, m.nx, m.ny, m.nz, m.ao]);
  }
  for (let i = 1; i <= 16; i++) {
    let u = i / 16;
    let m = evalZone("armFace", u, 0);
    scrollPerimeterPipe.push([m.x, m.y, u, 0, m.nx, m.ny, m.nz, m.ao]);
  }
  for (let i = 1; i <= 14; i++) {
    let v = i / 14;
    let m = evalZone("armFace", 1, v);
    scrollPerimeterPipe.push([m.x, m.y, 1, v, m.nx, m.ny, m.nz, m.ao]);
  }
  renderPipedWelting(scrollPerimeterPipe, 8.2);

  // 5. Render the deep tufted central leather button on the foreground armrest scroll
  renderScrollCenterButton(238, 595);

  noLoop();
}

