// ============================================================================
// GEOMETRY & SHAPE HELPERS
// ============================================================================

function drawPolyShape(pts, curvature = 0.35, closed = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

function getEllipsePoints(cx, cy, rx, ry, n = 36, rotDeg = 0, wobble = 0) {
  let pts = [];
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  for (let i = 0; i < n; i++) {
    let a = (i / n) * 360;
    let rMod = wobble > 0 ? 1 + wobble * (noise(cx * 0.01 + cos(a) * 1.5, cy * 0.01 + sin(a) * 1.5) - 0.5) : 1;
    let lx = cos(a) * rx * rMod;
    let ly = sin(a) * ry * rMod;
    pts.push([cx + lx * c - ly * s, cy + lx * s + ly * c]);
  }
  return pts;
}

// Anatomical Alphonso Mango contour generator:
// Broad rounded left-top shoulder, sunken stem dimple, convex dorsal arch,
// distinct ventral sinus concavity, and rounded distal beak ("nak") on the right.
function getAlphonsoPoint(tDeg, cx, cy, rx, ry, tiltDeg = -8) {
  let a = tDeg;
  let ca = cos(a);
  let sa = sin(a);

  let x = ca * rx;
  let y = sa * ry;

  // 1. Plump upper-left shoulder (around 135..225 deg)
  let shoulderBump = exp(-pow(angleDiff(a, 195) / 52, 2));
  x -= shoulderBump * rx * 0.12;
  y -= shoulderBump * ry * 0.14;

  // 2. Stem cavity depression at upper-left (around 165 deg)
  let stemDimple = exp(-pow(angleDiff(a, 162) / 16, 2));
  x += stemDimple * rx * 0.08;
  y += stemDimple * ry * 0.09;

  // 3. Broad belly below shoulder (around 105 deg)
  let bellyFullness = exp(-pow(angleDiff(a, 108) / 48, 2));
  y += bellyFullness * ry * 0.12;

  // 4. Characteristic Alphonso ventral sinus indentation (around 42 deg, lower-right before beak)
  let sinusIndent = exp(-pow(angleDiff(a, 42) / 28, 2));
  y -= sinusIndent * ry * 0.19;

  // 5. Distal beak ("nak") protrusion at right-downward tip (around 8 deg)
  let beakTip = exp(-pow(angleDiff(a, 6) / 26, 2));
  x += beakTip * rx * 0.14;
  y += beakTip * ry * 0.06;

  // 6. Dorsal crown arch (around -70 / 290 deg)
  let dorsalArch = exp(-pow(angleDiff(a, 285) / 55, 2));
  y -= dorsalArch * ry * 0.07;

  let ct = cos(tiltDeg);
  let st = sin(tiltDeg);
  return [
    cx + x * ct - y * st,
    cy + x * st + y * ct
  ];
}

function getAlphonsoContour(cx, cy, rx, ry, tiltDeg = -8, n = 48) {
  let pts = [];
  for (let i = 0; i < n; i++) {
    let a = (i / n) * 360;
    pts.push(getAlphonsoPoint(a, cx, cy, rx, ry, tiltDeg));
  }
  return pts;
}

function angleDiff(a, b) {
  let d = ((a - b + 540) % 360) - 180;
  return d;
}

// ============================================================================
//HYPERREAL WATER DROPLET / JUICE BEAD HELPER
// ============================================================================

function drawHyperrealDroplet(x, y, r, baseCol, shadowCol, tintCol) {
  // Cast shadow on lower-right
  brush.noStroke();
  brush.noFill();
  brush.wash(shadowCol, 110);
  drawPolyShape(getEllipsePoints(x + r * 0.28, y + r * 0.32, r * 0.95, r * 0.72, 16, 20), 0.4, true);

  // Droplet body base
  brush.wash(baseCol, 165);
  drawPolyShape(getEllipsePoints(x, y, r, r * 0.82, 18, -12), 0.4, true);

  // Internal dark upper-left refraction crescent
  brush.wash(shadowCol, 130);
  drawPolyShape(getEllipsePoints(x - r * 0.18, y - r * 0.18, r * 0.65, r * 0.48, 14, -25), 0.4, true);

  // Luminous lower-right transmitted caustic glow
  brush.wash(tintCol, 210);
  drawPolyShape(getEllipsePoints(x + r * 0.2, y + r * 0.2, r * 0.58, r * 0.42, 14, -20), 0.4, true);
  brush.noWash();

  // Crisp white specular highlight at upper-left & secondary rim glint
  brush.set("glint", "#ffffff", max(0.28, r * 0.08));
  brush.line(x - r * 0.38, y - r * 0.28, x - r * 0.12, y - r * 0.42);
  brush.set("rotring", "#ffffff", 0.35);
  brush.arc(x, y, r * 0.75, 20, 75);
}

// ============================================================================
// 1. SCROLL MOUNT & TEXTILE BACKGROUND
// ============================================================================

function drawScrollMount(sx, sy, sw, sh) {
  // Subtle raw-silk weave on left and right margins outside the scroll
  brush.noFill();
  brush.noWash();
  for (let i = 0; i < 95; i++) {
    let x = i < 48 ? map(i, 0, 47, 8, sx - 6) : map(i, 48, 94, sx + sw + 6, width - 8);
    brush.set("2H", i % 2 === 0 ? "#dfd4c2" : "#f5eee3", 0.35);
    brush.line(x, 10, x, height - 10);
  }
  for (let j = 0; j < 70; j++) {
    let y = map(j, 0, 69, 12, height - 12);
    brush.set("2H", "#e2d8c7", 0.28);
    brush.line(8, y, sx - 4, y);
    brush.line(sx + sw + 4, y, width - 8, y);
  }

  // Soft layered drop shadow behind the scroll
  brush.noStroke();
  for (let k = 4; k >= 1; k--) {
    brush.wash("#b9ae9e", 38);
    brush.rect(sx + k * 3.5, sy + k * 3.5, sw, sh, "corner");
  }

  // Conch-white paper base of the scroll
  brush.wash("#fbf7ef", 255);
  brush.rect(sx, sy, sw, sh, "corner");
  brush.noWash();
}

// ============================================================================
// 2. FLAT RITUAL BORDERS (VERMILION, LAMP-BLACK, CONCH-WHITE, LOTUS & LEAF)
// ============================================================================

function drawRitualBorders(sx, sy, sw, sh, vW, hH, px, pw, panelYs, ph) {
  const vermilion = "#dc5642";
  const vermilionLight = "#e7725e";
  const lampBlack = "#1c1a1e";
  const conchWhite = "#fcf8f0";
  const pastelLotus = "#f4b9b4";
  const pastelLeaf = "#b6d1b0";
  const pastelOchre = "#ecc97c";

  brush.noFill();
  brush.noStroke();

  // --- A. Base Flat Fills for Vertical & Horizontal Borders ---
  // Left & Right vertical strips
  brush.wash(vermilion, 252);
  brush.rect(sx, sy, vW, sh, "corner");
  brush.rect(sx + sw - vW, sy, vW, sh, "corner");

  // 5 Horizontal divider bands
  const hBandYs = [
    sy,
    panelYs[0] + ph,
    panelYs[1] + ph,
    panelYs[2] + ph,
    panelYs[3] + ph
  ];
  for (let by of hBandYs) {
    brush.wash(vermilion, 252);
    brush.rect(px, by, pw, hH, "corner");
  }

  // Outer & Inner Lamp-Black Guard Strips on Left & Right Borders
  const guardW = 11;
  brush.wash(lampBlack, 252);
  // Left outer & inner guard rails
  brush.rect(sx, sy, guardW, sh, "corner");
  brush.rect(sx + vW - guardW, sy, guardW, sh, "corner");
  // Right inner & outer guard rails
  brush.rect(sx + sw - vW, sy, guardW, sh, "corner");
  brush.rect(sx + sw - guardW, sy, guardW, sh, "corner");

  // Top & Bottom Lamp-Black Guard Strips on each of the 5 Horizontal Bands
  const hGuard = 5.5;
  for (let by of hBandYs) {
    brush.wash(lampBlack, 252);
    brush.rect(px, by, pw, hGuard, "corner");
    brush.rect(px, by + hH - hGuard, pw, hGuard, "corner");
  }

  // 10 Corner/Junction Blocks (where 2 vertical borders meet 5 horizontal bands)
  for (let by of hBandYs) {
    brush.wash(lampBlack, 255);
    brush.rect(sx, by, vW, hH, "corner");
    brush.rect(sx + sw - vW, by, vW, hH, "corner");
  }
  brush.noWash();

  // --- B. Repeating Horizontal Leaf & Lotus-Bud Motifs ---
  const numHRepeats = 16;
  const stepX = pw / numHRepeats; // 800 / 16 = 50px per motif unit

  for (let bIdx = 0; bIdx < hBandYs.length; bIdx++) {
    let by = hBandYs[bIdx];
    let cy = by + hH / 2;

    // 1. Batch lamp-black interstitial pockets along the vine
    brush.noStroke();
    brush.wash(lampBlack, 235);
    for (let i = 0; i < numHRepeats; i++) {
      let ux = px + i * stepX;
      let flip = (i + bIdx) % 2 === 0 ? 1 : -1;
      drawPolyShape([
        [ux + 6, cy - flip * 7],
        [ux + 16, cy - flip * 9.5],
        [ux + 24, cy - flip * 4],
        [ux + 14, cy - flip * 2]
      ], 0.3, true);
    }

    // 2. Batch Conch-White Lotus Buds & Stylized Leaves
    brush.wash(conchWhite, 252);
    for (let i = 0; i < numHRepeats; i++) {
      let ux = px + i * stepX;
      let flip = (i + bIdx) % 2 === 0 ? 1 : -1;

      // Pointed 3-petal Lotus Bud on first half of repeat
      let bx = ux + stepX * 0.28;
      let byOff = cy + flip * 2.2;
      drawHorizontalLotusBud(bx, byOff, 14, 7.5, 1);

      // Curved Pipal/Mango Leaf on second half of repeat
      let lx = ux + stepX * 0.75;
      let lyOff = cy - flip * 2.2;
      drawHorizontalRitualLeaf(lx, lyOff, 15, 7, -flip);
    }

    // 3. Batch Pastel Rose & Pastel Celadon Inner Fills inside buds & leaves
    brush.wash(pastelLotus, 240);
    for (let i = 0; i < numHRepeats; i++) {
      let ux = px + i * stepX;
      let flip = (i + bIdx) % 2 === 0 ? 1 : -1;
      let bx = ux + stepX * 0.28;
      let byOff = cy + flip * 2.2;
      drawPolyShape([
        [bx - 4, byOff],
        [bx + 2, byOff - 3.2],
        [bx + 9, byOff],
        [bx + 2, byOff + 3.2]
      ], 0.35, true);
    }

    brush.wash(pastelLeaf, 235);
    for (let i = 0; i < numHRepeats; i++) {
      let ux = px + i * stepX;
      let flip = (i + bIdx) % 2 === 0 ? 1 : -1;
      let lx = ux + stepX * 0.75;
      let lyOff = cy - flip * 2.2;
      drawPolyShape([
        [lx - 5, lyOff],
        [lx + 1, lyOff - 2.6],
        [lx + 7, lyOff],
        [lx + 1, lyOff + 2.6]
      ], 0.35, true);
    }

    // 4. Conch-white pearl beads along the top and bottom black guard strips
    brush.wash(conchWhite, 245);
    for (let i = 0; i < numHRepeats * 2; i++) {
      let dotX = px + (i + 0.5) * (pw / (numHRepeats * 2));
      drawPolyShape(getEllipsePoints(dotX, by + hGuard * 0.5, 2.2, 1.5, 8), 0.3, true);
      drawPolyShape(getEllipsePoints(dotX, by + hH - hGuard * 0.5, 2.2, 1.5, 8), 0.3, true);
    }
    brush.noWash();

    // 5. Confident Black Pen Outlines for the vine, buds, and leaves
    brush.set("rotring", lampBlack, 0.42);
    let vinePts = [];
    for (let i = 0; i <= numHRepeats * 2; i++) {
      let vx = px + i * (stepX / 2);
      let vy = cy + ((i + bIdx) % 2 === 0 ? -4.2 : 4.2);
      vinePts.push([vx, vy]);
    }
    brush.spline(vinePts, 0.5);

    for (let i = 0; i < numHRepeats; i++) {
      let ux = px + i * stepX;
      let flip = (i + bIdx) % 2 === 0 ? 1 : -1;
      let bx = ux + stepX * 0.28;
      let byOff = cy + flip * 2.2;
      let lx = ux + stepX * 0.75;
      let lyOff = cy - flip * 2.2;

      brush.set("rotring", lampBlack, 0.4);
      strokeHorizontalLotusBud(bx, byOff, 14, 7.5);
      strokeHorizontalRitualLeaf(lx, lyOff, 15, 7, -flip);
    }
  }

  // --- C. Repeating Vertical Leaf & Lotus-Bud Motifs (Left & Right Columns) ---
  const vCols = [sx + vW / 2, sx + sw - vW / 2];
  const numVRepeats = 5;
  const stepY = ph / numVRepeats; // 249 / 5 = 49.8px

  for (let colX of vCols) {
    for (let pIdx = 0; pIdx < panelYs.length; pIdx++) {
      let py = panelYs[pIdx];

      // 1. Lamp-black negative space teardrops
      brush.noStroke();
      brush.wash(lampBlack, 235);
      for (let j = 0; j < numVRepeats; j++) {
        let uy = py + j * stepY;
        let flip = j % 2 === 0 ? 1 : -1;
        drawPolyShape([
          [colX - flip * 16, uy + 8],
          [colX - flip * 20, uy + 22],
          [colX - flip * 10, uy + 30],
          [colX - flip * 7, uy + 16]
        ], 0.35, true);
      }

      // 2. Conch-white vertical Lotus Buds & Paired Leaves
      brush.wash(conchWhite, 252);
      for (let j = 0; j < numVRepeats; j++) {
        let uy = py + j * stepY;
        let flip = j % 2 === 0 ? 1 : -1;
        drawVerticalLotusBud(colX + flip * 5, uy + stepY * 0.3, 11, 18);
        drawVerticalRitualLeaf(colX - flip * 6, uy + stepY * 0.74, 10, 17, flip);
      }

      // 3. PastelLotus & PastelOchre inner fills
      brush.wash(pastelLotus, 240);
      for (let j = 0; j < numVRepeats; j++) {
        let uy = py + j * stepY;
        let flip = j % 2 === 0 ? 1 : -1;
        let bx = colX + flip * 5;
        let by = uy + stepY * 0.3;
        drawPolyShape([
          [bx, by + 5],
          [bx - 4.5, by - 1],
          [bx, by - 9],
          [bx + 4.5, by - 1]
        ], 0.35, true);
      }

      brush.wash(pastelOchre, 235);
      for (let j = 0; j < numVRepeats; j++) {
        let uy = py + j * stepY;
        let flip = j % 2 === 0 ? 1 : -1;
        let lx = colX - flip * 6;
        let ly = uy + stepY * 0.74;
        drawPolyShape([
          [lx, ly + 5],
          [lx - 3.5, ly - 1],
          [lx, ly - 7],
          [lx + 3.5, ly - 1]
        ], 0.35, true);
      }

      // 4. Conch-white pearls in left/right guard rails
      brush.wash(conchWhite, 245);
      let leftGuardX = colX - vW / 2 + guardW * 0.5;
      let rightGuardX = colX + vW / 2 - guardW * 0.5;
      for (let j = 0; j < numVRepeats * 2; j++) {
        let dotY = py + (j + 0.5) * (ph / (numVRepeats * 2));
        drawPolyShape(getEllipsePoints(leftGuardX, dotY, 1.8, 2.4, 8), 0.3, true);
        drawPolyShape(getEllipsePoints(rightGuardX, dotY, 1.8, 2.4, 8), 0.3, true);
      }
      brush.noWash();

      // 5. Confident Black Pen Outlines on Vertical Vine
      brush.set("rotring", lampBlack, 0.44);
      let vVine = [];
      for (let j = 0; j <= numVRepeats * 2; j++) {
        let vy = py + j * (stepY / 2);
        let vx = colX + (j % 2 === 0 ? -7 : 7);
        vVine.push([vx, vy]);
      }
      brush.spline(vVine, 0.5);

      for (let j = 0; j < numVRepeats; j++) {
        let uy = py + j * stepY;
        let flip = j % 2 === 0 ? 1 : -1;
        brush.set("rotring", lampBlack, 0.42);
        strokeVerticalLotusBud(colX + flip * 5, uy + stepY * 0.3, 11, 18);
        strokeVerticalRitualLeaf(colX - flip * 6, uy + stepY * 0.74, 10, 17, flip);
      }
    }
  }

  // --- D. 10 Corner / Junction Lotus Rosettes ---
  for (let by of hBandYs) {
    drawCornerRosette(sx + vW / 2, by + hH / 2, vW, hH, vermilionLight, conchWhite, pastelLotus, lampBlack);
    drawCornerRosette(sx + sw - vW / 2, by + hH / 2, vW, hH, vermilionLight, conchWhite, pastelLotus, lampBlack);
  }

  // --- E. Crisp Architectural Pen Framing Lines ---
  brush.noFill();
  brush.noWash();
  brush.set("rotring", lampBlack, 0.75);
  brush.rect(sx, sy, sw, sh, "corner");
  brush.rect(sx + guardW, sy, sw - guardW * 2, sh, "corner");

  for (let pIdx = 0; pIdx < panelYs.length; pIdx++) {
    let py = panelYs[pIdx];
    // Inner conch-white hairline buffer + double black pen frame around each watercolor panel
    brush.set("rotring", conchWhite, 0.9);
    brush.rect(px + 2, py + 2, pw - 4, ph - 4, "corner");
    brush.set("rotring", lampBlack, 0.7);
    brush.rect(px, py, pw, ph, "corner");
    brush.set("rotring", lampBlack, 0.38);
    brush.rect(px + 4.5, py + 4.5, pw - 9, ph - 9, "corner");
  }
}

function drawHorizontalLotusBud(cx, cy, len, wid, dir) {
  let d = dir;
  // Outer pointed lotus bud silhouette
  drawPolyShape([
    [cx - d * len * 0.55, cy],
    [cx - d * len * 0.2, cy - wid * 0.85],
    [cx + d * len * 0.35, cy - wid * 0.45],
    [cx + d * len * 0.75, cy],
    [cx + d * len * 0.35, cy + wid * 0.45],
    [cx - d * len * 0.2, cy + wid * 0.85]
  ], 0.32, true);
}

function strokeHorizontalLotusBud(cx, cy, len, wid) {
  drawPolyShape([
    [cx - len * 0.55, cy],
    [cx - len * 0.2, cy - wid * 0.85],
    [cx + len * 0.35, cy - wid * 0.45],
    [cx + len * 0.75, cy],
    [cx + len * 0.35, cy + wid * 0.45],
    [cx - len * 0.2, cy + wid * 0.85]
  ], 0.32, true);
  // Central petal ribs
  brush.line(cx - len * 0.45, cy, cx + len * 0.68, cy);
  brush.line(cx - len * 0.3, cy - wid * 0.35, cx + len * 0.35, cy - wid * 0.15);
  brush.line(cx - len * 0.3, cy + wid * 0.35, cx + len * 0.35, cy + wid * 0.15);
}

function drawHorizontalRitualLeaf(cx, cy, len, wid, tiltSign) {
  let t = tiltSign * 2.5;
  drawPolyShape([
    [cx - len * 0.6, cy + t],
    [cx - len * 0.1, cy - wid * 0.8],
    [cx + len * 0.65, cy - t],
    [cx - len * 0.1, cy + wid * 0.8]
  ], 0.38, true);
}

function strokeHorizontalRitualLeaf(cx, cy, len, wid, tiltSign) {
  let t = tiltSign * 2.5;
  drawPolyShape([
    [cx - len * 0.6, cy + t],
    [cx - len * 0.1, cy - wid * 0.8],
    [cx + len * 0.65, cy - t],
    [cx - len * 0.1, cy + wid * 0.8]
  ], 0.38, true);
  brush.line(cx - len * 0.55, cy + t, cx + len * 0.55, cy - t);
}

function drawVerticalLotusBud(cx, cy, wid, len) {
  drawPolyShape([
    [cx, cy + len * 0.52],
    [cx - wid * 0.82, cy + len * 0.15],
    [cx - wid * 0.45, cy - len * 0.32],
    [cx, cy - len * 0.68],
    [cx + wid * 0.45, cy - len * 0.32],
    [cx + wid * 0.82, cy + len * 0.15]
  ], 0.32, true);
}

function strokeVerticalLotusBud(cx, cy, wid, len) {
  drawPolyShape([
    [cx, cy + len * 0.52],
    [cx - wid * 0.82, cy + len * 0.15],
    [cx - wid * 0.45, cy - len * 0.32],
    [cx, cy - len * 0.68],
    [cx + wid * 0.45, cy - len * 0.32],
    [cx + wid * 0.82, cy + len * 0.15]
  ], 0.32, true);
  brush.line(cx, cy + len * 0.45, cx, cy - len * 0.6);
  brush.line(cx - wid * 0.35, cy + len * 0.2, cx - wid * 0.18, cy - len * 0.28);
  brush.line(cx + wid * 0.35, cy + len * 0.2, cx + wid * 0.18, cy - len * 0.28);
}

function drawVerticalRitualLeaf(cx, cy, wid, len, flip) {
  let t = flip * 2.5;
  drawPolyShape([
    [cx + t, cy + len * 0.55],
    [cx - wid * 0.78, cy],
    [cx - t, cy - len * 0.55],
    [cx + wid * 0.78, cy]
  ], 0.38, true);
}

function strokeVerticalRitualLeaf(cx, cy, wid, len, flip) {
  let t = flip * 2.5;
  drawPolyShape([
    [cx + t, cy + len * 0.55],
    [cx - wid * 0.78, cy],
    [cx - t, cy - len * 0.55],
    [cx + wid * 0.78, cy]
  ], 0.38, true);
  brush.line(cx + t, cy + len * 0.5, cx - t, cy - len * 0.5);
}

function drawCornerRosette(cx, cy, bw, bh, vermCol, whiteCol, pinkCol, blackCol) {
  brush.noStroke();
  // Inner vermilion cartouche
  brush.wash(vermCol, 245);
  brush.rect(cx - bw * 0.34, cy - bh * 0.34, bw * 0.68, bh * 0.68, "corner");

  // 8-petal flat conch-white lotus rosette
  brush.wash(whiteCol, 252);
  let pts = [];
  for (let i = 0; i < 16; i++) {
    let a = i * 22.5;
    let r = i % 2 === 0 ? 11.5 : 5.2;
    let rx = r * 1.35;
    let ry = r * 0.88;
    pts.push([cx + cos(a) * rx, cy + sin(a) * ry]);
  }
  drawPolyShape(pts, 0.25, true);

  // Center pink & black lotus core
  brush.wash(pinkCol, 250);
  drawPolyShape(getEllipsePoints(cx, cy, 6.2, 4.5, 12), 0.3, true);
  brush.wash(blackCol, 250);
  drawPolyShape(getEllipsePoints(cx, cy, 2.4, 1.8, 10), 0.3, true);
  brush.noWash();

  brush.set("rotring", whiteCol, 0.38);
  brush.rect(cx - bw * 0.36, cy - bh * 0.36, bw * 0.72, bh * 0.72, "corner");
  brush.set("rotring", blackCol, 0.38);
  drawPolyShape(pts, 0.25, true);
}

// ============================================================================
// PANEL 1: WHOLE ALPHONSO MANGO ON A LEAF
// ============================================================================

function drawPanel1_WholeMango(px, py, pw, ph) {
  brush.clip([px, py, px + pw, py + ph]);

  // --- 1. Soft Pastel Studio Watercolor Ground ---
  brush.noStroke();
  brush.fillBleed(0.24, "out");
  brush.fillTexture(0.38, 0.18);

  brush.fill("#f5efe4", 190);
  brush.rect(px, py, pw, ph, "corner");

  // Soft pastel celadon-mint atmosphere on upper-right & dusty lavender-grey table tone below
  brush.fill("#e1ece2", 115);
  drawPolyShape(getEllipsePoints(px + pw * 0.68, py + ph * 0.34, 290, 95, 28, -5, 0.08), 0.4, true);

  brush.fill("#fbe9dc", 95);
  drawPolyShape(getEllipsePoints(px + pw * 0.26, py + ph * 0.3, 230, 85, 24, 6, 0.08), 0.4, true);

  brush.fill("#d5d8e2", 110);
  drawPolyShape(getEllipsePoints(px + pw * 0.52, py + ph * 0.84, 380, 62, 28, 0, 0.05), 0.4, true);

  // --- 2. Hyperreal Banana / Mango Leaf ---
  // Sweeping across the lower two-thirds of the panel
  const leafCx = px + pw * 0.52;
  const leafCy = py + ph * 0.70;

  // Leaf cast shadow on the pastel ground
  brush.fillBleed(0.18, "out");
  brush.fill("#8c949e", 115);
  drawPolyShape([
    [px + 85, leafCy + 16],
    [px + 280, leafCy - 18],
    [px + 560, leafCy - 14],
    [px + 735, leafCy + 18],
    [px + 650, leafCy + 54],
    [px + 380, leafCy + 64],
    [px + 145, leafCy + 44]
  ], 0.38, true);

  // Main banana leaf blade silhouette (with a natural tropical split near right end)
  const leafBlade = [
    [px + 65, leafCy + 4],
    [px + 170, leafCy - 38],
    [px + 340, leafCy - 56],
    [px + 530, leafCy - 52],
    [px + 655, leafCy - 34],
    [px + 625, leafCy - 12], // tropical split notch
    [px + 685, leafCy - 22],
    [px + 748, leafCy + 6],
    [px + 680, leafCy + 36],
    [px + 520, leafCy + 52],
    [px + 330, leafCy + 54],
    [px + 165, leafCy + 34]
  ];

  // Layered leaf watercolor washes: pastel sage -> sunlit chartreuse -> deep viridian shadow
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.32, 0.22);
  brush.fill("#84b078", 210);
  drawPolyShape(leafBlade, 0.32, true);

  // Sunlit chartreuse upper half of leaf
  brush.fill("#b4d484", 150);
  drawPolyShape([
    [px + 95, leafCy - 2],
    [px + 220, leafCy - 36],
    [px + 450, leafCy - 48],
    [px + 635, leafCy - 28],
    [px + 580, leafCy - 4],
    [px + 320, leafCy - 6]
  ], 0.35, true);

  // Cool blue-green shaded lower half of leaf
  brush.fill("#4f7d58", 155);
  drawPolyShape([
    [px + 110, leafCy + 8],
    [px + 350, leafCy + 4],
    [px + 660, leafCy + 2],
    [px + 725, leafCy + 12],
    [px + 645, leafCy + 36],
    [px + 420, leafCy + 48],
    [px + 185, leafCy + 30]
  ], 0.35, true);

  // Glossy sky-blue & white specular sheen across the arched left/right lobes of the leaf
  brush.fill("#e6f2ea", 130);
  drawPolyShape(getEllipsePoints(px + 245, leafCy - 22, 75, 16, 18, -8), 0.4, true);
  drawPolyShape(getEllipsePoints(px + 615, leafCy - 16, 62, 14, 18, 6), 0.4, true);
  brush.noFill();

  // Parallel lateral leaf venation & central midrib
  for (let i = 0; i < 68; i++) {
    let vx = map(i, 0, 67, px + 95, px + 710);
    let midY = leafCy + sin(map(i, 0, 67, -20, 190)) * 7;
    let spanTop = 44 * sin(map(i, 0, 67, 12, 168));
    let spanBot = 42 * sin(map(i, 0, 67, 12, 168));

    brush.set("fiber", i % 2 === 0 ? "#5a875a" : "#cde3a8", 0.32);
    brush.line(vx, midY - 1.5, vx + 24, midY - spanTop);
    brush.set("fiber", i % 2 === 0 ? "#3c6344" : "#9bc284", 0.32);
    brush.line(vx, midY + 1.5, vx + 20, midY + spanBot);
  }

  // Prominent pale-celery central midrib
  let midribPts = [];
  for (let i = 0; i <= 16; i++) {
    let mx = map(i, 0, 16, px + 60, px + 742);
    let my = leafCy + sin(map(i, 0, 16, -20, 190)) * 7;
    midribPts.push([mx, my]);
  }
  brush.set("glint", "#e4efc4", 1.15);
  brush.spline(midribPts, 0.4);
  brush.set("fiber", "#5c7d4e", 0.45);
  brush.spline(midribPts.map(p => [p[0], p[1] + 2.2]), 0.4);

  // Crisp leaf margin contour
  brush.set("2B", "#3a5c3e", 0.42);
  drawPolyShape(leafBlade, 0.32, true);

  // --- 3. Deep Cast Shadow & Warm Caustic Bounce under Mango ---
  const mCx = px + pw * 0.49;
  const mCy = py + ph * 0.46;
  const mRx = 132;
  const mRy = 86;
  const mTilt = -7;

  brush.noStroke();
  brush.fillBleed(0.16, "out");
  // Warm golden-amber caustic transmitted light on the right side of the shadow
  brush.fill("#c78826", 145);
  drawPolyShape(getEllipsePoints(mCx + 42, mCy + 76, 118, 25, 24, 2), 0.4, true);

  // Deep forest-indigo occlusion shadow directly under the mango belly
  brush.fill("#223829", 215);
  drawPolyShape(getEllipsePoints(mCx + 6, mCy + 72, 108, 22, 24, -2), 0.4, true);
  brush.fill("#142419", 230);
  drawPolyShape(getEllipsePoints(mCx - 6, mCy + 69, 82, 13, 20, -3), 0.4, true);

  // --- 4. Hyperreal Whole Alphonso Mango ---
  // Step A: Base silhouette in luminous chrome yellow
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.26, 0.12);

  const mainContour = getAlphonsoContour(mCx, mCy, mRx, mRy, mTilt, 52);
  brush.fill("#f9bc28", 242);
  drawPolyShape(mainContour, 0.35, true);

  // Step B: Pastel lime-chartreuse transition toward the right beak ("nak")
  brush.fillBleed(0.22, "in");
  brush.fill("#d4d44c", 165);
  drawPolyShape(getEllipsePoints(mCx + 76, mCy + 12, 54, 42, 24, 15), 0.4, true);
  brush.fill("#b2c766", 140);
  drawPolyShape(getEllipsePoints(mCx + 104, mCy + 10, 32, 24, 20, 18), 0.4, true);

  // Step C: Multi-layered Blushing Orange-Red on the upper-left shoulder
  const blushLayers = [
    { dx: -18, dy: -8, rx: 108, ry: 72, col: "#f79c38", op: 155 },
    { dx: -32, dy: -14, rx: 95, ry: 64, col: "#f37d38", op: 165 },
    { dx: -46, dy: -20, rx: 80, ry: 54, col: "#e85c38", op: 175 },
    { dx: -58, dy: -24, rx: 64, ry: 44, col: "#d94330", op: 170 },
    { dx: -68, dy: -26, rx: 45, ry: 32, col: "#c43528", op: 140 }
  ];
  for (let bl of blushLayers) {
    brush.fill(bl.col, bl.op);
    drawPolyShape(getEllipsePoints(mCx + bl.dx, mCy + bl.dy, bl.rx, bl.ry, 26, -18), 0.4, true);
  }

  // Step D: Intense glowing cadmium-yellow core highlight on the mid-belly
  brush.fill("#fde258", 170);
  drawPolyShape(getEllipsePoints(mCx + 18, mCy - 6, 68, 46, 24, -8), 0.4, true);
  brush.noFill();

  // Step E: Photographic 3D Cross-Contour Glazing (85 meridian strokes from shoulder to beak)
  for (let i = 0; i < 85; i++) {
    let frac = i / 84;
    // Latitudinal band from top (-0.85) to bottom (+0.88)
    let lat = map(frac, 0, 1, -0.86, 0.88);
    let yOff = lat * mRy * 0.88;
    let xSpan = sqrt(max(0.05, 1 - lat * lat)) * mRx * 0.92;

    // Color shifts smoothly from deep coral-red at top-left to chrome yellow at mid to green-gold at right
    let segs = 3;
    for (let s = 0; s < segs; s++) {
      let x0 = map(s, 0, segs, -xSpan, xSpan);
      let x1 = map(s + 1, 0, segs, -xSpan, xSpan);
      let xm = (x0 + x1) * 0.5;

      let col = "#f8b828";
      if (xm < -25 && lat < 0.25) {
        col = lat < -0.3 ? "#dc4b34" : "#f0723c";
      } else if (xm > 55) {
        col = xm > 85 ? "#bcc95e" : "#e5cf3c";
      } else if (lat > 0.58) {
        col = "#d89224"; // warm form shadow on lower belly
      } else if (lat < -0.35 && xm > -25 && xm < 45) {
        col = "#fddf62"; // sunlit upper crown
      }

      let archY0 = yOff - (1 - pow(x0 / (mRx + 1), 2)) * lat * 12;
      let archY1 = yOff - (1 - pow(x1 / (mRx + 1), 2)) * lat * 12;

      let ct = cos(mTilt), st = sin(mTilt);
      let p0 = [mCx + x0 * ct - archY0 * st, mCy + x0 * st + archY0 * ct];
      let p1 = [mCx + x1 * ct - archY1 * st, mCy + x1 * st + archY1 * ct];

      brush.set("glaze", col, 0.85);
      brush.line(p0[0], p0[1], p1[0], p1[1]);
    }
  }

  // Step F: True Reflected Green Bounce Light along the lower contour of the mango
  let bouncePts = [];
  for (let a = 32; a <= 152; a += 8) {
    let p = getAlphonsoPoint(a, mCx, mCy, mRx * 0.94, mRy * 0.93, mTilt);
    bouncePts.push(p);
  }
  brush.set("softBlend", "#c2deb4", 1.35);
  brush.spline(bouncePts, 0.45);
  brush.set("softBlend", "#e8f2c8", 0.75);
  brush.spline(bouncePts, 0.45);

  // Step G: Skin Lenticels (190 tiny organic pores following 3D curvature)
  for (let i = 0; i < 190; i++) {
    let u = random(-0.92, 0.92);
    let v = random(-0.88, 0.88);
    if (u * u + v * v > 0.86) continue;
    let lx = u * mRx;
    let ly = v * mRy;
    let ct = cos(mTilt), st = sin(mTilt);
    let pxDot = mCx + lx * ct - ly * st;
    let pyDot = mCy + lx * st + ly * ct;

    // Pores in red shoulder are pale yellow-cream; pores in yellow/green zone are russet-olive
    let poreCol = (u < -0.15 && v < 0.25) ? "#fff0b3" : (u > 0.45 ? "#7a8432" : "#c76b24");
    brush.set("rotring", poreCol, random(0.24, 0.42));
    brush.line(pxDot, pyDot, pxDot + 0.8, pyDot + 0.4);
  }

  // Step H: Stem Cavity, Woody Pedicel & Oozing Sap Droplet
  const stemPos = getAlphonsoPoint(162, mCx, mCy, mRx * 0.82, mRy * 0.82, mTilt);
  const sx0 = stemPos[0] + 10;
  const sy0 = stemPos[1] + 4;

  // Shaded cavity depression
  brush.noStroke();
  brush.wash("#8c2d1e", 180);
  drawPolyShape(getEllipsePoints(sx0, sy0, 14, 9, 14, -35), 0.4, true);
  brush.wash("#4f4a28", 210);
  drawPolyShape(getEllipsePoints(sx0, sy0, 8, 5, 12, -35), 0.4, true);
  brush.noWash();

  // Radial skin creases around stem cavity
  for (let k = 0; k < 9; k++) {
    let ca = map(k, 0, 8, -110, 80);
    brush.set("fiber", "#782418", 0.38);
    brush.line(sx0 + cos(ca) * 5, sy0 + sin(ca) * 4, sx0 + cos(ca) * 18, sy0 + sin(ca) * 14);
  }

  // Short woody stem stub
  brush.noStroke();
  brush.wash("#595232", 245);
  drawPolyShape([
    [sx0 - 3, sy0 + 2],
    [sx0 - 19, sy0 - 11],
    [sx0 - 14, sy0 - 17],
    [sx0 + 3, sy0 - 4]
  ], 0.25, true);
  brush.wash("#8c8253", 220);
  drawPolyShape(getEllipsePoints(sx0 - 16.5, sy0 - 14, 4.2, 2.5, 10, -40), 0.3, true);
  brush.noWash();

  // Step I: True Curved Studio Window Reflection on the Upper Shoulder
  // Four perspective-warped panes of cool sky-white light with soft edges
  const winPanes = [
    [[-58, -46], [-28, -56], [-22, -38], [-52, -28]],
    [[-22, -58], [10, -62], [14, -44], [-16, -40]],
    [[-50, -22], [-20, -32], [-15, -16], [-44, -8]],
    [[-14, -34], [16, -38], [20, -22], [-10, -18]]
  ];
  brush.noStroke();
  for (let pane of winPanes) {
    let worldPane = pane.map(pt => [mCx + pt[0], mCy + pt[1]]);
    brush.wash("#e6f4ff", 115);
    drawPolyShape(worldPane, 0.32, true);
    let innerPane = pane.map(pt => [mCx + pt[0] * 0.96, mCy + pt[1] * 0.96]);
    brush.wash("#ffffff", 185);
    drawPolyShape(innerPane, 0.32, true);
  }
  brush.noWash();

  // Secondary wet glint along the dorsal arch and beak
  brush.set("glint", "#fff9d6", 0.75);
  brush.spline([
    [mCx + 28, mCy - 56],
    [mCx + 68, mCy - 38],
    [mCx + 102, mCy - 12]
  ], 0.45);

  // Crisp botanical contour refinement on the mango
  brush.set("2B", "#6e2c1c", 0.38);
  drawPolyShape(mainContour, 0.35, true);

  // Step J: Glistening Sap & Dew Droplets on Fruit and Leaf
  drawHyperrealDroplet(sx0 + 6, sy0 + 12, 6.5, "#f7a854", "#6e2214", "#ffffff");
  drawHyperrealDroplet(mCx - 12, mCy + 18, 5.2, "#f8b434", "#9c4416", "#fff8c4");
  drawHyperrealDroplet(px + 285, leafCy + 18, 6.0, "#8eb882", "#2b4d32", "#e8f7d4");
  drawHyperrealDroplet(px + 635, leafCy + 8, 4.8, "#8eb882", "#2b4d32", "#e8f7d4");

  brush.noClip();
}

// ============================================================================
// PANEL 2: THE FIRST SLICE (CUT MANGO, SCORED CHEEK & STEEL KNIFE)
// ============================================================================

function drawPanel2_FirstSlice(px, py, pw, ph) {
  brush.clip([px, py, px + pw, py + ph]);

  // --- 1. Soft Pastel Studio Ground ---
  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.35, 0.16);

  brush.fill("#f7f1e8", 195);
  brush.rect(px, py, pw, ph, "corner");

  brush.fill("#fce4d6", 105);
  drawPolyShape(getEllipsePoints(px + pw * 0.32, py + ph * 0.38, 250, 88, 24, -4, 0.06), 0.4, true);

  brush.fill("#e2eaf2", 120);
  drawPolyShape(getEllipsePoints(px + pw * 0.74, py + ph * 0.44, 240, 92, 24, 5, 0.06), 0.4, true);

  brush.fill("#d3d8e2", 115);
  drawPolyShape(getEllipsePoints(px + pw * 0.50, py + ph * 0.82, 390, 58, 26, 0, 0.05), 0.4, true);

  // --- 2. Left-Center: The Cut Alphonso Mango (Showing Exterior Blush + Wet Cut Plane) ---
  const m1Cx = px + 235;
  const m1Cy = py + 122;

  // Cast shadow + glowing orange juice puddle under the cut mango
  brush.fillBleed(0.16, "out");
  brush.fill("#d98722", 145);
  drawPolyShape(getEllipsePoints(m1Cx + 28, m1Cy + 68, 112, 24, 22, 4), 0.4, true);
  brush.fill("#2b2933", 210);
  drawPolyShape(getEllipsePoints(m1Cx - 8, m1Cy + 64, 96, 19, 22, -2), 0.4, true);

  // Exterior left/top skin of the cut mango
  brush.fillBleed(0.10, "in");
  const cutMangoBody = getAlphonsoContour(m1Cx, m1Cy, 114, 76, -12, 44);
  brush.fill("#f8b624", 240);
  drawPolyShape(cutMangoBody, 0.35, true);

  // Blushing vermilion-orange shoulder on left of cut mango
  brush.fill("#ee6638", 180);
  drawPolyShape(getEllipsePoints(m1Cx - 38, m1Cy - 14, 76, 52, 24, -22), 0.4, true);
  brush.fill("#d63f2d", 170);
  drawPolyShape(getEllipsePoints(m1Cx - 54, m1Cy - 20, 52, 38, 22, -25), 0.4, true);
  brush.noFill();

  // Glaze passes on exterior skin of cut mango
  for (let i = 0; i < 38; i++) {
    let a = map(i, 0, 37, 115, 265);
    let pOuter = getAlphonsoPoint(a, m1Cx, m1Cy, 110, 72, -12);
    let pInner = [m1Cx + cos(a) * 35, m1Cy + sin(a) * 25];
    let col = a < 195 ? "#df4d34" : "#f79c32";
    brush.set("glaze", col, 0.8);
    brush.line(pOuter[0], pOuter[1], pInner[0], pInner[1]);
  }

  // Window glint on left shoulder
  brush.noStroke();
  brush.wash("#ffffff", 180);
  drawPolyShape(getEllipsePoints(m1Cx - 48, m1Cy - 32, 22, 11, 16, -28), 0.35, true);
  brush.noWash();

  // --- The Flat Glistening Cut Face (facing lower-right at angle) ---
  const cutFaceCx = m1Cx + 24;
  const cutFaceCy = m1Cy + 8;
  const cutRx = 86;
  const cutRy = 54;
  const cutRot = -14;

  // 1. Thin red-gold skin rim around the cut plane
  brush.noStroke();
  brush.wash("#c94527", 240);
  drawPolyShape(getEllipsePoints(cutFaceCx, cutFaceCy, cutRx + 3, cutRy + 3, 36, cutRot), 0.35, true);

  // 2. Pale creamy-yellow sub-rind edge (characteristic 3mm border under mango skin)
  brush.wash("#fdf096", 248);
  drawPolyShape(getEllipsePoints(cutFaceCx, cutFaceCy, cutRx, cutRy, 36, cutRot), 0.35, true);
  brush.noWash();

  // 3. Watercolor interior flesh grading from chrome-gold to deep wet saffron-amber center
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.28, 0.14);
  brush.fill("#fbb82c", 235);
  drawPolyShape(getEllipsePoints(cutFaceCx, cutFaceCy, cutRx * 0.93, cutRy * 0.92, 34, cutRot), 0.35, true);

  brush.fill("#f5961e", 210);
  drawPolyShape(getEllipsePoints(cutFaceCx, cutFaceCy, cutRx * 0.74, cutRy * 0.72, 30, cutRot), 0.35, true);

  brush.fill("#e37014", 195);
  drawPolyShape(getEllipsePoints(cutFaceCx - 4, cutFaceCy + 2, cutRx * 0.48, cutRy * 0.44, 26, cutRot), 0.35, true);
  brush.noFill();

  // 4. Fine radial juice fibers & translucent knife-cut striations across the flat cut face
  for (let i = 0; i < 55; i++) {
    let a = (i / 55) * 360;
    let pIn = getEllipsePoints(cutFaceCx, cutFaceCy, cutRx * 0.18, cutRy * 0.16, 1, cutRot + a)[0];
    let pOut = getEllipsePoints(cutFaceCx, cutFaceCy, cutRx * 0.88, cutRy * 0.86, 1, cutRot + a)[0];
    brush.set("fiber", i % 3 === 0 ? "#ffe885" : "#d96814", 0.3);
    brush.line(pIn[0], pIn[1], pOut[0], pOut[1]);
  }
  // Parallel horizontal knife-blade shear marks catching wet light
  for (let k = -4; k <= 4; k++) {
    let ky = cutFaceCy + k * 7;
    brush.set("glint", "#fff8d4", 0.32);
    brush.line(cutFaceCx - 48, ky + 8, cutFaceCx + 48, ky - 12);
  }
  // Wet liquid specular sheet on the cut face
  brush.noStroke();
  brush.wash("#ffffff", 145);
  drawPolyShape(getEllipsePoints(cutFaceCx - 16, cutFaceCy - 12, 32, 11, 18, cutRot), 0.35, true);
  brush.noWash();

  // Crisp rim outline of the cut face
  brush.set("2B", "#8f3218", 0.38);
  drawPolyShape(getEllipsePoints(cutFaceCx, cutFaceCy, cutRx + 2.5, cutRy + 2.5, 36, cutRot), 0.35, true);

  // Juice droplets beading along the bottom cut edge
  drawHyperrealDroplet(cutFaceCx + 12, cutFaceCy + 50, 5.8, "#f8a624", "#9e3b10", "#fff4b8");
  drawHyperrealDroplet(cutFaceCx - 18, cutFaceCy + 48, 4.4, "#f8a624", "#9e3b10", "#fff4b8");

  // --- 3. Center-Right: The Scored "Hedgehog" Mango Cheek Slice ---
  const sCx = px + 498;
  const sCy = py + 150;
  const sRx = 104;
  const sRy = 58;

  // Cast shadow & golden juice pool under the scored cheek
  brush.noStroke();
  brush.fillBleed(0.15, "out");
  brush.fill("#e38b1c", 150);
  drawPolyShape(getEllipsePoints(sCx + 12, sCy + 44, 114, 28, 24, 3), 0.4, true);
  brush.fill("#2a2630", 215);
  drawPolyShape(getEllipsePoints(sCx, sCy + 40, 98, 22, 24, 2), 0.4, true);
  brush.noFill();

  // Outer skin boat underneath the scored cheek
  brush.wash("#e86834", 240);
  drawPolyShape(getEllipsePoints(sCx, sCy + 10, sRx + 4, sRy * 0.88, 32, 4), 0.35, true);
  brush.wash("#fdf096", 245);
  drawPolyShape(getEllipsePoints(sCx, sCy + 4, sRx, sRy * 0.84, 32, 4), 0.35, true);
  // Deep burnt-saffron crevices between the scored diamond cubes
  brush.wash("#b5430e", 245);
  drawPolyShape(getEllipsePoints(sCx, sCy, sRx * 0.95, sRy * 0.80, 32, 4), 0.35, true);
  brush.noWash();

  // Render a 4 x 3 grid of plump 3D scored mango flesh cubesarching upward
  const cols = 4;
  const rows = 3;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      let u = map(c, 0, cols - 1, -0.66, 0.66);
      let v = map(r, 0, rows - 1, -0.52, 0.52);
      if (u * u + v * v > 0.78) continue;

      let cubeX = sCx + u * sRx * 0.88 + v * 12;
      let cubeY = sCy + v * sRy * 0.78 - (1 - (u * u + v * v)) * 14;
      let cw = 21 * (1 - abs(u) * 0.15);
      let ch = 14 * (1 - abs(v) * 0.12);

      // Cube side bevel (deep saffron-orange)
      let sidePoly = [
        [cubeX - cw, cubeY + 2],
        [cubeX, cubeY - ch + 2],
        [cubeX + cw, cubeY + 2],
        [cubeX + cw * 0.85, cubeY + ch + 7],
        [cubeX, cubeY + ch * 1.45 + 7],
        [cubeX - cw * 0.85, cubeY + ch + 7]
      ];
      brush.noStroke();
      brush.wash("#e06d14", 245);
      drawPolyShape(sidePoly, 0.2, true);

      // Cube top face (luminous chrome-saffron)
      let topPoly = [
        [cubeX - cw, cubeY],
        [cubeX, cubeY - ch],
        [cubeX + cw, cubeY],
        [cubeX, cubeY + ch]
      ];
      brush.wash("#fba924", 250);
      drawPolyShape(topPoly, 0.18, true);

      // Inner sunlit golden glow on top face
      let innerPoly = topPoly.map(pt => [lerp(cubeX, pt[0], 0.65), lerp(cubeY, pt[1], 0.65)]);
      brush.wash("#fdd84c", 220);
      drawPolyShape(innerPoly, 0.2, true);
      brush.noWash();

      // Wet white specular glint along the sharp cut diamond edges
      brush.set("glint", "#ffffff", 0.48);
      brush.line(cubeX - cw * 0.8, cubeY - ch * 0.15, cubeX, cubeY - ch * 0.92);
      brush.line(cubeX, cubeY - ch * 0.92, cubeX + cw * 0.7, cubeY - ch * 0.2);

      // Dark crevice outline
      brush.set("2B", "#8f320a", 0.34);
      drawPolyShape(topPoly, 0.15, true);
    }
  }

  // --- 4. Right: Hyperreal Stainless Steel Paring Knife Blade with Juice Smear ---
  const kTipX = px + 598;
  const kTipY = py + 114;
  const kBaseX = px + pw - 22;
  const kBaseY = py + 62;

  // Knife cast shadow
  brush.noStroke();
  brush.wash("#8a95a5", 115);
  drawPolyShape([
    [kTipX + 8, kTipY + 18],
    [kBaseX, kBaseY + 26],
    [kBaseX, kBaseY + 58],
    [kTipX + 42, kTipY + 34]
  ], 0.25, true);

  // Knife blade silhouette
  const bladePoly = [
    [kTipX, kTipY],
    [kTipX + 68, kTipY - 22],
    [kBaseX, kBaseY - 14],
    [kBaseX, kBaseY + 24],
    [kTipX + 75, kTipY + 22]
  ];
  // Cool pastel steel base
  brush.wash("#cfdce8", 248);
  drawPolyShape(bladePoly, 0.15, true);

  // Dark slate metallic reflection band along the spine
  brush.wash("#536173", 220);
  drawPolyShape([
    [kTipX + 4, kTipY - 1],
    [kTipX + 68, kTipY - 21],
    [kBaseX, kBaseY - 13],
    [kBaseX, kBaseY - 2],
    [kTipX + 70, kTipY - 8]
  ], 0.15, true);

  // Warm mango reflection + smeared golden juice on the lower cutting bevel
  brush.wash("#f6a428", 195);
  drawPolyShape([
    [kTipX + 12, kTipY + 3],
    [kTipX + 115, kTipY - 4],
    [kTipX + 135, kTipY + 12],
    [kTipX + 55, kTipY + 18]
  ], 0.35, true);
  brush.noWash();

  // Razor-sharp white specular edge along the cutting edge
  brush.set("glint", "#ffffff", 0.72);
  brush.line(kTipX, kTipY, kTipX + 75, kTipY + 22);
  brush.line(kTipX + 75, kTipY + 22, kBaseX, kBaseY + 24);
  brush.set("rotring", "#2b333d", 0.42);
  drawPolyShape(bladePoly, 0.15, true);

  // Glistening juice droplet on the knife tip
  drawHyperrealDroplet(kTipX + 26, kTipY + 10, 5.2, "#f8a824", "#9e3f10", "#ffffff");

  brush.noClip();
}

// ============================================================================
// PANEL 3: THE FIBROUS SEED (GUTHLI) & CURLED PEELS
// ============================================================================

function drawPanel3_FibrousSeed(px, py, pw, ph) {
  brush.clip([px, py, px + pw, py + ph]);

  // --- 1. Soft Pastel Studio Ground ---
  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.35, 0.16);

  brush.fill("#f7efe7", 195);
  brush.rect(px, py, pw, ph, "corner");

  brush.fill("#f5ded8", 105);
  drawPolyShape(getEllipsePoints(px + pw * 0.50, py + ph * 0.42, 310, 92, 26, 0, 0.06), 0.4, true);

  brush.fill("#dfe8e2", 110);
  drawPolyShape(getEllipsePoints(px + pw * 0.22, py + ph * 0.55, 180, 75, 22, -8, 0.06), 0.4, true);
  drawPolyShape(getEllipsePoints(px + pw * 0.80, py + ph * 0.52, 180, 75, 22, 8, 0.06), 0.4, true);

  brush.fill("#d5d6e0", 115);
  drawPolyShape(getEllipsePoints(px + pw * 0.50, py + ph * 0.84, 380, 54, 26, 0, 0.05), 0.4, true);

  // --- 2. Left & Right Flanking Curled Mango Peels ---
  drawCurledMangoPeel(px + 148, py + 142, 1, "#e85d36", "#f9bf2c", "#fad978");
  drawCurledMangoPeel(px + pw - 148, py + 148, -0.85, "#df5232", "#f6b228", "#fbe088");

  // --- 3. Centerpiece: The Fibrous Alphonso Seed (Guthli) ---
  const sCx = px + pw * 0.50;
  const sCy = py + ph * 0.53;
  const sRx = 152;
  const sRy = 64;

  // Step A: Translucent golden-saffron juice halo pooling around the wet seed
  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fill("#fbbd32", 160);
  drawPolyShape(getEllipsePoints(sCx + 6, sCy + 22, sRx * 1.12, sRy * 0.82, 36, -2, 0.08), 0.4, true);
  brush.fill("#e67c16", 175);
  drawPolyShape(getEllipsePoints(sCx + 2, sCy + 18, sRx * 1.02, sRy * 0.68, 34, -2, 0.06), 0.4, true);

  // Deep contact shadow under the seed stone
  brush.fill("#36261b", 215);
  drawPolyShape(getEllipsePoints(sCx, sCy + 14, sRx * 0.88, sRy * 0.52, 30, -2), 0.4, true);

  // Step B: Seed Core Woody Husk & Clinging Pulp Washes
  const seedContour = getAlphonsoContour(sCx, sCy, sRx, sRy, -3, 48);
  brush.fillBleed(0.12, "in");
  // Warm parchment-almond husk base
  brush.fill("#e8cfa2", 240);
  drawPolyShape(seedContour, 0.35, true);

  // Rich golden-saffron clinging pulp in the mid-zones
  brush.fill("#f59c24", 185);
  drawPolyShape(getEllipsePoints(sCx - 12, sCy + 4, sRx * 0.84, sRy * 0.76, 32, -4, 0.08), 0.4, true);

  // Deep burnt-amber woody crevices along the central dorsal rib
  brush.fill("#b86218", 165);
  drawPolyShape(getEllipsePoints(sCx - 8, sCy - 2, sRx * 0.68, sRy * 0.42, 28, -4, 0.1), 0.4, true);

  // Creamy-buff woody highlight along the central ridge
  brush.fill("#fbf0d4", 190);
  drawPolyShape(getEllipsePoints(sCx - 16, sCy - 12, sRx * 0.58, sRy * 0.32, 24, -5), 0.4, true);
  brush.noFill();

  // Step C: 360+ Combed, Clumped Wet Silky Fibers ("fiber" brush)
  // 1. Perimeter clumped wet fiber locks radiating into the juice pool
  const numLocks = 76;
  for (let i = 0; i < numLocks; i++) {
    let a = (i / numLocks) * 360;
    let basePt = getAlphonsoPoint(a, sCx, sCy, sRx * 0.84, sRy * 0.82, -3);
    // Fibers sweep toward the right beak end
    let sweepAngle = a + (a < 180 ? -24 : 24);
    let len = random(18, 34) * (1 + 0.35 * abs(cos(a)));
    let midPt = [
      basePt[0] + cos(sweepAngle) * len * 0.55,
      basePt[1] + sin(sweepAngle) * len * 0.45
    ];
    let tipPt = [
      basePt[0] + cos(sweepAngle - 12) * len,
      basePt[1] + sin(sweepAngle - 12) * len * 0.78
    ];

    // Shadow fiber under-stroke
    brush.set("fiber", i % 2 === 0 ? "#b8681e" : "#d98824", 0.52);
    brush.spline([basePt, midPt, tipPt], 0.45);

    // Silky cream-gold fiber over-stroke
    brush.set("fiber", i % 3 === 0 ? "#fff8de" : "#fce28c", 0.38);
    brush.spline([basePt, [midPt[0] + 1, midPt[1] - 1], tipPt], 0.45);
  }

  // 2. Dense combed interior fibers sweeping longitudinally across the stone dome
  for (let i = 0; i < 260; i++) {
    let u = random(-0.88, 0.88);
    let v = random(-0.82, 0.82);
    if (u * u + v * v > 0.82) continue;

    let x0 = sCx + u * sRx * 0.86;
    let y0 = sCy + v * sRy * 0.82;
    // Fibers arch away from the central longitudinal seam and sweep right
    let dir = (v >= 0 ? 18 : -18) * (1 - abs(u) * 0.5) - 3;
    let fLen = random(22, 46);
    let x1 = x0 + cos(dir) * fLen * 0.5;
    let y1 = y0 + sin(dir) * fLen * 0.5 + (v >= 0 ? 3 : -3);
    let x2 = x0 + cos(dir * 0.6) * fLen;
    let y2 = y0 + sin(dir * 0.6) * fLen;

    let fCol;
    let rVal = random();
    if (rVal < 0.35) fCol = "#fdf6e2";      // silky wet cream fiber
    else if (rVal < 0.68) fCol = "#f9d26b"; // golden mango fiber
    else if (rVal < 0.88) fCol = "#e08422"; // wet saffron pulp strand
    else fCol = "#9c5824";                  // woody husk shadow groove

    brush.set("fiber", fCol, random(0.28, 0.48));
    brush.spline([[x0, y0], [x1, y1], [x2, y2]], 0.4);
  }

  // Step D: Wet Specular Streaks on the Combed Seed Dome & Juice Meniscus Glints
  for (let k = 0; k < 18; k++) {
    let gx = sCx + random(-85, 65);
    let gy = sCy + random(-32, 8);
    brush.set("glint", "#ffffff", random(0.32, 0.58));
    brush.spline([
      [gx, gy],
      [gx + 14, gy - 2],
      [gx + 28, gy + 1]
    ], 0.4);
  }

  // Continuous white liquid meniscus glint around the pooled juice halo
  for (let m = 0; m < 10; m++) {
    let ma = map(m, 0, 9, 15, 165);
    let p1 = getAlphonsoPoint(ma, sCx + 6, sCy + 20, sRx * 1.08, sRy * 0.78, -2);
    let p2 = getAlphonsoPoint(ma + 9, sCx + 6, sCy + 20, sRx * 1.08, sRy * 0.78, -2);
    brush.set("glint", "#ffffff", 0.48);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Satellite juice droplets & stray wet fibers on the table
  drawHyperrealDroplet(sCx - 165, sCy + 52, 5.5, "#f9b228", "#9c4212", "#ffffff");
  drawHyperrealDroplet(sCx + 172, sCy + 38, 6.2, "#f9b228", "#9c4212", "#ffffff");
  drawHyperrealDroplet(sCx + 145, sCy + 64, 4.2, "#f9b228", "#9c4212", "#ffffff");

  brush.noClip();
}

function drawCurledMangoPeel(cx, cy, dirScale, blushCol, yellowCol, pithCol) {
  let d = dirScale;
  // Shadow under curled peel
  brush.noStroke();
  brush.wash("#7c7682", 125);
  drawPolyShape([
    [cx - 52 * d, cy + 28],
    [cx + 42 * d, cy + 16],
    [cx + 58 * d, cy + 38],
    [cx - 32 * d, cy + 44]
  ], 0.38, true);

  // Exterior skin ribbon (chrome yellow grading to blushing coral)
  let extRibbon = [
    [cx - 58 * d, cy - 18],
    [cx - 18 * d, cy - 42],
    [cx + 38 * d, cy - 22],
    [cx + 52 * d, cy + 18],
    [cx + 12 * d, cy + 32],
    [cx - 38 * d, cy + 12]
  ];
  brush.wash(yellowCol, 245);
  drawPolyShape(extRibbon, 0.4, true);

  brush.wash(blushCol, 210);
  drawPolyShape([
    [cx - 56 * d, cy - 16],
    [cx - 18 * d, cy - 40],
    [cx + 12 * d, cy - 26],
    [cx - 18 * d, cy + 8]
  ], 0.4, true);

  // Interior curled-over pith face (pale fibrous orange-cream)
  let intRibbon = [
    [cx - 12 * d, cy - 6],
    [cx + 34 * d, cy - 18],
    [cx + 56 * d, cy + 14],
    [cx + 22 * d, cy + 36],
    [cx - 24 * d, cy + 22]
  ];
  brush.wash(pithCol, 248);
  drawPolyShape(intRibbon, 0.38, true);
  brush.noWash();

  // Pith scrape marks & skin glint
  for (let i = 0; i < 14; i++) {
    let t = i / 13;
    let x0 = lerp(cx - 10 * d, cx + 38 * d, t);
    let y0 = lerp(cy + 14, cy + 2, t);
    brush.set("fiber", "#e38824", 0.35);
    brush.line(x0, y0 - 8, x0 + 10 * d, y0 + 10);
  }
  brush.set("glint", "#ffffff", 0.55);
  brush.line(cx - 42 * d, cy - 24, cx - 8 * d, cy - 34);
  brush.set("2B", "#6e2c18", 0.38);
  drawPolyShape(extRibbon, 0.4, true);
  drawPolyShape(intRibbon, 0.38, true);
}

// ============================================================================
// PANEL 4: JUICE POOLING ON A HYPERREAL STAINLESS STEEL PLATE
// ============================================================================

function drawPanel4_SteelPlateJuice(px, py, pw, ph) {
  brush.clip([px, py, px + pw, py + ph]);

  // --- 1. Soft Pastel Studio Ground ---
  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.32, 0.14);

  brush.fill("#f2f4f7", 200);
  brush.rect(px, py, pw, ph, "corner");

  brush.fill("#e3eaf2", 120);
  drawPolyShape(getEllipsePoints(px + pw * 0.50, py + ph * 0.32, 360, 80, 26, 0, 0.05), 0.4, true);

  brush.fill("#f2e4d8", 110);
