function drawMetallicSector(cx, cy, rInX, rInY, rOutX, rOutY, startDeg, endDeg, col, op) {
  let pts = [];
  let steps = 14;
  for (let i = 0; i <= steps; i++) {
    let a = map(i, 0, steps, startDeg, endDeg);
    pts.push([cx + cos(a) * rOutX, cy + sin(a) * rOutY]);
  }
  for (let i = steps; i >= 0; i--) {
    let a = map(i, 0, steps, startDeg, endDeg);
    pts.push([cx + cos(a) * rInX, cy + sin(a) * rInY]);
  }
  brush.wash(col, op);
  drawPolyShape(pts, 0.25, true);
}

function drawJuicePoolOnSteel(poolPts, centerX, centerY) {
  // 1. Sub-surface warm mahogany contact shadow on upper-left & golden caustic on lower-right
  brush.noStroke();
  let shadowPts = poolPts.map(p => [p[0] - 2, p[1] - 2]);
  brush.wash("#8f3b0e", 130);
  drawPolyShape(shadowPts, 0.4, true);

  let causticPts = poolPts.map(p => [p[0] + 3.5, p[1] + 3.5]);
  brush.wash("#ffe268", 165);
  drawPolyShape(causticPts, 0.4, true);

  // 2. Thin luminous chrome-yellow outer liquid margin
  brush.wash("#fcd238", 230);
  drawPolyShape(poolPts, 0.42, true);
  brush.noWash();

  // 3. Translucent watercolor depth layers (rich mango orange -> deep syrupy saffron-vermilion center)
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.24, 0.12);

  let midPts = poolPts.map(p => [lerp(centerX, p[0], 0.84), lerp(centerY, p[1], 0.84)]);
  brush.fill("#f58d1c", 215);
  drawPolyShape(midPts, 0.42, true);

  let deepPts = poolPts.map(p => [lerp(centerX, p[0], 0.56), lerp(centerY, p[1], 0.56)]);
  brush.fill("#dc5814", 195);
  drawPolyShape(deepPts, 0.42, true);
  brush.noFill();

  // 4. Glossy sky-white window reflection on the surface of the liquid pool
  let glossPts = poolPts.map(p => [lerp(centerX - 12, p[0], 0.35), lerp(centerY - 8, p[1], 0.32)]);
  brush.noStroke();
  brush.wash("#ffffff", 155);
  drawPolyShape(glossPts, 0.4, true);
  brush.noWash();

  // 5. Razor-sharp white liquid meniscus highlight tracing the upper-left contour
  brush.set("glint", "#ffffff", 0.62);
  let halfLen = floor(poolPts.length * 0.58);
  let meniscusPts = [];
  for (let i = 0; i <= halfLen; i++) {
    meniscusPts.push([
      lerp(centerX, poolPts[i][0], 0.94),
      lerp(centerY, poolPts[i][1], 0.94)
    ]);
  }
  brush.spline(meniscusPts, 0.45);

  // Warm amber outer meniscus rim
  brush.set("fiber", "#b5470e", 0.36);
  drawPolyShape(poolPts, 0.42, true);
}

