// Isometric projection parameters
const OX = 575;
const OY = 600;
const COS30 = 0.8660254;
const SIN30 = 0.5;

// Project 3D isometric coordinates (x: front-left, y: front-right, z: up) to 2D canvas
function iso(x, y, z = 0) {
  return [
    OX - x * COS30 + y * COS30,
    OY + x * SIN30 + y * SIN30 - z
  ];
}

