function drawPaperSurface() {
  brush.noFill();
  brush.noHatch();
  // Delicate diagonal paper fiber grain
  brush.set("pencil_6H", PAL.paperGrain1, 0.35);
  for (let i = 0; i < 160; i++) {
    let x1 = random(40, 1160);
    let y1 = random(40, 1160);
    let len = random(30, 110);
    let ang = random(-15, 15);
    brush.line(x1, y1, x1 + cos(ang) * len, y1 + sin(ang) * len);
  }
  brush.set("white_chalk", PAL.paperGrain2, 0.25);
  for (let i = 0; i < 90; i++) {
    let x1 = random(40, 1160);
    let y1 = random(40, 1160);
    let len = random(20, 70);
    brush.line(x1, y1, x1 + len, y1 + random(-4, 4));
  }

  // Ultra-faint architectural registration ticks near corners of the sheet
  brush.set("tech_pen", PAL.g4H, 0.45);
  const m = 52;
  const tl = 14;
  // Top-left
  brush.line(m, m, m + tl, m);
  brush.line(m, m, m, m + tl);
  // Top-right
  brush.line(1200 - m, m, 1200 - m - tl, m);
  brush.line(1200 - m, m, 1200 - m, m + tl);
  // Bottom-left
  brush.line(m, 1200 - m, m + tl, 1200 - m);
  brush.line(m, 1200 - m, m, 1200 - m - tl);
  // Bottom-right
  brush.line(1200 - m, 1200 - m, 1200 - m - tl, 1200 - m);
  brush.line(1200 - m, 1200 - m, 1200 - m, 1200 - m - tl);
}

function drawWarmShadowEllipse(cx, cy, rx, ry, rotDeg, opacity1 = 30, opacity2 = 20) {
  brush.noStroke();
  brush.noHatch();
  brush.fill(PAL.warmShadow1, opacity1);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.38, 0.12);
  brush.beginShape(0.8);
  for (let a = 0; a < 360; a += 30) {
    let ex = cos(a) * rx;
    let ey = sin(a) * ry;
    let px = cx + ex * cos(rotDeg) - ey * sin(rotDeg);
    let py = cy + ex * sin(rotDeg) + ey * cos(rotDeg);
    brush.vertex(px, py);
  }
  brush.endShape(true);

  if (opacity2 > 0) {
    brush.fill(PAL.warmShadow2, opacity2);
    brush.fillBleed(0.18, "out");
    brush.beginShape(0.8);
    for (let a = 0; a < 360; a += 36) {
      let ex = cos(a) * rx * 0.62;
      let ey = sin(a) * ry * 0.58;
      let px = cx + ex * cos(rotDeg) - ey * sin(rotDeg);
      let py = cy + 2 + ex * sin(rotDeg) + ey * cos(rotDeg);
      brush.vertex(px, py);
    }
    brush.endShape(true);
  }
  brush.noFill();
}

function drawAllContactShadows() {
  // 1. Backrest [A] contact shadow wash underneath its bottom frame
  let pBack = iso(-185, 0, 140);
  drawWarmShadowEllipse(pBack[0] + 6, pBack[1] + 28, 76, 26, -24, 26, 18);

  // 2. Spine bracket [J] contact shadow
  let pSpine = iso(-285, 0, 55);
  drawWarmShadowEllipse(pSpine[0] + 4, pSpine[1] + 24, 42, 16, -25, 24, 15);

  // 3. Seat cushion [B] contact shadow wash
  let pSeat = iso(0, 0, 210);
  drawWarmShadowEllipse(pSeat[0], pSeat[1] + 42, 84, 42, -8, 28, 18);

  // 4. Right Armrest (-Y) contact shadow wash
  let pArmR = iso(0, -235, 110);
  drawWarmShadowEllipse(pArmR[0], pArmR[1] + 48, 42, 20, -25, 26, 18);

  // 5. Left Armrest (+Y) contact shadow wash
  let pArmL = iso(0, 235, 110);
  drawWarmShadowEllipse(pArmL[0], pArmL[1] + 48, 44, 21, -25, 28, 18);

  // 6. Tilt Mechanism [C] contact shadow wash
  let pMech = iso(0, 0, 58);
  drawWarmShadowEllipse(pMech[0], pMech[1] + 44, 54, 28, -12, 28, 18);

  // 7. Gas-lift cylinder [D] contact shadow wash
  let pCyl = iso(0, 0, -155);
  drawWarmShadowEllipse(pCyl[0], pCyl[1] + 18, 30, 15, 0, 30, 22);

  // 8. 5-Star Base [E] contact shadow wash (central + 5 arms)
  let pBase = iso(0, 0, -245);
  drawWarmShadowEllipse(pBase[0], pBase[1] + 20, 62, 30, 0, 26, 16);
  const baseAngles = [18, 90, 162, 234, 306];
  for (let ang of baseAngles) {
    let tip = iso(cos(ang) * 155, sin(ang) * 155, -255);
    drawWarmShadowEllipse(tip[0], tip[1] + 14, 34, 14, -ang * 0.4, 22, 12);
  }

  // 9. 5 Casters [F] grounded contact shadows (slightly warmer/crisper under each wheel pair)
  for (let ang of baseAngles) {
    let cPos = iso(cos(ang) * 165, sin(ang) * 165, -372);
    drawWarmShadowEllipse(cPos[0] + 2, cPos[1] + 20, 27, 13, -15, 36, 26);
  }

  // 10. Single Hex Key [K] & Fasteners grounded contact shadow wash
  let pHex = iso(235, -135, -145);
  // Long arm shadow
  drawWarmShadowEllipse(pHex[0] - 32, pHex[1] + 24, 58, 12, -30, 34, 24);
  // Short arm shadow
  drawWarmShadowEllipse(pHex[0] + 24, pHex[1] + 18, 26, 10, 30, 32, 22);
  // Spare bolts shadow
  drawWarmShadowEllipse(pHex[0] + 35, pHex[1] - 25, 22, 11, -15, 30, 20);
  drawWarmShadowEllipse(pHex[0] + 62, pHex[1] - 10, 18, 9, -15, 28, 18);
}

