// GEOMETRIC & SHADING HELPERS
// ============================================================================

function drawDashedLine(x1, y1, x2, y2, dashLen = 6, gapLen = 5, col = PAL.pen, w = 0.7) {
  let d = dist(x1, y1, x2, y2);
  if (d < 1) return;
  let ux = (x2 - x1) / d;
  let uy = (y2 - y1) / d;
  brush.set("tech_pen", col, w);
  for (let t = 0; t < d; t += dashLen + gapLen) {
    let t2 = min(d, t + dashLen);
    brush.line(x1 + ux * t, y1 + uy * t, x1 + ux * t2, y1 + uy * t2);
  }
}

function drawDashedIso(p1, p2, dashLen = 6, gapLen = 5, col = PAL.pen, w = 0.7) {
  drawDashedLine(p1[0], p1[1], p2[0], p2[1], dashLen, gapLen, col, w);
}

function drawArrowHead(x, y, dirX, dirY, len = 6.5, halfW = 2.6, col = PAL.pen) {
  let d = sqrt(dirX * dirX + dirY * dirY);
  if (d === 0) return;
  let ux = dirX / d;
  let uy = dirY / d;
  let px = -uy;
  let py = ux;
  let bx = x - ux * len;
  let by = y - uy * len;
  brush.set("tech_pen", col, 0.85);
  brush.line(x, y, bx + px * halfW, by + py * halfW);
  brush.line(x, y, bx - px * halfW, by - py * halfW);
  brush.line(bx + px * halfW, by + py * halfW, bx - px * halfW, by - py * halfW);
}

// Isometric horizontal circle/arc on XY plane at height Z (rx = R, ry = R * sin(30) = R * 0.5)
function drawIsoHorizEllipse(cx, cy, rScreen, startAng = 0, endAng = 360, steps = 36) {
  let pts = [];
  let ry = rScreen * 0.5;
  for (let i = 0; i <= steps; i++) {
    let a = lerp(startAng, endAng, i / steps);
    pts.push([cx + cos(a) * rScreen, cy + sin(a) * ry]);
  }
  if (pts.length >= 2) {
    brush.spline(pts, 0.4);
  }
}

// ============================================================================
// 2. HYPERREALISTIC COMPONENT RENDERERS
// ============================================================================

// --- [F] 5 SCUFFED NYLON TWIN-WHEEL CASTERS ---
function drawSingleCaster(cx3, cy3, cz3, swivelAng = 25) {
  let pTop = iso(cx3, cy3, cz3); // top of hood
  let sx = pTop[0];
  let sy = pTop[1];

  // 1. Vertical steel grip-ring stem pin (pointing straight up into star-base socket)
  let stemH = 22;
  let stemR = 4.2;
  // Stem shading bands
  for (let u = -1; u <= 1; u += 0.25) {
    let px = sx + u * stemR;
    let col = u < -0.2 ? PAL.gleam : (u < 0.3 ? PAL.g4H : PAL.g4B);
    let bName = u < -0.2 ? "white_chalk" : "pencil_6H";
    brush.set(bName, col, 0.65);
    brush.line(px, sy - 4, px, sy - 4 - stemH);
  }
  // Grip ring groove & bevel at top of stem
  brush.set("pencil_4B", PAL.g6B, 0.65);
  drawIsoHorizEllipse(sx, sy - 4 - stemH, stemR * 0.9, 0, 360, 16);
  drawIsoHorizEllipse(sx, sy - 4 - stemH + 4, stemR * 1.05, 0, 180, 12);
  drawIsoHorizEllipse(sx, sy - 4, stemR * 1.15, 0, 180, 12);
  brush.set("white_chalk", PAL.white, 0.7);
  brush.line(sx - stemR * 0.4, sy - 4, sx - stemR * 0.4, sy - 4 - stemH);

  // 2. Twin Nylon Wheels (offset along axle direction)
  let wheelCy = sy + 13;
  let rx = 13.5;
  let ry = 18.5;
  let tilt = -18;

  // Back wheel (left-up offset), central dark gap, Front wheel (right-down offset)
  let offsets = [
    { dx: -6.5, dy: -3.2, isFront: false },
    { dx: 6.5, dy: 3.2, isFront: true }
  ];

  for (let w of offsets) {
    let wx = sx + w.dx;
    let wy = wheelCy + w.dy;

    // Wheel tread thickness (rolling band)
    for (let t = 0; t <= 1; t += 0.14) {
      let shiftX = lerp(-3.2, 3.2, t);
      let shiftY = lerp(-1.5, 1.5, t);
      // Radial shading around wheel circumference
      for (let a = 0; a < 360; a += 12) {
        let a2 = a + 12;
        let ex1 = cos(a) * rx, ey1 = sin(a) * ry;
        let ex2 = cos(a2) * rx, ey2 = sin(a2) * ry;
        let x1 = wx + shiftX + ex1 * cos(tilt) - ey1 * sin(tilt);
        let y1 = wy + shiftY + ex1 * sin(tilt) + ey1 * cos(tilt);
        let x2 = wx + shiftX + ex2 * cos(tilt) - ey2 * sin(tilt);
        let y2 = wy + shiftY + ex2 * sin(tilt) + ey2 * cos(tilt);

        // Dark nylon base tone
        let shade = sin(a + 45);
        let col = shade > 0.4 ? PAL.g2H : (shade > -0.2 ? PAL.g2B : PAL.g6B);
        brush.set("pencil_HB", col, 0.7);
        brush.line(x1, y1, x2, y2);
      }
    }

    // Flat side face of front wheel
    if (w.isFront) {
      for (let r = 2; r < rx; r += 1.2) {
        let rrY = (r / rx) * ry;
        let col = r > rx * 0.72 ? PAL.g2B : (r > rx * 0.42 ? PAL.g4B : PAL.gHB);
        brush.set("pencil_6H", col, 0.65);
        let pts = [];
        for (let a = 0; a <= 360; a += 24) {
          let ex = cos(a) * r, ey = sin(a) * rrY;
          pts.push([
            wx + 2.8 + ex * cos(tilt) - ey * sin(tilt),
            wy + 1.4 + ex * sin(tilt) + ey * cos(tilt)
          ]);
        }
        brush.spline(pts, 0.4);
      }
      // Recessed center axle rivet
      brush.set("pencil_4B", PAL.g6B, 0.8);
      brush.circle(wx + 2.8, wy + 1.4, 3.2, 0.1);
      brush.set("white_chalk", PAL.gleam, 0.65);
      brush.arc(wx + 2.8, wy + 1.4, 3.5, 200, 330);
    }
  }

  // Deep shadow cleft between twin wheels
  brush.set("pencil_4B", PAL.g6B, 1.15);
  for (let a = -70; a <= 110; a += 10) {
    let ex = cos(a) * rx, ey = sin(a) * ry;
    let x1 = sx - 1.2 + ex * cos(tilt) - ey * sin(tilt);
    let y1 = wheelCy - 0.5 + ex * sin(tilt) + ey * cos(tilt);
    let x2 = sx + 1.2 + ex * cos(tilt) - ey * sin(tilt);
    let y2 = wheelCy + 0.5 + ex * sin(tilt) + ey * cos(tilt);
    brush.line(x1, y1, x2, y2);
  }

  // 3. Molded Nylon Hood / Yoke overarching the top of the twin wheels
  for (let v = 0; v <= 1; v += 0.08) {
    let archY = lerp(sy - 4, wheelCy + 1, v);
    let archW = sin(v * 140 + 20) * 17.5;
    let col = v < 0.35 ? PAL.g4H : (v < 0.7 ? PAL.gHB : PAL.g4B);
    brush.set("pencil_HB", col, 0.75);
    brush.line(sx - archW, archY - v * 2, sx + archW * 0.75, archY + v * 3);
  }
  // Hood highlight ridge
  brush.set("white_chalk", PAL.hiLight, 0.7);
  brush.spline([
    [sx - 12, sy + 1],
    [sx - 3, sy - 3.5],
    [sx + 8, sy + 1],
    [sx + 13, sy + 9]
  ], 0.5);

  // 4. Obsessive SCUFFED NYLON micro-scratches & dusty tread wear on wheels & hood
  brush.set("white_chalk", PAL.gleam, 0.55);
  for (let s = 0; s < 18; s++) {
    let ang = random(-60, 140);
    let rad = random(0.45, 0.95);
    let side = random() > 0.4 ? 4.5 : -5.5;
    let scX = sx + side + cos(ang) * rx * rad;
    let scY = wheelCy + sin(ang) * ry * rad;
    let sLen = random(2.5, 6.5);
    let sDir = random(-35, 45);
    brush.line(scX, scY, scX + cos(sDir) * sLen, scY + sin(sDir) * sLen);
  }
  brush.set("pencil_6H", PAL.g6H, 0.6);
  for (let s = 0; s < 14; s++) {
    let scX = sx + random(-13, 12);
    let scY = wheelCy + random(-8, 14);
    brush.line(scX, scY, scX + random(-5, 5), scY + random(-3, 3));
  }
}

function drawCastersAll() {
  const baseAngles = [18, 90, 162, 234, 306];
  // Sort back-to-front by screen Y
  let list = baseAngles.map(ang => {
    let cx = cos(ang) * 165;
    let cy = sin(ang) * 165;
    let cz = -352;
    let p = iso(cx, cy, cz);
    return { ang, cx, cy, cz, sy: p[1] };
  });
  list.sort((a, b) => a.sy - b.sy);
  for (let item of list) {
    drawSingleCaster(item.cx, item.cy, item.cz, item.ang);
  }
}

// --- [E] 5-STAR SWIVEL BASE ---
function drawFiveStarBase() {
  const cz = -238;
  const hubR = 23;
  const hubH = 28;
  const legLen = 165;
  const baseAngles = [18, 90, 162, 234, 306];

  // Sort legs by screen Y so back legs draw before hub and front legs draw after hub
  let legs = baseAngles.map(ang => {
    let tip = iso(cos(ang) * legLen, sin(ang) * legLen, cz - 14);
    return { ang, sy: tip[1] };
  });
  let hubCenter = iso(0, 0, cz);

  // Draw back legs first
  for (let leg of legs) {
    if (leg.sy < hubCenter[1]) {
      drawSingleBaseLeg(leg.ang, cz, hubR, legLen);
    }
  }

  // Draw central tapered hub collar
  drawBaseCentralHub(cz, hubR, hubH);

  // Draw front legs
  for (let leg of legs) {
    if (leg.sy >= hubCenter[1]) {
      drawSingleBaseLeg(leg.ang, cz, hubR, legLen);
    }
  }
}

function drawSingleBaseLeg(ang, cz, hubR, legLen) {
  let radX = cos(ang);
  let radY = sin(ang);
  let perpX = -sin(ang);
  let perpY = cos(ang);

  let steps = 28;
  let topCenterPts = [];
  let leftTopPts = [];
  let rightTopPts = [];
  let leftBotPts = [];
  let rightBotPts = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let r = lerp(hubR * 0.85, legLen, t);
    // Arch profile: rises near hub, sweeps gracefully down toward caster tip
    let archZ = cz + lerp(16, -12, pow(t, 1.15)) + sin(t * 180) * 7;
    let thickZ = lerp(18, 9.5, t);
    let halfW = lerp(15.5, 9.0, t);

    let cx = radX * r;
    let cy = radY * r;

    topCenterPts.push(iso(cx, cy, archZ + 2.5));
    leftTopPts.push(iso(cx + perpX * halfW, cy + perpY * halfW, archZ));
    rightTopPts.push(iso(cx - perpX * halfW, cy - perpY * halfW, archZ));
    leftBotPts.push(iso(cx + perpX * (halfW * 1.12), cy + perpY * (halfW * 1.12), archZ - thickZ));
    rightBotPts.push(iso(cx - perpX * (halfW * 1.12), cy - perpY * (halfW * 1.12), archZ - thickZ));
  }

  // Determine which side face is more visible to viewer
  // Viewer looks from (+X, +Y, +Z) -> screen normal check
  let midL = leftTopPts[14];
  let midR = rightTopPts[14];
  let midC = topCenterPts[14];

  // 1. Shade top bevel planes (left-top slope & right-top slope)
  for (let s = 0; s <= 1; s += 0.16) {
    let ptsL = [];
    let ptsR = [];
    for (let i = 0; i <= steps; i++) {
      ptsL.push([
        lerp(topCenterPts[i][0], leftTopPts[i][0], s),
        lerp(topCenterPts[i][1], leftTopPts[i][1], s)
      ]);
      ptsR.push([
        lerp(topCenterPts[i][0], rightTopPts[i][0], s),
        lerp(topCenterPts[i][1], rightTopPts[i][1], s)
      ]);
    }
    brush.set("pencil_6H", PAL.g4H, 0.7);
    brush.spline(ptsL, 0.35);
    brush.set("pencil_6H", PAL.g6H, 0.65);
    brush.spline(ptsR, 0.35);
  }

  // 2. Shade visible vertical side wall(s) with deep molded alloy gradient
  let drawLeftWall = midL[1] > midC[1] - 6;
  let drawRightWall = midR[1] > midC[1] - 6;

  if (drawLeftWall) {
    for (let s = 0; s <= 1; s += 0.12) {
      let wallPts = [];
      for (let i = 0; i <= steps; i++) {
        wallPts.push([
          lerp(leftTopPts[i][0], leftBotPts[i][0], s),
          lerp(leftTopPts[i][1], leftBotPts[i][1], s)
        ]);
      }
      let col = s < 0.3 ? PAL.gHB : (s < 0.75 ? PAL.g2B : PAL.g4B);
      brush.set("pencil_HB", col, 0.75);
      brush.spline(wallPts, 0.35);
    }
  }
  if (drawRightWall) {
    for (let s = 0; s <= 1; s += 0.12) {
      let wallPts = [];
      for (let i = 0; i <= steps; i++) {
        wallPts.push([
          lerp(rightTopPts[i][0], rightBotPts[i][0], s),
          lerp(rightTopPts[i][1], rightBotPts[i][1], s)
        ]);
      }
      let col = s < 0.3 ? PAL.g2H : (s < 0.75 ? PAL.gHB : PAL.g2B);
      brush.set("pencil_HB", col, 0.75);
      brush.spline(wallPts, 0.35);
    }
  }

  // 3. Crisp specular highlight along the top central spine ridge of the leg
  brush.set("white_chalk", PAL.white, 0.95);
  brush.spline(topCenterPts, 0.4);
  brush.set("white_chalk", PAL.gleam, 0.65);
  brush.spline(leftTopPts, 0.4);

  // Structural contour edges
  brush.set("pencil_HB", PAL.g2B, 0.7);
  brush.spline(rightTopPts, 0.4);
  if (drawLeftWall) {
    brush.set("pencil_4B", PAL.g4B, 0.8);
    brush.spline(leftBotPts, 0.4);
  }
  if (drawRightWall) {
    brush.set("pencil_4B", PAL.g4B, 0.8);
    brush.spline(rightBotPts, 0.4);
  }

  // 4. Cylindrical caster socket boss at outer tip of the leg
  let tipPos = iso(radX * legLen, radY * legLen, cz - 12);
  let bossR = 11.5;
  let bossH = 12;
  for (let u = -1; u <= 1; u += 0.18) {
    let bx = tipPos[0] + u * bossR;
    let col = u < -0.25 ? PAL.gleam : (u < 0.25 ? PAL.g2H : PAL.g4B);
    brush.set(u < -0.25 ? "white_chalk" : "pencil_HB", col, 0.7);
    brush.line(bx, tipPos[1], bx, tipPos[1] + bossH);
  }
  brush.set("pencil_HB", PAL.g2B, 0.75);
  drawIsoHorizEllipse(tipPos[0], tipPos[1], bossR, 0, 360, 20);
  brush.set("pencil_4B", PAL.g4B, 0.85);
  drawIsoHorizEllipse(tipPos[0], tipPos[1] + bossH, bossR, 0, 180, 16);
  brush.set("white_chalk", PAL.white, 0.75);
  drawIsoHorizEllipse(tipPos[0], tipPos[1], bossR * 0.88, 160, 320, 14);
}

function drawBaseCentralHub(cz, hubR, hubH) {
  let pTop = iso(0, 0, cz + 18);
  let pBot = iso(0, 0, cz - 10);
  let sx = pTop[0];

  // Vertical cylindrical shading on hub exterior
  for (let u = -1; u <= 1; u += 0.08) {
    let x = sx + u * hubR;
    let edgeCurve = sqrt(max(0, 1 - u * u)) * hubR * 0.5;
    let y1 = pTop[1] + edgeCurve;
    let y2 = pBot[1] + edgeCurve;
    let col = PAL.gHB;
    let bName = "pencil_HB";
    if (u > -0.55 && u < -0.2) {
      col = PAL.white;
      bName = "white_chalk";
    } else if (u >= -0.2 && u < 0.25) {
      col = PAL.g4H;
      bName = "pencil_6H";
    } else if (u >= 0.25 && u < 0.75) {
      col = PAL.g2B;
    } else {
      col = PAL.g4B;
    }
    brush.set(bName, col, 0.75);
    brush.line(x, y1, x, y2);
  }

  // Top rim & dark tapered internal bore for gas-lift cylinder
  brush.set("pencil_HB", PAL.g2B, 0.8);
  drawIsoHorizEllipse(sx, pTop[1], hubR, 0, 360, 28);
  brush.set("white_chalk", PAL.white, 0.85);
  drawIsoHorizEllipse(sx, pTop[1], hubR * 0.94, 150, 340, 20);

  // Inner dark socket bore with internal shadow gradient
  for (let r = hubR * 0.76; r > 2; r -= 1.4) {
    let depthShift = map(r, hubR * 0.76, 2, 0, 4.5);
    let col = r > hubR * 0.45 ? PAL.g4B : PAL.g6B;
    brush.set("pencil_4B", col, 0.85);
    drawIsoHorizEllipse(sx, pTop[1] + depthShift, r, 0, 360, 20);
  }
}

// --- [D] GAS-LIFT CYLINDER (OBSESSIVE BRUSHED CHROME HYPERREALISM) ---
function drawGasLiftCylinder() {
  // Three coaxial stages along X=0, Y=0:
  // 1. Lower tapered sleeve: z = -152 to -132 (r = 18 -> 22)
  // 2. Outer support housing tube: z = -132 to -52 (r = 22)
  // 3. Upper mirror-brushed chrome piston rod: z = -52 to +8 (r = 14) + rubber damper + brass valve button

  let pSleeveBot = iso(0, 0, -152);
  let pOuterBot = iso(0, 0, -132);
  let pOuterTop = iso(0, 0, -52);
  let pChromeTop = iso(0, 0, 6);
  let sx = pChromeTop[0];

  const rTapBot = 17.5;
  const rOuter = 22.0;
  const rChrome = 13.8;

  // Helper for brushed chrome reflectance curve across u in [-1, 1]
  function chromeTone(u, isMirror) {
    if (u < -0.84) return { b: "pencil_6H", c: PAL.g4H, w: 0.65 }; // left reflected light
    if (u < -0.50) return { b: "pencil_4B", c: isMirror ? PAL.g6B : PAL.g4B, w: 0.85 }; // deep dark reflection band
    if (u < -0.18) return { b: "white_chalk", c: PAL.white, w: 0.95 }; // blinding primary specular band
    if (u < 0.04)  return { b: "white_chalk", c: PAL.gleam, w: 0.75 }; // soft highlight shoulder
    if (u < 0.34)  return { b: "pencil_6H", c: PAL.g4H, w: 0.65 }; // mid metallic silver
    if (u < 0.70)  return { b: "pencil_4B", c: PAL.g4B, w: 0.85 }; // secondary dark reflection band
    if (u < 0.86)  return { b: "white_chalk", c: PAL.hiLight, w: 0.70 }; // secondary right rim glint
    return { b: "pencil_HB", c: PAL.g2B, w: 0.75 }; // far right terminator
  }

  // 1. Lower Tapered Press-Fit Cone (-152 to -132)
  for (let u = -1; u <= 1; u += 0.06) {
    let x1 = sx + u * rOuter;
    let y1 = pOuterBot[1] + sqrt(max(0, 1 - u * u)) * rOuter * 0.5;
    let x2 = sx + u * rTapBot;
    let y2 = pSleeveBot[1] + sqrt(max(0, 1 - u * u)) * rTapBot * 0.5;
    let st = chromeTone(u, false);
    brush.set(st.b, st.c, st.w);
    brush.line(x1, y1, x2, y2);
  }
  brush.set("pencil_4B", PAL.g6B, 0.8);
  drawIsoHorizEllipse(sx, pSleeveBot[1], rTapBot, 0, 180, 24);

  // 2. Outer Brushed Steel Support Cylinder (-132 to -52)
  // Vertical specular reflection bands
  for (let u = -1; u <= 1; u += 0.035) {
    let x = sx + u * rOuter;
    let curveY = sqrt(max(0, 1 - u * u)) * rOuter * 0.5;
    let yTop = pOuterTop[1] + curveY;
    let yBot = pOuterBot[1] + curveY;
    let st = chromeTone(u, false);
    brush.set(st.b, st.c, st.w);
    brush.line(x, yTop, x, yBot);
  }
  // Obsessive circumferential lathe-brushed micro-striations on outer cylinder
  for (let z = -130; z <= -54; z += 2.2) {
    let py = iso(0, 0, z)[1];
    // Draw fine horizontal brushed arcs broken into tonal segments
    brush.set("pencil_6H", (z % 4.4 < 2.2) ? PAL.g2H : PAL.g4B, 0.45);
    drawIsoHorizEllipse(sx, py, rOuter, 12, 168, 18);
    // Specular glints cutting across the brushed grain
    brush.set("white_chalk", PAL.white, 0.55);
    drawIsoHorizEllipse(sx, py, rOuter, 110, 138, 8);
    drawIsoHorizEllipse(sx, py, rOuter, 25, 42, 6);
  }
  // Machined retaining ring groove near bottom & top bevel of outer cylinder
  brush.set("pencil_4B", PAL.g6B, 0.75);
  drawIsoHorizEllipse(sx, pOuterBot[1], rOuter, 0, 180, 24);
  drawIsoHorizEllipse(sx, pOuterBot[1] - 8, rOuter * 1.01, 0, 180, 24);
  brush.set("white_chalk", PAL.white, 0.65);
  drawIsoHorizEllipse(sx, pOuterBot[1] - 9, rOuter, 95, 155, 12);

  // Top shoulder of outer cylinder
  brush.set("pencil_HB", PAL.g2B, 0.8);
  drawIsoHorizEllipse(sx, pOuterTop[1], rOuter, 0, 360, 28);
  brush.set("white_chalk", PAL.gleam, 0.75);
  drawIsoHorizEllipse(sx, pOuterTop[1], rOuter * 0.92, 180, 350, 20);

  // Black rubber cushion O-ring bumper sitting at base of inner piston shaft
  for (let dz = 0; dz <= 6; dz += 1.0) {
    let col = (dz > 3.5) ? PAL.g2B : PAL.g6B;
    brush.set("pencil_4B", col, 0.9);
    drawIsoHorizEllipse(sx, pOuterTop[1] - dz, rChrome * 1.15, 0, 360, 22);
  }
  brush.set("white_chalk", PAL.g4H, 0.55);
  drawIsoHorizEllipse(sx, pOuterTop[1] - 5.5, rChrome * 1.12, 105, 155, 10);

  // 3. Upper Mirror-Polished Brushed Chrome Piston Shaft (-46 to +6)
  let pShaftBot = iso(0, 0, -46);
  for (let u = -1; u <= 1; u += 0.04) {
    let x = sx + u * rChrome;
    let curveY = sqrt(max(0, 1 - u * u)) * rChrome * 0.5;
    let yTop = pChromeTop[1] + curveY;
    let yBot = pShaftBot[1] + curveY;
    let st = chromeTone(u, true);
    brush.set(st.b, st.c, st.w);
    brush.line(x, yTop, x, yBot);
  }

  // Ultra-fine horizontal brushed chrome lines & horizon reflection bands on inner piston
  for (let z = -44; z <= 4; z += 1.8) {
    let py = iso(0, 0, z)[1];
    brush.set("pencil_6H", PAL.g2B, 0.42);
    drawIsoHorizEllipse(sx, py, rChrome, 15, 165, 14);
    brush.set("white_chalk", PAL.white, 0.7);
    drawIsoHorizEllipse(sx, py, rChrome, 108, 142, 8);
  }

  // Top chamfer of piston shaft & central valve actuator pin
  brush.set("pencil_4B", PAL.g4B, 0.75);
  drawIsoHorizEllipse(sx, pChromeTop[1], rChrome, 0, 360, 24);
  brush.set("white_chalk", PAL.white, 0.9);
  drawIsoHorizEllipse(sx, pChromeTop[1], rChrome * 0.85, 150, 330, 18);

  // Actuator valve button at very top (+6 to +15)
  let rPin = 5.2;
  for (let u = -1; u <= 1; u += 0.2) {
    let px = sx + u * rPin;
    brush.set(u < 0 ? "white_chalk" : "pencil_4B", u < 0 ? PAL.white : PAL.g6B, 0.7);
    brush.line(px, pChromeTop[1], px, pChromeTop[1] - 8);
  }
  brush.set("pencil_4B", PAL.g6B, 0.7);
  drawIsoHorizEllipse(sx, pChromeTop[1] - 8, rPin, 0, 360, 14);
}

// --- [C] UNDER-SEAT TILT & TENSION MECHANISM + [H] 4 EXPLODED SCREWS ---
function drawTiltMechanism() {
  const cz = 75; // Top mounting plate height

  // 1. Cylindrical Tilt-Tension Adjustment Barrel hanging underneath the front (+X)
  for (let x = 8; x <= 42; x += 2.2) {
    let pC = iso(x, 0, cz - 28);
    let rKnob = (x > 26) ? 13.5 : 11.5;
    for (let a = 0; a < 360; a += 18) {
      let a2 = a + 18;
      // Circle in YZ plane
      let p1 = iso(x, cos(a) * rKnob, cz - 28 + sin(a) * rKnob);
      let p2 = iso(x, cos(a2) * rKnob, cz - 28 + sin(a2) * rKnob);
      let col = (sin(a) > 0.3) ? PAL.g4H : ((sin(a) > -0.3) ? PAL.g2B : PAL.g6B);
      brush.set("pencil_HB", col, 0.75);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }
  // Knurled grip ridges along tension knob (x = 26..42)
  for (let a = -60; a <= 210; a += 18) {
    let p1 = iso(26, cos(a) * 13.8, cz - 28 + sin(a) * 13.8);
    let p2 = iso(42, cos(a) * 13.8, cz - 28 + sin(a) * 13.8);
    let col = (a > 30 && a < 130) ? PAL.gleam : PAL.g6B;
    brush.set(col === PAL.gleam ? "white_chalk" : "pencil_4B", col, 0.65);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 2. Heavy Die-Cast Mechanism Housing Box (x: -44..44, y: -34..34, z: cz-22..cz)
  const bx1 = -44, bx2 = 44, by1 = -34, by2 = 34, bz1 = cz - 22, bz2 = cz;
  // Shade visible front-left (+X) face (x = bx2, y: by1..by2, z: bz1..bz2)
  for (let z = bz1; z <= bz2; z += 1.6) {
    let p1 = iso(bx2, by1, z);
    let p2 = iso(bx2, by2, z);
    let col = (z > bz2 - 5) ? PAL.g6B : PAL.g2B;
    brush.set("pencil_HB", col, 0.8);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  // Shade visible front-right (+Y) face (x: bx1..bx2, y = by2, z: bz1..bz2)
  for (let z = bz1; z <= bz2; z += 1.6) {
    let p1 = iso(bx1, by2, z);
    let p2 = iso(bx2, by2, z);
    let col = (z > bz2 - 4) ? PAL.g6B : PAL.g4B;
    brush.set("pencil_4B", col, 0.85);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  // Cross-axle pivot pins on side wall
  for (let ax of [-24, 22]) {
    let pAx = iso(ax, by2 + 2, cz - 11);
    brush.set("pencil_4B", PAL.g6B, 0.8);
    brush.circle(pAx[0], pAx[1], 4.5, 0.1);
    brush.set("white_chalk", PAL.white, 0.7);
    brush.arc(pAx[0], pAx[1], 4.5, 190, 320);
  }

  // 3. Stamped-Steel Top Mounting Plate (x: -56..56, y: -48..48, z: cz..cz+4)
  const px1 = -56, px2 = 56, py1 = -48, py2 = 48;
  // Shade top surface of mounting plate
  for (let y = py1; y <= py2; y += 2.2) {
    let p1 = iso(px1, y, cz + 3);
    let p2 = iso(px2, y, cz + 3);
    let col = (abs(y) < 16) ? PAL.g4H : PAL.g2H;
    brush.set("pencil_6H", col, 0.75);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  // Stamped structural X-ribs & central circular press boss on plate
  let pPlateC = iso(0, 0, cz + 4);
  brush.set("pencil_4B", PAL.g4B, 0.8);
  drawIsoHorizEllipse(pPlateC[0], pPlateC[1], 19, 0, 360, 24);
  brush.set("white_chalk", PAL.white, 0.8);
  drawIsoHorizEllipse(pPlateC[0], pPlateC[1], 18, 160, 330, 18);
  brush.set("pencil_4B", PAL.g6B, 0.85);
  drawIsoHorizEllipse(pPlateC[0], pPlateC[1] + 1, 11, 0, 360, 18);

  // Plate perimeter bevel & thickness rim
  let cornersTop = [
    iso(px1, py1, cz + 3),
    iso(px2, py1, cz + 3),
    iso(px2, py2, cz + 3),
    iso(px1, py2, cz + 3),
    iso(px1, py1, cz + 3)
  ];
  let cornersBot = [
    iso(px1, py1, cz),
    iso(px2, py1, cz),
    iso(px2, py2, cz),
    iso(px1, py2, cz),
    iso(px1, py1, cz)
  ];
  brush.set("pencil_4B", PAL.g4B, 0.9);
  brush.spline(cornersBot, 0.05);
  brush.set("pencil_HB", PAL.g2B, 0.8);
  brush.spline(cornersTop, 0.05);
  // Bright highlight on front-left edge of stamped steel plate
  brush.set("white_chalk", PAL.white, 0.9);
  brush.line(cornersTop[1][0], cornersTop[1][1], cornersTop[2][0], cornersTop[2][1]);
  brush.line(cornersTop[0][0], cornersTop[0][1], cornersTop[1][0], cornersTop[1][1]);

  // Rear spine receiver slot at (-X) end of mechanism
  let s1 = iso(px1 - 12, -16, cz - 6);
  let s2 = iso(px1, -16, cz - 6);
  let s3 = iso(px1, 16, cz - 6);
  let s4 = iso(px1 - 12, 16, cz - 6);
  brush.set("pencil_4B", PAL.g4B, 0.85);
  brush.spline([s1, s2, s3, s4, s1], 0.05);

  // 4. Height & Tilt Control Lever Rod + Contoured Paddle Handle extending along +Y
  let levStart = iso(14, 34, cz - 10);
  let levMid = iso(18, 86, cz - 14);
  let levEnd = iso(22, 112, cz - 16);
  // Chrome rod
  brush.set("pencil_4B", PAL.g4B, 0.9);
  brush.line(levStart[0], levStart[1] + 1.5, levMid[0], levMid[1] + 1.5);
  brush.set("white_chalk", PAL.white, 0.85);
  brush.line(levStart[0], levStart[1], levMid[0], levMid[1]);
  // Black molded paddle handle
  for (let w = -5; w <= 5; w += 1.2) {
    let h1 = iso(18 + w * 1.4, 84, cz - 14 - abs(w) * 0.3);
    let h2 = iso(22 + w * 1.8, 115, cz - 16 - abs(w) * 0.3);
    let col = w < -1 ? PAL.g2H : (w < 2 ? PAL.g2B : PAL.g6B);
    brush.set("pencil_HB", col, 0.85);
    brush.line(h1[0], h1[1], h2[0], h2[1]);
  }
  brush.set("white_chalk", PAL.gleam, 0.65);
  let hp1 = iso(14, 85, cz - 13);
  let hp2 = iso(17, 113, cz - 15);
  brush.line(hp1[0], hp1[1], hp2[0], hp2[1]);

  // 5. Four Exploded M6 Socket-Head Cap Screws [H] floating above the 4 corners of plate
  const screwCorners = [
    [-44, -36],
    [44, -36],
    [44, 36],
    [-44, 36]
  ];
  for (let sc of screwCorners) {
    // Hole in plate
    let pHole = iso(sc[0], sc[1], cz + 3.2);
    brush.set("pencil_4B", PAL.g6B, 0.85);
    drawIsoHorizEllipse(pHole[0], pHole[1], 3.8, 0, 360, 12);
    brush.set("white_chalk", PAL.white, 0.65);
    drawIsoHorizEllipse(pHole[0], pHole[1], 4.2, 0, 180, 10);

    // Floating screw at z = cz + 52
    drawSocketScrew(sc[0], sc[1], cz + 52);
  }
}

function drawSocketScrew(x, y, z) {
  let pBot = iso(x, y, z);
  let sx = pBot[0];
  let sy = pBot[1];
  // Threaded shaft (13px tall) with fine helical thread rings
  for (let dz = 0; dz <= 13; dz += 1.6) {
    let col = (dz % 3.2 < 1.6) ? PAL.g6B : PAL.g4H;
    brush.set("pencil_6H", col, 0.65);
    brush.line(sx - 2.6, sy - dz, sx + 2.6, sy - dz + 0.6);
  }
  brush.set("white_chalk", PAL.white, 0.75);
  brush.line(sx - 1.2, sy, sx - 1.2, sy - 13);

  // Cylindrical socket cap head
  for (let dz = 13; dz <= 18.5; dz += 1.1) {
    brush.set("pencil_HB", PAL.g2B, 0.75);
    brush.line(sx - 4.6, sy - dz, sx + 4.6, sy - dz);
  }
  brush.set("white_chalk", PAL.white, 0.85);
  brush.line(sx - 2.4, sy - 13, sx - 2.4, sy - 18.5);
  brush.set("pencil_4B", PAL.g6B, 0.8);
  drawIsoHorizEllipse(sx, sy - 18.5, 4.6, 0, 360, 12);
  // Washer below screw
  let wy = sy + 9;
  brush.set("pencil_HB", PAL.g2B, 0.7);
  drawIsoHorizEllipse(sx, wy, 5.5, 0, 360, 14);
  brush.set("white_chalk", PAL.white, 0.7);
  drawIsoHorizEllipse(sx, wy - 0.8, 5.2, 160, 340, 10);
}

// --- [B] CONTOURED UPHOLSTERED SEAT CUSHION ---
function drawSeatCushion() {
  const cz = 228;
  // Parametric 3D ergonomic seat cushion surface:
  // u in [-1, 1] across width (Y), v in [-1, 1] back-to-front (X)
  function seatSurface(u, v, isBottom = false) {
    // Rounded squircle width & length
    let r = sqrt(u * u + v * v);
    let cornerRound = 1.0 - 0.14 * pow(u * v, 2);
    let x = v * 74 * cornerRound;
    let y = u * 78 * cornerRound;

    if (isBottom) {
      let botZ = cz - 12 + (1 - r * r) * 3 - (v > 0.5 ? pow(v - 0.5, 2) * 28 : 0);
      return iso(x, y, botZ);
    }

    // Top sculpted foam contour:
    // Waterfall front edge drops smoothly for v > 0.35
    let waterfall = v > 0.35 ? -pow((v - 0.35) / 0.65, 2.1) * 18 : 0;
    // Side thigh bolsters rise gently near |u| ~ 0.75
    let bolster = sin(abs(u) * 145) * 4.5 * (1 - abs(v) * 0.4);
    // Rear pelvic cradle rises gently near v < -0.5
    let rearRise = v < -0.4 ? pow((-0.4 - v) / 0.6, 1.8) * 7 : 0;
    // Edge roll-off near perimeter
    let edgeRoll = (max(abs(u), abs(v)) > 0.82)
      ? -pow((max(abs(u), abs(v)) - 0.82) / 0.18, 1.7) * 9
      : 0;

    let z = cz + 14 + waterfall + bolster + rearRise + edgeRoll;
    return iso(x, y, z);
  }

  // 1. Molded dark-grey polypropylene under-shell & lower cushion rim
  for (let s = 0; s <= 1; s += 0.12) {
    let rimPtsFront = [];
    for (let u = -1; u <= 1.001; u += 0.08) {
      let pTop = seatSurface(u, 1.0, false);
      let pBot = seatSurface(u, 1.0, true);
      rimPtsFront.push([lerp(pTop[0], pBot[0], s), lerp(pTop[1], pBot[1], s)]);
    }
    let col = s < 0.45 ? PAL.gHB : (s < 0.75 ? PAL.g2B : PAL.g6B);
    brush.set("pencil_HB", col, 0.8);
    brush.spline(rimPtsFront, 0.4);

    let rimPtsSide = [];
    for (let v = -1; v <= 1.001; v += 0.08) {
      let pTop = seatSurface(1.0, v, false);
      let pBot = seatSurface(1.0, v, true);
      rimPtsSide.push([lerp(pTop[0], pBot[0], s), lerp(pTop[1], pBot[1], s)]);
    }
    brush.set("pencil_4B", s < 0.4 ? PAL.g2B : PAL.g6B, 0.85);
    brush.spline(rimPtsSide, 0.4);
  }

  // 2. Soft velvety graphite wash shading across the sculpted top cushion
  for (let v = -0.96; v <= 0.96; v += 0.06) {
    let rowPts = [];
    for (let u = -0.96; u <= 0.961; u += 0.1) {
      rowPts.push(seatSurface(u, v, false));
    }
    // Tonal modeling: waterfall front and right side roll into deeper graphite
    let shade = v * 0.45 + 0.15;
    let col = shade < -0.1 ? PAL.g6H : (shade < 0.25 ? PAL.g4H : (shade < 0.5 ? PAL.g2H : PAL.gHB));
    brush.set("graphite_wash", col, 0.9);
    brush.spline(rowPts, 0.45);
  }

  // 3. Obsessive woven textile upholstery micro-grid (warp & weft following 3D cushion curvature)
  // Warp lines (back-to-front along v)
  for (let u = -0.96; u <= 0.961; u += 0.032) {
    let pts = [];
    for (let v = -0.96; v <= 0.961; v += 0.08) {
      pts.push(seatSurface(u, v, false));
    }
    let edgeDark = max(abs(u), 0.2);
    let col = u < -0.25 ? PAL.g4H : (u < 0.45 ? PAL.g2H : PAL.gHB);
    if (abs(u) > 0.86) col = PAL.g2B;
    brush.set("pencil_6H", col, 0.58);
    brush.spline(pts, 0.4);
  }

  // Weft lines (left-to-right along u)
  for (let v = -0.96; v <= 0.961; v += 0.032) {
    let pts = [];
    for (let u = -0.96; u <= 0.961; u += 0.08) {
      pts.push(seatSurface(u, v, false));
    }
    let col = v < 0.15 ? PAL.g4H : (v < 0.62 ? PAL.g2H : PAL.g2B);
    brush.set("pencil_6H", col, 0.55);
    brush.spline(pts, 0.4);
  }

  // 4. Specular highlight sheen on the thigh bolsters & waterfall crest
  for (let v = -0.35; v <= 0.48; v += 0.045) {
    let hPts1 = [];
    for (let u = -0.82; u <= -0.15; u += 0.1) {
      hPts1.push(seatSurface(u, v, false));
    }
    brush.set("white_chalk", v > 0.15 ? PAL.white : PAL.gleam, 0.65);
    brush.spline(hPts1, 0.4);
  }
  for (let u = -0.75; u <= 0.45; u += 0.05) {
    let crestPts = [];
    for (let v = 0.15; v <= 0.58; v += 0.08) {
      crestPts.push(seatSurface(u, v, false));
    }
    brush.set("white_chalk", PAL.gleam, 0.55);
    brush.spline(crestPts, 0.4);
  }

  // 5. Stitched perimeter welt seam & individual thread ticks around cushion edge
  let seamPts = [];
  const N = 64;
  for (let i = 0; i <= N; i++) {
    let a = (i / N) * 360;
    // Squircle parameter
    let cu = cos(a), sv = sin(a);
    let rScale = 0.94 / pow(pow(abs(cu), 3.2) + pow(abs(sv), 3.2), 1 / 3.2);
    seamPts.push(seatSurface(cu * rScale, sv * rScale, false));
  }
  brush.set("pencil_4B", PAL.g4B, 0.8);
  brush.spline(seamPts, 0.4);
  // Parallel highlight welt cord just inside seam
  let innerSeamPts = [];
  for (let i = 0; i <= N; i++) {
    let a = (i / N) * 360;
    let cu = cos(a), sv = sin(a);
    let rScale = 0.915 / pow(pow(abs(cu), 3.2) + pow(abs(sv), 3.2), 1 / 3.2);
    innerSeamPts.push(seatSurface(cu * rScale, sv * rScale, false));
  }
  brush.set("white_chalk", PAL.white, 0.7);
  brush.spline(innerSeamPts, 0.4);

  // Subtle fabric tension creases along the front waterfall corner bolsters
  for (let c = 0; c < 5; c++) {
    let u0 = -0.82 + c * 0.08;
    let p1 = seatSurface(u0, 0.72, false);
    let p2 = seatSurface(u0 * 0.94, 0.93, false);
    brush.set("pencil_HB", PAL.g2B, 0.6);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.set("white_chalk", PAL.white, 0.5);
    brush.line(p1[0] + 1.2, p1[1] - 0.5, p2[0] + 1.2, p2[1] - 0.5);
  }
}

// --- [J] REAR SPINE & LUMBAR BRACKET ---
function drawLumbarSpineBracket() {
  // Floating behind/below the backrest at x = -275, y = 0, z = 65..220
  const bx = -275;
  // Vertical curved spine bar from z = 65 up to z = 195
  let spineSteps = 22;
  let spineLeft = [];
  let spineMid = [];
  let spineRight = [];

  for (let i = 0; i <= spineSteps; i++) {
    let t = i / spineSteps;
    let z = lerp(68, 200, t);
    let x = bx + sin(t * 150) * 18 - t * 14;
    let halfW = lerp(11, 8, t);
    spineLeft.push(iso(x, -halfW, z));
    spineMid.push(iso(x + 4, 0, z));
    spineRight.push(iso(x, halfW, z));
  }

  // Horizontal base tongue that slots forward (+X) into the tilt mechanism
  for (let y = -11; y <= 11; y += 2.2) {
    let p1 = iso(bx + 36, y, 68);
    let p2 = iso(bx, y, 68);
    brush.set("pencil_HB", abs(y) < 5 ? PAL.g4H : PAL.g2B, 0.75);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  // Slotted bolt holes on base tongue
  for (let xSlot of [bx + 16, bx + 26]) {
    let ps = iso(xSlot, 0, 69);
    brush.set("pencil_4B", PAL.g6B, 0.8);
    drawIsoHorizEllipse(ps[0], ps[1], 3.2, 0, 360, 10);
  }

  // Shade vertical spine upright
  for (let s = 0; s <= 1; s += 0.16) {
    let pts1 = [], pts2 = [];
    for (let i = 0; i <= spineSteps; i++) {
      pts1.push([lerp(spineLeft[i][0], spineMid[i][0], s), lerp(spineLeft[i][1], spineMid[i][1], s)]);
      pts2.push([lerp(spineMid[i][0], spineRight[i][0], s), lerp(spineMid[i][1], spineRight[i][1], s)]);
    }
    brush.set("pencil_6H", PAL.g4H, 0.7);
    brush.spline(pts1, 0.4);
    brush.set("pencil_HB", PAL.g2B, 0.75);
    brush.spline(pts2, 0.4);
  }
  brush.set("white_chalk", PAL.white, 0.85);
  brush.spline(spineMid, 0.4);
  brush.set("pencil_4B", PAL.g4B, 0.8);
  brush.spline(spineLeft, 0.4);
  brush.spline(spineRight, 0.4);

  // Winged lumbar crossbar at top of spine (z = 185..205, y = -68..68)
  for (let zOff = -7; zOff <= 7; zOff += 1.8) {
    let wPts = [];
    for (let u = -1; u <= 1.001; u += 0.1) {
      let wx = bx - 10 + u * u * 16;
      let wy = u * 66;
      let wz = 192 + zOff * (1 - 0.35 * abs(u));
      wPts.push(iso(wx, wy, wz));
    }
    let col = zOff > 2 ? PAL.g4H : (zOff > -2 ? PAL.gHB : PAL.g4B);
    brush.set("pencil_HB", col, 0.75);
    brush.spline(wPts, 0.4);
  }
}

// --- [A] MESH BACKREST WEAVE (OBSESSIVE TRANSLUCENT ELASTOMERIC WEAVE) ---
function drawMeshBackrest() {
  // Backrest centered around x = -182, y = 0, z = 148..398
  // Parametric 3D surface: u in [-1, 1] across width, v in [0, 1] bottom-to-top
  function backrestPt(u, v, xOffset = 0) {
    // Ergonomic hourglass-shoulder silhouette width
    let wProfile = 84 - 8 * sin(v * 180) + 12 * pow(v, 1.6);
    // Smoothly round off top and bottom corners
    let vClamp = constrain(v, 0, 1);
    let cornerPinch = 1.0;
    if (vClamp < 0.12) {
      let t = (0.12 - vClamp) / 0.12;
      cornerPinch = sqrt(max(0.08, 1 - t * t * 0.55));
    } else if (vClamp > 0.86) {
      let t = (vClamp - 0.86) / 0.14;
      cornerPinch = sqrt(max(0.08, 1 - t * t * 0.65));
    }
    let y = u * wProfile * cornerPinch;
    let z = lerp(152, 396, vClamp) + (1 - u * u) * (vClamp > 0.85 ? 8 : -4);

    // S-curve lumbar profile along v + concave lateral cradle along u
    let lumbarCurve = sin(vClamp * 200 - 15) * 14 - pow(vClamp, 1.5) * 26;
    let lateralWrap = (u * u) * 24;
    let x = -178 + lumbarCurve + lateralWrap + xOffset;

    return iso(x, y, z);
  }

  // 1. Draw the REAR STRUCTURAL LUMBAR PAD & SPINE BAR *behind* the mesh first
  // so it shows dimly through the translucent mesh weave!
  for (let v = 0.24; v <= 0.38; v += 0.014) {
    let lumPts = [];
    for (let u = -0.94; u <= 0.941; u += 0.08) {
      lumPts.push(backrestPt(u, v, -9));
    }
    let isCenter = abs(v - 0.31) < 0.035;
    brush.set("graphite_wash", isCenter ? PAL.gHB : PAL.g2H, 0.85);
    brush.spline(lumPts, 0.4);
  }
  // Vertical spine silhouette behind mesh
  for (let u = -0.11; u <= 0.11; u += 0.035) {
    let spPts = [];
    for (let v = 0.02; v <= 0.52; v += 0.06) {
      spPts.push(backrestPt(u, v, -10));
    }
    brush.set("graphite_wash", PAL.gHB, 0.8);
    brush.spline(spPts, 0.4);
  }

  // 2. Draw the REAR edge of the polymer perimeter frame
  let frameRearPts = [];
  const FN = 68;
  for (let i = 0; i <= FN; i++) {
    let a = (i / FN) * 360;
    let u = cos(a);
    let v = 0.5 + 0.5 * sin(a);
    frameRearPts.push(backrestPt(u * 1.07, v, -11));
  }
  brush.set("pencil_4B", PAL.g4B, 0.85);
  brush.spline(frameRearPts, 0.4);

  // 3. THE OBSESSIVE MESH BACKREST WEAVE (multi-layer warp, weft & diagonal tension strands)
  // Helper to clip parameter (u, v) inside rounded ergonomic mesh opening
  function inMeshWindow(u, v) {
    let vc = (v - 0.5) * 2.0; // [-1, 1]
    let d = pow(abs(u), 3.4) + pow(abs(vc), 3.4);
    return d <= 0.96;
  }

  // 3A. Diagonal elastomeric tension micro-threads (creates realistic moiré interference)
  for (let k = -36; k <= 36; k += 1.5) {
    let dPts1 = [];
    for (let s = -1; s <= 1; s += 0.05) {
      let u = s;
      let v = 0.5 + s * 0.35 + k * 0.022;
      if (v >= 0.03 && v <= 0.97 && inMeshWindow(u, v)) {
        dPts1.push(backrestPt(u, v, 0));
      }
    }
    if (dPts1.length >= 3) {
      brush.set("pencil_6H", PAL.g4H, 0.42);
      brush.spline(dPts1, 0.35);
    }
  }

  // 3B. Vertical Warp Strands (76 strands across u in [-0.95, 0.95])
  for (let i = -38; i <= 38; i++) {
    let u = (i / 38) * 0.95;
    let warpPts = [];
    for (let v = 0.02; v <= 0.98; v += 0.04) {
      if (inMeshWindow(u, v)) {
        warpPts.push(backrestPt(u, v, 0));
      }
    }
    if (warpPts.length >= 3) {
      // Foreshortening on lateral curves makes outer mesh strands denser & darker
      let col = PAL.g2H;
      let w = 0.52;
      if (u > 0.58 || u < -0.72) {
        col = PAL.g2B;
        w = 0.62;
      } else if (u > -0.45 && u < 0.15) {
        col = (i % 2 === 0) ? PAL.g4H : PAL.g2H;
        w = 0.48;
      }
      brush.set("pencil_6H", col, w);
      brush.spline(warpPts, 0.38);
    }
  }

  // 3C. Horizontal Weft Strands (88 strands across v in [0.03, 0.97])
  for (let j = 2; j <= 86; j++) {
    let v = j / 88;
    let weftPts = [];
    for (let u = -0.96; u <= 0.961; u += 0.05) {
      if (inMeshWindow(u, v)) {
        weftPts.push(backrestPt(u, v, 0));
      }
    }
    if (weftPts.length >= 3) {
      // Lumbar bulge (v ~ 0.25..0.42) catches more light; upper/lower recessions deepen
      let isLumbarZone = (v > 0.22 && v < 0.44);
      let col = isLumbarZone ? PAL.g4H : ((j % 3 === 0) ? PAL.g2B : PAL.g2H);
      brush.set("pencil_6H", col, 0.50);
      brush.spline(weftPts, 0.38);
    }
  }

  // 3D. Specular elastomeric sheen flecks where light grazes the curved lumbar mesh weave
  for (let v = 0.20; v <= 0.52; v += 0.028) {
    let glintPts = [];
    for (let u = -0.58; u <= -0.10; u += 0.06) {
      if (inMeshWindow(u, v)) {
        glintPts.push(backrestPt(u, v, 0.4));
      }
    }
    if (glintPts.length >= 2) {
      brush.set("white_chalk", PAL.gleam, 0.52);
      brush.spline(glintPts, 0.35);
    }
  }

  // 4. Sculpted Polymer Perimeter Frame (molded fiberglass-reinforced nylon rim around the mesh)
  const frameRings = 7;
  for (let rIdx = 0; rIdx <= frameRings; rIdx++) {
    let frac = rIdx / frameRings; // 0 = inner mesh bezel, 1 = outer frame perimeter
    let scaleUV = lerp(0.955, 1.075, frac);
    let xBulge = sin(frac * 180) * 4.5 - frac * 3.0;
    let ringPts = [];

    for (let i = 0; i <= FN; i++) {
      let a = (i / FN) * 360;
      let cu = cos(a);
      let sv = sin(a);
      let rSquircle = scaleUV / pow(pow(abs(cu), 3.4) + pow(abs(sv), 3.4), 1 / 3.4);
      let u = cu * rSquircle;
      let v = 0.5 + 0.5 * sv * rSquircle;
      ringPts.push(backrestPt(u, v, xBulge));
    }

    let col = PAL.gHB;
    let bName = "pencil_HB";
    let w = 0.8;
    if (rIdx === 0) {
      // Crisp dark recess channel where mesh locks into frame
      col = PAL.g6B;
      bName = "pencil_4B";
      w = 0.9;
    } else if (rIdx === 2 || rIdx === 3) {
      // Lit front bevel of polymer frame
      col = PAL.g4H;
      bName = "pencil_6H";
      w = 0.75;
    } else if (rIdx >= 5) {
      col = PAL.g4B;
      bName = "pencil_4B";
      w = 0.85;
    }
    brush.set(bName, col, w);
    brush.spline(ringPts, 0.4);
  }

  // Specular highlight arc along the top-left shoulder and left vertical frame rail
  let hiArcPts = [];
  for (let i = 10; i <= 42; i++) {
    let a = (i / FN) * 360;
    let cu = cos(a), sv = sin(a);
    let rSquircle = 1.005 / pow(pow(abs(cu), 3.4) + pow(abs(sv), 3.4), 1 / 3.4);
    let u = cu * rSquircle;
    let v = 0.5 + 0.5 * sv * rSquircle;
    hiArcPts.push(backrestPt(u, v, 3.8));
  }
  brush.set("white_chalk", PAL.white, 0.9);
  brush.spline(hiArcPts, 0.4);
}

// --- [G] LEFT & RIGHT T-ARMRESTS ---
function drawArmrestAssembly(sideY, isNearSide) {
  // sideY = -235 (far-right / upper-left on screen) or +235 (near-left / lower-right on screen)
  let dir = sideY > 0 ? 1 : -1;
  let baseZ = 105;

  // 1. Horizontal under-seat L-bracket mounting bar extending inward toward seat
  let inY1 = sideY - dir * 52;
  let inY2 = sideY;
  for (let x = -14; x <= 14; x += 2.4) {
    let p1 = iso(x, inY1, baseZ);
    let p2 = iso(x, inY2, baseZ);
    let col = abs(x) < 6 ? PAL.g4H : PAL.g2B;
    brush.set("pencil_HB", col, 0.75);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  // Thickness edge of L-bracket
  let b1 = iso(14, inY1, baseZ);
  let b2 = iso(14, inY2, baseZ);
  let b3 = iso(14, inY2, baseZ - 6);
  let b4 = iso(14, inY1, baseZ - 6);
  brush.set("pencil_4B", PAL.g4B, 0.85);
  brush.spline([b1, b2, b3, b4, b1], 0.05);
  brush.set("white_chalk", PAL.white, 0.75);
  brush.line(b1[0], b1[1], b2[0], b2[1]);

  // Slotted bolt holes on horizontal bracket tab
  for (let slotY of [inY1 + dir * 12, inY1 + dir * 26]) {
    let ps = iso(0, slotY, baseZ + 1);
    brush.set("pencil_4B", PAL.g6B, 0.8);
    drawIsoHorizEllipse(ps[0], ps[1], 3.4, 0, 360, 10);
  }

  // 2. Vertical Tapered Armrest Upright Post (z = baseZ to baseZ + 92)
  let postSteps = 20;
  for (let x = -11; x <= 11; x += 1.6) {
    let pBot = iso(x, sideY, baseZ);
    let pTop = iso(x * 0.82 - 4, sideY + dir * 4, baseZ + 90);
    let col = x > 3 ? PAL.gleam : (x > -3 ? PAL.g4H : PAL.g4B);
    let bName = x > 3 ? "white_chalk" : "pencil_HB";
    brush.set(bName, col, 0.75);
    brush.line(pBot[0], pBot[1], pTop[0], pTop[1]);
  }
  // Side face of vertical post
  for (let z = baseZ; z <= baseZ + 90; z += 2.2) {
    let t = (z - baseZ) / 90;
    let xFront = lerp(11, 11 * 0.82 - 4, t);
    let yCur = lerp(sideY, sideY + dir * 4, t);
    let p1 = iso(xFront, yCur - 6, z);
    let p2 = iso(xFront, yCur + 6, z);
    brush.set("pencil_HB", PAL.g2B, 0.75);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  // Telescoping chrome inner sleeve collar at z = baseZ + 52
  let pCollar = iso(-2, sideY + dir * 2, baseZ + 52);
  brush.set("pencil_4B", PAL.g6B, 0.85);
  drawIsoHorizEllipse(pCollar[0], pCollar[1], 11, 0, 180, 14);
  brush.set("white_chalk", PAL.white, 0.75);
  drawIsoHorizEllipse(pCollar[0], pCollar[1] - 2, 10.5, 90, 165, 10);

  // Height-adjustment trigger button on outer side of upright
  let pBtn1 = iso(7, sideY + dir * 6, baseZ + 62);
  let pBtn2 = iso(7, sideY + dir * 6, baseZ + 76);
  brush.set("pencil_4B", PAL.g6B, 0.95);
  brush.line(pBtn1[0], pBtn1[1], pBtn2[0], pBtn2[1]);
  brush.set("white_chalk", PAL.gleam, 0.65);
  brush.line(pBtn1[0] - 1.5, pBtn1[1], pBtn2[0] - 1.5, pBtn2[1]);

  // 3. Soft-Touch Molded Polyurethane Top Arm Pad (x: -48..46, y: sideY-14..sideY+20, z: baseZ+90..baseZ+102)
  const padZ = baseZ + 92;
  const padY = sideY + dir * 4;
  function armPadPt(u, v, zOff = 0) {
    // u in [-1, 1] width (Y), v in [-1, 1] length (X)
    let r = pow(abs(u), 3.0) + pow(abs(v), 3.0);
    let scale = 1.0 / pow(max(1.0, r), 1 / 3.0);
    let px = v * 48 * scale;
    let py = padY + u * 18 * scale;
    // Slight ergonomic dip in center of pad, rounded nose at front (+X)
    let contourZ = padZ + 9 - (v > 0.6 ? pow(v - 0.6, 2) * 14 : 0) - (1 - u * u) * 1.4 + zOff;
    return iso(px, py, contourZ);
  }

  // Dark underside bevel of arm pad
  for (let h = -8; h <= 0; h += 1.6) {
    let rim = [];
    for (let a = -30; a <= 210; a += 15) {
      rim.push(armPadPt(cos(a), sin(a), h));
    }
    brush.set("pencil_4B", h < -4 ? PAL.g6B : PAL.g2B, 0.85);
    brush.spline(rim, 0.4);
  }

  // Top polyurethane surface shading
  for (let u = -0.95; u <= 0.951; u += 0.08) {
    let pts = [];
    for (let v = -0.95; v <= 0.951; v += 0.1) {
      pts.push(armPadPt(u, v, 0));
    }
    let col = u < -0.2 ? PAL.g4H : (u < 0.4 ? PAL.g2H : PAL.gHB);
    brush.set("pencil_6H", col, 0.68);
    brush.spline(pts, 0.4);
  }
  for (let v = -0.95; v <= 0.951; v += 0.06) {
    let pts = [];
    for (let u = -0.95; u <= 0.951; u += 0.12) {
      pts.push(armPadPt(u, v, 0));
    }
    brush.set("pencil_6H", v > 0.4 ? PAL.gHB : PAL.g4H, 0.58);
    brush.spline(pts, 0.4);
  }

  // Highlight along the top bevel rim of the polyurethane pad
  let topRimHi = [];
  for (let a = 35; a <= 195; a += 12) {
    topRimHi.push(armPadPt(cos(a) * 0.94, sin(a) * 0.94, 0.4));
  }
  brush.set("white_chalk", PAL.white, 0.85);
  brush.spline(topRimHi, 0.4);
}

function drawRightArmrest() {
  drawArmrestAssembly(-235, false);
}

function drawLeftArmrest() {
  drawArmrestAssembly(235, true);
}

// --- [K] SINGLE HEX KEY & SPARE FASTENER SPECIMEN ---
function drawHexKeyAndFasteners() {
  // Positioned in the calm lower-left negative space:
  // Corner of L-shaped hex key at (205, -155, -142)
  const kx = 205, ky = -155, kz = -142;
  const longLen = 112;  // extends along +X (down-left on screen)
  const shortLen = 46;  // extends along +Y (down-right on screen)
  const bendR = 12;
  const hexR = 4.6;     // hexagonal bar radius

  // We build the 3D centerline path of the L-shaped hex key + local cross-section vectors
  let pathPts = [];
  // Short arm tip (kx, ky + shortLen) -> bend -> Long arm tip (kx + longLen, ky)
  for (let s = shortLen; s >= bendR; s -= 4) {
    pathPts.push({ x: kx, y: ky + s, z: kz, nx: 1, ny: 0 });
  }
  for (let a = 0; a <= 90; a += 15) {
    let cx = kx + bendR - cos(a) * bendR;
    let cy = ky + bendR - sin(a) * bendR;
    pathPts.push({ x: cx, y: cy, z: kz, nx: cos(a), ny: sin(a) });
  }
  for (let s = bendR; s <= longLen; s += 5) {
    pathPts.push({ x: kx + s, y: ky, z: kz, nx: 0, ny: 1 });
  }

  // A hexagonal prism lying flat has 3 visible upper facets:
  // Facet 1 (outer/back slope): z from +hexR*0.5 to +hexR, normal (-0.5)
  // Facet 2 (flat top facet):   z = +hexR, normal (-0.5 to +0.5)
  // Facet 3 (inner/front slope):z from +hexR to +hexR*0.5, normal (+0.5 to +1.0)
  // Facet 4 (lower shadow rim): z from +hexR*0.5 to -hexR*0.4, normal (+1.0)

  function hexFacetStream(nOff, zOff) {
    return pathPts.map(p => iso(p.x + p.nx * nOff, p.y + p.ny * nOff, p.z + zOff));
  }

  // 1. Lower dark facet (Facet 4: inner shadow edge)
  for (let f = 0; f <= 1; f += 0.25) {
    let nOff = lerp(hexR * 0.95, hexR * 0.55, f);
    let zOff = lerp(hexR * 0.4, -hexR * 0.5, f);
    brush.set("pencil_4B", PAL.g6B, 0.85);
    brush.spline(hexFacetStream(nOff, zOff), 0.35);
  }

  // 2. Inner/front angled facet (Facet 3: rich medium-dark steel tone)
  for (let f = 0; f <= 1; f += 0.2) {
    let nOff = lerp(hexR * 0.45, hexR * 0.95, f);
    let zOff = lerp(hexR, hexR * 0.4, f);
    brush.set("pencil_HB", PAL.g2B, 0.75);
    brush.spline(hexFacetStream(nOff, zOff), 0.35);
  }

  // 3. Outer/back angled facet (Facet 1: cool mid-silver steel tone)
  for (let f = 0; f <= 1; f += 0.25) {
    let nOff = lerp(-hexR * 0.95, -hexR * 0.45, f);
    let zOff = lerp(hexR * 0.4, hexR, f);
    brush.set("pencil_6H", PAL.g2H, 0.7);
    brush.spline(hexFacetStream(nOff, zOff), 0.35);
  }

  // 4. Flat Top Facet (Facet 2: blinding bright drawn-steel highlight!)
  for (let f = 0; f <= 1; f += 0.22) {
    let nOff = lerp(-hexR * 0.45, hexR * 0.45, f);
    let zOff = hexR;
    let col = (f > 0.2 && f < 0.8) ? PAL.white : PAL.gleam;
    brush.set("white_chalk", col, 0.85);
    brush.spline(hexFacetStream(nOff, zOff), 0.35);
  }

  // Crisp facet ridge lines along the hexagonal bar
  brush.set("pencil_6H", PAL.g4B, 0.65);
  brush.spline(hexFacetStream(-hexR * 0.95, hexR * 0.4), 0.35);
  brush.spline(hexFacetStream(hexR * 0.45, hexR), 0.35);
  brush.set("white_chalk", PAL.white, 0.95);
  brush.spline(hexFacetStream(-hexR * 0.45, hexR), 0.35);

  // Chamfered hexagonal end faces at both tips + subtle tool-scuff marks
  let tipLong = iso(kx + longLen, ky, kz + hexR * 0.3);
  let tipShort = iso(kx, ky + shortLen, kz + hexR * 0.3);
  for (let tip of [tipLong, tipShort]) {
    brush.set("pencil_4B", PAL.g6B, 0.85);
    brush.circle(tip[0], tip[1], 3.6, 0.15);
    brush.set("white_chalk", PAL.white, 0.75);
    brush.arc(tip[0], tip[1], 3.8, 170, 310);
  }

  // Stamped size marking "5mm CR-V" micro-ticks on the long shaft
  for (let m = 0; m < 6; m++) {
    let pm = iso(kx + 42 + m * 4.2, ky + 1.5, kz + hexR * 0.8);
    brush.set("pencil_6H", PAL.g2B, 0.55);
    brush.line(pm[0], pm[1], pm[0] - 1.5, pm[1] + 2.2);
  }

  // Two spare fastener specimens resting near the hex key
  drawHorizontalBoltSpecimen(kx - 28, ky - 22, kz);
  drawFlatWasherSpecimen(kx - 52, ky - 6, kz);
}

function drawHorizontalBoltSpecimen(bx, by, bz) {
  // Socket-head cap bolt lying along +X
  for (let s = 0; s <= 18; s += 1.6) {
    let p1 = iso(bx + s, by - 3.2, bz + 3);
    let p2 = iso(bx + s, by + 3.2, bz + 3);
    let col = (s % 3.2 < 1.6) ? PAL.g6B : PAL.g4H;
    brush.set("pencil_6H", col, 0.65);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  // Cylindrical socket head
  for (let s = -8; s <= 0; s += 1.2) {
    let p1 = iso(bx + s, by - 5.2, bz + 4.5);
    let p2 = iso(bx + s, by + 5.2, bz + 1.5);
    brush.set("pencil_HB", s > -3 ? PAL.g4B : PAL.g2H, 0.8);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  let pHead = iso(bx - 4, by, bz + 5.2);
  brush.set("white_chalk", PAL.white, 0.85);
  brush.line(pHead[0] - 3, pHead[1] - 1.5, pHead[0] + 3, pHead[1] + 1.5);
}

function drawFlatWasherSpecimen(wx, wy, wz) {
  let pW = iso(wx, wy, wz + 1.5);
