  brush.set("pencil_HB", PAL.g2H, 0.75);
  drawIsoHorizEllipse(pW[0], pW[1], 9.5, 0, 360, 18);
  brush.set("white_chalk", PAL.white, 0.85);
  drawIsoHorizEllipse(pW[0], pW[1], 8.6, 150, 330, 14);
  brush.set("pencil_4B", PAL.g6B, 0.85);
  drawIsoHorizEllipse(pW[0], pW[1] + 0.5, 4.2, 0, 360, 12);
}

