    pSeatRight[0] - COS30 * 3,
    pSeatRight[1] - SIN30 * 3,
    COS30,
    SIN30,
    6.5,
    2.5,
    PAL.pen
  );

  // 5. Rear Spine Bracket [J] insertion axis forward (+X) into Tilt Mechanism rear slot
  let pSpineTip = iso(-236, 0, 68);
  let pMechRear = iso(-68, 0, 68);
