// ============================================================================
// 4. TINY CIRCLED LETTER CODES & LEADER LINES
// ============================================================================

function drawCircledCode(cx, cy, letter, targetX, targetY) {
  const r = 11.5;

  // Short leader line from circle rim to target point + tiny terminal dot
  if (targetX !== undefined && targetY !== undefined) {
    let dx = targetX - cx;
    let dy = targetY - cy;
    let d = sqrt(dx * dx + dy * dy);
    if (d > r + 4) {
      let ux = dx / d;
      let uy = dy / d;
      brush.set("tech_pen", PAL.penFaint, 0.6);
      brush.line(cx + ux * (r + 2), cy + uy * (r + 2), targetX, targetY);
      brush.set("tech_pen", PAL.pen, 0.85);
      brush.circle(targetX, targetY, 1.6, 0.05);
    }
  }

  // Hand-drafted technical pen circle
  brush.set("tech_pen", PAL.pen, 0.8);
  brush.circle(cx, cy, r, 0.08);

  // Vector letter glyphs centered at (cx, cy)
  const w = 3.6;
  const h = 5.0;
  brush.set("tech_pen", PAL.g6B, 0.9);

  if (letter === "A") {
    brush.line(cx - w, cy + h, cx, cy - h);
    brush.line(cx + w, cy + h, cx, cy - h);
    brush.line(cx - w * 0.62, cy + 1.4, cx + w * 0.62, cy + 1.4);
  } else if (letter === "B") {
    brush.line(cx - w * 0.8, cy - h, cx - w * 0.8, cy + h);
    brush.spline([
      [cx - w * 0.8, cy - h],
      [cx + w * 0.7, cy - h * 0.85],
      [cx + w * 0.85, cy - h * 0.35],
      [cx - w * 0.8, cy - 0.2]
    ], 0.5);
    brush.spline([
      [cx - w * 0.8, cy - 0.2],
      [cx + w * 0.85, cy + h * 0.2],
      [cx + w * 0.8, cy + h * 0.85],
      [cx - w * 0.8, cy + h]
    ], 0.5);
  } else if (letter === "C") {
    brush.spline([
      [cx + w * 0.85, cy - h * 0.65],
      [cx, cy - h],
      [cx - w * 0.9, cy - h * 0.45],
      [cx - w * 0.9, cy + h * 0.45],
      [cx, cy + h],
      [cx + w * 0.85, cy + h * 0.65]
    ], 0.5);
  } else if (letter === "D") {
    brush.line(cx - w * 0.8, cy - h, cx - w * 0.8, cy + h);
    brush.spline([
      [cx - w * 0.8, cy - h],
      [cx + w * 0.4, cy - h * 0.9],
      [cx + w * 0.95, cy],
      [cx + w * 0.4, cy + h * 0.9],
      [cx - w * 0.8, cy + h]
    ], 0.5);
  } else if (letter === "E") {
    brush.line(cx - w * 0.8, cy - h, cx - w * 0.8, cy + h);
    brush.line(cx - w * 0.8, cy - h, cx + w * 0.8, cy - h);
    brush.line(cx - w * 0.8, cy, cx + w * 0.55, cy);
    brush.line(cx - w * 0.8, cy + h, cx + w * 0.85, cy + h);
  } else if (letter === "F") {
    brush.line(cx - w * 0.8, cy - h, cx - w * 0.8, cy + h);
    brush.line(cx - w * 0.8, cy - h, cx + w * 0.85, cy - h);
    brush.line(cx - w * 0.8, cy - 0.3, cx + w * 0.55, cy - 0.3);
  } else if (letter === "G") {
    brush.spline([
      [cx + w * 0.85, cy - h * 0.65],
      [cx, cy - h],
      [cx - w * 0.9, cy - h * 0.45],
      [cx - w * 0.9, cy + h * 0.45],
      [cx, cy + h],
      [cx + w * 0.9, cy + h * 0.55],
      [cx + w * 0.9, cy + 0.2]
    ], 0.45);
    brush.line(cx + 0.2, cy + 0.2, cx + w * 0.9, cy + 0.2);
  } else if (letter === "H") {
    brush.line(cx - w * 0.85, cy - h, cx - w * 0.85, cy + h);
    brush.line(cx + w * 0.85, cy - h, cx + w * 0.85, cy + h);
    brush.line(cx - w * 0.85, cy, cx + w * 0.85, cy);
  } else if (letter === "J") {
    brush.line(cx - w * 0.4, cy - h, cx + w * 0.8, cy - h);
    brush.spline([
      [cx + w * 0.5, cy - h],
      [cx + w * 0.5, cy + h * 0.55],
      [cx - w * 0.15, cy + h],
      [cx - w * 0.85, cy + h * 0.55]
    ], 0.45);
  } else if (letter === "K") {
    brush.line(cx - w * 0.85, cy - h, cx - w * 0.85, cy + h);
    brush.line(cx + w * 0.85, cy - h, cx - w * 0.85, cy + 0.5);
    brush.line(cx - w * 0.35, cy - 1.2, cx + w * 0.9, cy + h);
  }
}

