  drawChalkyDuskLight();

  noLoop();
}

// ============================================================================
// CLOTH 3D DRAPE & FOLD GEOMETRY
// ============================================================================

function clothEdges(u) {
  let pinch =
    7 * exp(-pow((u - 260) / 90, 2)) +
    11 * exp(-pow((u - 540) / 110, 2)) +
    15 * exp(-pow((u - 910) / 100, 2));
  let waveL = 5 * sin(u * 0.35 + 15) + 3 * cos(u * 0.85);
  let waveR = 5 * cos(u * 0.32 - 25) + 4 * sin(u * 0.78 + 40);
  return {
    vMin: -304 + pinch * 0.55 + waveL,
    vMax: 304 - pinch * 0.65 + waveR
  };
}

function clothElevation(u, v) {
  // Primary diagonal and longitudinal drape folds
  let d1 = (u - 0.58 * v - 225) / 52;
  let fold1 = 17.5 * exp(-d1 * d1);

  let d2 = (u + 0.42 * v - 495) / 68;
  let fold2 = 14.0 * sin(d2 * 95) * exp(-d2 * d2 * 0.65);

  let d3 = (u - 0.32 * v - 890) / 58;
  let fold3 = 23.0 * exp(-d3 * d3);

  let d4 = (u + 0.65 * v - 1060) / 74;
  let fold4 = 16.5 * exp(-d4 * d4);

  // Edge ripple folds near selvedges
  let edgeDistR = (v - 195) / 70;
  let rippleR = 9.5 * sin(u * 0.75 - v * 0.4) * exp(-edgeDistR * edgeDistR);

  let edgeDistL = (v + 185) / 75;
  let rippleL = 8.0 * cos(u * 0.62 + v * 0.5) * exp(-edgeDistL * edgeDistL);

  // Subtle weight depression under the resting teak blocks around (u=635, v=15)
  let bx = (u - 635) / 85;
  let by = (v - 15) / 95;
  let blockPress = -8.5 * exp(-(bx * bx + by * by));

  // Courtyard micro-undulation beneath cloth
  let groundWave = 7.0 * (noise(u * 0.0045 + 10, v * 0.0045 + 20) - 0.5);

  return fold1 + fold2 + fold3 + fold4 + rippleR + rippleL + blockPress + groundWave;
}

function clothSlope(u, v) {
  let eps = 3.0;
  let hC = clothElevation(u, v);
  let dhdu = (clothElevation(u + eps, v) - hC) / eps;
  let dhdv = (clothElevation(u, v + eps) - hC) / eps;
  // Raking dusk light comes from upper-left (roughly along -v and -u)
  return -0.52 * dhdu - 0.85 * dhdv;
}

function clothToScreen(u, v) {
  let h = clothElevation(u, v);
  let bx = CLOTH_ORIGIN.x + u * cosA + v * nxA;
  let by = CLOTH_ORIGIN.y + u * sinA + v * nyA;
  // Perspective displacement from standing viewpoint
  return {
    x: bx - h * 0.36,
    y: by - h * 0.68,
    h: h
  };
}

function isInsideCloth(x, y, margin = 0) {
  let dx = x - CLOTH_ORIGIN.x;
  let dy = y - CLOTH_ORIGIN.y;
  let u = dx * cosA + dy * sinA;
  let v = dx * nxA + dy * nyA;
  if (u < -48 - margin || u > 1520 + margin) return false;
  let edges = clothEdges(u);
  return v >= edges.vMin - margin && v <= edges.vMax + margin;
}

// ============================================================================
// 1 & 2. SUN-DRIED CRACKED MUD COURTYARD (PENCIL & CHALKY WASHES)
// ============================================================================

function drawMudCourtyardBase() {
  brush.noStroke();

  // Batch 1: Warm sun-baked clay patches
  brush.fill(PAL.mudWarm, 85);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.25);
  for (let i = 0; i < 14; i++) {
    let cx = random(60, 1140);
    let cy = random(60, 1140);
    if (isInsideCloth(cx, cy, -60)) continue;
    drawOrganicBlob(cx, cy, random(140, 280), random(90, 210), random(360), 9);
  }

  // Batch 2: Cooler chalky dusk clay patches
  brush.fill(PAL.mudCool, 75);
  brush.fillBleed(0.4, "out");
  brush.fillTexture(0.6, 0.3);
  for (let i = 0; i < 14; i++) {
    let cx = random(40, 1160);
    let cy = random(40, 1160);
    if (isInsideCloth(cx, cy, -50)) continue;
    drawOrganicBlob(cx, cy, random(130, 260), random(100, 220), random(360), 9);
  }

  // Batch 3: Lavender-grey dusk pools in slight courtyard hollows
  brush.fill(PAL.mudDusk, 65);
  brush.fillBleed(0.45, "out");
  for (let i = 0; i < 10; i++) {
    let cx = random(50, 1150);
    let cy = random(50, 1150);
    if (isInsideCloth(cx, cy, -30)) continue;
    drawOrganicBlob(cx, cy, random(110, 220), random(80, 160), random(360), 8);
  }

  brush.noFill();

  // Faint broom-swept arc marks in dry pencil across the courtyard
  brush.set("2H", PAL.mudShadow, 0.55);
  for (let i = 0; i < 95; i++) {
    let sx = random(20, 1180);
    let sy = random(20, 1180);
    if (isInsideCloth(sx, sy, 15)) continue;
    let baseAng = 25 + 20 * noise(sx * 0.003, sy * 0.003);
    let r = random(70, 160);
    brush.arc(sx, sy, r, baseAng, baseAng + random(18, 36));
  }
}

function drawOrganicBlob(cx, cy, rx, ry, rotDeg, steps) {
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  brush.beginShape(0.45);
  for (let i = 0; i < steps; i++) {
    let ang = (i / steps) * 360;
    let n = 0.75 + 0.45 * noise(cx * 0.01 + cos(ang), cy * 0.01 + sin(ang));
    let lx = cos(ang) * rx * n;
    let ly = sin(ang) * ry * n;
    brush.vertex(cx + lx * c - ly * s, cy + lx * s + ly * c);
  }
  brush.endShape(true);
}

function drawCrackedMudNetwork() {
  // Generate jittered Voronoi-like lattice for primary mud desiccation polygons
  let cols = 11;
  let rows = 11;
  let cellW = 1280 / cols;
  let cellH = 1280 / rows;
  let nodes = [];

  for (let r = 0; r <= rows; r++) {
    nodes[r] = [];
    for (let c = 0; c <= cols; c++) {
      let x = -40 + c * cellW + random(-cellW * 0.34, cellW * 0.34);
      let y = -40 + r * cellH + random(-cellH * 0.34, cellH * 0.34);
      nodes[r][c] = { x, y };
    }
  }

  let primaryEdges = [];
  let secondaryEdges = [];

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      let p00 = nodes[r][c];
      let p10 = nodes[r][c + 1];
      let p01 = nodes[r + 1][c];
      let p11 = nodes[r + 1][c + 1];

      if (random() < 0.88) primaryEdges.push([p00, p10]);
      if (random() < 0.88) primaryEdges.push([p00, p01]);

      // Subdivide cell with internal secondary clay crack
      if (random() < 0.75) {
        let t1 = random(0.25, 0.75);
        let t2 = random(0.25, 0.75);
        let m1 = {
          x: lerp(p00.x, p10.x, t1),
          y: lerp(p00.y, p10.y, t1)
        };
        let m2 = {
          x: lerp(p01.x, p11.x, t2),
          y: lerp(p01.y, p11.y, t2)
        };
        secondaryEdges.push([m1, m2]);

        if (random() < 0.55) {
          let m3 = {
            x: lerp(m1.x, m2.x, random(0.3, 0.7)),
            y: lerp(m1.y, m2.y, random(0.3, 0.7))
          };
          let m4 = {
            x: lerp(p00.x, p01.x, random(0.25, 0.75)),
            y: lerp(p00.y, p01.y, random(0.25, 0.75))
          };
          secondaryEdges.push([m3, m4]);
        }
      }
    }
  }

  // Draw primary mud cracks in pencil: shadow halo, curled sunlit lip, and dark fissure
  for (let e of primaryEdges) {
    let mx = (e[0].x + e[1].x) * 0.5;
    let my = (e[0].y + e[1].y) * 0.5;
    if (isInsideCloth(mx, my, -15) && isInsideCloth(e[0].x, e[0].y, -15) && isInsideCloth(e[1].x, e[1].y, -15)) {
      continue;
    }
    drawMudCrackFissure(e[0], e[1], true);
  }

  // Draw secondary hairline cracks in finer pencil
  for (let e of secondaryEdges) {
    let mx = (e[0].x + e[1].x) * 0.5;
    let my = (e[0].y + e[1].y) * 0.5;
    if (isInsideCloth(mx, my, -10)) continue;
    drawMudCrackFissure(e[0], e[1], false);
  }

  // Draw fine pencil shading, dry silt grains, tiny pebbles & straw bits on mud
  drawMudSurfaceMicroDetail();
}

function drawMudCrackFissure(pA, pB, isPrimary) {
  let steps = isPrimary ? 9 : 6;
  let pts = [];
  let dx = pB.x - pA.x;
  let dy = pB.y - pA.y;
  let len = sqrt(dx * dx + dy * dy);
  if (len < 8) return;
  let nx = -dy / len;
  let ny = dx / len;

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let jag =
      sin(t * 180) *
      (noise(pA.x * 0.03 + i * 0.7, pA.y * 0.03) - 0.5) *
      (isPrimary ? 16 : 9);
    let px = lerp(pA.x, pB.x, t) + nx * jag;
    let py = lerp(pA.y, pB.y, t) + ny * jag;
    pts.push({ x: px, y: py });
  }

  // 1. Sunlit curled clay lip (offset slightly down-right from crack)
  brush.set("cpencil", PAL.crackLip, isPrimary ? 1.15 : 0.75);
  for (let i = 0; i < pts.length - 1; i++) {
    if (isInsideCloth(pts[i].x, pts[i].y, 2)) continue;
    brush.line(
      pts[i].x + 1.8,
      pts[i].y + 1.8,
      pts[i + 1].x + 1.8,
      pts[i + 1].y + 1.8
    );
  }

  // 2. Soft bevelled graphite edge shading along crack lip
  brush.set("HB", PAL.mudShadow, isPrimary ? 0.95 : 0.6);
  for (let i = 0; i < pts.length - 1; i++) {
    if (isInsideCloth(pts[i].x, pts[i].y, 2)) continue;
    brush.line(
      pts[i].x - 1.4,
      pts[i].y - 1.2,
      pts[i + 1].x - 1.4,
      pts[i + 1].y - 1.2
    );
    // Occasional tiny lateral micro-spurs branching off main crack
    if (isPrimary && random() < 0.28) {
      let ang = atan2(dy, dx) + (random() < 0.5 ? 55 : -55) + random(-15, 15);
      let spurLen = random(8, 22);
      brush.line(
        pts[i].x,
        pts[i].y,
        pts[i].x + cos(ang) * spurLen,
        pts[i].y + sin(ang) * spurLen
      );
    }
  }

  // 3. Crisp dark desiccation fissure center in 2B pencil
  brush.set("2B", isPrimary ? PAL.crackDark : PAL.crackMid, isPrimary ? 0.85 : 0.5);
  for (let i = 0; i < pts.length - 1; i++) {
    if (isInsideCloth(pts[i].x, pts[i].y, 2)) continue;
    let p = isPrimary ? 0.8 + 0.4 * sin((i / pts.length) * 180) : 0.65;
    brush.strokeWeight((isPrimary ? 0.9 : 0.5) * p);
    brush.line(pts[i].x, pts[i].y, pts[i + 1].x, pts[i + 1].y);
  }
}

function drawMudSurfaceMicroDetail() {
  // Pencil cross-grain texture & tiny pebbles/chaff scattered on the courtyard
  for (let i = 0; i < 360; i++) {
    let x = random(15, 1185);
    let y = random(15, 1185);
    if (isInsideCloth(x, y, 8)) continue;

    if (random() < 0.65) {
      // Tiny silt grain or pebble with highlight & shadow
      let r = random(1.8, 5.2);
      brush.set("HB", PAL.pebble2, 0.65);
      brush.circle(x + 1, y + 1, r, 0.35);
      brush.set("cpencil", PAL.crackLip, 0.6);
      brush.arc(x - 0.6, y - 0.6, r * 0.85, 195, 330);
    } else {
      // Sun-dried straw chaff bit in pencil
      let ang = random(360);
      let l = random(7, 18);
      brush.set("2H", PAL.clothShade1, 0.65);
      brush.line(x, y, x + cos(ang) * l, y + sin(ang) * l);
      brush.set("HB", PAL.crackMid, 0.4);
      brush.line(x, y + 0.8, x + cos(ang) * l, y + sin(ang) * l + 0.8);
    }
  }

  // Subtle diagonal graphite hatching in shallow mud depressions
  brush.set("2H", PAL.mudShadow, 0.42);
  for (let i = 0; i < 180; i++) {
    let x = random(20, 1180);
    let y = random(20, 1180);
    if (isInsideCloth(x, y, 12)) continue;
    if (noise(x * 0.008, y * 0.008) > 0.52) {
      let l = random(16, 38);
      brush.line(x, y, x + l * 0.85, y - l * 0.52);
    }
  }
}

// ============================================================================
// 3 & 4. COTTON CLOTH CAST SHADOW & WATERCOLOR FOLD SHADING
// ============================================================================

function drawClothCastShadow() {
  brush.noStroke();

  // Soft layered dusk shadow under the cloth edges (light from top-left casts shadow down-right)
  let shadowPasses = [
    { offX: 16, offY: 14, col: PAL.mudShadow, alpha: 85, bleed: 0.32 },
    { offX: 8, offY: 7, col: PAL.crackMid, alpha: 95, bleed: 0.18 }
  ];

  for (let pass of shadowPasses) {
    brush.fill(pass.col, pass.alpha);
    brush.fillBleed(pass.bleed, "out");
    brush.fillTexture(0.5, 0.25);

    let uStep = 45;
    for (let u = -45; u < 1480; u += uStep) {
      let u2 = u + uStep + 4;
      let e1 = clothEdges(u);
      let e2 = clothEdges(u2);

      // Right-hand shadow band (stronger because light is from upper-left)
      let p1 = clothToScreen(u, e1.vMin);
      let p2 = clothToScreen(u2, e2.vMin);
      let p3 = clothToScreen(u2, e2.vMin + 55);
      let p4 = clothToScreen(u, e1.vMin + 55);
      let lift = max(0, p1.h * 0.55);

      brush.beginShape(0.2);
      brush.vertex(p1.x + pass.offX + lift, p1.y + pass.offY + lift);
      brush.vertex(p2.x + pass.offX + lift, p2.y + pass.offY + lift);
      brush.vertex(p3.x, p3.y);
      brush.vertex(p4.x, p4.y);
      brush.endShape(true);

      // Left-hand underside contact shadow
      let q1 = clothToScreen(u, e1.vMax);
      let q2 = clothToScreen(u2, e2.vMax);
      let q3 = clothToScreen(u2, e2.vMax - 35);
      let q4 = clothToScreen(u, e1.vMax - 35);

      brush.beginShape(0.2);
      brush.vertex(q1.x + pass.offX * 0.45, q1.y + pass.offY * 0.55);
      brush.vertex(q2.x + pass.offX * 0.45, q2.y + pass.offY * 0.55);
      brush.vertex(q3.x, q3.y);
      brush.vertex(q4.x, q4.y);
      brush.endShape(true);
    }
  }
  brush.noFill();
}

function drawCottonWatercolorGround() {
  brush.noStroke();

  // Base opaque wash so mud cracks don't bleed through the woven cotton
  let uSamples = [];
  for (let u = -45; u <= 1500; u += 32) uSamples.push(u);

  brush.wash(PAL.clothBase, 235);
  brush.beginShape(0.15);
  for (let u of uSamples) {
    let e = clothEdges(u);
    let p = clothToScreen(u, e.vMin);
    brush.vertex(p.x, p.y);
  }
  for (let i = uSamples.length - 1; i >= 0; i--) {
    let u = uSamples[i];
    let e = clothEdges(u);
    let p = clothToScreen(u, e.vMax);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(true);
  brush.noWash();

  // Group watercolor patches by tonal bucket for fast, rich watercolor rendering
  let buckets = [
    { col: PAL.clothSun, alpha: 95, bleed: 0.25, patches: [] },
    { col: PAL.clothWarm, alpha: 85, bleed: 0.28, patches: [] },
    { col: PAL.clothMid, alpha: 80, bleed: 0.28, patches: [] },
    { col: PAL.clothShade1, alpha: 95, bleed: 0.3, patches: [] },
    { col: PAL.clothShade2, alpha: 105, bleed: 0.32, patches: [] },
    { col: PAL.clothDuskShade, alpha: 90, bleed: 0.35, patches: [] }
  ];

  let du = 38;
  let dv = 42;
  for (let u = -42; u < 1470; u += du) {
    let e1 = clothEdges(u);
    let e2 = clothEdges(u + du);
    for (let t = 0; t < 14; t++) {
      let f0 = t / 14;
      let f1 = (t + 1) / 14;
      let v00 = lerp(e1.vMin, e1.vMax, f0);
      let v01 = lerp(e1.vMin, e1.vMax, f1);
      let v11 = lerp(e2.vMin, e2.vMax, f1);
      let v10 = lerp(e2.vMin, e2.vMax, f0);

      let uc = u + du * 0.5;
      let vc = (v00 + v01) * 0.5;
      let s = clothSlope(uc, vc);
      let h = clothElevation(uc, vc);

      let quad = [
        clothToScreen(u - 3, v00 - 3),
        clothToScreen(u + du + 3, v10 - 3),
        clothToScreen(u + du + 3, v11 + 3),
        clothToScreen(u - 3, v01 + 3)
      ];

      if (s > 0.16 || h > 14) {
        buckets[0].patches.push(quad);
      } else if (s > 0.04) {
        buckets[1].patches.push(quad);
      } else if (s > -0.06) {
        buckets[2].patches.push(quad);
      } else if (s > -0.18) {
        buckets[3].patches.push(quad);
      } else {
        buckets[4].patches.push(quad);
        if (s < -0.26) buckets[5].patches.push(quad);
      }
    }
  }

  for (let b of buckets) {
    brush.fill(b.col, b.alpha);
    brush.fillBleed(b.bleed, "out");
    brush.fillTexture(0.62, 0.28);
    for (let q of b.patches) {
      brush.beginShape(0.22);
      for (let pt of q) brush.vertex(pt.x, pt.y);
      brush.endShape(true);
    }
  }

  // Long continuous watercolor fold ribbons along the primary diagonal ridges & troughs
  let foldTraces = [
    { u0: 215, slopeV: 0.58, w: 38, col: PAL.clothSun, alpha: 95, offsetV: -18 },
    { u0: 248, slopeV: 0.58, w: 46, col: PAL.clothShade2, alpha: 110, offsetV: 22 },
    { u0: 478, slopeV: -0.42, w: 42, col: PAL.clothSun, alpha: 88, offsetV: -15 },
    { u0: 515, slopeV: -0.42, w: 50, col: PAL.clothDuskShade, alpha: 105, offsetV: 20 },
    { u0: 872, slopeV: 0.32, w: 46, col: PAL.clothSun, alpha: 100, offsetV: -22 },
    { u0: 912, slopeV: 0.32, w: 54, col: PAL.clothShade2, alpha: 115, offsetV: 24 },
    { u0: 1045, slopeV: -0.65, w: 44, col: PAL.clothShade1, alpha: 95, offsetV: 18 }
  ];

  for (let ft of foldTraces) {
    brush.fill(ft.col, ft.alpha);
    brush.fillBleed(0.35, "out");
    brush.fillTexture(0.65, 0.22);

    let leftPts = [];
    let rightPts = [];
    for (let s = -260; s <= 260; s += 35) {
      let u = ft.u0 + s * ft.slopeV;
      let e = clothEdges(u);
      let vCenter = constrain(s, e.vMin + 18, e.vMax - 18);
      let pL = clothToScreen(u - ft.w * 0.5, vCenter + ft.offsetV);
      let pR = clothToScreen(u + ft.w * 0.5, vCenter + ft.offsetV);
      leftPts.push(pL);
      rightPts.push(pR);
    }
    brush.beginShape(0.35);
    for (let p of leftPts) brush.vertex(p.x, p.y);
    for (let i = rightPts.length - 1; i >= 0; i--) brush.vertex(rightPts[i].x, rightPts[i].y);
    brush.endShape(true);
  }

  brush.noFill();
}

// ============================================================================
// 5. FABRIC WEAVE & SELVEDGE FRINGE THREADS
// ============================================================================

function drawFabricWeaveAndSelvedge() {
  // Fine cotton warp threads running along u
  for (let v = -296; v <= 296; v += 7.5) {
    let isLight = abs(v % 15) < 7.5;
    brush.set("cotton_thread", isLight ? PAL.weaveLight : PAL.weaveDark, isLight ? 0.75 : 0.65);

    for (let u = -40; u < 1460; u += 68) {
      if (random() < 0.22) continue;
      let e = clothEdges(u);
      if (v < e.vMin + 4 || v > e.vMax - 4) continue;
      let p1 = clothToScreen(u, v);
      let p2 = clothToScreen(u + random(38, 62), v);
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }
  }

  // Fine cotton weft threads running across v
  for (let u = -36; u <= 1460; u += 8.0) {
    let isLight = abs(u % 16) < 8;
    brush.set("cotton_thread", isLight ? PAL.weaveLight : PAL.weaveDark, 0.65);
    let e = clothEdges(u);

    for (let v = e.vMin + 6; v < e.vMax - 45; v += 58) {
      if (random() < 0.25) continue;
      let p1 = clothToScreen(u, v);
      let p2 = clothToScreen(u, min(e.vMax - 4, v + random(34, 52)));
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }
  }

  // Woven selvedge edge cords & frayed cotton fringe spilling onto the mud courtyard
  for (let u = -42; u <= 1470; u += 4.5) {
    let e = clothEdges(u);

    // Right selvedge fringe (vMin side)
    let pEdgeR = clothToScreen(u, e.vMin);
    let fringeLenR = random(7, 17);
    let angR = CLOTH_ANGLE - 90 + random(-18, 18);
    brush.set("2H", PAL.weaveDark, 0.55);
    brush.line(
      pEdgeR.x,
      pEdgeR.y,
      pEdgeR.x + cos(angR) * fringeLenR,
      pEdgeR.y + sin(angR) * fringeLenR
    );
    brush.set("cpencil", PAL.weaveLight, 0.5);
    brush.line(
      pEdgeR.x,
      pEdgeR.y,
      pEdgeR.x + cos(angR) * (fringeLenR * 0.75),
      pEdgeR.y + sin(angR) * (fringeLenR * 0.75)
    );

    // Left selvedge fringe (vMax side)
    let pEdgeL = clothToScreen(u, e.vMax);
    let fringeLenL = random(7, 16);
    let angL = CLOTH_ANGLE + 90 + random(-18, 18);
    brush.set("2H", PAL.weaveDark, 0.55);
    brush.line(
      pEdgeL.x,
      pEdgeL.y,
      pEdgeL.x + cos(angL) * fringeLenL,
      pEdgeL.y + sin(angL) * fringeLenL
    );
    brush.set("cpencil", PAL.weaveLight, 0.5);
    brush.line(
      pEdgeL.x,
      pEdgeL.y,
      pEdgeL.x + cos(angL) * (fringeLenL * 0.75),
      pEdgeL.y + sin(angL) * (fringeLenL * 0.75)
    );
  }
}

// ============================================================================
// 6. DRY BROKEN MARKER ENGINE & HAND-BLOCK PRINTED PATTERNS
// ============================================================================

// Evaluates local ink starvation & cotton weave skipping at cloth coordinates (u, v)
function getStarvationFactor(u, v, stampStarve) {
  // Cotton warp/weft micro-grid wave
  let weaveRidge = 0.5 * (sin(u * 28) + cos(v * 28));
  // Fold ridge tension (steep slopes cause slight block contact skip)
  let slopeMag = abs(clothSlope(u, v));
  // Stamp directional pressure starvation
  let dirStarve =
    stampStarve.base +
    stampStarve.gx * ((u - stampStarve.cu) / 52) +
    stampStarve.gy * ((v - stampStarve.cv) / 52);
  let n = noise(u * 0.045, v * 0.045);
  return constrain(dirStarve + slopeMag * 0.55 - weaveRidge * 0.16 + (n - 0.45) * 0.35, 0, 1);
}

// Draws a block-printed line in cloth (u,v) space using dry marker strokes that skip across weave
function drawDryBlockPath(uvPts, colMain, colStarved, weight, stampReg, stampStarve) {
  if (uvPts.length < 2) return;
  let ca = cos(stampReg.rot);
  let sa = sin(stampReg.rot);

  for (let i = 0; i < uvPts.length - 1; i++) {
    let p0 = uvPts[i];
    let p1 = uvPts[i + 1];
    let du = p1.u - p0.u;
    let dv = p1.v - p0.v;
    let distUV = sqrt(du * du + dv * dv);
    let subSteps = max(1, ceil(distUV / 4.2));

    for (let s = 0; s < subSteps; s++) {
      let t0 = s / subSteps;
      let t1 = (s + 0.86) / subSteps;
      let lu0 = lerp(p0.u, p1.u, t0) - stampStarve.cu;
      let lv0 = lerp(p0.v, p1.v, t0) - stampStarve.cv;
      let lu1 = lerp(p0.u, p1.u, t1) - stampStarve.cu;
      let lv1 = lerp(p0.v, p1.v, t1) - stampStarve.cv;

      let u0 = stampStarve.cu + lu0 * ca - lv0 * sa + stampReg.du;
      let v0 = stampStarve.cv + lu0 * sa + lv0 * ca + stampReg.dv;
      let u1 = stampStarve.cu + lu1 * ca - lv1 * sa + stampReg.du;
      let v1 = stampStarve.cv + lu1 * sa + lv1 * ca + stampReg.dv;

      let starve = getStarvationFactor((u0 + u1) * 0.5, (v0 + v1) * 0.5, stampStarve);

      // Skip across fabric weave threads when dye is starved
      if (starve > 0.74 && random() < 0.72) continue;
      if (starve > 0.48 && random() < 0.35) continue;

      let sc0 = clothToScreen(u0, v0);
      let sc1 = clothToScreen(u1, v1);

      if (starve > 0.42) {
        brush.set("starved_marker", colStarved, weight * (0.72 - starve * 0.25));
      } else {
        brush.set("dry_block_marker", colMain, weight * (0.95 - starve * 0.2));
      }
      brush.line(sc0.x, sc0.y, sc1.x, sc1.y);
    }
  }
}

// Draws a carved solid relief area (like petal or leaf fill) as closely packed dry skipping marker strokes
function drawDryBlockReliefPatch(cu, cv, rx, ry, rotDeg, colMain, colStarved, stampReg, stampStarve) {
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  let spacing = 3.1;

  for (let y = -ry; y <= ry; y += spacing) {
    let halfW = rx * sqrt(max(0, 1 - (y * y) / (ry * ry)));
    if (halfW < 1.5) continue;
    let x0 = -halfW;
    let x1 = halfW;
    let p0 = {
      u: cu + x0 * c - y * s,
      v: cv + x0 * s + y * c
    };
    let p1 = {
      u: cu + x1 * c - y * s,
      v: cv + x1 * s + y * c
    };
    drawDryBlockPath([p0, p1], colMain, colStarved, 0.72, stampReg, stampStarve);
  }

  // Slight dye bead rim around the carved wood edge
  let rimPts = [];
  let steps = 12;
  for (let i = 0; i <= steps; i++) {
    let ang = (i / steps) * 360;
    let lx = cos(ang) * rx;
    let ly = sin(ang) * ry;
    rimPts.push({
      u: cu + lx * c - ly * s,
      v: cv + lx * s + ly * c
    });
  }
  drawDryBlockPath(rimPts, colMain, colStarved, 0.55, stampReg, stampStarve);
}

function drawBlockPrintedPatterns() {
  // 1. Cross-border (Palla) at upper-left end of cloth (u = -25 .. 62)
  drawEndPallaBorder(-22, 58);

  // 2. Left & Right running selvedge borders (printed up to u = 740, then half-printed to 860)
  drawSelvedgeBorders();

  // 3. Main field square Buta block stamps (4 columns across v = -212 .. +212)
  let stampSize = 104;
  let uStart = 68;
  let numRows = 8; // Rows 0..4 full, Row 5 active/partial, Row 6 outline only, Row 7+ chalk ticks

  for (let row = 0; row < numRows; row++) {
    let rowU = uStart + row * stampSize;
    for (let col = 0; col < 4; col++) {
      let colV = -156 + col * stampSize;

      // Determine print state for half-printed narrative
      let doIndigo = false;
      let doMadder = false;
      let doIron = false;

      if (row <= 4) {
        // Fully printed rows
        doIndigo = true;
        doMadder = true;
        doIron = true;
      } else if (row === 5) {
        // Row 5 (u ~ 588..692): where the carved teak blocks currently rest!
        if (col === 0) {
          doIndigo = true;
          doMadder = true;
          doIron = true;
        } else if (col === 1 || col === 2) {
          // Madder & Iron-black freshly stamped under/beside the teak blocks
          doIndigo = false;
          doMadder = true;
          doIron = true;
        } else {
          // Col 3 has only Iron-black outline (rekh)
          doIndigo = false;
          doMadder = false;
          doIron = true;
        }
      } else if (row === 6) {
        // Row 6 (u ~ 692..796): only first 2 columns have Iron-black outline block stamped
        if (col <= 1) {
          doIron = true;
        }
      }

      if (doIndigo || doMadder || doIron) {
        drawSingleButaStamp(rowU + stampSize * 0.5, colV, stampSize, {
          indigo: doIndigo,
          madder: doMadder,
          iron: doIron,
          extraStarve: row === 5 && col === 2 ? 0.18 : 0
        });
      }
    }
  }

  // 4. Printer's chalk/charcoal registration guide ticks (`chhapa` grid) on unprinted cloth
  drawPrinterRegistrationTicks(uStart + 5 * stampSize, stampSize);
}

function drawEndPallaBorder(u0, u1) {
  let regIron = { du: 0, dv: 0, rot: 0.2 };
  let regMadder = { du: 2.2, dv: -1.8, rot: -0.5 };
  let regIndigo = { du: -1.8, dv: 2.4, rot: 0.6 };
  let starve = { cu: (u0 + u1) * 0.5, cv: 0, base: 0.18, gx: 0.1, gy: -0.08 };

  // Twin guard stripes across cloth width
  for (let uLine of [u0, u0 + 7, u1 - 7, u1]) {
    drawDryBlockPath(
      [
        { u: uLine, v: -215 },
        { u: uLine, v: 215 }
      ],
      PAL.ironBlack,
      PAL.ironDry,
      0.85,
      regIron,
      starve
    );
  }

  // Architectural mihrab arches & cypress trees across the palla band
  for (let v = -185; v <= 185; v += 52) {
    let cu = (u0 + u1) * 0.5;
    starve.cv = v;

    // Indigo arch spandrel fills
    drawDryBlockReliefPatch(cu - 12, v + 18, 8, 12, 15, PAL.indigoBlue, PAL.indigoLight, regIndigo, starve);
    drawDryBlockReliefPatch(cu - 12, v - 18, 8, 12, -15, PAL.indigoBlue, PAL.indigoLight, regIndigo, starve);

    // Madder red central cypress/floral tree
    drawDryBlockReliefPatch(cu + 2, v, 22, 11, 0, PAL.madderRed, PAL.madderLight, regMadder, starve);
    drawDryBlockReliefPatch(cu - 14, v, 8, 8, 0, PAL.madderDark, PAL.madderRed, regMadder, starve);

    // Iron-black arch & serrated leaf outlines
    let archPts = [];
    for (let a = -90; a <= 90; a += 22) {
      archPts.push({
        u: cu + 24 * cos(a) - 6,
        v: v + 22 * sin(a)
      });
    }
    drawDryBlockPath(archPts, PAL.ironBlack, PAL.ironDry, 0.78, regIron, starve);

    // Stem and leaf ribs inside arch
    drawDryBlockPath(
      [
        { u: u1 - 9, v: v },
        { u: u0 + 11, v: v }
      ],
      PAL.ironBlack,
      PAL.ironDry,
      0.7,
      regIron,
      starve
    );
    for (let k = -2; k <= 2; k++) {
      let bu = cu + k * 9;
      drawDryBlockPath(
        [
          { u: bu + 4, v: v - 9 },
          { u: bu, v: v },
          { u: bu + 4, v: v + 9 }
        ],
        PAL.ironBlack,
        PAL.ironDry,
        0.62,
        regIron,
        starve
      );
    }
  }
}

function drawSelvedgeBorders() {
  for (let side of [-1, 1]) {
    let vInner = side * 214;
    let vMid = side * 248;
    let vOuter = side * 282;

    // Border blocks repeat every 104 units along u
    for (let blockIdx = 0; blockIdx < 9; blockIdx++) {
      let u0 = -22 + blockIdx * 104;
      let u1 = u0 + 104;

      // Half-printed progression on borders too
      let hasIndigo = blockIdx <= 5;
      let hasMadder = blockIdx <= 6;
      let hasIron = blockIdx <= 7;
      if (!hasIron) continue;

      let starve = {
        cu: (u0 + u1) * 0.5,
        cv: vMid,
        base: random(0.14, 0.34) + (blockIdx >= 6 ? 0.18 : 0),
        gx: random(-0.22, 0.22),
        gy: random(-0.2, 0.2)
      };

      let regIron = { du: random(-1.2, 1.2), dv: random(-1.2, 1.2), rot: random(-0.6, 0.6) };
      let regMadder = { du: random(-3.4, 3.4), dv: random(-3.2, 3.2), rot: random(-1.1, 1.1) };
      let regIndigo = { du: random(-3.2, 3.2), dv: random(-3.4, 3.4), rot: random(-1.1, 1.1) };

      // Outer woven selvedge stripes in Madder & Iron-black
      if (hasMadder) {
        drawDryBlockPath(
          [
            { u: u0, v: vOuter },
            { u: u1, v: vOuter }
          ],
          PAL.madderRed,
          PAL.madderLight,
          1.35,
          regMadder,
          starve
        );
      }
      drawDryBlockPath(
        [
          { u: u0, v: vInner },
          { u: u1, v: vInner }
        ],
        PAL.ironBlack,
        PAL.ironDry,
        0.9,
        regIron,
        starve
      );
      drawDryBlockPath(
        [
          { u: u0, v: vInner + side * 7 },
          { u: u1, v: vInner + side * 7 }
        ],
        PAL.ironBlack,
        PAL.ironDry,
        0.75,
        regIron,
        starve
      );
      drawDryBlockPath(
        [
          { u: u0, v: vOuter - side * 6 },
          { u: u1, v: vOuter - side * 6 }
        ],
        PAL.ironBlack,
        PAL.ironDry,
        0.85,
        regIron,
        starve
      );

      // Undulating vine (`bel`) with alternating Madder flowers & Indigo leaves
      let vinePts = [];
      for (let u = u0; u <= u1; u += 8) {
        let wave = sin(((u - u0) / 104) * 720) * 11;
        vinePts.push({ u: u, v: vMid + wave });
      }
      drawDryBlockPath(vinePts, PAL.ironBlack, PAL.ironDry, 0.78, regIron, starve);

      for (let k = 0; k < 4; k++) {
        let fu = u0 + 13 + k * 26;
        let fv = vMid + (k % 2 === 0 ? -9 : 9);
        if (hasMadder) {
          drawDryBlockReliefPatch(fu, fv, 7.5, 7.5, 0, PAL.madderRed, PAL.madderLight, regMadder, starve);
        }
        if (hasIndigo) {
          drawDryBlockReliefPatch(
            fu + 11,
            vMid + (k % 2 === 0 ? 8 : -8),
            6.5,
            4.2,
            k % 2 === 0 ? 35 : -35,
            PAL.indigoBlue,
            PAL.indigoLight,
            regIndigo,
            starve
          );
        }
        // Iron-black flower petal outline
        let petPts = [];
        for (let a = 0; a <= 360; a += 45) {
          petPts.push({ u: fu + cos(a) * 7.8, v: fv + sin(a) * 7.8 });
        }
        drawDryBlockPath(petPts, PAL.ironBlack, PAL.ironDry, 0.62, regIron, starve);
      }

      // Kangura chevron teeth along inner track
      let chevPts = [];
      for (let u = u0; u <= u1; u += 13) {
        chevPts.push({ u: u, v: vInner });
        if (u + 6.5 <= u1) {
          chevPts.push({ u: u + 6.5, v: vInner + side * 7 });
        }
      }
      drawDryBlockPath(chevPts, PAL.ironBlack, PAL.ironDry, 0.65, regIron, starve);
    }
  }
}

// Draws one 104x104 hand-blocked botanical `Buta` stamp with authentic misregistration & ink starvation
function drawSingleButaStamp(cu, cv, sz, flags) {
  let half = sz * 0.46;

  // Each stamp impression has slightly different hand pressure starvation and block misregistration
  let stampStarve = {
    cu: cu,
    cv: cv,
    base: random(0.12, 0.35) + (flags.extraStarve || 0),
    gx: random(-0.28, 0.28),
    gy: random(-0.28, 0.28)
  };

  let regIron = {
    du: random(-1.4, 1.4),
    dv: random(-1.4, 1.4),
    rot: random(-0.85, 0.85)
  };
  let regMadder = {
    du: regIron.du + random(-3.8, 3.8),
    dv: regIron.dv + random(-3.8, 3.8),
    rot: regIron.rot + random(-1.4, 1.4)
  };
  let regIndigo = {
    du: regIron.du + random(-3.6, 3.6),
    dv: regIron.dv + random(-3.6, 3.6),
    rot: regIron.rot + random(-1.3, 1.3)
  };

  // --- PASS 1: INDIGO BLOCK (leaf fills, blossom core, corner medallions) ---
  if (flags.indigo) {
    // Central pomegranate blossom indigo heart & calyx
    drawDryBlockReliefPatch(cu - 14, cv - 4, 8.5, 8.5, 0, PAL.indigoBlue, PAL.indigoLight, regIndigo, stampStarve);
    drawDryBlockReliefPatch(cu + 2, cv - 2, 5.5, 7.5, -10, PAL.indigoDark, PAL.indigoBlue, regIndigo, stampStarve);

    // Pair of sweeping basal mango/acanthus leaves
    drawDryBlockReliefPatch(cu + 16, cv - 18, 13, 6.2, -38, PAL.indigoBlue, PAL.indigoLight, regIndigo, stampStarve);
    drawDryBlockReliefPatch(cu + 14, cv + 17, 13, 6.2, 36, PAL.indigoBlue, PAL.indigoLight, regIndigo, stampStarve);

    // Upper side leaf
    drawDryBlockReliefPatch(cu - 6, cv + 19, 10, 5.0, 28, PAL.indigoBlue, PAL.indigoLight, regIndigo, stampStarve);

    // Four corner quarter-rosette dots
    for (let sx of [-1, 1]) {
      for (let sy of [-1, 1]) {
        drawDryBlockReliefPatch(
          cu + sx * (half - 7),
          cv + sy * (half - 7),
          6.5,
          6.5,
          0,
          PAL.indigoBlue,
          PAL.indigoLight,
          regIndigo,
          stampStarve
        );
      }
    }
  }

  // --- PASS 2: MADDER RED BLOCK (main blossom petals, side buds, inner frame) ---
  if (flags.madder) {
    // Main blooming pomegranate flower fan of 5 petals
    let petalAngles = [-68, -34, 0, 34, 68];
    for (let a of petalAngles) {
      let rad = 14.5;
      let pu = cu - 16 - cos(a) * rad;
      let pv = cv - 4 + sin(a) * rad;
      drawDryBlockReliefPatch(
        pu,
        pv,
        9.2,
        5.4,
        -a,
        PAL.madderRed,
        PAL.madderLight,
        regMadder,
        stampStarve
      );
    }

    // Secondary side lotus buds
    drawDryBlockReliefPatch(cu - 4, cv - 23, 8.5, 5.5, -28, PAL.madderRed, PAL.madderLight, regMadder, stampStarve);
    drawDryBlockReliefPatch(cu - 22, cv + 20, 8.0, 5.2, 32, PAL.madderRed, PAL.madderLight, regMadder, stampStarve);

    // Basal cradle rosette
    drawDryBlockReliefPatch(cu + 29, cv, 6.5, 9.0, 0, PAL.madderDark, PAL.madderRed, regMadder, stampStarve);

    // Inner decorative madder frame border
    let f = half - 5;
    drawDryBlockPath(
      [
        { u: cu - f, v: cv - f },
        { u: cu + f, v: cv - f },
        { u: cu + f, v: cv + f },
        { u: cu - f, v: cv + f },
        { u: cu - f, v: cv - f }
      ],
      PAL.madderRed,
      PAL.madderLight,
      0.85,
      regMadder,
      stampStarve
    );
  }

  // --- PASS 3: IRON-BLACK (`SYAHI` / `REKH`) OUTLINE & DETAIL BLOCK ---
  if (flags.iron) {
    // Outer square stamp registration border
    drawDryBlockPath(
      [
        { u: cu - half, v: cv - half },
        { u: cu + half, v: cv - half },
        { u: cu + half, v: cv + half },
        { u: cu - half, v: cv + half },
        { u: cu - half, v: cv - half }
      ],
      PAL.ironBlack,
      PAL.ironStarved,
      0.78,
      regIron,
      stampStarve
    );

    // Graceful S-curved main stem from base to crown blossom
    let stemPts = [
      { u: cu + 34, v: cv },
      { u: cu + 20, v: cv + 3 },
      { u: cu + 6, v: cv - 2 },
      { u: cu - 8, v: cv - 4 },
      { u: cu - 16, v: cv - 4 }
    ];
    drawDryBlockPath(stemPts, PAL.ironBlack, PAL.ironStarved, 0.95, regIron, stampStarve);

    // Branching stems to side buds
    drawDryBlockPath(
      [
        { u: cu + 8, v: cv - 1 },
        { u: cu + 1, v: cv - 14 },
        { u: cu - 4, v: cv - 23 }
      ],
      PAL.ironBlack,
      PAL.ironStarved,
      0.72,
      regIron,
      stampStarve
    );
    drawDryBlockPath(
      [
        { u: cu - 4, v: cv - 3 },
        { u: cu - 12, v: cv + 10 },
        { u: cu - 22, v: cv + 20 }
      ],
      PAL.ironBlack,
      PAL.ironStarved,
      0.72,
      regIron,
      stampStarve
    );

    // Outlines and central ribs of the basal sweeping leaves
    for (let side of [-1, 1]) {
      let leafOutline = [
        { u: cu + 24, v: cv },
        { u: cu + 20, v: cv + side * 12 },
        { u: cu + 10, v: cv + side * 25 },
        { u: cu + 12, v: cv + side * 11 },
        { u: cu + 24, v: cv }
      ];
      drawDryBlockPath(leafOutline, PAL.ironBlack, PAL.ironStarved, 0.72, regIron, stampStarve);
      drawDryBlockPath(
        [
          { u: cu + 23, v: cv + side * 2 },
          { u: cu + 12, v: cv + side * 21 }
        ],
        PAL.ironBlack,
        PAL.ironStarved,
        0.58,
        regIron,
        stampStarve
      );
    }

    // Scalloped outline & stamen ribs around the main pomegranate flower
    let petalAngles = [-68, -34, 0, 34, 68];
    for (let a of petalAngles) {
      let rad = 14.5;
      let pu = cu - 16 - cos(a) * rad;
      let pv = cv - 4 + sin(a) * rad;
      let loopPts = [];
      for (let t = -90; t <= 90; t += 45) {
        let lx = cos(t) * 9.5;
        let ly = sin(t) * 5.2;
        loopPts.push({
          u: pu - lx * cos(a) - ly * sin(a),
          v: pv + lx * sin(a) - ly * cos(a)
        });
      }
      drawDryBlockPath(loopPts, PAL.ironBlack, PAL.ironStarved, 0.68, regIron, stampStarve);

      // Stamen vein line
      drawDryBlockPath(
        [
          { u: cu - 15, v: cv - 4 },
          { u: pu - cos(a) * 4, v: pv + sin(a) * 4 }
        ],
        PAL.ironBlack,
        PAL.ironStarved,
        0.55,
        regIron,
        stampStarve
      );
    }

    // Corner scalloped brackets
    let cDist = half - 13;
    for (let sx of [-1, 1]) {
      for (let sy of [-1, 1]) {
        drawDryBlockPath(
          [
            { u: cu + sx * half, v: cv + sy * cDist },
            { u: cu + sx * cDist, v: cv + sy * cDist },
            { u: cu + sx * cDist, v: cv + sy * half }
          ],
          PAL.ironBlack,
          PAL.ironStarved,
          0.65,
          regIron,
          stampStarve
        );
      }
    }
  }
}

function drawPrinterRegistrationTicks(uStart, stampSize) {
  // Subtle blue-chalk and charcoal registration crosses & dashed guide lines on the unprinted cotton
  for (let row = 0; row < 6; row++) {
    let u = uStart + row * stampSize;
    for (let col = 0; col <= 4; col++) {
      let v = -208 + col * stampSize;
      let p = clothToScreen(u, v);

      // Tiny cross tick mark snapped by the printer
      brush.set("cpencil", PAL.chalkMark, 0.65);
      brush.line(p.x - 4.5, p.y - 1.5, p.x + 4.5, p.y + 1.5);
      brush.line(p.x - 1.5, p.y + 4.5, p.x + 1.5, p.y - 4.5);

      // Faint charcoal dotted alignment thread impression along row
      if (col < 4 && row < 4) {
        for (let k = 1; k <= 5; k++) {
          let pv = clothToScreen(u, v + (k / 6) * stampSize);
          brush.set("2H", PAL.ironStarved, 0.45);
          brush.line(pv.x - 1.2, pv.y - 0.8, pv.x + 1.2, pv.y + 0.8);
        }
      }
    }
  }
}

// ============================================================================
// 7. SOFT WATERCOLOR FOLD OVERGLAZES (UNIFYING DYE & CLOTH DRAPE)
// ============================================================================

function drawFoldCreaseOverglazes() {
  brush.noStroke();

  // Translucent shadow glazes in fold valleys over the printed motifs
  let valleyTraces = [
    { u0: 250, slopeV: 0.58, w: 34, col: PAL.clothDuskShade, alpha: 62 },
    { u0: 518, slopeV: -0.42, w: 38, col: PAL.clothDuskShade, alpha: 68 },
    { u0: 912, slopeV: 0.32, w: 44, col: PAL.clothShade2, alpha: 75 }
  ];

  for (let vt of valleyTraces) {
    brush.fill(vt.col, vt.alpha);
    brush.fillBleed(0.3, "out");
    brush.fillTexture(0.55, 0.2);

    let lPts = [];
    let rPts = [];
    for (let s = -240; s <= 240; s += 40) {
      let u = vt.u0 + s * vt.slopeV;
      let pL = clothToScreen(u - vt.w * 0.5, s);
      let pR = clothToScreen(u + vt.w * 0.5, s);
      lPts.push(pL);
      rPts.push(pR);
    }
    brush.beginShape(0.3);
    for (let p of lPts) brush.vertex(p.x, p.y);
    for (let i = rPts.length - 1; i >= 0; i--) brush.vertex(rPts[i].x, rPts[i].y);
    brush.endShape(true);
  }

  // Soft chalky sunlit bloom along fold crests
  let crestTraces = [
    { u0: 215, slopeV: 0.58, w: 26, col: PAL.clothSun, alpha: 52 },
    { u0: 478, slopeV: -0.42, w: 28, col: PAL.clothSun, alpha: 48 },
    { u0: 872, slopeV: 0.32, w: 32, col: PAL.clothSun, alpha: 58 }
  ];

  for (let ct of crestTraces) {
    brush.fill(ct.col, ct.alpha);
    brush.fillBleed(0.28, "out");
    let lPts = [];
    let rPts = [];
    for (let s = -240; s <= 240; s += 40) {
      let u = ct.u0 + s * ct.slopeV;
      lPts.push(clothToScreen(u - ct.w * 0.5, s));
      rPts.push(clothToScreen(u + ct.w * 0.5, s));
    }
    brush.beginShape(0.3);
    for (let p of lPts) brush.vertex(p.x, p.y);
    for (let i = rPts.length - 1; i >= 0; i--) brush.vertex(rPts[i].x, rPts[i].y);
    brush.endShape(true);
  }

  brush.noFill();
}

// ============================================================================
// 8. CARVED TEAKWOOD PRINTING BLOCKS (WET DYE RELIEF FACE & HANDLE BLOCK)
// ============================================================================

function drawCarvedTeakBlocks() {
  // Position right on Row 5 where printing stops
  let centerBlock1 = clothToScreen(638, -52); // Resting block showing carved wooden handle
  let centerBlock2 = clothToScreen(658, 76);  // Tilted block showing wet dye-coated carved face

  // 1. Cast shadows of both teak blocks onto the cloth
  drawTeakBlockShadows(centerBlock1, centerBlock2);

  // 2. First Teak Block (resting face-down on cloth, showing seasoned teak body & top handle)
  drawHandleTeakBlock(centerBlock1.x, centerBlock1.y, 44);

  // 3. Primary Focal Teak Block (resting tilted on its edge so its deeply carved face
  //    glistening with wet madder-red & iron-black dye is seen hyperreally)
  drawWetCarvedFaceTeakBlock(centerBlock2.x, centerBlock2.y, 18);

  // 4. Fresh wet dye smudges & tiny droplets on the cloth beside the blocks
  drawFreshDyeDroplets(centerBlock2.x, centerBlock2.y);
}

function drawTeakBlockShadows(c1, c2) {
  brush.noStroke();

  // Long soft dusk cast shadows toward bottom-right
  brush.fill("#584947", 115);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.55, 0.25);

  drawQuadFill([
    { x: c1.x - 32, y: c1.y + 18 },
    { x: c1.x + 76, y: c1.y - 22 },
    { x: c1.x + 98, y: c1.y + 48 },
    { x: c1.x - 6, y: c1.y + 82 }
  ]);

  drawQuadFill([
    { x: c2.x - 42, y: c2.y + 22 },
    { x: c2.x + 84, y: c2.y - 16 },
    { x: c2.x + 114, y: c2.y + 62 },
    { x: c2.x - 10, y: c2.y + 94 }
  ]);

  // Darker contact occlusion shadow directly beneath the wood bases
  brush.fill("#332726", 145);
  brush.fillBleed(0.12, "out");
  drawQuadFill([
    { x: c1.x - 46, y: c1.y + 4 },
    { x: c1.x + 52, y: c1.y + 38 },
    { x: c1.x + 42, y: c1.y + 62 },
    { x: c1.x - 54, y: c1.y + 24 }
  ]);

  drawQuadFill([
    { x: c2.x - 54, y: c2.y + 16 },
    { x: c2.x + 58, y: c2.y + 48 },
    { x: c2.x + 46, y: c2.y + 72 },
    { x: c2.x - 62, y: c2.y + 38 }
  ]);

  brush.noFill();
}

function drawQuadFill(pts) {
  brush.beginShape(0.08);
  for (let p of pts) brush.vertex(p.x, p.y);
  brush.endShape(true);
}

// Helper: 2D local rotation around (cx, cy)
function rotPt(cx, cy, lx, ly, ang) {
  let c = cos(ang);
  let s = sin(ang);
  return {
    x: cx + lx * c - ly * s,
    y: cy + lx * s + ly * c
  };
}

function drawHandleTeakBlock(cx, cy, rotDeg) {
  let w = 48;
  let h = 48;
  let depth = 20; // 3D thickness offset

  let topFL = rotPt(cx, cy, -w, -h, rotDeg);
  let topFR = rotPt(cx, cy, w, -h, rotDeg);
  let topBR = rotPt(cx, cy, w, h, rotDeg);
  let topBL = rotPt(cx, cy, -w, h, rotDeg);

  let botFR = { x: topFR.x + 10, y: topFR.y + depth };
  let botBR = { x: topBR.x + 10, y: topBR.y + depth };
  let botBL = { x: topBL.x + 10, y: topBL.y + depth };

  brush.noStroke();

  // Side walls of teak block
  brush.wash(PAL.teakDark, 235);
  drawQuadFill([topBL, topBR, botBR, botBL]);
  brush.wash(PAL.teakEndGrain, 235);
  drawQuadFill([topFR, topBR, botBR, botFR]);

  // Top face of teak block
  brush.wash(PAL.teakBase, 240);
  drawQuadFill([topFL, topFR, topBR, topBL]);
  brush.noWash();

  // Watercolor patina & old dye stains on the back of the block
  brush.fill(PAL.teakLight, 95);
  brush.fillBleed(0.18, "in");
  drawQuadFill([
    topFL,
    rotPt(cx, cy, 12, -h, rotDeg),
    rotPt(cx, cy, 12, 0, rotDeg),
    rotPt(cx, cy, -w, 0, rotDeg)
  ]);

  brush.fill(PAL.madderDark, 65);
  brush.fillBleed(0.25, "in");
  drawQuadFill([botBL, botBR, { x: topBR.x + 5, y: topBR.y + 9 }, { x: topBL.x + 5, y: topBL.y + 9 }]);
  brush.noFill();

  // Wood grain lines in pencil across top face
  brush.set("HB", PAL.teakDark, 0.65);
  for (let y = -h + 4; y <= h - 4; y += 3.8) {
    let p0 = rotPt(cx, cy, -w + 3, y + sin(y * 8) * 1.5, rotDeg);
    let p1 = rotPt(cx, cy, w - 3, y + cos(y * 6) * 1.5, rotDeg);
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }

  // Sculpted wooden bridge handle (`hattha`) on top of the block
  let hw = 34;
  let hh = 11;
  let hLiftX = -7;
  let hLiftY = -12;

  let hFL = { x: rotPt(cx, cy, -hw, -hh, rotDeg).x + hLiftX, y: rotPt(cx, cy, -hw, -hh, rotDeg).y + hLiftY };
  let hFR = { x: rotPt(cx, cy, hw, -hh, rotDeg).x + hLiftX, y: rotPt(cx, cy, hw, -hh, rotDeg).y + hLiftY };
  let hBR = { x: rotPt(cx, cy, hw, hh, rotDeg).x + hLiftX, y: rotPt(cx, cy, hw, hh, rotDeg).y + hLiftY };
  let hBL = { x: rotPt(cx, cy, -hw, hh, rotDeg).x + hLiftX, y: rotPt(cx, cy, -hw, hh, rotDeg).y + hLiftY };

  let bBL = rotPt(cx, cy, -hw, hh, rotDeg);
  let bBR = rotPt(cx, cy, hw, hh, rotDeg);
  let bFR = rotPt(cx, cy, hw, -hh, rotDeg);

  // Handle shadow on block top
  brush.noStroke();
  brush.fill(PAL.teakHollow, 130);
  brush.fillBleed(0.15, "out");
  drawQuadFill([
    bBL,
    bBR,
    { x: bBR.x + 12, y: bBR.y + 10 },
    { x: bBL.x + 12, y: bBL.y + 10 }
  ]);
  brush.noFill();

  // Handle front & side walls
  brush.wash(PAL.teakDark, 240);
  drawQuadFill([hBL, hBR, bBR, bBL]);
  drawQuadFill([hFR, hBR, bBR, bFR]);

  // Handle top crest in sunlit teak
  brush.wash(PAL.teakLight, 245);
  drawQuadFill([hFL, hFR, hBR, hBL]);
  brush.noWash();

  // Printer's madder-stained thumbprint smudge on the handle grip
  brush.noStroke();
  brush.fill(PAL.madderDark, 85);
  brush.fillBleed(0.3, "in");
  brush.circle((hFL.x + hBR.x) * 0.5, (hFL.y + hBR.y) * 0.5, 11, 0.3);
  brush.noFill();

  // Crisp pencil edges, side vent holes, and wood joinery
  brush.set("2B", PAL.teakHollow, 0.78);
  brush.line(topFL.x, topFL.y, topFR.x, topFR.y);
  brush.line(topFR.x, topFR.y, topBR.x, topBR.y);
  brush.line(topBR.x, topBR.y, topBL.x, topBL.y);
  brush.line(topBL.x, topBL.y, topFL.x, topFL.y);
  brush.line(botBL.x, botBL.y, botBR.x, botBR.y);
  brush.line(botBR.x, botBR.y, botFR.x, botFR.y);
  brush.line(topBL.x, topBL.y, botBL.x, botBL.y);
  brush.line(topBR.x, topBR.y, botBR.x, botBR.y);
  brush.line(topFR.x, topFR.y, botFR.x, botFR.y);

  brush.line(hFL.x, hFL.y, hFR.x, hFR.y);
  brush.line(hFR.x, hFR.y, hBR.x, hBR.y);
  brush.line(hBR.x, hBR.y, hBL.x, hBL.y);
  brush.line(hBL.x, hBL.y, hFL.x, hFL.y);

  // Sunlit pencil highlight along top bevels
  brush.set("cpencil", PAL.clothSun, 0.85);
  brush.line(topFL.x, topFL.y, topFR.x, topFR.y);
  brush.line(topFL.x, topFL.y, topBL.x, topBL.y);
  brush.line(hFL.x, hFL.y, hFR.x, hFR.y);

  // Side air-escape holes drilled through the teak block
  for (let k of [-20, 0, 20]) {
    let hp = rotPt(cx, cy, k, h, rotDeg);
    brush.set("2B", PAL.teakHollow, 1.15);
    brush.circle(hp.x + 5, hp.y + 10, 2.8, 0.2);
  }
}

// Renders the tilted carved teak block with its intricate relief face wet & glistening with dye
function drawWetCarvedFaceTeakBlock(cx, cy, rotDeg) {
  // Fore-shortened face dimensions (tilted toward standing viewer)
  let fw = 52;
  let fh = 44;
  let bodyDX = 16;
  let bodyDY = -22;

  let fTL = rotPt(cx, cy, -fw, -fh, rotDeg);
  let fTR = rotPt(cx, cy, fw, -fh, rotDeg);
  let fBR = rotPt(cx, cy, fw, fh, rotDeg);
  let fBL = rotPt(cx, cy, -fw, fh, rotDeg);

  let bTL = { x: fTL.x + bodyDX, y: fTL.y + bodyDY };
  let bTR = { x: fTR.x + bodyDX, y: fTR.y + bodyDY };
  let bBR = { x: fBR.x + bodyDX, y: fBR.y + bodyDY };

  brush.noStroke();

  // 1. Seasoned teakwood side thickness walls (behind the tilted face)
  brush.wash(PAL.teakLight, 240);
  drawQuadFill([fTL, fTR, bTR, bTL]);

  brush.wash(PAL.teakBase, 240);
  drawQuadFill([fTR, fBR, bBR, bTR]);

  // 2. Deeply gouged dark teak cavity of the carved face
  brush.wash(PAL.teakHollow, 248);
  drawQuadFill([fTL, fTR, fBR, fBL]);
  brush.noWash();

  // Woodgrain & chisel gouge marks on the side walls and cavity interior
  brush.set("HB", PAL.teakDark, 0.65);
  for (let t = 0.1; t < 0.95; t += 0.12) {
    let p1 = { x: lerp(fTL.x, fTR.x, t), y: lerp(fTL.y, fTR.y, t) };
    let p2 = { x: lerp(bTL.x, bTR.x, t), y: lerp(bTL.y, bTR.y, t) };
    brush.line(p1.x, p1.y, p2.x, p2.y);

    let q1 = { x: lerp(fTR.x, fBR.x, t), y: lerp(fTR.y, fBR.y, t) };
    let q2 = { x: lerp(bTR.x, bBR.x, t), y: lerp(bTR.y, bBR.y, t) };
    brush.line(q1.x, q1.y, q2.x, q2.y);
  }

  // Carved chisel texture inside the recessed wood hollows
  brush.set("2B", "#22150e", 0.6);
  for (let y = -fh + 5; y <= fh - 5; y += 4.5) {
    for (let x = -fw + 6; x <= fw - 6; x += 9) {
      let p0 = rotPt(cx, cy, x, y, rotDeg);
      let p1 = rotPt(cx, cy, x + 5, y + 1.5, rotDeg);
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
  }

  // 3. Raised carved wooden relief walls + wet dye coating on the relief top!
  //    Helper to draw a raised carved wooden island with wet dye & dusk sky specular glint
  const drawCarvedReliefIsland = (lx, ly, rx, ry, locAng, wetColMain, wetColBright) => {
    let steps = 14;
    let basePts = [];
    let topPts = [];
    let ca = cos(locAng);
    let sa = sin(locAng);

    for (let i = 0; i < steps; i++) {
      let a = (i / steps) * 360;
      let ox = cos(a) * rx;
      let oy = sin(a) * ry;
      let px = lx + ox * ca - oy * sa;
      let py = ly + ox * sa + oy * ca;
      let ptScreen = rotPt(cx, cy, px, py, rotDeg);
      basePts.push(ptScreen);
      // Raised relief projects slightly forward/up-left toward viewer (-2.2, -2.6)
      topPts.push({ x: ptScreen.x - 2.2, y: ptScreen.y - 2.6 });
    }

    // Carved wooden side-wall of the relief
    brush.noStroke();
    brush.wash(PAL.teakBase, 235);
    brush.beginShape(0.2);
    for (let p of basePts) brush.vertex(p.x, p.y);
    brush.endShape(true);

    // Wet dye surface on top of the raised relief
    brush.wash(wetColMain, 245);
    brush.beginShape(0.25);
    for (let p of topPts) brush.vertex(p.x, p.y);
    brush.endShape(true);
    brush.noWash();

    // Rich watercolor pooling of wet dye inside the relief face
    brush.fill(wetColBright, 130);
    brush.fillBleed(0.15, "in");
    brush.beginShape(0.25);
    for (let p of topPts) brush.vertex(p.x, p.y);
    brush.endShape(true);
    brush.noFill();

    // Dark wet dye meniscus rim
    brush.set("rotring", PAL.wetIron, 0.55);
    for (let i = 0; i < topPts.length; i++) {
      let pA = topPts[i];
      let pB = topPts[(i + 1) % topPts.length];
      brush.line(pA.x, pA.y, pB.x, pB.y);
    }

    // Glistening dusk-sky specular highlight along the upper-left wet meniscus!
    brush.set("cpencil", PAL.wetSpecular, 0.9);
    for (let i = 6; i <= 10; i++) {
      let pA = topPts[i % topPts.length];
      let pB = topPts[(i + 1) % topPts.length];
      brush.line(pA.x + 0.6, pA.y + 0.6, pB.x + 0.6, pB.y + 0.6);
    }
  };

  // Raised outer & inner carved registration border strips coated in wet dye
  let rimThick = 3.8;
  drawCarvedReliefIsland(0, -fh + rimThick, fw - 2, rimThick * 0.7, 0, PAL.wetMadder, PAL.wetMadderMid);
  drawCarvedReliefIsland(0, fh - rimThick, fw - 2, rimThick * 0.7, 0, PAL.wetMadder, PAL.wetMadderMid);
  drawCarvedReliefIsland(-fw + rimThick, 0, rimThick * 0.7, fh - 2, 0, PAL.wetMadder, PAL.wetMadderMid);
  drawCarvedReliefIsland(fw - rimThick, 0, rimThick * 0.7, fh - 2, 0, PAL.wetMadder, PAL.wetMadderMid);

  // Mirror-image carved Buta floral motif on the block face (coated in glistening wet madder & iron dye)
  // Central pomegranate blossom fan of 5 carved relief petals
  let petalAngles = [-66, -33, 0, 33, 66];
  for (let a of petalAngles) {
    let rad = 14.0;
    let px = -12 - cos(a) * rad;
    let py = -3 - sin(a) * rad;
    drawCarvedReliefIsland(px, py, 8.8, 4.8, a, PAL.wetMadder, PAL.wetMadderMid);
  }

  // Central flower calyx & heart
  drawCarvedReliefIsland(-10, -3, 7.5, 7.2, 0, PAL.wetIron, PAL.wetMadder);

  // Sweeping carved basal leaves
  drawCarvedReliefIsland(15, 15, 12.5, 5.6, 36, PAL.wetMadder, PAL.wetMadderMid);
  drawCarvedReliefIsland(15, -16, 12.5, 5.6, -36, PAL.wetMadder, PAL.wetMadderMid);

  // Side lotus buds
  drawCarvedReliefIsland(-3, 20, 8.0, 4.8, 28, PAL.wetMadder, PAL.wetMadderMid);
  drawCarvedReliefIsland(-19, -18, 7.8, 4.6, -30, PAL.wetMadder, PAL.wetMadderMid);

  // Basal rosette & corner quarter-rosettes
  drawCarvedReliefIsland(28, 0, 6.2, 8.2, 0, PAL.wetMadder, PAL.wetMadderMid);
  for (let sx of [-1, 1]) {
    for (let sy of [-1, 1]) {
      drawCarvedReliefIsland(
        sx * (fw - 11),
        sy * (fh - 10),
        5.8,
        5.8,
        0,
        PAL.wetMadder,
        PAL.wetMadderMid
      );
    }
  }

  // Carved wooden stem ridge connecting base to blossom (with wet dye & specular glint)
  let stemLocal = [
    { x: 31, y: 0 },
    { x: 18, y: -2 },
    { x: 5, y: 2 },
    { x: -9, y: -3 }
  ];
  for (let i = 0; i < stemLocal.length - 1; i++) {
    let p0 = rotPt(cx, cy, stemLocal[i].x, stemLocal[i].y, rotDeg);
    let p1 = rotPt(cx, cy, stemLocal[i + 1].x, stemLocal[i + 1].y, rotDeg);
    brush.set("marker", PAL.teakBase, 1.3);
    brush.line(p0.x, p0.y, p1.x, p1.y);
    brush.set("marker", PAL.wetMadder, 1.0);
    brush.line(p0.x - 2, p0.y - 2.4, p1.x - 2, p1.y - 2.4);
    brush.set("cpencil", PAL.wetSpecular, 0.75);
    brush.line(p0.x - 2.5, p0.y - 2.9, p1.x - 2.5, p1.y - 2.9);
  }

  // Corner registration pin holes drilled into the block face
  for (let sx of [-1, 1]) {
    for (let sy of [-1, 1]) {
      let hp = rotPt(cx, cy, sx * (fw - 5.5), sy * (fh - 5.5), rotDeg);
      brush.set("2B", "#140b07", 1.2);
      brush.circle(hp.x - 2, hp.y - 2, 2.2, 0.15);
    }
  }

  // Crisp outer structural outlines of the tilted teak block
  brush.set("2B", PAL.teakHollow, 0.82);
  brush.line(fTL.x, fTL.y, fTR.x, fTR.y);
  brush.line(fTR.x, fTR.y, fBR.x, fBR.y);
  brush.line(fBR.x, fBR.y, fBL.x, fBL.y);
  brush.line(fBL.x, fBL.y, fTL.x, fTL.y);
  brush.line(bTL.x, bTL.y, bTR.x, bTR.y);
  brush.line(bTR.x, bTR.y, bBR.x, bBR.y);
  brush.line(fTL.x, fTL.y, bTL.x, bTL.y);
  brush.line(fTR.x, fTR.y, bTR.x, bTR.y);
  brush.line(fBR.x, fBR.y, bBR.x, bBR.y);

  // Extra wet dusk-sky specular glints across the glistening dye surface
  brush.set("cpencil", PAL.wetDuskGlint, 0.85);
  for (let k = 0; k < 18; k++) {
    let gx = random(-fw + 10, fw - 10);
    let gy = random(-fh + 10, fh - 10);
    let gp = rotPt(cx, cy, gx, gy, rotDeg);
    brush.line(gp.x - 2.5, gp.y - 2.5, gp.x + 1.5, gp.y - 1.2);
  }
}

