// ============================================================================
// GEOMETRY & SHADING HELPERS
// ============================================================================

function lerpPt(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}

// Evaluate polyline/curve at parameter t in [0, 1]
function sampleCurve(pts, t) {
  if (pts.length === 1) return [pts[0][0], pts[0][1]];
  let clamped = constrain(t, 0, 1);
  let scaled = clamped * (pts.length - 1);
  let idx = Math.floor(scaled);
  let frac = scaled - idx;
  if (idx >= pts.length - 1) return [pts[pts.length - 1][0], pts[pts.length - 1][1]];

  let p0 = pts[Math.max(0, idx - 1)];
  let p1 = pts[idx];
  let p2 = pts[idx + 1];
  let p3 = pts[Math.min(pts.length - 1, idx + 2)];

  // Catmull-Rom spline interpolation for smooth biological contours
  let t2 = frac * frac;
  let t3 = t2 * frac;
  let x = 0.5 * (
    (2 * p1[0]) +
    (-p0[0] + p2[0]) * frac +
    (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
    (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3
  );
  let y = 0.5 * (
    (2 * p1[1]) +
    (-p0[1] + p2[1]) * frac +
    (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
    (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3
  );
  return [x, y];
}

function drawFilledPoly(pts, curv = 0.15) {
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Elliptical arc points generator
function getEllipseArc(cx, cy, rx, ry, startDeg, endDeg, steps, rotDeg = 0) {
  let pts = [];
  let cosR = Math.cos(radians(rotDeg));
  let sinR = Math.sin(radians(rotDeg));
  for (let i = 0; i <= steps; i++) {
    let a = lerp(startDeg, endDeg, i / steps);
    let lx = rx * Math.cos(radians(a));
    let ly = ry * Math.sin(radians(a));
    let gx = cx + lx * cosR - ly * sinR;
    let gy = cy + lx * sinR + ly * cosR;
    pts.push([gx, gy]);
  }
  return pts;
}

// Parametric 3D Chitin Shell Renderer for Hyperreal Lobster Anatomy
// topPts: dorsal contour (away from upward light)
// botPts: ventral contour (facing dramatic upward lab light)
function renderChitinSegment(topPts, botPts, opts = {}) {
  let uSteps = opts.uSteps || 16;
  let vLayers = opts.vLayers || 22;
  let bulge = opts.bulge !== undefined ? opts.bulge : 0.14;
  let rimColor = opts.rimColor || "#76ff03";      // radioactive lime upward bounce
  let subRimColor = opts.subRimColor || "#ff7b00"; // sodium orange translucent joint glow
  let cyanGlow = opts.cyanGlow || "#00f5d4";       // electric cyan lower midtone
  let cobaltMid = opts.cobaltMid || "#0055ff";     // saturated cobalt shell
  let royalMid = opts.royalMid || "#002b88";       // deep ultramarine
  let darkCore = opts.darkCore || "#040a24";       // midnight Prussian shadow
  let topRim = opts.topRim || "#b52bff";           // electric violet sky rim
  let specPos1 = opts.specPos1 !== undefined ? opts.specPos1 : 0.30;
  let specPos2 = opts.specPos2 !== undefined ? opts.specPos2 : 0.68;
  let speckles = opts.speckles !== undefined ? opts.speckles : 55;

  // Build closed contour polygon for opaque base wash
  let boundary = [];
  for (let i = 0; i <= uSteps; i++) {
    boundary.push(sampleCurve(topPts, i / uSteps));
  }
  for (let i = uSteps; i >= 0; i--) {
    boundary.push(sampleCurve(botPts, i / uSteps));
  }

  // 1. Solid dark base wash so shell is completely opaque
  brush.noStroke();
  brush.noHatch();
  brush.wash(darkCore, 250);
  drawFilledPoly(boundary, 0.12);
  brush.noWash();

  // Helper to evaluate 3D surface point at (u, v)
  function surfPt(u, v) {
    let pT = sampleCurve(topPts, u);
    let pB = sampleCurve(botPts, u);
    let dx = pB[0] - pT[0];
    let dy = pB[1] - pT[1];
    let dist = Math.hypot(dx, dy) || 1;
    // Perpendicular outward bulge along shell axis
    let nx = -dy / dist;
    let ny = dx / dist;
    let b = Math.sin(v * Math.PI) * dist * bulge;
    return [
      lerp(pT[0], pB[0], v) + nx * b,
      lerp(pT[1], pB[1], v) + ny * b,
      dist
    ];
  }

  // 2. Longitudinal gouache & colored-pencil shading bands across v in [0, 1]
  for (let j = 0; j <= vLayers; j++) {
    let v = j / vLayers;
    let col, w, brName;

    if (v < 0.09) {
      col = topRim;
      w = 0.55;
      brName = "cpencil";
    } else if (v < 0.24) {
      col = darkCore;
      w = 0.85;
      brName = "gouache_chisel";
    } else if (v < 0.44) {
      col = royalMid;
      w = 0.9;
      brName = "gouache_chisel";
    } else if (v < 0.66) {
      col = cobaltMid;
      w = 0.85;
      brName = "gouache_chisel";
    } else if (v < 0.82) {
      col = cyanGlow;
      w = 0.75;
      brName = "cpencil";
    } else if (v < 0.93) {
      col = subRimColor;
      w = 0.7;
      brName = "cpencil";
    } else {
      col = rimColor;
      w = 0.85;
      brName = "gloss_razor";
    }

    let ribbon = [];
    for (let i = 0; i <= 10; i++) {
      let u = i / 10;
      let sp = surfPt(u, v);
      let pr = 0.6 + 0.6 * Math.sin(u * Math.PI);
      ribbon.push([sp[0], sp[1], pr]);
    }
    brush.set(brName, col, w);
    brush.spline(ribbon, 0.45);
  }

  // 3. Cross-contour chitinous form rings (curved ribs modeling cylinder volume)
  let ribCount = opts.ribCount || 11;
  for (let i = 1; i < ribCount; i++) {
    let u = i / ribCount;
    let ribPts = [];
    for (let k = 0; k <= 6; k++) {
      let v = k / 6;
      let sp = surfPt(u + 0.03 * Math.sin(v * Math.PI), v);
      ribPts.push([sp[0], sp[1], 0.4 + 0.7 * Math.sin(v * Math.PI)]);
    }
    let ribCol = i % 2 === 0 ? "#0077ff" : "#02164f";
    brush.set("2B", ribCol, 0.52);
    brush.spline(ribPts, 0.4);
  }

  // 4. Hyperreal chromatophore speckles & calcified tubercles
  for (let s = 0; s < speckles; s++) {
    let u = random(0.04, 0.96);
    let v = random(0.06, 0.94);
    let sp = surfPt(u, v);
    let r = random();

    if (r < 0.42) {
      // Dark indigo/black organic shell pit
      brush.set("rotring", "#020514", random(0.45, 1.15));
      brush.line(sp[0], sp[1], sp[0] + random(-2.5, 2.5), sp[1] + random(-2.5, 2.5));
    } else if (r < 0.76) {
      // Vivid cerulean/cobalt mottling
      brush.set("cpencil", v > 0.55 ? "#00e5ff" : "#0066ff", random(0.5, 1.1));
      brush.line(sp[0], sp[1], sp[0] + random(-3.5, 3.5), sp[1] + random(-2, 2));
    } else if (r < 0.92) {
      // Pale ivory/cyan calcified tubercle bump
      brush.set("gloss_razor", "#b8f2ff", random(0.45, 0.95));
      brush.line(sp[0], sp[1], sp[0] + 1.8, sp[1] - 1.2);
    } else {
      // Upward light orange/lime reflection fleck
      brush.set("gloss_razor", v > 0.6 ? "#ccff33" : "#ff9100", random(0.4, 0.85));
      brush.line(sp[0], sp[1], sp[0] + 1.6, sp[1] + 0.8);
    }
  }

  // 5. Wet Chitinous Specular Highlight Strips
  if (specPos1 > 0) {
    let spec1 = [];
    for (let i = 0; i <= 10; i++) {
      let u = lerp(0.08, 0.92, i / 10);
      let jitterV = specPos1 + 0.025 * Math.sin(u * Math.PI * 3);
      let sp = surfPt(u, jitterV);
      let pr = Math.sin((i / 10) * Math.PI) * 1.25;
      spec1.push([sp[0], sp[1], pr]);
    }
    brush.set("cpencil", "#48cae4", 1.25);
    brush.spline(spec1, 0.5);
    brush.set("gloss_razor", "#ffffff", 0.85);
    brush.spline(spec1, 0.5);
  }

  if (specPos2 > 0) {
    let spec2 = [];
    for (let i = 0; i <= 8; i++) {
      let u = lerp(0.14, 0.86, i / 8);
      let sp = surfPt(u, specPos2);
      let pr = Math.sin((i / 8) * Math.PI) * 0.95;
      spec2.push([sp[0], sp[1], pr]);
    }
    brush.set("gloss_razor", "#90e0ef", 0.65);
    brush.spline(spec2, 0.45);
  }

  // 6. Crisp structural outline & joint rim
  let topStroke = [];
  let botStroke = [];
  for (let i = 0; i <= 10; i++) {
    let u = i / 10;
    let ptT = sampleCurve(topPts, u);
    let ptB = sampleCurve(botPts, u);
    topStroke.push([ptT[0], ptT[1], 0.7]);
    botStroke.push([ptB[0], ptB[1], 0.9]);
  }
  brush.set("rotring", "#03071e", 0.75);
  brush.spline(topStroke, 0.4);
  brush.set("gloss_razor", rimColor, 0.7);
  brush.spline(botStroke, 0.4);
}

// Helper to draw sharp calcified spines along carapace/claws
function drawSpine(x, y, angleDeg, len, baseW, rimCol = "#ff9e00") {
  let rad = radians(angleDeg);
  let perp = rad + Math.PI / 2;
  let tipX = x + Math.cos(rad) * len;
  let tipY = y + Math.sin(rad) * len;
  let b1x = x + Math.cos(perp) * baseW * 0.5;
  let b1y = y + Math.sin(perp) * baseW * 0.5;
  let b2x = x - Math.cos(perp) * baseW * 0.5;
  let b2y = y - Math.sin(perp) * baseW * 0.5;

  brush.noStroke();
  brush.wash("#003566", 240);
  drawFilledPoly([[b1x, b1y], [tipX, tipY], [b2x, b2y]], 0.05);
  brush.noWash();

  brush.set("rotring", "#020824", 0.65);
  brush.line(b1x, b1y, tipX, tipY);
  brush.set("gloss_razor", rimCol, 0.65);
  brush.line(b2x, b2y, tipX, tipY);
  brush.set("gloss_razor", "#ffffff", 0.55);
  brush.line(lerp(b2x, tipX, 0.4), lerp(b2y, tipY, 0.4), tipX, tipY);
}

// Helper to draw a hyperreal water bubble inside the glass dome
function drawGlassBubble(x, y, r, tintCol = "#76ff03") {
  // Subtle dark refraction rim
  brush.set("rotring", "#091536", 0.45);
  brush.circle(x, y, r, 0.06);

  // Colored internal caustic crescent (bottom-right facing upward light)
  brush.set("cpencil", tintCol, 0.55);
  brush.arc(x, y, r * 0.85, 15, 155);

  // Sodium orange opposite internal bounce
  brush.set("cpencil", "#ff7b00", 0.45);
  brush.arc(x, y, r * 0.82, 195, 310);

  // Crisp white upper-left specular arc
  brush.set("gloss_razor", "#ffffff", 0.65);
  brush.arc(x, y, r * 0.88, 190, 265);

  // Pinprick white highlight dot
  brush.set("gloss_razor", "#ffffff", 0.9);
  brush.line(x - r * 0.42, y - r * 0.42, x - r * 0.30, y - r * 0.48);
  brush.line(x + r * 0.35, y + r * 0.38, x + r * 0.42, y + r * 0.34);
}

// ============================================================================
// MAIN RENDER PIPELINE
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);

  // Deep cosmic bruised-violet ground
  background("#090214");

  // --------------------------------------------------------------------------
  // 1. ALIEN SKY: RADIOACTIVE LIME, ELECTRIC VIOLET & SODIUM ORANGE SWEEPS
  // --------------------------------------------------------------------------
  renderAlienSky();

  // --------------------------------------------------------------------------
  // 2. HEROIC UPWARD SHADOW CAST ONTO THE ALIEN SKY / LAB WALL
  // --------------------------------------------------------------------------
  renderHeroicUpwardShadow();

  // --------------------------------------------------------------------------
  // 3. DIAGONAL BRUSHED STEEL LAB BENCH & UPWARD LIGHT WELL
  // --------------------------------------------------------------------------
  renderSteelLabBench();

  // --------------------------------------------------------------------------
  // 4. REAR GLASS CLOCHE WALL, CAUSTIC BASE RING & BACK REFRACTIONS
  // --------------------------------------------------------------------------
  renderClocheRearLayer();

  // --------------------------------------------------------------------------
  // 5. THE HYPERREAL LIVE BLUE LOBSTER (TRAPPED & REARING DIAGONALLY)
  // --------------------------------------------------------------------------
  renderHyperrealBlueLobster();

  // --------------------------------------------------------------------------
  // 6. FOREGROUND GLASS DOME: HARD SPECULAR ARC, BUBBLES & RIM REFRACTIONS
  // --------------------------------------------------------------------------
  renderClocheForeground();

  // --------------------------------------------------------------------------
  // 7. PULP SCI-FI MAGAZINE COVER BORDER & BLANK MASTHEAD BAND AT TOP
  // --------------------------------------------------------------------------
  renderPulpMastheadAndFrame();

  // --------------------------------------------------------------------------
  // 8. CLOCHE APEX KNOB OVERLAPPING THE MASTHEAD BAND (CLASSIC PULP DEPTH)
  // --------------------------------------------------------------------------
  renderClocheApexKnob();

  noLoop();
}

// ============================================================================
// LAYER 1: ALIEN SKY BACKGROUND
