  brush.fill("#9d1bff", 110);
  drawFilledPoly([[0, 200], [980, 150], [720, 480], [0, 680]], 0.2);

  // Batch 2: Sodium Orange diagonal horizon surge (lower-left to upper-right)
  brush.fill("#ff4800", 135);
  brush.fillBleed(0.4, "out");
  drawFilledPoly([[0, 560], [520, 340], [1200, 180], [1200, 590], [0, 880]], 0.2);

  brush.fill("#ff9100", 125);
