  brush.noFill();

  // Sweeping diagonal airbrush spray bands (lurid pulp sci-fi sky texture)
  let skyBands = [
    // Electric violet upper bands
    { x1: -60, y1: 310, x2: 780, y2: 120, col: "#3c096c", br: "airbrush_mega", w: 1.5, n: 10 },
    { x1: -40, y1: 390, x2: 960, y2: 140, col: "#7b2cbf", br: "airbrush_mega", w: 1.3, n: 12 },
    { x1: 20, y1: 460, x2: 1120, y2: 170, col: "#c724ff", br: "airbrush_soft", w: 1.2, n: 14 },
    { x1: 120, y1: 490, x2: 1240, y2: 210, col: "#e066ff", br: "airbrush_fine", w: 1.1, n: 12 },

    // Sodium orange diagonal surge
    { x1: -60, y1: 660, x2: 1240, y2: 240, col: "#ff3c00", br: "airbrush_mega", w: 1.5, n: 14 },
    { x1: -40, y1: 720, x2: 1250, y2: 310, col: "#ff6d00", br: "airbrush_soft", w: 1.35, n: 16 },
    { x1: 40, y1: 760, x2: 1240, y2: 380, col: "#ffaa00", br: "airbrush_soft", w: 1.15, n: 14 },
    { x1: 180, y1: 710, x2: 1220, y2: 430, col: "#ffd000", br: "airbrush_fine", w: 1.0, n: 12 },

    // Radioactive lime diagonal core & Cherenkov aura
    { x1: -30, y1: 860, x2: 1240, y2: 470, col: "#2b9348", br: "airbrush_mega", w: 1.5, n: 12 },
    { x1: 60, y1: 850, x2: 1180, y2: 490, col: "#76ff03", br: "airbrush_mega", w: 1.4, n: 16 },
    { x1: 160, y1: 830, x2: 1060, y2: 510, col: "#b2ff59", br: "airbrush_soft", w: 1.25, n: 16 },
    { x1: 280, y1: 800, x2: 940, y2: 530, col: "#eaff80", br: "airbrush_fine", w: 1.1, n: 14 }
  ];

  for (let b of skyBands) {
    brush.set(b.br, b.col, b.w);
    for (let i = 0; i < b.n; i++) {
      let oy = random(-48, 48);
      let midX = lerp(b.x1, b.x2, 0.5) + random(-40, 40);
