// ============================================================================
// LAYER 3: DIAGONAL STEEL LAB BENCH & UPWARD SPECIMEN LIGHT-WELL
// ============================================================================
function renderSteelLabBench() {
  // Bold diagonal bench geometry:
  // Back edge: (0, 790) -> (1200, 585)  (slope = -205 / 1200 = -0.17083, angle = -9.69 deg)
  // Front top lip: (0, 1095) -> (1200, 865)
  // Bevel thickness: 48 px
  let backL = [0, 790];
  let backR = [1200, 585];
  let frontL = [0, 1095];
  let frontR = [1200, 865];
  let bevL = [0, 1145];
  let bevR = [1200, 915];

  // 1. Base metallic wash for bench top surface
  brush.noStroke();
  brush.wash("#161f2c", 250);
  drawFilledPoly([backL, backR, frontR, frontL], 0.02);

  // Dark steel front bevel & lower laboratory cabinet apron
  brush.wash("#0b1017", 255);
  drawFilledPoly([frontL, frontR, [1200, 1200], [0, 1200]], 0.02);

  brush.wash("#28364a", 235);
  drawFilledPoly([frontL, frontR, bevR, bevL], 0.02);
  brush.noWash();

  // 2. Brushed stainless steel directional texture & dramatic color reflections
  let benchAngle = -9.8;
  for (let i = 0; i < 220; i++) {
    let t = i / 220;
    let yStart = lerp(792, 1092, t);
    let yEnd = lerp(587, 862, t);
    let x1 = random(0, 350);
    let x2 = random(850, 1200);
    let y1 = lerp(yStart, yEnd, x1 / 1200);
    let y2 = lerp(yStart, yEnd, x2 / 1200);

    // Choose reflection color based on zone relative to cloche (cx=610)
    let col = "#2b394d";
    let w = random(0.45, 1.1);
    let br = "2H";
    let r = random();
    if (r < 0.22) {
      col = "#4a5d75";
    } else if (r < 0.38) {
      col = "#0d131c";
    } else if (r < 0.54) {
      col = "#76ff03"; // radioactive lime reflection
      br = "cpencil";
      w = 0.65;
    } else if (r < 0.70) {
      col = "#ff7b00"; // sodium orange reflection
      br = "cpencil";
      w = 0.65;
    } else if (r < 0.84) {
      col = "#9d4edd"; // electric violet reflection
      br = "cpencil";
      w = 0.6;
    } else {
      col = "#caf0f8"; // bright steel specular hairline
      br = "gloss_razor";
      w = 0.45;
    }

    brush.set(br, col, w);
    brush.line(x1, y1, x2, y2);
  }

  // 3. Engraved scientific calibration grid on the steel lab bench
  for (let g = 1; g <= 9; g++) {
    let gxTop = g * 125 - 40;
    let gyTop = lerp(790, 585, gxTop / 1200);
    let gxBot = gxTop + 95;
    let gyBot = lerp(1095, 865, gxBot / 1200);
    brush.set("rotring", "#090d14", 0.55);
    brush.line(gxTop, gyTop, gxBot, gyBot);
    brush.set("gloss_razor", "#5c7696", 0.35);
    brush.line(gxTop + 1.5, gyTop, gxBot + 1.5, gyBot);
  }

  // 4. Embedded Upward Specimen Light-Well under the Cloche (cx = 610, cy = 835)
  // This is the dramatic upward light source illuminating the lobster from underneath!
  let lwCx = 610, lwCy = 838;
  let outerWell = getEllipseArc(lwCx, lwCy, 355, 114, 0, 360, 48, -7.5);
  let midWell = getEllipseArc(lwCx, lwCy, 295, 92, 0, 360, 48, -7.5);
  let innerWell = getEllipseArc(lwCx, lwCy, 235, 72, 0, 360, 48, -7.5);
  let coreWell = getEllipseArc(lwCx, lwCy, 155, 46, 0, 360, 40, -7.5);

  brush.noStroke();
  // Dark steel housing rim
  brush.wash("#080c14", 245);
  drawFilledPoly(outerWell, 0.15);
  // Radioactive lime & cyan luminous ring
  brush.wash("#38b000", 215);
  drawFilledPoly(midWell, 0.15);
  brush.wash("#76ff03", 225);
  drawFilledPoly(innerWell, 0.15);
  // White-hot / cyan-lime upward lamp core
  brush.wash("#eaff80", 235);
  drawFilledPoly(coreWell, 0.15);
  brush.noWash();

  // Airbrushed upward light bloom across the bench and base of cloche
  brush.set("airbrush_mega", "#76ff03", 1.35);
  brush.spline([[310, 865, 0.5], [610, 825, 1.3], [910, 795, 0.5]], 0.4);
  brush.set("airbrush_soft", "#ff9100", 1.15);
  brush.spline([[340, 895, 0.5], [610, 885, 1.2], [890, 835, 0.5]], 0.4);
  brush.set("airbrush_fine", "#ffffff", 1.1);
  brush.spline([[440, 848, 0.5], [610, 832, 1.3], [780, 815, 0.5]], 0.4);

  // 5. Cast Shadow of the Lobster & Cloche Rim across the Front-Left Steel Bench
  let benchShadow = [
    [255, 860], [105, 945], [0, 1020], [0, 1095],
    [320, 1030], [510, 945], [380, 895]
  ];
  brush.noStroke();
  brush.wash("#050811", 195);
  drawFilledPoly(benchShadow, 0.2);
  brush.noWash();

  // Caustic refracted light arcs thrown onto the steel bench in front of the cloche
  for (let c = 0; c < 6; c++) {
    let caustPts = getEllipseArc(615, 852 + c * 9, 348 + c * 11, 112 + c * 5, 12, 168, 32, -7.5);
    let cCol = c % 2 === 0 ? "#76ff03" : (c === 3 ? "#ffffff" : "#ff9100");
    brush.set(c === 3 ? "gloss_razor" : "cpencil", cCol, c === 3 ? 0.95 : 0.75);
    brush.spline(caustPts, 0.35);
  }

  // 6. Steel Bench Front Bevel Edge Highlights, Rivets & Pulp Lab Details
  brush.set("gloss_razor", "#e0fbfc", 1.1);
  brush.line(0, 1095, 1200, 865);
  brush.set("cpencil", "#76ff03", 0.8);
  brush.line(0, 1098, 1200, 868);
  brush.set("rotring", "#05070c", 1.2);
  brush.line(0, 1145, 1200, 915);

  // Industrial steel rivets along the bevel strip
  for (let rx = 70; rx < 1160; rx += 135) {
    let ry = lerp(1095, 865, rx / 1200) + 24;
    brush.noStroke();
    brush.wash("#090d14", 240);
    brush.circle(rx, ry, 7, 0.05);
    brush.noWash();
    brush.set("rotring", "#05070b", 0.6);
    brush.circle(rx, ry, 7, 0.05);
    brush.set("gloss_razor", "#b8f2ff", 0.65);
    brush.arc(rx, ry, 6, 200, 340);
  }

  // Condensed water droplets & puddles on the steel bench outside the cloche
  let benchDrops = [
    [210, 915, 14, 5], [245, 935, 9, 3.5], [165, 945, 18, 6],
    [965, 785, 16, 5.5], [1015, 805, 10, 3.5], [925, 825, 12, 4],
    [495, 968, 15, 5], [745, 918, 13, 4.5]
  ];
  for (let d of benchDrops) {
    let dPts = getEllipseArc(d[0], d[1], d[2], d[3], 0, 360, 16, -8);
    brush.noStroke();
    brush.wash("#061a2e", 210);
    drawFilledPoly(dPts, 0.2);
    brush.noWash();
    brush.set("gloss_razor", "#76ff03", 0.55);
    brush.spline(getEllipseArc(d[0], d[1] + 1, d[2] * 0.85, d[3] * 0.8, 15, 165, 10, -8), 0.3);
    brush.set("gloss_razor", "#ffffff", 0.65);
    brush.spline(getEllipseArc(d[0], d[1] - 1, d[2] * 0.75, d[3] * 0.7, 200, 330, 10, -8), 0.3);
  }
}

// ============================================================================
// LAYER 4: REAR GLASS CLOCHE WALL & INTERNAL ATMOSPHERE
// ============================================================================
function renderClocheRearLayer() {
  // Cloche Geometry:
  // Base center: (610, 838), tilt = -7.5 deg, rx = 335, ry = 104
  // Left wall: x = 275, y = 860 up to y = 515
  // Right wall: x = 945, y = 785 up to y = 445
  // Dome hemisphere: center (610, 480), radius = 336, apex around (610, 145)

  // Build full cloche silhouette for subtle internal refraction wash
  let domeArc = [];
  for (let i = 0; i <= 40; i++) {
    let a = lerp(186, 354, i / 40);
    let rad = radians(a);
    let x = 610 + 336 * Math.cos(rad);
    let y = 485 + 325 * Math.sin(rad) - (x - 610) * 0.08;
    domeArc.push([x, y]);
  }
  let baseArc = getEllipseArc(610, 838, 336, 104, 0, 180, 32, -7.5);
  let clocheOutline = domeArc.concat(baseArc);

  // Subtle internal humid cyan/violet glass tint
  brush.noStroke();
  brush.fill("#00b4d8", 32);
  brush.fillBleed(0.15, "in");
  drawFilledPoly(clocheOutline, 0.1);
  brush.noFill();

  // Rear elliptical glass base rim (seen through the dome)
  let rearRim1 = getEllipseArc(610, 838, 336, 104, 180, 360, 36, -7.5);
  let rearRim2 = getEllipseArc(610, 830, 326, 98, 180, 360, 36, -7.5);
  brush.set("cpencil", "#00f5d4", 0.75);
  brush.spline(rearRim1, 0.35);
  brush.set("gloss_razor", "#b2ff59", 0.65);
  brush.spline(rearRim2, 0.35);

  // Rear inner water/condensation meniscus pool at the bottom of the cloche
  let poolRim = getEllipseArc(610, 822, 322, 92, 185, 355, 32, -7.5);
  brush.set("cpencil", "#48cae4", 0.55);
  brush.spline(poolRim, 0.35);
}

