// ============================================================================
// LAYER 6: FOREGROUND GLASS CLOCHE, HARD SPECULAR ARC & BUBBLES
// ============================================================================
function renderClocheForeground() {
  // 1. Left & Right Glass Cylinder Walls + Hemispherical Dome Contour
  let leftWall = [[275, 862, 1.0], [275, 685, 0.9], [275, 505, 0.95]];
  let rightWall = [[945, 785, 1.0], [945, 615, 0.9], [945, 455, 0.95]];

  let domeContour = [];
  for (let i = 0; i <= 40; i++) {
    let a = lerp(182, 358, i / 40);
    let rad = radians(a);
    let x = 610 + 335 * Math.cos(rad);
    let y = 485 + 324 * Math.sin(rad) - (x - 610) * 0.075;
    domeContour.push([x, y, 0.9 + 0.3 * Math.sin((i / 40) * Math.PI)]);
  }

  // Thick borosilicate glass double-edge refractions (lime, cyan, violet, white)
  brush.set("cpencil", "#00f5d4", 1.25);
  brush.spline(leftWall, 0.2);
  brush.spline(rightWall, 0.2);
  brush.spline(domeContour, 0.4);

  // Inner glass wall thickness line (8px inset)
  let innerDome = domeContour.map(p => [
    610 + (p[0] - 610) * 0.974,
    485 + (p[1] - 485) * 0.974,
    p[2] * 0.8
  ]);
  brush.set("cpencil", "#d966ff", 0.85);
  brush.spline(innerDome, 0.4);
  brush.line(284, 858, 284, 505);
  brush.line(936, 782, 936, 455);

  // Crisp outer specular glass contour
  brush.set("gloss_razor", "#ffffff", 0.95);
  brush.spline(leftWall, 0.2);
  brush.spline(rightWall, 0.2);
  brush.spline(domeContour, 0.4);

  // 2. HARD SPECULAR ARC CURVING AROUND THE DOME (Key Style Directive!)
  // Sweeps dramatically down the upper-left curve of the hemisphere and cylinder wall
  let specArcOuter = [];
  let specArcInner = [];
  for (let i = 0; i <= 28; i++) {
    let t = i / 28;
    let a = lerp(252, 184, t);
    let rad = radians(a);
    let rx = 292;
    let ry = 285;
    let x1 = 610 + rx * Math.cos(rad);
    let y1 = 485 + ry * Math.sin(rad) - (x1 - 610) * 0.07;
    // Width of the hard specular reflection tapers at top and bottom
    let bandW = 26 * Math.sin(t * Math.PI) + 5;
    let x2 = x1 + bandW;
    let y2 = y1 + bandW * 0.35;
    specArcOuter.push([x1, y1]);
    specArcInner.push([x2, y2]);
  }
  // Extend hard specular band vertically down the left cylinder wall
  let cylSpecL = [[318, 495], [318, 635], [318, 765]];
  let cylSpecR = [[338, 502], [336, 638], [326, 768]];

  let fullSpecPoly = specArcOuter.concat(cylSpecL).concat(cylSpecR.slice().reverse()).concat(specArcInner.slice().reverse());

  // Soft airbrush glow behind the hard specular arc
  brush.set("airbrush_soft", "#00f5d4", 1.15);
  brush.spline(specArcOuter.map(p => [p[0], p[1], 1.0]), 0.4);
  brush.line(325, 495, 325, 765);

  // Hard-edged white specular reflection plane
  brush.noStroke();
  brush.wash("#ffffff", 220);
  drawFilledPoly(fullSpecPoly, 0.15);
  brush.noWash();

  // Chromatic aberration prism fringes along the hard specular arc
  brush.set("gloss_razor", "#d966ff", 0.85);
  brush.spline(specArcOuter.map(p => [p[0] - 2.5, p[1] - 1.5, 0.9]), 0.4);
  brush.set("gloss_razor", "#76ff03", 0.85);
  brush.spline(specArcInner.map(p => [p[0] + 2.5, p[1] + 1.5, 0.9]), 0.4);
  brush.set("gloss_razor", "#ffffff", 1.25);
  brush.spline(specArcOuter.map(p => [p[0], p[1], 1.1]), 0.4);
  brush.line(318, 495, 318, 765);

  // Secondary Window / Laboratory Lamp Reflection Arc on the Upper-Right Dome
  let rightSpec1 = [];
  let rightSpec2 = [];
  for (let i = 0; i <= 20; i++) {
    let t = i / 20;
    let a = lerp(292, 348, t);
    let rad = radians(a);
    let x = 610 + 305 * Math.cos(rad);
    let y = 485 + 295 * Math.sin(rad) - (x - 610) * 0.075;
    let w = 14 * Math.sin(t * Math.PI) + 2;
    rightSpec1.push([x, y]);
    rightSpec2.push([x - w, y + w * 0.35]);
  }
  brush.noStroke();
  brush.wash("#ffaa00", 175);
  drawFilledPoly(rightSpec1.concat(rightSpec2.slice().reverse()), 0.15);
  brush.noWash();
  brush.set("gloss_razor", "#ffffff", 1.05);
  brush.spline(rightSpec1.map(p => [p[0], p[1], 1.0]), 0.4);
  brush.set("cpencil", "#ff6d00", 0.9);
  brush.spline(rightSpec2.map(p => [p[0], p[1], 0.9]), 0.4);

  // Sweeping equator reflection ring across the front curvature of the dome
  let frontDomeGlint = getEllipseArc(610, 492, 334, 68, 18, 162, 32, -7.5);
  brush.set("cpencil", "#48cae4", 0.65);
  brush.spline(frontDomeGlint, 0.35);
  brush.set("gloss_razor", "#ffffff", 0.55);
  brush.spline(getEllipseArc(610, 490, 334, 68, 32, 115, 20, -7.5), 0.35);

  // 3. BUBBLES ON THE INSIDE OF THE GLASS & CONDENSATION STREAMS (Key Style Directive!)
  // Rising streams of oxygenated bubbles from the flooded base rim & claw contact points
  let bubbleClusters = [
    // Left wall & antenna contact bubble stream
