function renderPulpMastheadAndFrame() {
  // 1. Classic Pulp Magazine Outer Cover Margin Frame
  let m = 24;
  brush.noStroke();
  brush.wash("#090312", 255);
  // Top margin strip
  drawFilledPoly([[0, 0], [1200, 0], [1200, m], [0, m]], 0);
  // Bottom margin strip
  drawFilledPoly([[0, 1200 - m], [1200, 1200 - m], [1200, 1200], [0, 1200]], 0);
  // Left margin strip
  drawFilledPoly([[0, 0], [m, 0], [m, 1200], [0, 1200]], 0);
  // Right margin strip
  drawFilledPoly([[1200 - m, 0], [1200, 0], [1200, 1200], [1200 - m, 1200]], 0);

  // 2. BLANK MASTHEAD BAND AT THE TOP (Where a pulp magazine title would sit)
  // Positioned across x: 24..1176, y: 24..176 with an authentic stepped Art-Deco /
  // Atomic-Age pulp banner silhouette and blank issue/price emblem box on the left.
  let mastheadOuter = [
    [24, 24], [1176, 24], [1176, 166],
    [980, 166], [955, 182], [245, 182], [220, 166], [24, 166]
  ];
  let mastheadInner = [
    [36, 34], [1164, 34], [1164, 154],
    [974, 154], [950, 170], [250, 170], [226, 154], [36, 154]
  ];

  // Deep obsidian-violet masthead ground
  brush.wash("#0d051a", 252);
  drawFilledPoly(mastheadOuter, 0.02);

  // Rich vintage parchment-gold / dark-indigo recessed blank title plate
  brush.wash("#160a2c", 248);
  drawFilledPoly(mastheadInner, 0.02);
  brush.noWash();

  // Subtle horizontal airbrushed metallic gradient inside the blank masthead band
  // so it looks like a genuine painted pulp header slot ready for lettering
  brush.set("airbrush_soft", "#3c096c", 0.95);
  brush.line(60, 62, 1140, 62);
  brush.set("airbrush_soft", "#240046", 0.9);
  brush.line(60, 125, 1140, 125);
  brush.set("airbrush_fine", "#ff6d00", 0.65);
  brush.line(250, 162, 950, 162);

  // Stepped atomic-age double trim rules around the blank masthead band
  brush.set("gouache_chisel", "#ff6d00", 0.95);
  drawFilledPolyBorder(mastheadOuter);

  brush.set("gloss_razor", "#76ff03", 0.9);
  drawFilledPolyBorder(mastheadInner);

  // Inner decorative rule & corner bevel accents inside the blank masthead
  let decoRule = [
    [48, 44], [1152, 44], [1152, 144],
    [968, 144], [945, 160], [255, 160], [232, 144], [48, 144]
  ];
  brush.set("gloss_razor", "#ffaa00", 0.65);
  drawFilledPolyBorder(decoRule);

  // Blank Pulp Issue / Price Badge Medallion on the upper-left of the masthead
  let badgeCx = 118, badgeCy = 98;
  brush.noStroke();
  brush.wash("#ff5400", 240);
  brush.circle(badgeCx, badgeCy, 42, 0.04);
  brush.wash("#120624", 245);
  brush.circle(badgeCx, badgeCy, 35, 0.04);
  brush.noWash();
  brush.set("gloss_razor", "#ffd000", 0.85);
  brush.circle(badgeCx, badgeCy, 42, 0.04);
  brush.set("gloss_razor", "#76ff03", 0.7);
  brush.circle(badgeCx, badgeCy, 35, 0.04);

  // Matching blank geometric emblem on the upper-right of the masthead
  let rBox = [[1045, 58], [1135, 58], [1135, 132], [1045, 132]];
  brush.noStroke();
  brush.wash("#0b0318", 245);
  drawFilledPoly(rBox, 0.02);
  brush.noWash();
  brush.set("gloss_razor", "#ff6d00", 0.8);
  drawFilledPolyBorder(rBox);
  brush.set("gloss_razor", "#76ff03", 0.55);
  drawFilledPolyBorder([[1052, 65], [1128, 65], [1128, 125], [1052, 125]]);

  // 3. Outer Pulp Cover Frame Rules (Sodium Orange & Radioactive Lime)
  let outerFrame = [[24, 24], [1176, 24], [1176, 1176], [24, 1176]];
  let innerFrame = [[30, 30], [1170, 30], [1170, 1170], [30, 1170]];
  brush.set("gouache_chisel", "#ff6d00", 0.9);
  drawFilledPolyBorder(outerFrame);
  brush.set("gloss_razor", "#76ff03", 0.75);
  drawFilledPolyBorder(innerFrame);
}

function drawFilledPolyBorder(pts) {
  for (let i = 0; i < pts.length; i++) {
    let a = pts[i];
    let b = pts[(i + 1) % pts.length];
    brush.line(a[0], a[1], b[0], b[1]);
  }
}

