async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  brush.scaleBrushes(3);
  randomSeed(1884);
  noiseSeed(1884);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.paper);

  // 1. ARCHITECTURAL SHEET SUBSTRATE, GRID & UNDERLYING CONSTRUCTION LINES
  drawPaperAtmosphere();
  drawDraftingGridAndBorders();
  drawUnderlyingConstructionLines();

  // 2. BATCHED WATERCOLOR WASHES (Flat analytical lighting, warm sepia & walnut tones)
  drawBatchedWatercolorWashes();

  // 3. HYPERREAL PIANO CASEWORK, FLAME WALNUT VENEER & LACQUER CRACK
  drawWalnutCaseAndMoldings();
  drawFlameWalnutPanels();
  drawLacquerCrack();
  drawBrassSconcesAndHardware();

  // 4. HYPERREAL 88-KEY KEYBOARD (Yellowed Ivory, Chips, Ebony Sharps, Baize Felt)
  drawKeyboardAndCheeks();

  // 5. CONSOLE LEGS, PLINTH, CASTORS & WORN BRIGHT BRASS PEDALS
  drawLegsPlinthAndCastors();
  drawWornBrassPedals();

  // 6. HATCHED ARCHITECTURAL SECTION CUTS (Floor Datum & Section A-A in Right Margin)
  drawFloorSectionCut();
  drawRightMarginSectionCut();

  // 7. ANALYTIC OVERLAY: DIMENSION STRINGS, TICKS, CALLOUTS & TITLE BLOCK
  drawDimensionsAndCallouts();
  drawTitleBlock();

  noLoop();
}

