    brush.line(tx, 36, tx, 48);
    brush.line(tx, 1152, tx, 1164);
    drawArchText(cols[i], tx - 56, 39, 6, 0.45, PAL.dimLine);
  }
  const rows = ["A", "B", "C", "D", "E", "F", "G", "H"];
  for (let j = 0; j < 8; j++) {
    let ty = 170 + j * 125;
    brush.set("rotring", PAL.inkMid, 0.4);
    brush.line(36, ty, 48, ty);
    brush.line(1152, ty, 1164, ty);
    drawArchText(rows[j], 39, ty - 65, 6, 0.45, PAL.dimLine);
  }
}

