function drawCenterlineAxis(x, y1, y2) {
  let y = y1;
  while (y < y2) {
    let seg = min(y + 24, y2);
    brush.line(x, y, x, seg);
    if (seg + 5 < y2) {
      brush.line(x, seg + 4, x, min(seg + 8, y2));
    }
    y += 36;
  }
}

