function drawMirroredFlameWash(cx, cy, halfW, h) {
  brush.beginShape(0.4);
  brush.vertex(cx - halfW, cy + h * 0.65);
  brush.vertex(cx - halfW * 0.5, cy + h * 0.15);
  brush.vertex(cx, cy - h * 0.45);
  brush.vertex(cx + halfW * 0.5, cy + h * 0.15);
  brush.vertex(cx + halfW, cy + h * 0.65);
  brush.vertex(cx + halfW * 0.55, cy + h * 0.85);
  brush.vertex(cx, cy + h * 0.15);
  brush.vertex(cx - halfW * 0.55, cy + h * 0.85);
  brush.endShape(true);
}

