function drawSteppedMoldingFrame(x, y, w, h, steps) {
  for (let i = 0; i < steps; i++) {
    let off = i * 3;
    // Top & left light catch vs bottom & right shadow in flat orthographic convention
    brush.set("HB", i % 2 === 0 ? PAL.walnutDeep : PAL.walnutMid, i === 0 || i === steps - 1 ? 0.85 : 0.45);
    brush.line(x + off, y + off, x + w - off, y + off);
    brush.line(x + off, y + off, x + off, y + h - off);

    brush.set("rotring", PAL.walnutDeep, i === 0 || i === steps - 1 ? 0.9 : 0.55);
    brush.line(x + off, y + h - off, x + w - off, y + h - off);
    brush.line(x + w - off, y + off, x + w - off, y + h - off);

    // Mitered 45-degree corner joints
    if (i === 0) {
      let m = (steps - 1) * 3;
      brush.set("2H", PAL.walnutDark, 0.45);
      brush.line(x, y, x + m, y + m);
      brush.line(x + w, y, x + w - m, y + m);
      brush.line(x, y + h, x + m, y + h - m);
      brush.line(x + w, y + h, x + w - m, y + h - m);
    }
  }
}

