function renderBookmatchedVeneer(x, y, w, h, symX, archSteepness, numCurves) {
  // Draw undulating horizontal chatoyant curl stripes first
  for (let r = 0; r < h; r += 5.5) {
    let py = y + r;
    let wave = sin(r * 9 + symX * 0.2);
    let isLight = wave > 0.25;
    brush.set("cpencil", isLight ? PAL.chatoyant : PAL.walnutRich, isLight ? 0.52 : 0.48);

    let pts = [];
    let steps = 14;
    for (let s = 0; s <= steps; s++) {
      let px = x + (w * s) / steps;
      let dx = abs(px - symX);
      let n = noise(dx * 0.018, py * 0.022 + symX * 0.01) * 14 - 7;
      let arch = -pow(dx / (w * 0.5), 1.45) * 26 * archSteepness + n;
      let cy = constrain(py + arch, y + 2, y + h - 2);
      pts.push([px, cy]);
    }
    brush.spline(pts, 0.45);
  }

  // Draw sharp dark walnut cathedral grain fibers mirrored across symX
  for (let i = 0; i < numCurves; i++) {
    let baseT = i / numCurves;
    let startY = y + h * (0.08 + baseT * 1.15);
    let col = i % 3 === 0 ? PAL.walnutDeep : (i % 2 === 0 ? PAL.walnutDark : PAL.walnutMid);
    let wt = i % 4 === 0 ? 0.58 : 0.36;
    brush.set(i % 3 === 0 ? "rotring" : "2B", col, wt);

    let pts = [];
    let steps = 18;
    for (let s = 0; s <= steps; s++) {
      let px = x + (w * s) / steps;
      let dx = abs(px - symX);
      let asym = (px > symX ? 1 : -1) * noise(i * 0.3, s * 0.2) * 1.8;
      let grainWarp = noise(dx * 0.025, i * 0.28) * 18;
      let cathedral = pow(dx / (w * 0.52), 1.6) * (h * 0.52 * archSteepness);
      let ripple = sin(dx * 4.5 + i * 22) * 2.2;
      let py = startY + cathedral - grainWarp + ripple + asym;
      py = constrain(py, y + 1.5, y + h - 1.5);
      pts.push([px, py]);
    }
    brush.spline(pts, 0.5);
  }
}

function renderHorizontalWoodGrain(x, y, w, h, lines) {
  for (let i = 0; i < lines; i++) {
    let py = y + 1.5 + (i / lines) * (h - 3);
    let col = i % 3 === 0 ? PAL.walnutDark : (i % 3 === 1 ? PAL.walnutMid : PAL.chatoyant);
    brush.set("cpencil", col, 0.38);
    let pts = [];
    for (let s = 0; s <= 10; s++) {
      let px = x + (w * s) / 10;
      let dy = (noise(px * 0.015, py * 0.08 + i) - 0.5) * 3.2;
      pts.push([px, constrain(py + dy, y + 1, y + h - 1)]);
    }
    brush.spline(pts, 0.4);
  }
}

function renderVerticalWoodGrain(x, y, w, h, lines) {
  for (let i = 0; i < lines; i++) {
    let px = x + 1.5 + (i / lines) * (w - 3);
    let col = i % 2 === 0 ? PAL.walnutDark : PAL.walnutMid;
    brush.set("cpencil", col, 0.38);
    let pts = [];
    for (let s = 0; s <= 8; s++) {
      let py = y + (h * s) / 8;
      let dx = (noise(px * 0.08 + i, py * 0.015) - 0.5) * 2.5;
      pts.push([constrain(px + dx, x + 1, x + w - 1), py]);
    }
    brush.spline(pts, 0.4);
  }
}

function drawLacquerCrack() {
  // Hyperreal crazed shellac/lacquer fissure on the upper center walnut panel
  // Main crack spine from (578, 282) down-left to (524, 434)
  const mainCrack = [
    [578, 282], [571, 299], [566, 314], [556, 332],
    [551, 351], [541, 372], [536, 393], [529, 414], [524, 434]
  ];
  const branchA = [[566, 314], [579, 328], [588, 344], [594, 359]];
  const branchB = [[551, 351], [534, 360], [521, 371], [511, 385]];
  const branchC = [[536, 393], [548, 408], [555, 424]];
  const branchD = [[556, 332], [546, 336], [539, 343]];

  // 1. Pale lifted-lacquer refraction edge (offset +1.1px right)
  brush.set("2H", PAL.ivoryLight, 0.68);
  for (let i = 0; i < mainCrack.length - 1; i++) {
    brush.line(
      mainCrack[i][0] + 1.2, mainCrack[i][1],
      mainCrack[i + 1][0] + 1.2, mainCrack[i + 1][1]
    );
  }
  for (let b of [branchA, branchB, branchC]) {
    for (let i = 0; i < b.length - 1; i++) {
      brush.line(b[i][0] + 0.9, b[i][1], b[i + 1][0] + 0.9, b[i + 1][1]);
    }
  }

  // 2. Razor-sharp dark fissure crevice
  brush.set("rotring", PAL.inkDark, 0.78);
  for (let i = 0; i < mainCrack.length - 1; i++) {
    brush.line(mainCrack[i][0], mainCrack[i][1], mainCrack[i + 1][0], mainCrack[i + 1][1]);
  }

  // 3. Secondary crazing hairlines
  brush.set("rotring", PAL.walnutDeep, 0.45);
  for (let b of [branchA, branchB, branchC, branchD]) {
    for (let i = 0; i < b.length - 1; i++) {
      brush.line(b[i][0], b[i][1], b[i + 1][0], b[i + 1][1]);
    }
  }

  // Fine horizontal crazing checks along the main fissure
  brush.set("2H", PAL.chatoyant, 0.32);
  for (let i = 1; i < mainCrack.length - 1; i++) {
    let cx = mainCrack[i][0];
    let cy = mainCrack[i][1];
    brush.line(cx - 7, cy - 2, cx + 8, cy + 3);
  }
}

