  brush.noStroke();
  brush.wash(PAL.feltRed, 225);
  brush.rect(181, 548, 598, 5);   // Upper nameboard felt
  brush.rect(181, 595, 598, 4.5); // Under-key rail felt
  brush.noWash();

  // 2. Sculpted Walnut Cheek Blocks (left: 138..181, right: 779..822)
  brush.noStroke();
  brush.wash(PAL.walnutMid, 195);
  brush.rect(138, 512, 43, 88);
  brush.rect(779, 512, 43, 88);
  brush.wash(PAL.walnutDark, 140);
  brush.rect(138, 588, 43, 12);
  brush.rect(779, 588, 43, 12);
  brush.noWash();
  renderVerticalWoodGrain(141, 515, 37, 82, 10);
  renderVerticalWoodGrain(782, 515, 37, 82, 10);
  brush.set("rotring", PAL.walnutDeep, 0.85);
  brush.noFill();
  brush.rect(138, 512, 43, 88);
  brush.rect(779, 512, 43, 88);

  // 3. Individual 52 White Keys (A0 to C8)
  // Top tail surface (553..572), front ivory wafer lip (572..580), key front (580..595)
  const chippedKeys = {
    15: { side: "right", w: 4.5, h: 4.2 }, // B2
    23: { side: "left",  w: 5.8, h: 5.2 }, // C4 (Middle C - prominent chip)
    24: { side: "right", w: 4.2, h: 3.8 }, // D4
    28: { side: "center", w: 5.0, h: 4.5 }, // A4
    34: { side: "left",  w: 3.8, h: 3.5 }  // G5
  };

  for (let i = 0; i < numWhite; i++) {
    let kx = keyLeft + i * kw;
    // Calculate yellowing based on proximity to middle register (keys 16..36) + subtle per-key variation
    let midFactor = exp(-pow((i - 25) / 13, 2));
    let nVal = noise(i * 0.73);
    let waferCol = PAL.ivoryLight;
    if (midFactor + nVal * 0.35 > 0.85) waferCol = PAL.ivoryAged;
    else if (midFactor + nVal * 0.35 > 0.55) waferCol = PAL.ivoryYellow;
    else if (midFactor + nVal * 0.35 > 0.3) waferCol = PAL.ivoryMid;

    brush.noStroke();
    // Recessed white key tail between black keys (553..572)
    brush.wash(waferCol, 195);
    brush.rect(kx + 0.6, 553, kw - 1.2, 19);

    // Bright ivory front wafer lip (572..580)
    brush.wash(waferCol, 235);
    brush.rect(kx + 0.5, 572, kw - 1.0, 8);

    // Shadowed vertical key front below the overhanging ivory wafer (580..595)
    brush.wash(PAL.ivoryShadow, 175);
    brush.rect(kx + 0.6, 580, kw - 1.2, 15);
    brush.noWash();

    // Subtle ivory grain hairlines & age craze on middle keys
    if (midFactor > 0.45 && i % 2 === 0) {
      brush.set("2H", PAL.sepiaWash, 0.28);
      brush.line(kx + 3.5, 572.5, kx + 3.8, 579.5);
      brush.line(kx + 7.5, 581, kx + 7.5, 594);
    }

    // Bright upper ivory edge catch-light
    brush.set("cpencil", "#fffdf7", 0.55);
    brush.line(kx + 0.8, 572.5, kx + kw - 0.8, 572.5);

    // Crisp shadow line directly under the ivory wafer lip (y = 580)
    brush.set("rotring", PAL.walnutDark, 0.58);
    brush.line(kx + 0.4, 580, kx + kw - 0.4, 580);

    // Vertical gap between white keys
    brush.set("rotring", PAL.inkDark, 0.52);
    brush.line(kx, 553, kx, 595);

    // Render Hyperreal Ivory Chips on selected keys!
    if (chippedKeys[i]) {
      let ch = chippedKeys[i];
      let cx = ch.side === "left" ? kx + 0.5 : (ch.side === "right" ? kx + kw - ch.w - 0.5 : kx + 3.2);
      let cy = 572;

      // Dark exposed wood core beneath chipped ivory wafer
      brush.noStroke();
      brush.wash(PAL.chipDark, 245);
      brush.beginShape(0.05);
      brush.vertex(cx, cy);
      brush.vertex(cx + ch.w, cy);
      brush.vertex(cx + ch.w * 0.8, cy + ch.h);
      brush.vertex(cx + ch.w * 0.25, cy + ch.h * 1.15);
      brush.vertex(cx, cy + ch.h * 0.7);
      brush.endShape(true);
      brush.noWash();

      // Crisp broken ivory fracture rim highlight & micro-crack
      brush.set("2H", "#ffffff", 0.45);
      brush.line(cx, cy + ch.h * 0.7, cx + ch.w * 0.25, cy + ch.h * 1.15);
      brush.line(cx + ch.w * 0.25, cy + ch.h * 1.15, cx + ch.w * 0.8, cy + ch.h);
      brush.set("rotring", PAL.walnutDeep, 0.38);
      brush.line(cx + ch.w * 0.4, cy + ch.h, cx + ch.w * 0.5, 580);
    }
  }
  // Rightmost key border
  brush.set("rotring", PAL.inkDark, 0.6);
  brush.line(keyLeft + numWhite * kw, 553, keyLeft + numWhite * kw, 595);
  brush.line(keyLeft, 572, keyLeft + numWhite * kw, 572);
  brush.line(keyLeft, 595, keyLeft + numWhite * kw, 595);

  // 4. 36 Ebony Black Keys (Sharps) in Strict Frontal Elevation
  // Pattern: A#0 (after key 0), then 7 octaves starting at key 2, 9, 16, 23, 30, 37, 44
  // with sharp offsets [0, 1, 3, 4, 5] (C#, D#, F#, G#, A#)
  const sharpIndices = [0];
  for (let oct = 0; oct < 7; oct++) {
    let base = 2 + oct * 7;
    sharpIndices.push(base, base + 1, base + 3, base + 4, base + 5);
  }

  for (let idx of sharpIndices) {
    // Center of sharp is on the seam between white key idx and idx + 1
    let seamX = keyLeft + (idx + 1) * kw;
    let bwBase = 7.0;
    let bwTop = 5.4;
    let bTopY = 553.5;
    let bBotY = 572.0;

    // Ebony body trapezoid (chamfered sides in frontal elevation)
    brush.noStroke();
    brush.wash(PAL.ebony, 248);
    brush.beginShape(0);
    brush.vertex(seamX - bwBase / 2, bBotY);
    brush.vertex(seamX - bwTop / 2, bTopY);
    brush.vertex(seamX + bwTop / 2, bTopY);
    brush.vertex(seamX + bwBase / 2, bBotY);
    brush.endShape(true);

    // Front vertical bevel face of the ebony key
    brush.wash(PAL.ebonyMid, 220);
    brush.rect(seamX - bwTop / 2 + 0.4, bTopY + 11, bwTop - 0.8, 7);
    brush.noWash();

    // Worn satin sheen on the top-front nose of each ebony sharp (brighter in central octaves)
    let wear = exp(-pow((idx - 25) / 15, 2));
    brush.set("cpencil", wear > 0.5 ? "#b0a496" : PAL.ebonySheen, 0.58);
    brush.line(seamX - bwTop / 2 + 0.5, bTopY + 1.0, seamX + bwTop / 2 - 0.5, bTopY + 1.0);
    brush.line(seamX - bwTop / 2 + 0.5, bTopY + 10.5, seamX + bwTop / 2 - 0.5, bTopY + 10.5);

    // Crisp ebony outline
    brush.set("rotring", PAL.inkDark, 0.48);
    brush.line(seamX - bwBase / 2, bBotY, seamX - bwTop / 2, bTopY);
    brush.line(seamX - bwTop / 2, bTopY, seamX + bwTop / 2, bTopY);
    brush.line(seamX + bwTop / 2, bTopY, seamX + bwBase / 2, bBotY);
  }
}

