// 6. HATCHED ARCHITECTURAL SECTION CUTS (Floor Datum & Section A-A in Right Margin)
// =============================================================================
function drawFloorSectionCut() {
  // Heavy architectural floor cut line at Y_FLOOR = 936
  brush.set("rotring", PAL.inkDark, 1.35);
  brush.line(95, Y_FLOOR, 865, Y_FLOOR);
  brush.line(915, Y_FLOOR, 1115, Y_FLOOR);

  // Subfloor hatching zone beneath Y_FLOOR (y = 936..968)
  brush.noStroke();
  brush.wash(PAL.sectionFill, 85);
  brush.rect(105, Y_FLOOR, 750, 28);
  brush.rect(920, Y_FLOOR, 190, 28);
  brush.noWash();

  // Classic architectural earth/subfloor alternating 45° / -45° hatch packs
  brush.set("rotring", PAL.inkMid, 0.42);
  for (let x = 105; x < 840; x += 28) {
    let dir = ((x - 105) / 28) % 2 === 0;
    for (let k = 0; k < 28; k += 5.5) {
      if (dir) {
        brush.line(x + k, Y_FLOOR, x, Y_FLOOR + k);
        brush.line(x + 28, Y_FLOOR + k, x + k, Y_FLOOR + 28);
      } else {
        brush.line(x + 28 - k, Y_FLOOR, x + 28, Y_FLOOR + k);
        brush.line(x, Y_FLOOR + k, x + 28 - k, Y_FLOOR + 28);
      }
    }
  }
  for (let x = 920; x < 1095; x += 28) {
    for (let k = 0; k < 28; k += 5.5) {
      brush.line(x + k, Y_FLOOR, x, Y_FLOOR + k);
      brush.line(x + 28, Y_FLOOR + k, x + k, Y_FLOOR + 28);
    }
  }
  brush.set("2H", PAL.dimLine, 0.35);
  brush.line(105, Y_FLOOR + 28, 855, Y_FLOOR + 28);
  brush.line(920, Y_FLOOR + 28, 1110, Y_FLOOR + 28);
}

function drawRightMarginSectionCut() {
  // SECTION A-A: Strict vertical cross-section cut through the piano center (x = 930..1095, y = 200..936)
  // Demonstrates internal structure: laminated pinblock, cast-iron harp, spruce soundboard,
  // keybed structural beams, key lever & action profile, and hatched casework cuts.

  // 1. Background interior cavity & backpost elevation
  brush.noStroke();
  brush.wash(PAL.paperWarm, 150);
  brush.rect(975, 218, 110, 702);
  // Heavy timber backpost (x = 1068..1088)
  brush.wash(PAL.sepiaWash, 145);
  brush.rect(1068, 218, 20, 698);
  brush.noWash();

  // 2. Hatched Hardwood Casework Section Cuts (using brush.hatch!)
  const cutBlocks = [
    [965, 200, 123, 18, 45],  // Top lid cut
    [975, 218, 17, 32, -45],  // Upper frieze rail cut
    [975, 250, 14, 224, 45],  // Upper front panel cut
    [975, 474, 17, 22, -45],  // Fallboard rail cut
    [940, 496, 48, 16, 45],   // Fallboard cylinder lip cut
    [926, 600, 18, 26, -45],  // Keyslip cut
    [926, 626, 124, 26, 45],  // Heavy keybed timber cut
    [975, 652, 16, 232, 45],  // Lower belly panel cut
    [975, 884, 113, 36, -45], // Bottom plinth & sole timber cut
    [1032, 224, 26, 96, -45]  // Laminated beech pinblock (wrestplank)
  ];

  // Fill cut blocks with warm section tone
  brush.noStroke();
  brush.wash(PAL.walnutLight, 130);
  for (let b of cutBlocks) {
    brush.rect(b[0], b[1], b[2], b[3]);
  }
  brush.noWash();

  // Hatch each cut block at 45° or -45° with crisp rotring lines
  brush.hatchStyle("rotring", PAL.inkDark, 0.42);
  for (let b of cutBlocks) {
    brush.hatch(4.5, b[4], { rand: 0.02 });
    brush.noStroke();
    brush.rect(b[0], b[1], b[2], b[3]);
  }
  brush.noHatch();

  // Heavy section-cut outlines around all cut blocks
  brush.set("rotring", PAL.inkDark, 0.9);
  brush.noFill();
  for (let b of cutBlocks) {
    brush.rect(b[0], b[1], b[2], b[3]);
  }

  // 3. Spruce Soundboard & Bridges in Section (x = 1058..1066, y = 320..880)
  brush.noStroke();
  brush.wash(PAL.ivoryYellow, 180);
  brush.rect(1058, 320, 8, 560);
  brush.noWash();
  brush.set("rotring", PAL.inkDark, 0.65);
  brush.rect(1058, 320, 8, 560);
  // Soundboard ribs along back face
  for (let ry = 350; ry < 860; ry += 48) {
    brush.noStroke();
    brush.wash(PAL.walnutLight, 180);
    brush.rect(1066, ry, 7, 14);
    brush.noWash();
    brush.set("rotring", PAL.inkDark, 0.5);
    brush.rect(1066, ry, 7, 14);
  }

  // 4. Cast-Iron Harp Plate & Vertical String Line (x = 1022..1030)
  brush.noStroke();
  brush.wash(PAL.brassMid, 190);
  brush.rect(1022, 224, 9, 655);
  brush.noWash();
  brush.set("rotring", PAL.inkDark, 0.6);
  brush.rect(1022, 224, 9, 655);
  // Tuning pins inserted into pinblock (y = 235..305)
  for (let py = 236; py <= 302; py += 9) {
    brush.set("rotring", PAL.inkDark, 0.65);
    brush.line(1012, py + 2, 1048, py - 2);
  }
  // Taut vertical piano wire from tuning pin over treble & bass bridges to hitch pin
  brush.set("rotring", PAL.inkDark, 0.55);
  brush.line(1018, 250, 1052, 860);

  // 5. Key Lever & Hammer Action Profile in Section (x = 928..1035, y = 380..595)
  // White key lever resting on keybed & balance rail pin
  brush.noStroke();
  brush.wash(PAL.ivoryMid, 220);
  brush.rect(928, 572, 112, 18);
  // Ebony sharp cap in section
  brush.wash(PAL.ebony, 240);
  brush.rect(942, 553.5, 36, 18.5);
  brush.noWash();
  brush.set("rotring", PAL.inkDark, 0.7);
  brush.rect(928, 572, 112, 18);
  brush.rect(942, 553.5, 36, 18.5);
  // Lead key counterweights inside key lever
  brush.circle(1018, 581, 4.5, 0.05);
  brush.circle(1030, 581, 4.5, 0.05);

  // Capstan, Whippen, Jack & Felt Hammer striking string at y = 415
  brush.set("rotring", PAL.inkMid, 0.55);
  brush.line(1012, 572, 1012, 515); // Capstan & abstract
  brush.rect(998, 502, 28, 13);     // Whippen assembly
  brush.line(1004, 502, 1016, 420); // Hammer shank
  // Pear-shaped felt hammer head striking string at (1026, 415)
  brush.noStroke();
  brush.wash(PAL.ivoryLight, 235);
  brush.beginShape(0.3);
  brush.vertex(1010, 412);
  brush.vertex(1028, 408);
  brush.vertex(1028, 422);
  brush.vertex(1010, 418);
  brush.endShape(true);
  brush.noWash();
  brush.set("rotring", PAL.inkDark, 0.65);
  brush.beginShape(0.3);
  brush.vertex(1010, 412);
  brush.vertex(1028, 408);
  brush.vertex(1028, 422);
  brush.vertex(1010, 418);
  brush.endShape(true);

  // Pedal trapwork vertical push-rod in lower cavity
  brush.set("HB", PAL.inkMid, 0.6);
  brush.line(1004, 652, 1004, 912);
  brush.line(960, 922, 1008, 912); // Pedal lever arm
}

