function drawDimH(x1, x2, y, label) {
  // Extension lines
  brush.set("2H", PAL.constLine, 0.35);
  brush.line(x1, y - 10, x1, y + 14);
  brush.line(x2, y - 10, x2, y + 14);

  // Dimension line
  brush.set("HB", PAL.dimLine, 0.48);
  brush.line(x1 - 6, y, x2 + 6, y);

  // 45-degree architectural slash ticks at ends
  brush.set("rotring", PAL.inkDark, 0.78);
