// =============================================================================
// VECTOR ARCHITECTURAL LETTERING HELPER (100% p5.brush strokes)
// =============================================================================
function drawArchText(str, x, y, size, weight, col) {
  brush.set("rotring", col, weight);
  let cx = x;
  let w = size * 0.68;
  let step = size * 1.05;
  let upper = str.toUpperCase();

  for (let i = 0; i < upper.length; i++) {
    let ch = upper[i];
    if (ch === ' ') {
      cx += step * 0.75;
      continue;
    }
    let segs = GLYPHS[ch];
    if (segs) {
      for (let s of segs) {
        brush.line(
          cx + s[0] * w,
          y + s[1] * size,
          cx + s[2] * w,
          y + s[3] * size
        );
      }
    }
    cx += step;
  }
}

