function draw() {
  translate(-width / 2, -height / 2);

  // Warm museum paper & aged plaster ground
  background("#e8e2d5");

  // -------------------------------------------------------------------------
  // 1. PAINTED DIORAMA CYCLORAMA (Hazy Beech Forest at Dusk in Watercolor)
