}

// ===========================================================================
// LAYER 1: PAINTED DIORAMA CYCLORAMA (Soft Watercolor Beech Forest)
// ===========================================================================
function drawDioramaBackdrop() {
  brush.noField();
  brush.noStroke();

  // Soft dusk sky & upper cyclorama plaster dome washes (lavender + raw umber)
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.65, 0.25);

  // Batch 1: Pale dusk lavender atmospheric washes
  brush.fill("#b8b0c2", 52);
  drawSoftBand(40, 0, 1160, 420, 18);
  drawSoftBand(60, 120, 1140, 560, 16);

  brush.fill("#9c93ab", 48);
  drawSoftBand(80, 40, 1120, 310, 14);
  drawSoftBlob(320, 210, 260, 140, 14);
  drawSoftBlob(820, 190, 290, 150, 14);

  // Batch 2: Muted sap green distant canopy washes (the color accent in haze)
  brush.fillBleed(0.42, "out");
  brush.fill("#667554", 46);
  drawSoftBlob(220, 140, 240, 150, 14);
  drawSoftBlob(540, 110, 310, 165, 14);
  drawSoftBlob(920, 150, 270, 160, 14);
  drawSoftBand(50, 340, 1150, 540, 16);

  brush.fill("#4d5c3e", 44);
  drawSoftBlob(160, 240, 200, 130, 12);
  drawSoftBlob(680, 210, 250, 135, 12);
  drawSoftBlob(1020, 260, 190, 130, 12);

  // Batch 3: Raw umber forest floor recession on the painted wall
  brush.fillBleed(0.38, "out");
  brush.fill("#786856", 55);
  drawSoftBand(40, 470, 1160, 690, 16);
  brush.fill("#5c4e3f", 52);
  drawSoftBand(40, 560, 1160, 745, 16);

  // Distant hazy beech trunks (painted softly onto the curved plaster wall)
  const distantTrees = [
    { x: 135, w: 34, top: 40, bot: 660, col: "#8d848c", op: 55 },
    { x: 265, w: 24, top: 65, bot: 645, col: "#968e96", op: 45 },
    { x: 390, w: 46, top: 20, bot: 670, col: "#7b7278", op: 58 },
    { x: 525, w: 28, top: 70, bot: 650, col: "#928991", op: 44 },
    { x: 635, w: 32, top: 50, bot: 655, col: "#857c82", op: 48 },
    { x: 775, w: 54, top: 15, bot: 685, col: "#746b6f", op: 62 },
    { x: 910, w: 26, top: 60, bot: 665, col: "#8c838a", op: 46 },
    { x: 1035, w: 62, top: 10, bot: 710, col: "#6b6163", op: 68 }
  ];

  // Draw misty far trunks
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.5, 0.2);
  for (let t of distantTrees) {
    brush.fill(t.col, t.op);
    drawPaintedTreeTrunk(t.x, t.top, t.bot, t.w);
  }

  // Intervening dusk mist band (lavender-grey veil)
  brush.fillBleed(0.5, "out");
  brush.fill("#c5bfd0", 42);
  drawSoftBand(50, 380, 1150, 560, 14);

  // Closer painted beech trees on the cyclorama (sap green moss stains + raw umber bark)
  const midTrees = [
    { x: 195, w: 68, top: 0, bot: 700 },
    { x: 465, w: 58, top: 0, bot: 685 },
    { x: 845, w: 74, top: 0, bot: 715 },
    { x: 1110, w: 52, top: 0, bot: 735 }
  ];

  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.6, 0.35);
  for (let t of midTrees) {
    // Raw umber & slate bark wash
    brush.fill("#63584e", 72);
    drawPaintedTreeTrunk(t.x, t.top, t.bot, t.w);

    // Sap-green painted moss wash along the left side of the trunk
    brush.fill("#4f613d", 62);
    drawPaintedTreeTrunk(t.x - t.w * 0.22, t.top + 80, t.bot, t.w * 0.42);
  }

  // Deliberately painterly brush marks on the backdrop trees & branches (soft charcoal/2B)
  brush.noFill();
  brush.wiggle(1.8);
  for (let t of midTrees) {
    // Soft vertical bark edge shading
    brush.set("charcoal", "#4a423b", 0.65);
    brush.line(t.x - t.w * 0.48, t.top + 20, t.x - t.w * 0.52, t.bot - 10);
    brush.set("2B", "#7c726b", 0.45);
    brush.line(t.x + t.w * 0.46, t.top + 30, t.x + t.w * 0.5, t.bot - 15);

    // Characteristic horizontal beech bark lenticels (soft, blurry, painted look)
    for (let y = t.top + 60; y < t.bot - 40; y += random(22, 42)) {
      let lx = t.x - t.w * 0.35 + random(0, t.w * 0.3);
      let lw = random(t.w * 0.2, t.w * 0.48);
      brush.set("2B", "#494139", 0.38);
      brush.line(lx, y, lx + lw, y + random(-3, 3));
    }

    // Sweeping painted boughs in the upper canopy
    if (t.x < 950) {
      brush.set("charcoal", "#595046", 0.55);
      brush.spline([
        [t.x + t.w * 0.3, 180 + random(-30, 30), 0.7],
        [t.x + 90, 130 + random(-20, 20), 0.5],
        [t.x + 190, 105 + random(-25, 25), 0.2]
      ], 0.5);
    }
  }
  brush.noField();

  // Painted foliage dabbing in the upper backdrop (sap green & lavender-grey)
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  for (let i = 0; i < 16; i++) {
    let fx = random(80, 1120);
    let fy = random(40, 330);
    brush.fill(i % 3 === 0 ? "#7c758a" : "#4e603c", random(32, 54));
    brush.circle(fx, fy, random(32, 68), 0.45);
  }

  // The telltale Diorama Cove Joint: where the curved painted wall meets the 3D plaster ground
  // A subtle continuous curved seam and slight tonal disconnect at y ≈ 685..745
  brush.noFill();
  brush.set("2H", "#635a4f", 0.35);
  let covePts = [];
  for (let x = 35; x <= 1185; x += 60) {
    let cy = 702 + 28 * sin((x / 1200) * 165 - 20) + (x / 1200) * 32;
    covePts.push([x, cy, 0.4]);
  }
  brush.spline(covePts, 0.4);

  // Subtle wall-crack in the upper right plaster cyclorama (betraying its age)
  brush.set("finePen", "#8a8175", 0.35);
  brush.spline([
    [985, 78, 0.2],
    [972, 128, 0.5],
    [978, 164, 0.4],
    [964, 212, 0.15]
  ], 0.3);
}

