  brush.beginShape(0.15);
  brush.vertex(30, 695);
  brush.vertex(350, 682);
  brush.vertex(740, 708);
  brush.vertex(1190, 742);
  brush.vertex(1190, 1190);
  brush.vertex(30, 1190);
  brush.endShape(true);
  brush.noWash();

  // 2. Watercolor & raw umber washes modeling the plaster rocks and forest bank
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.75, 0.45);

  // Left big limestone/plaster slab (under badger's hind legs)
  const leftRock = [
    [55, 755], [185, 718], [365, 732], [495, 785],
    [515, 885], [420, 965], [210, 985], [55, 935]
