  // Deep shadow washes under the rock overhangs & badger belly/legs
  brush.fillBleed(0.14, "out");
  brush.fill("#3d372f", 145);
  // Shadow under left rock ledge
  drawPolyShape([
    [80, 910], [260, 925], [455, 915], [490, 960], [240, 995], [75, 960]
  ], 0.2);
  // Cast shadow of the badger on the plaster stones
  drawPolyShape([
    [275, 792], [520, 775], [725, 815], [865, 825],
    [840, 885], [615, 895], [395, 855], [260, 835]
  ], 0.35);
