  brush.fill("#292520", 165);
  drawPolyShape([
    [765, 815], [852, 812], [868, 842], [775, 848]
  ], 0.35);

  // 3. Flocked Fake Moss Patches (Sap Green & Olive Accent on the Plaster Rocks)
