    { x: 195, y: 745, rx: 85, ry: 26 },
    { x: 355, y: 762, rx: 68, ry: 22 },
    { x: 575, y: 805, rx: 72, ry: 24 },
    { x: 755, y: 808, rx: 64, ry: 20 },
    { x: 925, y: 858, rx: 92, ry: 30 },
