    brush.fill("#667a47", 95);
    drawSoftBlob(m.x - m.rx * 0.15, m.y - 4, m.rx * 0.65, m.ry * 0.65, 10);
  }
  brush.noFill();

  // 4. Hyperreal Pen & Graphite Facets on the Plaster Rocks
  // Structural rock planes hatched at crisp geological angles
  const rockFacets = [
    // Left rock upper & side facets
    { pts: [[70, 765], [190, 730], [240, 815], [95, 845]], dist: 5.5, ang: -18, col: "#4a443c", b: "2H", w: 0.38 },
    { pts: [[190, 730], [365, 740], [385, 835], [240, 815]], dist: 6.5, ang: 12, col: "#575046", b: "2H", w: 0.35 },
    { pts: [[240, 815], [385, 835], [475, 805], [495, 895], [220, 925]], dist: 4.2, ang: -38, col: "#36312b", b: "HB", w: 0.45 },
    { pts: [[95, 845], [240, 815], [220, 925], [75, 915]], dist: 3.8, ang: -65, col: "#2b2722", b: "rotring", w: 0.35 },
    // Center-right stepping stone facets
    { pts: [[485, 825], [645, 795], [670, 875], [475, 910]], dist: 5.0, ang: -24, col: "#453f37", b: "2H", w: 0.4 },
    { pts: [[645, 795], [840, 805], [860, 895], [670, 875]], dist: 6.0, ang: 8, col: "#524b42", b: "2H", w: 0.35 },
    { pts: [[840, 805], [1025, 850], [1055, 945], [860, 895]], dist: 4.5, ang: -32, col: "#38332c", b: "HB", w: 0.42 },
    { pts: [[510, 905], [860, 895], [960, 995], [565, 1015]], dist: 3.6, ang: -52, col: "#2a2520", b: "rotring", w: 0.38 },
