    { pts: [[510, 905], [860, 895], [910, 955], [545, 965]], dist: 4.5, ang: 25, col: "#221e1a", b: "rotring", w: 0.32 },
    // Foreground plaster apron hatched texture
    { pts: [[50, 985], [480, 975], [520, 1175], [50, 1175]], dist: 5.5, ang: -14, col: "#3c362f", b: "HB", w: 0.42 },
    { pts: [[480, 975], [1160, 980], [1160, 1175], [520, 1175]], dist: 5.0, ang: -28, col: "#332e27", b: "HB", w: 0.45 }
  ];

  for (let f of rockFacets) {
    let poly = new brush.Polygon(f.pts);
    brush.hatchStyle(f.b, f.col, f.w);
    poly.hatch(f.dist, f.ang, { rand: 0.04, gradient: 0.25 });
  }
  brush.noHatch();

  // Sharp pen & graphite rock fissures, chipped white plaster edges & burlap texture
  for (let f of rockFacets) {
    brush.set("rotring", "#2b2621", 0.38);
    for (let i = 0; i < f.pts.length; i++) {
      let p1 = f.pts[i];
      let p2 = f.pts[(i + 1) % f.pts.length];
