        brush.spline([
          [p1[0], p1[1], 0.3],
          [(p1[0] + p2[0]) * 0.5 + random(-6, 6), (p1[1] + p2[1]) * 0.5 + random(-5, 5), 0.7],
          [p2[0], p2[1], 0.2]
        ], 0.25);
      }
    }
  }

  // Tell-tale chipped plaster highlights (bright chalky white where plaster chipped at the rock edge)
  const plasterChips = [
    [[235, 814], [258, 818], [248, 826]],
    [[662, 872], [692, 876], [678, 886]],
    [[852, 892], [878, 898], [864, 908]],
    [[412, 954], [442, 950], [428, 964]]
  ];
  brush.noStroke();
  for (let chip of plasterChips) {
    brush.wash("#f5f2ea", 230);
    drawPolyShape(chip, 0.05);
  }
  brush.noWash();
  for (let chip of plasterChips) {
    brush.set("finePen", "#2a2520", 0.35);
    brush.line(chip[0][0], chip[0][1], chip[1][0], chip[1][1]);
    brush.line(chip[1][0], chip[1][1], chip[2][0], chip[2][1]);
  }

  // Expose a tiny patch of plaster-soaked burlap weave at the bottom right corner of the diorama base
  brush.set("finePen", "#4a4339", 0.32);
  for (let bx = 980; bx < 1120; bx += 5.5) {
    brush.line(bx, 1085 + random(-3, 3), bx - 4, 1145 + random(-3, 3));
  }
  for (let by = 1088; by < 1145; by += 5.5) {
    brush.line(976 + random(-3, 3), by, 1122 + random(-3, 3), by + 3);
  }

  // 5. Granular Flocked Fake Moss Detail (Stippled spray + hundreds of tiny crisp moss tufts)
  for (let m of mossPatches) {
    brush.set("flockSpray", "#3a4c26", 0.85);
    brush.line(m.x - m.rx * 0.7, m.y, m.x + m.rx * 0.7, m.y + 3);
    brush.set("flockSpray", "#7b8f54", 0.65);
    brush.line(m.x - m.rx * 0.5, m.y - 4, m.x + m.rx * 0.5, m.y - 2);

    // Individual glue-clumped fake moss fibers in fine pen and colored pencil
    let tuftCount = floor(m.rx * 0.95);
    for (let i = 0; i < tuftCount; i++) {
      let tx = m.x + random(-m.rx * 0.88, m.rx * 0.88);
      let ty = m.y + random(-m.ry * 0.75, m.ry * 0.75);
      let col = random() < 0.35 ? "#2b381b" : (random() < 0.6 ? "#556b36" : "#8a9c62");
      brush.set("finePen", col, random(0.32, 0.55));
      let len = random(5, 13);
      let ang = random(-115, -65);
      brush.line(tx, ty, tx + cos(ang) * len, ty + sin(ang) * len);
      if (random() < 0.45) {
        brush.line(tx, ty, tx + cos(ang + 22) * (len * 0.8), ty + sin(ang + 22) * (len * 0.8));
      }
    }
  }

  // Scattered loose flock crumbs & dust granules across the plaster rock ledges
  for (let i = 0; i < 260; i++) {
    let gx = random(65, 1135);
    let gy = random(735, 1140);
    let col = random() < 0.4 ? "#3e4f28" : "#2b2620";
    brush.set("finePen", col, random(0.28, 0.5));
    brush.line(gx, gy, gx + random(-2.5, 2.5), gy + random(-2, 2));
  }
}

