  // -------------------------------------------------------------------------
  // B. TORSO, RUMP, TAIL & HEAD BASE WASHES (Opaque Underfur Layer)
  // -------------------------------------------------------------------------
  // Bushy Blunt Tail (x: 172..255, y: 505..635)
