  const bodyPts = [
    [232, 515], [278, 448], [358, 412], [462, 416], [588, 422],
    [682, 452], [758, 470], [838, 514], [914, 564], [918, 588],
    [894, 608], [862, 618], [765, 628], [692, 642], [648, 688],
    [555, 712], [422, 716], [335, 688], [248, 615]
  ];
  brush.wash("#3b3733", 245);
  drawPolyShape(bodyPts, 0.18);

