  // 1) Dorsal forehead-to-snout white blaze
  const upperBlazePts = [
    [665, 452], [755, 470], [838, 514], [902, 556],
    [886, 566], [808, 518], [722, 482], [652, 468]
  ];
  brush.wash("#efeae0", 245);
  drawPolyShape(upperBlazePts, 0.15);

  // 2) Lower cheek/jaw white band (below the black eye stripe)
