    [648, 548], [728, 558], [805, 572], [885, 588],
    [892, 606], [852, 618], [755, 624], [658, 602]
  ];
  brush.wash("#ede8dc", 242);
  drawPolyShape(cheekWhitePts, 0.18);

  // 3) Jet-Black Badger Mask Stripe (sweeping from snout through eye and over ear)
  const blackMaskPts = [
    [655, 468], [725, 482], [812, 518], [888, 565],
    [878, 586], [798, 570], [718, 554], [635, 535]
  ];
  brush.wash("#141312", 248);
  drawPolyShape(blackMaskPts, 0.15);

  // 4) Black throat/chin under-patch
  const throatBlackPts = [
    [655, 602], [758, 622], [848, 616], [768, 632], [685, 648], [635, 635]
  ];
  brush.wash("#161514", 242);
  drawPolyShape(throatBlackPts, 0.15);

  // Near-Side Left Hind Leg & Left Foreleg (Dark Black-Brown Pelage)
  const leftHindPts = [
    [268, 565], [348, 575], [362, 675], [335, 755],
    [362, 795], [348, 812], [278, 804], [275, 715], [252, 635]
  ];
  brush.wash("#181615", 245);
  drawPolyShape(leftHindPts, 0.15);

  const leftForePts = [
    [568, 545], [658, 565], [662, 695], [658, 792],
    [698, 832], [682, 850], [612, 842], [602, 775], [575, 668]
  ];
  brush.wash("#151413", 248);
  drawPolyShape(leftForePts, 0.15);
  brush.noWash();

  // -------------------------------------------------------------------------
  // C. GRAPHITE TONAL SCULPTING OF MUSCULATURE (2B / HB Cross-Contour Hatching)
  // -------------------------------------------------------------------------
  // Deep belly & flank curvature hatching
  let bellyHatchPoly = new brush.Polygon([
    [265, 585], [410, 605], [565, 600], [665, 635],
    [565, 710], [415, 714], [325, 682]
  ]);
  brush.hatchStyle("2B", "#1c1a18", 0.5);
  bellyHatchPoly.hatch(3.6, -12, { rand: 0.06, gradient: 0.35 });

  // Shoulder & ribcage depression behind foreleg
  let ribShadePoly = new brush.Polygon([
    [455, 450], [565, 455], [575, 610], [445, 605]
  ]);
  brush.hatchStyle("HB", "#4a453f", 0.42);
  ribShadePoly.hatch(4.5, -55, { rand: 0.05, gradient: 0.4 });
  brush.noHatch();

  // -------------------------------------------------------------------------
  // D. THOUSANDS OF INDIVIDUAL GUARD HAIRS (Anatomical Flow & Agouti Banding)
  // -------------------------------------------------------------------------
  // 1. Bushy Tail Guard Hairs (coarse buff, grey & dark-tipped bristles)
  for (let i = 0; i < 240; i++) {
    let t = random();
    let tx = lerp(242, 184, t) + random(-16, 16);
    let ty = lerp(522, 615, t) + random(-18, 18);
    let ang = lerp(142, 112, t) + random(-14, 14);
    let len = random(24, 46);
    let col = random() < 0.35 ? "#2e2b27" : (random() < 0.7 ? "#ded8ca" : "#8c8478");
    drawCurvedGuardHair(tx, ty, ang, len, col, random(0.32, 0.58));
  }

  // 2. Main Dorsal Saddle, Rump, Flanks & Shoulder Coat (Grizzled Silver-Grey Agouti Hairs)
  // Badger guard hairs are ~35-55px long here, sweeping from spine down and back in shingle layers
  for (let pass = 0; pass < 3; pass++) {
    let count = pass === 0 ? 750 : (pass === 1 ? 850 : 650);
    for (let i = 0; i < count; i++) {
      // Sample along body length u (0 = rump, 1 = neck/shoulder) and vertical v (0 = spine, 1 = lower flank)
      let u = random();
      let v = pow(random(), 0.85);

      // Spine curve from rump (245, 505) through high arch (390, 412) to shoulder (655, 448)
      let spineX = lerp(245, 665, u);
      let spineY = 414 + 85 * pow(u - 0.38, 2) + (u > 0.5 ? (u - 0.5) * 35 : 0);

      // Lower belly/flank boundary
      let bellyY = 665 + 45 * sin(u * 150) - (u < 0.25 ? (0.25 - u) * 140 : 0);

      let hx = spineX + random(-14, 14);
      let hy = lerp(spineY, bellyY, v) + random(-8, 8);

      // Compute anatomical hair flow angle (in degrees: 180 = left/rear, 90 = straight down)
      // At spine (v ~ 0): hairs point rear-and-slightly-down (165..178 deg)
      // Mid-flank (v ~ 0.5): hairs sweep backward and downward (135..158 deg)
      // Lower flank/belly (v ~ 0.85): hairs droop more downward and rear (115..142 deg)
      // Shoulder whorl (u > 0.72): hairs fan out from shoulder blade down toward foreleg
      let baseAng = lerp(172, 128, v);
      if (u > 0.72) {
        baseAng = lerp(168, 108, v);
      } else if (u < 0.22) {
        baseAng = lerp(165, 118, v);
      }
      let ang = baseAng + random(-9, 9);
      let len = lerp(34, 54, sin(v * 140)) * random(0.8, 1.2);

      // Agouti color logic:
      // Pass 0: Dark charcoal/black underfur & dark hair bases
      // Pass 1: Mid slate-umber & warm grizzled grey shafts
      // Pass 2: Crisp silver-ivory guard hairs with dark tips catching the light
      let col;
      let w;
      if (pass === 0) {
        col = v > 0.68 ? "#141312" : (random() < 0.5 ? "#24211e" : "#3d3833");
        w = random(0.38, 0.62);
      } else if (pass === 1) {
        if (v > 0.75) {
          col = random() < 0.7 ? "#1b1917" : "#4a453f";
        } else {
          col = random() < 0.45 ? "#7a7369" : (random() < 0.75 ? "#a8a094" : "#2b2824");
        }
        w = random(0.3, 0.5);
      } else {
        // Silver-white highlight guard hairs concentrated on upper back, rump & mid-flank
        if (v > 0.78 && random() < 0.75) {
          col = "#2e2b27";
        } else {
          col = random() < 0.55 ? "#f0ece1" : (random() < 0.82 ? "#d4cec0" : "#161513");
        }
        w = random(0.24, 0.42);
      }

      drawCurvedGuardHair(hx, hy, ang, len, col, w);
    }
  }

  // Dorsal spine bristling fringe (individual guard hairs breaking the top contour against the watercolor backdrop!)
  for (let i = 0; i < 190; i++) {
    let u = random(0.02, 0.96);
    let sx = lerp(248, 695, u);
    let sy = 414 + 85 * pow(u - 0.38, 2) + (u > 0.5 ? (u - 0.5) * 35 : 0);
    let ang = lerp(195, 168, u) + random(-10, 10);
    let len = random(18, 34);
    let col = random() < 0.65 ? "#f2eee4" : (random() < 0.85 ? "#9c9488" : "#1f1d1a");
    drawCurvedGuardHair(sx, sy + 4, ang, len, col, random(0.24, 0.4));
  }

  // 3. Near-Side Left Hind Leg & Left Foreleg Fur (Jet-black & deep espresso coarse hairs)
  drawLimbFurRegion(275, 575, 345, 795, 380, 96, ["#0d0c0b", "#1c1a18", "#332f2b", "#6e685f"]);
  drawLimbFurRegion(575, 555, 668, 825, 460, 86, ["#0c0b0a", "#1a1816", "#2e2a26", "#666057"]);

  // 4. Planted Left Hind Paw & Five Claws (gripping the left plaster stone at x: 325..392, y: 790..816)
  drawBadgerClaw(352, 792, 386, 804, 5.0);
  drawBadgerClaw(344, 796, 380, 810, 5.5);
  drawBadgerClaw(334, 800, 370, 814, 5.5);
  drawBadgerClaw(322, 803, 356, 816, 5.0);
  drawBadgerClaw(310, 805, 340, 816, 4.5);

  // 5. Planted Left Forepaw & Five Long Curved Digging Claws (at x: 645..740, y: 825..862)
  // Plus a tiny glimpse of the steel taxidermy mounting pin beneath the arch of the paw!
  brush.set("rotring", "#1a1816", 0.55);
  brush.line(648, 842, 648, 856);
  brush.set("finePen", "#d8d4ca", 0.35);
  brush.line(649.5, 842, 649.5, 855);

  drawBadgerClaw(692, 828, 738, 846, 6.2);
  drawBadgerClaw(684, 834, 732, 854, 7.0);
  drawBadgerClaw(674, 838, 722, 860, 7.2);
  drawBadgerClaw(662, 842, 706, 862, 6.6);
  drawBadgerClaw(648, 844, 686, 862, 5.5);

  // Dark knuckle hairs overlapping the bases of the left forepaw claws
  for (let i = 0; i < 45; i++) {
    let kx = random(635, 695);
    let ky = random(822, 844);
    drawCurvedGuardHair(kx, ky, random(15, 42), random(12, 22), "#141210", 0.35);
  }

  // -------------------------------------------------------------------------
  // E. HEAD, FACIAL STRIPES, EARS, RHINARIUM & GLASS EYE (Hyperreal Focal Point)
  // -------------------------------------------------------------------------
  // 1. Far-side Right Ear tip peeking at (782, 464)
  brush.noStroke();
  brush.wash("#1c1a18", 240);
  drawPolyShape([[762, 474], [776, 454], [796, 458], [798, 478]], 0.3);
  brush.noWash();
  for (let i = 0; i < 38; i++) {
    let a = lerp(-155, -25, i / 38);
    let ex = 780 + cos(a) * 14;
    let ey = 468 + sin(a) * 11;
    drawCurvedGuardHair(ex, ey, a + random(-15, 15), random(8, 15), "#f5f2e8", 0.32);
  }

  // 2. Fine Directional Hair Flow on the Head Stripes
  // Upper white forehead/snout blaze hairs (short, dense, sleek ivory hairs sweeping back-and-up)
  for (let i = 0; i < 340; i++) {
    let t = random();
    let bx = lerp(665, 898, t) + random(-8, 8);
    let by = lerp(458, 558, t) + random(-9 * (1 - t * 0.5), 6 * (1 - t * 0.5));
    let ang = lerp(198, 208, t) + random(-8, 8);
    let len = lerp(24, 11, t) * random(0.8, 1.15);
    let col = random() < 0.72 ? "#fbf8f0" : (random() < 0.9 ? "#ded8ca" : "#9e9689");
    drawCurvedGuardHair(bx, by, ang, len, col, random(0.24, 0.38));
  }

  // Lower white cheek & jaw band hairs (sweeping backward and slightly downward into the neck ruff)
  for (let i = 0; i < 360; i++) {
    let t = random();
    let cx = lerp(648, 886, t) + random(-10, 10);
    let cy = lerp(572, 598, t) + random(-14 * (1 - t * 0.4), 14 * (1 - t * 0.4));
    let ang = lerp(162, 188, t) + random(-10, 10);
    let len = lerp(32, 12, t) * random(0.8, 1.2);
    let col = random() < 0.68 ? "#f7f4eb" : (random() < 0.88 ? "#d6d0c2" : "#7d766b");
    drawCurvedGuardHair(cx, cy, ang, len, col, random(0.25, 0.4));
  }

  // Bold Jet-Black Eye Mask Stripe Hairs (sweeping from snout through eye and over ear)
  for (let i = 0; i < 480; i++) {
    let t = random();
    let mx = lerp(642, 885, t) + random(-10, 10);
    let my = lerp(505, 574, t) + random(-18 * (1 - t * 0.5), 16 * (1 - t * 0.5));
    let ang = lerp(175, 196, t) + random(-9, 9);
    let len = lerp(28, 11, t) * random(0.8, 1.15);
    let col = random() < 0.65 ? "#0d0c0b" : (random() < 0.88 ? "#211f1d" : "#45413c");
    drawCurvedGuardHair(mx, my, ang, len, col, random(0.26, 0.44));
  }

  // Dark throat & chin hairs
  for (let i = 0; i < 180; i++) {
    let t = random();
    let tx = lerp(645, 855, t) + random(-8, 8);
    let ty = lerp(622, 618, t) + random(-8, 10);
    drawCurvedGuardHair(tx, ty, random(155, 182), random(12, 24), random() < 0.7 ? "#121110" : "#2e2b27", 0.34);
  }

  // 3. Near-Side Left Ear at (710, 488) with Iconic Crisp White Tufted Rim
  // Deep dark ear cavity
  brush.noStroke();
  brush.wash("#12100f", 248);
  drawPolyShape([[688, 495], [696, 470], [724, 468], [732, 492], [712, 506]], 0.3);
  brush.noWash();

  // Inner ear warm leather/putty tone & fine shading
  brush.set("rotring", "#2b2520", 0.35);
  for (let i = 0; i < 24; i++) {
    let a = random(-150, 30);
    brush.line(708, 488, 708 + cos(a) * 12, 488 + sin(a) * 10);
  }

  // Dense pure-white ear rim fringe
  for (let i = 0; i < 85; i++) {
    let u = i / 85;
    let a = lerp(215, -35, u);
    let ex = 710 + cos(a) * 19 + random(-2, 2);
    let ey = 486 + sin(a) * 16 + random(-2, 2);
    let col = random() < 0.8 ? "#fcfaf2" : "#d8d2c5";
    drawCurvedGuardHair(ex, ey, a + random(-18, 18), random(11, 20), col, random(0.28, 0.42));
  }

  // 4. THE GLASS EYE at (802, 534) — Wet-varnished eyelid rim & pinprick gallery highlight
  const eyeX = 802;
  const eyeY = 534;

  // Dark taxidermy putty / leather eyelid rim
  brush.noStroke();
  brush.wash("#0a0909", 252);
  drawPolyShape([
    [eyeX - 15, eyeY - 2], [eyeX - 6, eyeY - 11], [eyeX + 8, eyeY - 10],
    [eyeX + 15, eyeY + 1], [eyeX + 7, eyeY + 10], [eyeX - 7, eyeY + 9]
  ], 0.35);

  // Deep brown-black glass iris & pupil dome
  brush.wash("#1c1510", 250);
  brush.circle(eyeX, eyeY, 9.5, 0.08);
  brush.wash("#070606", 252);
  brush.circle(eyeX + 1, eyeY, 6.2, 0.05);

  // Secondary soft corneal glow along lower-right glass curve
  brush.wash("#7d786c", 145);
  drawPolyShape([
    [eyeX - 4, eyeY + 5], [eyeX + 4, eyeY + 6], [eyeX + 7, eyeY + 2], [eyeX + 2, eyeY + 4]
  ], 0.2);

  // THE PINPRICK GALLERY HIGHLIGHT (Razor-sharp white square-oval window reflection + secondary speck)
  brush.wash("#ffffff", 255);
  drawPolyShape([
    [eyeX - 4.5, eyeY - 5.5], [eyeX + 0.5, eyeY - 6.0],
    [eyeX + 1.0, eyeY - 2.0], [eyeX - 4.0, eyeY - 1.5]
  ], 0.05);
  brush.circle(eyeX + 3.8, eyeY - 3.2, 1.4, 0.02);
  brush.noWash();

  // Crisp pen detailing around the eyelid crease and tear duct
  brush.set("finePen", "#050505", 0.45);
  brush.arc(eyeX, eyeY, 10.5, -165, 15);
  brush.arc(eyeX, eyeY, 10.2, 15, 195);
  // Tiny glossy specular dash on the lower black wax eyelid rim
  brush.set("finePen", "#dcd8ce", 0.32);
  brush.line(eyeX - 5, eyeY + 9.2, eyeX + 2, eyeY + 9.6);

  // 5. SCULPTED RHINARIUM (Wet-Varnished Black Leather Nose Pad at x: 892..922, y: 558..596)
  brush.noStroke();
  brush.wash("#141312", 250);
  drawPolyShape([
    [894, 558], [916, 562], [922, 576], [916, 594], [896, 596], [888, 578]
  ], 0.25);

  // Deep nostril comma cavity
  brush.wash("#050505", 255);
  drawPolyShape([
    [902, 572], [914, 570], [916, 580], [908, 586], [900, 580]
  ], 0.25);

  // Varnished specular highlight on top of the nose pad
  brush.wash("#e6e2d8", 190);
  drawPolyShape([
    [898, 562], [914, 565], [915, 569], [899, 566]
  ], 0.15);
  brush.noWash();

  // Pebbled skin texture & taxidermy lip seam in fine rotring pen
  brush.set("finePen", "#080707", 0.42);
  for (let i = 0; i < 42; i++) {
    let nx = random(892, 918);
    let ny = random(562, 592);
    brush.line(nx, ny, nx + 1.2, ny + 1.2);
  }
  // Slightly stiff wired mouth line
  brush.set("rotring", "#0b0a09", 0.48);
  brush.spline([
    [914, 593, 0.4],
    [888, 602, 0.7],
    [856, 600, 0.5],
    [832, 594, 0.2]
  ], 0.35);

  // 6. Stiff Translucent-Ivory Vibrissae (Whiskers)
  const whiskers = [
    [[886, 582], [862, 598], [828, 622]],
    [[892, 586], [875, 608], [848, 636]],
    [[898, 584], [895, 610], [882, 642]],
    [[882, 576], [852, 584], [812, 596]],
    [[896, 575], [918, 592], [938, 616]],
    [[890, 590], [912, 608], [928, 632]],
    // Supraorbital sensory bristles above the eye
    [[808, 518], [795, 496], [776, 482]],
    [[814, 520], [806, 498], [792, 484]]
  ];
  for (let w of whiskers) {
    brush.set("finePen", "#1a1816", 0.36);
    brush.spline([
      [w[0][0], w[0][1] + 1, 0.6],
      [w[1][0], w[1][1] + 1, 0.4],
      [w[2][0], w[2][1] + 1, 0.1]
    ], 0.45);
    brush.set("finePen", "#f7f4ec", 0.32);
    brush.spline([
      [w[0][0], w[0][1], 0.7],
      [w[1][0], w[1][1], 0.45],
      [w[2][0], w[2][1], 0.1]
    ], 0.45);
  }
}

// ===========================================================================
// LAYER 4: FOREGROUND MUSEUM SPECIMEN PLAQUE & WIRED DRY BRACKEN
// ===========================================================================
function drawForegroundProps() {
  brush.noField();

  // 1. Small ivory-and-brass museum specimen number plaque pinned to the lower-left plaster rock
  const tagX = 118;
  const tagY = 875;
  const tagW = 86;
  const tagH = 34;

  // Plaque drop shadow
  brush.noStroke();
  brush.wash("#211d18", 160);
  drawPolyShape([
    [tagX + 3, tagY + 4], [tagX + tagW + 3, tagY + 2],
    [tagX + tagW + 1, tagY + tagH + 4], [tagX + 1, tagY + tagH + 6]
  ], 0.05);

  // Aged card stock fill
  brush.wash("#efe9d8", 242);
  drawPolyShape([
    [tagX, tagY], [tagX + tagW, tagY - 2],
    [tagX + tagW - 2, tagY + tagH], [tagX - 2, tagY + tagH + 2]
  ], 0.05);
  brush.noWash();

  // Crisp double border & corner mounting pins in rotring pen
  brush.set("rotring", "#2b251f", 0.35);
  brush.line(tagX, tagY, tagX + tagW, tagY - 2);
  brush.line(tagX + tagW, tagY - 2, tagX + tagW - 2, tagY + tagH);
  brush.line(tagX + tagW - 2, tagY + tagH, tagX - 2, tagY + tagH + 2);
  brush.line(tagX - 2, tagY + tagH + 2, tagX, tagY);

  // Corner pin heads
  brush.circle(tagX + 5, tagY + 5, 1.5, 0.05);
  brush.circle(tagX + tagW - 7, tagY + 3, 1.5, 0.05);

  // Miniature calligraphic ink inscription ("No. 402 — Meles meles") simulated in finePen
  brush.set("finePen", "#1f1a16", 0.32);
  // "402."
  brush.line(tagX + 12, tagY + 11, tagX + 26, tagY + 11);
  // Italicized binomial line
  for (let lx = tagX + 12; lx < tagX + tagW - 12; lx += 4.5) {
    let dy = sin(lx * 35) * 1.6;
    brush.line(lx, tagY + 21 + dy, lx + 2.8, tagY + 19 - dy);
  }
  brush.line(tagX + 12, tagY + 27, tagX + 54, tagY + 26);

  // 2. Artificial Wired Dry Beech Leaves & Bracken Stalk near right rock crevice (x: 945, y: 845)
  brush.set("rotring", "#332c24", 0.42);
  brush.spline([
    [955, 862, 0.7],
    [978, 812, 0.5],
    [1012, 772, 0.3]
  ], 0.35);

  // Curled dry beech leaves wired to the stem
  const leaves = [
    { x: 974, y: 818, ang: -35, col: "#7a5c3c" },
    { x: 992, y: 794, ang: 18, col: "#8a6b47" },
    { x: 1010, y: 774, ang: -22, col: "#6e5235" },
    // Fallen dry leaf near badger's hind foot
    { x: 405, y: 822, ang: 12, col: "#7d6040" }
  ];
  for (let lf of leaves) {
    let c = cos(lf.ang);
    let s = sin(lf.ang);
    let pts = [
      [lf.x, lf.y],
      [lf.x + c * 14 - s * 7, lf.y + s * 14 + c * 7],
      [lf.x + c * 28, lf.y + s * 28],
      [lf.x + c * 14 + s * 7, lf.y + s * 14 - c * 7]
    ];
    brush.noStroke();
    brush.wash(lf.col, 210);
    drawPolyShape(pts, 0.25);
    brush.noWash();
    brush.set("finePen", "#2b231b", 0.32);
    brush.line(pts[0][0], pts[0][1], pts[2][0], pts[2][1]);
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
    brush.line(pts[0][0], pts[0][1], pts[3][0], pts[3][1]);
  }
}

// ===========================================================================
// LAYER 5: VITRINE GLASS OVERLAY (Diagonal Glare, Fingerprint Smear & Frame)
// ===========================================================================
function drawVitrineGlassOverlay() {
  brush.noField();

  // -------------------------------------------------------------------------
  // 1. DIAGONAL STREAK OF REFLECTED GALLERY LIGHT ACROSS THE VITRINE PANE
  // -------------------------------------------------------------------------
  // Main diagonal glare band from top-left (145, 0) to bottom-right (1200, 995)
  // Plus a parallel secondary thin reflection (from the rear surface of the thick plate glass!)
  brush.noStroke();

  // Soft outer glow of the reflection band
  brush.wash("#f4f6f8", 16);
  drawPolyShape([
    [95, 0], [325, 0], [1200, 825], [1200, 1045]
  ], 0.02);

  // Core crisp gallery light streak
  brush.wash("#ffffff", 26);
  drawPolyShape([
    [155, 0], [265, 0], [1200, 882], [1200, 988]
  ], 0.02);

  // Brightest specular ribbon along the leading edge of the glass reflection
  brush.wash("#ffffff", 34);
  drawPolyShape([
    [175, 0], [212, 0], [1200, 932], [1200, 968]
  ], 0.02);

  // Secondary parallel double-reflection (plate glass thickness offset ~38px)
  brush.wash("#eef2f5", 20);
  drawPolyShape([
    [355, 0], [382, 0], [1200, 772], [1200, 798]
  ], 0.02);

  // Faint interruption in the glare: reflection of an opposing museum gallery doorway lintel
  brush.wash("#d6dce0", 18);
  drawPolyShape([
    [515, 240], [595, 240], [745, 382], [665, 382]
  ], 0.02);
  brush.noWash();

  // Ultra-fine diagonal glass-sheen lines in 2H & glassGlaze along the reflection path
  for (let i = 0; i < 68; i++) {
    let offset = random(-65, 85);
    let x1 = 205 + offset + random(-20, 120);
    let y1 = (x1 - (205 + offset)) * 0.94 + random(0, 260);
    let len = random(95, 280);
    let x2 = x1 + len;
    let y2 = y1 + len * 0.94;
    if (x2 < 1195 && y2 < 1185 && y1 > 5) {
      brush.set(i % 3 === 0 ? "glassGlaze" : "2H", "#ffffff", i % 3 === 0 ? 0.8 : 0.25);
      brush.line(x1, y1, x2, y2);
    }
  }

  // -------------------------------------------------------------------------
  // 2. FAINT FINGERPRINT SMEAR ON THE VITRINE GLASS
  // -------------------------------------------------------------------------
  // Positioned at (865, 428) — right along the diagonal glare above the badger's snout,
  // where a visitor leaned in and touched the glass!
  const fpX = 865;
  const fpY = 428;

  // Greasy skin-oil smudge halo & downward drag smear
  brush.noStroke();
  brush.wash("#eff1ea", 22);
  drawSoftBlob(fpX, fpY, 26, 34, 14);
  brush.wash("#e8ebe2", 16);
  drawPolyShape([
    [fpX - 18, fpY + 8], [fpX + 16, fpY + 12],
    [fpX - 8, fpY + 68], [fpX - 34, fpY + 58]
  ], 0.35);
  brush.noWash();

  // Concentric dermatoglyphic fingerprint whorl ridges (tilted oval loops)
  push();
  translate(fpX, fpY);
  rotate(-18);
  for (let r = 3; r <= 26; r += 2.3) {
    brush.set("finePen", "#f7f9f4", 0.22);
    // Upper whorl arch
    let aStart = -165 + random(-12, 12);
    let aEnd = -15 + random(-12, 12);
    drawEllipticalRidgeArc(0, 0, r * 0.78, r * 1.08, aStart, aEnd);

    // Broken side/lower loop ridges
    if (random() < 0.85) {
      drawEllipticalRidgeArc(0, 2, r * 0.76, r * 1.05, 10 + random(-8, 8), 155 + random(-10, 10));
    }
  }
  // Central whorl core loop
  brush.set("finePen", "#ffffff", 0.24);
  brush.line(-1.5, -4, 1.5, 5);
  pop();

  // Faint dragging smudge streaks from the fingertip
  for (let i = 0; i < 18; i++) {
    let sx = fpX + random(-15, 12);
    let sy = fpY + random(5, 22);
    brush.set("2H", "#f0f2eb", 0.22);
    brush.line(sx, sy, sx - random(12, 26), sy + random(28, 54));
  }

  // Secondary fainter index-finger smudge nearby at (918, 456)
  brush.noStroke();
  brush.wash("#eff1ea", 15);
  drawSoftBlob(918, 456, 16, 22, 10);
  brush.noWash();
  push();
  translate(918, 456);
  rotate(-8);
  for (let r = 4; r <= 15; r += 2.6) {
    brush.set("finePen", "#f4f6f0", 0.19);
    drawEllipticalRidgeArc(0, 0, r * 0.75, r * 1.05, -150, 25);
  }
  pop();

  //Tiny dust motes & micro-scratches on the outer glass surface catching gallery light
  for (let i = 0; i < 95; i++) {
    let dx = random(60, 1170);
    let dy = random(30, 1160);
    brush.set("finePen", "#fbfcfa", random(0.18, 0.3));
    if (random() < 0.25) {
      let ang = random(360);
      brush.line(dx, dy, dx + cos(ang) * random(6, 18), dy + sin(ang) * random(6, 18));
    } else {
      brush.line(dx, dy, dx + 1.2, dy + 0.8);
    }
  }

  // -------------------------------------------------------------------------
  // 3. DARK BRONZE VITRINE CASE MULLION & GLASS EDGE BEVEL (Framing the Scene)
  // -------------------------------------------------------------------------
  brush.noStroke();
  // Left dark bronze/ebonized wood vitrine frame strip
  brush.wash("#181614", 252);
  brush.rect(0, 0, 38, 1200, "corner");

  // Top dark vitrine header strip
  brush.rect(0, 0, 1200, 24, "corner");

  // Bottom dark vitrine sill strip
  brush.rect(0, 1176, 1200, 24, "corner");

  // Right thin vitrine edge
  brush.rect(1182, 0, 18, 1200, "corner");

  // Inner brass/glass putty rabbet bevel along the left mullion
  brush.wash("#4a4236", 210);
  brush.rect(38, 24, 5, 1152, "corner");
  brush.noWash();

  // Specular vertical highlight on the bevel of the vitrine glass edge
  brush.set("finePen", "#e8ecee", 0.42);
  brush.line(44, 24, 44, 1176);
  brush.set("finePen", "#6e6556", 0.35);
  brush.line(38, 24, 38, 1176);

  // Brass slotted screw heads along the left vitrine mullion
  const screwYs = [140, 580, 1020];
  for (let sy of screwYs) {
    brush.noStroke();
    brush.wash("#7a6b4f", 220);
    brush.circle(20, sy, 5.5, 0.05);
    brush.noWash();
    brush.set("rotring", "#0c0b0a", 0.4);
    brush.circle(20, sy, 5.5, 0.05);
    brush.line(16, sy - 2, 24, sy + 2);
    brush.set("finePen", "#dfd6c3", 0.28);
    brush.arc(20, sy, 4.5, -140, -30);
  }
}

// ===========================================================================
// GEOMETRY & HYPERREAL BRUSHWORK HELPERS
// ===========================================================================

function drawSoftBand(x1, y1, x2, y2, steps) {
  brush.beginShape(0.35);
  for (let i = 0; i <= steps; i++) {
    let x = lerp(x1, x2, i / steps);
    let y = y1 + sin(i * 38) * 18 + random(-10, 10);
    brush.vertex(x, y);
  }
  for (let i = steps; i >= 0; i--) {
    let x = lerp(x1, x2, i / steps);
    let y = y2 + cos(i * 42) * 22 + random(-12, 12);
    brush.vertex(x, y);
  }
  brush.endShape(true);
}

function drawSoftBlob(cx, cy, rx, ry, verts) {
  brush.beginShape(0.45);
  for (let i = 0; i < verts; i++) {
    let a = (i / verts) * 360;
    let rMod = 0.85 + 0.28 * noise(cx * 0.02 + cos(a), cy * 0.02 + sin(a));
    brush.vertex(cx + cos(a) * rx * rMod, cy + sin(a) * ry * rMod);
  }
  brush.endShape(true);
}

function drawPaintedTreeTrunk(cx, topY, botY, w) {
  brush.beginShape(0.25);
  let steps = 7;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let y = lerp(topY, botY, t);
    let flare = t > 0.85 ? (t - 0.85) * w * 0.9 : 0;
    let sway = sin(t * 180 + cx) * (w * 0.14);
    brush.vertex(cx - w * 0.5 - flare + sway, y);
  }
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let y = lerp(topY, botY, t);
    let flare = t > 0.85 ? (t - 0.85) * w * 1.1 : 0;
    let sway = sin(t * 180 + cx) * (w * 0.14);
    brush.vertex(cx + w * 0.5 + flare + sway, y);
  }
  brush.endShape(true);
}

function drawPolyShape(pts, curv) {
  brush.beginShape(curv);
  for (let p of pts) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
}

function drawCurvedGuardHair(x, y, angDeg, len, col, weight) {
  brush.set("guardHair", col, weight);
  let midAng = angDeg + random(-8, 8);
  let endAng = midAng + random(-10, 12);
  let x1 = x + cos(midAng) * (len * 0.52);
  let y1 = y + sin(midAng) * (len * 0.52);
  let x2 = x1 + cos(endAng) * (len * 0.48);
  let y2 = y1 + sin(endAng) * (len * 0.48);
  brush.spline([
    [x, y, 0.35],
    [x1, y1, 0.95],
    [x2, y2, 0.08]
  ], 0.35);
}

function drawLimbFurRegion(x1, y1, x2, y2, count, baseAng, palette) {
  for (let i = 0; i < count; i++) {
    let u = random();
    let v = random();
    let hx = lerp(x1, x2, u) + random(-22, 22) * (1 - v * 0.35);
    let hy = lerp(y1, y2, v) + random(-10, 10);
    let ang = baseAng + random(-14, 14);
    let len = random(18, 34);
    let col = palette[floor(pow(random(), 1.5) * palette.length)];
    drawCurvedGuardHair(hx, hy, ang, len, col, random(0.28, 0.48));
  }
}

function drawBadgerClaw(bx, by, tx, ty, thickness) {
  let mx = (bx + tx) * 0.5 + (ty - by) * 0.18;
  let my = (by + ty) * 0.5 - (tx - bx) * 0.16;
  let nx = -(ty - by);
  let ny = tx - bx;
  let nLen = sqrt(nx * nx + ny * ny) || 1;
  nx = (nx / nLen) * thickness;
  ny = (ny / nLen) * thickness;

  // Keratin horn base wash
  brush.noStroke();
  brush.wash("#cfc6b2", 240);
  drawPolyShape([
    [bx, by],
    [mx + nx * 0.55, my + ny * 0.55],
    [tx, ty],
    [mx - nx * 0.25, my - ny * 0.25],
    [bx - nx * 0.35, by - ny * 0.35]
  ], 0.25);
  brush.noWash();

  // Dark underside & keratin ridge lines in fine rotring pen
  brush.set("rotring", "#1d1a16", 0.38);
  brush.spline([
    [bx - nx * 0.35, by - ny * 0.35, 0.7],
    [mx - nx * 0.25, my - ny * 0.25, 0.6],
    [tx, ty, 0.3]
  ], 0.35);
  brush.set("finePen", "#4f473c", 0.32);
  brush.spline([
    [bx, by, 0.6],
    [mx + nx * 0.55, my + ny * 0.55, 0.5],
    [tx, ty, 0.2]
  ], 0.35);

  // Dorsal ivory highlight along the top curve of the claw
  brush.set("finePen", "#f7f4ea", 0.32);
  brush.spline([
    [bx, by + 0.5, 0.5],
    [mx + nx * 0.35, my + ny * 0.35, 0.7],
    [tx - 1, ty, 0.1]
  ], 0.35);
}

function drawEllipticalRidgeArc(cx, cy, rx, ry, aStart, aEnd) {
  let pts = [];
  let steps = 8;
  for (let i = 0; i <= steps; i++) {
    let a = lerp(aStart, aEnd, i / steps);
    pts.push([cx + cos(a) * rx, cy + sin(a) * ry, 0.45]);
  }
  brush.spline(pts, 0.4);
}
